// This is explicit native configuration, not a captured PHP request preference.
pub const NormalTitleOptions = struct {
    namespace_id: i32,
    requested_variant: ?[]const u8,
    configured_default_variant: ?[]const u8,
    disable_title_conversion: bool,
};
pub const NormalTitleDefaults = struct {
    title: []const u8,
    namespace_catalog: *const @import("namespace_registry").Registry,
    namespace_sha256: [32]u8,
    profile: @import("namespace_registry").ManualConversionContext,
    profile_sha256: [32]u8,
    options: NormalTitleOptions,
    config_sha256: []const u8,

    fn sameSource(left: []const u8, right: []const u8) bool {
        return left.ptr == right.ptr and left.len == right.len;
    }
    fn digest(profile: @import("namespace_registry").ManualConversionContext, variants: []const []const u8) [32]u8 {
        var hash = std.crypto.hash.sha2.Sha256.init(.{});
        for ([_][]const u8{ profile.policy, profile.base, profile.source_core,
            profile.source_converter_sha256, profile.siteinfo_sha256, profile.static_default_variant orelse "" }) |value| {
            hash.update(value); hash.update("\x00");
        }
        for (variants) |value| { hash.update(value); hash.update("\x00"); }
        hash.update("\x01");
        for (profile.fallbacks) |value| { hash.update(value); hash.update("\x00"); }
        hash.update("\x01");
        for (profile.separator_variants) |value| { hash.update(value); hash.update("\x00"); }
        hash.update(if (profile.automatic_identity) "\x01" else "\x00");
        if (profile.effective_override) |effective| {
            hash.update("\x01");
            for ([_][]const u8{ effective.namespace_title, effective.message_key,
                effective.interface_messages_sha256, effective.language_fallbacks_sha256,
                effective.page_index_sha256, effective.title_index_sha256, effective.temporal_scope }) |value| {
                hash.update(value); hash.update("\x00");
            }
            hash.update(std.mem.asBytes(&effective.page_index_bytes));
            hash.update(std.mem.asBytes(&effective.title_index_bytes));
        } else hash.update("\x00");
        var result: [32]u8 = undefined;
        hash.final(&result);
        return result;
    }
    pub fn current(self: NormalTitleDefaults, title: []const u8, namespace_catalog: ?*const @import("namespace_registry").Registry) bool {
        if (!sameSource(self.title, title) or namespace_catalog != self.namespace_catalog or
            !std.mem.eql(u8, &self.namespace_sha256, &self.namespace_catalog.source_sha256)) return false;
        const issued = normalTitleDefaults(title, namespace_catalog, self.options) orelse return false;
        return std.mem.eql(u8, self.config_sha256, issued.config_sha256) and
            sameSource(self.profile.base, issued.profile.base) and
            sameSource(self.profile.source_core, issued.profile.source_core) and
            sameSource(self.profile.source_converter_sha256, issued.profile.source_converter_sha256) and
            sameSource(self.profile.siteinfo_sha256, issued.profile.siteinfo_sha256) and
            sameSource(self.profile.static_default_variant orelse return false, issued.profile.static_default_variant orelse return false) and
            std.mem.eql(u8, &self.profile_sha256, &issued.profile_sha256);
    }
};
pub fn normalTitleDefaults(title: []const u8, namespace_catalog: ?*const @import("namespace_registry").Registry, options: NormalTitleOptions) ?NormalTitleDefaults {
    if (options.namespace_id != 0 or options.requested_variant != null or options.configured_default_variant != null or options.disable_title_conversion or
        title.len == 0 or !std.unicode.utf8ValidateSlice(title) or std.mem.indexOfAny(u8, title, "#[]{}<>&|\"'\r\n") != null) return null;
    for (title) |byte| if (std.ascii.isControl(byte)) return null;
    const ns = namespace_catalog orelse return null;
    const profile = ns.manual_conversion_context orelse return null;
    const variants = ns.language_conversion orelse return null;
    const static_variant = profile.static_default_variant orelse return null;
    // A missing MAIN rule falls through Parser to convertSplitTitle/translate.
    // Require the existing effective empty-table proof, not just core defaults.
    // Non-main namespace conversion has separate message/gender effects.
    const page = ns.ofTitle(title);
    const effective = profile.effective_override orelse return null;
    const table_title = ns.ofTitle(effective.namespace_title);
    if (page.id != 0 or !std.mem.eql(u8, page.text, title) or !profile.automatic_identity or
        table_title.id != 8 or !std.mem.startsWith(u8, table_title.text, "Conversiontable/") or
        !std.mem.eql(u8, table_title.text["Conversiontable/".len..], profile.base) or
        !std.mem.startsWith(u8, effective.message_key, "conversiontable/") or
        !std.mem.eql(u8, effective.message_key["conversiontable/".len..], profile.base) or
        effective.page_index_bytes == 0 or effective.title_index_bytes == 0) return null;
    for ([_][]const u8{ effective.interface_messages_sha256, effective.language_fallbacks_sha256,
        effective.page_index_sha256, effective.title_index_sha256 }) |value| {
        if (value.len != 64) return null;
        for (value) |byte| if (!std.ascii.isHex(byte)) return null;
    }
    if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or
        !std.mem.eql(u8, profile.base, ns.content_language) or !std.mem.eql(u8, static_variant, profile.base) or
        !std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2") or
        profile.source_converter_sha256.len != 64 or profile.siteinfo_sha256.len != 64 or variants.len == 0 or variants.len > 32) return null;
    for (profile.source_converter_sha256) |byte| if (!std.ascii.isHex(byte)) return null;
    for (profile.siteinfo_sha256) |byte| if (!std.ascii.isHex(byte)) return null;
    var selected = false;
    for (variants) |variant| if (std.mem.eql(u8, variant, static_variant)) { selected = true; };
    if (!selected) return null;
    return .{ .title = title, .namespace_catalog = ns, .namespace_sha256 = ns.source_sha256,
        .profile = profile, .profile_sha256 = NormalTitleDefaults.digest(profile, variants), .options = options,
        // MainConfigSchema at the same core sets DefaultLanguageVariant=false
        // and DisableTitleConversion=false; LanguageConverter then uses static.
        .config_sha256 = "3431088101d64e88c2da66453929f942b72b6e7fc540ecb289a21015cd97848a" };
}
