};
pub const Role = enum { normal, label, pronunciation, headword, example, quotation, citation, reference };
pub const Provenance = enum { parsed, protected_literal, entity_literal };

pub const CompiledTextRejection = struct {
    reason: enum { generated_link_marker, wiki_delimiter, html_token, external_opener },
    offset: usize,
};
pub fn compiledTextRejection(text: []const u8) ?CompiledTextRejection {
    if (std.mem.indexOf(u8, text, generated_link.prefix)) |at| return .{ .reason = .generated_link_marker, .offset = at };
    for ([_][]const u8{ "[[", "]]", "{{", "}}", "{|", "|}" }) |token| {
        if (std.mem.indexOf(u8, text, token)) |at| return .{ .reason = .wiki_delimiter, .offset = at };
    }
    var at: usize = 0;
    while (std.mem.indexOfScalarPos(u8, text, at, '<')) |start| {
        var name = start + 1;
        if (name < text.len and text[name] == '/') name += 1;
        if (name < text.len and std.ascii.isAlphabetic(text[name]) and std.mem.indexOfScalarPos(u8, text, name, '>') != null)
            return .{ .reason = .html_token, .offset = start };
        at = start + 1;
    }
    at = 0;
    while (std.mem.indexOfScalarPos(u8, text, at, '[')) |start| {
        if (start + 1 < text.len and text[start + 1] != '[' and ir.hasExternalProtocol(text[start + 1 ..]))
            return .{ .reason = .external_opener, .offset = start };
        at = start + 1;
    }
    return null;
}
pub fn requireCompiledText(text: []const u8) !void {
    if (compiledTextRejection(text) != null) return error.UncompiledPresentation;
}

/// Decode one authored STYLE value through the ordinary compiler semantics.
/// This grants no identity or scope authority; callers still bind the tag to
/// their exact borrowed source and balanced physical region.
/// One complete source HR opening. STYLE is source data, never a geometry grant:
/// the Book must bind every decoded attribute to the exact captured HR and the
/// observed cascade must independently account for all its declarations.
pub fn authoredRuleSourceOpening(source: []const u8, tag: syntax.Tag) ?[]const u8 {
    if (!tag.is("hr") or tag.closing or tag.html_pre) return null;
    const whole = Renderer.projectedTrackedTagOpening(.{ .bytes = source }, tag) orelse return null;
    if (trim(tag.attrs).len == 0) {
        if (!std.ascii.eqlIgnoreCase(whole, "<hr>") and !std.ascii.eqlIgnoreCase(whole, "<hr />")) return null;
    } else if (!Renderer.htmlNestedAttributes(tag.attrs, &.{"style"})) return null;
    return whole;
}

pub fn authoredStyleAttributeAlloc(a: A, tag: syntax.Tag) Error!?[]const u8 {
    var renderer: Renderer = .{ .a = a, .context = .{} };
    return renderer.semanticAttribute(tag, "style");
}

// Build-only motion custody stays inside one active renderer invocation.
// Unknown ancestry differs from a local style which has not inherited yet.
const NativeInlineMotionRoot = struct { source: MissingText, reference: ?enum { isolated } = null };
const NativeInlineMotionState = union(enum) {
    absent,
    unknown,
    proved: struct {
        root: *const NativeInlineMotionRoot,
        epoch: u64,
        last: ?*const NativeInlineMotionDeclaration = null,
    },
};
const LiteralSubject = struct {
        key: usize, root: *const NativeInlineMotionRoot, epoch: u64,
        declaration: ?*const NativeInlineMotionDeclaration, host: *const NativeArticleHost,
        snapshot: [32]u8, body: MissingText,
        profile: *const table_style_profile.Profile, node: *const table_style_profile.TextElement,
};
const LiteralSubjectWork = struct {
        snapshot_calls: usize = 0, snapshot_source_bytes: usize = 0,
        pair_scans: usize = 0, pair_source_bytes: usize = 0,
        sibling_scans: usize = 0, sibling_source_bytes: usize = 0,
};
const NativeInlineMotionOrigin = enum { html, wiki_table, wiki_row, wiki_td, wiki_th };
const NativeInlineMotionDeclaration = struct {
    origin: NativeInlineMotionOrigin = .html,
    previous: ?*const NativeInlineMotionDeclaration,
    source: MissingText,
    opening: []const u8,
    opening_snapshot: []const u8,
    css: []const u8,
};

const NativeRubyUnitlessLineHeight = struct {
    factor: f32,
    motion: NativeInlineMotionState,
    profile: ?*const table_style_profile.Profile,
    parent: ?*const NativeRubyUnitlessLineHeight,
};

pub const Style = struct {
    positioned_container_resolution: ?table_style_profile.ContainerResolution = null,
    positioned_container_opening: ?[]const u8 = null,
    // End of the borrowed child text for a matched inline formatting element.
    display_space_end: ?[*]const u8 = null,
