    ordinary_action_entity: ?[]const u8 = null,
    ordinary_action_origin: ?*OrdinaryActionGroupBinding = null,
    native_inline_motion: NativeInlineMotionState = .absent,
    ruby_unitless_line_height: ?NativeRubyUnitlessLineHeight = null,
    ruby_unitless_metric: bool = false,
    // Only the source-bound Table path sets these build-time ownership facts.
    authored_link_font_override: bool = false,
    cell_policy_inherited_font: bool = false,
    link_paint: ?presentation_types.LinkPaint = null,
    ordinary_link_paint: ?*OrdinaryLinkPaintBinding = null,
    table_link_source: ?[]const u8 = null,
    table_link_wrap: ?presentation_types.TextWrap = null,
    // Own candidate is transient; only the inherited refusal state is captured.
    relative_context_own: bool = false,
    text_element: ?*const table_style_profile.TextElement = null,
    custom_properties: ?table_style_profile.CustomEnvironment = null,
    relative_context_policy_present: bool = false,
    // Producer-only conservative inherited policy; never a reader field.
    column_fragmentation_policy_present: bool = false,
    table_collapse: ?table_style_profile.BorderCollapseState = null,
    table_inheritance_scoped: bool = false,
    // Own-element proof only; recomputed at each HTML/wiki table style entry.
    table_text_color_consumed: bool = false,
    image: ?presentation_types.InlineImage = null,
    image_fields_compiled: bool = false,
    provenance: Provenance = .parsed,
    kind: ir.InlineKind = .text,
    target: []const u8 = "",
    language: []const u8 = "",
    classes: []const u8 = "",
    direction: []const u8 = "",
    // Effective metadata saved before legacy Unicode isolation clears direction.
    // Consumed only when this exact captured interval becomes a typed scope.
    captured_direction: ?[]const u8 = null,
    explanation: []const u8 = "",
    tooltip: ?[]const u8 = null,
    tooltip_set: bool = false,
    // Build-only presence: an explicit empty title must suppress inheritance.
    explanation_set: bool = false,
    foreground: ?[]const u8 = null,
    // Concrete paint retained when nested cell content is flattened.
    background: ?[]const u8 = null,
    foreground_set: bool = false,
    font_scale: ?f32 = null,
    font_scale_basis: FontScaleBasis = .context,
    font_features: ?presentation_types.FontFeaturePolicy = null,
    font_family: ?presentation_types.ContainerFontFamily = null,
    font_scale_set: bool = false,
    // Build-only completeness; never serialized as span style or identity.
    font_size_unknown: bool = false,
    bold: bool = false,
    italic: bool = false,
    code: bool = false,
    small: bool = false,
    superscript: bool = false,
    subscript: bool = false,
    strike: bool = false,
    underline: bool = false,
    role: Role = .normal,
    // Only typed Ruby consumes this source-depth refusal; legacy spans do not.
    ruby_script_ambiguous: bool = false,
    // Build-only context: decorative file names are not semantic heading text.
    heading: bool = false,
    // Unmatched pre is ordinary parsed HTML, with preformatted whitespace.
    preserve_whitespace: bool = false,
    // Build-only generated Poem wrapper; never inferred from lexical classes.
    poem_indent: ?u8 = null,
    // Poem recursively parses its body before an enclosing internal holder.
    // Navigation remains inherited; a newly created holder clears this phase.
    poem_independent_parse: bool = false,
    // Keep the internal label parser while emitting an anchor without an action.
    // This build-only marker is never stored in a presentation span.
    self_link_target: ?[]const u8 = null,
    missing_nonaction: bool = false,
};
fn inheritInlineMetadata(style: *Style, parent: Style) void {
    if (style.native_inline_motion == .absent) style.native_inline_motion = parent.native_inline_motion;
    if (style.ruby_unitless_line_height == null) style.ruby_unitless_line_height = parent.ruby_unitless_line_height;
    if (style.text_element == null) style.text_element = parent.text_element;
    if (style.custom_properties == null) style.custom_properties = parent.custom_properties;
    style.relative_context_policy_present = style.relative_context_policy_present or parent.relative_context_policy_present;
    style.column_fragmentation_policy_present = style.column_fragmentation_policy_present or parent.column_fragmentation_policy_present;
    if (!style.table_inheritance_scoped) {
        style.table_collapse = parent.table_collapse;
        style.table_inheritance_scoped = parent.table_inheritance_scoped;
    }
    if (style.font_features == null) style.font_features = parent.font_features;
    if (style.font_family == null) style.font_family = parent.font_family;
    if (style.link_paint == null and style.kind == parent.kind and
        (style.kind == .link or style.kind == .external_link) and style.target.len != 0 and
        style.target.ptr == parent.target.ptr and style.target.len == parent.target.len) {
        style.link_paint = parent.link_paint; style.table_link_source = parent.table_link_source;
        style.table_link_wrap = parent.table_link_wrap;
    }
    if (!style.font_scale_set and style.font_scale == null) {
        style.font_scale = parent.font_scale;
        style.font_scale_basis = parent.font_scale_basis;
        style.font_scale_set = parent.font_scale_set or (parent.font_scale != null and !parent.cell_policy_inherited_font);
        style.cell_policy_inherited_font = parent.cell_policy_inherited_font;
        style.font_size_unknown = parent.font_size_unknown;
    }
    if (!style.tooltip_set and style.tooltip == null) {
        style.tooltip = parent.tooltip;
        style.tooltip_set = parent.tooltip_set or parent.tooltip != null;
    }
    if (!style.explanation_set and style.explanation.len == 0) {
        style.explanation = parent.explanation;
        style.explanation_set = parent.explanation_set or parent.explanation.len != 0;
    }
    if (!style.foreground_set and style.foreground == null) {
        style.foreground = parent.foreground;
        style.foreground_set = parent.foreground_set or parent.foreground != null;
    }
}

// Only an existing parsed HTML title with complete attribute quoting can
// authorize advisory metadata or a title-only owned fragment scope.
pub fn hasAuthoredTooltipTitle(tag: syntax.Tag) bool {
    if (tag.attr("title") == null) return false;
    var quote: u8 = 0;
    for (tag.attrs) |c| {
        if (quote != 0) {
            if (c == quote) quote = 0;
        } else if (c == '\'' or c == '"') quote = c
        else if (c == '<' or c == '>') return false;
    }
    return quote == 0;
}

