// Build-only source proof. The target remains the borrowed slice of this
// complete parsed external token; neither field is serialized into DPR.
pub const ExternalLiteralParameterProof = struct {
    token: []const u8,
    target: []const u8,
    // The retained token owns this raw slice; target owns only cleanUrl's pipe
    // escaping. Validation re-proves both, never trusting a span flag alone.
    literal_parent_source: ?[]const u8 = null,
    // Complete ordinary rendering input, retained across child/block parsing.
    // A token-local unmatched opener is not sufficient preprocessing proof.
    literal_parent_root: ?[]const u8 = null,
};

fn externalLiteralParameterProofMatches(proof: ExternalLiteralParameterProof, target: []const u8) bool {
    return externalLiteralParameterTokenMatches(proof, target, false);
}

fn externalLiteralParameterTokenMatches(proof: ExternalLiteralParameterProof, target: []const u8, allow_unlabelled: bool) bool {
    if (target.ptr != proof.target.ptr or target.len != proof.target.len or proof.token.len < 3 or
        proof.token[0] != '[' or proof.token[proof.token.len - 1] != ']') return false;
    if (proof.literal_parent_source) |raw| {
        if (allow_unlabelled) return false;
        const close = ir.literalUnclosedConditionalLinkClose(proof.token, 0) orelse return false;
        if (close + 1 != proof.token.len) return false;
        const root = proof.literal_parent_root orelse return false;
        if (root.len > 4 * 1024 * 1024) return false;
        const token_at = std.mem.indexOf(u8, root, proof.token) orelse return false;
        if (std.mem.indexOfPos(u8, root, token_at + 1, proof.token) != null) return false;
        // Conservatively exclude later/earlier closure, including syntax hidden
        // in attributes or another block. Do not infer expansion provenance from
        // a label, unknown missing-dependency bit, or reconstructed token alone.
        for ([_][]const u8{ root[0..token_at], root[token_at + proof.token.len ..] }) |outside|
            if (std.mem.indexOf(u8, outside, "{{") != null or std.mem.indexOf(u8, outside, "}}") != null) return false;
        const base = @intFromPtr(proof.token.ptr);
        const at = @intFromPtr(raw.ptr);
        if (at <= base or at - base >= proof.token.len or raw.len > proof.token.len - (at - base)) return false;
        var it: ir.InlineIterator = .{ .input = proof.token, .renderer_boundaries = true };
        const token = it.next() orelse return false;
        if (token.kind != .external_link or it.cursor != proof.token.len or token.external_label_prefix.len != 0 or
            token.target.ptr != raw.ptr or token.target.len != raw.len or token.text.ptr == raw.ptr or token.text.len == 0 or
            ir.literalUnclosedConditionalUrl(raw) == null) return false;
        var cursor: usize = 0;
        for (raw) |ch| {
            const width: usize = if (ch == '|') 3 else 1;
            if (cursor > target.len or width > target.len - cursor) return false;
            if (ch == '|') {
                if (!std.mem.eql(u8, target[cursor .. cursor + 3], "%7C")) return false;
            } else if (target[cursor] != ch) return false;
            cursor += width;
        }
        return cursor == target.len;
    }
    const base = @intFromPtr(proof.token.ptr);
    const at = @intFromPtr(target.ptr);
    if (at <= base or at - base >= proof.token.len or target.len > proof.token.len - (at - base)) return false;
    var it: ir.InlineIterator = .{ .input = proof.token, .renderer_boundaries = true };
    const token = it.next() orelse return false;
    if (token.kind != .external_link or it.cursor != proof.token.len or token.external_label_prefix.len != 0 or
        token.target.ptr != target.ptr or token.target.len != target.len or
        (!allow_unlabelled and token.text.ptr == token.target.ptr) or token.text.len == 0) return false;
    return Renderer.literalDefaultlessExternalParameter(target) != null;
}

pub fn hasCompiledExternalLiteralParameterTarget(span: Span) bool {
    if (span.kind != .external_link) return false;
    const proof = span.external_literal_parameter orelse return false;
    return externalLiteralParameterProofMatches(proof, span.target);
}

// Operate on final emitted spans, not a raw-source lookahead. This pass is
// idempotent and never edits authored span bytes or grants a provenance waiver.
// Captures/fragment regrouping copy whole Spans; validateSpans invokes it again
// after those joins and before the unchanged parsed-source rejection.
fn rubyDiagnosticChildren(a: A, original: []const Span, depth: usize) Error![]const Span {
    if (original.len == 0) return original;
    const children = try a.dupe(Span, original);
    try separateGeneratedDiagnosticBoundariesAt(a, children, depth);
    return children;
}

pub fn separateGeneratedDiagnosticBoundaries(a: A, spans: []Span) Error!void {
    return separateGeneratedDiagnosticBoundariesAt(a, spans, 0);
}
fn separateGeneratedDiagnosticBoundariesAt(a: A, spans: []Span, ruby_depth: usize) Error!void {
    var has_ruby = false;
    for (spans) |span| has_ruby = has_ruby or span.ruby != null or span.inline_padding_group != null or span.inline_action_group != null or span.inline_box_group != null;
    if (has_ruby) {
        // Validate the bounded semantic tree before copying any descendant.
        // Normalize child arrays before callers validate their aggregate text.
        if (ruby_depth > presentation_types.max_ruby_depth) return error.UncompiledPresentation;
        const validated = try rubyFallbackSpans(a, spans);
        a.free(validated);
        for (spans) |*span| if (span.inline_action_group) |original| {
            const group = try a.create(presentation_types.InlineActionGroup(Span));
            group.* = original.*;
            group.spans = try rubyDiagnosticChildren(a, original.spans, ruby_depth + 1);
            span.inline_action_group = group;
        };
        for (spans) |*span| if (span.inline_box_group) |original| {
            // A single source-bound entity contains no diagnostic boundary to
            // separate. Sharing it preserves its original group and leaf identity.
            if (span.static_frame_entity) |held| if (original.spans.len == 1) {
                const leaf = &original.spans[0];
                if (staticInlineFrame(span.*, original.*) and staticInlineOrdinarySpan(leaf.*) and
                    !leaf.generated_diagnostic and held.matches(original, leaf)) continue;
            };
            const group = try a.create(presentation_types.InlineBoxGroup(Span));
            group.* = original.*;
            group.spans = try rubyDiagnosticChildren(a, original.spans, ruby_depth + 1);
            if (presentation_types.inlineBoxHasOverlayContent(original.*)) {
                const overlays = try a.dupe(presentation_types.InlineBoxOverlayFor(Span), original.overlays);
                for (overlays) |*overlay| if (overlay.content) |body| {
                    const content = try a.create(presentation_types.InlineBoxOverlayContent(Span));
                    content.* = body.*;
                    content.spans = try rubyDiagnosticChildren(a, body.spans, ruby_depth + 2);
                    overlay.content = content;
                };
                group.overlays = overlays;
            }
            span.inline_box_group = group;
        };
        for (spans) |*span| if (span.inline_padding_group) |original| {
            const group = try a.create(presentation_types.InlinePaddingGroup(Span));
            group.* = original.*;
            group.spans = try rubyDiagnosticChildren(a, original.spans, ruby_depth + 1);
            span.inline_padding_group = group;
        };
        for (spans) |*span| if (span.ruby) |original| {
            const ruby = try a.create(presentation_types.Ruby(Span));
            ruby.* = original.*;
            const segments = try a.dupe(presentation_types.RubySegment(Span), original.segments);
            ruby.segments = segments;
            for (segments) |*segment| {
                segment.gap_before = try rubyDiagnosticChildren(a, segment.gap_before, ruby_depth + 1);
                const bases = try a.dupe(presentation_types.RubyBase(Span), segment.bases);
                segment.bases = bases;
                for (bases) |*base| {
                    base.gap_before = try rubyDiagnosticChildren(a, base.gap_before, ruby_depth + 1);
                    base.spans = try rubyDiagnosticChildren(a, base.spans, ruby_depth + 1);
                }
                const annotations = try a.dupe(presentation_types.RubyAnnotation(Span), segment.annotations);
                segment.annotations = annotations;
                for (annotations) |*annotation| {
                    annotation.gap_before = try rubyDiagnosticChildren(a, annotation.gap_before, ruby_depth + 1);
                    annotation.spans = try rubyDiagnosticChildren(a, annotation.spans, ruby_depth + 1);
                    annotation.fallback_before = try rubyDiagnosticChildren(a, annotation.fallback_before, ruby_depth + 1);
                    annotation.fallback_after = try rubyDiagnosticChildren(a, annotation.fallback_after, ruby_depth + 1);
                }
            }
            span.ruby = ruby;
        };
        const Boundary = struct {
            allocator: A,
            edge: ?u8 = null,
            generated: bool = false,
            writable_previous: ?*Span = null,
            fn consume(self: *@This(), span: *Span, writable: bool) Error!void {
                if (span.provenance != .parsed or span.kind == .line_break or span.image != null) {
                    self.edge = null; self.generated = false; self.writable_previous = null;
                    return;
                }
                if (span.text.len == 0) return;
                if (self.edge) |edge| if ((edge == '[' or edge == ']') and edge == span.text[0]) {
                    if (span.generated_diagnostic) {
                        // Child arrays are immutable owned semantic data. A
                        // generated diagnostic requiring mutation is not a
                        // certificate for parsed delimiter markup.
                        if (!writable) return error.UncompiledTemplate;
                        span.text = try std.fmt.allocPrint(self.allocator, " {s}", .{span.text});
                    } else if (self.generated) {
                        const previous = self.writable_previous orelse return error.UncompiledTemplate;
                        previous.text = try std.fmt.allocPrint(self.allocator, "{s} ", .{previous.text});
                    }
                };
                self.edge = span.text[span.text.len - 1];
                self.generated = span.generated_diagnostic;
                self.writable_previous = if (writable and span.generated_diagnostic) span else null;
            }
        };
        var boundary: Boundary = .{ .allocator = a };
        for (spans) |*span| {
            if (span.ruby != null or span.inline_padding_group != null or span.inline_action_group != null or span.inline_box_group != null) {
                const leaves = try rubyFallbackSpans(a, &.{span.*});
                defer a.free(leaves);
                for (leaves) |leaf| {
                    var read_only = leaf;
                    try boundary.consume(&read_only, false);
                }
            } else try boundary.consume(span, true);
        }
        return;
    }

    var previous: ?usize = null;
    for (spans, 0..) |*span, index| {
        if (span.provenance != .parsed or span.kind == .line_break or span.image != null) {
            previous = null;
            continue;
        }
        // Empty parsed emissions do not change the actual output boundary.
        if (span.text.len == 0) continue;
        if (previous) |prior| {
            const left = &spans[prior];
            const edge = left.text[left.text.len - 1];
            if ((edge == '[' or edge == ']') and edge == span.text[0]) {
                if (span.generated_diagnostic) {
                    span.text = try std.fmt.allocPrint(a, " {s}", .{span.text});
                } else if (left.generated_diagnostic) {
                    left.text = try std.fmt.allocPrint(a, "{s} ", .{left.text});
                }
            }
        }
        previous = index;
    }
}
