// Quotes are resolved at build time before HTML repair. Internal labels have
// their own quote scope; authored HTML belongs to the surrounding line scope.
const QuoteBoundaries = struct {
    link_close: ?usize,
    template_close: ?usize,
    fn init(input: []const u8) QuoteBoundaries {
        return .{ .link_close = std.mem.lastIndexOf(u8, input, "]]"), .template_close = std.mem.lastIndexOf(u8, input, "}}") };
    }
    fn canClose(self: QuoteBoundaries, input: []const u8, at: usize) bool {
        const last = if (starts(input[at..], "[[")) self.link_close else self.template_close;
        return if (last) |end| end > at else false;
    }
};
// A recognized raw HTML opener cannot occur in a MediaWiki link target.
// Stop before a pipe or any other structural byte: admitted labels, escaped
// angles, protected tags and incomplete/unknown HTML retain their own paths.
fn htmlInterruptedInternalOpening(input: []const u8, at: usize) bool {
    if (at > input.len or !starts(input[at..], "[[")) return false;
    const body_start = at + 2;
    const relative = std.mem.indexOfAny(u8, input[body_start..], "[]{}|<>&\r\n") orelse return false;
    const boundary = body_start + relative;
    if (input[boundary] != '<') return false;
    var tag = syntax.tagAt(input, boundary) orelse return false;
    // A complete TemplateStyles strip token may precede the real HTML opener.
    // That following opener, not the extension alone, proves this target invalid.
    if (!tag.closing and tag.self_closing and tag.is("templatestyles")) {
        if (tag.end == input.len or input[tag.end] != '<') return false;
        tag = syntax.tagAt(input, tag.end) orelse return false;
    }
    return !tag.closing and !tag.isOpaque() and syntax.pairedHtmlTag(tag.name);
}

// An empty link opener on its own authored list line is literal source. It
// cannot borrow a later chunk's close or hide the intervening block structure.
fn standaloneListLinkOpening(input: []const u8, at: usize) bool {
    if (at > input.len or !starts(input[at..], "[[")) return false;
    const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
    if (!std.mem.eql(u8, trim(input[at..end]), "[[")) return false;
    var begin = at;
    while (begin != 0 and input[begin - 1] != '\n') begin -= 1;
    var cursor = begin;
    while (cursor < at and std.mem.indexOfScalar(u8, "*#;:", input[cursor]) != null) : (cursor += 1) {}
    if (cursor == begin) return false;
    for (input[cursor..at]) |byte| if (byte != ' ' and byte != '\t') return false;
    return true;
}
// A complete inline link followed by a colon can label the same physical
// list line's empty opener. The label remains ordinary parsed source; only
// the final two brackets earn literal provenance. No later line is searched.
fn labeledListLinkOpening(input: []const u8, at: usize) bool {
    if (at > input.len or !starts(input[at..], "[[")) return false;
    const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
    if (!std.mem.eql(u8, trim(input[at..end]), "[[")) return false;
    var begin = at;
    while (begin != 0 and input[begin - 1] != '\n') begin -= 1;
    var cursor = begin;
    // Semicolon terms own their colon split in a separate body phase.
    while (cursor < at and std.mem.indexOfScalar(u8, "*#:", input[cursor]) != null) : (cursor += 1) {}
    if (cursor == begin) return false;
    const prefix = std.mem.trim(u8, input[cursor..at], " \t");
    if (prefix.len == 0 or prefix[prefix.len - 1] != ':') return false;
    const label = std.mem.trim(u8, prefix[0 .. prefix.len - 1], " \t");
    if (!starts(label, "[[")) return false;
    const pair = syntax.balanced(label, 0) orelse return false;
    if (pair.end != label.len or label.len < 5) return false;
    const inner = label[2 .. label.len - 2];
    if (std.mem.indexOfAny(u8, inner, "[]{}<>'\"\r\n") != null) return false;
    for (inner) |byte| if (std.ascii.isControl(byte)) return false;
    if (std.mem.indexOfScalar(u8, inner, '|')) |pipe| {
        if (trim(inner[0..pipe]).len == 0 or trim(inner[pipe + 1 ..]).len == 0 or
            std.mem.indexOfScalar(u8, inner[pipe + 1 ..], '|') != null) return false;
    } else if (trim(inner).len == 0) return false;
    return true;
}

fn quoteOpaqueEnd(a: A, input: []const u8, at: usize, boundaries: QuoteBoundaries, opaque_scan: *syntax.OpaqueScan, context: Context) Error!?usize {
    if (input[at] == '<') {
        if (opaque_scan.protectedEnd(input, at, null)) |end| return end;
        if (opaque_scan.tagAt(input, at, null)) |tag| return tag.end;
    }
    if (ir.doubleOpeningExternalToken(input, at)) return null;
    if ((starts(input[at..], "[[") or starts(input[at..], "{{")) and boundaries.canClose(input, at)) {
        if (syntax.balancedWithOpaqueScan(input, at, opaque_scan)) |pair| {
            if (starts(input[at..], "[[") and try ordinaryBodyLinkRefused(a, input[at..pair.end], context)) return null;
            return pair.end;
        }
    }
    return null;
}
// A body owner may request a physical cut through a rejected empty list
// opener. This exception changes source-cut traversal only, never quote
// normalization or literal provenance in an admitted label/template owner.
fn quoteOpaqueCutEnd(a: A, input: []const u8, at: usize, boundaries: QuoteBoundaries, opaque_scan: *syntax.OpaqueScan, context: Context, label_scope: bool, cut: ?usize) Error!?usize {
    const end = try quoteOpaqueEnd(a, input, at, boundaries, opaque_scan, context);
    if (!label_scope) if (cut) |position| if (end) |skip| {
        if (skip > position and (standaloneListLinkOpening(input, at) or labeledListLinkOpening(input, at) or htmlInterruptedInternalOpening(input, at))) return null;
    };
    return end;
}
fn ordinaryBodyLinkRefused(a: A, input: []const u8, context: Context) Error!bool {
    var it: ir.InlineIterator = .{ .input = input, .renderer_boundaries = true, .link_trail = context.link_trail };
    const token = it.next() orelse return false;
    if (token.kind != .link or !token.link_has_pipe or it.cursor != input.len or
        std.mem.indexOfScalar(u8, token.text, '\n') == null or syntax.delimiter(token.text, "[[", 0) == null) return false;
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    var resolved: ?[]const u8 = null;
    var refused = false;
    var probe: Renderer = .{ .a = arena.allocator(), .context = context, .navigation_target_probe = &resolved, .navigation_refused_probe = &refused, .navigation_probe_source = input };
    try probe.inlineText(input, .{}, 0);
    return refused;
}
const QuoteBehaviorRegistry = @import("namespace_registry").behavior_switches.Registry;
fn quoteControlEnd(a: A, input: []const u8, at: usize, registry: ?*const QuoteBehaviorRegistry) Error!?usize {
    const end = (if (registry) |captured| try captured.matchAt(a, input, at) else syntax.behaviorSwitchEnd(input, at)) orelse return null;
    const toc = if (registry) |captured| try captured.tocMatchAt(a, input, at) else if (std.ascii.eqlIgnoreCase(input[at..end], "__TOC__")) end else null;
    return if (toc != null and toc.? == end) null else end;
}
const QuoteRun = struct { count: usize, end: usize };
fn quoteRun(a: A, input: []const u8, at: usize, registry: ?*const QuoteBehaviorRegistry) Error!QuoteRun {
    var end = at;
    var count: usize = 0;
    while (end < input.len and input[end] == '\'') {
        count += 1;
        end += 1;
        var next = end;
        while (next < input.len) {
            if (try quoteControlEnd(a, input, next, registry)) |skip| next = skip else break;
        }
        // Consume empty controls only when another apostrophe joins this run.
        // Otherwise their exact authored bytes remain for the existing phase.
        if (next < input.len and input[next] == '\'') end = next;
    }
    return .{ .count = count, .end = end };
}
fn quoteRemember(previous: *[2]u8, bytes: []const u8) void {
    if (bytes.len >= 2) {
        previous.* = .{ bytes[bytes.len - 1], bytes[bytes.len - 2] };
    } else if (bytes.len == 1) {
        // Untyped aggregate assignment writes into previous element by element.
        const prior_first = previous[0];
        previous.* = .{ bytes[0], prior_first };
    }
}

const QuoteState = enum { none, b, i, bi, ib, both };
pub const QuoteSeed = struct { state: QuoteState, correction: ?usize, line_end: usize, boundaries: QuoteBoundaries, label_scope: bool = false, opaque_cut: ?usize = null };
pub const LinkQuoteObservation = struct { entry: QuoteSeed, resume_quote: QuoteSeed };

const PreparedQuoteSource = struct {
    source: MissingText,
    angles: []const usize,

    // Public cuts/seeds remain in raw source coordinates. Only quote scanning
    // and emission use the entity-expanded domain; heading origins never move.
    fn forward(self: PreparedQuoteSource, raw: usize) usize {
        var low: usize = 0;
        var high = self.angles.len;
        while (low < high) {
            const middle = low + (high - low) / 2;
            if (self.angles[middle] < raw) low = middle + 1 else high = middle;
        }
        return raw + low * 3;
    }
    fn backward(self: PreparedQuoteSource, prepared: usize) usize {
        var low: usize = 0;
        var high = self.angles.len;
        while (low < high) {
            const middle = low + (high - low) / 2;
            const end = self.angles[middle] + middle * 3 + 4;
            if (end <= prepared) low = middle + 1 else high = middle;
        }
        if (low < self.angles.len and prepared > self.angles[low] + low * 3) return self.angles[low];
        return prepared - low * 3;
    }
    fn forwardSeed(self: PreparedQuoteSource, seed: QuoteSeed) QuoteSeed {
        var result = seed;
        result.line_end = self.forward(seed.line_end);
        if (seed.opaque_cut) |value| result.opaque_cut = self.forward(value);
        if (seed.correction) |value| result.correction = self.forward(value);
        if (seed.boundaries.link_close) |value| result.boundaries.link_close = self.forward(value);
        if (seed.boundaries.template_close) |value| result.boundaries.template_close = self.forward(value);
        return result;
    }
    fn rawSeed(self: PreparedQuoteSource, seed: QuoteSeed, raw_cut: usize, prepared_cut: usize) QuoteSeed {
        var result = seed;
        result.line_end = self.backward(prepared_cut + seed.line_end) - raw_cut;
        if (seed.opaque_cut) |value| result.opaque_cut = self.backward(prepared_cut + value) - raw_cut;
        if (seed.correction) |value| result.correction = self.backward(prepared_cut + value) - raw_cut;
        if (seed.boundaries.link_close) |value| result.boundaries.link_close = self.backward(prepared_cut + value) - raw_cut;
        if (seed.boundaries.template_close) |value| result.boundaries.template_close = self.backward(prepared_cut + value) - raw_cut;
        return result;
    }
    fn release(self: PreparedQuoteSource, a: A, original: MissingText, retained: MissingText) void {
        a.free(self.angles);
        if (self.source.bytes.ptr != original.bytes.ptr and self.source.bytes.ptr != retained.bytes.ptr) a.free(self.source.bytes);
        if (self.source.ranges.ptr != original.ranges.ptr and self.source.ranges.ptr != retained.ranges.ptr) a.free(self.source.ranges);
        if (self.source.literal_curly_ranges.ptr != original.literal_curly_ranges.ptr and self.source.literal_curly_ranges.ptr != retained.literal_curly_ranges.ptr) a.free(self.source.literal_curly_ranges);
    }
};

fn prepareQuoteSource(a: A, source: MissingText) Error!PreparedQuoteSource {
    var renderer: Renderer = .{ .a = a, .context = .{} };
    return renderer.prepareQuoteSource(source, false);
}

const QuoteTransition = struct { prefix: []const u8, suffix: []const u8 = "", state: QuoteState };
fn quoteTransitionValue(state: QuoteState, run: usize) QuoteTransition {
    const transitions = [6][3]QuoteTransition{
        .{ .{ .prefix = "<i>", .state = .i }, .{ .prefix = "<b>", .state = .b }, .{ .prefix = "", .state = .both } },
        .{ .{ .prefix = "<i>", .state = .bi }, .{ .prefix = "</b>", .state = .none }, .{ .prefix = "</b><i>", .state = .i } },
        .{ .{ .prefix = "</i>", .state = .none }, .{ .prefix = "<b>", .state = .ib }, .{ .prefix = "</i><b>", .state = .b } },
        .{ .{ .prefix = "</i>", .state = .b }, .{ .prefix = "</i></b><i>", .state = .i }, .{ .prefix = "</i></b>", .state = .none } },
        .{ .{ .prefix = "</b></i><b>", .state = .b }, .{ .prefix = "</b>", .state = .i }, .{ .prefix = "</b></i>", .state = .none } },
        .{ .{ .prefix = "<b><i>", .suffix = "</i>", .state = .b }, .{ .prefix = "<i><b>", .suffix = "</b>", .state = .i }, .{ .prefix = "<i><b>", .suffix = "</b></i>", .state = .none } },
    };
    const index: usize = switch (run) {
        2 => 0,
        3 => 1,
        5 => 2,
        else => unreachable,
    };
    return transitions[@backingInt(state)][index];
}
fn quoteTransition(out: *std.ArrayList(u8), buffer: *std.ArrayList(u8), a: A, state: *QuoteState, run: usize) Error!void {
    const transition = quoteTransitionValue(state.*, run);
    try out.appendSlice(a, transition.prefix);
    if (state.* == .both) {
        try out.appendSlice(a, buffer.items);
        buffer.clearRetainingCapacity();
    }
    try out.appendSlice(a, transition.suffix);
    state.* = transition.state;
}
fn quoteFinish(out: *std.ArrayList(u8), buffer: *std.ArrayList(u8), a: A, state: QuoteState) Error!void {
    const close: []const u8 = switch (state) {
        .none => "",
        .b => "</b>",
        .i => "</i>",
        .bi => "</i></b>",
        .ib => "</b></i>",
        .both => "",
    };
    if (state == .both and buffer.items.len != 0) {
        try out.appendSlice(a, "<b><i>");
        try out.appendSlice(a, buffer.items);
        try out.appendSlice(a, "</i></b>");
        buffer.clearRetainingCapacity();
    }
    try out.appendSlice(a, close);
}
fn hasWikiQuoteMarkers(a: A, input: []const u8, depth: usize, boundaries: QuoteBoundaries, registry: ?*const QuoteBehaviorRegistry, context: Context) Error!bool {
    if (depth >= max_depth or std.mem.indexOfScalar(u8, input, '\'') == null) return false;
    var at: usize = 0;
    var opaque_scan: syntax.OpaqueScan = .{};
    while (at < input.len) {
        if (try quoteOpaqueEnd(a, input, at, boundaries, &opaque_scan, context)) |end| {
            if (starts(input[at..], "[[")) {
                const inner = input[at + 2 .. end - 2];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    if (try hasWikiQuoteMarkers(a, inner[pipe + 1 ..], depth + 1, QuoteBoundaries.init(inner[pipe + 1 ..]), registry, context)) return true;
                }
            }
            at = end;
        } else {
            if (try quoteControlEnd(a, input, at, registry)) |skip| {
                at = skip;
                continue;
            }
            if (input[at] == '\'' and (try quoteRun(a, input, at, registry)).count >= 2) return true;
            at += 1;
        }
    }
    return false;
}

const QuoteLineInfo = struct { end: usize, correction: ?usize };
fn quoteLineInfo(a: A, input: []const u8, start: usize, label_scope: bool, boundaries: QuoteBoundaries, registry: ?*const QuoteBehaviorRegistry, opaque_scan: *syntax.OpaqueScan, context: Context, cut: ?usize) Error!QuoteLineInfo {
    var end = start;
    var bold_count: usize = 0;
    var italic_count: usize = 0;
    var single: ?usize = null;
    var multi: ?usize = null;
    var space: ?usize = null;
    var previous: [2]u8 = .{ 0, 0 };
    while (end < input.len and (label_scope or input[end] != '\n')) {
        if (try quoteOpaqueCutEnd(a, input, end, boundaries, opaque_scan, context, label_scope, cut)) |skip| {
            quoteRemember(&previous, input[end..skip]);
            end = skip;
            continue;
        }
        if (try quoteControlEnd(a, input, end, registry)) |skip| {
            end = skip;
            continue;
        }
        const quote = try quoteRun(a, input, end, registry);
        const run = quote.count;
        const normalized = if (run == 4) @as(usize, 3) else if (run > 5) @as(usize, 5) else run;
        if (normalized == 2 or normalized == 5) italic_count += 1;
        if (normalized == 3 or normalized == 5) bold_count += 1;
        if (normalized == 3) {
            const x1: u8 = if (run == 4) '\'' else previous[0];
            const x2: u8 = if (run == 4) previous[0] else previous[1];
            if (x1 == ' ') {
                if (space == null) space = end;
            } else if (x2 == ' ') {
                if (single == null) single = end;
            } else if (multi == null) multi = end;
        }
        if (run == 0) {
            quoteRemember(&previous, input[end .. end + 1]);
            end += 1;
        } else {
            quoteRemember(&previous, if (run == 1) "'" else "''");
            end = quote.end;
        }
    }
    const counted_correction: ?usize = if (bold_count % 2 == 1 and italic_count % 2 == 1)
        (if (single) |at| at else if (multi) |at| at else space)
    else
        null;
    return .{ .end = end, .correction = counted_correction };
}
const QuoteBoundaryScan = struct {
    input: []const u8,
    boundaries: QuoteBoundaries,
    raw_input_len: usize,
    initial: ?QuoteSeed,
    scratch: ?std.heap.ArenaAllocator = null,
    prepared: ?PreparedQuoteSource = null,
    cursor: usize = 0,
    line: ?QuoteLineInfo = null,
    // Counting and walking retain the same opaque policy for this line.
    // A later cut must not promote a previously visible root to an opaque one.
    line_cut: ?usize = null,
    state: QuoteState = .none,
    label_scope: bool = false,
    count_opaque: syntax.OpaqueScan = .{},
    walk_opaque: syntax.OpaqueScan = .{},
    context: Context = .{},

    fn init(input: []const u8, seed: ?QuoteSeed) QuoteBoundaryScan {
        return .{ .input = input, .raw_input_len = input.len, .initial = seed, .boundaries = if (seed) |value| value.boundaries else QuoteBoundaries.init(input), .state = if (seed) |value| value.state else .none, .label_scope = if (seed) |value| value.label_scope else false, .line = if (seed) |value| .{ .end = @min(value.line_end, input.len), .correction = value.correction } else null, .line_cut = if (seed) |value| value.opaque_cut else null };
    }
    fn initWithContext(input: []const u8, seed: ?QuoteSeed, context: Context) QuoteBoundaryScan {
        var scan = init(input, seed);
        scan.context = context;
        return scan;
    }
    fn shifted(boundary: ?usize, offset: usize) ?usize {
        return if (boundary) |end| (if (end >= offset) end - offset else null) else null;
    }
    fn deinit(self: *QuoteBoundaryScan) void {
        if (self.scratch) |*scratch| scratch.deinit();
        self.scratch = null;
    }
    fn at(self: *QuoteBoundaryScan, a: A, raw_position: usize, registry: ?*const QuoteBehaviorRegistry) Error!QuoteSeed {
        if (raw_position > self.raw_input_len) return error.InvalidPreContext;
        if (self.prepared == null) {
            self.scratch = std.heap.ArenaAllocator.init(a);
            self.prepared = try prepareQuoteSource(self.scratch.?.allocator(), MissingText.untracked(self.input));
            self.input = self.prepared.?.source.bytes;
            if (self.initial) |raw_seed| {
                const seed = self.prepared.?.forwardSeed(raw_seed);
                self.boundaries = seed.boundaries;
                self.line = .{ .end = @min(seed.line_end, self.input.len), .correction = seed.correction };
                self.line_cut = seed.opaque_cut;
            } else self.boundaries = QuoteBoundaries.init(self.input);
        }
        const position = self.prepared.?.forward(raw_position);
        if (position < self.cursor or position > self.input.len) return error.InvalidPreContext;
        while (true) {
            if (self.line == null) {
                self.line = try quoteLineInfo(a, self.input, self.cursor, self.label_scope, self.boundaries, registry, &self.count_opaque, self.context, position);
                self.line_cut = position;
            }
            const line = self.line.?;
            if (self.cursor == position) return self.prepared.?.rawSeed(.{ .state = self.state, .correction = shifted(line.correction, position), .line_end = line.end - position, .boundaries = .{ .link_close = shifted(self.boundaries.link_close, position), .template_close = shifted(self.boundaries.template_close, position) }, .label_scope = self.label_scope, .opaque_cut = if (self.line_cut) |cut| (if (cut > position) cut - position else 0) else null }, raw_position, position);
            if (self.cursor == line.end) {
                self.cursor += 1;
                self.line = null;
                self.state = .none;
                continue;
            }
            if (try quoteOpaqueCutEnd(a, self.input, self.cursor, self.boundaries, &self.walk_opaque, self.context, self.label_scope, self.line_cut)) |end| {
                if (end > position) return error.InvalidPreContext;
                self.cursor = end;
                continue;
            }
            if (try quoteControlEnd(a, self.input, self.cursor, registry)) |end| {
                if (end > position) return error.InvalidPreContext;
                self.cursor = end;
                continue;
            }
            const run = try quoteRun(a, self.input, self.cursor, registry);
            if (run.count >= 2) {
                const normalized: usize = if (line.correction != null and line.correction.? == self.cursor) 2 else if (run.count == 4) 3 else if (run.count > 5) 5 else run.count;
                self.state = quoteTransitionValue(self.state, normalized).state;
            }
            const end = if (run.count == 0) self.cursor + 1 else run.end;
            if (end > position) return error.InvalidPreContext;
            self.cursor = end;
        }
    }
};

fn labelQuoteSeed(a: A, input: []const u8, registry: ?*const QuoteBehaviorRegistry) Error!QuoteSeed {
    return labelQuoteSeedWithContext(a, input, .{ .behavior_switches = registry });
}
fn labelQuoteSeedWithContext(a: A, input: []const u8, context: Context) Error!QuoteSeed {
    var scan = QuoteBoundaryScan.initWithContext(input, null, context);
    defer scan.deinit();
    scan.label_scope = true;
    return scan.at(a, 0, context.behavior_switches);
}

// A single forward walk over one admitted raw label supplies all owner cuts.
// Values contain offsets and state only; no probe-arena storage escapes.
pub fn linkQuoteCutSeedsAlloc(a: A, input: []const u8, cuts: []const usize, entry: QuoteSeed, registry: ?*const QuoteBehaviorRegistry) Error![]QuoteSeed {
    return linkQuoteCutSeedsWithContextAlloc(a, input, cuts, entry, .{ .behavior_switches = registry });
}
pub fn linkQuoteCutSeedsWithContextAlloc(a: A, input: []const u8, cuts: []const usize, entry: QuoteSeed, context: Context) Error![]QuoteSeed {
    if (!entry.label_scope) return error.InvalidPreContext;
    return quoteCutSeedsAlloc(a, input, cuts, entry, context);
}
pub fn bodyQuoteCutSeedsAlloc(a: A, input: []const u8, cuts: []const usize, registry: ?*const QuoteBehaviorRegistry) Error![]QuoteSeed {
    return bodyQuoteCutSeedsWithContextAlloc(a, input, cuts, .{ .behavior_switches = registry });
}
pub fn bodyQuoteCutSeedsWithContextAlloc(a: A, input: []const u8, cuts: []const usize, context: Context) Error![]QuoteSeed {
    return quoteCutSeedsAlloc(a, input, cuts, null, context);
}
fn quoteCutSeedsAlloc(a: A, input: []const u8, cuts: []const usize, entry: ?QuoteSeed, context: Context) Error![]QuoteSeed {
    const result = try a.alloc(QuoteSeed, cuts.len);
    errdefer a.free(result);
    var scan = QuoteBoundaryScan.initWithContext(input, entry, context);
    defer scan.deinit();
    var previous: ?usize = null;
    for (cuts, result) |cut, *seed| {
        if (cut > input.len or (previous != null and cut <= previous.?)) return error.InvalidPreContext;
        seed.* = try scan.at(a, cut, context.behavior_switches);
        previous = cut;
    }
    return result;
}

fn quoteFormatting(state: QuoteState) SpanFlags {
    return switch (state) {
        .b => .{ .bold = true },
        .i => .{ .italic = true },
        .bi, .ib, .both => .{ .bold = true, .italic = true },
        .none => .{},
    };
}

// Reuse the ordinary internal-link label stage for an already source-bound
// observation. These bytes confer no authority; the page owner must still
// match its exact original occurrence and the actual renderer options.
pub fn figureObservationReadyCaptionAlloc(a: A, caption: []const u8, context: Context) Error!?FigureCaptionSourceShape {
    var renderer: Renderer = .{ .a = a, .context = context };
    return renderer.observedReadyCaptionSource(caption);
}

pub fn figureObservationStageOptionsAlloc(a: A, options: []const u8, context: Context) Error![]const u8 {
    return normalizeMisnestedHtmlDepth(a, try normalizeWikiQuotesSeededWithContext(a, options, 1, true, context, null), 1, false);
}

// The observation scanner uses the ordinary File target stage, including its
// single entity decode and the already-qualified File-only percent decode.
// This yields no Figure admission and never promotes an explicit text link.
// Build-only correspondence query; use the same maintained interwiki resolver
// as ordinary link emission. This does not render a label or authorize its CSS.
pub fn literalSourceLinkDestinationAlloc(a: A, ns: *const @import("namespace_registry").Registry, raw: []const u8) Error!?struct { target: []const u8, external: bool, source_title: []const u8 } {
    if (raw.len == 0 or std.mem.indexOfAny(u8, raw, "<>[]{}|?\\\r\n\x00") != null or !safeInternalTarget(raw)) return null;
    var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = ns } };
    const decoded = try renderer.internalPercentTitleText(raw);
    if (Renderer.invalidDecodedOrdinaryTitle(decoded) or std.mem.indexOfAny(u8, decoded, "<>[]{}|?\\\r\n\x00") != null) return null;
    const title = ns.normalizeTitle(a, decoded, 0, .any) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null };
    // The ordinary link path removes one authored leading colon before
    // Category membership. Preserve that explicit text-link distinction through
    // title normalization; File/media observations retain their separate issuer.
    const explicit_category = starts(raw, ":") and ns.ofTitle(raw[1..]).id == 14;
    if (renderer.namespaceOfTarget(title)) |id| if (id == 6 or (id == 14 and !explicit_category)) return null;
    const selected = try renderer.interwikiDestination(renderer.currentWikiTarget(title), 0);
    if (selected.target.len == 0 or renderer.fallbacks.any()) return null;
    return .{ .target = selected.target, .external = selected.external, .source_title = title };
}

pub fn figureObservationFileTargetAlloc(a: A, raw: []const u8, context: Context) Error!?[]const u8 {
    if (context.namespace_catalog == null) return null;
    var renderer: Renderer = .{ .a = a, .context = context };
    const file = try renderer.internalFileTitleText(raw);
    var target = file.text;
    if (!safeInternalTarget(target) or internalTargetNeedsLiteralBody(target) or
        (file.decoded_file and Renderer.invalidDecodedFileTitle(target)) or starts(target, ":")) return null;
    if (std.mem.indexOfScalar(u8, target, '_') != null) {
        const normalized = try a.dupe(u8, target);
        std.mem.replaceScalar(u8, normalized, '_', ' ');
        target = normalized;
    }
    target = renderer.currentWikiTarget(target);
    if (renderer.namespaceOfTarget(target) != 6) return null;
    return target;
}

fn normalizeWikiQuotes(a: A, input: []const u8, depth: usize, label_scope: bool) Error![]const u8 {
    return normalizeWikiQuotesWithControls(a, input, depth, label_scope, null);
}
fn normalizeWikiQuotesWithControls(a: A, input: []const u8, depth: usize, label_scope: bool, registry: ?*const QuoteBehaviorRegistry) Error![]const u8 {
    return normalizeWikiQuotesSeeded(a, input, depth, label_scope, registry, null);
}
fn normalizeWikiQuotesSeeded(a: A, input: []const u8, depth: usize, label_scope: bool, registry: ?*const QuoteBehaviorRegistry, initial: ?QuoteSeed) Error![]const u8 {
    return normalizeWikiQuotesSeededWithContext(a, input, depth, label_scope, .{ .behavior_switches = registry }, initial);
}
fn normalizeWikiQuotesSeededWithContext(a: A, input: []const u8, depth: usize, label_scope: bool, context: Context, initial: ?QuoteSeed) Error![]const u8 {
    const raw = MissingText.untracked(input);
    const prepared = try prepareQuoteSource(a, raw);
    errdefer prepared.release(a, raw, raw);
    // This quote-only helper preserves its borrowed source when no active
    // quotes exist. Renderer sanitation has its own explicit preparation.
    if (initial == null and !try hasWikiQuoteMarkers(a, prepared.source.bytes, depth, QuoteBoundaries.init(prepared.source.bytes), context.behavior_switches, context)) {
        prepared.release(a, raw, raw);
        return input;
    }
    const output = try normalizeWikiQuotesPreparedWithContext(a, prepared.source.bytes, depth, label_scope, context, if (initial) |seed| prepared.forwardSeed(seed) else null);
    prepared.release(a, raw, MissingText.untracked(output));
    return output;
}
fn normalizeWikiQuotesPreparedWithContext(a: A, input: []const u8, depth: usize, label_scope: bool, context: Context, initial: ?QuoteSeed) Error![]const u8 {
    const registry = context.behavior_switches;
    const boundaries = if (initial) |seed| seed.boundaries else QuoteBoundaries.init(input);
    if (initial == null and !try hasWikiQuoteMarkers(a, input, depth, boundaries, registry, context)) return input;
    var out: std.ArrayList(u8) = .empty;
    var buffer: std.ArrayList(u8) = .empty;
    var line_start: usize = 0;
    var count_opaque: syntax.OpaqueScan = .{};
    var emit_opaque: syntax.OpaqueScan = .{};
    while (line_start < input.len) {
        const info: QuoteLineInfo = if (line_start == 0 and initial != null)
            .{ .end = @min(initial.?.line_end, input.len), .correction = initial.?.correction }
        else
            try quoteLineInfo(a, input, line_start, label_scope, boundaries, registry, &count_opaque, context, null);
        const end = info.end;
        const correction = info.correction;
        var cursor = line_start;
        var state: QuoteState = if (line_start == 0 and initial != null) initial.?.state else .none;
        if (state != .none and state != .both) try out.appendSlice(a, switch (state) {
            .b => "<b>",
            .i => "<i>",
            .bi => "<b><i>",
            .ib => "<i><b>",
            else => unreachable,
        });
        while (cursor < end) {
            const sink = if (state == .both) &buffer else &out;
            if (try quoteOpaqueEnd(a, input, cursor, boundaries, &emit_opaque, context)) |skip| {
                if (starts(input[cursor..], "[[")) {
                    const inner = input[cursor + 2 .. skip - 2];
                    if (syntax.delimiter(inner, "|", 0)) |pipe| {
                        try sink.appendSlice(a, input[cursor .. cursor + 2 + pipe + 1]);
                        try sink.appendSlice(a, try normalizeMisnestedHtmlDepth(a, try normalizeWikiQuotesSeededWithContext(a, inner[pipe + 1 ..], depth + 1, true, context, null), depth + 1, false));
                        try sink.appendSlice(a, "]]");
                    } else try sink.appendSlice(a, input[cursor..skip]);
                } else try sink.appendSlice(a, input[cursor..skip]);
                cursor = skip;
                continue;
            }
            if (try quoteControlEnd(a, input, cursor, registry)) |skip| {
                try sink.appendSlice(a, input[cursor..skip]);
                cursor = skip;
                continue;
            }
            const quote = try quoteRun(a, input, cursor, registry);
            const run = quote.count;
            if (run >= 2) {
                var normalized = if (run == 4) @as(usize, 3) else if (run > 5) @as(usize, 5) else run;
                var literal = if (run == 4) @as(usize, 1) else if (run > 5) run - 5 else 0;
                if (correction != null and correction.? == cursor) {
                    normalized = 2;
                    literal += 1;
                }
                // Encoded extras cannot become fresh quote markers in recursive HTML.
                for (0..literal) |_| try sink.appendSlice(a, "&#39;");
                try quoteTransition(&out, &buffer, a, &state, normalized);
                cursor = quote.end;
            } else {
                try sink.append(a, input[cursor]);
                cursor += 1;
            }
        }
        try quoteFinish(&out, &buffer, a, state);
        if (end < input.len) try out.append(a, '\n');
        line_start = if (end < input.len) end + 1 else end;
    }
    return out.toOwnedSlice(a);
}

fn appendMissingBuffer(a: A, out: *missing_dependency.Builder, buffer: *missing_dependency.Builder) Error!void {
    const saved = try buffer.finish(a);
    try out.append(a, saved);
    buffer.* = .{};
}
fn quoteTransitionMissing(out: *missing_dependency.Builder, buffer: *missing_dependency.Builder, a: A, state: *QuoteState, run: usize) Error!void {
    const transition = quoteTransitionValue(state.*, run);
    try out.append(a, MissingText.untracked(transition.prefix));
    if (state.* == .both) try appendMissingBuffer(a, out, buffer);
    try out.append(a, MissingText.untracked(transition.suffix));
    state.* = transition.state;
}
fn quoteFinishMissing(out: *missing_dependency.Builder, buffer: *missing_dependency.Builder, a: A, state: QuoteState) Error!void {
    const close: []const u8 = switch (state) {
        .none, .both => "",
        .b => "</b>",
        .i => "</i>",
        .bi => "</i></b>",
        .ib => "</b></i>",
    };
    if (state == .both and buffer.bytes.items.len != 0) {
        try out.append(a, MissingText.untracked("<b><i>"));
        try appendMissingBuffer(a, out, buffer);
        try out.append(a, MissingText.untracked("</i></b>"));
    }
    try out.append(a, MissingText.untracked(close));
}
fn normalizeHtmlWithMissing(a: A, source: MissingText, depth: usize, recognize_external_links: bool) Error!MissingText {
    return normalizeMisnestedHtmlWithMissing(a, source, depth, recognize_external_links);
}
fn normalizeWikiQuotesWithMissing(a: A, source: MissingText, depth: usize, label_scope: bool, context: Context, initial: ?QuoteSeed) Error!MissingText {
