        try quoteFinishMapped(&out, &buffer, a, state, out_mapping, buffer_mapping, last_quote_origin);
        if (end < input.len) try appendQuoteSourceCopy(a, &out, out_mapping, source, end, end + 1);
        line_start = if (end < input.len) end + 1 else end;
    }
    var result = try out.finish(a);
    // Quote-only input can emit no copied source bytes. Selected provenance
    // still retains unknown even when every emitted token is compiler-owned.
    if (selected_source) result.unknown = result.unknown or source.unknown;
    if (mapped) {
        out_map.output = result.bytes;
        source_map.?.* = out_map;
        out_map = .{};
    }
    return result;
}

pub const Reference = struct { kind: citation_state.Kind = .note, number: usize, group_number: ?u32, name: []const u8 = "", group: []const u8 = "", body: []const u8 = "", missing: ?MissingText = null, spans: []const Span = &.{}, blocks: ?[]const Block = null, poem: bool = false, poem_direction: []const u8 = "", citation_plan: ?*const CitationPlan = null, citation_item: ?usize = null };
pub const ReferenceDefinition = struct { name: []const u8, group: []const u8 = "", body: []const u8 = "", missing: ?MissingText = null, list_defined: bool = false };
pub const ReferenceDefinitions = struct { body_link_continuations: ?*const BodyLinkContinuations = null, normal_title_defaults: ?NormalTitleDefaults = null, display_title_precedence: ?DisplayTitlePrecedence = null, local_link_targets: ?LocalLinkTargetSource = null, content_conversion: ?bool = null, items: []const ReferenceDefinition = &.{}, fallbacks: @import("presentation_fallback.zig").Report = .{}, citations: ?*const CitationPlan = null };

/// Collect names once without rendering reference bodies or creating citations.
pub fn referenceDefinitionsAlloc(a: std.mem.Allocator, source: []const u8) Error!ReferenceDefinitions {
    var renderer: Renderer = .{ .a = a, .context = .{} };
    try renderer.referenceDefinitions(source, "");
    return .{ .items = try renderer.ref_defs.toOwnedSlice(a), .fallbacks = renderer.fallbacks };
}

pub fn referenceDefinitionsWithMissingAlloc(a: A, source: MissingText) Error!ReferenceDefinitions {
    var renderer: Renderer = .{ .a = a, .context = .{}, .body_missing = source };
    try renderer.referenceDefinitions(source.bytes, "");
    return .{ .items = try renderer.ref_defs.toOwnedSlice(a), .fallbacks = renderer.fallbacks };
}

const max_nodes = 100_000;
const max_depth = 48;
fn starts(text: []const u8, prefix: []const u8) bool {
    return syntax.starts(text, prefix);
}
fn trim(text: []const u8) []const u8 {
    return syntax.trim(text);
}
fn listRoot(mark: u8) u8 {
    return if (mark == ';' or mark == ':') ';' else mark;
}
fn resetChangedListCounters(counts: []usize, previous: []const u8, current: []const u8) void {
    const limit = @min(counts.len, @min(previous.len, current.len));
    var common: usize = 0;
    while (common < limit and listRoot(previous[common]) == listRoot(current[common])) : (common += 1) {}
    // A different nested list family closes that list, but keeps common parents.
    @memset(counts[common..], 0);
}
// MediaWiki chooses definition separators after quote/link rendering, outside
// accepted HTML nesting. Keep the shared template delimiter rules unchanged.
const DefinitionColonScanner = struct {
    input: []const u8,
    cursor: usize = 0,
    html_depth: usize = 0,

    fn next(self: *DefinitionColonScanner, after: usize) ?usize {
        const text = self.input;
        while (self.cursor < text.len) {
            const colon = syntax.delimiter(text, ":", self.cursor) orelse return null;
            while (self.cursor < colon) {
                if (text[self.cursor] == '<') {
                    if (syntax.protectedEnd(text, self.cursor)) |end| {
                        self.cursor = end;
                        continue;
                    }
                    if (syntax.tagAt(text, self.cursor)) |tag| {
                        if (normalizableHtmlTag(tag.name) or oneOf(tag.name, &.{ "table", "tr", "td", "th", "caption" })) {
                            if (tag.closing) {
                                self.html_depth -|= 1;
                            } else {
                                // A slash does not close a non-void HTML container.
                                self.html_depth += 1;
                            }
                        }
                        self.cursor = tag.end;
                        continue;
                    }
                }
                if (starts(text[self.cursor..], "[[") or starts(text[self.cursor..], "{{")) {
                    if (syntax.balanced(text, self.cursor)) |pair| {
                        self.cursor = pair.end;
                        continue;
                    }
                }
                self.cursor += 1;
            }
            self.cursor = colon + 1;
            // A link-label opener can scope later text beyond the link itself.
            // Advance through it once; rejecting a link's colon must not reset depth.
            if (self.html_depth == 0 and colon >= after) return colon;
        }
        return null;
    }
};
pub fn inlineDefinitionSplit(text: []const u8) ?struct { term: []const u8, definition: []const u8 } {
    var scanner: DefinitionColonScanner = .{ .input = text };
    var colon = scanner.next(0) orelse return null;
    // Links become anchors before MediaWiki's definition-list pass. Reuse the
    // accepted bracketed/free-link extents without changing template delimiters.
    var tokens: ir.InlineIterator = .{ .input = text };
    while (true) {
        const before = tokens.cursor;
        const token = tokens.next() orelse break;
        if (tokens.cursor <= before) break;
        if (tokens.cursor <= colon) continue;
        if (token.kind == .external_link and before <= colon) {
            colon = scanner.next(tokens.cursor) orelse return null;
            continue;
        }
        break;
    }
    const term = std.mem.trim(u8, text[0..colon], " \t");
    const definition = std.mem.trim(u8, text[colon + 1 ..], " \t");
    return .{ .term = term, .definition = definition };
}
fn oneOf(name: []const u8, names: []const []const u8) bool {
    for (names) |n| if (std.ascii.eqlIgnoreCase(name, n)) return true;
    return false;
}

fn adoptionFormattingTag(name: []const u8) bool {
    return oneOf(name, &.{ "b", "big", "code", "em", "font", "i", "s", "small", "strike", "strong", "tt", "u" });
}

fn normalizableHtmlTag(name: []const u8) bool {
    return oneOf(name, &.{
        "b",    "strong", "i",    "em",   "u",    "s",   "del",        "strike", "ins",  "sup",  "sub",  "small",
        "big",  "span",   "font", "code", "tt",   "kbd", "samp",       "var",    "cite", "dfn",  "abbr", "q",
        "time", "mark",   "bdi",  "bdo",  "ruby", "rb",  "rt",         "rtc",    "rp",   "data", "h1",   "h2",
        "h3",   "h4",     "h5",   "h6",   "div",  "p",   "blockquote", "center", "ul",   "ol",   "li",   "dl",
        "dt",   "dd",
    });
}

// A complete admitted link can outlive a physical DIV owner. Its destination
// belongs to this occurrence, independently of the HTML formatting stack.
pub const BodyLinkContinuationParent = struct {
    source: MissingText,
    opening: usize,
    label_start: usize,
    label_end: usize,
    end: usize,
    target: []const u8,
    destination_resolved: bool = false,
};
pub const BodyLinkContinuation = struct {
    start: usize,
    label_start: usize,
    label_end: usize,
    end: usize,
    parent: BodyLinkContinuationParent,
};
pub const BodyLinkContinuations = struct {
    source: MissingText,
    original: MissingText,
    original_image: []const u8,
    source_image: []const u8,
    copies: QuoteSourceMap,
    original_binding: ?TableDirectionRangeBinding,
    items: []const BodyLinkContinuation,
    title: []const u8,
    namespace_catalog: ?*const @import("namespace_registry").Registry,
    local_link_targets: ?LocalLinkTargetSource,
};
const BodyLinkQuoteDomain = struct {
    map: *const QuoteSourceMap,
    parent: ?*const BodyLinkQuoteDomain,
};

fn bodyLinkContinuationOriginal(parent: BodyLinkContinuationParent) ?[]const u8 {
    if (!ordinaryNormalizationRange(parent.source, parent.opening, parent.end) or
        parent.source.lost_missing_range or parent.target.len == 0 or
        parent.label_start <= parent.opening + 2 or parent.label_end < parent.label_start or parent.label_end > parent.end or
        parent.end - parent.label_end != 2) return null;
    const original = parent.source.bytes[parent.opening..parent.end];
    if (!starts(original, "[[") or !std.mem.endsWith(u8, original, "]]") or
        parent.source.bytes[parent.label_start - 1] != '|') return null;
    var iterator: ir.InlineIterator = .{ .input = original, .renderer_boundaries = true };
    const token = iterator.next() orelse return null;
    if (token.kind != .link or !token.link_has_pipe or token.link_empty_label or
        token.link_label_restored_close or token.trail.len != 0 or iterator.cursor != original.len or
        token.text.ptr != parent.source.bytes[parent.label_start..].ptr or
        token.text.len != parent.label_end - parent.label_start) return null;
    return original;
}

fn bodyLinkContinuationAt(items: []const BodyLinkContinuationParent, at: usize) ?BodyLinkContinuationParent {
    var lo: usize = 0;
    var hi = items.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (items[mid].opening < at) lo = mid + 1 else hi = mid;
    }
    return if (lo < items.len and items[lo].opening == at) items[lo] else null;
}

// The first body implementation admits no independent wiki/quote domain in
// the crossing label. HTML tokens still go through the maintained normalizer.
fn bodyLinkContinuationLabel(input: []const u8) bool {
    var at: usize = 0;
    var close = false;
    var opened: usize = 0;
    while (at < input.len) {
        if (input[at] == '<') {
            const tag = syntax.tagAt(input, at) orelse return false;
            if (!tag.is("div") or tag.self_closing or !Renderer.formattingAngleAttributesBalanced(tag.attrs) or
                (tag.closing and trim(tag.attrs).len != 0)) return false;
            if (tag.closing) {
                if (opened == 0) close = true else opened -= 1;
            } else {
                if (opened == max_depth) return false;
                opened += 1;
            }
            at = tag.end;
            continue;
        }
        if (std.mem.indexOfScalar(u8, "[]{}'", input[at]) != null) return false;
        if (at == 0 or input[at - 1] == '\n') {
            var next = at;
            while (next < input.len and (input[next] == ' ' or input[next] == '\t' or input[next] == '\r')) : (next += 1) {}
            if (next < input.len and std.mem.indexOfScalar(u8, "*#;:=|!", input[next]) != null) return false;
        }
        at += 1;
    }
    return close and opened == 0;
}

// Recognition is earned once from the complete ordinary source token. The
// immutable borrowed proof survives only within one normalization/emission call.
const ReopenedExternalParent = struct {
    source: MissingText,
    start: usize,
    end: usize,
    target: []const u8,
    fn init(source: MissingText, start: usize, end: usize, target: []const u8) ?ReopenedExternalParent {
        if (!ordinaryNormalizationRange(source, start, end) or
            !ir.bracketedAngleProtocolTarget(source.bytes[start..end], target)) return null;
        return .{ .source = source, .start = start, .end = end, .target = target };
    }
    fn borrowedOriginal(self: ReopenedExternalParent) ?[]const u8 {
        if (!ordinaryNormalizationRange(self.source, self.start, self.end)) return null;
        const original = self.source.bytes[self.start..self.end];
        if (original.len < 3 or original[0] != '[' or original[original.len - 1] != ']' or
            self.target.len == 0 or self.target.len >= original.len - 1 or
            self.target.ptr != original[1..].ptr) return null;
        return original;
    }
};
const ReopenedExternalLink = struct {
    start: usize,
    label_start: usize,
    end: usize,
    parent: ReopenedExternalParent,
    fn lessThan(_: void, lhs: ReopenedExternalLink, rhs: ReopenedExternalLink) bool {
        return lhs.start < rhs.start;
    }
};
const ReopenedExternalDomain = struct {
    source: []const u8,
    // Sorted once after normalization, before this immutable domain is exposed.
    links: []const ReopenedExternalLink,
    parent: ?*const ReopenedExternalDomain,
};
fn reopenedExternalLowerBound(links: []const ReopenedExternalLink, at: usize) usize {
    var first: usize = 0;
    var last = links.len;
    while (first < last) {
        const middle = first + (last - first) / 2;
        if (links[middle].start < at) first = middle + 1 else last = middle;
    }
    return first;
}
fn ordinaryNormalizationRange(source: MissingText, start: usize, end: usize) bool {
    if (source.unknown or start >= end or end > source.bytes.len) return false;
    for (source.ranges) |range| if (range.start < end and range.end > start) return false;
    for (source.literal_curly_ranges) |range| if (range.start < end and range.end > start) return false;
    for (source.generated_links) |range| if (range.start < end and range.end > start) return false;
    return true;
}
fn recordReopenedExternal(a: A, links: ?*std.ArrayList(ReopenedExternalLink), frame: HtmlNormalizationFrame, end: usize) Error!void {
    const sink = links orelse return;
    const parent = frame.angle_parent orelse return;
    if (!frame.repair_generated) return;
    try sink.append(a, .{ .start = frame.output_start, .label_start = frame.label_output_start, .end = end, .parent = parent });
}

const HtmlNormalizationFrame = struct {
    name: []const u8,
    opener: []const u8,
    formatting: bool,
    external_close_at: ?usize = null,
    label_output_start: usize = 0,
    repair_generated: bool = false,
    output_start: usize = 0,
    angle_parent: ?ReopenedExternalParent = null,
    body_link_parent: ?BodyLinkContinuationParent = null,
};
const HtmlNormalizationToken = struct { frame: HtmlNormalizationFrame, closing: bool, end: usize };
const max_html_normalization_frames = max_depth * 4;

// External links are parsed after quotes upstream. Their brackets therefore
// participate in formatting repair, while authored HTML anchors remain literal.
fn htmlNormalizationToken(input: []const u8, at: usize, recognize_external_links: bool) ?HtmlNormalizationToken {
    if (recognize_external_links and input[at] == ']') return .{ .frame = .{ .name = "!external", .opener = "", .formatting = true }, .closing = true, .end = at + 1 };
    if (recognize_external_links and input[at] == '[') {
        if (at + 1 >= input.len or input[at + 1] == '[' or !ir.hasExternalProtocol(input[at + 1 ..])) return null;
        var iterator: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
        const token = iterator.next() orelse return null;
        if (token.kind != .external_link) return null;
        const target_end = @intFromPtr(token.target.ptr) - @intFromPtr(input.ptr) + token.target.len;
        return .{ .frame = .{ .name = "!external", .opener = input[at..target_end], .formatting = true, .external_close_at = at + iterator.cursor - 1 }, .closing = false, .end = target_end };
    }
    const tag = syntax.tagAt(input, at) orelse return null;
    if (!normalizableHtmlTag(tag.name) or tag.self_closing) return null;
    return .{ .frame = .{ .name = tag.name, .opener = input[at..tag.end], .formatting = adoptionFormattingTag(tag.name) }, .closing = tag.closing, .end = tag.end };
}
fn htmlNormalizationMatch(frames: []const HtmlNormalizationFrame, token: HtmlNormalizationToken, at: usize) ?usize {
    var index = frames.len;
    while (index != 0) {
        index -= 1;
        if (std.ascii.eqlIgnoreCase(frames[index].name, token.frame.name)) {
            if (frames[index].body_link_parent) |parent| if (parent.label_end != at) continue;
            if (frames[index].external_close_at) |close_at| {
                if (close_at != at) continue;
            }
            return index;
        }
    }
    return null;
}
fn hasMisnestedHtml(input: []const u8, depth: usize, recognize_external_links: bool) bool {
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    if (depth >= max_depth) return false;
    const boundaries = QuoteBoundaries.init(input);
    if (std.mem.indexOfScalar(u8, input, '<') == null) return false;
    var frames: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
    var frame_count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfAnyPos(u8, input, pos, "<[]")) |at| {
        if (input[at] == '<') if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            pos = end;
            continue;
        };
        if (starts(input[at..], "[[") and !ir.doubleOpeningExternalToken(input, at)) {
            if (boundaries.canClose(input, at)) if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                const inner = input[at + 2 .. pair.inner_end];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    if (hasMisnestedHtml(inner[pipe + 1 ..], depth + 1, false)) return true;
                }
                pos = pair.end;
                continue;
            };
            pos = at + 2;
            continue;
        }
        if (input[at] == '<') if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (!normalizableHtmlTag(tag.name) or tag.self_closing) {
                pos = tag.end;
                continue;
            }
        };
        const token = htmlNormalizationToken(input, at, recognize_external_links) orelse {
            pos = at + 1;
            continue;
        };
        pos = token.end;
        if (!token.closing) {
            if (frame_count == frames.len) return false;
            frames[frame_count] = token.frame;
            frame_count += 1;
        } else if (htmlNormalizationMatch(frames[0..frame_count], token, at)) |index| {
            if (index + 1 != frame_count) return true;
            frame_count = index;
        }
    }
    return false;
}
fn appendHtmlFrameClose(a: A, out: *std.ArrayList(u8), frame: HtmlNormalizationFrame) Error!void {
    if (frame.external_close_at != null) {
        // Only an empty repair-generated fragment needs a transparent label.
        if (std.mem.trim(u8, out.items[frame.label_output_start..], " \t\r\n").len == 0)
            try out.appendSlice(a, "<span></span>");
        return out.append(a, ']');
    }
    try out.appendSlice(a, "</");
    try out.appendSlice(a, frame.name);
    try out.append(a, '>');
}
fn normalizeMisnestedHtml(a: A, input: []const u8) Error![]const u8 {
    return normalizeMisnestedHtmlDepth(a, input, 0, true);
}
fn normalizeMisnestedHtmlDepth(a: A, input: []const u8, depth: usize, recognize_external_links: bool) Error![]const u8 {
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    if (!hasMisnestedHtml(input, depth, recognize_external_links)) return input;
    const boundaries = QuoteBoundaries.init(input);
    var out: std.ArrayList(u8) = .empty;
    var frames: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
    var frame_count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfAnyPos(u8, input, pos, "<[]")) |at| {
        try out.appendSlice(a, input[pos..at]);
        if (input[at] == '<') if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            try out.appendSlice(a, input[at..end]);
            pos = end;
            continue;
        };
        if (starts(input[at..], "[[") and !ir.doubleOpeningExternalToken(input, at)) {
            if (boundaries.canClose(input, at)) if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                const inner = input[at + 2 .. pair.inner_end];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    try out.appendSlice(a, input[at .. at + 2 + pipe + 1]);
                    try out.appendSlice(a, try normalizeMisnestedHtmlDepth(a, inner[pipe + 1 ..], depth + 1, false));
                    try out.appendSlice(a, "]]");
                } else try out.appendSlice(a, input[at..pair.end]);
                pos = pair.end;
                continue;
            };
            try out.appendSlice(a, input[at .. at + 2]);
            pos = at + 2;
            continue;
        }
        if (input[at] == '<') if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (!normalizableHtmlTag(tag.name) or tag.self_closing) {
                try out.appendSlice(a, input[at..tag.end]);
                pos = tag.end;
                continue;
            }
        };
        const token = htmlNormalizationToken(input, at, recognize_external_links) orelse {
            try out.append(a, input[at]);
            pos = at + 1;
            continue;
        };
        const raw = input[at..token.end];
        if (!token.closing) {
            try out.appendSlice(a, raw);
            if (frame_count == frames.len) return input;
            var frame = token.frame;
            if (frame.external_close_at != null) frame.label_output_start = out.items.len;
            frames[frame_count] = frame;
            frame_count += 1;
            pos = token.end;
            continue;
        }
        const index = htmlNormalizationMatch(frames[0..frame_count], token, at) orelse {
            try out.appendSlice(a, raw);
            pos = token.end;
            continue;
        };
        const above = frames[index + 1 .. frame_count];
        var close_index = above.len;
        while (close_index != 0) {
            close_index -= 1;
            try appendHtmlFrameClose(a, &out, above[close_index]);
        }
        const closed = frames[index];
        if (closed.external_close_at != null and closed.repair_generated and
            std.mem.trim(u8, out.items[closed.label_output_start..], " \t\r\n").len == 0)
            try out.appendSlice(a, "<span></span>");
        try out.appendSlice(a, raw);
        var retained: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
        var retained_len: usize = 0;
        for (above) |frame| if (frame.formatting) {
            retained[retained_len] = frame;
            retained_len += 1;
        };
        frame_count = index;
        for (retained[0..retained_len]) |frame| {
            try out.appendSlice(a, frame.opener);
            var reopened = frame;
            if (frame.external_close_at != null) {
                try out.append(a, ' ');
                reopened.label_output_start = out.items.len;
                reopened.repair_generated = true;
            }
            frames[frame_count] = reopened;
            frame_count += 1;
        }
        pos = token.end;
    }
    try out.appendSlice(a, input[pos..]);
    return out.toOwnedSlice(a);
}

fn appendHtmlFrameCloseMissing(a: A, out: *missing_dependency.Builder, frame: HtmlNormalizationFrame, links: ?*std.ArrayList(ReopenedExternalLink)) Error!void {
    if (frame.external_close_at != null) {
        if (std.mem.trim(u8, out.bytes.items[frame.label_output_start..], " \t\r\n").len == 0)
            try out.append(a, MissingText.untracked("<span></span>"));
        try out.append(a, MissingText.untracked("]"));
        return recordReopenedExternal(a, links, frame, out.bytes.items.len);
    }
    try out.append(a, MissingText.untracked("</"));
    try out.append(a, MissingText.untracked(frame.name));
    try out.append(a, MissingText.untracked(">"));
}
fn normalizeMisnestedHtmlWithMissing(a: A, source: MissingText, depth: usize, recognize_external_links: bool) Error!MissingText {
    return normalizeMisnestedHtmlWithReopened(a, source, depth, recognize_external_links, null);
}
fn normalizeMisnestedHtmlWithReopened(a: A, source: MissingText, depth: usize, recognize_external_links: bool, links: ?*std.ArrayList(ReopenedExternalLink)) Error!MissingText {
    return normalizeMisnestedHtmlWithBodyLinks(a, source, depth, recognize_external_links, links, null);
}
const BodyLinkNormalization = struct {
    parents: []const BodyLinkContinuationParent,
    output: *std.ArrayList(BodyLinkContinuation),
    copies: *QuoteSourceMap,
};
fn bodyLinkNormalizationToken(input: []const u8, at: usize, ordinary: bool, mode: ?BodyLinkNormalization) ?HtmlNormalizationToken {
    if (mode) |selected| {
        if (bodyLinkContinuationAt(selected.parents, at)) |parent| {
            if (bodyLinkContinuationOriginal(parent) == null or parent.source.bytes.ptr != input.ptr or parent.source.bytes.len != input.len) return null;
            return .{ .frame = .{ .name = "!body-link", .opener = input[at..parent.label_start],
                .formatting = true, .body_link_parent = parent }, .closing = false, .end = parent.label_start };
        }
        if (starts(input[at..], "]]")) return .{ .frame = .{ .name = "!body-link", .opener = "", .formatting = true },
            .closing = true, .end = at + 2 };
    }
    return htmlNormalizationToken(input, at, ordinary);
}
fn recordBodyLinkContinuation(a: A, mode: ?BodyLinkNormalization, frame: HtmlNormalizationFrame, label_end: usize, end: usize) Error!void {
    const selected = mode orelse return;
    const parent = frame.body_link_parent orelse return;
    if (bodyLinkContinuationOriginal(parent) == null) return error.InvalidPreContext;
    if (selected.output.items.len >= max_nodes) return error.RenderLimit;
    try selected.output.append(a, .{ .start = frame.output_start, .label_start = frame.label_output_start,
        .label_end = label_end, .end = end, .parent = parent });
}
fn closeBodyLinkContinuation(a: A, out: *missing_dependency.Builder, frame: HtmlNormalizationFrame, mode: ?BodyLinkNormalization) Error!bool {
    if (frame.body_link_parent == null) return false;
    if (std.mem.trim(u8, out.bytes.items[frame.label_output_start..], " \t\r\n").len == 0)
        try out.append(a, MissingText.untracked("<span></span>"));
    const label_end = out.bytes.items.len;
    try out.append(a, MissingText.untracked("]]"));
    try recordBodyLinkContinuation(a, mode, frame, label_end, out.bytes.items.len);
    return true;
}

fn normalizeMisnestedHtmlWithBodyLinks(a: A, source: MissingText, depth: usize, recognize_external_links: bool, links: ?*std.ArrayList(ReopenedExternalLink), body_links: ?BodyLinkNormalization) Error!MissingText {
    return normalizeMisnestedHtmlWithBodyLinksAndCopies(a, source, depth, recognize_external_links, links, body_links, null);
}
fn normalizeMisnestedHtmlWithBodyLinksAndCopies(a: A, source: MissingText, depth: usize, recognize_external_links: bool, links: ?*std.ArrayList(ReopenedExternalLink), body_links: ?BodyLinkNormalization, extra_copies: ?*QuoteSourceMap) Error!MissingText {
    const input = source.bytes;
    const copy_map = if (body_links) |mode| mode.copies else extra_copies;
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    if (body_links == null and !hasMisnestedHtml(input, depth, recognize_external_links)) {
        if (extra_copies) |map| {
            try map.appendCopy(a, 0, 0, input.len);
            map.output = input;
        }
        return source;
    }
    var body_repaired = false;
    const boundaries = QuoteBoundaries.init(input);
    var out: missing_dependency.Builder = .{};
    var frames: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
    var frame_count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfAnyPos(u8, input, pos, "<[]")) |at| {
        try appendQuoteSourceCopy(a, &out, copy_map, source, pos, at);
        if (input[at] == '<') if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
            try appendQuoteSourceCopy(a, &out, copy_map, source, at, end);
            pos = end;
            continue;
        };
        if (starts(input[at..], "[[") and !ir.doubleOpeningExternalToken(input, at) and
            (if (body_links) |mode| bodyLinkContinuationAt(mode.parents, at) == null else true)) {
            if (boundaries.canClose(input, at)) if (syntax.balancedWithOpaqueScan(input, at, &opaque_scan)) |pair| {
                if (body_links != null) {
                    try appendQuoteSourceCopy(a, &out, copy_map, source, at, pair.end);
                    pos = pair.end;
                    continue;
                }
                const inner = input[at + 2 .. pair.inner_end];
                if (syntax.delimiter(inner, "|", 0)) |pipe| {
                    try appendQuoteSourceCopy(a, &out, copy_map, source, at, at + 2 + pipe + 1);
                    try out.append(a, try normalizeMisnestedHtmlWithMissing(a, try missing_dependency.slice(a, source, at + 2 + pipe + 1, pair.inner_end), depth + 1, false));
                    try appendQuoteSourceCopy(a, &out, copy_map, source, pair.inner_end, pair.end);
                } else try appendQuoteSourceCopy(a, &out, copy_map, source, at, pair.end);
                pos = pair.end;
                continue;
            };
            try appendQuoteSourceCopy(a, &out, copy_map, source, at, at + 2);
            pos = at + 2;
            continue;
        }
        if (input[at] == '<') if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
            if (!normalizableHtmlTag(tag.name) or tag.self_closing) {
                try appendQuoteSourceCopy(a, &out, copy_map, source, at, tag.end);
                pos = tag.end;
                continue;
            }
        };
        const token = bodyLinkNormalizationToken(input, at, recognize_external_links, body_links) orelse {
            try appendQuoteSourceCopy(a, &out, copy_map, source, at, at + 1);
            pos = at + 1;
            continue;
        };
        if (!token.closing) {
            const output_start = out.bytes.items.len;
            try appendQuoteSourceCopy(a, &out, copy_map, source, at, token.end);
            if (frame_count == frames.len) {
                if (links) |sink| sink.clearRetainingCapacity();
                if (body_links) |mode| mode.output.clearRetainingCapacity();
                return source;
            }
            var frame = token.frame;
            frame.output_start = output_start;
            if (frame.body_link_parent != null) frame.label_output_start = out.bytes.items.len;
            if (frame.external_close_at) |close_at| {
                frame.label_output_start = out.bytes.items.len;
                const target = input[at + 1 .. token.end];
                if (links != null) frame.angle_parent = ReopenedExternalParent.init(source, at, close_at + 1, target);
            }
            frames[frame_count] = frame;
            frame_count += 1;
            pos = token.end;
            continue;
        }
        const index = htmlNormalizationMatch(frames[0..frame_count], token, at) orelse {
            try appendQuoteSourceCopy(a, &out, copy_map, source, at, token.end);
            pos = token.end;
            continue;
        };
        const above = frames[index + 1 .. frame_count];
        if (body_links != null and above.len != 0) {
            var crossing_action = false;
            for (above) |frame| if (frame.body_link_parent != null) { crossing_action = true; break; };
            if (!crossing_action or !std.ascii.eqlIgnoreCase(frames[index].name, "div")) {
                body_links.?.output.clearRetainingCapacity();
                return source;
            }
            body_repaired = true;
        }
        var close_index = above.len;
        while (close_index != 0) {
            close_index -= 1;
            if (!try closeBodyLinkContinuation(a, &out, above[close_index], body_links))
                try appendHtmlFrameCloseMissing(a, &out, above[close_index], links);
        }
        const closed = frames[index];
        if (closed.external_close_at != null and closed.repair_generated and
            std.mem.trim(u8, out.bytes.items[closed.label_output_start..], " \t\r\n").len == 0)
            try out.append(a, MissingText.untracked("<span></span>"));
        if (closed.body_link_parent != null and closed.repair_generated and
            std.mem.trim(u8, out.bytes.items[closed.label_output_start..], " \t\r\n").len == 0)
            try out.append(a, MissingText.untracked("<span></span>"));
        const body_label_end = out.bytes.items.len;
        try appendQuoteSourceCopy(a, &out, copy_map, source, at, token.end);
        if (closed.body_link_parent != null and closed.repair_generated)
            try recordBodyLinkContinuation(a, body_links, closed, body_label_end, out.bytes.items.len);
        if (closed.external_close_at != null) try recordReopenedExternal(a, links, closed, out.bytes.items.len);
        var retained: [max_html_normalization_frames]HtmlNormalizationFrame = undefined;
        var retained_len: usize = 0;
        for (above) |frame| if (frame.formatting) {
            retained[retained_len] = frame;
            retained_len += 1;
        };
        frame_count = index;
        for (retained[0..retained_len]) |frame| {
            const output_start = out.bytes.items.len;
            try out.append(a, try missingSlice(a, source, frame.opener));
            var reopened = frame;
            reopened.output_start = output_start;
            if (frame.body_link_parent != null) {
                reopened.label_output_start = out.bytes.items.len;
                reopened.repair_generated = true;
            }
            if (frame.external_close_at != null) {
                try out.append(a, MissingText.untracked(" "));
                reopened.label_output_start = out.bytes.items.len;
                reopened.repair_generated = true;
            }
            frames[frame_count] = reopened;
            frame_count += 1;
        }
        pos = token.end;
    }
    try appendQuoteSourceCopy(a, &out, copy_map, source, pos, input.len);
    if (body_links) |mode| {
        if (!body_repaired) { mode.output.clearRetainingCapacity(); return source; }
        std.mem.sort(BodyLinkContinuation, mode.output.items, {}, struct {
            fn lessThan(_: void, x: BodyLinkContinuation, y: BodyLinkContinuation) bool { return x.start < y.start; }
        }.lessThan);
    }
    if (links) |sink| std.mem.sort(ReopenedExternalLink, sink.items, {}, ReopenedExternalLink.lessThan);
    const result = try out.finish(a);
    if (extra_copies) |map| map.output = result.bytes;
    return result;
}
inline fn referenceStringEqual(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    if (a.len == 0) return true;
    if (a.len < 4) {
        const middle = a.len / 2;
        return ((a[0] ^ b[0]) | (a[a.len - 1] ^ b[b.len - 1]) | (a[middle] ^ b[middle])) == 0;
    }
    if (a.len <= 8) {
        return std.mem.readInt(u32, a[0..4], .little) == std.mem.readInt(u32, b[0..4], .little) and
            std.mem.readInt(u32, a[a.len - 4 ..][0..4], .little) == std.mem.readInt(u32, b[b.len - 4 ..][0..4], .little);
    }
    if (a.len <= 16) {
        return std.mem.readInt(u64, a[0..8], .little) == std.mem.readInt(u64, b[0..8], .little) and
            std.mem.readInt(u64, a[a.len - 8 ..][0..8], .little) == std.mem.readInt(u64, b[b.len - 8 ..][0..8], .little);
    }
    return std.mem.eql(u8, a, b);
}

fn pipeTrickLabel(target: []const u8) []const u8 {
    // MediaWiki's pre-save pipe trick is intentionally syntactic: the first
    // colon prefix is removed even when it is not a registered namespace. It
    // does not apply to section/anchor links.
    if (std.mem.indexOfScalar(u8, target, '#') != null) return target;
    var label = target;
    if (std.mem.indexOfScalar(u8, label, ':')) |colon| label = std.mem.trimStart(u8, label[colon + 1 ..], " \t");
    if (label.len != 0 and label[label.len - 1] == ')') {
        if (std.mem.lastIndexOf(u8, label, " (")) |paren| label = label[0..paren];
    } else if (std.mem.indexOf(u8, label, ", ")) |comma| {
        label = label[0..comma];
    }
    return label;
}

// Action destinations are semantic data, never a deferred template input.
// Inspect decoded targets only; percent-encoded braces and single braces stay literal.
pub fn unresolvedActionTarget(target: []const u8) bool {
    return std.mem.indexOf(u8, target, "{{") != null or std.mem.indexOf(u8, target, "}}") != null;
}

// Closing braces alone are literal URL characters in MediaWiki. Opening
// template markers remain forbidden, and non-URL action targets stay strict.
pub fn unresolvedExternalActionTarget(target: []const u8) bool {
    return std.mem.indexOf(u8, target, "{{") != null or
        (std.mem.indexOf(u8, target, "}}") != null and !safeUrl(target));
}

pub fn safeUrl(url: []const u8) bool {
    if (!ir.validExternalUrl(url)) return false;
    for (url) |ch| if (ch <= 32 or ch == 127) return false;
    return true;
}

const MagicLinkKind = enum { rfc, pmid, isbn };
const MagicLink = struct {
    kind: MagicLinkKind,
    end: usize,
    text: []const u8,
    payload: []const u8,
};

fn magicSpace(ch: u8) bool {
    return ch == ' ' or ch == '\t';
}

// MediaWiki Parser::SPACE_NOT_NL, on authored source. Do not decode arbitrary
// entities here: encoded prefixes and double-encoded spaces remain literal.
fn isbnSpaceLen(input: []const u8) usize {
    if (input.len == 0) return 0;
    if (magicSpace(input[0])) return 1;
    if (std.mem.startsWith(u8, input, "&nbsp;")) return 6;
    if (std.mem.startsWith(u8, input, "&#")) {
        var pos: usize = 2;
        const hex = pos < input.len and (input[pos] == 'x' or input[pos] == 'X');
        if (hex) pos += 1;
        while (pos < input.len and input[pos] == '0') : (pos += 1) {}
        if (hex) {
            if (pos + 3 <= input.len and (input[pos] == 'a' or input[pos] == 'A') and
                input[pos + 1] == '0' and input[pos + 2] == ';') return pos + 3;
        } else if (std.mem.startsWith(u8, input[pos..], "160;")) return pos + 4;
        return 0;
    }
    if (input[0] < 0x80) return 0;
    const len = std.unicode.utf8ByteSequenceLength(input[0]) catch return 0;
    if (len > input.len) return 0;
    const cp = std.unicode.utf8Decode(input[0..len]) catch return 0;
    return if (cp == 0xa0 or cp == 0x1680 or (cp >= 0x2000 and cp <= 0x200a) or
        cp == 0x202f or cp == 0x205f or cp == 0x3000) len else 0;
}

fn isbnDelimiterLen(input: []const u8) usize {
    return if (input.len != 0 and input[0] == '-') 1 else isbnSpaceLen(input);
}

// The optional second slice starts at an entity boundary in ordinary text.
// Matching this view avoids copying or decoding the unconsumed page suffix.
const MagicSource = struct {
    first: []const u8,
    tail: []const u8 = "",

    fn remaining(self: MagicSource, pos: usize) []const u8 {
        return if (pos < self.first.len) self.first[pos..] else self.tail[pos - self.first.len ..];
    }
    fn byte(self: MagicSource, pos: usize) ?u8 {
        const rest = self.remaining(pos);
        return if (rest.len == 0) null else rest[0];
    }
    fn boundaryAfter(self: MagicSource, pos: usize) bool {
        return if (pos < self.first.len)
            ir.linkBoundaryAfter(self.first, pos)
        else
            ir.linkBoundaryAfter(self.tail, pos - self.first.len);
    }
};

const MagicMatch = struct { kind: MagicLinkKind, end: usize, payload_start: usize };

fn isbnPayloadEnd(input: MagicSource, start: usize, thirteen: bool) ?usize {
    var pos = start;
    if (thirteen) {
        const rest = input.remaining(pos);
        if (!std.mem.startsWith(u8, rest, "978") and !std.mem.startsWith(u8, rest, "979")) return null;
        pos += 3;
        pos += isbnDelimiterLen(input.remaining(pos));
    }
    for (0..9) |_| {
        const ch = input.byte(pos) orelse return null;
        if (!std.ascii.isDigit(ch)) return null;
        pos += 1;
        pos += isbnDelimiterLen(input.remaining(pos));
    }
    const check = input.byte(pos) orelse return null;
    if (!std.ascii.isDigit(check) and check != 'X' and check != 'x') return null;
    pos += 1;
    return if (input.boundaryAfter(pos)) pos else null;
}

fn magicMatchAt(input: MagicSource, start: usize) ?MagicMatch {
    if (!ir.linkBoundaryBefore(input.first, start)) return null;
    const Prefix = struct { kind: MagicLinkKind, len: usize };
    const prefix: Prefix = if (std.mem.startsWith(u8, input.first[start..], "RFC"))
        .{ .kind = .rfc, .len = 3 }
    else if (std.mem.startsWith(u8, input.first[start..], "PMID"))
        .{ .kind = .pmid, .len = 4 }
    else if (std.mem.startsWith(u8, input.first[start..], "ISBN"))
        .{ .kind = .isbn, .len = 4 }
    else
        return null;

    var pos = start + prefix.len;
    const spaces_start = pos;
    while (true) {
        const rest = input.remaining(pos);
        const len = if (prefix.kind == .isbn)
            isbnSpaceLen(rest)
        else if (rest.len != 0 and magicSpace(rest[0]))
            @as(usize, 1)
        else
            0;
        if (len == 0) break;
        pos += len;
    }
    if (pos == spaces_start) return null;
    const payload_start = pos;
    if (prefix.kind == .rfc or prefix.kind == .pmid) {
        while (input.byte(pos)) |ch| {
            if (!std.ascii.isDigit(ch)) break;
            pos += 1;
        }
        if (pos == payload_start or !input.boundaryAfter(pos)) return null;
        return .{ .kind = prefix.kind, .end = pos, .payload_start = payload_start };
    }
    // The upstream optional 97[89] prefix is greedy, but may backtrack to the
    // ten-digit alternative. Each digit position allows only one delimiter.
    const end = isbnPayloadEnd(input, payload_start, true) orelse
        isbnPayloadEnd(input, payload_start, false) orelse return null;
    return .{ .kind = .isbn, .end = end, .payload_start = payload_start };
}

fn magicLinkAt(input: []const u8, start: usize) ?MagicLink {
    const matched = magicMatchAt(.{ .first = input }, start) orelse return null;
    return .{
        .kind = matched.kind,
        .end = matched.end,
        .text = input[start..matched.end],
        .payload = input[matched.payload_start..matched.end],
    };
}

fn isbnCandidateStart(value: []const u8) ?usize {
    var cursor: usize = 0;
    while (std.mem.indexOfPos(u8, value, cursor, "ISBN")) |at| {
        const after = at + 4;
        if (ir.linkBoundaryBefore(value, at) and
            (after == value.len or isbnSpaceLen(value[after..]) != 0)) return at;
        cursor = after;
    }
    return null;
}

fn magicLinkStart(input: []const u8, start: usize) ?usize {
    var pos = start;
    while (pos < input.len) {
        const relative = std.mem.indexOfAny(u8, input[pos..], "RPI") orelse return null;
        pos += relative;
        if (magicLinkAt(input, pos) != null) return pos;
        pos += 1;
    }
    return null;
}
// Strip only complete active comments before decoding title entities. Keep
// protected bodies intact. Ordinary attribute quotes do not protect comments.
fn internalTargetWithoutCommentsAlloc(a: A, value: []const u8) ![]const u8 {
    if (std.mem.indexOf(u8, value, "<!--") == null) return value;
    var result: std.ArrayList(u8) = .empty;
    errdefer result.deinit(a);
    var scan: syntax.OpaqueScan = .{};
    var cursor: usize = 0;
    var copied: usize = 0;
    var changed = false;
    while (cursor < value.len) {
        if (starts(value[cursor..], "<!--")) {
            const close = std.mem.indexOfPos(u8, value, cursor + 4, "-->") orelse break;
            try result.appendSlice(a, value[copied..cursor]);
            cursor = close + 3;
            copied = cursor;
            changed = true;
            continue;
        }
        if (scan.protectedEnd(value, cursor, null)) |end| {
            cursor = end;
            continue;
        }
        if (scan.tagAt(value, cursor, null)) |tag| {
            cursor = tag.end;
            continue;
        }
        cursor += 1;
    }
    if (!changed) {
        result.deinit(a);
        return value;
    }
    try result.appendSlice(a, value[copied..]);
    return try result.toOwnedSlice(a);
}

fn internalTargetHasNowikiRegion(target: []const u8) bool {
    var cursor: usize = 0;
    var no_more_close = false;
    while (std.mem.indexOfScalarPos(u8, target, cursor, '<')) |open| {
        if (syntax.nowikiRegionAtCached(target, open, &no_more_close) != null) return true;
        cursor = open + 1;
    }
    return false;
}

// The tokenizer normalizes target edges. Recover only authored final ASCII
// spaces for an unpiped visible label; never change the canonical target or
// treat tabs/entities/invalid title source as a newly supported label grammar.
fn unpipedLinkLabelSpaces(input: []const u8, token: ir.InlineSpan, end: usize) []const u8 {
    if (token.link_has_pipe or end > input.len or end < token.trail.len + 2) return "";
    const input_at = @intFromPtr(input.ptr);
    const target_at = @intFromPtr(token.target.ptr);
    if (target_at < input_at or target_at - input_at > input.len) return "";
    const offset = target_at - input_at;
    if (token.target.len > input.len - offset) return "";
    const first = offset + token.target.len;
    const last = end - token.trail.len - 2;
    if (first > last or !std.mem.eql(u8, input[last .. last + 2], "]]")) return "";
    const suffix = input[first..last];
    for (suffix) |ch| if (ch != ' ') return "";
    return suffix;
}

// Source syntax eligibility precedes literal invalid-title body recovery.
// Replacement characters may render there but never grant navigation authority.
fn internalTargetSyntaxAllowed(target: []const u8, comptime allow_replacement: bool) bool {
    var has_non_ascii = false;
    for (target) |ch| {
        if (ch < 32 or ch == 127 or std.mem.indexOfScalar(u8, "[]{}", ch) != null) return false;
        has_non_ascii = has_non_ascii or ch >= 128;
    }
    if (!has_non_ascii) return true;
    if (!std.unicode.utf8ValidateSlice(target)) return false;
    var view = std.unicode.Utf8View.initUnchecked(target);
    var it = view.iterator();
    while (it.nextCodepoint()) |cp| if ((cp >= 0x80 and cp <= 0x9f) or (!allow_replacement and cp == 0xfffd)) return false;
    return true;
}
// Match the renderer's earlier label-only recovery before considering a
// rejected target's complete visible body during citation preparation.
fn internalTargetHasMissingOccurrence(source: MissingText, target: []const u8) bool {
    const base = @intFromPtr(source.bytes.ptr);
    const at = @intFromPtr(target.ptr);
    if (at < base or at - base > source.bytes.len or target.len > source.bytes.len - (at - base)) return false;
    const first = at - base;
    const last = first + target.len;
    for (source.ranges) |occurrence| if (occurrence.start >= first and occurrence.end <= last) return true;
    return false;
}
fn safeInternalTarget(target: []const u8) bool {
    return internalTargetSyntaxAllowed(target, false);
}
fn internalTargetNeedsLiteralBody(target: []const u8) bool {
    return std.mem.indexOfAny(u8, target, "<>") != null or
        std.mem.indexOf(u8, target, "\u{fffd}") != null;
}
test "root-relative Container sides require the actual native owner font before normalization" {
    const a = std.testing.allocator;
    var sheet = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer sheet.deinit();
    sheet.selected_root_per_body = 0.5;
    var renderer: Renderer = .{ .a = a, .body_depth = 1, .context = .{ .title = "sample", .table_styles = &sheet } };
    const tag = syntax.tagAt("<div style='margin-top:0.4rem;padding-top:1.25rem'>", 0).?;
    const element: table_style_profile.TextElement = .{ .tag = "div" };
    const owner: Style = .{ .text_element = &element, .font_scale_basis = .normal_body, .font_scale = 2, .font_scale_set = true };
    var actual = try renderer.containerResolution(tag, .{}, owner);
    try std.testing.expect(!actual.unresolved);
    try std.testing.expectEqual(@as(f32, 0.1), actual.style.margins.?.top.value);
    try std.testing.expect(try Renderer.normalizeContainerStyleAlloc(a, &actual.style, 2));
    try std.testing.expectEqual(@as(f32, 0.2), actual.style.margins.?.top.value);
    try std.testing.expectEqual(@as(f32, 0.625), actual.style.padding.?.top.value);
    var small = owner; small.small = true;
    try std.testing.expect((try renderer.containerResolution(tag, .{}, small)).unresolved);
    renderer.pre_block = true;
    try std.testing.expect((try renderer.containerResolution(tag, .{}, .{ .text_element = &element })).unresolved);
}

test "safe internal target ASCII fast path preserves Unicode and control checks" {
    try std.testing.expect(safeInternalTarget("cat#section"));
    try std.testing.expect(safeInternalTarget("caf\xc3\xa9"));
    try std.testing.expect(safeInternalTarget("cat \xf0\x9f\x90\x88"));
    try std.testing.expect(!safeInternalTarget("cat\x7f"));
    try std.testing.expect(!safeInternalTarget("cat\xc2\x85"));
    try std.testing.expect(!safeInternalTarget("cat\xff"));
    try std.testing.expect(!safeInternalTarget("antiquit\u{fffd}"));
    try std.testing.expect(!safeInternalTarget("Good#\u{fffd}"));
    try std.testing.expect(safeInternalTarget("Tom''s"));
    try std.testing.expect(!safeInternalTarget("[[taking]]"));
    try std.testing.expect(!safeInternalTarget("{{{7}}}"));
    try std.testing.expect(!safeInternalTarget("taking#x[y]"));
}

/// The caller uses an arena for a page; returned arrays/text share its lifetime.
pub fn unclosedFragmentTraceEnabled(value: ?[]const u8) !bool {
    const raw = value orelse return false;
    if (std.mem.eql(u8, raw, "0")) return false;
    if (std.mem.eql(u8, raw, "1")) return true;
    return error.InvalidUnclosedFragmentTrace;
}
pub fn tableViewportTraceEnabled(value: ?[]const u8) !bool {
    const raw = value orelse return false;
    if (std.mem.eql(u8, raw, "0")) return false;
    if (std.mem.eql(u8, raw, "1")) return true;
    return error.InvalidTableViewportTrace;
}
fn boundedTraceHex(buffer: []u8, bytes: []const u8) []const u8 {
    const count = @min(bytes.len, buffer.len / 2);
    const digits = "0123456789abcdef";
    for (bytes[0..count], 0..) |byte, i| {
        buffer[2 * i] = digits[byte >> 4];
        buffer[2 * i + 1] = digits[byte & 15];
    }
    return buffer[0 .. count * 2];
}

/// Preserve only the first active page-body TOC boundary before owner regrouping.
/// Returns input when unchanged; otherwise the caller owns the allocated slice.
/// Reference/list bodies retain the existing deferred-reference policy, not Cite parity.
// Resolve this before behavior-switch removal and before language-owner slicing.
// Unknown capture state is distinct from an explicit page-global suppression.
pub fn pageContentConversion(a: A, input: []const u8, context: Context) Error!?bool {
    if (context.content_conversion) |enabled| return enabled;
    const namespaces = context.namespace_catalog orelse return null;
    _ = namespaces.language_conversion orelse return null;
    const registry = context.behavior_switches orelse return null;
    var scan: usize = 0;
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    while (scan < input.len) {
        if (input[scan] == '<') {
            const tag = opaque_scan.tagAt(input, scan, &no_more_nowiki_close);
            if (opaque_scan.protectedEnd(input, scan, &no_more_nowiki_close)) |end| {
                scan = end;
                continue;
            }
            if (tag) |opening| {
                scan = if (opening.is("includeonly") and !opening.closing and !opening.self_closing)
                    if (syntax.matchingTag(input, opening)) |pair| pair.end else input.len
                else
                    opening.end;
                continue;
            }
        }
        if (try registry.noContentConvertMatchAt(a, input, scan)) |end| {
            if ((try registry.matchAt(a, input, scan)) == end) return false;
        }
        scan += 1;
    }
    return true;
}

pub fn preparePageTocSourceAlloc(a: A, input: []const u8, registry: ?*const @import("namespace_registry").behavior_switches.Registry) Error![]const u8 {
    return (try preparePageTocSourceWithMissingAlloc(a, MissingText.untracked(input), registry)).bytes;
}
pub fn preparePageTocSourceWithMissingAlloc(a: A, source: MissingText, registry: ?*const @import("namespace_registry").behavior_switches.Registry) Error!MissingText {
    const input = source.bytes;
    var out: missing_dependency.Builder = .{};
    errdefer out.deinit(a);
    var emitted: usize = 0;
    var scan: usize = 0;
    var first_toc = false;
    // Track the copied output line once, so TOC elision cannot create or
    // extend an earlier-phase horizontal-rule prefix.
    var hyphen_line = true;
    var no_more_nowiki_close = false;
    var opaque_scan: syntax.OpaqueScan = .{};
    while (scan < input.len) {
        if (input[scan] == '<') {
            const tag = opaque_scan.tagAt(input, scan, &no_more_nowiki_close);
            if (opaque_scan.protectedEnd(input, scan, &no_more_nowiki_close)) |end| {
                scan = end;
                continue;
            }
            if (tag) |opening| {
                // Hidden includeonly bodies cannot consume the page's first TOC.
                // Match the renderer's complete, self-closing and unclosed scopes.
                scan = if (opening.is("includeonly") and !opening.closing and !opening.self_closing)
                    if (syntax.matchingTag(input, opening)) |pair| pair.end else input.len
                else
                    opening.end;
                continue;
            }
        }
        const matched = if (registry) |captured| try captured.matchAt(a, input, scan) else syntax.behaviorSwitchEnd(input, scan);
        if (matched) |end| {
            const toc_end = if (registry) |captured| try captured.tocMatchAt(a, input, scan) else if (std.ascii.eqlIgnoreCase(input[scan..end], "__TOC__")) end else null;
            if (toc_end != null and toc_end.? == end) {
                if (first_toc) {
                    const copied = input[emitted..scan];
                    try out.appendSlice(a, source, emitted, scan);
                    for (copied) |ch| {
                        if (ch == '\n') hyphen_line = true else if (ch != '-') hyphen_line = false;
                    }
                    emitted = end;
                    if (hyphen_line and end < input.len and input[end] == '-') {
                        // Preserve this existing suffix byte without joining it
                        // to an authored hyphen run across the removed control.
                        try out.append(a, missingEdit(source, end, end + 1, "&#45;"));
                        emitted = end + 1;
                        hyphen_line = false;
                    }
                } else first_toc = true;
            }
            scan = @max(end, emitted);
        } else scan += 1;
    }
    if (emitted == 0) return source;
    try out.appendSlice(a, source, emitted, input.len);
    return try out.finish(a);
}

// Build-only preparation. Numeric labels are resolved before language-owner
// regrouping, while the original Poem transport and its authenticated items stay
// immutable. All returned strings/overlays belong to the supplied page allocator.
const MissingBuffer = struct {
    builder: missing_dependency.Builder = .{},
    items: []const u8 = &.{},
    const empty: @This() = .{};
    fn append(self: *@This(), a: A, byte: u8) Error!void {
        try self.builder.append(a, MissingText.untracked(&.{byte}));
        self.items = self.builder.bytes.items;
    }
    fn appendCopied(self: *@This(), a: A, parent: MissingText, bytes: []const u8) Error!void {
        try self.builder.append(a, try missingSlice(a, parent, bytes));
        self.items = if (self.builder.bytes.items.len == 0 and bytes.len == 0 and Renderer.wikiClassContains(parent.bytes, bytes))
            bytes else self.builder.bytes.items;
    }
    fn view(self: *const @This()) MissingText {
        return .{ .bytes = self.items, .ranges = self.builder.ranges.items, .literal_curly_ranges = self.builder.literal_curly_ranges.items, .generated_links = self.builder.generated_links.items, .generated_source = if (self.builder.generated_links.items.len == 0) null else self.items, .unknown = self.builder.unknown, .lost_missing_range = self.builder.lost_missing_range };
    }
    fn take(self: *@This(), a: A) Error!MissingText {
        const value = try self.builder.finish(a);
        self.* = .empty;
        return value;
    }
    fn deinit(self: *@This(), a: A) void {
        self.builder.deinit(a);
        self.* = .empty;
    }
};

// Issued only by the existing complete-root numbering pass when its sole
// changes are validated ordinary numeric labels, never arbitrary replacements.
// This transition conveys structural continuity only to an observed heading-root
// article fragment's directly dispatched wiki table. It carries no class census.
pub const InlineBoxTableTransition = struct { original: []const u8, prepared: []const u8 };
pub const ClassScopeSourceTransition = struct { original: []const u8, prepared: []const u8 };
// Coordinates issued by the page preparation operation, not DOM authority.
// The ranges and their backing source live in the supplied page allocator.
fn nativeClassAttributeNameByte(byte: u8) bool { return std.ascii.isAlphanumeric(byte) or byte == '-' or byte == '_' or byte == ':'; }
fn nativeClassAdjacentQuotedAttributes(source: []const u8, start: usize) bool {
    var cursor = start;
    var count: usize = 0;
    while (cursor < source.len) {
        if (std.ascii.isWhitespace(source[cursor]) or std.mem.indexOfScalar(u8, ">/|!", source[cursor]) != null) return count != 0;
        if (count == 64) return false;
        const name = cursor;
        while (cursor < source.len and nativeClassAttributeNameByte(source[cursor])) : (cursor += 1) {}
        if (cursor == name) return false;
        while (cursor < source.len and std.ascii.isWhitespace(source[cursor])) : (cursor += 1) {}
        if (cursor == source.len or source[cursor] != '=') return false;
        cursor += 1;
        while (cursor < source.len and std.ascii.isWhitespace(source[cursor])) : (cursor += 1) {}
        if (cursor == source.len or (source[cursor] != '\'' and source[cursor] != '"')) return false;
        const quote = source[cursor];
        cursor += 1;
        while (cursor < source.len and source[cursor] != quote) : (cursor += 1) {
            if (std.mem.indexOfScalar(u8, "<>{}\x00", source[cursor]) != null) return false;
        }
        if (cursor == source.len) return false;
        cursor += 1;
        count += 1;
    }
    return count != 0;
}

fn nativeClassAppendTokens(a: A, result: *std.ArrayList(u8), classes: []const u8) !void {
    if (classes.len > 65536) return error.InvalidSourceClassInventory;
    var it = std.mem.tokenizeAny(u8, classes, " \t\r\n\x0c");
    while (it.next()) |name| {
        if (name.len > 1024) return error.InvalidSourceClassInventory;
        for (name) |byte| if (byte < 0x20 or byte == 0x7f) return error.InvalidSourceClassInventory;
        if (table_style_profile.Profile.hasClass(result.items, name)) continue;
        if (result.items.len + name.len + 1 > 65536) return error.InvalidSourceClassInventory;
        if (result.items.len != 0) try result.append(a, ' ');
        try result.appendSlice(a, name);
    }
}

fn nativeClassDecodedAttribute(a: A, raw: []const u8) ![]const u8 {
    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(a);
    var at: usize = 0;
    while (at < raw.len) {
        if (raw[at] != '&') { try out.append(a, raw[at]); at += 1; continue; }
        const end = std.mem.indexOfScalarPos(u8, raw, at + 1, ';') orelse return error.InvalidSourceClassInventory;
        const name = raw[at + 1 .. end];
        if (name.len == 0) return error.InvalidSourceClassInventory;
        if (name[0] == '#') {
            const hex = name.len > 1 and (name[1] == 'x' or name[1] == 'X');
            const digits = name[if (hex) @as(usize, 2) else 1 ..];
            const point = std.fmt.parseInt(u21, digits, if (hex) 16 else 10) catch return error.InvalidSourceClassInventory;
            if (point == 0 or point == 0xfffd or (point >= 0xd800 and point <= 0xdfff) or point > 0x10ffff) return error.InvalidSourceClassInventory;
            var scratch: [4]u8 = undefined;
            const length = std.unicode.utf8Encode(point, &scratch) catch return error.InvalidSourceClassInventory;
            try out.appendSlice(a, scratch[0..length]);
        } else try out.appendSlice(a, entities.lookupHtmlNamedEntity(name) orelse return error.InvalidSourceClassInventory);
        at = end + 1;
    }
    if (!std.unicode.utf8ValidateSlice(out.items)) return error.InvalidSourceClassInventory;
    return out.toOwnedSlice(a);
}

pub fn appendNativeAuthoredSourceClasses(a: A, result: *std.ArrayList(u8), source: []const u8) (A.Error || error{InvalidSourceClassInventory})!void {
    return appendNativeAuthoredSourceTokens(a, result, source, .class);
}
pub fn appendNativeAuthoredSourceIds(a: A, result: *std.ArrayList(u8), source: []const u8) (A.Error || error{InvalidSourceClassInventory})!void {
    return appendNativeAuthoredSourceTokens(a, result, source, .id);
}
const NativeSourceAttribute = enum { class, id };
fn appendNativeAuthoredSourceTokens(a: A, result: *std.ArrayList(u8), source: []const u8,
    comptime attribute: NativeSourceAttribute) (A.Error || error{InvalidSourceClassInventory})!void
{
    const name = @tagName(attribute);
    if (source.len == 0 or source.len > 2 * 1024 * 1024 or !std.unicode.utf8ValidateSlice(source) or std.mem.indexOfScalar(u8, source, 0) != null) return error.InvalidSourceClassInventory;
    // Match Tag.attribute source whitespace, including vertical tab. The
    // returned HTML inventory deliberately keeps its separate HTML grammar.
    var at: usize = 0;
    var values: usize = 0;
    var value_bytes: usize = 0;
    while (at < source.len) : (at += 1) {
        if (source.len - at < name.len or !std.ascii.eqlIgnoreCase(source[at..][0..name.len], name) or
            (at != 0 and nativeClassAttributeNameByte(source[at - 1]))) continue;
        var cursor = at + name.len;
        if (cursor < source.len and nativeClassAttributeNameByte(source[cursor])) continue;
        while (cursor < source.len and std.ascii.isWhitespace(source[cursor])) : (cursor += 1) {}
        if (cursor == source.len or source[cursor] != '=') continue;
        cursor += 1;
        while (cursor < source.len and std.ascii.isWhitespace(source[cursor])) : (cursor += 1) {}
        if (cursor == source.len) return error.InvalidSourceClassInventory;
        const quoted = source[cursor] == '"' or source[cursor] == '\'';
        const quote = source[cursor];
        if (quoted) cursor += 1;
        const begin = cursor;
        if (quoted) {
            while (cursor < source.len and source[cursor] != quote) : (cursor += 1) {
                // Inclusions/manual conversion could change the class value
                // after this source boundary; no such rewrite is certified here.
                if (std.mem.indexOfScalar(u8, "<>{}", source[cursor]) != null) return error.InvalidSourceClassInventory;
            }
            if (cursor == source.len) return error.InvalidSourceClassInventory;
        } else {
            while (cursor < source.len and !std.ascii.isWhitespace(source[cursor]) and source[cursor] != '>') : (cursor += 1) {
                // A compact wiki cell separator and an HTML unquoted value
                // have different endpoints. Keep that ambiguity unresolved.
                if (std.mem.indexOfScalar(u8, "\"'`=</|!{}", source[cursor]) != null) return error.InvalidSourceClassInventory;
            }
            if (cursor == begin) return error.InvalidSourceClassInventory;
        }
        const raw = source[begin..cursor];
        values += 1;
        if (values > 8192 or raw.len > 65536 - value_bytes) return error.InvalidSourceClassInventory;
        value_bytes += raw.len;
        const decoded = try nativeClassDecodedAttribute(a, raw);
        defer a.free(decoded);
        try nativeClassAppendTokens(a, result, decoded);
        if (quoted) {
            cursor += 1;
            if (cursor < source.len and !std.ascii.isWhitespace(source[cursor]) and
                std.mem.indexOfScalar(u8, ">/|!", source[cursor]) == null and
                !nativeClassAdjacentQuotedAttributes(source, cursor)) {
                return error.InvalidSourceClassInventory;
            }
        }
        // Continue at the next source byte, including inside this candidate.
        // A false-positive quoted occurrence in text cannot hide a later real
        // wiki attribute. Conflicting nested candidates conservatively refuse.
    }
}

// Only the normal Builder issues this from its final complete prepared page.
// Renderer fragment entry points cannot manufacture whole-page authority.
pub const NativeSourceClassProof = struct {
    revision_exterior_tags: ?[]const []const u8 = null,
    source: MissingText,
    source_snapshot: []const u8,
    source_sha256: [32]u8,
    profile: *const table_style_profile.Profile,
    inventory: table_style_profile.ObservedStyleInventorySnapshot,
    classes: []const u8,
    ids: ?[]const u8,

    pub fn deinit(self: *const @This(), a: A) void {
        @constCast(&self.inventory).deinit();
        if (self.ids) |ids| a.free(ids);
        a.free(self.classes);
        a.free(self.source_snapshot);
        a.destroy(self);
    }
};
pub const NativeSourceClassRange = struct {
    proof: *const NativeSourceClassProof,
    start: usize,
    prepared: MissingText,
};
fn nativeSourceClassClean(source: MissingText) bool {
    return !source.unknown and !source.lost_missing_range and source.generated_source == null and
        source.ranges.len == 0 and source.literal_curly_ranges.len == 0 and source.generated_links.len == 0;
}
// Allocation hint only. The compact Profile.ancestor_classes catalogue covers
// TD/TH paint scopes, not ordinary text/container selectors.
fn nativeSourceClassTextSelectorHint(selector: anytype) bool {
    if (selector.necessary_ancestor_classes.len != 0 or selector.necessary_ancestor_ids.len != 0) return true;
    // Own class/ID rules also need the existing full-page negative inventory
    // when inherited direction is checked across every source layer.
    for (selector.chain) |part| {
        if (part.classes.len != 0 or part.ids.len != 0) return true;
    }
    return false;
}
fn nativeSourceClassProfileHint(profile: *const table_style_profile.Profile) bool {
    if (profile.ancestor_classes.len != 0) return true;
    for (profile.rules) |rule| if (rule.selector.necessary_ancestor_ids.len != 0) return true;
    inline for (.{ "text_rules", "block_rules" }) |field_name| {
        for (@field(profile.*, field_name)) |rule| if (nativeSourceClassTextSelectorHint(rule.selector)) return true;
    }
    for (profile.container_rules) |rule| {
        for (rule.selector.chain) |part| {
            if (part.compound.classes.len != 0 or part.compound.ids.len != 0) return true;
        }
        for (rule.selector.necessary_chain) |part| {
            if (part.compound.classes.len != 0 or part.compound.ids.len != 0) return true;
        }
        if (rule.selector.fallback) |fallback| if (nativeSourceClassTextSelectorHint(fallback)) return true;
    }
    for (profile.display_rules) |rule| if (rule.selector.necessary_ancestor_classes.len != 0) return true;
    return false;
}
const native_source_root_class_tokens = "mw-parser-output mw-content-ltr mw-content-rtl";

pub fn nativeSourceClassProofAlloc(a: A, source: MissingText, profile: *const table_style_profile.Profile) A.Error!?*const NativeSourceClassProof {
    return nativeSourceClassProofWithExteriorAlloc(a, source, profile, null);
}
pub fn nativeSourceClassProofWithExteriorAlloc(a: A, source: MissingText, profile: *const table_style_profile.Profile,
    tags: ?[]const []const u8) A.Error!?*const NativeSourceClassProof {
    if (!nativeSourceClassClean(source) or source.bytes.len == 0 or profile.reading_target != .screen or
        profile.page_style_parent != null or (tags == null and !nativeSourceClassProfileHint(profile))) return null;
    var classes: std.ArrayList(u8) = .empty;
    defer classes.deinit(a);
    appendNativeAuthoredSourceClasses(a, &classes, source.bytes) catch |failure| switch (failure) {
        error.OutOfMemory => return error.OutOfMemory, error.InvalidSourceClassInventory => return null,
    };
    // Retain both supported native root direction alternatives. These are a
    // conservative union, not an assertion that either direction was observed.
    // Generated descendant classes require the consumer's separate domain proof.
    nativeClassAppendTokens(a, &classes, native_source_root_class_tokens) catch |failure| switch (failure) {
        error.OutOfMemory => return error.OutOfMemory, error.InvalidSourceClassInventory => return null,
    };
    // The audited native ParserOutput root alternatives declare no ID. This
    // inventory is usable only in the consumer's same source-owned ordinary
    // domain; it grants no absence on generated headings, references or media.
    var ids: std.ArrayList(u8) = .empty;
    defer ids.deinit(a);
    const ids_complete = complete: {
        appendNativeAuthoredSourceIds(a, &ids, source.bytes) catch |failure| switch (failure) {
            error.OutOfMemory => return error.OutOfMemory, error.InvalidSourceClassInventory => break :complete false,
        };
        break :complete true;
    };
    var inventory = table_style_profile.ObservedStyleInventorySnapshot.init(a, profile) catch |failure| switch (failure) {
        error.OutOfMemory => return error.OutOfMemory, error.InvalidStyleProfile => return null,
    };
    errdefer inventory.deinit();
    const snapshot = try a.dupe(u8, source.bytes); errdefer a.free(snapshot);
    const names = try classes.toOwnedSlice(a); errdefer a.free(names);
    const id_names: ?[]const u8 = if (ids_complete) try ids.toOwnedSlice(a) else null;
    errdefer if (id_names) |names_value| a.free(names_value);
    const proof = try a.create(NativeSourceClassProof);
    proof.* = .{ .source = source, .source_snapshot = snapshot, .source_sha256 = undefined, .revision_exterior_tags = tags,
        .profile = profile, .inventory = inventory, .classes = names, .ids = id_names };
    std.crypto.hash.sha2.Sha256.hash(source.bytes, &proof.source_sha256, .{});
    return proof;
}
pub fn nativeSourceClassRangeCurrent(range: NativeSourceClassRange, current: MissingText, profile: ?*const table_style_profile.Profile) bool {
    const proof = range.proof;
    if (profile != proof.profile or proof.profile.page_style_parent != null or proof.profile.reading_target != .screen or
        !proof.inventory.current() or !nativeSourceClassClean(proof.source) or !nativeSourceClassClean(range.prepared) or
        !nativeSourceClassClean(current) or current.bytes.ptr != range.prepared.bytes.ptr or current.bytes.len != range.prepared.bytes.len or
        range.start > proof.source.bytes.len or current.bytes.len > proof.source.bytes.len - range.start or
        proof.source_snapshot.len != proof.source.bytes.len or proof.source_snapshot.ptr == proof.source.bytes.ptr) return false;
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(proof.source.bytes, &digest, .{});
    if (!std.mem.eql(u8, &digest, &proof.source_sha256) or !std.mem.eql(u8, proof.source.bytes, proof.source_snapshot)) return false;
    return std.mem.eql(u8, current.bytes, proof.source.bytes[range.start..][0..current.bytes.len]);
}

pub const SourceElementProjection = struct {
    pub const Copy = struct { original_start: usize, prepared_start: usize, len: usize };
    original: MissingText,
    prepared: []const u8,
    copies: []const Copy,
    // Issued only for the exact selected normal page, carried across the two
    // insertion-only preparation stages. It does not make provenance known.
    observed_source: ?ObservedTextClassScope = null,

    fn observedOriginal(self: *const @This()) ?ObservedTextClassScope {
        const selected = self.observed_source orelse return null;
        if (selected.source.ptr != self.original.bytes.ptr or selected.source.len != self.original.bytes.len) return null;
        const profile = selected.scope.page_styles orelse return null;
        if (profile.reading_target != .screen or selected.scope.page_style_root == null) return null;
        return selected;
    }
    fn ordinaryRange(self: *const @This(), source: MissingText, start: usize, end: usize) bool {
        if (!source.unknown) return ordinaryNormalizationRange(source, start, end);
        if (self.observedOriginal() == null or start >= end or end > source.bytes.len) return false;
        for (source.ranges) |range| if (range.start < end and range.end > start) return false;
        for (source.literal_curly_ranges) |range| if (range.start < end and range.end > start) return false;
        for (source.generated_links) |range| if (range.start < end and range.end > start) return false;
        return true;
    }

    pub fn originalRange(self: *const @This(), start: usize, len: usize) ?usize {
        if (start > self.prepared.len or len > self.prepared.len - start) return null;
        for (self.copies) |copy| {
            if (copy.prepared_start > self.prepared.len or copy.len > self.prepared.len - copy.prepared_start or
                copy.original_start > self.original.bytes.len or copy.len > self.original.bytes.len - copy.original_start) return null;
            if (start < copy.prepared_start or start - copy.prepared_start > copy.len or len > copy.len - (start - copy.prepared_start)) continue;
            const original_start = copy.original_start + start - copy.prepared_start;
            if (!std.mem.eql(u8, self.prepared[start..][0..len], self.original.bytes[original_start..][0..len])) return null;
            if (self.original.lost_missing_range or self.original.generated_source != null or
                !self.ordinaryRange(self.original, original_start, original_start + len)) return null;
            return original_start;
        }
        return null;
    }

    pub fn preparedRange(self: *const @This(), start: usize, len: usize) ?usize {
        if (start > self.original.bytes.len or len > self.original.bytes.len - start) return null;
        for (self.copies) |copy| {
            if (start < copy.original_start or start - copy.original_start > copy.len or len > copy.len - (start - copy.original_start)) continue;
            const prepared_start = copy.prepared_start + start - copy.original_start;
            if (self.originalRange(prepared_start, len) == start) return prepared_start;
        }
        return null;
    }

    fn compose(a: A, first: @This(), second: @This()) Error!?@This() {
        if (first.prepared.ptr != second.original.bytes.ptr or first.prepared.len != second.original.bytes.len) return null;
        if (first.observed_source) |selected| {
            const next_selected = second.observed_source orelse return null;
            if (selected.scope != next_selected.scope or selected.source.ptr != next_selected.source.ptr or
                selected.source.len != next_selected.source.len or first.observedOriginal() == null) return null;
        } else if (second.observed_source != null) return null;
        var copies: std.ArrayList(Copy) = .empty;
        errdefer copies.deinit(a);
        for (second.copies) |next| for (first.copies) |previous| {
            const start = @max(next.original_start, previous.prepared_start);
            const end = @min(next.original_start + next.len, previous.prepared_start + previous.len);
            if (start >= end) continue;
            try copies.append(a, .{ .original_start = previous.original_start + start - previous.prepared_start,
                .prepared_start = next.prepared_start + start - next.original_start, .len = end - start });
        };
        return .{ .original = first.original, .prepared = second.prepared, .copies = try copies.toOwnedSlice(a), .observed_source = first.observed_source };
    }
};

// Document binds this view only after its normal parser-output range checks.
// It cannot expose the original page's ancestor-class inventory.
pub const TableDirectionRangeBinding = struct {
    projection: *const SourceElementProjection,
    owner: MissingText,
    page_start: usize,
    fn validCoordinates(source: MissingText) bool {
        var previous: usize = 0;
        for (source.ranges) |range| {
            if (range.start < previous or range.start >= range.end or range.end > source.bytes.len or range.occurrence == 0) return false;
            previous = range.end;
        }
        return true;
    }
    // The complete selected prefix carries the same observed source scope as
    // the ordinary insertion-only projection. Unknown dependency coverage is
    // retained; each consumed range still asks that projection for ordinary bytes.
    pub fn sourceCurrent(self: @This(), selected: TableContainingDirectionSource, styles: ?*const table_style_profile.Profile) bool {
        if (self.owner.lost_missing_range or self.owner.generated_source != null or
            self.projection.original.lost_missing_range or self.projection.original.generated_source != null or
            self.projection.original.bytes.ptr != selected.source.ptr or self.projection.original.bytes.len != selected.source.len or
            !validCoordinates(self.owner) or !validCoordinates(self.projection.original)) return false;
        if (!self.owner.unknown and !self.projection.original.unknown) return true;
        if (!selected.prefix_viewport or !selected.root_only or
            self.owner.literal_curly_ranges.len != 0 or self.owner.generated_links.len != 0 or
            self.projection.original.literal_curly_ranges.len != 0 or self.projection.original.generated_links.len != 0) return false;
        const observed = self.projection.observedOriginal() orelse return false;
        const current = (selected.preflight_scope orelse return false)(selected.context, selected.source) orelse return false;
        return current.scope == observed.scope and current.source.ptr == selected.source.ptr and current.source.len == selected.source.len and
            observed.scope.page_styles == styles;
    }
    fn originalRange(self: @This(), part: []const u8) ?usize {
        const offset = std.math.sub(usize, @intFromPtr(part.ptr), @intFromPtr(self.owner.bytes.ptr)) catch return null;
        if (offset > self.owner.bytes.len or part.len > self.owner.bytes.len - offset or
            self.page_start > self.projection.prepared.len or self.owner.bytes.len > self.projection.prepared.len - self.page_start or
            self.owner.lost_missing_range or self.owner.generated_source != null or
            !validCoordinates(self.owner) or !validCoordinates(self.projection.original) or
            !self.projection.ordinaryRange(self.owner, offset, offset + part.len) or
            !std.mem.eql(u8, part, self.projection.prepared[self.page_start + offset..][0..part.len])) return null;
        return self.projection.originalRange(self.page_start + offset, part.len);
    }
};

pub const SourceElementBinding = struct {
    scope: *const table_style_profile.BoundedTextClassScope,
    projection: *const SourceElementProjection,
    owner: MissingText,
    page_start: usize,

    pub fn matchesHelpCircleOwner(binding: ?SourceElementBinding, live: []const u8, paint: table_style_profile.SourceHelpCirclePaint) bool {
        if (!Renderer.wikiClassContains(paint.source, paint.opening) or !std.mem.eql(u8, live, paint.owner_snapshot)) return false;
        const start = @intFromPtr(paint.opening.ptr) - @intFromPtr(paint.source.ptr);
        if (live.len > paint.source.len - start or !std.mem.eql(u8, paint.source[start..][0..live.len], paint.owner_snapshot)) return false;
        if (live.ptr == paint.opening.ptr) return true;
        const held = binding orelse return false;
        return held.projection.original.bytes.ptr == paint.source.ptr and held.projection.original.bytes.len == paint.source.len and
            held.originalRange(live) == start;
    }

    fn ownerOffset(self: @This(), part: []const u8) ?usize {
        const first = @intFromPtr(self.owner.bytes.ptr);
        const pointer = @intFromPtr(part.ptr);
        if (pointer < first or pointer - first > self.owner.bytes.len or part.len > self.owner.bytes.len - (pointer - first)) return null;
        const start = pointer - first;
        if (self.page_start > self.projection.prepared.len or self.owner.bytes.len > self.projection.prepared.len - self.page_start or
            !std.mem.eql(u8, part, self.projection.prepared[self.page_start + start..][0..part.len]) or
            self.owner.lost_missing_range or self.owner.generated_source != null or
            !self.projection.ordinaryRange(self.owner, start, start + part.len)) return null;
        if (self.owner.unknown) {
            const selected = self.projection.observedOriginal() orelse return null;
            if (selected.scope != self.scope) return null;
        }
        return start;
    }

    fn originalRange(self: @This(), part: []const u8) ?usize {
        const start = self.ownerOffset(part) orelse return null;
        return self.projection.originalRange(self.page_start + start, part.len);
    }

    fn ownerRange(self: @This(), original_start: usize, len: usize) ?[]const u8 {
        const prepared_start = self.projection.preparedRange(original_start, len) orelse return null;
        if (prepared_start < self.page_start or prepared_start - self.page_start > self.owner.bytes.len or
            len > self.owner.bytes.len - (prepared_start - self.page_start)) return null;
        const part = self.owner.bytes[prepared_start - self.page_start..][0..len];
        if (self.originalRange(part) != original_start) return null;
        return part;
    }
};

pub const PreparedExternalLinks = struct {
    // Cumulative generation across fresh citation passes; cached input is unknown.
    // Zero proves that the maintained producer introduced no autonumber consumer.
    generated_external_labels: ?usize = null,
    source_element_projection: ?SourceElementProjection = null,
    class_scope_transition: ?ClassScopeSourceTransition = null,
    inline_box_table_transition: ?InlineBoxTableTransition = null,
    fallbacks: @import("presentation_fallback.zig").Report = .{},
    content_conversion: ?bool = null,
    citations: ?*const CitationPlan = null,
    source: []const u8,
    missing: MissingText,
    poem_phase: ?*const PoemPhase,
};
const PageExternalNumbering = struct {
    const Phase = enum { extensions, interlanguage, media, ordinary };
    const Edit = struct { start: usize, end: usize, value: []const u8, tracked: ?MissingText = null, numbered_label_only: bool = false, citation_attribute_only: bool = false };
    a: A,
    renderer: Renderer,
    phase: ?*const PoemPhase,
    number: usize = 0,
    edits: std.ArrayList(Edit) = .empty,
    seen_references: std.ArrayList(usize) = .empty,
    seen_reference_sites: std.ArrayList(usize) = .empty,
    seen_extensions: std.ArrayList(usize) = .empty,
    seen_poem: []bool,
    citations: ?*CitationPlan = null,
    collecting_citations: bool = false,
    source_element_input: ?SourceElementProjection = null,
    root_missing: MissingText = MissingText.untracked(""),
    numbered_batches: std.ArrayList(usize) = .empty,
    tracked_domains: std.ArrayList(MissingText) = .empty,
    native_domain_depth: usize = 0,

    fn containsFolded(bytes: []const u8, needle: []const u8) bool {
        if (needle.len > bytes.len) return false;
        for (0..bytes.len - needle.len + 1) |at| if (std.ascii.eqlIgnoreCase(bytes[at..][0..needle.len], needle)) return true;
        return false;
    }
    fn citationPossible(source: []const u8) bool {
        // Entity-bearing attributes can expose tags only after their own decode.
        // Keep those conservative positives; plain no-ref pages need no collector.
        return containsFolded(source, "<ref") or std.mem.indexOfScalar(u8, source, '&') != null;
    }
    fn citationPossibleInContext(source: []const u8, context: Context) bool {
        if (citationPossible(source)) return true;
        if (context.poem_phase) |phase| for (phase.items, 0..) |item, index| {
            if (item.body) |body_value| if (citationPossible(body_value)) return true;
            if (index < phase.numbered_bodies.len) if (phase.numbered_bodies[index]) |body_value| if (citationPossible(body_value)) return true;
        };
        for (context.citation_definitions) |definition| if (citationPossible(definition.body)) return true;
        return false;
    }
    fn collisionDomains(renderer: *Renderer, domains: *std.ArrayList([]const u8), source: []const u8) Error!void {
        try domains.append(renderer.a, source);
        const controlled = try renderer.withoutBehaviorControls(source);
        try domains.append(renderer.a, controlled);
        const decoded = try renderer.entityText(controlled);
        try domains.append(renderer.a, decoded);
        // Media title destinations decode percent escapes after entity decoding.
        try domains.append(renderer.a, std.Uri.percentDecodeInPlace(try renderer.a.dupe(u8, decoded)));
        // Visible text accepts longer numeric references than attribute fields.
        var visible: std.ArrayList(u8) = .empty;
        var at: usize = 0;
        while (at < controlled.len) {
            var scratch: [4]u8 = undefined;
            if (controlled[at] == '&') if (Renderer.decodeEntity(controlled[at..], &scratch, true)) |entity_value| {
                try visible.appendSlice(renderer.a, entity_value.bytes);
                at += entity_value.consumed;
                continue;
            };
            try visible.append(renderer.a, controlled[at]);
            at += 1;
        }
        try domains.append(renderer.a, visible.items);
    }
    fn citationAttributeAlloc(a: A, root: []const u8, context: Context) Error![]const u8 {
        var scratch = std.heap.ArenaAllocator.init(a);
        defer scratch.deinit();
        var renderer: Renderer = .{ .a = scratch.allocator(), .context = context };
        var domains: std.ArrayList([]const u8) = .empty;
        try collisionDomains(&renderer, &domains, root);
        if (context.poem_phase) |phase| for (phase.items, 0..) |item, index| {
            if (item.body) |body_value| try collisionDomains(&renderer, &domains, body_value);
            if (index < phase.numbered_bodies.len) if (phase.numbered_bodies[index]) |body_value| try collisionDomains(&renderer, &domains, body_value);
        };
        for (context.citation_definitions) |definition| try collisionDomains(&renderer, &domains, definition.body);
        var serial: usize = 0;
        while (true) : (serial += 1) {
            const candidate = try std.fmt.allocPrint(a, "data-wikidict-cite-{d}", .{serial});
            var collision = false;
            for (domains.items) |domain_value| collision = collision or containsFolded(domain_value, candidate);
            if (!collision) return candidate;
            a.free(candidate);
        }
    }
    // Keep exact whole-domain identity while retaining the existing metadata
    // validation and allocation-error contract. A full copy may deliberately
    // decline excessive ordinary ranges; preserve that result rather than
    // restoring the original evidence after its limit was exceeded.
    fn wholeTrackedCitationBody(self: *@This(), source: MissingText) Error!MissingText {
        const checked = try missingSlice(self.a, source, source.bytes);
        if (checked.bytes.ptr == source.bytes.ptr) return checked;
        if (checked.unknown != source.unknown or checked.ranges.len != source.ranges.len or
            checked.literal_curly_ranges.len != source.literal_curly_ranges.len or
            checked.generated_links.len != source.generated_links.len) return checked;
        // Full-slice validation retained every channel. Only this exact parent,
        // never an equal-byte or detached value, supplies its original identity.
        self.a.free(checked.bytes);
        self.a.free(checked.ranges);
        self.a.free(checked.literal_curly_ranges);
        self.a.free(checked.generated_links);
        return source;
    }
    fn trackedCitationBody(self: *@This(), body_text: []const u8) Error!MissingText {
        // Generated projection/control domains retain their exact tracked slices.
        // Native originals have no source-range manifest and remain explicitly unknown.
        const pointer = @intFromPtr(body_text.ptr);
        var index = self.tracked_domains.items.len;
        while (index != 0) {
            index -= 1;
            const source = self.tracked_domains.items[index];
            const begin = @intFromPtr(source.bytes.ptr);
            if (pointer >= begin and pointer - begin <= source.bytes.len and body_text.len <= source.bytes.len - (pointer - begin)) {
                if (pointer == begin and body_text.len == source.bytes.len)
                    return self.wholeTrackedCitationBody(source);
                return missingSlice(self.a, source, body_text);
            }
        }
        if (body_text.ptr == self.root_missing.bytes.ptr and body_text.len == self.root_missing.bytes.len)
            return self.wholeTrackedCitationBody(self.root_missing);
        return missingSlice(self.a, self.root_missing, body_text);
    }
    // Only the selected page preparation borrows a validated clean child back
    // from missingSlice's allocation. The original pointer range, not equal
    // text, owns this identity; every tracking channel and unknown state stays.
    fn trackedCitationDomain(self: *@This(), source: []const u8) Error!MissingText {
        var tracked = try self.trackedCitationBody(source);
        if (tracked.bytes.ptr == source.ptr or !self.renderer.context.observe_source_elements or
            self.phase != null or self.renderer.context.citation_definitions.len != 0 or
            self.selectedSourceElementInput(self.root_missing) == null or
            self.root_missing.lost_missing_range or self.root_missing.generated_source != null or
            tracked.lost_missing_range or tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or
            tracked.generated_source != null or tracked.generated_links.len != 0) return tracked;
        const begin = @intFromPtr(self.root_missing.bytes.ptr);
        const at = @intFromPtr(source.ptr);
        if (at < begin or at - begin > self.root_missing.bytes.len or
            source.len > self.root_missing.bytes.len - (at - begin) or
            tracked.bytes.len != source.len or !std.mem.eql(u8, tracked.bytes, source)) return tracked;
        if (self.source_element_input) |prior|
            if (prior.originalRange(at - begin, source.len) == null) return tracked;
        self.a.free(tracked.bytes);
        tracked.bytes = source;
        return tracked;
    }
    fn capturedCitationBody(self: *@This(), body_text: []const u8) Error!MissingText {
        const value = try self.trackedCitationBody(body_text);
        var closing: usize = 0;
        var at: usize = 0;
        while (std.mem.indexOfPos(u8, body_text, at, native_poem_prefix)) |found| {
            const item = self.renderer.poemItemAt(body_text[found..]) orelse {
                at = found + native_poem_prefix.len;
                continue;
            };
            at = found + item.token.len;
            if (item.kind != .indent) continue;
            const generated_tag = syntax.tagAt(body_text, at) orelse continue;
            if (!generated_tag.is("span") or generated_tag.closing or generated_tag.self_closing) continue;
            if (syntax.matchingTag(body_text, generated_tag) == null) closing += 1;
        }
        if (closing == 0) return value;
        var out: missing_dependency.Builder = .{};
        defer out.deinit(self.a);
        try out.append(self.a, value);
        for (0..closing) |_| try out.append(self.a, MissingText.untracked("</span>"));
        return out.finish(self.a);
    }
    fn annotateCitation(self: *@This(), input: []const u8, tag: syntax.Tag, event: usize) Error!void {
        // An authored dangling assignment must not consume our generated
        // attribute as its value. Tag normalization keeps the original name
        // slice, so insert before all authored attributes without rewriting them.
        const first = @intFromPtr(input.ptr);
        const name = @intFromPtr(tag.name.ptr);
        if (tag.closing or tag.name.len == 0 or name < first or name - first > input.len or
            tag.name.len > input.len - (name - first) or tag.end > input.len) return error.InvalidPreContext;
        const end = name - first + tag.name.len;
        if (end >= tag.end) return error.InvalidPreContext;
        const attribute_text = try std.fmt.allocPrint(self.a, " {s}=\"{d}\"", .{ self.citations.?.attribute, event });
        try self.replace(input, end, end, attribute_text);
        const position = self.address(input, end);
        for (self.edits.items) |*edit| if (edit.start == position and edit.end == position and
            edit.tracked == null and std.mem.eql(u8, edit.value, attribute_text)) {
            edit.citation_attribute_only = true;
            break;
        };
    }
    fn citationEvent(self: *@This(), tag: syntax.Tag) Error!citation_state.Event {
        const plan = self.citations orelse return error.InvalidPreContext;
        const raw = tag.attr(plan.attribute) orelse return error.InvalidPreContext;
        const index = std.fmt.parseInt(usize, raw, 10) catch return error.InvalidPreContext;
        if (index >= plan.events.items.len) return error.InvalidPreContext;
        const event = plan.events.items[index];
        if (!tag.is(switch (event.tag) {
            .ref => "ref",
            .references => "references",
            .poem => "poem",
        })) return error.InvalidPreContext;
        return event;
    }
    fn citationReference(self: *@This(), input: []const u8, at: usize, tag: syntax.Tag, body_text: ?[]const u8, depth: usize) Error!void {
        const site = self.address(input, at);
        for (self.seen_reference_sites.items) |prior| if (prior == site) return;
        try self.seen_reference_sites.append(self.a, site);
        if (!self.collecting_citations) {
            const event = try self.citationEvent(tag);
            // Missing-list footers retain the established first-ref schedule.
            // Explicit footers remain attached to their references occurrence.
            if (event.item) |item_id| {
                const plan = self.citations.?;
                for (plan.final_batches.items) |batch_index| {
                    if (batch_index >= plan.batches.items.len) return error.InvalidPreContext;
                    for (plan.batches.items[batch_index].items) |id| if (id == item_id) {
                        try self.citationFooter(batch_index, depth + 1);
                        return;
                    };
                }
            }
            return;
        }
        const name = (try self.renderer.semanticAttribute(tag, "name")) orelse "";
        const group = (try self.renderer.semanticAttribute(tag, "group")) orelse "";
        const follow = (try self.renderer.semanticAttribute(tag, "follow")) orelse "";
        const body_value = if (body_text) |value| try self.capturedCitationBody(value) else null;
        const event = self.citations.?.reference(self.a, name, group, follow, body_value) catch |err| switch (err) {
            error.InvalidAuthoredCitation => try self.citations.?.invalidReference(self.a),
            else => |remaining| return remaining,
        };
        try self.annotateCitation(input, tag, event);
    }
    fn citationListDefinitions(self: *@This(), input: []const u8, default_group: []const u8, depth: usize) Error!bool {
        if (depth > max_depth) return error.RenderLimit;
        var authored_error = false;
        var scan: syntax.OpaqueScan = .{};
        var at: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, at, '<')) |open| {
            if (starts(input[open..], "<!--")) {
                at = scan.protectedEnd(input, open, null) orelse input.len;
                continue;
            }
            const tag = try self.renderer.semanticTagAt(input, open) orelse {
                at = open + 1;
                continue;
            };
            at = tag.end;
            if (tag.closing) continue;
            if (tag.is("includeonly")) {
                at = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len;
                continue;
            }
            const pair = scan.pair(input, tag) orelse continue;
            at = pair.end;
            if (!tag.is("ref")) {
                if (!tag.isOpaque() and !tag.is("includeonly")) {
                    const nested_error = try self.citationListDefinitions(input[tag.end..pair.inner_end], default_group, depth + 1);
                    authored_error = authored_error or nested_error;
                }
                continue;
            }
            if (self.citations.?.definition_events >= self.citations.?.limit) return error.RenderLimit;
            const name = (try self.renderer.semanticAttribute(tag, "name")) orelse "";
            const own_group = (try self.renderer.semanticAttribute(tag, "group")) orelse "";
            const group = if (own_group.len != 0) own_group else default_group;
            const body_value = if (tag.self_closing) null else try self.capturedCitationBody(input[tag.end..pair.inner_end]);
            const follow = (try self.renderer.semanticAttribute(tag, "follow")) orelse "";
            const validation = if (follow.len != 0)
                self.citations.?.rejectListDefinition()
            else
                self.citations.?.listDefinition(self.a, name, group, body_value);
            validation catch |err| switch (err) {
                error.InvalidAuthoredCitation => authored_error = true,
                else => |remaining| return remaining,
            };
        }
        return authored_error;
    }
    fn citationReferences(self: *@This(), input: []const u8, at: usize, tag: syntax.Tag, body_text: ?[]const u8, depth: usize) Error!void {
        const site = self.address(input, at);
        for (self.seen_reference_sites.items) |prior| if (prior == site) return;
        try self.seen_reference_sites.append(self.a, site);
        if (self.collecting_citations) {
            const group = (try self.renderer.semanticAttribute(tag, "group")) orelse "";
            const authored_error = if (body_text) |value| try self.citationListDefinitions(value, group, depth + 1) else false;
            const event = try self.citations.?.references(self.a, group);
            self.citations.?.events.items[event].authored_error = authored_error;
            try self.annotateCitation(input, tag, event);
        } else {
            const event = try self.citationEvent(tag);
            try self.citationFooter(event.batch orelse return error.InvalidPreContext, depth + 1);
        }
    }
    fn citationFooter(self: *@This(), batch_index: usize, depth: usize) Error!void {
        if (depth > max_depth) return error.RenderLimit;
        for (self.numbered_batches.items) |prior| if (prior == batch_index) return;
        try self.numbered_batches.append(self.a, batch_index);
        const plan = self.citations.?;
        if (batch_index >= plan.batches.items.len) return error.InvalidPreContext;
        const batch = plan.batches.items[batch_index];
        // Reused invalid-input recovery bodies already carry their earlier URL
        // labels. Replace only the old prefix, retaining this epoch's follow tail.
        for (batch.items) |item_id| {
            const item = &plan.items.items[item_id];
            if (item.recovery) |recovery_id| if (plan.recoveries.items[recovery_id].body) |recovered| {
                const body_value = item.body orelse return error.InvalidPreContext;
                if (item.recovery_prefix_len > body_value.bytes.len) return error.InvalidPreContext;
                var joined: missing_dependency.Builder = .{};
                defer joined.deinit(self.a);
                try joined.append(self.a, recovered);
                try joined.appendSlice(self.a, body_value, item.recovery_prefix_len, body_value.bytes.len);
                item.body = try joined.finish(self.a);
                item.recovery_prefix_len = recovered.bytes.len;
            };
        }
        // Controls are prepared once per joined body, before ANY footer phase.
        for (batch.recoveries) |id| if (plan.recoveries.items[id].body) |value| {
            plan.recoveries.items[id].body = try self.renderer.externalSourceControlsWithMissing(value);
        };
        for (batch.items) |id| if (plan.items.items[id].body) |value| {
            plan.items.items[id].body = try self.renderer.externalSourceControlsWithMissing(value);
        };
        // One parser domain across the whole footer, not one domain per item.
        // Null-ordinal unused-definition recovery retains existing product policy.
        for ([_]Phase{ .extensions, .interlanguage, .media, .ordinary }) |phase_kind| {
            for (batch.recoveries) |id| if (plan.recoveries.items[id].body) |value|
                try self.walk(value.bytes, phase_kind, true, true, depth + 1);
            for (batch.items) |id| if (plan.items.items[id].body) |value|
                try self.walk(value.bytes, phase_kind, true, true, depth + 1);
        }
        for (batch.recoveries) |id| if (plan.recoveries.items[id].body) |value| {
            plan.recoveries.items[id].body = try self.applyWithMissing(value);
        };
        for (batch.items) |id| if (plan.items.items[id].body) |value| {
            plan.items.items[id].body = try self.applyWithMissing(value);
        };
    }
    fn rawPoem(self: *@This(), input: []const u8, tag: syntax.Tag, content: []const u8, in_reference: bool, depth: usize) Error!void {
        if (self.renderer.poem_authored_token or self.renderer.poemHasUnregisteredItem(content)) return;
        if (!self.collecting_citations or self.native_domain_depth != 0) {
            if (!self.collecting_citations and tag.attr(self.citations.?.attribute) != null) _ = try self.citationEvent(tag);
            try self.domain(content, in_reference, depth + 1);
            return;
        }
        const plan = self.citations.?;
        const first_event = plan.events.items.len;
        const first_item = self.renderer.poem_items.items.len;
        const projected = try self.renderer.poemProjectionWithMissing(try self.trackedCitationBody(content));
        try self.tracked_domains.append(self.a, projected);
        try self.domain(projected.bytes, in_reference, depth + 1);
        if (plan.events.items.len == first_event) {
            // This scope contributes no citation state; preserve its original path.
            // Nested no-citation scopes likewise add no persistent registry entries.
            self.renderer.poem_items.shrinkRetainingCapacity(first_item);
            return;
        }
        for (self.renderer.poem_items.items[first_item..]) |item| {
            var found = false;
            for (plan.local_poem_items.items) |prior| if (std.mem.eql(u8, prior.token, item.token)) {
                found = true;
                break;
            };
            if (!found) try plan.local_poem_items.append(self.a, .{
                .token = item.token,
                .kind = @fromBackingInt(@intCast(@backingInt(item.kind))),
                .indent = item.indent,
                .tag = item.tag,
                .body = item.body,
            });
        }
        const event = try plan.preparedPoem(self.a);
        try self.annotateCitation(input, tag, event);
        try self.replaceTracked(content, 0, content.len, try self.applyWithMissing(projected));
    }
    fn body(self: *@This(), index: usize) []const u8 {
        const phase = self.phase.?;
        if (index < phase.numbered_bodies.len) if (phase.numbered_bodies[index]) |value| return value;
        return phase.items[index].body orelse "";
    }
    // Reference definitions borrowed by the existing Renderer can point into
    // its owned Poem copies. Translate only those exact byte ranges back to the
    // immutable phase body that will receive the corresponding preparation.
    fn address(self: *@This(), input: []const u8, offset: usize) usize {
        const pointer = @intFromPtr(input.ptr);
        if (self.phase != null and input.len != 0) for (self.renderer.poem_items.items, 0..) |item, index| {
            if (index >= self.phase.?.items.len) break;
            const begin = @intFromPtr(item.body.ptr);
            if (pointer >= begin and pointer < begin + item.body.len and input.len <= begin + item.body.len - pointer)
                return @intFromPtr(self.body(index).ptr) + pointer - begin + offset;
        };
        return pointer + offset;
    }
    fn enclosed(first: usize, last: usize, edit: Edit) bool {
        return if (edit.start == edit.end) edit.start >= first and edit.start < last else edit.start >= first and edit.end <= last;
    }
    fn replace(self: *@This(), input: []const u8, start: usize, end: usize, value: []const u8) Error!void {
        if (start > end or end > input.len or self.edits.items.len >= max_nodes) return error.RenderLimit;
        const first = self.address(input, start);
        const last = self.address(input, end);
        var index: usize = 0;
        while (index < self.edits.items.len) {
            const edit = self.edits.items[index];
            if (edit.start == first and edit.end == last) return;
            if (first != last and enclosed(first, last, edit)) {
                _ = self.edits.swapRemove(index);
                continue;
            }
            if (edit.start != edit.end and (if (first == last) first >= edit.start and first < edit.end else first < edit.end and last > edit.start))
                return error.InvalidPreContext;
            index += 1;
        }
        try self.edits.append(self.a, .{ .start = first, .end = last, .value = value });
    }
    fn replaceTracked(self: *@This(), input: []const u8, start: usize, end: usize, value: MissingText) Error!void {
        try self.replace(input, start, end, value.bytes);
        const first = self.address(input, start);
        const last = self.address(input, end);
        for (self.edits.items) |*edit| if (edit.start == first and edit.end == last) {
            edit.tracked = value;
            return;
        };
        return error.InvalidPreContext;
    }
    fn selectedSourceElementInput(self: *const @This(), original: MissingText) ?ObservedTextClassScope {
        const sizing = self.renderer.context.figure_sizing orelse return null;
        const selected = sizing.text_class_scope orelse return null;
        const profile = selected.scope.page_styles orelse return null;
        if (profile.reading_target != .screen or selected.scope.page_style_root == null) return null;
        if (selected.source.ptr == original.bytes.ptr and selected.source.len == original.bytes.len) return selected;
        // The second pass consumes only the first pass's exact allocated output.
        const prior = self.source_element_input orelse return null;
        const previous = prior.observedOriginal() orelse return null;
        if (previous.scope != selected.scope or previous.source.ptr != selected.source.ptr or
            previous.source.len != selected.source.len or prior.prepared.ptr != original.bytes.ptr or
            prior.prepared.len != original.bytes.len) return null;
        return selected;
    }
    fn sourceElementProjection(self: *const @This(), original: MissingText, source: MissingText, prepared: []const u8) Error!?SourceElementProjection {
        const observed = self.selectedSourceElementInput(original);
        if (!self.renderer.context.observe_source_elements or self.phase != null or
            self.renderer.context.citation_definitions.len != 0 or original.lost_missing_range or
            original.generated_source != null or source.lost_missing_range or source.generated_source != null or
            ((original.unknown or source.unknown) and observed == null) or
            !std.mem.eql(u8, original.bytes, source.bytes)) return null;
        const begin = @intFromPtr(source.bytes.ptr);
        const end = begin + source.bytes.len;
        var selected: std.ArrayList(Edit) = .empty;
        defer selected.deinit(self.a);
        for (self.edits.items) |edit| {
            if (!enclosed(begin, end, edit) or edit.start != edit.end or edit.tracked != null or
                (!edit.numbered_label_only and !edit.citation_attribute_only)) return null;
            try selected.append(self.a, edit);
        }
        std.mem.sort(Edit, selected.items, {}, struct {
            fn less(_: void, lhs: Edit, rhs: Edit) bool { return lhs.start < rhs.start; }
        }.less);
        var copies: std.ArrayList(SourceElementProjection.Copy) = .empty;
        defer copies.deinit(self.a);
        var original_at: usize = 0;
        var prepared_at: usize = 0;
        for (selected.items) |edit| {
            const start = edit.start - begin;
            if (start < original_at) return null;
            const len = start - original_at;
            if (prepared_at > prepared.len or len > prepared.len - prepared_at or
                !std.mem.eql(u8, source.bytes[original_at..start], prepared[prepared_at..][0..len])) return null;
            if (len != 0) try copies.append(self.a, .{ .original_start = original_at, .prepared_start = prepared_at, .len = len });
            prepared_at += len;
            if (edit.value.len > prepared.len - prepared_at or !std.mem.eql(u8, edit.value, prepared[prepared_at..][0..edit.value.len])) return null;
            prepared_at += edit.value.len;
            original_at = start;
        }
        const len = source.bytes.len - original_at;
        if (prepared_at > prepared.len or len != prepared.len - prepared_at or
            !std.mem.eql(u8, source.bytes[original_at..], prepared[prepared_at..])) return null;
        if (len != 0) try copies.append(self.a, .{ .original_start = original_at, .prepared_start = prepared_at, .len = len });
        return .{ .original = original, .prepared = prepared, .copies = try copies.toOwnedSlice(self.a), .observed_source = observed };
    }
    fn inlineBoxTableTransition(selected: []const Edit, original: MissingText, source: MissingText, prepared: []const u8) ?InlineBoxTableTransition {
        if (original.lost_missing_range or source.lost_missing_range or original.generated_source != null or
            source.generated_source != null or !std.mem.eql(u8, original.bytes, source.bytes)) return null;
        if (std.mem.indexOf(u8, source.bytes, "\n{|") == null and !std.mem.startsWith(u8, source.bytes, "{|")) return null;
        const begin = @intFromPtr(source.bytes.ptr);
        const end = begin + source.bytes.len;
        for (selected) |edit| {
            if (!enclosed(begin, end, edit)) return null;
            if (edit.tracked) |replacement| {
                // A recursively prepared caption may return a tracked copy of
                // identical text. Preserve both the bytes and every local channel.
                if (edit.start >= edit.end or edit.numbered_label_only or edit.citation_attribute_only or
                    replacement.bytes.ptr != edit.value.ptr or replacement.bytes.len != edit.value.len or
                    replacement.unknown != original.unknown or replacement.unknown != source.unknown or
                    replacement.lost_missing_range or replacement.ranges.len != 0 or replacement.literal_curly_ranges.len != 0 or
                    replacement.generated_links.len != 0 or replacement.generated_source != null) return null;
                const before = edit.start - begin;
                const after = edit.end - begin;
                const slice = source.bytes[before..after];
                if (!std.mem.eql(u8, slice, replacement.bytes) or
                    !Renderer.noLiParentSourceRange(source, slice) or
                    !Renderer.noLiParentSourceRange(original, original.bytes[before..after])) return null;
                continue;
            }
            if (edit.start != edit.end or
                edit.numbered_label_only == edit.citation_attribute_only or edit.start <= begin or edit.start >= end) return null;
            const at = edit.start - begin;
            if (!Renderer.noLiParentSourceRange(original, original.bytes[at - 1 .. at + 1]) or
                !Renderer.noLiParentSourceRange(source, source.bytes[at - 1 .. at + 1])) return null;
        }
        return .{ .original = original.bytes, .prepared = prepared };
    }
    fn classScopeTransition(self: *const @This(), original: MissingText, source: MissingText, prepared: []const u8) ?ClassScopeSourceTransition {
        if (self.collecting_citations or self.citations != null or self.phase != null or
            self.renderer.context.citation_definitions.len != 0 or !std.mem.eql(u8, original.bytes, source.bytes) or
            original.unknown or original.lost_missing_range or original.ranges.len != 0 or
            original.literal_curly_ranges.len != 0 or original.generated_links.len != 0 or source.unknown or source.lost_missing_range or
            source.ranges.len != 0 or source.literal_curly_ranges.len != 0 or source.generated_links.len != 0) return null;
        const begin = @intFromPtr(source.bytes.ptr);
        const end = begin + source.bytes.len;
        for (self.edits.items) |edit| {
            if (!enclosed(begin, end, edit) or edit.start != edit.end or !edit.numbered_label_only or edit.tracked != null) return null;
        }
        return .{ .original = original.bytes, .prepared = prepared };
    }
    fn apply(self: *@This(), input: []const u8) Error![]const u8 {
        return (try self.applyWithMissing(MissingText.untracked(input))).bytes;
    }
    const TableTransitionRequest = struct { original: MissingText, result: ?InlineBoxTableTransition = null };

    fn applyWithMissing(self: *@This(), source: MissingText) Error!MissingText {
        return self.applyWithTableTransition(source, null);
    }

    fn applyWithTableTransition(self: *@This(), source: MissingText, table: ?*TableTransitionRequest) Error!MissingText {
        const input = source.bytes;
        const begin = self.address(input, 0);
        const end = begin + input.len;
        var selected: std.ArrayList(Edit) = .empty;
        defer selected.deinit(self.a);
        for (self.edits.items) |edit| if (enclosed(begin, end, edit))
            try selected.append(self.a, edit);
        if (selected.items.len == 0) {
            if (table) |request| if (begin == @intFromPtr(input.ptr)) {
                request.result = inlineBoxTableTransition(&.{}, request.original, source, input);
            };
            return source;
        }
        std.mem.sort(Edit, selected.items, {}, struct {
            fn less(_: void, lhs: Edit, rhs: Edit) bool {
                return lhs.start < rhs.start;
            }
        }.less);
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var position: usize = 0;
        for (selected.items) |edit| {
            const start = edit.start - begin;
            if (start < position) return error.InvalidPreContext;
            try out.appendSlice(self.a, source, position, start);
            try out.append(self.a, edit.tracked orelse missingEdit(source, start, edit.end - begin, edit.value));
            position = edit.end - begin;
        }
        try out.appendSlice(self.a, source, position, input.len);
        const prepared = try out.finish(self.a);
        // Only these sorted edits produced this source slice. Detached reference
        // bodies keep their own address domains and missing-dependency evidence.
        if (table) |request| if (begin == @intFromPtr(input.ptr)) {
            request.result = inlineBoxTableTransition(selected.items, request.original, source, prepared.bytes);
        };
        return prepared;
    }
    fn reference(self: *@This(), site: usize, name: []const u8, group: []const u8, source: []const u8, depth: usize) Error!void {
        // Anonymous references have no reusable referenceIndex. Their source site
        // still belongs to one extension pass even when a caption is revisited.
        for (self.seen_reference_sites.items) |prior| if (prior == site) return;
        try self.seen_reference_sites.append(self.a, site);
        const index = (try self.renderer.referenceIndex(name, group, source)) orelse return error.RenderLimit;
        // A forward use with no resolved body consumes nothing. Its later
        // definition must still be prepared when that body becomes available.
        if (self.renderer.refs.items[index].body.len == 0) return;
        for (self.seen_references.items) |seen| if (seen == index) return;
        try self.seen_references.append(self.a, index);
        try self.domain(self.renderer.refs.items[index].body, true, depth + 1);
    }
    fn domain(self: *@This(), source: []const u8, in_reference: bool, depth: usize) Error!void {
        if (depth > max_depth) return error.RenderLimit;
        const controlled = try self.renderer.externalSourceControlsWithMissing(try self.trackedCitationDomain(source));
        const prepared = controlled.bytes;
        try self.tracked_domains.append(self.a, controlled);
        if (self.collecting_citations) {
            try self.walk(prepared, .extensions, in_reference, true, depth + 1);
        } else {
            for ([_]Phase{ .extensions, .interlanguage, .media, .ordinary }) |phase_kind| {
                try self.walk(prepared, phase_kind, in_reference, true, depth + 1);
                if (depth == 0 and phase_kind == .extensions) if (self.citations) |plan|
                    for (plan.final_batches.items) |batch| try self.citationFooter(batch, depth + 1);
            }
        }
        if (prepared.ptr != source.ptr) try self.replaceTracked(source, 0, source.len, try self.applyWithMissing(controlled));
    }
    fn attribute(self: *@This(), tag: syntax.Tag, name: []const u8, depth: usize) Error!void {
        const raw = tag.attr(name) orelse return;
        const value = (try self.renderer.semanticAttribute(tag, name)) orelse return;
        const before = self.edits.items.len;
        try self.domain(value, false, depth + 1);
        if (self.edits.items.len == before) return;
        const prepared = try self.apply(value);
        var escaped: std.ArrayList(u8) = .empty;
        errdefer escaped.deinit(self.a);
        for (prepared) |ch| switch (ch) {
            '&' => try escaped.appendSlice(self.a, "&amp;"),
            '<' => try escaped.appendSlice(self.a, "&lt;"),
            '>' => try escaped.appendSlice(self.a, "&gt;"),
            ' ', 0x09...0x0d => try escaped.appendSlice(self.a, try std.fmt.allocPrint(self.a, "&#{d};", .{ch})),
            '"' => try escaped.appendSlice(self.a, "&quot;"),
            '\'' => try escaped.appendSlice(self.a, "&#39;"),
            else => try escaped.append(self.a, ch),
        };
        try self.replace(raw, 0, raw.len, try escaped.toOwnedSlice(self.a));
    }
    fn gallery(self: *@This(), input: []const u8, tag: syntax.Tag, depth: usize) Error!void {
        try self.attribute(tag, "caption", depth + 1);
        var lines = std.mem.splitScalar(u8, input, '\n');
        while (lines.next()) |raw_line| {
            const line = trim(raw_line);
            const pipe = syntax.delimiter(line, "|", 0) orelse continue;
            const raw_file = trim(line[0..pipe]);
            const colon = std.mem.indexOfScalar(u8, raw_file, ':');
            const file = if (colon != null and self.renderer.namespaceOfTarget(raw_file) == 6) raw_file[colon.? + 1 ..] else raw_file;
            if (media_types.referencedKind(file) == null) continue;
            const choice = self.renderer.mediaCaptionChoice(trim(line[pipe + 1 ..]), file, Renderer.mediaOptionMode(file, true));
            if (choice.authored_caption) try self.domain(choice.text, false, depth + 1);
        }
    }
    fn deletedEnd(self: *@This(), input: []const u8, at: usize) ?usize {
        const address_at = self.address(input, at);
        for (self.edits.items) |edit| if (edit.value.len == 0 and edit.start <= address_at and address_at < edit.end) {
            const end = self.address(input, input.len);
            return @min(edit.end, end) - self.address(input, 0);
        };
        return null;
    }
    fn citationTargetHasMissingOccurrence(self: *@This(), input: []const u8, target: []const u8) Error!bool {
        const base = @intFromPtr(input.ptr);
        const at = @intFromPtr(target.ptr);
        if (at < base or at - base > input.len or target.len > input.len - (at - base)) return false;
        const first = at - base;
        // Tracking can own a byte copy. Transport only the already proved
        // original slice offset into that exact tracked domain, never its pointer.
        const tracked = try self.trackedCitationBody(input);
        if (tracked.bytes.len != input.len) return error.InvalidPreContext;
        return internalTargetHasMissingOccurrence(tracked, tracked.bytes[first .. first + target.len]);
    }
    // The renderer's structural-title recovery visits the whole raw inner
    // body, but only after earlier label-only policies. Match that precedence
    // before registering citations hidden inside a rejected target.
    fn structuralTargetBodyVisible(self: *@This(), input: []const u8, token: ir.InlineSpan, original_target: []const u8) Error!bool {
        if (!safeInternalTarget(token.target) and try self.citationTargetHasMissingOccurrence(input, token.target)) return false;
        if (std.mem.indexOfAny(u8, original_target, "\r\n") != null) return false;
        var target = try self.renderer.withoutBehaviorControls(original_target);
        if (target.len != token.target.len) {
            target = std.mem.trim(u8, target, " \t");
            const title_part = if (starts(target, ":")) std.mem.trim(u8, target[1..], " \t") else target;
            const namespace_only = if (self.renderer.namespaceOfTarget(title_part) != null)
                std.mem.trim(u8, title_part[std.mem.indexOfScalar(u8, title_part, ':').? + 1 ..], " \t").len == 0
            else
                false;
            if (title_part.len == 0 or namespace_only) return false;
        }
        if (try self.renderer.internalTargetHasUnboundParameter(target, 0) != .none) return false;
        target = try self.renderer.entityText(target);
        return std.mem.indexOfAny(u8, target, "[]{}") != null;
    }
    fn internal(self: *@This(), input: []const u8, start: usize, end: usize, token: ir.InlineSpan, phase: Phase, in_reference: bool, allowed: bool, depth: usize) Error!void {
        const raw_target = try self.renderer.withoutBehaviorControls(token.target);
        var target = try self.renderer.entityText(raw_target);
        if (std.mem.indexOfScalar(u8, raw_target, '%') != null) {
            const decoded = try self.renderer.internalPercentTitleText(raw_target);
            // Match ordinary title emission before classifying language metadata.
            // Keep the separately qualified File caption preparation unchanged.
            if (!try self.renderer.fileTitleNamespace(decoded) and !try self.renderer.fileTitleNamespace(target) and
                !Renderer.invalidDecodedOrdinaryTitle(decoded)) target = decoded;
        }
        const explicit = starts(target, ":");
        if (phase == .interlanguage and allowed and self.renderer.isInterlanguageMetadata(target)) {
            const opening = start + (std.mem.indexOf(u8, input[start..end], "[[") orelse return error.InvalidPreContext);
            var first = opening;
            while (first != 0 and std.ascii.isWhitespace(input[first - 1])) first -= 1;
            // Match Parser's newline-plus-whitespace removal, not inline spaces.
            if (std.mem.indexOfScalar(u8, input[first..opening], '\n') == null) first = opening;
            try self.replace(input, first, end - token.trail.len, "");
            return;
        }
        if (phase == .extensions) {
            const original_target = try internalTargetWithoutCommentsAlloc(self.a, token.target);
            const angle_target = try self.renderer.entityText(try self.renderer.withoutBehaviorControls(original_target));
            const nowiki_target = internalTargetHasNowikiRegion(original_target);
            const whole_nowiki_body = nowiki_target and (safeInternalTarget(token.target) or
                !(try self.citationTargetHasMissingOccurrence(input, token.target)));
            const whole_structural_body = !nowiki_target and std.mem.indexOfAny(u8, angle_target, "[]{}") != null and
                try self.structuralTargetBodyVisible(input, token, original_target);
            if (whole_nowiki_body or whole_structural_body or (!nowiki_target and internalTargetSyntaxAllowed(angle_target, true) and
                internalTargetNeedsLiteralBody(angle_target)))
            {
                // These invalid titles render their complete original inner
                // body, not only a piped label. Prepare every visible extension
                // occurrence in that same raw domain before the strict consumer.
                const opening = start + (std.mem.indexOf(u8, input[start..end], "[[") orelse return error.InvalidPreContext);
                const outer_end = end - token.trail.len;
                try self.walk(input[opening + 2 .. outer_end - 2], phase, in_reference, false, depth + 1);
                return;
            }
        }
        if (!explicit and self.renderer.namespaceOfTarget(target) == 6) {
            if (!token.link_has_pipe or (phase != .extensions and phase != .interlanguage and phase != .media)) return;
            const colon = std.mem.indexOfScalar(u8, target, ':') orelse return;
            const file = target[colon + 1 ..];
            const choice = self.renderer.mediaCaptionChoice(token.text, file, Renderer.mediaOptionMode(file, false));
            if (choice.authored_caption) {
                if (phase == .extensions or phase == .interlanguage)
                    try self.walk(choice.text, phase, in_reference, phase == .interlanguage, depth + 1)
                else
                    try self.domain(choice.text, false, depth + 1);
            }
        } else if (phase == .extensions and token.link_has_pipe) {
            // Strip-phase extensions precede ordinary internal-link holders.
            // Their bodies are processed here without admitting nested ordinary actions.
            try self.walk(token.text, phase, in_reference, false, depth + 1);
        } else if (token.link_has_pipe and self.renderer.nestedLabelRefusal(target, token.text, explicit) != null) {
            try self.walk(token.text, phase, in_reference, allowed, depth + 1);
        }
    }
    fn walk(self: *@This(), input: []const u8, phase: Phase, in_reference: bool, allowed: bool, depth: usize) Error!void {
        if (depth > max_depth) return error.RenderLimit;
        var it: ir.InlineIterator = .{ .input = input, .renderer_boundaries = true, .link_trail = self.renderer.context.link_trail };
        var opaque_scan: syntax.OpaqueScan = .{};
        while (it.cursor < input.len) {
            const at = it.cursor;
            if (phase != .extensions) if (self.deletedEnd(input, at)) |end| {
                it.cursor = end;
                continue;
            };
            if (self.renderer.poemItemAt(input[at..])) |item| {
                it.cursor += item.token.len;
                const index = nativePoemIndex(input[at..]) orelse return error.InvalidPreContext;
                if (phase == .extensions and self.phase != null and index < self.seen_poem.len and item.kind == .literal and std.mem.eql(u8, item.tag, "poem") and !self.seen_poem[index]) {
                    self.seen_poem[index] = true;
                    self.native_domain_depth += 1;
                    defer self.native_domain_depth -= 1;
                    try self.domain(self.body(index), in_reference, depth + 1);
                }
                continue;
            }
            // The renderer rejects only an unbalanced invocation prefix and
            // resumes ordinary children. Do not let the shared iterator hide
            // later citation sites by treating the whole page tail as text.
            // This advances the collector only; authored bytes stay unchanged.
            if (starts(input[at..], "{{") and syntax.balancedWithOpaqueScan(input, at, &opaque_scan) == null) {
                it.cursor += if (starts(input[at..], "{{{")) @as(usize, 3) else 2;
                continue;
            }
            if (input[at] == '<') {
                if (starts(input[at..], "<!--")) {
                    it.cursor = opaque_scan.protectedEnd(input, at, null) orelse input.len;
                    continue;
                }
                if (try self.renderer.semanticTagAt(input, at)) |tag| {
                    it.cursor = tag.end;
                    if (tag.closing or tag.self_closing) {
                        if (phase == .extensions and !tag.closing and !in_reference) {
                            if (self.citations != null and tag.is("ref"))
                                try self.citationReference(input, at, tag, null, depth + 1)
                            else if (self.citations != null and tag.is("references"))
                                try self.citationReferences(input, at, tag, null, depth + 1)
                            else if (tag.is("ref"))
                                try self.reference(self.address(input, at), (try self.renderer.semanticAttribute(tag, "name")) orelse "", (try self.renderer.semanticAttribute(tag, "group")) orelse "", "", depth + 1);
                        }
                        continue;
                    }
                    if (tag.is("includeonly")) {
                        it.cursor = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len;
                        continue;
                    }
                    if (tag.is("nowiki")) {
                        it.cursor = opaque_scan.protectedEnd(input, at, null) orelse input.len;
                        continue;
                    }
                    // Tables are ordinary HTML, so the opaque-only matcher
                    // below cannot reach their admission rule.
                    if (tag.is("table")) if (syntax.matchingTagWithOpaqueScan(input, tag, &opaque_scan)) |table_pair| {
                        const table_content = input[tag.end..table_pair.inner_end];
                        if (!(try self.renderer.htmlTranslationsTable(tag, table_content)) and
                            !Renderer.htmlTableCaptionsComplete(table_content))
                        {
                            it.cursor = table_pair.end;
                            continue;
                        }
                    };
                    const pair = opaque_scan.pair(input, tag) orelse continue;
                    const content = input[tag.end..pair.inner_end];
                    it.cursor = pair.end;
                    if (tag.is("references")) {
                        if (phase == .extensions and !in_reference and self.citations != null)
                            try self.citationReferences(input, at, tag, content, depth + 1);
                        continue;
                    }
                    if (tag.is("ref")) {
                        if (phase == .extensions and !in_reference and self.citations != null) {
                            try self.citationReference(input, at, tag, content, depth + 1);
                            continue;
                        }
                        if (phase == .extensions and !in_reference)
                            try self.reference(self.address(input, at), (try self.renderer.semanticAttribute(tag, "name")) orelse "", (try self.renderer.semanticAttribute(tag, "group")) orelse "", content, depth + 1);
                    } else if (tag.is("gallery") or tag.is("poem")) {
                        if (phase == .extensions) {
                            const address_at = self.address(input, at);
                            var seen = false;
                            for (self.seen_extensions.items) |prior| if (prior == address_at) {
                                seen = true;
                                break;
                            };
                            if (!seen) {
                                try self.seen_extensions.append(self.a, address_at);
                                if (tag.is("gallery"))
                                    try self.gallery(content, tag, depth + 1)
                                else if (self.citations != null)
                                    try self.rawPoem(input, tag, content, in_reference, depth + 1)
                                else
                                    try self.domain(content, in_reference, depth + 1);
                            }
                        }
                    } else if (!tag.isOpaque() or tag.html_pre) {
                        try self.walk(content, phase, in_reference, allowed and !tag.is("a"), depth + 1);
                    }
                    continue;
                }
            }
            const before = it.cursor;
            // InlineIterator owns token admission; yield before authenticated
            // native items even when they follow an ordinary text run.
            const stop = if (self.renderer.poem_items.items.len != 0) std.mem.indexOfPos(u8, input, before + 1, native_poem_prefix) orelse input.len else input.len;
            it.input = input[0..stop];
            const token = it.next() orelse {
                it.input = input;
                continue;
            };
            it.input = input;
            if (it.cursor == before) return error.InvalidPreContext;
            if (token.kind == .link) {
                try self.internal(input, before, it.cursor, token, phase, in_reference, allowed, depth + 1);
            } else if ((phase == .extensions or phase == .interlanguage) and token.kind == .external_link and
                (token.text.ptr != token.target.ptr or token.text.len != token.target.len))
            {
                // Internal language metadata is removed before external labels
                // become holders. Keep ordinary numbering owned by the outer action.
                try self.walk(token.text, phase, in_reference, phase == .interlanguage, depth + 1);
            } else if (phase == .ordinary and allowed and token.kind == .external_link and
                token.external_label_prefix.len == 0 and token.text.ptr == token.target.ptr and token.text.len == token.target.len)
            {
                const target_at = @intFromPtr(token.target.ptr) - @intFromPtr(input.ptr);
                if (target_at == 0 or target_at > input.len or input[target_at - 1] != '[' or it.cursor == 0 or input[it.cursor - 1] != ']') continue;
                // Only a complete parsed source token can authorize a literal
                // defaultless destination before ordinary page numbering. The
                // prepared explicit token is independently revalidated at emission.
                const proof: ExternalLiteralParameterProof = .{ .token = input[before..it.cursor], .target = token.target };
                const literal_target = externalLiteralParameterTokenMatches(proof, token.target, true);
                const target = if (literal_target) token.target else try self.renderer.externalUrlTarget(token.target);
                // Never manufacture a clean label for another unresolved target.
                if (!literal_target and unresolvedExternalActionTarget(target)) return error.UncompiledTemplate;
                if (!safeUrl(target)) continue;
                const closing = self.address(input, it.cursor - 1);
                var prepared_here = false;
                for (self.edits.items) |edit| if (edit.start == closing and edit.end == closing) {
                    prepared_here = true;
                    break;
                };
                if (prepared_here) continue;
                if (self.number >= max_nodes) return error.RenderLimit;
                self.number += 1;
                const label = try std.fmt.allocPrint(self.a, " <nowiki>[{d}]</nowiki>", .{self.number});
                try self.replace(input, it.cursor - 1, it.cursor - 1, label);
                for (self.edits.items) |*edit| if (edit.start == closing and edit.end == closing and
                    edit.tracked == null and std.mem.eql(u8, edit.value, label)) {
                    edit.numbered_label_only = true;
                    break;
                };
            }
        }
    }
};
pub fn preparePageExternalLinksAlloc(a: A, source: []const u8, context: Context) Error!PreparedExternalLinks {
    return preparePageExternalLinksWithMissingAlloc(a, MissingText.untracked(source), context);
}
pub fn preparePageExternalLinksWithMissingAlloc(a: A, tracked: MissingText, context: Context) Error!PreparedExternalLinks {
    return preparePageExternalLinksModeAlloc(a, tracked, context, true, null);
}
fn preparePageExternalLinksModeAlloc(a: A, tracked: MissingText, context: Context, category_sortkeys: bool, source_renderer: ?*Renderer) Error!PreparedExternalLinks {
    const bound = try bindGeneratedSource(a, tracked, context.poem_phase);
    var category_context = context;
    category_context.content_conversion = try pageContentConversion(a, bound.bytes, context);
    var category_renderer: Renderer = .{ .a = a, .context = category_context };
    const initial_page = category_sortkeys and context.citations == null and !context.external_links_prepared and context.poem_phase == null;
    const multiline_source = if (initial_page) try category_renderer.preparePlainMultilineManualWithMissing(bound) else bound;
    const conversion_source = try category_renderer.prepareUnmatchedManualWithMissing(multiline_source);
    const category_source = if (initial_page)
        try category_renderer.preparePlainCategorySortKeys(conversion_source)
    else
        conversion_source;
    // The matched parser handles physical tables/internal links before external
    // autonumbering. An interrupted internal opener must not hide a later
    // authored bracketed external link from the page's numbering pass.
    var table_renderer: Renderer = .{ .a = a, .context = category_context };
    const opening_renderer = source_renderer orelse &table_renderer;
    // An observing renderer retains the helper's pointer-backed heading aliases.
    // Whole-page Builder callers establish their heading root after preparation.
    const normalized = if (initial_page)
        try opening_renderer.prepareTableInterruptedLinkOpenings(category_source)
    else
        category_source;
    var page_context = context;
    if (normalized.bytes.ptr != bound.bytes.ptr)
        page_context.citation_original_root = context.citation_original_root orelse bound.bytes;
    page_context.content_conversion = try pageContentConversion(a, normalized.bytes, context);
    var result = try preparePageExternalLinksInner(a, normalized, page_context);
    if (result.inline_box_table_transition) |*proof| {
        if (std.mem.eql(u8, tracked.bytes, bound.bytes) and std.mem.eql(u8, tracked.bytes, multiline_source.bytes) and
            std.mem.eql(u8, tracked.bytes, conversion_source.bytes) and std.mem.eql(u8, tracked.bytes, category_source.bytes) and
            std.mem.eql(u8, tracked.bytes, normalized.bytes) and proof.original.ptr == normalized.bytes.ptr and
            proof.original.len == normalized.bytes.len) proof.original = tracked.bytes else result.inline_box_table_transition = null;
    }
    if (result.class_scope_transition) |*proof| {
        if (std.mem.eql(u8, tracked.bytes, bound.bytes) and std.mem.eql(u8, tracked.bytes, multiline_source.bytes) and
            std.mem.eql(u8, tracked.bytes, conversion_source.bytes) and std.mem.eql(u8, tracked.bytes, category_source.bytes) and
            std.mem.eql(u8, tracked.bytes, normalized.bytes) and proof.original.ptr == normalized.bytes.ptr and
            proof.original.len == normalized.bytes.len) proof.original = tracked.bytes else result.class_scope_transition = null;
    }
    if (result.source_element_projection) |*proof| {
        if (std.mem.eql(u8, tracked.bytes, bound.bytes) and std.mem.eql(u8, tracked.bytes, multiline_source.bytes) and
            std.mem.eql(u8, tracked.bytes, conversion_source.bytes) and std.mem.eql(u8, tracked.bytes, category_source.bytes) and
            std.mem.eql(u8, tracked.bytes, normalized.bytes) and proof.original.bytes.ptr == normalized.bytes.ptr and
            proof.original.bytes.len == normalized.bytes.len) {
            proof.original = tracked;
        } else {
            a.free(proof.copies);
            result.source_element_projection = null;
        }
    }
    result.content_conversion = page_context.content_conversion;
    if (initial_page) result.fallbacks.merge(opening_renderer.fallbacks);
    return result;
}
fn preparePageExternalLinksInner(a: A, tracked: MissingText, context: Context) Error!PreparedExternalLinks {
    // A supplied immutable registry belongs to already annotated/numbered input.
    // Owner copies must never append follows or allocate URL labels a second time.
    if (context.citations) |plan| return .{ .source = tracked.bytes, .missing = tracked, .poem_phase = context.poem_phase, .citations = plan };
    if (tracked.ranges.len == 0) if (context.poem_phase) |known| {
        if (known.numbered_source) |root| if (known.numbered_citations) |plan| {
            if (std.mem.eql(u8, tracked.bytes, root) or std.mem.eql(u8, tracked.bytes, known.full_output))
                return .{ .source = root, .missing = MissingText.transformedFrom(tracked, root), .poem_phase = known, .citations = plan };
        };
    };
    const citation_possible = PageExternalNumbering.citationPossibleInContext(tracked.bytes, context);
    const control_can_form_tag = std.mem.indexOfScalar(u8, tracked.bytes, '<') != null and
        (context.behavior_switches != null or std.mem.indexOf(u8, tracked.bytes, "__") != null);
    if (!citation_possible and !control_can_form_tag)
        return preparePageExternalCore(a, tracked, context, false, null);
    // TOC elision can complete a tag name. Resolve that tracked transformation
    // before registering identities, so later owner/body TOC passes are stable.
    const toc_source = try preparePageTocSourceWithMissingAlloc(a, tracked, context.behavior_switches);
    var citation_context = context;
    if (toc_source.bytes.ptr != tracked.bytes.ptr)
        citation_context.citation_original_root = context.citation_original_root orelse tracked.bytes;
    if (!PageExternalNumbering.citationPossibleInContext(toc_source.bytes, citation_context))
        return preparePageExternalCore(a, tracked, context, false, null);
    const plan = try a.create(CitationPlan);
    plan.* = .{ .attribute = try PageExternalNumbering.citationAttributeAlloc(a, toc_source.bytes, citation_context), .limit = max_nodes };
    for (context.citation_definitions) |definition| if (definition.name.len != 0 and definition.body.len != 0) {
        try plan.authority(a, definition.name, definition.group, definition.missing orelse MissingText.transformed(definition.body));
    };
    const collected = try preparePageExternalCore(a, toc_source, citation_context, true, plan);
    defer if (collected.source_element_projection) |proof| a.free(proof.copies);
    if (plan.events.items.len == 0) {
        var final = try preparePageExternalCore(a, tracked, context, false, null);
        final.generated_external_labels = if (collected.generated_external_labels) |first|
            if (final.generated_external_labels) |last| first + last else null else null;
        return final;
    }
    try plan.finish(a);
    var numbered_context = citation_context;
    numbered_context.poem_phase = collected.poem_phase;
    numbered_context.citations = plan;
    var result = try preparePageExternalCoreWithProjection(a, collected.missing, numbered_context, false, plan, collected.source_element_projection);
    result.generated_external_labels = if (collected.generated_external_labels) |first|
        if (result.generated_external_labels) |last| first + last else null else null;
    if (result.inline_box_table_transition) |*second| {
        if (collected.inline_box_table_transition) |first| {
            if (toc_source.bytes.ptr == tracked.bytes.ptr and toc_source.bytes.len == tracked.bytes.len and
                first.prepared.ptr == second.original.ptr and first.prepared.len == second.original.len)
                second.original = first.original else result.inline_box_table_transition = null;
        } else result.inline_box_table_transition = null;
    }
    if (result.source_element_projection) |second| {
        defer a.free(second.copies);
        result.source_element_projection = null;
        if (toc_source.bytes.ptr == tracked.bytes.ptr and toc_source.bytes.len == tracked.bytes.len) {
            if (collected.source_element_projection) |first|
                result.source_element_projection = try SourceElementProjection.compose(a, first, second);
        }
    }
    return result;
}
fn preparePageExternalCore(a: A, tracked: MissingText, context: Context, collecting: bool, citations: ?*CitationPlan) Error!PreparedExternalLinks {
    return preparePageExternalCoreWithProjection(a, tracked, context, collecting, citations, null);
}
fn preparePageExternalCoreWithProjection(a: A, tracked: MissingText, context: Context, collecting: bool, citations: ?*CitationPlan,
    source_element_input: ?SourceElementProjection) Error!PreparedExternalLinks
{
    const source = tracked.bytes;
    // Repeated whole-page rendering reuses its already numbered root. Owner
    // subdomains keep that root as definition authority without replacing it.
    if (!collecting and citations == null and tracked.ranges.len == 0) if (context.poem_phase) |known| if (known.numbered_source) |root| {
        if (std.mem.eql(u8, source, root) or std.mem.eql(u8, source, known.full_output))
            return .{ .source = root, .missing = MissingText.transformedFrom(tracked, root), .poem_phase = known };
    };
    var prep: PageExternalNumbering = .{
        .a = a,
        .renderer = .{ .a = a, .context = context },
        .phase = context.poem_phase,
        .citations = citations,
        .collecting_citations = collecting,
        .source_element_input = source_element_input,
        .root_missing = tracked,
        .seen_poem = try a.alloc(bool, if (context.poem_phase) |phase| phase.items.len else 0),
    };
    defer prep.edits.deinit(a);
    defer prep.numbered_batches.deinit(a);
    defer prep.tracked_domains.deinit(a);
    defer prep.seen_references.deinit(a);
    defer prep.seen_reference_sites.deinit(a);
    defer prep.seen_extensions.deinit(a);
    defer a.free(prep.seen_poem);
    @memset(prep.seen_poem, false);
    try prep.renderer.loadPoemPhase();
    // Recollect against the exact prepared domain; native metadata originals
    // remain authentication evidence, not mutable source-rewrite storage.
    prep.renderer.ref_defs.clearRetainingCapacity();
    const controlled = try prep.renderer.externalSourceControlsWithMissing(tracked);
    const input = controlled.bytes;
    prep.root_missing = controlled;
    prep.renderer.poem_definitions_complete = true;
    if (citations == null) {
        try prep.renderer.referenceDefinitions(input, "");
        for (prep.renderer.ref_defs.items) |definition| if (definition.list_defined)
            try prep.reference(@intFromPtr(definition.body.ptr), definition.name, definition.group, definition.body, 0);
    }
    try prep.domain(input, false, 0);
    var table_transition: PageExternalNumbering.TableTransitionRequest = .{ .original = tracked };
    const prepared_missing = try prep.applyWithTableTransition(controlled, &table_transition);
    const prepared = prepared_missing.bytes;
    var phase = context.poem_phase;
    if (phase) |original| {
        const bodies = try a.alloc(?[]const u8, original.items.len);
        const body_links = try a.alloc([]const generated_link.Range, original.items.len);
        @memset(body_links, &.{});
        @memset(bodies, null);
        const previous_root = original.numbered_source orelse original.full_output;
        const whole_page = std.mem.eql(u8, source, previous_root) or if (context.citation_original_root) |root|
            std.mem.eql(u8, root, previous_root) or std.mem.eql(u8, root, original.full_output)
        else
            false;
        const prepared_root = if (whole_page) prepared else previous_root;
        // Owner slices may normalize independently, but cannot replace the
        // prepared full-page definition authority with their smaller domain.
        const prepared_plan = if (!collecting and whole_page) citations else original.numbered_citations;
        var changed = whole_page and (!std.mem.eql(u8, prepared_root, previous_root) or prepared_plan != original.numbered_citations or
            (prepared_missing.generated_links.len != 0 and prepared_root.ptr != previous_root.ptr));
        for (original.items, 0..) |item, index| {
            const body = prep.body(index);
            if (item.body == null) continue;
            const bound_body = try bindGeneratedSource(a, MissingText.untracked(body), original);
            const updated = try prep.applyWithMissing(bound_body);
            bodies[index] = if (updated.bytes.ptr != body.ptr) updated.bytes else if (index < original.numbered_bodies.len) original.numbered_bodies[index] else null;
            body_links[index] = updated.generated_links;
            changed = changed or updated.bytes.ptr != body.ptr;
        }
        if (changed) {
            const overlay = try a.create(PoemPhase);
            overlay.* = original.*;
            overlay.numbered_bodies = bodies;
            overlay.numbered_body_links = body_links;
            overlay.numbered_source = if (whole_page) prepared_root else original.numbered_source;
            overlay.numbered_links = if (whole_page) prepared_missing.generated_links else original.numbered_links;
            overlay.numbered_citations = prepared_plan;
            phase = overlay;
        } else { a.free(bodies); a.free(body_links); }
    }
    return .{ .generated_external_labels = if (prep.renderer.fallbacks.any()) null else prep.number,
        .source = prepared, .missing = prepared_missing, .poem_phase = phase, .citations = if (!collecting) citations else null,
        .class_scope_transition = if (std.mem.eql(u8, tracked.bytes, controlled.bytes)) prep.classScopeTransition(tracked, controlled, prepared) else null,
        .inline_box_table_transition = table_transition.result,
        .source_element_projection = try prep.sourceElementProjection(tracked, controlled, prepared) };
}

const HeadingSourceAlias = struct { copied: []const u8, original: []const u8 };
const HeadingSourceCopy = struct { start: usize, original: []const u8 };
const CitationLocal = struct { plan: *const CitationPlan, indices: []?usize };

const WikiTableTailProof = struct { source: MissingText, completed_close: ?usize = null };

const ConsumedClosedInlineDivs = struct {
    source: []const u8,
    owner: ?*const InlineSourceDomain = null,
    snapshot: ?[]const u8 = null,
    unknown: bool,
    ranges: std.ArrayList([2]usize) = .empty,
};

// Allocation eligibility only. The ordinary parser still has to consume a
// complete matching DIV before a position receipt can be published.
fn needsConsumedDivSnapshot(input: []const u8) bool {
    if (input.len > 16 * 1024 or std.mem.indexOf(u8, input, "-{") == null) return false;
    var at: usize = 0;
    while (std.mem.indexOfScalarPos(u8, input, at, '<')) |open| {
        if (input.len - open >= 4 and std.ascii.eqlIgnoreCase(input[open..open + 4], "<div")) return true;
        at = open + 1;
    }
    return false;
}

const ConsumedPlannedReference = struct {
    start: usize,
    end: usize,
    plan: *const CitationPlan,
    event: usize,
    source_digest: [32]u8,
};

const InlineSourceDomain = struct {
    source: []const u8,
    parent: ?*const InlineSourceDomain,
    // Exact metadata retained by the ordinary inline source owner.
    tracked: ?MissingText = null,
    // Offsets consumed by this live ordinary HTML parse. No layout authority.
    consumed_unclosed_centers: ?*std.ArrayList(usize) = null,
    consumed_closed_divs: ?*ConsumedClosedInlineDivs = null,
    consumed_planned_references: ?*std.ArrayList(ConsumedPlannedReference) = null,
};

// Selected by the ordinary whole-page producer, never inferred by a fragment.
pub const ContentRoot = enum { unknown, parser_output };

// Issued only from the original page observation through an exact owner range.
pub fn containsSortedOffset(openings: []const usize, boundary: usize) bool {
    var lo: usize = 0;
    var hi = openings.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (openings[mid] < boundary) lo = mid + 1 else hi = mid;
    }
    return lo < openings.len and openings[lo] == boundary;
}

pub const NativeArticleFragment = struct {
    literal_prefix: ?*const ObservedLiteralPrefix = null,
    page: []const u8,
    original_page: ?[]const u8,
    start: usize,
    prepared: []const u8,
    starts_page: bool,
    static_paragraph_openings: []const usize = &.{},
    static_paragraph_original_prefix: []const u8 = "",
    static_example_openings: []const usize = &.{},
    static_example_original_prefix: []const u8 = "",
    observed_box_table_heading_root: bool = false,
};
pub const NativeArticleHost = struct {
    renderer: *const Renderer,
    source: MissingText,
    title: []const u8,
    language_code: []const u8,
    active_source: ?MissingText = null,
    active_snapshot: ?[32]u8 = null,
    active_fragment: ?NativeArticleFragment = null,
    active_whole_page: bool = false,
    // Final semantic Entry factories render application chrome outside source
    // CSS. These facts say nothing about an observed HTML/BODY or source IDs.
    external_id_subjects_absent: bool = false,
    external_heading_subjects_absent: bool = false,
    // The final Article factory owns the native paragraph root. Source CSS
    // subjects are its retained descendants, not application chrome. Explicit
    // HTML/BODY/root and unsupported external effects still require proof.
    native_paragraph_css_subjects: bool = false,

    pub fn sameSource(left: MissingText, right: MissingText) bool {
        return left.bytes.ptr == right.bytes.ptr and left.bytes.len == right.bytes.len and
            left.ranges.ptr == right.ranges.ptr and left.ranges.len == right.ranges.len and
            left.literal_curly_ranges.ptr == right.literal_curly_ranges.ptr and left.literal_curly_ranges.len == right.literal_curly_ranges.len and
            left.generated_links.ptr == right.generated_links.ptr and left.generated_links.len == right.generated_links.len and
            left.generated_source == null and right.generated_source == null and
            left.unknown == right.unknown and left.lost_missing_range == right.lost_missing_range;
    }

    fn snapshotInteger(hash: *std.crypto.hash.sha2.Sha256, value: u64) void {
        var encoded: [8]u8 = undefined;
        std.mem.writeInt(u64, &encoded, value, .little);
        hash.update(&encoded);
    }

    pub fn snapshot(tracked: MissingText) ?[32]u8 {
        // Valid generated-link ranges require generated_source, which the
        // existing native motion root already refuses. Do not chase Bound graphs.
        if (tracked.generated_source != null or tracked.generated_links.len != 0 or
            tracked.ranges.len > missing_dependency.max_metadata_bytes / @sizeOf(missing_dependency.Range) or
            tracked.literal_curly_ranges.len > missing_dependency.max_metadata_bytes / @sizeOf(missing_dependency.LiteralRange)) return null;
        var hash = std.crypto.hash.sha2.Sha256.init(.{});
        hash.update("wikidict.native-article-active-source.v1");
        snapshotInteger(&hash, tracked.bytes.len);
        hash.update(tracked.bytes);
        snapshotInteger(&hash, tracked.ranges.len);
        for (tracked.ranges) |range| {
            snapshotInteger(&hash, range.start); snapshotInteger(&hash, range.end); snapshotInteger(&hash, range.occurrence);
        }
        snapshotInteger(&hash, tracked.literal_curly_ranges.len);
        for (tracked.literal_curly_ranges) |range| {
            snapshotInteger(&hash, range.start); snapshotInteger(&hash, range.end);
        }
        hash.update(&.{ @as(u8, @intFromBool(tracked.unknown)), @as(u8, @intFromBool(tracked.lost_missing_range)) });
        var result: [32]u8 = undefined;
        hash.final(&result);
        return result;
    }

    pub fn matchesActive(self: *const NativeArticleHost, renderer: *const Renderer, tracked: MissingText) bool {
        const active = self.active_source orelse return false;
        const code = renderer.native_body_language orelse return false;
        if (self.renderer != renderer or renderer.native_article_host != self or
            !std.mem.eql(u8, self.title, renderer.context.title) or !std.mem.eql(u8, self.language_code, code) or
            !sameSource(active, tracked)) return false;
        const expected = self.active_snapshot orelse return false;
        const current = snapshot(tracked) orelse return false;
        return std.mem.eql(u8, &expected, &current);
    }

    fn startsBoxTableRoot(self: *const NativeArticleHost, renderer: *const Renderer, tracked: MissingText) bool {
        if (self.startsPage(renderer, tracked)) return true;
        const fragment = self.active_fragment orelse return false;
        return fragment.observed_box_table_heading_root and fragment.start != 0 and !self.active_whole_page and
            self.matchesActive(renderer, tracked) and renderer.content_root == .parser_output and
            fragment.prepared.ptr == tracked.bytes.ptr and fragment.prepared.len == tracked.bytes.len and
            fragment.start < fragment.page.len and tracked.bytes.len <= fragment.page.len - fragment.start and
            std.mem.eql(u8, tracked.bytes, fragment.page[fragment.start..][0..tracked.bytes.len]);
    }
    pub fn startsPage(self: *const NativeArticleHost, renderer: *const Renderer, tracked: MissingText) bool {
        if (!self.matchesActive(renderer, tracked) or renderer.content_root != .parser_output) return false;
        if (self.active_whole_page) return self.active_fragment == null and sameSource(self.source, tracked);
        const fragment = self.active_fragment orelse return false;
        if (!fragment.starts_page or fragment.start != 0 or tracked.bytes.len > fragment.page.len or
            fragment.prepared.ptr != tracked.bytes.ptr or fragment.prepared.len != tracked.bytes.len or
            !std.mem.eql(u8, fragment.page[0..tracked.bytes.len], tracked.bytes)) return false;
        if (fragment.original_page) |original| if (!std.mem.eql(u8, original, fragment.page)) return false;
        return true;
    }
};

pub const RootWikiTableRange = struct {
    page: []const u8,
    start: usize,
    prepared: []const u8,
    openings: []const usize,
    top_level_openings: []const usize = &.{},
};

/// Build-only eligibility for the existing native LTR inline slice contract.
/// This scans rendered text, including decoded entities, never source spelling.
pub fn hasInlineBoxParagraphObligation(values: []const Span) bool {
    for (values) |span| if (span.inline_box_group != null) return true;
    return false;
}
const StaticInlineTextScan = struct {
    first: ?u21 = null,
    last: ?u21 = null,
    fn text(self: *@This(), value: []const u8) Error!void {
        var iterator = (std.unicode.Utf8View.init(value) catch return error.UncompiledPresentation).iterator();
        while (iterator.nextCodepoint()) |cp| {
            // Shared with the native slice consumer. Format characters which
            // genuinely participate in shaping are retained, not stripped.
            if (cp <= 0x1f or (cp >= 0x7f and cp <= 0x9f) or cp == 0xfffc or cp == 0x2028 or cp == 0x2029 or
                cp == 0x061c or cp == 0x200e or cp == 0x200f or (cp >= 0x202a and cp <= 0x202e) or
                (cp >= 0x2066 and cp <= 0x2069) or cp == 0x00ad or cp == 0x200b or cp == 0x2060 or cp == 0xfeff)
                return error.UncompiledPresentation;
            if (@import("unicode_bidi.zig").strongDirection(cp)) |direction| {
                if (direction == .rtl) return error.UncompiledPresentation;
            }
            if (self.first == null) self.first = cp;
            self.last = cp;
        }
    }
};
fn staticInlineEdgeWhitespace(cp: u21) bool {
    return cp == 0x20 or cp == 0xa0 or cp == 0x1680 or (cp >= 0x2000 and cp <= 0x200a) or
        cp == 0x202f or cp == 0x205f or cp == 0x3000;
}
// A run of nonbreaking spaces in a square swatch has measured advance even
// though its glyphs have no ink. It has no collapsible edge to transfer.
fn staticInlineNonbreakingSwatch(span: Span, group: presentation_types.InlineBoxGroup(Span)) bool {
    if (span.kind != .text or span.target.len != 0 or span.background == null or
        group.radius != null or group.overlays.len != 0 or group.spans.len != 1) return false;
    const child = group.spans[0];
    if (child.kind != .text or child.target.len != 0 or child.text.len == 0) return false;
    var rest = child.text;
    while (std.mem.startsWith(u8, rest, "\u{a0}")) rest = rest[2..];
    if (rest.len != 0) return false;
    const edge = group.border.top;
    if (edge != .solid or edge.solid.color != .rgb or edge.solid.width.unit != .px or edge.solid.width.value <= 0) return false;
    inline for (.{ "top", "right", "bottom", "left" }) |side| {
        if (@field(group.padding, side).value != 0 or !Renderer.sameFigurePreparationValue(@field(group.border, side), edge)) return false;
    }
    return true;
}
fn inlineBoxHasAudioControl(span: anytype) bool {
    return if (comptime @hasField(@TypeOf(span), "audio_control")) span.audio_control != null else false;
}
// A neutral-border ordinary inline owns a horizontal advance, an opaque paint
// interval, or both. Each child retains its own font, language, and action.
fn staticInlineFrame(owner: Span, group: presentation_types.InlineBoxGroup(Span)) bool {
    if (owner.kind != .text or owner.target.len != 0 or owner.flags.superscript or owner.flags.subscript or
        owner.flags.underline or owner.flags.strike or owner.inline_style != null or owner.font_size_unknown or
        group.radius != null or group.overlays.len != 0 or group.padding.top.value != 0 or group.padding.bottom.value != 0 or
        group.padding.left.unit != .px or group.padding.right.unit != .px or
        (group.padding.left.value == 0 and group.padding.right.value == 0 and owner.background == null)) return false;
    inline for (.{ "top", "right", "bottom", "left" }) |edge| if (@field(group.border, edge) != .none) return false;
    return presentation_types.validInlineBoxGroupOwner(owner);
}

// Keep the paragraph's direction scan continuous across declaring boundaries.
// Only neutral-border frames recurse. Bordered children retain the established
// metric/slice proof and detached overlay content cannot enter this subtree.
// Build-only source binding for a horizontal frame whose entire child is one
// original character reference. Recheck the parser node and its exact group
// when a containing frame or the containing paragraph visits this leaf again.
const StaticFrameNonbreakingEntity = struct {
    original: []const u8,
    group: *const presentation_types.InlineBoxGroup(Span),
    child: *const Span,

    fn matches(self: @This(), frame: *const presentation_types.InlineBoxGroup(Span), leaf: *const Span) bool {
        if (self.group != frame or frame.spans.len != 1 or self.child != leaf or leaf != &frame.spans[0] or
            (frame.padding.left.value == 0 and frame.padding.right.value == 0) or
            leaf.provenance != .entity_literal or leaf.kind != .text or leaf.target.len != 0 or leaf.inline_box_group != null or
            !std.mem.eql(u8, leaf.text, "\u{a0}")) return false;
        const tag = syntax.tagAt(self.original, 0) orelse return false;
        if (!tag.is("span") or tag.closing or tag.self_closing) return false;
        const pair = syntax.matchingTag(self.original, tag) orelse return false;
        if (pair.end != self.original.len or !Renderer.tableNestedSourceClose(self.original, tag.name, pair, false)) return false;
        const token = self.original[tag.end..pair.inner_end];
        if (token.len < 3 or token[0] != '&') return false;
        var buf: [4]u8 = undefined;
        const decoded = Renderer.decodeEntity(token, &buf, true) orelse return false;
        return decoded.consumed == token.len and std.mem.eql(u8, decoded.bytes, leaf.text);
    }
};

fn scanStaticInlineFrame(paragraph: *StaticInlineTextScan, owner: Span, depth: usize, remaining: *usize) Error!void {
    if (depth >= presentation_types.max_content_depth) return error.UncompiledPresentation;
    const frame = owner.inline_box_group orelse return error.UncompiledPresentation;
    if (!staticInlineFrame(owner, frame.*) or frame.spans.len > remaining.*) return error.UncompiledPresentation;
    remaining.* -= frame.spans.len;
    for (frame.spans, 0..) |span, i| {
        const decoded_text = if (owner.static_frame_entity) |held| held.matches(frame, &frame.spans[i]) else false;
        if (!staticInlineOrdinarySpan(span) or span.flags.superscript or span.flags.subscript or span.font_size_unknown or
            (span.provenance != .parsed and !decoded_text) or span.generated_diagnostic or span.generated_link != null or
            span.external_literal_parameter != null or presentation_types.spanHasClippedAbsolute(span) or
            inlineBoxHasAudioControl(span) or !presentation_types.validRubyChild(span)) return error.UncompiledPresentation;
        if (span.inline_box_group) |child| {
            if (staticInlineFrame(span, child.*)) {
                try scanStaticInlineFrame(paragraph, span, depth + 1, remaining);
            } else {
                if (depth + 1 >= presentation_types.max_content_depth or child.radius != null or child.overlays.len != 0 or
                    !staticDottedTextLabel(span, child.*) or child.spans.len > remaining.*) return error.UncompiledPresentation;
                remaining.* -= child.spans.len;
                const leaf = child.spans[0];
                if (!staticInlineOrdinarySpan(leaf) or leaf.inline_box_group != null or !presentation_types.validRubyChild(leaf) or
                    presentation_types.spanHasClippedAbsolute(leaf) or inlineBoxHasAudioControl(leaf) or
                    !inlineBoxWireMetricEqual(span, leaf)) return error.UncompiledPresentation;
                var label: StaticInlineTextScan = .{};
                try label.text(leaf.text);
                if (label.first == null or staticInlineEdgeWhitespace(label.first.?) or staticInlineEdgeWhitespace(label.last.?))
                    return error.UncompiledPresentation;
                try paragraph.text(leaf.text);
            }
        } else {
            try paragraph.text(span.text);
        }
    }
}

// A nested fixed-color circle has one real text leaf. Both boxes participate
// in line layout. Neither one supplies an action, direction or advisory title.
fn plainStaticBoxText(span: Span) bool {
    return staticInlineOrdinarySpan(span) and span.kind == .text and span.target.len == 0 and
        span.tooltip == null and span.inline_style == null and span.background == null and
        span.explanation.len == 0 and !span.flags.superscript and !span.flags.subscript and
        !presentation_types.spanHasClippedAbsolute(span) and !inlineBoxHasAudioControl(span);
}

fn fixedCircleLeaf(span: Span) ?Span {
    const group = span.inline_box_group orelse return null;
    const radius = group.radius orelse return null;
    if (!plainStaticBoxText(span) or radius.unit != .percent or radius.value != 50 or group.spans.len != 1 or
        group.overlays.len != 0 or group.border.top != .dotted or !presentation_types.validInlineBoxGroupOwner(span)) return null;
    const edge = group.border.top.dotted;
    if (edge.color != .rgb or edge.width.unit != .px or edge.width.value != 1) return null;
    inline for (.{ "top", "right", "bottom", "left" }) |side| if (@field(group.padding, side).value != 0) return null;
    const leaf = group.spans[0];
    if (!plainStaticBoxText(leaf) or leaf.inline_box_group != null or leaf.text.len == 0 or
        !inlineBoxWireMetricEqual(span, leaf)) return null;
    return leaf;
}

fn topEdgeWithCircle(owner: Span, group: presentation_types.InlineBoxGroup(Span)) bool {
    if (!plainStaticBoxText(owner) or group.overlays.len != 0 or group.radius != null or group.spans.len != 3 or
        group.border.top != .solid or group.border.right != .none or group.border.bottom != .none or group.border.left != .none) return false;
    const top = group.border.top.solid;
    if (top.color != .current_color or top.width.unit != .px or top.width.value != 1 or fixedCircleLeaf(group.spans[1]) == null) return false;
    inline for (.{ "top", "right", "bottom", "left" }) |side| if (@field(group.padding, side).value != 0) return false;
    for (group.spans, 0..) |child, i| {
        if (!plainStaticBoxText(child) or !inlineBoxWireMetricEqual(owner, child)) return false;
        if (i != 1 and (child.inline_box_group != null or child.text.len == 0)) return false;
    }
    return true;
}

fn staticDottedTextLabel(owner: Span, box: presentation_types.InlineBoxGroup(Span)) bool {
    if (owner.kind != .text or owner.target.len != 0 or box.radius != null or box.overlays.len != 0 or
        box.spans.len != 1 or box.spans[0].kind != .text or box.spans[0].target.len != 0 or
        box.border.top != .none or box.border.right != .none or box.border.left != .none or box.border.bottom != .dotted) return false;
    const line = box.border.bottom.dotted;
    if (line.color != .rgb or line.width.unit != .px or line.width.value <= 0) return false;
    inline for (.{ "top", "right", "bottom", "left" }) |side| if (@field(box.padding, side).value != 0) return false;
    return true;
}
fn staticInlineOrdinarySpan(span: Span) bool {
    return (span.kind == .text or span.kind == .link or span.kind == .external_link) and span.direction.len == 0 and
        span.captured_direction == null and !span.generated_bidi_boundary and span.captured_bidi_scope == null and
        span.pending_bidi_scope == null and span.image == null and span.ruby == null and span.inline_padding_group == null and
        span.inline_action_group == null and span.pending_figure == null and span.pending_container == null;
}
fn staticDashedLinkLabel(owner: Span, box: presentation_types.InlineBoxGroup(Span)) bool {
    if (owner.kind != .link or owner.target.len == 0 or owner.background == null or box.radius != null or box.overlays.len != 0 or
        box.spans.len != 1 or box.spans[0].kind != .text or box.spans[0].target.len != 0 or box.spans[0].text.len == 0 or
        box.border.top != .none or box.border.right != .none or box.border.left != .none or box.border.bottom != .dashed) return false;
    const line = box.border.bottom.dashed;
    if (line.color != .rgb or line.width.unit != .px or line.width.value != 1) return false;
    inline for (.{ "top", "right", "bottom", "left" }) |side| if (@field(box.padding, side).value != 0) return false;
    return true;
}
fn inlineBoxWireMetricEqual(owner: Span, child: Span) bool {
    var child_flags = child.flags;
    if (owner.inline_box_group) |box| {
        // A square dotted baseline label uses the declaring font for its border
        // band and the native child's actual font for shaping and line metrics.
        if (staticDottedTextLabel(owner, box.*) or staticDashedLinkLabel(owner, box.*)) child_flags.italic = owner.flags.italic;
    }
    const help_style: ?presentation_types.InlineTextStyle = .{ .cursor = .help };
    return (owner.inline_style == null or Renderer.sameFigurePreparationValue(owner.inline_style, help_style)) and
        Renderer.sameFigurePreparationValue(owner.inline_style, child.inline_style) and
        owner.link_paint == null and child.link_paint == null and std.meta.eql(child_flags, owner.flags) and
        Renderer.sameFigurePreparationValue(child.font_scale, owner.font_scale) and child.font_scale_basis == owner.font_scale_basis and
        !child.font_size_unknown and !owner.font_size_unknown and
        Renderer.sameFigurePreparationValue(child.font_features, owner.font_features) and
        Renderer.sameFigurePreparationValue(child.font_family, owner.font_family) and std.mem.eql(u8, child.language, owner.language) and
        std.mem.eql(u8, child.classes, owner.classes) and child.role == owner.role and
        Renderer.sameFigurePreparationValue(child.background, owner.background);
}
/// Must be called on the final complete physical paragraph, again after joins
/// or Document composition. A label's script alone does not prove its base.
pub fn validateInlineBoxParagraph(values: []const Span) Error!void {
    // A bare published run has no containing Flow to position detached text.
    for (values) |span| if (span.inline_box_group) |group| {
        if (presentation_types.inlineBoxHasOverlayContent(group.*)) return error.UncompiledPresentation;
    };
    return validateInlineBoxRunStructure(values);
}

// Parsing and paragraph joins can precede construction of the owning BDI Flow.
// Validate the run here; Document checks final containing blocks before encoding.
fn validateInlineBoxRunStructure(values: []const Span) Error!void {
    if (!hasInlineBoxParagraphObligation(values)) return;
    var remaining = presentation_types.max_presentation_items;
    var paragraph: StaticInlineTextScan = .{};
    for (values) |span| {
        // A typed sibling break has no directional character or box contents.
        // Keep scanning every later run; it does not reset the paragraph proof.
        if (span.kind == .line_break) {
            var ordinary = span;
            ordinary.kind = .text;
            if (!staticInlineOrdinarySpan(ordinary) or span.inline_box_group != null or
                presentation_types.spanHasClippedAbsolute(span) or inlineBoxHasAudioControl(span) or span.target.len != 0 or
                !(span.text.len == 0 or std.mem.eql(u8, span.text, "\n")))
                return error.UncompiledPresentation;
            continue;
        }
        // An independently compiled image remains a neutral replaced sibling.
        // It supplies no text or box authority and cannot reset later direction checks.
        if (span.image) |image| {
            var ordinary = span;
            ordinary.image = null;
            const action_kind: presentation_types.InlineKind = switch (span.kind) {
                .text => .text, .link => .link, .external_link => .external_link,
                else => return error.UncompiledPresentation,
            };
            if (!span.image_fields_compiled or span.text.len != 0 or
                span.provenance != .parsed or span.generated_diagnostic or span.font_size_unknown or
                !staticInlineOrdinarySpan(ordinary) or span.inline_box_group != null or
                presentation_types.spanHasClippedAbsolute(span) or inlineBoxHasAudioControl(span) or
                span.nonfloating_image or span.nonfloating_image_alignment != null or
                !presentation_types.validInlineImage(image) or
                !presentation_types.validInlineImageAction(action_kind, span.target))
                return error.UncompiledPresentation;
            continue;
        }
        if (!staticInlineOrdinarySpan(span)) return error.UncompiledPresentation;
        if (span.inline_box_group) |group| {
            if (staticInlineFrame(span, group.*)) {
                try scanStaticInlineFrame(&paragraph, span, 0, &remaining);
                continue;
            }
            if (span.flags.superscript or span.flags.subscript) return error.UncompiledPresentation;
            if (group.spans.len == 0) {
                // This exact zero-advance top edge has no text to add to the
                // paragraph's bidi scan. Continue checking all later siblings.
                if (!presentation_types.validInlineBoxGroupOwner(span)) return error.UncompiledPresentation;
                continue;
            }
            if (presentation_types.inlineBoxHasOverlayContent(group.*) and
                !presentation_types.validInlineBoxGroupOwner(span)) return error.UncompiledPresentation;
            var label: StaticInlineTextScan = .{};
            const circle_label = topEdgeWithCircle(span, group.*);
            for (group.spans, 0..) |item, i| {
                const child = if (circle_label and i == 1) fixedCircleLeaf(item).? else item;
                if (!staticInlineOrdinarySpan(child) or child.inline_box_group != null or child.flags.superscript or child.flags.subscript or
                    !inlineBoxWireMetricEqual(span, child))
                    return error.UncompiledPresentation;
                try label.text(child.text);
                try paragraph.text(child.text);
            }
            if (label.first == null or ((staticInlineEdgeWhitespace(label.first.?) or staticInlineEdgeWhitespace(label.last.?)) and
                !staticInlineNonbreakingSwatch(span, group.*)))
                return error.UncompiledPresentation;
        } else {
            if (span.inline_box_group != null) return error.UncompiledPresentation;
            try paragraph.text(span.text);
        }
    }
    // With no excluded/isolate content or R/AL text, native Auto resolves
    // LTR, including the no-strong fallback. Explicit directions refuse above;
    // the native consumer independently checks its actual containing block.
}

/// Qualify the exact run in its containing block. The typed isolate keeps its
/// own bidi resolution, and the absolute child never advances the outer line.
/// The consumer still resolves fragment geometry at its actual viewport width.
/// A recursive Flow visit alone cannot establish any of these relationships.
pub fn validateInlineBoxFlowRun(block: *const Block, selected: []const Span) Error!void {
    const parts = block.flow orelse return error.UncompiledPresentation;
    if (block.spans.len != 0 or block.figure != null or block.container != null or block.feature != null or
        block.table != null or block.style != null or block.text_align != null) return error.UncompiledPresentation;
    switch (block.kind) {
        .paragraph => if (block.depth != 0 or block.list_path.len != 0) return error.UncompiledPresentation,
        .list_item => if (block.depth != 1 or !std.mem.eql(u8, block.list_path, "*")) return error.UncompiledPresentation,
        else => return error.UncompiledPresentation,
    }
    var outer: StaticInlineTextScan = .{};
    var found = false;
    for (parts) |part| switch (part.kind) {
        .figure => return error.UncompiledPresentation,
        .@"inline" => {
            if (part.scope != null or part.figure != null) return error.UncompiledPresentation;
            try scanInlineBoxFlowSiblings(&outer, part.spans);
        },
        .scope => {
            if (found or part.spans.len != 0 or part.figure != null) return error.UncompiledPresentation;
            const scope = part.scope orelse return error.UncompiledPresentation;
            if (!presentation_types.validBidiScopeHeader(scope) or scope.mode != .isolate or scope.resolved_direction != .ltr or
                scope.parts.len != 1) return error.UncompiledPresentation;
            const run = scope.parts[0];
            if (run.kind != .@"inline" or run.figure != null or run.scope != null or run.spans.len != selected.len or
                run.spans.ptr != selected.ptr) return error.UncompiledPresentation;
            try validateInlineBoxRunStructure(selected);
            var inner: StaticInlineTextScan = .{};
            for (selected, 0..) |span, index| {
                const group = span.inline_box_group orelse {
                    try scanInlineBoxFlowSiblings(&inner, selected[index..][0..1]);
                    continue;
                };
                if (found or span.kind != .text or span.target.len != 0 or group.overlays.len != 1)
                    return error.UncompiledPresentation;
                const content = group.overlays[0].content orelse return error.UncompiledPresentation;
                if (!presentation_types.validInlineBoxOverlayContent(content.*)) return error.UncompiledPresentation;
                for (group.spans) |child| {
                    if (child.kind != .text or child.target.len != 0) return error.UncompiledPresentation;
                    try inner.text(child.text);
                }
                for (content.spans) |child| {
                    // ZWSP is an authored break opportunity in the positioned
                    // text. It must never enter the in-flow label scan.
                    var chunks = std.mem.splitSequence(u8, child.text, "\u{200b}");
                    var detached: StaticInlineTextScan = .{};
                    while (chunks.next()) |chunk| try detached.text(chunk);
                }
                found = true;
            }
            if (!found) return error.UncompiledPresentation;
        },
    };
    if (!found) return error.UncompiledPresentation;
}

fn scanInlineBoxFlowSiblings(scan: *StaticInlineTextScan, spans: []const Span) Error!void {
    for (spans) |span| {
        var ordinary = span;
        if (span.kind == .line_break) {
            if (!(span.text.len == 0 or std.mem.eql(u8, span.text, "\n")) or span.target.len != 0)
                return error.UncompiledPresentation;
            ordinary.kind = .text;
        }
        if (!staticInlineOrdinarySpan(ordinary) or span.inline_box_group != null or presentation_types.spanHasClippedAbsolute(span) or
            inlineBoxHasAudioControl(span) or span.font_size_unknown) return error.UncompiledPresentation;
        if (span.kind != .line_break) try scan.text(span.text);
    }
}

test "static swatch joins only concordant source entity leaves and preserves their provenance" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const swatch: table_style_profile.InlineBoxResolution = .{ .static_decoration = true,
        .border = .all(.{ .solid = .{ .width = .{ .unit = .px, .value = 1 }, .color = .{ .rgb = "#000000" } } }) };
    const style: Style = .{ .background = "#ffffff" };
    const Cases = struct { source: []const u8, accept: bool, unknown: bool = false, lost: bool = false };
    for ([_]Cases{
        .{ .source = "&nbsp;&nbsp;&nbsp;&nbsp;", .accept = true },
        .{ .source = "&#160;&#xA0;", .accept = true },
        .{ .source = "&nbsp; X", .accept = false },
        .{ .source = "&nbsp;&bogus;", .accept = false },
        .{ .source = "&nbsp;", .accept = false, .unknown = true },
        .{ .source = "&nbsp;", .accept = false, .lost = true },
    }) |case| {
        var r: Renderer = .{ .a = a, .context = .{} };
        try r.inlineTextWithMissing(MissingText.untracked(case.source), style, 0);
        var tracked = MissingText.untracked(case.source);
        tracked.unknown = case.unknown;
        tracked.lost_missing_range = case.lost;
        try std.testing.expectEqual(case.accept, try r.joinStaticSwatchEntities(tracked, case.source, swatch, style));
        if (case.accept) {
            try std.testing.expectEqual(@as(usize, 1), r.spans.items.len);
            const leaf = r.spans.items[0];
            try std.testing.expectEqual(Provenance.entity_literal, leaf.provenance);
            try std.testing.expectEqual(std.mem.count(u8, case.source, "&") * 2, leaf.text.len);
            try std.testing.expectEqual(leaf.text.len / 2, std.mem.count(u8, leaf.text, "\u{a0}"));
        }
    }
}

test "plain square nonbreaking swatch keeps its source next to an independent language link" {
    const spaces = "\u{a0}\u{a0}\u{a0}\u{a0}";
    var child: [1]Span = .{.{ .text = spaces, .background = "#ffffff" }};
    var group: presentation_types.InlineBoxGroup(Span) = .{
        .padding = .all(.{ .unit = .px, .value = 0 }),
        .border = .all(.{ .solid = .{ .width = .{ .unit = .px, .value = 1 }, .color = .{ .rgb = "#000000" } } }),
        .spans = &child,
    };
    var run = [_]Span{ .{ .text = "", .background = "#ffffff", .inline_box_group = &group }, .{ .text = " " },
        .{ .kind = .link, .text = "white", .target = "white#Енглески", .language = "en" } };
    try validateInlineBoxParagraph(&run);
    for ([_][]const u8{ "", " ", "\u{a0} ", " \u{a0}", "\u{2007}", "\u{a0}X", "X\u{a0}" }) |invalid| {
        child[0].text = invalid;
        try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&run));
    }
    child[0].text = spaces;
    group.border.left = .none;
    try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&run));
    group.border.left = group.border.top;
    group.radius = .{ .unit = .px, .value = 2 };
    try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&run));
    group.radius = null;
    group.padding.top.value = 1;
    try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&run));
    group.padding.top.value = 0;
    const edge = group.border.top;
    group.border = .all(.{ .solid = .{ .width = edge.solid.width, .color = .current_color } });
    try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&run));
    group.border = .all(edge);
    group.overlays = &.{.{ .insets = .{ .top = .{ .unit = .px, .value = 0 }, .right = .{ .unit = .px, .value = 0 } }, .border = .all(.none) }};
    try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&run));
    group.overlays = &.{};
    run[0].text = spaces;
    try std.testing.expectError(error.InvalidPresentation, presentation_types.validateInlineBoxGroupTree(run[0], 0, 0));
    run[0].text = "";
    run[0].kind = .link;
    run[0].target = "white";
    try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&run));
    run[0].kind = .text;
    run[0].target = "";
    run[2].text = "\u{05d0}";
    try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&run));
}

test "cell group opacity keeps authored cell paint and refuses an unrepresented backdrop" {
    var cell: table_style_profile.CellResolution = .{ .style = .{ .opacity = 0.2 },
        .background = "#abcdef", .background_specified = false, .unresolved = false };
    const table: presentation_types.TableStyle = .{ .background = "#abcdef" };
    try Renderer.preserveCellGroupBackdrop(&cell, "#abcdef", table, 1);
    try std.testing.expect(cell.background == null);
    cell.background_specified = true;
    cell.background = "#121212";
    try Renderer.preserveCellGroupBackdrop(&cell, "#abcdef", table, 1);
    try std.testing.expectEqualStrings("#121212", cell.background.?);
    try std.testing.expectError(error.UncompiledPresentation, Renderer.preserveCellGroupBackdrop(&cell, "#ffeecc", table, 1));
    try std.testing.expectError(error.UncompiledPresentation, Renderer.preserveCellGroupBackdrop(&cell, "#abcdef", table, 2));
    cell.style.?.opacity = 1;
    try Renderer.preserveCellGroupBackdrop(&cell, "#ffeecc", table, 2);
    try std.testing.expectEqualStrings("#121212", cell.background.?);
}

test "inline slice validates the complete directional paragraph including siblings after a break" {
    const group: presentation_types.InlineBoxGroup(Span) = .{
        .padding = .all(.{ .unit = .px, .value = 0 }),
        .border = .all(.{ .solid = .{ .width = .{ .unit = .px, .value = 1 }, .color = .current_color } }),
        .spans = &.{.{ .text = "tone" }},
    };
    var spans = [_]Span{ .{ .text = "before" }, .{ .text = "", .inline_box_group = &group },
        .{ .text = "\n", .kind = .line_break }, .{ .text = "after" } };
    try validateInlineBoxParagraph(&spans);
    for ([_][]const u8{ "\u{05d0}", "\u{202e}", "\u{fffc}" }) |invalid| {
        spans[3].text = invalid;
        try std.testing.expectError(error.UncompiledPresentation, validateInlineBoxParagraph(&spans));
    }
    try std.testing.expect(inlineBoxHasAudioControl(.{ .audio_control = @as(?bool, true) }));
    try std.testing.expect(!inlineBoxHasAudioControl(.{}));
}

pub const Renderer = struct {
    fn validClosedMissingFigures(scope: *const table_style_profile.BoundedTextClassScope, source: []const u8, profile: *const table_style_profile.Profile) ?table_style_profile.ClosedMissingFigureProof {
        const proof = scope.closed_missing_figures orelse return null;
        if (proof.styles != profile or proof.root != scope.page_style_root or proof.operations == 0 or proof.operations > 64 or
            proof.source.len == 0 or proof.source.ptr != source.ptr or proof.source.len != source.len) return null;
        return proof;
    }

    fn requireClosedMissingFigureStyle(self: *Renderer, choice: FigureChoice, tracked: MissingText, observed: ?FigureStyleObservation) Error!void {
        const selected = if (self.context.figure_sizing) |sizing| sizing.text_class_scope else null;
        const owed = self.required_missing_figure_scope orelse if (selected) |value|
            if (value.scope.closed_missing_figures != null) value.scope else return
        else return;
        const current = selected orelse return self.figureUnavailableAt("closed_figure_scope", tracked.bytes, 0, 0);
        const styles = self.context.table_styles orelse return self.figureUnavailableAt("closed_figure_profile", tracked.bytes, 0, 0);
        if (current.scope != owed or validClosedMissingFigures(owed, current.source, styles) == null or
            choice.content != .missing or observed == null)
            return self.figureUnavailableAt("closed_figure_operation", tracked.bytes, 0, 0);
    }

    fn observedEmptyMissingCaption(self: *const Renderer, selected: FigureClassSourceDomain, token: []const u8,
        options: []const u8) bool
    {
        const proof = selected.scope.empty_missing_figure_captions orelse return false;
        if (proof.styles != self.context.table_styles or selected.scope.page_styles != proof.styles or
            proof.root != selected.scope.page_style_root or proof.source.ptr != selected.selected.ptr or
            proof.source.len != selected.selected.len or proof.operations.len == 0 or proof.operations.len > 64 or
            !wikiClassContains(selected.selected, token) or options.len == 0 or syntax.delimiter(options, "|", 0) != null) return false;
        const start = @intFromPtr(token.ptr) - @intFromPtr(selected.selected.ptr);
        var found: usize = 0;
        for (proof.operations) |operation| {
            if (operation.start >= operation.end or operation.end > selected.selected.len) return false;
            if (operation.start == start and operation.end - operation.start == token.len) found += 1;
        }
        return found == 1;
    }

    fn emptyCaptionMappedWithToken(token: []const u8, caption: []const u8, mapped: []const u8) ?[]const u8 {
        if (caption.len != 0 or token.len != mapped.len or !std.mem.eql(u8, token, mapped)) return null;
        const at = std.math.sub(usize, @intFromPtr(caption.ptr), @intFromPtr(token.ptr)) catch return null;
        if (at > token.len) return null;
        return mapped[at..at];
    }
    fn observedFigureCaptionLinks(self: *Renderer, caption: []const u8) Error!?[]ObservedFigureCaptionLink {
        if (caption.len == 0 or caption.len > 4096 or trim(caption).len != caption.len) return null;
        var links: std.ArrayList(ObservedFigureCaptionLink) = .empty;
        defer links.deinit(self.a);
        var cursor: usize = 0;
        while (std.mem.indexOfPos(u8, caption, cursor, "[[")) |start| {
            if (!observedFigurePlainCaptionText(caption[cursor..start]) or links.items.len == 16) return null;
            var iterator: ir.InlineIterator = .{ .input = caption[start..], .renderer_boundaries = true, .link_trail = self.context.link_trail };
            const node = iterator.next() orelse return null;
            if (node.kind != .link or !node.link_has_pipe or node.link_empty_label or node.link_label_restored_close or
                node.trail.len != 0 or node.target.len == 0 or node.text.len == 0 or trim(node.text).len != node.text.len or
                !observedFigurePlainCaptionText(node.text) or !safeInternalTarget(node.target) or
                std.mem.indexOfAny(u8, node.target, "\x00\r\n\t<>{}&[]|' ") != null or
                self.namespaceOfTarget(node.target) == 6 or self.isInterlanguageMetadata(node.target)) return null;
            const token = caption[start..][0..iterator.cursor];
            if (token.len < 4 or !std.mem.endsWith(u8, token, "]]")) return null;
            try links.append(self.a, .{ .source = token });
            cursor = start + token.len;
        }
        if (links.items.len == 0 or !observedFigurePlainCaptionText(caption[cursor..])) return null;
        return try links.toOwnedSlice(self.a);
    }

    fn observedFigureCaptionSource(self: *Renderer, caption: []const u8, allow_categories: bool, allow_local_links: bool) Error!?FigureCaptionSourceShape {
        if (caption.len == 0 or caption.len > 4096 or !std.unicode.utf8ValidateSlice(caption) or
            std.mem.indexOfAny(u8, caption, "\x00\r\n\t{}&") != null or
            std.mem.indexOf(u8, caption, "__") != null) return null;
        const visible = trim(caption);
        if (visible.len == 0 or std.mem.indexOfScalar(u8, "*#;:", visible[0]) != null) return null;
        var inventory: FigureCaptionAuthoredInventory = .{};
        if (!figureCaptionFiniteNodesWithInventoryIn(self, .{ .bytes = caption }, caption, &inventory, allow_categories)) return null;
        var nodes: std.ArrayList(FigureCaptionSourceNode) = .empty;
        defer nodes.deinit(self.a);
        var root_text = false;
        if (!try self.observedReadyCaptionSourceBody(caption, null, false, 0, &nodes, &root_text, allow_categories, allow_local_links)) return null;
        return .{ .nodes = try nodes.toOwnedSlice(self.a), .has_text = root_text };
    }

    fn prepareObservedMissingFigure(self: *Renderer, choice: FigureChoice, parent: Style, tracked: MissingText,
        rtl: bool, observed: FigureStyleObservation) Error!PreparedFigureGeometry
    {
        if (choice.content != .missing or choice.format != .thumbnail or parent.underline or parent.strike or
            self.block_formatting.underline or self.block_formatting.strike) return self.figureUnavailableAt("observed_missing.content_shape", tracked.bytes, 0, 0);
        if (self.active_bidi_capture) |owner| if (owner.resolved == null) return self.figureUnavailableAt("observed_missing.bidi", tracked.bytes, 0, 0);
        const missing = choice.content.missing;
        const operation = self.observedFigureSourceOperation(tracked, choice.caption, choice.file, choice.format) orelse return self.figureUnavailableAt("observed_missing.operation", tracked.bytes, 0, 0);
        // Preserve the qualified ordinary A-only source contract. The shared
        // bounded Figure parser supplies the additional plain/quote/remote arm.
        const legacy_links = try self.observedFigureCaptionLinks(operation.caption);
        const source_shape: ?FigureCaptionSourceShape = if (operation.caption.len == 0)
            .{ .nodes = &.{}, .has_text = false } else if (legacy_links != null) null else
            (try self.observedFigureCaptionSource(operation.caption, false, true)) orelse return self.figureUnavailableAt("observed_missing.caption_shape", tracked.bytes, 0, 0);
        if (source_shape) |shape| for (shape.nodes) |node| {
            if (node.parent) |parent_index| {
                if (parent_index >= shape.nodes.len or node.kind != .link or
                    shape.nodes[parent_index].kind != .bold or shape.nodes[parent_index].parent != null)
                    return self.figureUnavailableAt("observed_missing.caption_shape", tracked.bytes, 0, 0);
            }
            if (node.kind != .italic and node.kind != .bold and node.kind != .link and node.kind != .line_break)
                return self.figureUnavailableAt("observed_missing.caption_shape", tracked.bytes, 0, 0);
        };
        // The captured pre-table origin is only a candidate: the complete
        // observed Missing resolver below must independently prove TD font equality.
        const parent_candidate = if (self.observedFigureNativeFontOrigin(parent) != null) parent else
            (try self.observedWikiFigureParentCandidate(operation, observed, parent)) orelse {
                if (self.context.table_viewport_trace) self.traceWikiFigureFontWitness(operation, observed, parent);
                return self.figureUnavailableAt("observed_missing.native_parent_origin", tracked.bytes, 0, 0);
            };
        for (observed.contexts, 0..) |context, context_index| {
            if (!self.observedFigureNativeParent(operation, context, parent_candidate)) return self.figureUnavailableAt("observed_missing.native_parent", tracked.bytes, 0, @intCast(context_index));
            if (source_shape) |shape| if (!observedReadyCaptionSourceMatches(shape, context))
                return self.figureUnavailableAt("observed_missing.caption_emission", tracked.bytes, 0, @intCast(context_index));
        }
        const language = self.observedFigureParentLanguage(operation, observed, parent_candidate) orelse
            return self.figureUnavailableAt("observed_missing.language", tracked.bytes, 0, 0);
        const native_parent: presentation_types.FigureMediaStrut = .{
            .font_scale = self.observedFigureNativeFontOrigin(parent_candidate) orelse return self.figureUnavailableAt("observed_missing.font_origin", tracked.bytes, 0, 0),
            .bold = parent.bold or self.block_formatting.bold, .italic = parent.italic or self.block_formatting.italic,
            .code = parent.code or self.block_formatting.code, .language = language, .direction = if (rtl) .rtl else .ltr, .font_features = parent.font_features,
        };
        var cascade_witness: table_style_profile.ObservedMissingFigureWitness = .{};
        const computed = (table_style_profile.resolveObservedMissingFigureWithWitness(self.a, observed.contexts, missing.data_width, native_parent, &cascade_witness) catch |err| return self.authoredElementQueryError(err))
            orelse return self.figureUnavailableAt(cascade_witness.stage, tracked.bytes, 0,
                (@as(u64, @intCast(cascade_witness.context_index)) << 32) | @as(u64, cascade_witness.subject orelse 0));
        const geometry = computed.geometry; const frame = geometry.frame;
        var session: ObservedFigureCaptionSession = .{ .operation = operation };
        if (source_shape) |shape| {
            if (shape.nodes.len != geometry.caption_inline.nodes.len) return self.figureUnavailableAt("observed_missing.caption_count", tracked.bytes, 0, 0);
            const bound = try self.a.alloc(ObservedFigureCaptionNode, shape.nodes.len);
            var caption_links: std.ArrayList(ObservedFigureCaptionLink) = .empty;
            defer caption_links.deinit(self.a);
            for (shape.nodes, geometry.caption_inline.nodes, bound) |source_node, computed_style, *out| {
                const style = observedFigureTextStyle(computed_style.font, computed_style.foreground) orelse return self.figureUnavailableAt("observed_missing.caption_style", tracked.bytes, 0, 0);
                if ((self.block_formatting.bold and !style.bold) or (self.block_formatting.italic and !style.italic)) return self.figureUnavailable();
                out.* = .{ .source = source_node, .style = style };
                if (source_node.kind == .link) try caption_links.append(self.a, .{ .source = source_node.opening, .style = style });
            }
            session.nodes = bound; session.links = try caption_links.toOwnedSlice(self.a);
        } else {
            session.links = legacy_links.?;
            session.link_style = observedFigureTextStyle(geometry.caption_link_font orelse return self.figureUnavailable(),
                .{ .kind = .rgb, .value = (geometry.caption_paint orelse return self.figureUnavailable()).normal.foreground }) orelse return self.figureUnavailableAt("observed_missing.link_font", tracked.bytes, 0, 0);
        }
        if (geometry.caption_link_count != session.links.len) return self.figureUnavailableAt("observed_missing.caption_count", tracked.bytes, 0, 0);
        if (!safeUrl(missing.href)) return self.figureUnavailableAt("observed_missing.href", tracked.bytes, 0, 0);
        const caption_style = observedFigureTextStyle(frame.caption_font, frame.caption_foreground) orelse return self.figureUnavailableAt("observed_missing.caption_font", tracked.bytes, 0, 0);
        var label_style = observedFigureTextStyle(geometry.label.font, geometry.label.foreground) orelse return self.figureUnavailableAt("observed_missing.label_font", tracked.bytes, 0, 0);
        label_style.kind = .external_link; label_style.target = missing.href;
        label_style.tooltip = missing.label; label_style.tooltip_set = true;
        const wrapper = computed.layout.wrapper;
        const margins = wrapper.margin_values orelse return self.figureUnavailableAt("observed_missing.wrapper", tracked.bytes, 0, 0);
        const zero: presentation_types.StyleLength = .{ .unit = .px, .value = 0 };
        var summary: presentation_types.StyleEdges = undefined;
        inline for (.{ "top", "right", "bottom", "left" }) |side| @field(summary, side) = switch (@field(margins, side)) {
            .auto => zero, .length => |value| value,
        };
        const placement: presentation_types.FigurePlacement = if (wrapper.float_side) |side|
            (if (side == .left) .float_left else .float_right)
            else if (margins.left == .auto and margins.right == .auto) .center else .none;
        const clear: presentation_types.FigureClear = if (wrapper.clear) |value| switch (value) {
            .none => .none, .left => .left, .right => .right, .both => .both,
        } else .none;
        const value: Figure = .{
            .content = .{ .missing = .{ .label = .{ .text = missing.label, .kind = .external_link, .target = missing.href },
                .width = geometry.label.width, .line_height = geometry.label.line_height, .link_paint = null } },
            .frame_min_width = frame.frame_min_width, .table_caption_layout = computed.layout,
            .format = choice.format, .placement = placement, .clear = clear, .margins = summary,
            .image_insets = geometry.label.insets, .caption_padding = frame.caption_padding,
            .caption_font_scale = frame.caption_font.font_scale, .caption_line_height = frame.caption_line_height,
            .frame_background = frame.frame_background, .frame_border = .{ .kind = .none },
            .image_background = geometry.label.background, .image_border = geometry.label.border,
            .caption_foreground = frame.caption_foreground, .caption_background = frame.caption_background,
            .caption_text_align = frame.caption_text_align,
        };
        if (!presentation_types.validFigureGeometry(value)) return self.figureUnavailableAt("observed_missing.final_model", tracked.bytes, 0, 0);
        const caption_domain = self.observedFigureCanonicalOperation(operation) orelse return self.figureUnavailable();
        session.preflight = .{ .profile = observed.profile, .scope = caption_domain.scope,
            .root = caption_domain.scope.page_style_root orelse return self.figureUnavailable(), .style = caption_style };
        return .{ .value = value, .caption_style = caption_style, .missing_style = label_style,
            .observed_caption = session };
    }
    const LiteralHtmlTableOperation = struct {
        tracked: MissingText,
        start: usize,
        end: usize,
    };

    const LiteralHtmlCellOperation = struct {
        proof: *const table_style_profile.SourceLiteralDivProof,
        scope: *const table_style_profile.BoundedTextClassScope,
        physical: *const table_style_profile.TextElement,
        tags: [4]syntax.Tag,
        table: LiteralHtmlTableOperation,
    };

    fn prepareLiteralHtmlTable(self: *const Renderer, tag: syntax.Tag, input: []const u8) ?LiteralHtmlTableOperation {
        if (!self.wikiClassOrdinaryDomain() or !tag.is("table")) return null;
        const domain = self.pageStyleDomain() orelse return null;
        const issued = domain.scope.source_literal_divs_source orelse return null;
        if (issued.ptr != domain.source.ptr or issued.len != domain.source.len) return null;
        for (domain.scope.source_literal_divs) |proof| {
            if (proof.html_cell_parent != null) break;
        } else return null;
        const binding = self.source_element_binding orelse return null;
        const tracked = self.body_missing orelse return null;
        const opening = projectedTrackedTagOpening(tracked, tag) orelse return null;
        const begin = @intFromPtr(opening.ptr) - @intFromPtr(tracked.bytes.ptr);
        const reparsed = syntax.tagAt(tracked.bytes, begin) orelse return null;
        const complete = syntax.matchingTag(tracked.bytes, reparsed) orelse return null;
        if (complete.end > tracked.bytes.len or input.ptr != tracked.bytes[reparsed.end..].ptr or
            input.len != complete.inner_end - reparsed.end) return null;
        const whole = tracked.bytes[begin..complete.end];
        if (!noLiParentSourceRange(tracked, whole) or !binding.projection.ordinaryRange(tracked, begin, complete.end)) return null;
        const owner = self.registeredOriginalInterval(whole, binding.owner.bytes) orelse return null;
        const start = binding.originalRange(owner) orelse return null;
        const end = start + owner.len;
        for (domain.scope.source_literal_divs) |proof| {
            const cell = proof.html_cell_parent orelse continue;
            if (cell.table.start == start and cell.table.end == end and cell.table.opening_end == start + opening.len and
                cell.table.body_end == start + complete.inner_end - begin) return .{ .tracked = tracked, .start = start, .end = end };
        }
        return null;
    }

    fn prepareLiteralHtmlCell(self: *Renderer, table: LiteralHtmlTableOperation, row_tag: syntax.Tag,
        cell_tag: syntax.Tag, body: []const u8,
    ) Error!?LiteralHtmlCellOperation {
        if (!row_tag.is("tr") or !cell_tag.is("td")) return null;
        const domain = self.pageStyleDomain() orelse return null;
        const class_domain = self.figureClassSourceDomain() orelse return null;
        if (class_domain.scope != domain.scope) return null;
        const binding = self.source_element_binding orelse return null;
        const root = domain.scope.page_style_complete_root orelse return null;
        const alternative = root.alternative_ancestry orelse return null;
        if (!root.physical_ancestry_complete or !root.ancestry_complete or
            !alternative.physical_ancestry_complete or !alternative.ancestry_complete) return null;
        const row_input = projectedTrackedTagOpening(table.tracked, row_tag) orelse return null;
        const cell_input = projectedTrackedTagOpening(table.tracked, cell_tag) orelse return null;
        for (domain.scope.source_literal_divs) |*proof| {
            const cap = proof.html_cell_parent orelse continue;
            if (proof.parent_start != null or proof.wiki_cell_parent != null or cap.table.start != table.start or cap.table.end != table.end or
                cap.table.opening_end > cap.row.start or cap.row.start >= cap.row.opening_end or cap.row.opening_end > cap.cell.start or
                cap.cell.start >= cap.cell.opening_end or cap.cell.opening_end > proof.range.anchor_start or
                proof.range.anchor_end > cap.cell.body_end or cap.cell.body_end >= cap.cell.end or
                cap.cell.end > cap.row.body_end or cap.row.body_end >= cap.row.end or cap.row.end > cap.table.body_end or
                cap.table.body_end >= cap.table.end) continue;
            if (row_input.len != cap.row.opening_end - cap.row.start or cell_input.len != cap.cell.opening_end - cap.cell.start or
                body.len != cap.cell.body_end - cap.cell.opening_end) continue;
            const row_owner = self.registeredOriginalInterval(row_input, binding.owner.bytes) orelse continue;
            const cell_owner = self.registeredOriginalInterval(cell_input, binding.owner.bytes) orelse continue;
            const body_owner = self.registeredOriginalInterval(body, binding.owner.bytes) orelse continue;
            if (binding.originalRange(row_owner) != cap.row.start or binding.originalRange(cell_owner) != cap.cell.start or
                binding.originalRange(body_owner) != cap.cell.opening_end) continue;
            const table_owner = binding.ownerRange(cap.table.start, cap.table.opening_end - cap.table.start) orelse continue;
            const table_tag = syntax.tagAt(table_owner, 0) orelse continue;
            if (!table_tag.is("table")) continue;
            const tags: [4]syntax.Tag = .{ table_tag,
                .{ .name = "tbody", .attrs = "", .end = 0, .closing = false, .self_closing = false }, row_tag, cell_tag };
            var physical = root;
            for (tags, [_][]const u8{ table_owner, table_owner, row_owner, cell_owner }) |tag, anchor| {
                physical = try self.literalWikiCellNode(tag, anchor, physical, domain);
                // The Book domain names the immutable full expansion. The
                // live class domain may be its distinct language fragment.
                @constCast(physical).ancestor_class_source = class_domain.selected;
                if (physical.alternative_ancestry) |other| @constCast(other).ancestor_class_source = class_domain.selected;
            }
            return .{ .proof = proof, .scope = domain.scope, .physical = physical, .tags = tags, .table = table };
        }
        return null;
    }

    fn literalHtmlCellParent(self: *const Renderer, known: LiteralDivContext,
        parent: ?*const table_style_profile.TextElement,
    ) ?*const table_style_profile.TextElement {
        const live = self.literal_html_cell orelse return null;
        const domain = self.pageStyleDomain() orelse return null;
        const binding = self.source_element_binding orelse return null;
        const proof = known.proof;
        const cap = proof.html_cell_parent orelse return null;
        // Recheck the entire original table on each use. A clean copied DIV
        // cannot lend ancestry after its enclosing source becomes tainted.
        if (cap.table.start != live.table.start or cap.table.end != live.table.end or
            cap.table.start >= cap.table.end or cap.table.end > domain.source.len) return null;
        const whole = binding.ownerRange(cap.table.start, cap.table.end - cap.table.start) orelse return null;
        if (!noLiParentSourceRange(binding.owner, whole) or binding.originalRange(whole) != cap.table.start or
            !binding.projection.ordinaryRange(binding.projection.original, cap.table.start, cap.table.end)) return null;
        if (parent != live.physical or proof != live.proof or domain.scope != live.scope or
            !self.currentAncestorScope(live.physical) or proof.range.anchor_end <= proof.range.anchor_start) return null;
        const current = self.registeredOriginalInterval(known.current_operation, binding.owner.bytes) orelse return null;
        if (current.len != proof.range.anchor_end - proof.range.anchor_start or
            binding.originalRange(current) != proof.range.anchor_start) return null;
        return live.physical;
    }


    const LiteralWikiTableOperation = struct {
        tracked: MissingText,
        table_opening: []const u8,
        outer_parent: ?*const table_style_profile.TextElement,
        row_opening: ?[]const u8 = null,
        cell_attrs: ?[]const u8 = null,
    };
    const LiteralWikiCell = struct {
        proof: table_style_profile.SourceWikiCellParentProof,
        scope: *const table_style_profile.BoundedTextClassScope,
        original: []const u8,
        copied: MissingText,
        logical_parent: *const table_style_profile.TextElement,
        physical_parent: *const table_style_profile.TextElement,
        outer_parent: *const table_style_profile.TextElement,
        tags: [4]syntax.Tag,
    };

    fn literalWikiCellCopies(self: *const Renderer, original: []const u8, replay: MissingText,
        copies: []const HeadingSourceCopy) bool
    {
        const binding = self.source_element_binding orelse return false;
        const domain = self.pageStyleDomain() orelse return false;
        if (original.len == 0 or replay.bytes.len != original.len or copies.len == 0 or
            !wikiClassContains(domain.source, original) or !noLiParentSourceRange(replay, replay.bytes) or
            !binding.projection.ordinaryRange(replay, 0, replay.bytes.len)) return false;
        const start = @intFromPtr(original.ptr) - @intFromPtr(domain.source.ptr);
        const owner = binding.ownerRange(start, original.len) orelse return false;
        if (!noLiParentSourceRange(binding.owner, owner) or
            !binding.projection.ordinaryRange(binding.projection.original, start, start + original.len)) return false;
        var end: usize = 0;
        for (copies) |copy| {
            if (copy.original.len == 0 or copy.start < end or copy.start > original.len or
                copy.original.len > original.len - copy.start) return false;
            const mapped = self.registeredCaptionOriginal(copy.original) orelse return false;
            if (mapped.ptr != original[copy.start..].ptr or mapped.len != copy.original.len or
                !std.mem.eql(u8, replay.bytes[copy.start..][0..copy.original.len], mapped)) return false;
            // Only the parser's identical physical LF gaps may join copied
            // intervals. Equal text without these live copy edges is not custody.
            for (original[end..copy.start], replay.bytes[end..copy.start]) |left, right|
                if (left != '\n' or right != '\n') return false;
            end = copy.start + copy.original.len;
        }
        for (original[end..], replay.bytes[end..]) |left, right| if (left != '\n' or right != '\n') return false;
        return true;
    }

    fn literalWikiCellParent(self: *const Renderer, known: LiteralDivContext,
        parent: ?*const table_style_profile.TextElement) ?*const table_style_profile.TextElement
    {
        const proof = known.proof.wiki_cell_parent orelse return null;
        const live = self.literal_wiki_cell orelse return null;
        const domain = self.pageStyleDomain() orelse return null;
        if (known.proof.parent_start != null or !std.meta.eql(proof, live.proof) or live.scope != domain.scope or
            (parent != live.logical_parent and parent != live.physical_parent) or
            proof.body_start >= proof.body_end or proof.body_end > domain.source.len or
            live.original.ptr != domain.source[proof.body_start..].ptr or live.original.len != proof.body_end - proof.body_start or
            known.proof.range.anchor_start < proof.body_start or known.proof.range.anchor_end > proof.body_end or
            !live.outer_parent.physical_ancestry_complete or !live.outer_parent.ancestry_complete or
            (live.outer_parent != domain.scope.page_style_complete_root and !self.currentAncestorScope(live.outer_parent))) return null;
        const binding = self.source_element_binding orelse return null;
        if (!noLiParentSourceRange(live.copied, live.copied.bytes) or
            !binding.projection.ordinaryRange(live.copied, 0, live.copied.bytes.len)) return null;
        if (proof.parent_start) |parent_start| {
            const outer_anchor = live.outer_parent.page_style_anchor orelse return null;
            const outer_tag = syntax.tagAt(outer_anchor, 0) orelse return null;
            const fresh_outer = self.literalDivContextForTrackedTag(outer_tag, binding.owner) orelse return null;
            if (fresh_outer.proof != live.outer_parent.source_literal_div or fresh_outer.proof.range.anchor_start != parent_start or
                !self.literalDivParent(fresh_outer, live.outer_parent.parent)) return null;
        } else if (live.outer_parent != domain.scope.page_style_complete_root or
            self.literalRootWikiTableProof(proof.table_start, domain) == null) return null;
        const original = self.registeredCaptionOriginal(known.current_operation) orelse return null;
        if (original.ptr != domain.source[known.proof.range.anchor_start..].ptr or
            original.len != known.proof.range.anchor_end - known.proof.range.anchor_start) return null;
        return live.physical_parent;
    }

    fn literalWikiCellNode(self: *Renderer, tag: syntax.Tag, anchor: []const u8,
        parent: *const table_style_profile.TextElement, domain: PageStyleDomain) Error!*const table_style_profile.TextElement
    {
        const node = try self.a.create(table_style_profile.TextElement);
        const own = try self.a.create(syntax.Tag); own.* = tag;
        node.* = .{ .tag = tag.name, .classes = (try self.semanticAttribute(tag, "class")) orelse "",
            .id = (try self.semanticAttribute(tag, "id")) orelse "", .language = try self.semanticAttribute(tag, "lang"),
            .parent = parent, .physical_ancestry_complete = true, .ancestry_complete = true,
            .page_style_root = domain.scope.page_style_root, .page_style_source = domain.source, .page_style_anchor = anchor,
            .ancestor_class_scope = domain.scope, .ancestor_class_source = domain.source,
            .complete_ancestor_classes = try self.childAncestorClasses(parent), .complete_ancestor_ids = try self.childAncestorIds(parent),
            .attribute_presence = .{ .ctx = own, .get = htmlOwnAttributePresence },
            .observed_inline_style = (try self.semanticAttribute(tag, "style")) orelse "" };
        if (parent.alternative_ancestry) |alternative_parent| {
            const alternative = try self.a.create(table_style_profile.TextElement);
            alternative.* = node.*; alternative.parent = alternative_parent;
            alternative.alternative_ancestry = null;
            node.alternative_ancestry = alternative;
        }
        return node;
    }

    fn literalRootWikiTableProof(self: *const Renderer, start: usize, domain: PageStyleDomain) ?*const table_style_profile.SourceWikiCellParentProof {
        if (!self.wikiClassOrdinaryDomain()) return null;
        const binding = self.source_element_binding orelse return null;
        const issued = domain.scope.source_literal_divs_source orelse return null;
        const observed = binding.projection.observedOriginal() orelse return null;
        const root = domain.scope.page_style_complete_root orelse return null;
        const alternative = root.alternative_ancestry orelse return null;
        if (!root.physical_ancestry_complete or !root.ancestry_complete or
            !alternative.physical_ancestry_complete or !alternative.ancestry_complete) return null;
        if (domain.scope.page_style_complete_root == null or issued.ptr != domain.source.ptr or issued.len != domain.source.len or
            observed.scope != domain.scope or observed.source.ptr != domain.source.ptr or observed.source.len != domain.source.len) return null;
        for (domain.scope.source_literal_divs) |*proof| if (proof.wiki_cell_parent) |*cap| {
            if (cap.parent_start != null or cap.table_start != start or cap.table_start >= cap.table_open_end or
                cap.table_open_end >= cap.row_start or cap.row_start >= cap.row_end or cap.row_end >= cap.attrs_start or
                cap.attrs_start > cap.attrs_end or cap.attrs_end > cap.body_start or cap.body_start >= cap.body_end or
                cap.body_end >= cap.table_end or cap.table_end > domain.source.len or proof.parent_start != null or
                proof.range.anchor_start < cap.body_start or proof.range.anchor_end > cap.body_end) continue;
            const original = domain.source[cap.table_start..cap.table_end];
            if (!starts(original, "{|") or !std.mem.endsWith(u8, original, "|}")) continue;
            const owner = binding.ownerRange(cap.table_start, original.len) orelse continue;
            if (!noLiParentSourceRange(binding.owner, owner) or
                !binding.projection.ordinaryRange(binding.projection.original, cap.table_start, cap.table_end)) continue;
            return cap;
        };
        return null;
    }

    fn literalRootWikiTableOpening(self: *const Renderer, opening: []const u8,
        parent: ?*const table_style_profile.TextElement) ?*const table_style_profile.SourceWikiCellParentProof
    {
        const domain = self.pageStyleDomain() orelse return null;
        const root = domain.scope.page_style_complete_root orelse return null;
        if (parent != null and parent != root) return null;
        const original = self.registeredCaptionOriginal(opening) orelse return null;
        if (!wikiClassContains(domain.source, original)) return null;
        const start = @intFromPtr(original.ptr) - @intFromPtr(domain.source.ptr);
        const cap = self.literalRootWikiTableProof(start, domain) orelse return null;
        if (original.len != cap.table_open_end - cap.table_start) return null;
        const tracked = self.body_missing orelse return null;
        if (!wikiClassContains(tracked.bytes, opening)) return null;
        const at = @intFromPtr(opening.ptr) - @intFromPtr(tracked.bytes.ptr);
        const length = cap.table_end - cap.table_start;
        if (length > tracked.bytes.len - at) return null;
        const whole = tracked.bytes[at..][0..length];
        const binding = self.source_element_binding orelse return null;
        if (!noLiParentSourceRange(tracked, whole) or !binding.projection.ordinaryRange(tracked, at, at + length)) return null;
        const mapped = self.registeredCaptionOriginal(whole) orelse return null;
        if (mapped.ptr != domain.source[cap.table_start..].ptr or mapped.len != length) return null;
        return cap;
    }

    fn literalRootWikiTableTag(self: *const Renderer, tag: syntax.Tag,
        parent: ?*const table_style_profile.TextElement) ?*const table_style_profile.SourceWikiCellParentProof
    {
        if (!tag.is("table") or tag.closing or tag.self_closing or tag.html_pre) return null;
        const held = self.page_style_wiki_opening orelse return null;
        if (held.tag.name.ptr != tag.name.ptr or held.tag.name.len != tag.name.len or
            held.tag.attrs.ptr != tag.attrs.ptr or held.tag.attrs.len != tag.attrs.len) return null;
        const anchor = self.pageStyleWikiOpening(tag) orelse return null;
        const actual_parent = if (parent) |node| own: {
            if (node.source_wiki_root_table == null) break :own parent;
            const prior = node.page_style_anchor orelse return null;
            if (!self.currentAncestorScope(node) or prior.ptr != anchor.ptr or prior.len != anchor.len or
                node.source_key != @intFromPtr(tag.name.ptr)) return null;
            break :own node.parent;
        } else null;
        return self.literalRootWikiTableOpening(held.source, actual_parent);
    }

    const LiteralRootWikiRow = struct { node: *const table_style_profile.TextElement, table: syntax.Tag, tbody: syntax.Tag };
    fn literalRootWikiRow(self: *Renderer, tag: syntax.Tag,
        parent: ?*const table_style_profile.TextElement) Error!?LiteralRootWikiRow
    {
        if (!tag.is("tr") or tag.closing or tag.self_closing or tag.html_pre) return null;
        const table = parent orelse return null;
        const cap = table.source_wiki_root_table orelse return null;
        const domain = self.pageStyleDomain() orelse return null;
        if (self.literalRootWikiTableProof(cap.table_start, domain) != cap or !self.currentAncestorScope(table)) return null;
        const operation = self.literal_wiki_table_operation orelse return null;
        const row = operation.row_opening orelse return null;
        const held = self.page_style_wiki_opening orelse return null;
        if (held.tag.name.ptr != tag.name.ptr or held.tag.attrs.ptr != tag.attrs.ptr or held.tag.attrs.len != tag.attrs.len or
            held.source.ptr != row.ptr or held.source.len != row.len or operation.outer_parent != table.parent or
            !noLiParentSourceRange(operation.tracked, row)) return null;
        const original = self.registeredCaptionOriginal(row) orelse return null;
        const table_original = self.registeredCaptionOriginal(operation.table_opening) orelse return null;
        if (original.ptr != domain.source[cap.row_start..].ptr or original.len != cap.row_end - cap.row_start or
            table_original.ptr != domain.source[cap.table_start..].ptr or table_original.len != cap.table_open_end - cap.table_start) return null;
        const binding = self.source_element_binding orelse return null;
        const table_anchor = binding.ownerRange(cap.table_start, cap.table_open_end - cap.table_start) orelse return null;
        const row_anchor = binding.ownerRange(cap.row_start, cap.row_end - cap.row_start) orelse return null;
        const tbody: syntax.Tag = .{ .name = "tbody", .attrs = "", .end = 0, .closing = false, .self_closing = false };
        const body = try self.literalWikiCellNode(tbody, table_anchor, table, domain);
        const node = try self.literalWikiCellNode(tag, row_anchor, body, domain);
        return .{ .node = node, .table = .{ .name = "table", .attrs = table_anchor[2..], .end = 0, .closing = false, .self_closing = false }, .tbody = tbody };
    }

    const LiteralWikiCellAttributeSource = struct { input: []const u8, original: []const u8, empty: bool };
    fn literalWikiCellAttributeSource(self: *const Renderer, operation: *const LiteralWikiTableOperation) ?LiteralWikiCellAttributeSource {
        const attributes = operation.cell_attrs orelse return null;
        if (attributes.len != 0) {
            if (!noLiParentSourceRange(operation.tracked, attributes)) return null;
            return .{ .input = attributes, .original = self.registeredCaptionOriginal(attributes) orelse return null, .empty = false };
        }
        // An empty attribute slice has no independent range authority. Retain
        // the actual first-cell delimiter selected by this live parser instead.
        const at = std.math.sub(usize, @intFromPtr(attributes.ptr), @intFromPtr(operation.tracked.bytes.ptr)) catch return null;
        if (at < 2 or at >= operation.tracked.bytes.len or operation.tracked.bytes[at] != '\n' or operation.tracked.bytes[at - 2] != '\n' or
            (operation.tracked.bytes[at - 1] != '|' and operation.tracked.bytes[at - 1] != '!')) return null;
        const marker = operation.tracked.bytes[at - 1..at];
        if (!noLiParentSourceRange(operation.tracked, marker)) return null;
        return .{ .input = marker, .original = self.registeredCaptionOriginal(marker) orelse return null, .empty = true };
    }

    fn literalWikiCellCurrentBody(self: *const Renderer, operation: *const LiteralWikiTableOperation,
        attributes: LiteralWikiCellAttributeSource, original: []const u8) bool
    {
        const marker_at = std.math.sub(usize, @intFromPtr(attributes.input.ptr), @intFromPtr(operation.tracked.bytes.ptr)) catch return false;
        if (!attributes.empty or marker_at >= operation.tracked.bytes.len) return false;
        const at = marker_at + 1;
        if (original.len > operation.tracked.bytes.len - at) return false;
        const current = operation.tracked.bytes[at..][0..original.len];
        const binding = self.source_element_binding orelse return false;
        if (!noLiParentSourceRange(operation.tracked, current) or
            !binding.projection.ordinaryRange(operation.tracked, at, at + current.len)) return false;
        const mapped = self.registeredCaptionOriginal(current) orelse return false;
        return mapped.ptr == original.ptr and mapped.len == original.len;
    }

    fn literalWikiCellStyleNode(self: *const Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement) ?*const table_style_profile.TextElement {
        const live = self.literal_wiki_cell_style orelse return null;
        const domain = self.pageStyleDomain() orelse return null;
        const binding = self.source_element_binding orelse return null;
        const operation = self.literal_wiki_table_operation orelse return null;
        const own = live.tags[3];
        if (live.scope != domain.scope or operation.outer_parent != live.outer_parent or
            tag.name.ptr != own.name.ptr or tag.name.len != own.name.len or tag.attrs.ptr != own.attrs.ptr or tag.attrs.len != own.attrs.len or
            tag.end != 0 or tag.closing or tag.self_closing or tag.html_pre or
            (parent != live.logical_parent.parent and parent != live.physical_parent.parent) or
            !self.currentAncestorScope(live.physical_parent)) return null;
        const attributes = self.literalWikiCellAttributeSource(operation) orelse return null;
        const cap = live.proof;
        if (!attributes.empty or cap.table_start >= cap.table_open_end or cap.table_open_end >= cap.row_start or
            cap.row_start >= cap.row_end or cap.row_end >= cap.attrs_start or cap.attrs_start != cap.attrs_end or
            cap.attrs_start != cap.body_start or cap.body_start >= cap.body_end or cap.body_end > cap.table_end or
            cap.table_end > domain.source.len or cap.attrs_start < 2 or domain.source[cap.attrs_start] != '\n' or
            domain.source[cap.attrs_start - 2] != '\n' or domain.source[cap.attrs_start - 1] != @as(u8, if (cap.header) '!' else '|') or
            attributes.original.ptr != domain.source[cap.attrs_start - 1..].ptr or attributes.original.len != 1 or
            live.original.ptr != domain.source[cap.body_start..].ptr or live.original.len != cap.body_end - cap.body_start or
            !self.literalWikiCellCurrentBody(operation, attributes, live.original)) return null;
        const row = self.registeredCaptionOriginal(operation.row_opening orelse return null) orelse return null;
        const table = self.registeredCaptionOriginal(operation.table_opening) orelse return null;
        if (row.ptr != domain.source[cap.row_start..].ptr or row.len != cap.row_end - cap.row_start or
            table.ptr != domain.source[cap.table_start..].ptr or table.len != cap.table_open_end - cap.table_start) return null;
        const body = binding.ownerRange(cap.body_start, live.original.len) orelse return null;
        if (!noLiParentSourceRange(binding.owner, body) or
            !binding.projection.ordinaryRange(binding.projection.original, cap.body_start, cap.body_end)) return null;
        return live.physical_parent;
    }

    fn emptyNativeWikiCellStyle(self: *Renderer, tag: syntax.Tag, parent: Style, native: CellNativeContext,
        inherited: SpanFlags, motion: NativeInlineMotionState) Error!?struct { style: Style, formatting: SpanFlags, weight_consumed: bool, ancestor_id_superset: []const u8 }
    {
        if ((!tag.is("td") and !tag.is("th")) or tag.attrs.len != 0 or tag.end != 0 or
            tag.closing or tag.self_closing or tag.html_pre) return null;
        const profile = self.context.table_styles orelse return null;
        if (self.textPaintProfile() != profile) return null;
        const state = switch (motion) { .proved => |known| known, else => return null };
        const parent_state = switch (parent.native_inline_motion) { .proved => |known| known, else => return null };
        if (self.native_inline_motion_root != state.root or self.native_inline_motion_epoch != state.epoch or
            state.root != parent_state.root or state.epoch != parent_state.epoch) return null;
        const declaration = state.last orelse return null;
        if (declaration.previous != parent_state.last or
            declaration.origin != (if (tag.is("th")) NativeInlineMotionOrigin.wiki_th else .wiki_td)) return null;
        const operation = self.literal_wiki_table_operation orelse return null;
        const attributes = operation.cell_attrs orelse return null;
        if (attributes.ptr != tag.attrs.ptr or attributes.len != 0 or operation.tracked.unknown or
            !NativeArticleHost.sameSource(declaration.source, operation.tracked) or
            !noLiParentSourceRange(operation.tracked, declaration.opening)) return null;
        const parsed = (try self.nativeInlineMotionWikiTag(declaration.origin, declaration.opening)) orelse return null;
        if (!parsed.is(tag.name) or parsed.attrs.ptr != attributes.ptr or parsed.attrs.len != 0) return null;
        // The real delimiter and current declaration issue this ordinary TD/TH.
        // Whole-source IDs only remove impossible ancestors; the node itself
        // retains its original unknown ancestry for every later query.
        const logical = try self.textElement(tag, parent.text_element, parent.language);
        const ids = (try self.nativeSourceClassQueryTokensDiagnosed(tag, profile, logical, motion, null, true)) orelse return null;
        errdefer self.a.free(ids);
        const previous_attributes = self.body_formatting_attributes.native_inline_motion;
        const previous_language = if (self.body_language_direction) |value| value.native_inline_motion else .absent;
        self.body_formatting_attributes.native_inline_motion = motion;
        if (self.body_language_direction) |*value| value.native_inline_motion = motion;
        defer {
            self.body_formatting_attributes.native_inline_motion = previous_attributes;
            if (self.body_language_direction) |*value| value.native_inline_motion = previous_language;
        }
        var own_style = try self.cellOwnerStyle(tag, parent, true, native);
        own_style.native_inline_motion = motion;
        own_style.text_element = logical;
        var formatting = inherited;
        if (try self.htmlFontWeightIn(tag, parent.text_element, inherited.bold, parent.language)) |value| formatting.bold = value;
        if (try self.htmlFontStyleIn(tag, parent.text_element, inherited.italic, parent.language)) |value| formatting.italic = value;
        const paint = try self.textPaint(tag, parent.text_element, parent.language);
        return .{ .style = own_style, .formatting = formatting, .ancestor_id_superset = ids,
            .weight_consumed = self.tableTextWeightConsumed(paint, inherited.bold, formatting.bold) };
    }

    fn emptyLiteralWikiCellStyle(self: *Renderer, tag: syntax.Tag, parent: Style, native: CellNativeContext,
        inherited: SpanFlags) Error!?struct { style: Style, formatting: SpanFlags, weight_consumed: bool }
    {
        const operation = self.literal_wiki_table_operation orelse return null;
        const attributes = self.literalWikiCellAttributeSource(operation) orelse return null;
        if (!attributes.empty or tag.attrs.len != 0) return null;
        const logical = try self.textElement(tag, parent.text_element, parent.language);
        var live = (try self.prepareLiteralWikiCell(.{ .text_element = logical })) orelse return null;
        const previous = self.literal_wiki_cell_style;
        self.literal_wiki_cell_style = &live;
        defer self.literal_wiki_cell_style = previous;
        const own = live.tags[3];
        if (self.literalWikiCellStyleNode(own, parent.text_element) == null) return null;
        // The ordinary own-element cascade computes font/paint and inherited
        // properties using the proved TD, independently of its descendants.
        var style = try self.cellOwnerStyle(own, parent, true, native);
        style.text_element = live.physical_parent;
        var formatting = inherited;
        if (try self.htmlFontWeightIn(own, parent.text_element, inherited.bold, parent.language)) |value| formatting.bold = value;
        if (try self.htmlFontStyleIn(own, parent.text_element, inherited.italic, parent.language)) |value| formatting.italic = value;
        const paint = try self.textPaint(own, parent.text_element, parent.language);
        return .{ .style = style, .formatting = formatting,
            .weight_consumed = self.tableTextWeightConsumed(paint, inherited.bold, formatting.bold) };
    }

    // The whole-cell edge must agree with the already registered line edges.
    // A canonical-source shortcut would conflict with those immediate pointers
    // for single-line children, even when both paths reach the same source.
    fn literalWikiCellReplayOrigin(self: *const Renderer, tracked: MissingText, original: []const u8,
        replay: MissingText, copies: []const HeadingSourceCopy) ?[]const u8
    {
        if (copies.len == 0 or original.len == 0 or original.len != replay.bytes.len) return null;
        const first_at = std.math.sub(usize, @intFromPtr(copies[0].original.ptr), @intFromPtr(tracked.bytes.ptr)) catch return null;
        const at = std.math.sub(usize, first_at, copies[0].start) catch return null;
        if (at > tracked.bytes.len or replay.bytes.len > tracked.bytes.len - at) return null;
        const current = tracked.bytes[at..][0..replay.bytes.len];
        const binding = self.source_element_binding orelse return null;
        if (!noLiParentSourceRange(tracked, current) or !binding.projection.ordinaryRange(tracked, at, at + current.len)) return null;
        for (copies) |copy| {
            if (copy.start > current.len or copy.original.len > current.len - copy.start or
                copy.original.ptr != current[copy.start..].ptr) return null;
        }
        const mapped = self.registeredCaptionOriginal(current) orelse return null;
        if (mapped.ptr != original.ptr or mapped.len != original.len or !std.mem.eql(u8, current, replay.bytes)) return null;
        return current;
    }

    fn bindLiteralWikiCell(self: *Renderer, replay: MissingText, copies: []const HeadingSourceCopy, style: Style) Error!?LiteralWikiCell {
        var live = (try self.prepareLiteralWikiCell(style)) orelse return null;
        var original = live.original;
        // The ordinary parser omits the single LF after a bare cell opener.
        // Only that exact source byte may precede the complete copied body.
        if (live.proof.attrs_start == live.proof.attrs_end and original.len == replay.bytes.len + 1 and original[0] == '\n') original = original[1..];
        if (!self.literalWikiCellCopies(original, replay, copies)) return null;
        const operation = self.literal_wiki_table_operation orelse return null;
        const immediate = self.literalWikiCellReplayOrigin(operation.tracked, original, replay, copies) orelse return null;
        try self.heading_source_aliases.append(self.a, .{ .copied = replay.bytes, .original = immediate });
        live.copied = replay;
        return live;
    }

    fn prepareLiteralWikiCell(self: *Renderer, style: Style) Error!?LiteralWikiCell {
        if (!self.wikiClassOrdinaryDomain() or self.typed_table_depth == 0) return null;
        const domain = self.pageStyleDomain() orelse return null;
        const binding = self.source_element_binding orelse return null;
        const issued = domain.scope.source_literal_divs_source orelse return null;
        const observed = binding.projection.observedOriginal() orelse return null;
        if (issued.ptr != domain.source.ptr or issued.len != domain.source.len or observed.scope != domain.scope or
            observed.source.ptr != domain.source.ptr or observed.source.len != domain.source.len) return null;
        const td = style.text_element orelse return null;
        const tr = td.parent orelse return null;
        const row_parent = tr.parent orelse return null;
        const table = if (std.ascii.eqlIgnoreCase(row_parent.tag, "tbody")) row_parent.parent orelse return null else row_parent;
        const outer = table.parent orelse return null;
        const operation = self.literal_wiki_table_operation orelse return null;
        if (outer != operation.outer_parent) return null;
        const row_input = operation.row_opening orelse return null;
        const attributes = self.literalWikiCellAttributeSource(operation) orelse return null;
        for ([_][]const u8{operation.table_opening, row_input, attributes.input}) |part|
            if (!noLiParentSourceRange(operation.tracked, part)) return null;
        const table_original = self.registeredCaptionOriginal(operation.table_opening) orelse return null;
        const row_original = self.registeredCaptionOriginal(row_input) orelse return null;
        const cell_original = if (attributes.empty) attributes.original[1..] else attributes.original;
        const outer_proof = outer.source_literal_div;
        if ((!std.ascii.eqlIgnoreCase(td.tag, "td") and !std.ascii.eqlIgnoreCase(td.tag, "th")) or
            !std.ascii.eqlIgnoreCase(tr.tag, "tr") or !std.ascii.eqlIgnoreCase(table.tag, "table") or
            !self.currentAncestorScope(td) or !self.currentAncestorScope(tr) or !self.currentAncestorScope(table) or
            (outer != domain.scope.page_style_complete_root and !self.currentAncestorScope(outer))) return null;
        for (domain.scope.source_literal_divs) |proof| {
            const cap = proof.wiki_cell_parent orelse continue;
            if (proof.parent_start != null or
                (if (cap.parent_start) |parent_start| outer_proof == null or parent_start != outer_proof.?.range.anchor_start
                    else outer != domain.scope.page_style_complete_root or table.source_wiki_root_table == null or
                        self.literalRootWikiTableProof(cap.table_start, domain) != table.source_wiki_root_table) or
                cap.table_start >= cap.table_open_end or cap.table_open_end >= cap.row_start or
                cap.row_start >= cap.row_end or cap.row_end >= cap.attrs_start or cap.attrs_start > cap.attrs_end or
                cap.attrs_end > cap.body_start or cap.body_start >= cap.body_end or cap.body_end > cap.table_end or
                cap.table_end > domain.source.len or !std.ascii.eqlIgnoreCase(td.tag, if (cap.header) "th" else "td")) continue;
            if (attributes.empty != (cap.attrs_start == cap.attrs_end)) continue;
            if (attributes.empty and (cap.attrs_start < 2 or cap.attrs_end != cap.body_start or domain.source[cap.attrs_start] != '\n' or
                domain.source[cap.attrs_start - 2] != '\n' or domain.source[cap.attrs_start - 1] != @as(u8, if (cap.header) '!' else '|'))) continue;
            if (!attributes.empty and cap.attrs_end == cap.body_start) continue;
            const original = domain.source[cap.body_start..cap.body_end];
            if (attributes.empty and !self.literalWikiCellCurrentBody(operation, attributes, original)) continue;
            const body_anchor = binding.ownerRange(cap.body_start, original.len) orelse continue;
            if (!noLiParentSourceRange(binding.owner, body_anchor) or
                !binding.projection.ordinaryRange(binding.projection.original, cap.body_start, cap.body_end)) continue;
            if (table_original.ptr != domain.source[cap.table_start..].ptr or table_original.len != cap.table_open_end - cap.table_start or
                row_original.ptr != domain.source[cap.row_start..].ptr or row_original.len != cap.row_end - cap.row_start or
                cell_original.ptr != domain.source[cap.attrs_start..].ptr or cell_original.len != cap.attrs_end - cap.attrs_start or
                !starts(table_original, "{|") or !starts(row_original, "|-")) continue;
            const table_anchor = binding.ownerRange(cap.table_start, table_original.len) orelse continue;
            const row_anchor = binding.ownerRange(cap.row_start, row_original.len) orelse continue;
            const cell_anchor = if (attributes.empty)
                binding.ownerRange(cap.attrs_start - 1, 1) orelse continue
            else binding.ownerRange(cap.attrs_start, cell_original.len) orelse continue;
            if (cap.parent_start != null) {
                const outer_anchor = outer.page_style_anchor orelse continue;
                const outer_tag = syntax.tagAt(outer_anchor, 0) orelse continue;
                const outer_known = self.literalDivContextForTrackedTag(outer_tag, binding.owner) orelse continue;
                if (outer_known.proof != outer_proof or !self.literalDivParent(outer_known, outer.parent)) continue;
            }
            // Build the physical chain only for this complete cell operation.
            // The empty TBODY is established by the existing captured grid join.
            const tags: [4]syntax.Tag = .{
                .{ .name = "table", .attrs = table_anchor[2..], .end = 0, .closing = false, .self_closing = false },
                .{ .name = "tbody", .attrs = "", .end = 0, .closing = false, .self_closing = false },
                .{ .name = "tr", .attrs = row_anchor[2..], .end = 0, .closing = false, .self_closing = false },
                .{ .name = if (cap.header) "th" else "td", .attrs = if (attributes.empty) cell_anchor[1..] else cell_anchor, .end = 0, .closing = false, .self_closing = false },
            };
            var physical = outer;
            for (tags, [_][]const u8{ table_anchor, table_anchor, row_anchor, cell_anchor }) |tag, anchor| {
                physical = try self.literalWikiCellNode(tag, anchor, physical, domain);
                if (tag.is("table") and cap.parent_start == null) {
                    const root_cap = self.literalRootWikiTableProof(cap.table_start, domain) orelse return null;
                    @constCast(physical).source_wiki_root_table = root_cap;
                    if (physical.alternative_ancestry) |alternative| @constCast(alternative).source_wiki_root_table = root_cap;
                }
            }
            return .{ .proof = cap, .scope = domain.scope, .original = original, .copied = MissingText.untracked(original),
                .logical_parent = td, .physical_parent = physical, .outer_parent = outer, .tags = tags };
        }
        return null;
    }

    const LiteralDivContext = struct {
        proof: *const table_style_profile.SourceLiteralDivProof,
        opening: []const u8,
        current_operation: []const u8,
    };

    fn projectedTrackedTagOpening(tracked: MissingText, tag: syntax.Tag) ?[]const u8 {
        if (tag.closing or tag.self_closing or tag.html_pre or !wikiClassContains(tracked.bytes, tag.name)) return null;
        const name_at = @intFromPtr(tag.name.ptr) - @intFromPtr(tracked.bytes.ptr);
        if (name_at == 0) return null;
        const opening = syntax.tagAt(tracked.bytes, name_at - 1) orelse return null;
        if (opening.end <= name_at or opening.end > tracked.bytes.len or tracked.bytes[opening.end - 1] != '>') return null;
        if (opening.name.ptr != tag.name.ptr or opening.name.len != tag.name.len or
            opening.attrs.ptr != tag.attrs.ptr or opening.attrs.len != tag.attrs.len or
            opening.closing != tag.closing or opening.self_closing != tag.self_closing or opening.html_pre != tag.html_pre) return null;
        const whole = tracked.bytes[name_at - 1..opening.end];
        // renderBody parses a trimmed physical line at zero; tag.end can be
        // relative to that slice, not the tracked owner. The reparsed pointers
        // and complete opening determine the range, never that foreign offset.
        if (tag.end < whole.len or tag.end > tracked.bytes.len) return null;
        return whole;
    }

    fn literalDivContextForTag(self: *const Renderer, tag: syntax.Tag) ?LiteralDivContext {
        const tracked = if (self.inline_missing) |current|
            (if (wikiClassContains(current.bytes, tag.name)) current else self.body_missing orelse return null)
            else self.body_missing orelse return null;
        return self.literalDivContextForTrackedTag(tag, tracked);
    }

    fn literalDivContextForTrackedTag(self: *const Renderer, tag: syntax.Tag, tracked: MissingText) ?LiteralDivContext {
        return self.literalDivContextForTrackedTagIn(tag, tracked, false);
    }
    fn literalDivContextForTrackedTagIn(self: *const Renderer, tag: syntax.Tag, tracked: MissingText, inline_restoration: bool) ?LiteralDivContext {
        const ordinary = if (inline_restoration) self.literalUlInlineDomain() else self.wikiClassOrdinaryDomain();
        if (!tag.is("div") or tag.closing or tag.self_closing or tag.html_pre or !ordinary) return null;
        const domain = self.pageStyleDomain() orelse return null;
        if (domain.scope.page_style_complete_root == null) return null;
        const selected = self.figureStyleSourceDomain() orelse return null;
        if (selected.scope != domain.scope or selected.selected.ptr != domain.source.ptr or selected.selected.len != domain.source.len) return null;
        _ = self.figureStyleOriginalBinding(selected) orelse return null;
        const issued = domain.scope.source_literal_divs_source orelse return null;
        if (issued.ptr != domain.source.ptr or issued.len != domain.source.len) return null;
        const binding = self.source_element_binding orelse return null;
        const observed = binding.projection.observedOriginal() orelse return null;
        if (observed.scope != domain.scope or observed.source.ptr != domain.source.ptr or observed.source.len != domain.source.len) return null;
        // Unlike generic projected absence, this separately issued operation may
        // retain global unknown. Every complete local range remains clean.
        const opening = projectedTrackedTagOpening(tracked, tag) orelse return null;
        const current_start = @intFromPtr(opening.ptr) - @intFromPtr(tracked.bytes.ptr);
        const current_tag = syntax.tagAt(tracked.bytes, current_start) orelse return null;
        const current_pair = syntax.matchingTag(tracked.bytes, current_tag) orelse return null;
        if (current_pair.end <= current_start or current_pair.end > tracked.bytes.len) return null;
        const current_whole = tracked.bytes[current_start..current_pair.end];
        if (!noLiParentSourceRange(tracked, current_whole) or
            !binding.projection.ordinaryRange(tracked, current_start, current_pair.end)) return null;
        const owner_whole = if (wikiClassContains(binding.owner.bytes, current_whole)) current_whole else mapped: {
            // Registration must cover the complete operation, not only its
            // opening/name. Equality without the existing live alias is refusal.
            const original = self.registeredCaptionOriginal(current_whole) orelse return null;
            if (wikiClassContains(binding.owner.bytes, original)) break :mapped original;
            if (!wikiClassContains(domain.source, original)) return null;
            const at = @intFromPtr(original.ptr) - @intFromPtr(domain.source.ptr);
            break :mapped binding.ownerRange(at, original.len) orelse return null;
        };
        const owner_start = @intFromPtr(owner_whole.ptr) - @intFromPtr(binding.owner.bytes.ptr);
        const original_start = binding.originalRange(owner_whole) orelse return null;
        for (domain.scope.source_literal_divs) |*proof| {
            const range = proof.range;
            if (range.anchor_start != original_start or range.anchor_end <= original_start or range.anchor_end > domain.source.len or
                range.anchor_end - original_start != owner_whole.len or range.name_start != original_start + 1 or
                range.name_len != tag.name.len or range.attrs_len != tag.attrs.len) continue;
            if (!noLiParentSourceRange(binding.owner, owner_whole) or
                !binding.projection.ordinaryRange(binding.owner, owner_start, owner_start + owner_whole.len) or
                !binding.projection.ordinaryRange(binding.projection.original, original_start, range.anchor_end) or
                !std.mem.eql(u8, current_whole, owner_whole)) return null;
            const own = syntax.tagAt(owner_whole, 0) orelse return null;
            const pair = syntax.matchingTag(owner_whole, own) orelse return null;
            if (pair.end != owner_whole.len or !std.ascii.eqlIgnoreCase(own.name, tag.name) or !std.mem.eql(u8, own.attrs, tag.attrs) or
                range.attrs_start != original_start + @intFromPtr(own.attrs.ptr) - @intFromPtr(owner_whole.ptr)) return null;
            return .{ .proof = proof, .opening = owner_whole[0..own.end], .current_operation = current_whole };
        }
        return null;
    }

    fn literalUlRestoration(self: *const Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement) bool {
        const inline_restoration = self.inline_source_domain != null;
        const ordinary = if (inline_restoration) self.literalUlInlineDomain() else self.wikiClassOrdinaryDomain();
        if (!tag.is("ul") or tag.closing or tag.self_closing or tag.html_pre or tag.attrs.len != 0 or !ordinary) return false;
        const domain = self.pageStyleDomain() orelse return false;
        const binding = self.source_element_binding orelse return false;
        const tracked = self.inline_missing orelse return false;
        const opening = projectedTrackedTagOpening(tracked, tag) orelse return false;
        if (!std.mem.eql(u8, opening, "<ul>") or !noLiParentSourceRange(tracked, opening)) return false;
        const current_start = @intFromPtr(opening.ptr) - @intFromPtr(tracked.bytes.ptr);
        if (!binding.projection.ordinaryRange(tracked, current_start, current_start + opening.len)) return false;
        const authored_opening = if (inline_restoration) mapped: {
            const paragraph_source = self.literalUlInlineOriginal() orelse return false;
            if (current_start > paragraph_source.len or opening.len > paragraph_source.len - current_start) return false;
            break :mapped paragraph_source[current_start..][0..opening.len];
        } else opening;
        const original = self.registeredCaptionOriginal(authored_opening) orelse return false;
        if (!wikiClassContains(domain.source, original) or !std.mem.eql(u8, original, opening)) return false;
        const original_start = @intFromPtr(original.ptr) - @intFromPtr(domain.source.ptr);
        const body = self.body_missing orelse return false;
        const original_body = self.registeredCaptionOriginal(body.bytes) orelse return false;
        if (!wikiClassContains(domain.source, original_body) or !std.mem.eql(u8, original_body, body.bytes)) return false;
        const body_start = @intFromPtr(original_body.ptr) - @intFromPtr(domain.source.ptr);
        for (domain.scope.source_literal_divs) |*proof| {
            const restore = proof.restored_ul orelse continue;
            const start = proof.range.anchor_end;
            if (restore.depth == 0 or restore.depth > 8 or restore.end <= start or restore.end > domain.source.len or
                restore.end - start != @as(usize, restore.depth) * 4 or restore.body_end < restore.end or restore.body_end > domain.source.len or
                (restore.items == 0) != (restore.body_end == restore.end) or
                original_start < start or original_start + opening.len > restore.end or (original_start - start) % 4 != 0) continue;
            var at = start;
            while (at < restore.end) : (at += 4) if (!std.mem.eql(u8, domain.source[at..][0..4], "<ul>")) return false;
            if (start < body_start or restore.body_end - body_start > body.bytes.len) return false;
            const local_start = start - body_start; const local_end = restore.body_end - body_start;
            if (!noLiParentSourceRange(body, body.bytes[local_start..local_end]) or
                !noLiParentSourceRange(binding.projection.original, domain.source[start..restore.body_end]) or
                !binding.projection.ordinaryRange(body, local_start, local_end) or
                !binding.projection.ordinaryRange(binding.projection.original, start, restore.body_end)) return false;
            if (proof.range.anchor_start >= start or start > domain.source.len) return false;
            const owner_note = binding.ownerRange(proof.range.anchor_start, start - proof.range.anchor_start) orelse return false;
            const note_tag = syntax.tagAt(owner_note, 0) orelse return false;
            const known = self.literalDivContextForTrackedTagIn(note_tag, binding.owner, inline_restoration) orelse return false;
            if (known.proof != proof or !self.literalDivParentIn(known, parent, inline_restoration)) return false;
            // Book proved the restored UL/LI skeleton against the captured
            // sibling list. renderBody has already cut this bare opener run
            // away from the following wiki lines, which retain their normal
            // list paths, content, actions and independent style checks.
            return true;
        }
        return false;
    }

    fn literalDivParent(self: *const Renderer, known: LiteralDivContext, parent: ?*const table_style_profile.TextElement) bool {
        return self.literalDivParentIn(known, parent, false);
    }
    fn literalDivParentIn(self: *const Renderer, known: LiteralDivContext, parent: ?*const table_style_profile.TextElement, inline_restoration: bool) bool {
        const domain = self.pageStyleDomain() orelse return false;
        if (known.proof.html_cell_parent != null) return self.literalHtmlCellParent(known, parent) != null;
        if (known.proof.wiki_cell_parent != null) return self.literalWikiCellParent(known, parent) != null;
        if (known.proof.parent_start) |parent_start| {
            const node = parent orelse return false;
            const proof = node.source_literal_div orelse return false;
            if (proof.range.anchor_start != parent_start or !node.physical_ancestry_complete or !node.ancestry_complete or
                node.page_style_root != domain.scope.page_style_root or !self.currentAncestorScope(node)) return false;
            if (proof.range.anchor_end <= parent_start or proof.range.anchor_end > domain.source.len) return false;
            const anchor = node.page_style_anchor orelse return false;
            const binding = self.source_element_binding orelse return false;
            if (binding.originalRange(anchor) != parent_start) return false;
            const parent_tag = syntax.tagAt(anchor, 0) orelse return false;
            const current_whole = node.source_literal_div_current orelse return false;
            const current_tag = syntax.tagAt(current_whole, 0) orelse return false;
            if (node.source_key != @intFromPtr(current_tag.name.ptr) or node.tag.ptr != current_tag.name.ptr or
                !std.ascii.eqlIgnoreCase(node.tag, parent_tag.name)) return false;
            const registered = self.registeredCaptionOriginal(current_whole) orelse return false;
            const owner_whole = binding.ownerRange(parent_start, proof.range.anchor_end - parent_start) orelse return false;
            const owner_original = binding.originalRange(owner_whole) orelse return false;
            if (owner_original != parent_start or registered.len != owner_whole.len or
                !std.mem.eql(u8, current_whole, owner_whole)) return false;
            // The registered caption helper may return the language fragment
            // itself when its bounded class scope owns the whole parent.
            // Accept that exact live range only with both local parent edges.
            if (registered.ptr != domain.source[parent_start..].ptr and
                (!known.proof.paired_parent_heads or registered.ptr != owner_whole.ptr)) return false;
            // Child rendering contracts body_missing to its own slice. Revalidate
            // this already-issued parent against the retained whole owner, never
            // borrow the child's range or bypass fresh owner/projection taint.
            const fresh = self.literalDivContextForTrackedTagIn(parent_tag, binding.owner, inline_restoration) orelse return false;
            if (fresh.proof != proof or parent_start >= known.proof.range.anchor_start) return false;
            return self.literalDivParentIn(fresh, node.parent, inline_restoration);
        }
        return parent == null or domain.scope.page_style_complete_root == parent;
    }

    fn validClosedReadyFigures(scope: *const table_style_profile.BoundedTextClassScope, source: []const u8, profile: *const table_style_profile.Profile) ?table_style_profile.ClosedReadyFigureProof {
        const proof = scope.closed_ready_figures orelse return null;
        if (proof.styles != profile or proof.root != scope.page_style_root or proof.operations == 0 or proof.operations > 64 or
            proof.source.len == 0 or proof.source.ptr != source.ptr or proof.source.len != source.len) return null;
        return proof;
    }

    fn requireClosedReadyFigureStyle(self: *Renderer, choice: FigureChoice, tracked: MissingText, observed: ?FigureStyleObservation) Error!void {
        const selected = if (self.context.figure_sizing) |sizing| sizing.text_class_scope else null;
        const owed = self.required_ready_figure_scope orelse if (selected) |value|
            if (value.scope.closed_ready_figures != null) value.scope else return
        else return;
        self.required_ready_figure_scope = owed;
        const current = selected orelse return self.figureUnavailableAt("closed_ready_scope", tracked.bytes, 0, 0);
        const styles = self.context.table_styles orelse return self.figureUnavailableAt("closed_ready_profile", tracked.bytes, 0, 0);
        if (current.scope != owed or validClosedReadyFigures(owed, current.source, styles) == null or
            choice.content != .image or observed == null)
            return self.figureUnavailableAt("closed_ready_operation", tracked.bytes, 0, 0);
    }
    fn literalDivPageStyleRootForTag(self: *const Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement) ?*const table_style_profile.TextElement {
        if (self.literalDivContextForTag(tag)) |known| if (self.literalDivParent(known, parent))
            return self.pageStyleDomain().?.scope.page_style_root;
        return self.pageStyleRootForTag(tag, parent);
    }

    const FigureWikiNativeFont = struct { style: Style, formatting: SpanFlags };

    const ObservedFigureCaptionSession = struct {
        operation: FigureStyleOperation,
        preflight: ?struct {
            profile: *const table_style_profile.Profile,
            scope: *const table_style_profile.BoundedTextClassScope,
            root: *const table_style_profile.TextElement,
            style: Style,
        } = null,
        italic: ?Style = null,
        bold: ?Style = null,
        links: []ObservedFigureCaptionLink = &.{},
        link_style: ?Style = null,
        nodes: []const ObservedFigureCaptionNode = &.{},
    };

    const ObservedFigureCaptionNode = struct { source: FigureCaptionSourceNode, style: Style };

    const ObservedFigureCaptionLink = struct { source: []const u8, seen: bool = false, style: ?Style = null };

    const ObservedReadyCaptionShape = struct { italic: usize = 0, bold: usize = 0 };

    const FigureWikiFontWitness = struct {
        stage: []const u8 = "table.not_entered",
        native: ?FigureWikiNativeFont = null,
        table_element: ?*const table_style_profile.TextElement = null,
        row_element: ?*const table_style_profile.TextElement = null,
        cell_element: ?*const table_style_profile.TextElement = null,
        tracked: ?MissingText = null,
        source: []const u8 = "",
        opening_start: usize = 0,
        visible: bool = false,
        observation: bool = false,
        table_depth: usize = 0,
        ordinary: bool = false,
        ordinary_flags: u64 = 0,
        body_font: FormattingAttributes = .{},
        domain: bool = false,
        origin: ?f32 = null,
        first_cell: bool = false,
        hidden: bool = false,
        raw_cell: []const u8 = "",
        row_attrs: []const u8 = "",
        cell_attrs: []const u8 = "",
        context_index: usize = 0,
    };

    const FigureWikiTableFontSource = struct {
        table: []const u8,
        attrs: []const u8,
        native: FigureWikiNativeFont,
        element: *const table_style_profile.TextElement,
        origin: f32,
        first_cell: ?[]const u8 = null,
    };

    const FigureWikiCellFontSource = struct {
        table: *const FigureWikiTableFontSource,
        row_attrs: []const u8,
        cell_attrs: []const u8,
        cell: []const u8,
        row_element: *const table_style_profile.TextElement,
        element: *const table_style_profile.TextElement,

        // This capability belongs to the current renderer and cannot cross a
        // JSON boundary. Optional null remains an ordinary data-only value.
        pub fn jsonStringify(_: @This(), _: anytype) std.Io.Writer.Error!void {
            return error.WriteFailed;
        }

        pub fn jsonParse(_: std.mem.Allocator, _: anytype, _: std.json.ParseOptions) !@This() {
            return error.UnexpectedToken;
        }

        pub fn jsonParseFromValue(_: std.mem.Allocator, _: std.json.Value, _: std.json.ParseOptions) !@This() {
            return error.UnexpectedToken;
        }
    };

    fn observedFigurePlainCaptionText(text_value: []const u8) bool {
        if (!std.unicode.utf8ValidateSlice(text_value) or std.mem.indexOfAny(u8, text_value, "\x00\r\n\t<>{}&[]|'") != null or
            std.mem.indexOf(u8, text_value, "__") != null or std.mem.indexOf(u8, text_value, "://") != null) return false;
        if (magicLinkStart(text_value, 0) != null) return false;
        var iterator: ir.InlineIterator = .{ .input = text_value, .renderer_boundaries = true };
        while (iterator.next()) |node| if (node.kind != .text) return false;
        return true;
    }

    fn observedReadyCaptionPlainText(value: []const u8) bool {
        if (!observedFigurePlainCaptionText(value)) return false;
        for (0..value.len) |at| if (magicLinkStart(value, at) != null) return false;
        return true;
    }

    fn observedReadyCaptionSource(self: *Renderer, caption: []const u8) Error!?FigureCaptionSourceShape {
        return self.observedFigureCaptionSource(caption, true, false);
    }

    fn observedReadyCaptionSourceBody(self: *Renderer, body: []const u8, parent: ?u32, in_link: bool,
        depth: usize, nodes: *std.ArrayList(FigureCaptionSourceNode), root_text: *bool, allow_categories: bool, allow_local_links: bool) Error!bool
    {
        if (depth > 8) return false;
        var at: usize = 0;
        // The captured root text can begin with the same literal numeric
        // prefix admitted by the flat Figure grammar. Nested/link bodies do
        // not inherit this permission; all remaining bytes use the old parser.
        if (parent == null and !in_link) if (observedFigureNumericCaptionPrefixEnd(body)) |end| {
            if (end == body.len) return false;
            root_text.* = true;
            at = end;
        };
        while (at < body.len) {
            var kind: FigureCaptionSourceKind = undefined;
            var opening: []const u8 = undefined;
            var inner: []const u8 = undefined;
            var end: usize = undefined;
            var classes: []const u8 = "";
            var href: []const u8 = "";
            var quote = false;
            if (body[at] == '<') {
                const tag = syntax.tagAt(body, at) orelse return false;
                if (tag.closing or tag.html_pre) return false;
                kind = if (tag.is("i")) .italic else if (tag.is("b")) .bold else
                    if (tag.is("span")) .span else if (tag.is("br")) .line_break else return false;
                opening = body[at..tag.end];
                if (kind == .span and trim(tag.attrs).len != 0) {
                    var attrs: FigureCaptionAuthoredInventory = .{};
                    if (!attrs.span(tag) or attrs.has_language) return false;
                    classes = tag.attr("class") orelse return false;
                } else if (trim(tag.attrs).len != 0) return false;
                if (kind == .line_break) {
                    inner = ""; end = tag.end;
                } else {
                    if (tag.self_closing) return false;
                    const pair = syntax.matchingTag(body, tag) orelse return false;
                    const close = syntax.tagAt(body, pair.inner_end) orelse return false;
                    if (!close.closing or close.self_closing or trim(close.attrs).len != 0 or
                        !std.ascii.eqlIgnoreCase(close.name, tag.name)) return false;
                    inner = body[tag.end..pair.inner_end]; end = pair.end;
                }
            } else if (std.mem.startsWith(u8, body[at..], "''")) {
                var count: usize = 2;
                while (at + count < body.len and body[at + count] == '\'') : (count += 1) {}
                if (count != 2 and count != 3) return false;
                const marker = body[at..][0..count];
                const close = std.mem.indexOfPos(u8, body, at + count, marker) orelse return false;
                if (close == at + count or (close + count < body.len and body[close + count] == '\'')) return false;
                kind = if (count == 2) .italic else .bold;
                opening = marker; inner = body[at + count..close]; end = close + count; quote = true;
            } else if (std.mem.startsWith(u8, body[at..], "[[")) {
                if (in_link) return false;
                var iterator: ir.InlineIterator = .{ .input = body, .cursor = at,
                    .renderer_boundaries = true, .link_trail = self.context.link_trail };
                const node = iterator.next() orelse return false;
                if (node.kind != .link or node.link_empty_label or node.link_label_restored_close or node.trail.len != 0 or
                    iterator.cursor <= at or node.target.len == 0 or trim(node.target).len != node.target.len or
                    !safeInternalTarget(node.target) or std.mem.indexOfAny(u8, node.target, "[]{}<>|&'\r\n") != null) return false;
                end = iterator.cursor;
                if (node.target[0] != ':' and self.namespaceOfTarget(node.target) == 14) {
                    if (!allow_categories) return false;
                    // Normal caption parsing retains this metadata operation;
                    // it emits no element, text or action into the observed tree.
                    if (node.link_has_pipe and !observedReadyCaptionPlainText(node.text)) return false;
                    at = end; continue;
                }
                if (node.text.len == 0 or trim(node.text).len != node.text.len) return false;
                if (!observedReadyCaptionPlainText(node.text) and !figureCaptionBoldLocalLabel(node.text) and
                    !figureCaptionItalicLocalLabel(node.text)) return false;
                const destination = try self.interwikiDestination(node.target, 0);
                if (destination.external or destination.interwiki) {
                    if (!node.link_has_pipe or !self.figureCaptionRemoteTarget(node.target) or
                        !destination.external or !destination.interwiki or !safeUrl(destination.target)) return false;
                    href = destination.target;
                } else {
                    // This additional Missing-caption arm is an ordinary local
                    // title, not namespace/interwiki/fragment or redlink policy.
                    // The exact captured href must independently agree below.
                    if (!allow_local_links or self.namespaceOfTarget(node.target) != null or
                        std.mem.indexOfAny(u8, node.target, ":#?%\\") != null or
                        !std.mem.eql(u8, destination.target, node.target)) return false;
                    href = try std.mem.concat(self.a, u8, &.{ "/wiki/", try self.interwikiUrlPart(node.target) });
                }
                kind = .link; opening = body[at..end]; inner = node.text;
            } else {
                const start = at;
                at += 1;
                while (at < body.len and std.mem.indexOfScalar(u8, "<['", body[at]) == null) : (at += 1) {}
                const text_value = body[start..at];
                if (!observedReadyCaptionPlainText(text_value)) return false;
                if (parent) |index| nodes.items[index].has_text = true else root_text.* = true;
                continue;
            }
            if (nodes.items.len == 64) return false;
            const index: u32 = @intCast(nodes.items.len);
            try nodes.append(self.a, .{ .kind = kind, .parent = parent, .opening = opening,
                .classes = classes, .href = href, .quote = quote });
            if (kind != .line_break and !try self.observedReadyCaptionSourceBody(inner, index,
                in_link or kind == .link, depth + 1, nodes, root_text, allow_categories, allow_local_links)) return false;
            at = end;
        }
        return true;
    }

    fn observedReadyCaptionSourceMatches(shape: FigureCaptionSourceShape,
        context: table_style_profile.FigureObservedContext) bool
    {
        if (!table_style_profile.figureObservedContextValid(context) or
            context.nodes[context.caption].has_text != shape.has_text) return false;
        var mapped: [64]u32 = undefined;
        var count: usize = 0;
        for (context.nodes, 0..) |node, index| {
            if (index <= context.caption) continue;
            var ancestor = node.parent;
            var remaining: usize = 512;
            var owned = false;
            while (ancestor) |parent| {
                if (remaining == 0 or parent >= index) return false;
                remaining -= 1;
                if (parent == context.caption) { owned = true; break; }
                ancestor = context.nodes[parent].parent;
            }
            if (!owned) continue;
            if (count == shape.nodes.len or count == mapped.len) return false;
            const source_node = shape.nodes[count];
            const expected_parent = if (source_node.parent) |parent| blk: {
                if (parent >= count) return false;
                break :blk mapped[parent];
            } else context.caption;
            const expected_tag: []const u8 = switch (source_node.kind) {
                .italic => "i", .bold => "b", .span => "span", .line_break => "br", .link => "a",
            };
            if (node.parent != expected_parent or !std.ascii.eqlIgnoreCase(node.tag, expected_tag) or
                node.has_text != source_node.has_text) return false;
            if (source_node.kind == .link) {
                var seen_href = false;
                for (node.attributes) |attribute| {
                    if (std.ascii.eqlIgnoreCase(attribute.name, "href")) {
                        if (!std.mem.eql(u8, attribute.value, source_node.href)) return false;
                        seen_href = true;
                    } else if (std.ascii.eqlIgnoreCase(attribute.name, "class")) {
                        if (!std.mem.eql(u8, attribute.value, if (std.mem.startsWith(u8, source_node.href, "/wiki/")) "" else "extiw")) return false;
                    } else if (!std.ascii.eqlIgnoreCase(attribute.name, "title")) return false;
                }
                if (!seen_href) return false;
            } else {
                var seen_class = false;
                for (node.attributes) |attribute| {
                    if (!std.ascii.eqlIgnoreCase(attribute.name, "class") or source_node.kind != .span or
                        !std.mem.eql(u8, attribute.value, source_node.classes)) return false;
                    seen_class = true;
                }
                if (seen_class != (source_node.classes.len != 0)) return false;
            }
            mapped[count] = @intCast(index); count += 1;
        }
        return count == shape.nodes.len;
    }

    fn observedReadyCaptionOperationShape(caption: []const u8) ?ObservedReadyCaptionShape {
        // The original source operation retains its length and control-byte
        // domain. Only literal edge spaces are absent from the visible shape.
        if (caption.len > 4096) return null;
        return observedReadyCaptionShape(std.mem.trim(u8, caption, " "));
    }

    // This is the existing literal numeric caption prefix. It creates no
    // action or element and is shared by the flat and structured caption scans.
    fn observedFigureNumericCaptionPrefixEnd(caption: []const u8) ?usize {
        if (caption.len == 0 or caption[0] != '[') return null;
        var cursor: usize = 1;
        while (cursor < caption.len and std.ascii.isDigit(caption[cursor])) : (cursor += 1) {}
        if (cursor == 1 or cursor + 1 >= caption.len or caption[cursor] != ']' or caption[cursor + 1] != ' ') return null;
        return cursor + 2;
    }

    fn observedReadyCaptionShape(caption: []const u8) ?ObservedReadyCaptionShape {
        if (caption.len == 0 or caption.len > 4096 or !std.unicode.utf8ValidateSlice(caption) or
            trim(caption).len != caption.len or std.mem.indexOfAny(u8, caption, "\x00\r\n\t{}&|=:") != null or
            std.mem.indexOf(u8, caption, "__") != null or std.mem.indexOf(u8, caption, "://") != null or
            std.mem.indexOf(u8, caption, "//") != null) return null;
        var start: usize = 0;
        if (caption[0] == '[') start = observedFigureNumericCaptionPrefixEnd(caption) orelse return null;
        if (std.mem.indexOfAny(u8, caption[start..], "[]") != null) return null;
        if (start == caption.len or std.mem.indexOfScalar(u8, "*#;", caption[start]) != null) return null;
        var result: ObservedReadyCaptionShape = .{};
        var active: ?usize = null;
        var opening_end: usize = 0;
        var cursor = start;
        while (cursor < caption.len) {
            if (caption[cursor] == '<') {
                const tag = syntax.tagAt(caption, cursor) orelse return null;
                if (tag.self_closing or std.mem.endsWith(u8, caption[cursor..tag.end], "/>") or
                    trim(tag.attrs).len != 0 or (!tag.is("i") and !tag.is("b"))) return null;
                // These are the same classless direct I/B children counted in
                // the captured caption graph. No nested or mixed formatting
                // is admitted by this initial flat caption contract.
                const kind: usize = if (tag.is("i")) 4 else 5;
                if (tag.closing) {
                    if (active == null or active.? != kind or cursor == opening_end) return null;
                    active = null;
                } else {
                    if (active != null or result.italic + result.bold == 16) return null;
                    if (kind == 4) result.italic += 1 else result.bold += 1;
                    active = kind; opening_end = tag.end;
                }
                cursor = tag.end;
                continue;
            }
            if (caption[cursor] == '>') return null;
            if (caption[cursor] != '\'') { cursor += 1; continue; }
            var end = cursor;
            while (end < caption.len and caption[end] == '\'') : (end += 1) {}
            const count = end - cursor;
            if (count != 2 and count != 3) return null;
            if (active) |kind| {
                if (kind != count or cursor == opening_end) return null;
                active = null;
            } else {
                if (result.italic + result.bold == 16) return null;
                if (count == 2) result.italic += 1 else result.bold += 1;
                active = count; opening_end = end;
            }
            cursor = end;
        }
        return if (active == null) result else null;
    }

    // Called before context-dependent inline/figure choices. A selected page
    // obligation cannot disappear merely because a later choice declines.
    fn potentialBlockMediaOptions(self: *Renderer, raw: []const u8, file: []const u8) bool {
        const mode = mediaOptionMode(file, false);
        var seen_format = false;
        var format: ?[]const u8 = null;
        var horizontal: ?[]const u8 = null;
        var at: usize = 0;
        while (at <= raw.len) {
            const end = syntax.delimiter(raw, "|", at) orelse raw.len;
            if (self.mediaOption(trim(raw[at..end]), mode, &seen_format)) |option| {
                if (oneOf(option.id, &.{ "img_thumbnail", "img_framed", "img_manualthumb", "img_frameless" })) format = option.id;
                if (horizontal == null and oneOf(option.id, &.{ "img_left", "img_right", "img_center", "img_none" })) horizontal = option.id;
            }
            if (end == raw.len) break;
            at = end + 1;
        }
        if (format) |selected| return std.mem.eql(u8, selected, "img_frameless");
        return horizontal != null;
    }
    fn figureBlockSourceOptions(self: *Renderer, raw: []const u8, file: []const u8) Error!?FigureBlockSourceOptions {
        if (raw.len == 0 or raw.len > 8192 or std.mem.indexOfAny(u8, raw, "{}<>[]\x00\r\n") != null or
            media_types.referencedKind(file) != .image) return null;
        const mode = mediaOptionMode(file, false);
        if (mode != .image and mode != .svg) return null;
        var image: presentation_types.InlineImage = .{ .file = file };
        var seen_format = false;
        var horizontal: ?[]const u8 = null;
        var link_value: ?[]const u8 = null;
        var alternative: ?[]const u8 = null;
        var at: usize = 0;
        while (at <= raw.len) {
            const end = syntax.delimiter(raw, "|", at) orelse raw.len;
            const part = trim(raw[at..end]);
            if (self.mediaOption(part, mode, &seen_format)) |option| {
                if (std.mem.eql(u8, option.id, "img_width")) {
                    try inlineImageDimensions(option.value orelse return null, &image);
                } else if (oneOf(option.id, &.{ "img_left", "img_right", "img_center", "img_none" })) {
                    if (horizontal == null) horizontal = option.id;
                } else if (std.mem.eql(u8, option.id, "img_link")) {
                    link_value = option.value orelse "";
                } else if (std.mem.eql(u8, option.id, "img_alt")) {
                    alternative = option.value orelse "";
                } else return null;
            } else if (part.len != 0) return null;
            if (end == raw.len) break;
            at = end + 1;
        }
        if (seen_format or !std.mem.eql(u8, horizontal orelse return null, "img_none") or
            trim(link_value orelse return null).len != 0 or trim(alternative orelse return null).len != 0 or
            (image.width_px == null and image.height_px == null)) return null;
        return .{ .width_px = image.width_px, .height_px = image.height_px };
    }

    fn selectedCapturedOuterAncestors(self: *const Renderer, outer: *[max_depth * 2]*const table_style_profile.TextElement) ?[]const *const table_style_profile.TextElement {
        const domain = self.pageStyleDomain() orelse return null;
        const complete_root = domain.scope.page_style_complete_root orelse return null;
        const alternate_root = complete_root.alternative_ancestry orelse return null;
        const Node = table_style_profile.TextElement;
        var outer_count: usize = 0;
        var primary: ?*const Node = complete_root;
        var alternate: ?*const Node = alternate_root;
        // Membership is pointer-exact in the selected Book's paired chains.
        // These nodes own captured ancestors, not source-opening anchors.
        while (primary) |node| {
            const other = alternate orelse return null;
            if (outer_count + 2 > outer.len or node == other or
                node.page_style_root != complete_root or other.page_style_root != alternate_root or
                node.alternative_ancestry != other or other.alternative_ancestry != null or
                !node.ancestry_complete or !node.physical_ancestry_complete or
                !other.ancestry_complete or !other.physical_ancestry_complete or
                !std.ascii.eqlIgnoreCase(node.tag, other.tag)) return null;
            for (outer[0..outer_count]) |prior| if (prior == node or prior == other) return null;
            outer[outer_count] = node; outer[outer_count + 1] = other; outer_count += 2;
            primary = node.parent; alternate = other.parent;
        }
        if (alternate != null) return null;
        return outer[0..outer_count];
    }

    fn blockMediaNativeAncestorsCurrent(self: *const Renderer, initial: *const table_style_profile.TextElement) bool {
        const domain = self.pageStyleDomain() orelse return false;
        const Node = table_style_profile.TextElement;
        var outer_storage: [max_depth * 2]*const Node = undefined;
        const outer = self.selectedCapturedOuterAncestors(&outer_storage) orelse return false;
        const Frame = struct { node: *const Node, edge: u2 = 0 };
        var stack: [max_depth * 2]Frame = undefined;
        var depth: usize = 1; stack[0] = .{ .node = initial };
        var completed: [max_depth * 2]*const Node = undefined;
        var completed_count: usize = 0;
        var admitted: usize = 0;
        while (depth != 0) {
            const frame = &stack[depth - 1];
            if (frame.edge == 0) {
                for (stack[0 .. depth - 1]) |active| if (active.node == frame.node) return false;
                var done = false;
                for (completed[0..completed_count]) |prior| if (prior == frame.node) { done = true; break; };
                if (done) { depth -= 1; continue; }
                if (admitted == completed.len) return false;
                admitted += 1;
                var captured = false;
                for (outer) |known| if (known == frame.node) { captured = true; break; };
                if (!captured) {
                    const node = frame.node;
                    if (!self.currentAncestorScope(node) or node.page_style_root != domain.scope.page_style_root or
                        !node.ancestry_complete or !node.physical_ancestry_complete) return false;
                    const proof = node.source_literal_div orelse return false;
                    var issued = false;
                    for (domain.scope.source_literal_divs) |*known| if (known == proof) { issued = true; break; };
                    const current = node.source_literal_div_current orelse return false;
                    const original = self.registeredCaptionOriginal(current) orelse return false;
                    const binding = self.source_element_binding orelse return false;
                    const range = proof.range;
                    if (!issued or proof.html_cell_parent != null or range.anchor_start >= range.anchor_end or range.anchor_end > domain.source.len) return false;
                    const owner = binding.ownerRange(range.anchor_start, range.anchor_end - range.anchor_start) orelse return false;
                    const tag = syntax.tagAt(current, 0) orelse return false;
                    const anchor = node.page_style_anchor orelse return false;
                    if (!tag.is("div") or tag.closing or tag.self_closing or tag.html_pre or
                        node.source_key != @intFromPtr(tag.name.ptr) or node.tag.ptr != tag.name.ptr or
                        original.ptr != domain.source[range.anchor_start..].ptr or original.len != owner.len or
                        binding.originalRange(anchor) != range.anchor_start or
                        !std.mem.eql(u8, current, owner) or !noLiParentSourceRange(binding.owner, owner)) return false;
                    const start = @intFromPtr(owner.ptr) - @intFromPtr(binding.owner.bytes.ptr);
                    if (!binding.projection.ordinaryRange(binding.owner, start, start + owner.len) or
                        !binding.projection.ordinaryRange(binding.projection.original, range.anchor_start, range.anchor_end)) return false;
                }
            }
            if (frame.edge < 2) {
                const next = if (frame.edge == 0) frame.node.parent else frame.node.alternative_ancestry;
                frame.edge += 1;
                if (next) |node| {
                    if (depth == stack.len) return false;
                    stack[depth] = .{ .node = node }; depth += 1;
                }
            } else {
                completed[completed_count] = frame.node; completed_count += 1; depth -= 1;
            }
        }
        return true;
    }
    fn blockMediaEmissionAllowed(self: *const Renderer, style: Style) bool {
        return !style.heading and !style.code and style.kind == .text and !style.preserve_whitespace and
            !self.pre_block and !self.parsed_pre and self.media_action_depth == 0 and self.body_link_target.len == 0 and
            self.poem_depth == 0 and (self.media_depth == 0 or self.figure_caption_depth != 0) and !self.image_block_suppressed and
            (self.bidi_scope_depth == 0 or self.active_bidi_capture != null) and
            (if (self.semantic_capture) |hints| hints.figure_blocks else false);
    }
    fn closedReadyBlockMediaOwed(self: *Renderer, token: []const u8) Error!bool {
        const selected = if (self.context.figure_sizing) |sizing| sizing.text_class_scope else null;
        const owed = self.required_ready_figure_scope orelse if (selected) |value|
            if (value.scope.closed_ready_figures != null) value.scope else return false
        else return false;
        self.required_ready_figure_scope = owed;
        const current = selected orelse return self.figureUnavailableAt("block_ready.detached_scope", token, 0, 0);
        const styles = self.context.table_styles orelse return self.figureUnavailableAt("block_ready.detached_profile", token, 0, 0);
        if (current.scope != owed or validClosedReadyFigures(owed, current.source, styles) == null)
            return self.figureUnavailableAt("block_ready.stale_scope", token, 0, 0);
        return true;
    }
    fn observedBlockMediaNativeParent(self: *Renderer, operation: FigureStyleOperation,
        context: table_style_profile.FigureObservedContext, parent: Style) Error!bool
    {
        if (operation.layout_kind != .block_media or context.layout_kind != .block_media or
            self.observedFigureNativeFontOrigin(parent) == null or !table_style_profile.figureObservedContextValid(context)) return false;
        const selected = self.observedFigureCanonicalOperation(operation) orelse return false;
        const binding = self.source_element_binding orelse return false;
        const observed_binding = binding.projection.observedOriginal() orelse return false;
        if (binding.scope != selected.scope or observed_binding.scope != selected.scope or
            observed_binding.source.ptr != selected.selected.ptr or observed_binding.source.len != selected.selected.len) return false;
        var observed_index = context.nodes[context.frame].parent orelse return false;
        var native = parent.text_element orelse return false;
        if (!self.blockMediaNativeAncestorsCurrent(native)) return false;
        var child_start = @intFromPtr(operation.token.ptr) - @intFromPtr(selected.selected.ptr);
        var child_end = child_start + operation.token.len;
        var remaining: usize = max_depth;
        while (observed_index != context.root) {
            if (remaining == 0) return false; remaining -= 1;
            const observed = context.nodes[observed_index];
            const proof = native.source_literal_div orelse return false;
            var issued = false;
            for (selected.scope.source_literal_divs) |*known| if (known == proof) { issued = true; break; };
            const range = proof.range;
            if (!issued or proof.html_cell_parent != null or !std.ascii.eqlIgnoreCase(observed.tag, "div") or !std.ascii.eqlIgnoreCase(native.tag, "div") or
                !native.physical_ancestry_complete or !native.ancestry_complete or
                native.page_style_root != selected.scope.page_style_root or !self.currentAncestorScope(native) or
                range.anchor_start >= range.anchor_end or range.anchor_end > selected.selected.len or
                child_start <= range.anchor_start or child_end >= range.anchor_end) return false;
            const current = native.source_literal_div_current orelse return false;
            const current_tag = syntax.tagAt(current, 0) orelse return false;
            if (native.source_key != @intFromPtr(current_tag.name.ptr) or native.tag.ptr != current_tag.name.ptr) return false;
            const original = self.registeredCaptionOriginal(current) orelse return false;
            const owner = binding.ownerRange(range.anchor_start, range.anchor_end - range.anchor_start) orelse return false;
            if (binding.originalRange(owner) != range.anchor_start or
                original.ptr != selected.selected[range.anchor_start..].ptr or original.len != owner.len or
                current.len != owner.len or !std.mem.eql(u8, current, owner)) return false;
            const owner_start = @intFromPtr(owner.ptr) - @intFromPtr(binding.owner.bytes.ptr);
            if (!noLiParentSourceRange(binding.owner, owner) or
                !binding.projection.ordinaryRange(binding.owner, owner_start, owner_start + owner.len) or
                !binding.projection.ordinaryRange(binding.projection.original, range.anchor_start, range.anchor_end)) return false;
            const tag = syntax.tagAt(original, 0) orelse return false;
            const pair = syntax.matchingTag(original, tag) orelse return false;
            const anchor = native.page_style_anchor orelse return false;
            if (!tag.is("div") or tag.closing or tag.self_closing or tag.html_pre or pair.end != original.len or
                binding.originalRange(anchor) != range.anchor_start or
                !std.mem.eql(u8, current_tag.attrs, tag.attrs)) return false;
            if (!try self.observedWikiOwnAttributesEqual(tag.attrs, observed)) return false;
            // The innermost source DIV contains this complete File alone. The
            // outer literal-DIV chain owns its independently proved children;
            // no new allocation or sibling ordinal is inferred here.
            if (child_start == @intFromPtr(operation.token.ptr) - @intFromPtr(selected.selected.ptr)) {
                const local_start = child_start - range.anchor_start;
                const local_end = child_end - range.anchor_start;
                if (local_start < tag.end or local_end > pair.inner_end or
                    trim(original[tag.end..local_start]).len != 0 or trim(original[local_end..pair.inner_end]).len != 0) return false;
            }
            const next_observed = observed.parent orelse return false;
            if (proof.parent_start) |start| {
                const next = native.parent orelse return false;
                const next_proof = next.source_literal_div orelse return false;
                if (next_proof.range.anchor_start != start or next_observed == context.root) return false;
                native = next;
            } else {
                if (next_observed != context.root) return false;
                native = native.parent orelse return false;
            }
            child_start = range.anchor_start; child_end = range.anchor_end; observed_index = next_observed;
        }
        return native == selected.scope.page_style_complete_root or native == selected.scope.page_style_root;
    }
    fn observedBlockMediaStyle(self: *Renderer, tracked: MissingText, caption: []const u8, file: []const u8) Error!?FigureStyleObservation {
        const sizing = self.context.figure_sizing orelse return null;
        const callback = sizing.resolve_figure_style_fn orelse return null;
