    fn inlineMissingOriginalSlice(self: *const Renderer, domain: AuthoredElementSourceDomain, part: []const u8) ?[]const u8 {
        const selected = self.figureStyleSourceDomain() orelse return null;
        if (selected.scope != domain.scope or selected.selected.ptr != domain.source.ptr or selected.selected.len != domain.source.len) return null;
        if (self.authoredElementOriginalSlice(domain, part)) |original| return original;
        // Normal paragraph quote processing copies the literal File token and
        // its HTML parents. Reuse only those live, unchanged copied intervals.
        var result: ?[]const u8 = null;
        for ([_]?*const QuoteClassSource{ self.figure_caption_quote_source, self.quote_class_source }) |initial| {
            var next = initial;
            var remaining: usize = max_depth + 1;
            while (next) |quote| {
                if (remaining == 0) return null;
                remaining -= 1; next = quote.parent;
                if (!self.figureStyleQuoteDomainCurrent(selected, quote)) continue;
                const copied = quote.map.copiedOriginal(part) orelse continue;
                const original = self.figureStyleQuoteOriginalSlice(selected, quote, copied) orelse continue;
                if (result) |prior| if (prior.ptr != original.ptr or prior.len != original.len) return null;
                result = original;
            }
        }
        return result;
    }

    fn inlineMissingOpeningCurrent(self: *const Renderer, domain: AuthoredElementSourceDomain,
        current: syntax.Tag, original: []const u8) bool
    {
        const expected = syntax.tagAt(original, 0) orelse return false;
        if (expected.end != original.len or current.closing or current.self_closing or expected.closing or expected.self_closing or
            !std.ascii.eqlIgnoreCase(current.name, expected.name)) return false;
        const name = self.inlineMissingOriginalSlice(domain, current.name) orelse return false;
        if (name.ptr != expected.name.ptr or name.len != expected.name.len) return false;
        if (current.attrs.len == 0) return expected.attrs.len == 0;
        const attrs = self.inlineMissingOriginalSlice(domain, current.attrs) orelse return false;
        return attrs.ptr == expected.attrs.ptr and attrs.len == expected.attrs.len;
    }

    const HiddenInlineMissing = struct { token: []const u8, file: []const u8 };

    // Reuse the normal selected operation, including its exact source and
