            original.kind != .text or original.provenance != .parsed or self.body_link_target.len != 0 or
            self.poem_depth != 0 or self.media_depth != 0 or self.media_action_depth != 0 or
            original.heading or original.code or original.preserve_whitespace or self.image_block_suppressed or
            self.active_bidi_capture != null or self.bidi_scope_depth != 0) return null;
        const table = self.inline_table_boundaries orelse return null;
        const table_opening = table.source_opening orelse return null;
        const row_opening = table.row_opening orelse return null;
        if (tag.end > pair.inner_end or pair.inner_end > tracked.bytes.len or pair.end > tracked.bytes.len) return null;
        const body = try missingSlice(self.a, tracked, tracked.bytes[tag.end..pair.inner_end]);
        if (body.lost_missing_range or body.generated_source != null or body.ranges.len != 0) return null;
        const token = trim(body.bytes);
