        const colon = std.mem.indexOfScalar(u8, target, ':') orelse return null;
        const identity = (try self.canonicalMediaFile(target[colon + 1 ..])) orelse return null;
        const file = identity[0 .. std.mem.indexOfScalar(u8, identity, '#') orelse identity.len];
        const provider = self.context.figure_sizing orelse return null;
        const callback = provider.resolve_inline_missing_fn orelse return null;
        const callback_context = provider.figure_style_ctx orelse return null;
        const domain = self.observedOperationSourceDomain() orelse return null;
        const source_token = self.inlineMissingOriginalSlice(domain, token) orelse return null;
        const observed = (try callback(callback_context, self.a, .{ .source = domain.source, .token = source_token, .file = file })) orelse return null;
        const source_context = provider.source_context orelse return null;
