        const options = inlineMissingOptions(node.text, self.context) orelse return null;
        if (options.width != observed.data_width or !std.mem.eql(u8, options.label, observed.label)) return null;
        const selected_parent = observed.profile.page_style_parent orelse return null;
        for (observed.contexts) |context| {
