        const node = iterator.next() orelse return self.figureUnavailable();
        if (node.kind != .link or iterator.cursor != token.len or node.trail.len != 0 or !node.link_has_pipe or
            node.link_empty_label or node.link_label_restored_close) return self.figureUnavailable();
        const options = inlineMissingOptions(node.text, self.context) orelse return self.figureUnavailableAt("inline_missing.options", token, 0, 0);
        if (options.width != observed.data_width or !std.mem.eql(u8, options.label, observed.label)) return self.figureUnavailable();
        const selected_parent = observed.profile.page_style_parent orelse return self.figureUnavailable();
        const page = self.figurePageLanguageContext();
        var language: ?[]const u8 = null;
