            catch |err| return self.authoredElementQueryError(err)) orelse return self.figureUnavailableAt("inline_missing.cascade", token, 0, 0);
        var action = original; action.kind = .external_link; action.target = observed.href;
        var style = observedFigureMediaStyle(action, computed.font,
