                // Exact official spelling is retained if a nested protected
                // body later displays the wrapper rather than parsing it.
                try colon.append(self.a, MissingText.untracked(try std.fmt.allocPrint(self.a, "<span class=\"mw-poem-indented\" style=\"display: inline-block; margin-inline-start: {d}em;\">", .{count})));
                try colon.appendSlice(self.a, source, pos + count, end);
                try colon.append(self.a, MissingText.untracked("</span>"));
            } else try colon.appendSlice(self.a, source, pos, end);
            if (end < input.len) try colon.appendSlice(self.a, source, end, end + 1);
            pos = if (end < input.len) end + 1 else end;
        }
        const transformed = try colon.finish(self.a);
        defer self.a.free(transformed.bytes);
        defer self.a.free(transformed.ranges);
        defer self.a.free(transformed.literal_curly_ranges);
        pos = if (starts(transformed.bytes, "\n")) 1 else 0;
        var limit = transformed.bytes.len;
        if (limit > pos and transformed.bytes[limit - 1] == '\n') limit -= 1;
        var out: missing_dependency.Builder = .{};
        defer out.deinit(self.a);
        while (pos < limit) {
            const end = std.mem.indexOfScalarPos(u8, transformed.bytes[0..limit], pos, '\n') orelse limit;
            const line = transformed.bytes[pos..end];
            var spaces: usize = 0;
            while (spaces < line.len and line[spaces] == ' ') : (spaces += 1) {}
            for (0..spaces) |_| try out.append(self.a, MissingText.untracked("&#160;"));
            try out.appendSlice(self.a, transformed, pos + spaces, end);
            if (end < limit) {
                try out.append(self.a, MissingText.untracked(try self.poemToken(if (std.mem.eql(u8, line, "----")) .soft_space else .line_break, 0, &digest)));
                try out.appendSlice(self.a, transformed, end, end + 1);
            }
            pos = if (end < limit) end + 1 else end;
        }
        return out.finish(self.a);
    }
    fn poem(self: *Renderer, input: []const u8, style: Style, depth: usize) Error!void {
        return self.poemWithPhase(input, style, depth, false);
    }
    fn poemWithPhase(self: *Renderer, input: []const u8, style: Style, depth: usize, prepared: bool) Error!void {
        if (self.poem_depth >= max_depth or depth >= max_depth) {
            self.fallbacks.render_limit = true;
            try self.protectedLiteral(input, style);
            return;
        }
        if (self.poem_authored_token or self.poemHasUnregisteredItem(input)) {
            // An authored token-like spelling is never interpreted as an item.
            self.fallbacks.unsupported_element = true;
            try self.protectedLiteral(input, style);
            return;
        }
        const projected = if (prepared) input else self.poemProjection(input) catch |err| switch (err) {
            error.RenderLimit => {
                self.fallbacks.render_limit = true;
                try self.protectedLiteral(input, style);
                return;
            },
            else => return err,
        };
        const previous_depth = self.poem_depth;
        const previous_direction = self.poem_direction;
        const previous_style = self.poem_base_style;
        const previous_indent = self.poem_line_indent;
        const previous_body_link_target = self.body_link_target;
        if (self.spans.items.len != 0 and self.spans.items[self.spans.items.len - 1].kind != .line_break)
            try self.lineBreak(.{});
        self.poem_depth += 1;
        self.poem_direction = style.direction;
        self.poem_base_style = style;
        self.poem_base_style.poem_indent = null;
        self.poem_base_style.poem_independent_parse = true;
        self.poem_line_indent = 0;
        self.body_link_target = "";
        defer {
            self.poem_depth = previous_depth;
            self.poem_direction = previous_direction;
            self.poem_base_style = previous_style;
            self.poem_line_indent = previous_indent;
            self.body_link_target = previous_body_link_target;
        }
        // The existing block parser owns lists, headings, rules and tables.
        // Span-only containment flattens their preserved reading order; its
        // non-equivalent geometry remains explicitly diagnosed below.
        const blocks = try self.renderBody(projected);
        for (blocks, 0..) |block_value, index| {
            if (index != 0 and self.spans.items.len != 0 and self.spans.items[self.spans.items.len - 1].kind != .line_break)
                try self.lineBreak(style);
            if (block_value.kind == .rule) {
                self.fallbacks.unsupported_element = true;
                try self.text("────────", style);
                try self.lineBreak(style);
                continue;
            }
            if (block_value.kind == .table or block_value.depth != 0 or block_value.kind == .heading)
                self.fallbacks.unsupported_element = true;
            if (block_value.feature) |feature| {
                self.fallbacks.unsupported_element = true;
                // Swatch tables already retain the hex text in their cell.
                // Span-only poem projection cannot show the visual feature,
                // but must not invent a duplicate copy of its text fallback.
                if (!(block_value.kind == .table and block_value.table != null and std.mem.eql(u8, feature.kind, "color_swatch")))
                    try self.text(feature.data, style);
            }
            if (block_value.list_path.len != 0) switch (block_value.list_path[block_value.list_path.len - 1]) {
                '*' => try self.text("• ", style),
                '#' => {
                    try self.text(block_value.number, style);
                    try self.text(". ", style);
                },
                else => {},
            };
            // Remove the post-HR generated break once (official late exception).
            var first: usize = 0;
            if (index != 0 and blocks[index - 1].kind == .rule and block_value.spans.len != 0 and
                (block_value.spans[0].image == null and block_value.spans[0].ruby == null and block_value.spans[0].inline_padding_group == null and block_value.spans[0].inline_action_group == null and block_value.spans[0].inline_box_group == null and (block_value.spans[0].kind == .line_break or trim(block_value.spans[0].text).len == 0))) first = 1;
            if (block_value.container != null) return self.containerUnavailableAt("poem_container_block", "");
            if (block_value.figure != null or block_value.flow != null) return self.figureUnavailable();
            try self.spans.appendSlice(self.a, block_value.spans[first..]);
            if (block_value.table) |table| try self.tableInline(table, style, true);
        }
        self.poem_boundary_pending = true;
    }

    // Failure evidence is build-only and local to this exact compiler fragment.
    // It cannot admit source, alter a returned error, or enter Stored data.
    // The exact same fallback Boolean is returned to the existing assignment.
    // This build-only first-event diagnostic cannot authorize style or alter
    // Stored output. A missing source coordinate is explicit, never guessed.
    fn traceUnresolvedTableStyle(self: *Renderer, unresolved: bool, branch: []const u8, hint: []const u8) bool {
        if (!unresolved or self.fallbacks.unresolved_table_style or self.rejection_probe_scope or self.table_style_trace_branch != null) return unresolved;
        self.table_style_trace_branch = branch;
        const source = if (self.source_element_binding) |binding| binding.owner.bytes else self.bounded_text_class_source orelse "";
        const first = @intFromPtr(source.ptr); const pointer = @intFromPtr(hint.ptr);
        const offset: ?usize = if (hint.len != 0 and pointer >= first and pointer - first <= source.len and hint.len <= source.len - (pointer - first)) pointer - first else null;
        const prepared_page_offset: ?usize = if (self.source_element_binding) |binding|
            (if (offset) |at| std.math.add(usize, binding.page_start, at) catch null else null) else null;
        const original_page_offset: ?usize = if (self.source_element_binding) |binding| binding.originalRange(hint) else null;
        var title_buffer: [256]u8 = undefined; var hint_buffer: [512]u8 = undefined;
        const title_hex = boundedTraceHex(&title_buffer, self.context.title);
        const hint_hex = boundedTraceHex(&hint_buffer, hint);
        diagnostics.logLine("presentation fallback phase=table_style first_event_scope=renderer_fragment first_branch={s} title_hex={s} title_bytes={d} fragment_bytes={d} local_offset={any} prepared_page_offset={any} original_page_offset={any} hint_hex={s} hint_bytes={d} hint_truncated={any} table_depth={d} body_depth={d} font_scope_unresolved={any}", .{
            branch, title_hex, self.context.title.len, source.len, offset,
            prepared_page_offset, original_page_offset,
            hint_hex, hint.len, hint.len > hint_hex.len / 2, self.typed_table_depth, self.body_depth, self.table_style_font_unresolved,
        });
        return unresolved;
    }

    fn tracePresentationRejection(self: *Renderer, phase: []const u8, reject_reason: []const u8, fragment: []const u8, local_offset: usize, reason_bits: u64, failure: Error) void {
        if (self.rejection_probe_scope or self.rejection_trace_events != 0) return;
        self.rejection_trace_events += 1;
        if (rejected_compiler_capture) |capture| capture.record(phase, reject_reason, fragment, local_offset, reason_bits, failure);
        if (self.inline_box_profile_diagnostic != .none) {
            diagnostics.logLine("presentation inline_box profile_reason={s}", .{@tagName(self.inline_box_profile_diagnostic)});
        }
        const bounded_offset = @min(local_offset, fragment.len);
        const window_start = bounded_offset -| 64;
        const window_end = window_start + @min(@as(usize, 256), fragment.len - window_start);
        var fragment_buffer: [512]u8 = undefined;
        var title_buffer: [256]u8 = undefined;
        const fragment_hex = boundedTraceHex(&fragment_buffer, fragment[window_start..window_end]);
        const title_hex = boundedTraceHex(&title_buffer, self.context.title);
        diagnostics.logLine("presentation rejected phase={s} reason={s} bits=0x{x} error={s} title_hex={s} title_bytes={d} title_truncated={any} fragment_bytes={d} local_offset={d} window_offset={d} window_hex={s} window_truncated={any}", .{
            phase, reject_reason, reason_bits, @errorName(failure), title_hex, self.context.title.len,
            self.context.title.len > title_hex.len / 2, fragment.len, bounded_offset, window_start,
            fragment_hex, window_start != 0 or window_end != fragment.len,
        });
    }

    pub fn traceDocumentBody(self: *Renderer, comptime event: enum { begin, end, failure }, source: MissingText, fragments: usize, failure: ?anyerror) void {
        if (event == .begin) {
            self.document_body_trace = self.context.table_viewport_trace and !self.context.observe_structure_only and !self.rejection_probe_scope;
            self.container_query_trace_events = 0;
        }
        if (!self.document_body_trace) return;
        var title_buffer: [256]u8 = undefined; var language_buffer: [256]u8 = undefined;
        diagnostics.logLine("presentation document_body event={s} renderer=0x{x} title_hex={s} language_hex={s} source_ptr=0x{x} source_bytes={d} fragments={d} content_root={s} observe_structure_only={any} rejection_probe_scope={any} unsupported_element={any} unresolved_table_style={any} container_queries={d} error={s}", .{
            if (event == .failure) "error" else @tagName(event), @intFromPtr(self),
            boundedTraceHex(&title_buffer, self.context.title), boundedTraceHex(&language_buffer, self.context.language),
            @intFromPtr(source.bytes.ptr), source.bytes.len, fragments, @tagName(self.content_root),
            self.context.observe_structure_only, self.rejection_probe_scope,
            self.fallbacks.unsupported_element, self.fallbacks.unresolved_table_style, self.container_query_trace_events,
            if (failure) |err| @errorName(err) else if (event == .failure) "unavailable" else "none",
        });
        if (event != .begin) self.document_body_trace = false;
    }

    fn traceContainerQuery(self: *Renderer, stage: []const u8, tag: syntax.Tag, query: *const table_style_profile.TextElement, environment: ?table_style_profile.CustomEnvironment, consumed: bool, result: table_style_profile.ContainerResolution) void {
        if (!self.document_body_trace or !self.context.table_viewport_trace or self.context.observe_structure_only or self.rejection_probe_scope or !result.unresolved or self.container_query_trace_events >= 8) return;
        self.container_query_trace_events += 1;
        // Read the already-live query and existing alias map. Null coordinates
        // remain unknown; diagnostics never manufacture an original range.
        const original = self.registeredCaptionOriginal(tag.name) orelse tag.name;
        const name_offset: ?usize = if (self.source_element_binding) |binding| binding.originalRange(original) else null;
        const opening_offset: ?usize = if (name_offset) |offset| (if (offset != 0) offset - 1 else null) else null;
        var attrs_buffer: [512]u8 = undefined;
        const attrs_hex = boundedTraceHex(&attrs_buffer, tag.attrs);
        diagnostics.logLine("presentation container_query stage={s} renderer=0x{x} event={d} original_opening_offset={any} name_ptr=0x{x} attrs_hex={s} attrs_bytes={d} attrs_truncated={any} content_root={s} observe_structure_only={any} rejection_probe_scope={any} body_depth={d} table_depth={d} binding={any} page_root={any} page_source={any} page_anchor={any} physical_ancestry={any} ancestry={any} alternative={any} literal_div={any} root_child={any}", .{
            stage, @intFromPtr(self), self.container_query_trace_events, opening_offset, @intFromPtr(tag.name.ptr),
            attrs_hex, tag.attrs.len, tag.attrs.len > attrs_hex.len / 2, @tagName(self.content_root),
            self.context.observe_structure_only, self.rejection_probe_scope, self.body_depth, self.typed_table_depth,
            self.source_element_binding != null, query.page_style_root != null, query.page_style_source != null,
            query.page_style_anchor != null, query.physical_ancestry_complete, query.ancestry_complete,
            query.alternative_ancestry != null, query.source_literal_div != null, query.source_root_child != null,
        });
        diagnostics.logLine("presentation container_query_proof stage={s} renderer=0x{x} event={d} ancestor_scope={any} complete_classes={any} complete_ids={any} parent_nonmatch={any} custom_present={any} custom_complete={any} custom_values={d} inheritance_consumed={any} specified={any} positioning_specified={any} unresolved={any}", .{
            stage, @intFromPtr(self), self.container_query_trace_events,
            query.ancestor_class_scope != null, query.complete_ancestor_classes != null, query.complete_ancestor_ids != null,
            query.source_parent_tag_nonmatch != null, environment != null,
            if (environment) |env| env.complete else false, if (environment) |env| env.values.len else @as(usize, 0),
            consumed, result.specified, result.positioning_specified, result.unresolved,
        });
    }

    // A retained-body fallback is not a fatal compiler rejection. Give it a
    // separate first-event guard so a later real error keeps its own evidence.
    fn traceContainerGeometryRefusal(self: *Renderer, reason: ContainerGeometryRefusal, fragment: []const u8) void {
        if (self.rejection_probe_scope or self.container_geometry_refusal != null) return;
        self.container_geometry_refusal = reason;
        var fragment_buffer: [512]u8 = undefined;
        var title_buffer: [256]u8 = undefined;
        const fragment_hex = boundedTraceHex(&fragment_buffer, fragment[0..@min(fragment.len, 256)]);
        const title_hex = boundedTraceHex(&title_buffer, self.context.title);
        diagnostics.logLine("presentation fallback phase=container_geometry_div reason={s} flag=unsupported_element title_hex={s} title_bytes={d} title_truncated={any} fragment_bytes={d} window_hex={s} window_truncated={any}", .{
            @tagName(reason), title_hex, self.context.title.len, self.context.title.len > title_hex.len / 2,
            fragment.len, fragment_hex, fragment.len > 256,
        });
        if (self.positionedContainerDiagnosticFor(fragment)) |detail| {
            diagnostics.logLine("presentation positioned_container_source stage={s} query={s} native={s} node={s} property={s} rule={any}", .{
                @tagName(detail.stage), @tagName(detail.query.reason), @tagName(detail.native_classes.reason),
                detail.query.node_tag orelse "", detail.query.property orelse "", detail.query.rule_order,
            });
        }
        if (self.document_body_trace and self.context.table_viewport_trace) {
            const original = self.registeredCaptionOriginal(fragment) orelse fragment;
            const offset: ?usize = if (self.source_element_binding) |binding| binding.originalRange(original) else null;
            diagnostics.logLine("presentation container_refusal_context stage={s} renderer=0x{x} original_fragment_offset={any} fragment_ptr=0x{x} content_root={s} observe_structure_only={any} rejection_probe_scope={any} body_depth={d} table_depth={d} binding={any} container_queries={d}", .{
                @tagName(reason), @intFromPtr(self), offset, @intFromPtr(fragment.ptr), @tagName(self.content_root),
                self.context.observe_structure_only, self.rejection_probe_scope, self.body_depth, self.typed_table_depth,
                self.source_element_binding != null, self.container_query_trace_events,
            });
        }
    }

    // Only previously untraced exits use this wrapper. Keep figureUnavailable
    // itself silent so existing precise geometry traces retain precedence.
    fn figureUnavailableAt(self: *Renderer, reason: []const u8, fragment: []const u8, offset: usize, bits: u64) Error {
        self.tracePresentationRejection("figure_admission", reason, fragment, offset, bits, error.UncompiledPresentation);
        return self.figureUnavailable();
    }

    fn figureGeometryRejected(self: *Renderer, choice: FigureChoice, reject_reason: []const u8, failure: Error) Error {
        self.tracePresentationRejection("figure_geometry", reject_reason, choice.file, 0, 0, failure);
        return failure;
    }

    fn manualConversionRejected(self: *Renderer, input: []const u8, at: usize, reject_reason: []const u8, failure: Error) Error {
        self.tracePresentationRejection("manual_conversion", reject_reason, input, at, 0, failure);
        return failure;
    }

    fn markUnclosed(self: *Renderer, input: []const u8, tag: syntax.Tag, comptime site: []const u8) void {
        self.fallbacks.unclosed_formatting = true;
        if (!self.context.unclosed_fragment_trace or self.unclosed_trace_events >= 8) return;
        self.unclosed_trace_events += 1;
        // parseSpans can normalize quotes/HTML into a new allocation. This
        // offset is local to the exact compiler fragment, never a page offset.
        const name_offset = @intFromPtr(tag.name.ptr) - @intFromPtr(input.ptr);
        var fragment_buffer: [1024]u8 = undefined;
        var title_buffer: [256]u8 = undefined;
        const window_offset = name_offset -| 256;
        const window_end = @min(input.len, window_offset + fragment_buffer.len / 2);
        const fragment_hex = boundedTraceHex(&fragment_buffer, input[window_offset..window_end]);
        const title_hex = boundedTraceHex(&title_buffer, self.context.title);
        diagnostics.logLine("presentation unclosed site={s} title_hex={s} title_bytes={d} title_truncated={any} tag={s} name_offset={d} fragment_bytes={d} fragment_window_offset={d} fragment_window_hex={s} fragment_truncated={any}", .{
            site,         title_hex,                                     self.context.title.len, self.context.title.len > title_hex.len / 2,
            tag.name,     name_offset,                                   input.len,              window_offset,
            fragment_hex, window_offset != 0 or window_end != input.len,
        });
    }

    // Parser.handleInternalLinks2 gives a category's plain sort key to
    // addCategory without recursively parsing it. A malformed template in that
    // metadata cannot borrow a later heading's close. Retain the category and
    // tracked metadata (rebased on edits); only brace spelling in the proved key changes.
    fn preparePlainCategorySortKeys(self: *Renderer, source: MissingText) Error!MissingText {
        const namespaces = self.context.namespace_catalog orelse return source;
        const input = source.bytes;
        if (std.mem.indexOf(u8, input, "[[") == null or std.mem.indexOf(u8, input, "{{") == null) return source;
        try generated_link.validateRanges(input, source.generated_source, source.generated_links);
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var emitted: usize = 0;
        var at: usize = 0;
        var generated_index: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        while (at < input.len) {
            while (generated_index < source.generated_links.len and source.generated_links[generated_index].end <= at) : (generated_index += 1) {}
            if (generated_index < source.generated_links.len and source.generated_links[generated_index].start <= at) {
                at = source.generated_links[generated_index].end;
                continue;
            }
            if ((at == 0 or input[at - 1] == '\n') and input[at] == ' ') {
                at = (std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len);
                if (at < input.len) at += 1;
                continue;
            }
            if (input[at] == '<') {
                if (opaque_scan.protectedEnd(input, at, null)) |end| { at = end; continue; }
                const tag = opaque_scan.tagAt(input, at, null) orelse break;
                // Attributes are skipped atomically. Ordinary formatting does
                // not change category ownership; protected/action bodies do.
                if (!tag.closing and !tag.self_closing and
                    (!recognizedInlineHtmlName(tag.name) or tag.html_pre or tag.isOpaque() or
                    oneOf(tag.name, &.{ "a", "code", "tt", "kbd", "samp", "var", "q", "blockquote", "includeonly", "noinclude", "script", "style", "textarea", "iframe", "object", "embed" }))) {
                    at = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len;
                    continue;
                }
                at = tag.end;
                continue;
            }
            if (starts(input[at..], "[[")) {
                const rest = input[at + 2 ..];
                var end: ?usize = null;
                var key_start: usize = 0;
                if (std.mem.indexOfAny(u8, rest, "[]{}|<>&\r\n")) |split| {
                    const target = trim(rest[0..split]);
                    if (rest[split] == '|' and target.len != 0 and target[0] != ':' and
                        safeInternalTarget(target) and std.mem.indexOfAny(u8, target, "#\"'") == null)
                    {
                        const colon = std.mem.indexOfScalar(u8, target, ':');
                        if (colon) |c| if (trim(target[c + 1 ..]).len != 0) {
                            if (namespaces.byName(target[0..c])) |ns| if (ns.id == 14) {
                                key_start = at + 2 + split + 1;
                                if (std.mem.indexOfAnyPos(u8, input, key_start, "[]<>|&\r\n\"")) |close| {
                                    const key = input[key_start..close];
                                    // One apostrophe is plain key text; quote runs
                                    // can own formatting across the category boundary.
                                    if (starts(input[close..], "]]") and std.mem.indexOf(u8, key, "''") == null and
                                        std.mem.indexOf(u8, key, "{{") != null and std.mem.indexOf(u8, key, "}}") == null)
                                        end = close + 2;
                                }
                            };
                        };
                    }
                }
                if (end) |close| {
                    var overlap = false;
                    for (source.ranges) |range| if (range.start < close and range.end > at) { overlap = true; break; };
                    if (generated_index < source.generated_links.len and source.generated_links[generated_index].start < close) overlap = true;
                    for (source.literal_curly_ranges) |range| if (range.start < close and range.end > at) { overlap = true; break; };
                    if (!overlap) {
                        for (input[key_start .. close - 2], key_start..) |byte, pos| {
                            if (byte != '{' and byte != '}') continue;
                            try out.appendSlice(self.a, source, emitted, pos);
                            try out.append(self.a, missingEdit(source, pos, pos + 1, if (byte == '{') "&#123;" else "&#125;"));
                            emitted = pos + 1;
                        }
                        at = close;
                        continue;
                    }
                }
                const pair = syntax.balancedWithOpaqueScan(input, at, &opaque_scan) orelse break;
                at = pair.end;
                continue;
            }
            if (starts(input[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &opaque_scan) orelse break;
                at = pair.end;
                continue;
            }
            if (input[at] == '[') {
                // An external/unknown label cannot lend category ownership.
                at = (std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse break) + 1;
                continue;
            }
            at += 1;
        }
        if (emitted == 0) return source;
        try out.appendSlice(self.a, source, emitted, input.len);
        return out.finish(self.a);
    }

    fn namespaceOfTarget(self: *const Renderer, title: []const u8) ?i32 {
        const colon = std.mem.indexOfScalar(u8, title, ':') orelse return null;
        const prefix = title[0..colon];
        if (self.context.namespace_catalog) |registry|
            return if (registry.byName(prefix)) |spec| spec.id else null;
        // Canonical standard names are also useful to standalone semantic
        // presentation callers that have no edition-local aliases.
        if (std.ascii.eqlIgnoreCase(prefix, "Category")) return 14;
        if (std.ascii.eqlIgnoreCase(prefix, "File") or std.ascii.eqlIgnoreCase(prefix, "Image")) return 6;
        return null;
    }

    const LinkDestination = struct { target: []const u8, external: bool = false, interwiki: bool = false };
    fn isSelfLink(self: *Renderer, target: []const u8) Error!bool {
        const hash = std.mem.indexOfScalar(u8, target, '#');
        // Linker::makeSelfLinkObj treats both "" and "0" as a false PHP hash.
        if (hash) |at| if (at + 1 != target.len and !std.mem.eql(u8, target[at + 1 ..], "0")) return false;
        const page = if (hash) |at| target[0..at] else target;
        if (page.len == 0 or self.context.title.len == 0) return false;
        if (self.context.namespace_catalog) |registry| {
            // Interwiki pages are not local title identities, even when their
            // literal spelling happens to equal this page's title.
            if (self.namespaceOfTarget(page) == null) {
                if (std.mem.indexOfScalar(u8, page, ':')) |colon| {
                    for (registry.interwiki_rows) |row| {
                        if (!row.is_current_wiki and std.ascii.eqlIgnoreCase(row.prefix, std.mem.trim(u8, page[0..colon], " \t"))) return false;
                    }
                }
            }
            const normalized = registry.normalizeTitle(self.a, page, 0, .any) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => return false,
            };
            defer self.a.free(normalized);
            if (registry.ofTitle(normalized).id == -1) return false;
            const current = registry.normalizeTitle(self.a, self.context.title, 0, .any) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => return false,
            };
            defer self.a.free(current);
            return std.mem.eql(u8, normalized, current);
        }
        if (std.mem.indexOfScalar(u8, page, ':')) |colon|
            if (std.ascii.eqlIgnoreCase(page[0..colon], "Special")) return false;
        // Without edition metadata, only exact title identity is established.
        return std.mem.eql(u8, page, self.context.title);
    }
    // A query-local negative certificate. This does not change the emitted
    // node, its parents, attributes, source scope or selector-match authority.
    fn negativePaintQueryClasses(self: *Renderer, complete: ?[]const u8, element: *const table_style_profile.TextElement) Error!?[]const u8 {
        return self.negativePaintQueryTokens(complete, element, false);
    }
    fn negativePaintQueryTokens(self: *Renderer, complete: ?[]const u8, element: *const table_style_profile.TextElement, comptime ids: bool) Error!?[]const u8 {
        const inherited = complete orelse return null;
        if (inherited.len > 65536) return null;
        var result: std.ArrayList(u8) = .empty;
        defer result.deinit(self.a);
        try result.appendSlice(self.a, inherited);
        const Node = table_style_profile.TextElement;
        var captured_storage: [max_depth * 2]*const Node = undefined;
        var captured: ?[]const *const Node = null;
        var captured_checked = false;
        const Frame = struct { node: *const Node, edge: u2 = 0 };
        var stack: [256]Frame = undefined;
        var completed: [256]*const Node = undefined;
        var depth: usize = 1;
        var completed_count: usize = 0;
        var admitted: usize = 0;
        stack[0] = .{ .node = element };
        while (depth != 0) {
            const frame = &stack[depth - 1];
            if (frame.edge == 0) {
                // The two authenticated ancestry views may join at a shared
                // parent. Only a node still on this path constitutes a cycle.
                for (stack[0 .. depth - 1]) |active| if (active.node == frame.node) return null;
                var done = false;
                for (completed[0..completed_count]) |prior| if (prior == frame.node) { done = true; break; };
                if (done) { depth -= 1; continue; }
                if (admitted == completed.len) return null;
                if (!self.currentAncestorScope(frame.node)) {
                    // Captured outer ancestors own exact Book identities, not
                    // native source-opening anchors. Keep this query-local.
                    if (!captured_checked) {
                        captured = self.selectedCapturedOuterAncestors(&captured_storage);
                        captured_checked = true;
                    }
                    var known = false;
                    for (captured orelse &.{}) |observed| if (observed == frame.node) { known = true; break; };
                    if (!known) return null;
                }
                admitted += 1;
                const node = frame.node;
                for ([_][]const u8{ if (ids) node.id else node.classes,
                    (if (ids) node.complete_ancestor_ids else node.complete_ancestor_classes) orelse "" }) |tokens| {
                    if (tokens.len >= 65536 - result.items.len) return null;
                    try result.append(self.a, ' ');
                    try result.appendSlice(self.a, tokens);
                }
            }
            if (frame.edge < 2) {
                const next = if (frame.edge == 0) frame.node.parent else frame.node.alternative_ancestry;
                frame.edge += 1;
                if (next) |node| {
                    if (depth == stack.len) return null;
                    stack[depth] = .{ .node = node };
                    depth += 1;
                }
            } else {
                completed[completed_count] = frame.node;
                completed_count += 1;
                depth -= 1;
            }
        }
        return try self.a.dupe(u8, result.items);
    }
    fn ordinaryLinkQueryDomain(self: *const Renderer, original: Style, source: ?[]const u8) bool {
        if (self.inline_source_domain == null) return self.wikiClassOrdinaryDomain();
        // The normal inline parser owns one live source domain while issuing
        // a complete link. Do not treat that domain as an unowned nested parse.
        // All other ordinary-scope barriers stay independent and unchanged.
        if (self.content_root != .parser_output or self.in_reference or self.in_template_literal_scope or
            self.pre_block or self.parsed_pre or self.block_formatting.code or self.poem_depth != 0 or
            self.explicit_wiki_label != null or self.body_link_target.len != 0 or
            self.html_list_item_flow or self.html_blockquote_flow or self.figure_implicit_list_context) return false;
        if (self.body_language_direction) |style| if (style.code or style.provenance != .parsed or
            style.kind != .text or style.target.len != 0 or style.self_link_target != null) return false;
        if (original.provenance != .parsed or original.kind != .text or original.target.len != 0 or
            original.self_link_target != null or original.code or original.preserve_whitespace or original.missing_nonaction) return false;
        const token = source orelse return false;
        const domain = self.inline_source_domain.?;
        const tracked = self.inline_missing orelse return false;
        if (domain.parent != null or domain.source.ptr != tracked.bytes.ptr or domain.source.len != tracked.bytes.len or
            !wikiClassCleanText(tracked) or !wikiClassContains(domain.source, token)) return false;
        return true;
    }
    fn captionNoLiParentSource(self: *const Renderer, tracked: MissingText, source: []const u8) ?[]const u8 {
        if (self.figure_implicit_list_context or self.html_list_item_flow or
