    fn ordinaryLinkClassParent(self: *const Renderer, original: Style, source: ?[]const u8) ?*const table_style_profile.TextElement {
        if (!self.wikiClassOrdinaryState() or original.provenance != .parsed or original.kind != .text or
            original.target.len != 0 or original.self_link_target != null or original.code or
            original.preserve_whitespace or original.missing_nonaction) return null;
        const token = source orelse return null;
        const selected = self.figureClassSourceDomain() orelse return null;
        const parent = original.text_element orelse return null;
        const parent_source = parent.ancestor_class_source orelse return null;
        if (parent.ancestor_class_scope != selected.scope or parent.complete_ancestor_classes == null or
            parent_source.ptr != selected.selected.ptr or parent_source.len != selected.selected.len or
            !self.currentAncestorScope(parent) or parent.alternative_ancestry != null or
            self.classScopeForSource(token) != selected.scope) return null;
        const live = self.inline_source_domain orelse return null;
        const tracked = self.inline_missing orelse return null;
        if (live.source.ptr != tracked.bytes.ptr or live.source.len != tracked.bytes.len or
            !wikiClassCleanText(tracked) or !wikiClassContains(tracked.bytes, token)) return null;
        var frame: ?*const InlineSourceDomain = live;
        var remaining: usize = max_depth + 1;
        while (frame) |current| {
            if (remaining == 0) return null;
            remaining -= 1;
            const held = current.tracked orelse return null;
            if (held.bytes.ptr != current.source.ptr or held.bytes.len != current.source.len or
                !wikiClassCleanText(held) or self.classScopeForSource(current.source) != selected.scope) return null;
            if (current.parent) |outer| {
                if (!wikiClassContains(outer.source, current.source)) return null;
            } else if (current.source.ptr != selected.selected.ptr or current.source.len != selected.selected.len) return null;
            frame = current.parent;
