        const name_at = std.math.sub(usize, parent.source_key, @intFromPtr(selected.selected.ptr)) catch return null;
        if (name_at == 0 or name_at >= selected.selected.len) return null;
        const parent_tag = syntax.tagAt(selected.selected, name_at - 1) orelse return null;
        if (parent_tag.closing or parent_tag.self_closing or parent_tag.html_pre or parent_tag.isOpaque() or
            !knownInlineHtmlName(parent_tag.name) or parent_tag.name.ptr != parent.tag.ptr or parent_tag.name.len != parent.tag.len or
            @intFromPtr(parent_tag.name.ptr) != parent.source_key) return null;
        const parent_pair = syntax.matchingTag(selected.selected, parent_tag) orelse return null;
        if (!wikiClassContains(selected.selected[parent_tag.end..parent_pair.inner_end], token)) return null;
        var iterator: ir.InlineIterator = .{ .input = token, .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const source_link = iterator.next() orelse return null;
        if (source_link.kind != .link or source_link.link_label_restored_close or source_link.trail.len != 0 or
            iterator.cursor != token.len or self.namespaceOfTarget(source_link.target) == 6) return null;
        return parent;
    }

    // Project only an unchanged authored interval through the current ordinary
    // quote/copy operation. The returned key is the name identity used by
    // textElement; it is not a new page or physical-ancestry capability.
    const OrdinaryLinkOriginal = struct { bytes: []const u8, key: usize };
    fn ordinaryLinkOriginal(self: *const Renderer, selected: FigureClassSourceDomain, part: []const u8) ?OrdinaryLinkOriginal {
        if (self.figureStyleOriginalSlice(selected, part)) |original|
            return .{ .bytes = original, .key = @intFromPtr(part.ptr) };
        var next = self.quote_class_source;
        var remaining: usize = max_depth + 1;
