            const copied = domain.map.copiedOriginal(part) orelse continue;
            if (!std.mem.eql(u8, part, copied)) return null;
            const original = self.figureStyleQuoteOriginalSlice(selected, domain, copied) orelse continue;
            return .{ .bytes = original, .key = @intFromPtr(copied.ptr) };
        }
        return null;
    }
