    fn ordinaryBulletLinkState(self: *const Renderer, token: []const u8) bool {
        if (!self.figure_implicit_list_context or self.content_root != .parser_output or
            self.in_reference or self.in_template_literal_scope or self.pre_block or self.parsed_pre or
            self.block_formatting.code or self.poem_depth != 0 or self.explicit_wiki_label != null or
            self.body_link_target.len != 0 or self.html_list_item_flow or self.html_blockquote_flow) return false;
        if (self.body_language_direction) |style| if (style.code or style.provenance != .parsed or
            style.kind != .text or style.target.len != 0 or style.self_link_target != null) return false;
        const operation = self.ordinary_bullet_link orelse return false;
        const held = self.body_missing orelse return false;
        if (held.bytes.ptr != operation.source.ptr or held.bytes.len != operation.source.len or
            !noLiParentSourceRange(held, operation.line) or !wikiClassContains(operation.line, operation.body)) return false;
        const selected = self.figureStyleSourceDomain() orelse return false;
        const binding = self.figureStyleOriginalBinding(selected) orelse return false;
        const original_line = self.figureStyleOriginalSlice(selected, operation.line) orelse return false;
        const original_body = self.figureStyleOriginalSlice(selected, operation.body) orelse return false;
        const original_token = self.ordinaryLinkOriginal(selected, token) orelse return false;
        if (original_line.len == 0 or original_line[0] != '*' or std.mem.indexOfAny(u8, original_line, "\r\n") != null or
