        const parsed_body = wikiListLineBody(original_line[1..]);
        if (parsed_body.ptr != original_body.ptr or parsed_body.len != original_body.len) return false;
        const at = std.math.sub(usize, @intFromPtr(original_line.ptr), @intFromPtr(selected.selected.ptr)) catch return false;
        if (at != 0 and selected.selected[at - 1] != '\n') return false;
        const owner_line = binding.ownerRange(at, original_line.len) orelse return false;
        return owner_line.len == operation.line.len and std.mem.eql(u8, owner_line, operation.line);
