        const parent_source = parent.ancestor_class_source orelse return null;
        if (parent.ancestor_class_scope != selected.scope or parent.complete_ancestor_classes == null or
            parent_source.ptr != selected.selected.ptr or parent_source.len != selected.selected.len or
