            std.mem.eql(u8, live.label, held.observation.label) and sameFigurePreparationValue(live.font, held.observation.font) and
            live.wrap == held.observation.wrap and sameFigurePreparationValue(live.paint, held.observation.paint) and sameFigurePreparationValue(style.link_paint, @as(?presentation_types.LinkPaint, live.paint)) and
            style.font_scale == font.font_scale and style.font_scale_basis == font.font_scale_basis and style.font_scale_set and !style.font_size_unknown and
            sameFigurePreparationValue(style.font_family, font.font_family) and sameFigurePreparationValue(style.font_features, font.font_features) and
            std.mem.eql(u8, style.language, font.language) and style.bold == font.bold and style.italic == font.italic and
            !style.code and !style.small and !style.superscript and !style.subscript and !style.strike and
            style.underline == live.paint.normal.underline and style.foreground != null and
            std.mem.eql(u8, style.foreground.?, live.paint.normal.foreground) and style.authored_link_font_override;
    }

