    fn isInterlanguageMetadata(self: *const Renderer, target: []const u8) bool {
        const registry = self.context.namespace_catalog orelse return false;
        if (registry.interwiki_magic != true or target.len == 0 or starts(target, ":") or
            !safeInternalTarget(target) or std.mem.indexOfAny(u8, target, "\r\n") != null or
            self.namespaceOfTarget(target) != null) return false;
        const host_namespace = registry.ofTitle(self.context.title).id;
        if (host_namespace > 0 and @mod(host_namespace, 2) == 1) return false;
        const colon = std.mem.indexOfScalar(u8, target, ':') orelse return false;
        if (std.mem.trim(u8, target[colon + 1 ..], " \t").len == 0) return false;
        const prefix = std.mem.trim(u8, target[0..colon], " \t");
        for (registry.interwiki_rows) |row| if (std.ascii.eqlIgnoreCase(row.prefix, prefix))
            return row.is_interlanguage and !row.is_current_wiki;
        return false;
    }
    fn currentWikiTarget(self: *const Renderer, original: []const u8) []const u8 {
        const registry = self.context.namespace_catalog orelse return original;
        var title = original;
        for (0..8) |_| {
            if (self.namespaceOfTarget(title) != null) return title;
            const colon = std.mem.indexOfScalar(u8, title, ':') orelse return title;
            const prefix = std.mem.trim(u8, title[0..colon], " \t");
            var next: ?[]const u8 = null;
            for (registry.interwiki_rows) |row| {
                if (row.is_current_wiki and std.ascii.eqlIgnoreCase(row.prefix, prefix)) {
                    const body = std.mem.trimStart(u8, title[colon + 1 ..], " \t");
                    if (body.len != 0) next = body;
                    break;
                }
            }
            title = next orelse return title;
        }
        return original;
    }
    fn interwikiDestination(self: *Renderer, title: []const u8, depth: usize) Error!LinkDestination {
        const ordinary: LinkDestination = .{ .target = title };
        if (depth >= 8 or self.namespaceOfTarget(title) != null) return ordinary;
        const registry = self.context.namespace_catalog orelse return ordinary;
        const colon = std.mem.indexOfScalar(u8, title, ':') orelse return ordinary;
        const prefix = std.mem.trim(u8, title[0..colon], " \t");
        for (registry.interwiki_rows) |row| {
            if (!std.ascii.eqlIgnoreCase(row.prefix, prefix)) continue;
            var body = std.mem.trimStart(u8, title[colon + 1 ..], " \t");
            if (row.is_current_wiki) {
                if (body.len == 0) return ordinary;
                return self.interwikiDestination(body, depth + 1);
            }
            if (starts(body, ":")) body = std.mem.trimStart(u8, body[1..], " \t");
            const hash = std.mem.indexOfScalar(u8, body, '#');
            const page = if (hash) |at| body[0..at] else body;
            const encoded = try self.interwikiUrlPart(page);
            var url: std.ArrayList(u8) = .empty;
            var at: usize = 0;
            while (std.mem.indexOfPos(u8, row.url, at, "$1")) |found| {
                try url.appendSlice(self.a, row.url[at..found]);
                try url.appendSlice(self.a, encoded);
                at = found + 2;
            }
            try url.appendSlice(self.a, row.url[at..]);
            if (hash) |start| {
                try url.append(self.a, '#');
                try url.appendSlice(self.a, try self.interwikiUrlPart(body[start + 1 ..]));
            }
            const result = try url.toOwnedSlice(self.a);
            // Reuse the existing external-action admissibility contract.
            if (!safeUrl(result) or unresolvedExternalActionTarget(result)) {
                self.fallbacks.rejected_external_target = true;
                return .{ .target = "" };
            }
            return .{ .target = result, .external = true, .interwiki = true };
        }
        return ordinary;
    }
    fn interwikiUrlPart(self: *Renderer, value: []const u8) Error![]const u8 {
        var out: std.Io.Writer.Allocating = .init(self.a);
        for (value) |ch| {
            if (ch == ' ') {
                out.writer.writeByte('_') catch return error.OutOfMemory;
            } else if (std.ascii.isAlphanumeric(ch) or std.mem.indexOfScalar(u8, "-._~/:()", ch) != null) {
                out.writer.writeByte(ch) catch return error.OutOfMemory;
            } else out.writer.print("%{X:0>2}", .{ch}) catch return error.OutOfMemory;
        }
        return out.toOwnedSlice() catch return error.OutOfMemory;
    }

    fn nestedLabelRefusal(self: *const Renderer, target: []const u8, label: []const u8, explicit: bool) ?bool {
        const namespace = self.namespaceOfTarget(target);
        if (!explicit and namespace == 6) return null;
        if (syntax.delimiter(label, "[[", 0) == null) return null;
        return safeInternalTarget(target) and (explicit or namespace != 14);
    }

    fn canonicalMediaFile(self: *Renderer, raw: []const u8) Error!?[]const u8 {
        var identity = raw;
        if (std.mem.indexOf(u8, raw, poem_prefix) != null) {
            var at: usize = 0;
            while (std.mem.indexOfPos(u8, raw, at, poem_prefix)) |found| {
                const item = self.poemItemAt(raw[found..]) orelse {
                    self.fallbacks.unsupported_element = true;
                    return null;
                };
                if (item.kind != .literal or !std.mem.eql(u8, item.tag, "text")) {
                    self.fallbacks.unsupported_element = true;
                    return null;
                }
                at = found + item.token.len;
            }
            identity = try self.poemCleanField(raw);
        }
        var normalized: std.Io.Writer.Allocating = .init(self.a);
        defer normalized.deinit();
        @import("namespace_registry").normalizeSpacing(&normalized.writer, identity) catch |err| switch (err) {
            error.WriteFailed => return error.OutOfMemory,
            else => {
                self.fallbacks.unsupported_element = true;
                return null;
            },
        };
        return normalized.toOwnedSlice() catch return error.OutOfMemory;
    }
    fn resolvedMediaFile(self: *Renderer, raw: []const u8) Error!?[]const u8 {
        const authored = (try self.canonicalMediaFile(raw)) orelse return null;
        if (self.context.figure_sizing) |source| {
            if (source.resolve_canonical_file_fn) |resolve| {
                if (try resolve(source.ctx, self.a, authored)) |resolved| return resolved;
            }
        }
        return authored;
    }
    fn mediaClasses(self: *Renderer, raw: []const u8) Error![]const u8 {
        const file = (try self.resolvedMediaFile(raw)) orelse return "wikidict-media";
        // Only an actual emitted Media.file can authorize ownership metadata.
        if (!self.media_indices.contains(file)) return "wikidict-media";
        const prefix = "wikidict-media wikidict-media-file-";
        // DPR2 already limits each classes string to 32 MiB. Check before doubling.
        if (file.len > (32 * 1024 * 1024 - prefix.len) / 2) return error.RenderLimit;
        const value = try self.a.alloc(u8, prefix.len + file.len * 2);
        @memcpy(value[0..prefix.len], prefix);
        const hex = "0123456789abcdef";
        for (file, 0..) |byte, index| {
            value[prefix.len + index * 2] = hex[byte >> 4];
            value[prefix.len + index * 2 + 1] = hex[byte & 15];
        }
        return value;
    }
