    fn captionCatalogTable(self: *Renderer, out: *std.ArrayList(Span), table: Table, depth: CaptionCatalogDepth) Error!void {
        if (table.caption_blocks) |caption| try self.captionCatalogBlocks(out, caption, try depth.contentChild()) else try out.appendSlice(self.a, table.caption);
        for (table.rows, 0..) |row, ri| {
            if (ri != 0 or table.caption.len != 0 or table.caption_blocks != null) try out.append(self.a, .{ .kind = .line_break, .text = "" });
            for (row.cells, 0..) |cell, ci| {
                if (ci != 0) try out.append(self.a, .{ .text = " · " });
                if (cell.blocks) |children| try self.captionCatalogBlocks(out, children, depth) else {
                    try out.appendSlice(self.a, cell.spans);
                    if (cell.nested_table) |child| try self.captionCatalogTable(out, child, try depth.nestedTable());
                }
            }
        }
    }
    fn captionCatalogFigure(self: *Renderer, out: *std.ArrayList(Span), figure: Figure, depth: CaptionCatalogDepth) Error!void {
        if (figure.caption_blocks) |blocks| try self.captionCatalogBlocks(out, blocks, try depth.contentChild()) else try out.appendSlice(self.a, figure.caption);
    }
    fn captureFigureCaption(self: *Renderer, input: []const u8, capture: MediaCaptionCapture, output: *?[]const Block) Error![]const Span {
        if (self.figure_caption_depth >= 16) return error.RenderLimit;
        const tracked = capture.tracked orelse return error.UncompiledPresentation;
        if (tracked.bytes.ptr != input.ptr or tracked.bytes.len != input.len) return error.UncompiledPresentation;
        const previous_caption_parent = self.caption_class_parent;
        const previous_caption_source = self.caption_class_source;
        self.caption_class_parent = null;
        self.caption_class_source = null;
        if (capture.style.text_element) |root| {
            if (root.tag.len == "figcaption".len and std.mem.eql(u8, root.tag, "figcaption") and
                root.ancestor_class_scope != null and root.complete_ancestor_classes != null and self.currentAncestorScope(root)) {
                self.caption_class_parent = root;
                self.caption_class_source = input;
            }
        }
        defer self.caption_class_parent = previous_caption_parent;
        defer self.caption_class_source = previous_caption_source;
        const previous_no_li = self.caption_no_li_source;
        self.caption_no_li_source = null;
        if (capture.no_li_parent) if (capture.style.text_element) |root| {
            if (std.mem.eql(u8, root.tag, "figcaption"))
                self.caption_no_li_source = self.captionNoLiParentSource(tracked, input);
        };
        defer self.caption_no_li_source = previous_no_li;
        const previous = .{ .missing = self.body_missing, .suppression = self.image_block_suppressed,
            .formatting = self.block_formatting, .attributes = self.body_formatting_attributes,
            .headings = self.page_html_heading_openings, .wiki_headings = self.page_wiki_heading_openings,
            .content_headings = self.page_wiki_content_heading_openings, .quote = self.next_quote_seed,
            .domain = self.inline_source_domain, .table = self.inline_table_boundaries };
        self.figure_caption_depth += 1;
        self.body_missing = tracked;
        self.image_block_suppressed = false;
        self.page_html_heading_openings = null;
        self.page_wiki_heading_openings = null;
        self.page_wiki_content_heading_openings = null;
        self.next_quote_seed = null;
        self.inline_source_domain = null;
        self.inline_table_boundaries = null;
        self.body_formatting_attributes = .{ .classes = capture.style.classes, .role = capture.style.role,
            .text_element = capture.style.text_element, .custom_properties = capture.style.custom_properties, .table_collapse = capture.style.table_collapse, .table_inheritance_scoped = capture.style.table_inheritance_scoped, .relative_context_policy_present = capture.style.relative_context_policy_present, .column_fragmentation_policy_present = capture.style.column_fragmentation_policy_present };
        self.block_formatting = .{ .bold = capture.style.bold, .italic = capture.style.italic, .code = capture.style.code,
            .small = capture.style.small, .superscript = capture.style.superscript, .subscript = capture.style.subscript,
            .strike = capture.style.strike, .underline = capture.style.underline };
        defer {
            self.figure_caption_depth -= 1;
            self.body_missing = previous.missing;
            self.image_block_suppressed = previous.suppression;
            self.block_formatting = previous.formatting;
            self.body_formatting_attributes = previous.attributes;
            self.page_html_heading_openings = previous.headings;
            self.page_wiki_heading_openings = previous.wiki_headings;
            self.page_wiki_content_heading_openings = previous.content_headings;
            self.next_quote_seed = previous.quote;
            self.inline_source_domain = previous.domain;
            self.inline_table_boundaries = previous.table;
        }
        // A Figure owns its caption's computed style. Keep earlier page
        // fallbacks, but do not let one hide a fresh unresolved caption effect.
        const previous_unresolved_style = self.fallbacks.unresolved_table_style;
        self.fallbacks.unresolved_table_style = false;
        defer self.fallbacks.unresolved_table_style = self.fallbacks.unresolved_table_style or previous_unresolved_style;
        const spans = try self.cellSpansWithLanguageDirection(input, capture.style, output, null);
        if (self.fallbacks.unresolved_table_style) return self.figureUnavailableAt("caption_style", input, 0, 0);
        if (output.*) |blocks| {
            var catalog: std.ArrayList(Span) = .empty;
            errdefer catalog.deinit(self.a);
            try self.captionCatalogBlocks(&catalog, blocks, .{});
            return try catalog.toOwnedSlice(self.a);
        }
        return spans;
    }
    pub fn mediaCaptionLink(self: *Renderer, file: []const u8, caption: []const u8, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        const capture: MediaCaptionCapture = .{ .mode = .link, .style = style, .depth = depth, .target = target, .external = external };
        const parsed = (try self.mediaFileKindWithSpans(file, caption, null, capture)) orelse try self.captureMediaCaption(caption, capture);
        try self.spans.appendSlice(self.a, parsed);
    }
    fn mediaFileKindWithSpans(self: *Renderer, raw: []const u8, caption: []const u8, authoritative_kind: ?media_types.Kind, caption_style: ?MediaCaptionCapture) Error!?[]const Span {
        // Media is supplemental presentation. Pathological nesting or a page with
        // hundreds of assets must not make the entry itself unreadable.
        if (self.media_depth >= max_depth) {
            self.fallbacks.render_limit = true;
            return null;
        }
        self.media_depth += 1;
        defer self.media_depth -= 1;
        const file = (try self.resolvedMediaFile(raw)) orelse return null;
        const kind = authoritative_kind orelse media_types.referencedKind(file) orelse return null;
        const heading_only = if (caption_style) |capture| capture.heading_only else false;
        const previous_index = self.media_indices.get(file);
        const replacing_heading = if (previous_index) |index| blk: {
            if (heading_only or !self.media_heading_only.items[index]) return null;
            break :blk true;
        } else false;
        if (!replacing_heading and self.media_remaining_items == 0) {
            self.fallbacks.render_limit = true;
            return null;
        }
        var metadata_blocks: ?[]const Block = null;
        // This also covers metadata-only parseSpans callers without a capture.
        const previous_handoff = self.container_handoff_suppressed;
        self.container_handoff_suppressed = true;
        defer self.container_handoff_suppressed = previous_handoff;
        const caption_spans = if (caption_style) |capture| try self.captureMediaCaption(caption, capture) else if (self.hasFigureBody(caption)) blk: {
            // Metadata-only registration still parses nested caption effects
            // once. Its text is derived from the same typed local graph.
            const tracked = if (self.body_missing) |parent| tracked: {
                const begin = @intFromPtr(caption.ptr);
                const root = @intFromPtr(parent.bytes.ptr);
                if (begin < root or begin - root > parent.bytes.len or caption.len > parent.bytes.len - (begin - root))
                    return self.figureUnavailable();
                break :tracked try missingSlice(self.a, parent, caption);
            } else MissingText.untracked(caption);
            break :blk try self.captureMediaCaption(caption, .{ .style = .{}, .tracked = tracked, .figure_blocks = &metadata_blocks });
        } else try self.parseSpans(caption, .{});
        // Caption parsing can register nested media. Recheck the same canonical
        // identity and budget before committing this metadata record. Preserve
        // the captured occurrence so its caller never repeats caption effects.
        // Captions can grow the map or register this same file. Never retain a
        // map entry pointer or stale absence result across that recursion.
        if (self.media_indices.get(file)) |index| {
            if (!heading_only and self.media_heading_only.items[index]) {
                const description = try plainText(self.a, caption_spans);
                self.media.items[index].caption = description;
                self.media_caption_spans.items[index] = caption_spans;
                self.media_heading_only.items[index] = false;
            }
            return if (caption_style != null) caption_spans else null;
        }
        if (self.media_remaining_items == 0) {
            self.fallbacks.render_limit = true;
            return if (caption_style != null) caption_spans else null;
        }
        const description = try plainText(self.a, caption_spans);
        try self.media.ensureUnusedCapacity(self.a, 1);
        try self.media_caption_spans.ensureUnusedCapacity(self.a, 1);
        try self.media_heading_only.ensureUnusedCapacity(self.a, 1);
        try self.media_indices.ensureUnusedCapacity(self.a, 1);
        const index = self.media.items.len;
        self.media.appendAssumeCapacity(.{ .file = file, .kind = kind, .caption = description });
        self.media_caption_spans.appendAssumeCapacity(caption_spans);
        self.media_heading_only.appendAssumeCapacity(heading_only);
        self.media_indices.putAssumeCapacityNoClobber(file, index);
        self.media_remaining_items -= 1;
        return if (caption_style != null) caption_spans else null;
    }
    // Ordinary source-backed documents can contain more typed items than the
    // small-input expansion allowance. Keep work bounded by source bytes and
    // by the format's aggregate item ceiling; the codec enforces its own count.
    pub fn budgetForSource(self: *Renderer, source_bytes: usize) void {
        self.node_limit = @max(max_nodes, @min(source_bytes, presentation_types.max_presentation_items));
    }

    fn spend(self: *Renderer) bool {
        if (self.nodes >= self.node_limit) {
            self.fallbacks.render_limit = true;
            self.truncated = true;
            return false;
        }
        self.nodes += 1;
        return true;
    }
    pub fn text(self: *Renderer, value: []const u8, original: Style) Error!void {
        try self.loadPoemPhase();
        if (try self.generatedText(value, original)) return;
        if (self.poem_dispatch_limit) return;
        // Ordinary pages retain the original single-span emission path.
        if (self.poem_items.items.len == 0 and self.poem_depth == 0 and !self.poem_boundary_pending)
            return self.textRaw(value, original);
        var style = original;
        if (self.poem_boundary_pending and (value.len != 0 or original.image != null)) {
            self.poem_boundary_pending = false;
            if (original.kind != .line_break and self.spans.items.len != 0 and self.spans.items[self.spans.items.len - 1].kind != .line_break)
                try self.textRaw("\n", .{ .kind = .line_break });
            self.poem_line_indent = 0;
        }
        var at: usize = 0;
        while (at < value.len) {
            const found = std.mem.indexOfPos(u8, value, at, poem_prefix) orelse break;
            try self.poemText(value[at..found], style);
            if (self.poemItemAt(value[found..])) |item| {
                if (self.poem_item_dispatches >= max_nodes) {
                    self.fallbacks.render_limit = true;
                    self.poem_dispatch_limit = true;
                    try self.textRaw("[render output truncated]", style);
                    return;
                }
                self.poem_item_dispatches += 1;
                at = found + item.token.len;
                if (item.kind == .line_break) {
                    var break_style = style;
                    break_style.kind = .line_break;
                    try self.poemText("\n", break_style);
                    // The accompanying source-formatting LF is not a second
                    // semantic break, including inside nowiki/pre/source.
                    if (at < value.len and value[at] == '\n') at += 1;
                    style.poem_indent = null;
                } else if (item.kind == .literal) {
                    var literal_style = style;
                    if (std.mem.eql(u8, item.tag, "poem")) {
                        try self.inlineText(item.body, literal_style, self.poem_depth + 1);
                    } else if (std.mem.eql(u8, item.tag, "text")) {
                        try self.poemText(item.body, literal_style);
                    } else {
                        const nowiki = std.mem.eql(u8, item.tag, "nowiki");
                        if (!nowiki) {
                            literal_style.code = true;
                            literal_style.preserve_whitespace = true;
                        }
                        literal_style.provenance = .protected_literal;
                        if (oneOf(item.tag, &.{ "source", "syntaxhighlight" }))
                            try self.text(item.body, literal_style)
                        else if (nowiki)
                            try self.protectedNowikiLiteral(item.body, literal_style)
                        else
                            try self.protectedLiteral(item.body, literal_style);
                    }
                } else if (item.kind == .soft_space) {
                    // Core nowiki collapses this unspecialized LF as HTML
                    // whitespace; actual pre/source literal contexts retain LF.
                    if (style.preserve_whitespace) {
                        var break_style = style;
                        break_style.kind = .line_break;
                        try self.poemText("\n", break_style);
                        style.poem_indent = null;
                    } else try self.poemText(" ", style);
                    if (at < value.len and value[at] == '\n') at += 1;
                }
            } else {
                try self.poemText(poem_prefix, style);
                at = found + poem_prefix.len;
            }
        }
        try self.poemText(value[at..], style);
    }
    fn poemText(self: *Renderer, value: []const u8, original: Style) Error!void {
        if (value.len == 0 and original.image == null) return;
        var style = original;
        if (self.poem_depth != 0) {
            const parent = self.poem_base_style;
            inheritInlineMetadata(&style, parent);
            style.bold = style.bold or parent.bold;
            style.italic = style.italic or parent.italic;
            style.code = style.code or parent.code;
            style.small = style.small or parent.small;
            style.superscript = style.superscript or parent.superscript;
            style.subscript = style.subscript or parent.subscript;
            style.strike = style.strike or parent.strike;
            style.underline = style.underline or parent.underline;
            if (style.language.len == 0) style.language = parent.language;
            if (style.direction.len == 0) {
                style.direction = parent.direction;
                if (style.captured_direction == null) style.captured_direction = parent.captured_direction;
            }
            if (parent.classes.len != 0) style.classes = try std.fmt.allocPrint(self.a, "{s} {s}", .{ parent.classes, style.classes });
            if (style.poem_indent) |indent| self.poem_line_indent = indent;
            style.classes = try self.poemClasses(style.classes, self.poem_line_indent);
        }
        // A registered wrapper owns indentation even when the joined reference
        // is parsed outside ambient Poem. Do not convert raw LF or inherit the
        // first reference's unrelated direction/classes onto later body parts.
        if (self.poem_depth == 0) if (style.poem_indent) |indent| {
            style.classes = try self.poemClasses(style.classes, indent);
        };
        // A nowiki item captured before Poem projection has no registered
        // break for its raw LF. It remains HTML whitespace after unstripping.
        // Registered breaks have already been dispatched with line_break kind;
        // pre/source contexts preserve their literal whitespace.
        if (self.poem_depth != 0 and style.kind != .line_break and
            style.provenance == .protected_literal and !style.preserve_whitespace and
            std.mem.indexOfAny(u8, value, "\r\n") != null)
        {
            var normalized: std.ArrayList(u8) = .empty;
            var whitespace = false;
            for (value) |ch| {
                if (ch == '\n' or ch == '\r' or ch == '\t') {
                    if (!whitespace) try normalized.append(self.a, ' ');
                    whitespace = true;
                } else {
                    try normalized.append(self.a, ch);
                    whitespace = ch == ' ';
                }
            }
            return self.textRaw(try normalized.toOwnedSlice(self.a), style);
        }
        if (self.poem_depth != 0 and style.kind != .line_break) {
            var at: usize = 0;
            while (std.mem.indexOfScalarPos(u8, value, at, '\n')) |lf| {
                try self.textRaw(value[at..lf], style);
                var break_style = style;
                break_style.kind = .line_break;
                try self.textRaw("\n", break_style);
                self.poem_line_indent = 0;
                style.poem_indent = null;
                style.classes = try self.poemClasses(style.classes, 0);
                at = lf + 1;
            }
            try self.textRaw(value[at..], style);
        } else try self.textRaw(value, style);
        if (style.kind == .line_break) self.poem_line_indent = 0;
    }
    fn inlineBoxFontAndInkEqual(left: Style, right: Style) bool {
        if (left.font_size_unknown or right.font_size_unknown) return false;
        inline for (.{ "font_scale", "font_scale_basis", "font_scale_set", "font_features", "font_family", "bold", "italic", "code", "small", "superscript", "subscript",
            "ordinary_action_origin", "ordinary_link_paint", "link_paint", "role" }) |field|
            if (!std.meta.eql(@field(left, field), @field(right, field))) return false;
        inline for (.{ "language", "classes" }) |field|
            if (!std.mem.eql(u8, @field(left, field), @field(right, field))) return false;
        inline for (.{ "foreground" }) |field| {
            const first = @field(left, field); const second = @field(right, field);
            if ((first == null) != (second == null)) return false;
            if (first) |value| if (!std.mem.eql(u8, value, second.?)) return false;
        }
        return true;
    }
    // Diagnostic-only u8 tag in reason_bits[48..55]; zero means no branch.
    // The scoped copied-cell/quote diagnostic owns lower bits and is ORed by
    // its caller. These tags neither grant geometry nor change error policy.
    const InlineBoxResolutionDiagnostic = enum(u8) {
        none = 0,
        constructed_binding_absent = 1,
        constructed_selection_rejected = 2,
        constructed_candidate_absent = 3,
        constructed_geometry_rejected = 4,
        constructed_resolution_absent = 5,
        isolated_source_ancestry_absent = 6,
        profile_geometry_unresolved = 7,
        isolated_geometry_unresolved = 8,
        fn bits(self: @This()) u64 { return @as(u64, @intFromEnum(self)) << 48; }
    };
    fn directWikiHeadingSpan(self: *const Renderer, line: []const u8, heading: Heading) ?[]const u8 {
        const tracked = self.body_missing orelse return null;
        const title = heading.title;
        if (self.in_reference or self.in_template_literal_scope or self.pre_block or self.parsed_pre or
            self.poem_depth != 0 or self.table_viewport_cell_source != null or
            !noLiParentSourceRange(tracked, line) or title.len == 0 or
            line.len != title.len + 2 * @as(usize, heading.level) or
            !inlineOverlaySameSourceSlice(title, line[heading.level..][0..title.len])) return null;
        const opener = syntax.tagAt(title, 0) orelse return null;
        if (!opener.is("span") or opener.closing or opener.self_closing or
            !formattingAngleAttributesBalanced(opener.attrs)) return null;
        const pair = syntax.matchingTag(title, opener) orelse return null;
        if (pair.end != title.len or pair.inner_end == opener.end or
            std.mem.indexOfAny(u8, title[opener.end..pair.inner_end], "<>[]{}'\r\n") != null) return null;
        return title;
    }

    // Transport only local facts about the exact authored SPAN. A clean
    // opening can carry these facts even when missing source elsewhere on the
    // page prevents issuing a complete ancestor class/ID inventory.
    fn inlineBoxAuthoredSelectorFacts(self: *Renderer, tag: syntax.Tag, element: *table_style_profile.TextElement) Error!void {
        if (self.paragraph_span_quotes) |receipt| {
            if (tag.is("span") and element.alternative_ancestry == null and element.source_key == @intFromPtr(tag.name.ptr) and
                receipt.root == self.native_inline_motion_root and receipt.epoch == self.native_inline_motion_epoch and
                self.body_depth == 1 and self.wikiClassOrdinaryState() and self.typed_table_depth == 0 and
                self.media_depth == 0 and self.ruby_depth == 0 and self.figure_caption_depth == 0)
            {
                if (self.dispatched_static_paragraph) |line| if (self.inline_missing) |tracked| {
                    if (localTrackedTagOpening(tracked, tag)) |opening| {
                        if (noLiParentSourceRange(tracked, opening)) if (receipt.map.copiedOriginal(opening)) |original| {
                            if (self.wikiCellCurrentBodyRange(receipt.root.source, original)) |owned| {
                                if (wikiClassContains(line, owned)) element.source_direct_parent_not_li = true;
                            }
                        };
                    }
                };
            }
        }
        if (self.wiki_heading_span_title) |issued| if (tag.is("span") and element.alternative_ancestry == null and
            element.source_key == @intFromPtr(tag.name.ptr)) {
            const tracked = self.inline_missing orelse return;
            if (localTrackedTagOpening(tracked, tag)) |opening| if (noLiParentSourceRange(tracked, opening))
                if (self.wikiCellCurrentBodyRange(MissingText.untracked(issued), opening)) |original| {
                    if (issued.ptr == original.ptr) element.source_direct_parent_not_li = true;
                };
        };
        if (!tag.is("span") or self.content_root != .parser_output or self.in_reference or self.in_template_literal_scope or
            self.pre_block or self.parsed_pre or self.poem_depth != 0 or self.media_depth != 0 or self.ruby_depth != 0 or
            self.table_viewport_cell_source != null or self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            element.alternative_ancestry != null or element.source_key != @intFromPtr(tag.name.ptr)) return;
        const root = self.native_inline_motion_root orelse return;
        if (!self.native_inline_motion_active or root.reference != null) return;
        const tracked = self.inline_missing orelse return;
        const opening = localTrackedTagOpening(tracked, tag) orelse return;
        if (!noLiParentSourceRange(tracked, opening)) return;
        const original_opening = self.wikiCellCurrentBodyRange(root.source, opening) orelse return;
        const source = root.source.bytes;
        const at = @intFromPtr(original_opening.ptr) - @intFromPtr(source.ptr);
        const original = syntax.tagAt(source, at) orelse return;
        if (!original.is("span") or original.closing or original.self_closing or original.end != at + original_opening.len) return;
        // The tracked original is an HTML SPAN, including inside a link label.
        // Its own selector subject cannot be a hyperlink.
        element.source_nonlink_element = true;
        element.source_fragment_target_absent = htmlOwnAttributePresence(&original, "id") == .absent;
        const parent = element.parent orelse return;
        if (!std.ascii.eqlIgnoreCase(parent.tag, "span") or at == 0) return;
        const parent_end = if (source[at - 1] == '>') at else end: {
            // A relative span can start with ordinary text before its overlay.
            // Authenticate the complete prefix from that live owner's opening.
            const owner = self.inline_box_owner orelse return;
            if (!wikiClassContains(owner.body, opening)) return;
            const length = @intFromPtr(opening.ptr) - @intFromPtr(owner.body.ptr);
            if (length == 0 or length > 4096 or length >= at or !observedReadyCaptionPlainText(owner.body[0..length])) return;
            const prefix = owner.body[0 .. length + opening.len];
            if (!noLiParentSourceRange(tracked, prefix)) return;
            const original_prefix = self.wikiCellCurrentBodyRange(root.source, prefix) orelse return;
            if (original_prefix.ptr != source[at - length ..].ptr) return;
            break :end at - length;
        };
        const start = std.mem.lastIndexOfScalar(u8, source[0..parent_end], '<') orelse return;
        const article_parent = syntax.tagAt(source, start) orelse return;
        if (!article_parent.is("span") or article_parent.closing or article_parent.self_closing or
            article_parent.end != parent_end or !noLiParentSourceRange(root.source, source[start..original.end]) or
            htmlOwnAttributePresence(&article_parent, "class") == .unknown) return;
        const pair = syntax.matchingTag(source, article_parent) orelse return;
        const child = syntax.matchingTag(source, original) orelse return;
        if (child.end > pair.inner_end) return;
        const classes = (try self.semanticAttribute(article_parent, "class")) orelse "";
        if (!std.mem.eql(u8, classes, parent.classes)) return;
        element.source_direct_parent_classes = classes;
    }

    fn inlineBoxListAncestorClasses(self: *Renderer, element: *const table_style_profile.TextElement,
        state: NativeInlineMotionState) Error!?[]const u8
    {
        const current_list = self.inline_box_root_list orelse return null;
        const host = self.native_article_host orelse return null;
        const held = switch (state) { .proved => |value| value, else => return null };
        if (self.content_root != .parser_output or !host.native_paragraph_css_subjects or self.context.observe_structure_only or
            self.native_inline_motion_root != held.root or self.native_inline_motion_epoch != held.epoch or held.epoch == 0 or
            held.root.reference != null or !host.matchesActive(self, held.root.source) or self.in_reference or
            self.in_template_literal_scope or self.typed_table_depth != 0 or self.table_viewport_cell_source != null or
            self.html_blockquote_flow or self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            self.media_depth != 0 or self.ruby_depth != 0 or self.poem_depth != 0 or self.pre_block or self.parsed_pre) return null;
        const list = self.wikiCellCurrentBodyRange(held.root.source, current_list) orelse return null;
        const root_tag = syntax.tagAt(list, 0) orelse return null;
        const pair = syntax.matchingTag(list, root_tag) orelse return null;
        if (!oneOf(root_tag.name, &.{ "ul", "ol" }) or pair.end != list.len) return null;
        var entry = held.last;
        var cursor: ?*const table_style_profile.TextElement = element;
        var depth: usize = 0;
        var saw_item = false;
        while (cursor) |node| : (cursor = node.parent) {
            const declaration = entry orelse return null;
            if (depth >= max_depth or declaration.origin != .html or node.alternative_ancestry != null or
                !std.mem.eql(u8, declaration.opening, declaration.opening_snapshot)) return null;
            depth += 1;
            const tag = syntax.tagAt(declaration.opening, 0) orelse return null;
            const mapped = self.wikiCellCurrentBodyRange(held.root.source, declaration.opening) orelse return null;
            if (!wikiClassContains(list, mapped) or tag.end != declaration.opening.len or !tag.is(node.tag) or
                node.source_key != @intFromPtr(tag.name.ptr) or htmlOwnAttributePresence(&tag, "class") == .unknown or
                !std.mem.eql(u8, node.classes, (try self.semanticAttribute(tag, "class")) orelse "")) return null;
            if (node.parent == null) {
