        }
        return if (count != 0) count else null;
    }
    fn externalUrlTarget(self: *Renderer, raw: []const u8) Error![]const u8 {
        var value = raw;
        if (literalDefaultlessExternalPath(raw)) |count| {
            // Browser navigation escapes braces in a URL path. This proof runs
            // on authored tokens, before entities can manufacture delimiters.
            var escaped: std.ArrayList(u8) = .empty;
            for (raw) |ch| switch (ch) {
                '{' => try escaped.appendSlice(self.a, "%7B"),
                '}' => try escaped.appendSlice(self.a, "%7D"),
                else => try escaped.append(self.a, ch),
            };
            value = try escaped.toOwnedSlice(self.a);
            self.unresolved_templates += count;
            self.fallbacks.missing_template = true;
        }
        if (std.mem.indexOfScalar(u8, value, '&') == null) return value;
        var out: std.ArrayList(u8) = .empty;
        var start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, value, start, '&')) |i| {
            try out.appendSlice(self.a, value[start..i]);
            var buf: [4]u8 = undefined;
            if (decodeEntity(value[i..], &buf, false)) |decoded| {
                // Literal lowercase entities are source delimiters handled by
                // DocIR. Other encoded angles belong to the URL, not its label.
                const delimiter = starts(value[i..], "&lt;") or starts(value[i..], "&gt;");
                if (!delimiter and std.mem.eql(u8, decoded.bytes, "<")) {
                    try out.appendSlice(self.a, "%3C");
                } else if (!delimiter and std.mem.eql(u8, decoded.bytes, ">")) {
                    try out.appendSlice(self.a, "%3E");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, " ")) {
                    try out.append(self.a, '+');
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\t")) {
                    try out.appendSlice(self.a, "%09");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\n")) {
                    try out.appendSlice(self.a, "%0A");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\r")) {
                    try out.appendSlice(self.a, "%EF%BF%BD");
                } else if (std.mem.eql(u8, decoded.bytes, "\"")) {
                    try out.appendSlice(self.a, "%22");
                } else if (std.mem.eql(u8, decoded.bytes, "\xc2\xa0")) {
                    try out.appendSlice(self.a, "%C2%A0");
                } else try out.appendSlice(self.a, decoded.bytes);
                start = i + decoded.consumed;
            } else {
                try out.append(self.a, '&');
                start = i + 1;
            }
        }
        try out.appendSlice(self.a, value[start..]);
        return out.toOwnedSlice(self.a);
    }
    // External-label parsing retains the outer action. A complete borrowed
    // bare URL inside that label still carries preprocessing's defaultless
    // parameter text; protect its proven braces without creating another link.
    fn literalParameterInInheritedExternalLabel(self: *const Renderer, tracked: MissingText, at: usize, end: usize, token: ir.InlineSpan, style: Style) bool {
        if (tracked.unknown or style.provenance != .parsed or style.kind != .external_link or
            style.target.len == 0 or !safeUrl(style.target) or unresolvedExternalActionTarget(style.target) or
            style.missing_nonaction or style.self_link_target != null or style.image != null or
            style.code or style.preserve_whitespace or self.pre_block or self.parsed_pre or self.in_template_literal_scope or
            self.inline_image_attribute or self.explicit_wiki_label != null or self.navigation_target_probe != null or
            at >= end or end > tracked.bytes.len or end - at > 4096 or
            token.kind != .external_link or token.external_label_prefix.len != 0 or
            token.target.len != end - at or token.target.ptr != tracked.bytes[at..].ptr or
            token.text.ptr != token.target.ptr or token.text.len != token.target.len) return false;
        const domain = self.inline_source_domain orelse return false;
        if (domain.source.ptr != tracked.bytes.ptr or domain.source.len != tracked.bytes.len) return false;
        for (tracked.ranges) |range| if (range.start < end and range.end > at) return false;
        for (tracked.literal_curly_ranges) |range| if (range.start < end and range.end > at) return false;
        for (tracked.generated_links) |range| if (range.start < end and range.end > at) return false;
        var iterator: ir.InlineIterator = .{ .input = tracked.bytes[at..], .renderer_boundaries = true };
        const parsed = iterator.next() orelse return false;
        if (parsed.kind != .external_link or iterator.cursor != end - at or
            parsed.target.ptr != token.target.ptr or parsed.target.len != token.target.len or
            parsed.text.ptr != parsed.target.ptr or parsed.text.len != parsed.target.len or parsed.external_label_prefix.len != 0) return false;
        return literalDefaultlessExternalParameter(token.target) != null;
    }

    fn externalUrlLabel(self: *Renderer, value: []const u8, style: Style, count_parameters: bool) Error!void {
        const literal_parameters = literalDefaultlessExternalParameter(value);
        if (literalDefaultlessExternalPath(value) != null or literal_parameters != null) {
            if (count_parameters) if (literal_parameters) |count| {
                self.unresolved_templates += count;
                self.fallbacks.missing_template = true;
            };
            // Preserve the authored bare-URL label; only navigation uses the
            // escaped spelling. The shared proof covers every brace below.
            var start: usize = 0;
            while (std.mem.indexOfPos(u8, value, start, "{{{")) |at| {
                const end = (std.mem.indexOfPos(u8, value, at + 3, "}}}") orelse unreachable) + 3;
                try self.text(value[start..at], style);
                try self.protectedLiteral(value[at..end], style);
                start = end;
            }
            try self.text(value[start..], style);
            return;
        }
        // Only the proven closing-brace runs are literal. Keep all surrounding
        // visible text parsed, with the same validated action and style.
        var start: usize = 0;
        while (std.mem.indexOfPos(u8, value, start, "}}")) |at| {
            try self.text(value[start..at], style);
            var end = at + 2;
            while (end < value.len and value[end] == '}') : (end += 1) {}
            var literal_style = style;
            literal_style.provenance = .protected_literal;
            try self.text(value[at..end], literal_style);
            start = end;
        }
        try self.text(value[start..], style);
    }
    pub fn link(self: *Renderer, label: []const u8, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        return self.linkWithMissing(MissingText.untracked(label), target, style, depth, external);
    }
    pub fn linkWithMissing(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        return self.linkWithMissingParameterProof(tracked, target, style, depth, external, null);
    }
    fn linkWithMissingParameterProof(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool, proof: ?ExternalLiteralParameterProof) Error!void {
        return self.linkWithSourceProof(tracked, target, style, depth, external, proof, null);
    }
    fn linkWithSourceProof(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool, proof: ?ExternalLiteralParameterProof, angle_source: ?[]const u8) Error!void {
        return self.linkWithRecognizedSource(tracked, target, style, depth, external, proof, angle_source, null, null);
    }
    fn linkWithRecognizedSource(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool, proof: ?ExternalLiteralParameterProof, angle_source: ?[]const u8, reopened_parent: ?ReopenedExternalParent, action_capture: ?*?Style) Error!void {
        const label = tracked.bytes;
        const angle_proven = external and ((if (angle_source) |source| ir.bracketedAngleProtocolTarget(source, target) else false) or
            (if (reopened_parent) |parent| parent.target.ptr == target.ptr and parent.target.len == target.len and parent.borrowedOriginal() != null else false));
        var s = style;
        const parameter_proven = external and if (proof) |p| externalLiteralParameterProofMatches(p, target) else false;
        const start = self.spans.items.len;
        defer if (parameter_proven) {
            // A child action never inherits the outer source proof.
            for (self.spans.items[start..]) |*span| if (span.kind == .external_link and span.target.ptr == target.ptr and span.target.len == target.len) {
                span.external_literal_parameter = proof;
            };
        };
        const resolved_target = if (external and !parameter_proven) try self.externalUrlTarget(target) else target;
        if (external and !parameter_proven and ir.literalUnclosedConditionalUrl(target) != null)
            return error.UncompiledTemplate;
        if (parameter_proven) {
            self.unresolved_templates += if (proof.?.literal_parent_source) |raw|
                ir.literalUnclosedConditionalUrl(raw).?
            else literalDefaultlessExternalParameter(target).?;
            self.fallbacks.missing_template = true;
        }
        if (external and !parameter_proven and unresolvedExternalActionTarget(resolved_target)) {
            self.fallbacks.rejected_external_target = true;
            // Retain an authored label and all its formatting, but never inherit
            // an outer action or fabricate a replacement destination.
            s.kind = .text;
            s.target = "";
            if (std.mem.eql(u8, label, target)) {
                self.unresolved_templates += 1;
                return error.UncompiledTemplate;
            }
            const label_start = self.spans.items.len;
            try self.inlineTextWithMissing(try missingSlice(self.a, tracked, label), s, depth + 1);
            // Only this rejected action's emitted label is checked. Real
            // protected/entity literals are not deferred source instructions.
            var previous: u8 = 0;
            for (self.spans.items[label_start..]) |span| {
                if (span.kind == .line_break or span.provenance != .parsed) {
                    previous = 0;
                    continue;
                }
                for (span.text) |ch| {
                    if ((ch == '{' or ch == '}') and ch == previous) {
                        self.unresolved_templates += 1;
                        return error.UncompiledTemplate;
                    }
                    previous = ch;
                }
            }
            return;
        }
        if (resolved_target.len != 0 and (!external or safeUrl(resolved_target) or (angle_proven and std.mem.eql(u8, resolved_target, target)))) {
            s.kind = if (external) .external_link else .link;
            s.target = resolved_target;
            const same_observed_caption_action = !external and self.figure_caption_depth != 0 and
                style.kind == .link and style.self_link_target == null and
                style.target.ptr == resolved_target.ptr and style.target.len == resolved_target.len and
                if (self.explicit_wiki_label) |scope| scope.kind == .link and
                    scope.target.ptr == resolved_target.ptr and scope.target.len == resolved_target.len and
                    scope.observed_caption_depth == depth and
                    (if (scope.observed_caption_label) |bound| bound.ptr == label.ptr and bound.len == label.len else false) and
                    (if (self.observed_figure_caption) |session| session.links.len != 0 else false) else false;
            const same_table_action = style.link_paint != null and self.tableLinkActionCurrent(style, resolved_target) and
                if (self.explicit_wiki_label) |scope| scope.kind == style.kind and
                    scope.target.ptr == resolved_target.ptr and scope.target.len == resolved_target.len else false;
            if (self.pageStyleDomain() != null and !same_observed_caption_action and !same_table_action and
                !self.sameOrdinaryActionGroupLabel(style, resolved_target, label, depth) and
                !( !external and self.sameOrdinaryLabelAction(style, resolved_target, label, depth)))
                s = try self.wikiLinkStyleIn(style, .{ .target = resolved_target, .external = external }, target);
            if (!external) s.poem_independent_parse = false;
        }
        if (action_capture) |capture| capture.* = s;
        if (external and std.mem.eql(u8, label, target)) {
            const decoded_label = try self.entityText(label);
            // URL text containing encoded controls/whitespace uses its escaped
            // destination spelling, never raw navigation control characters.
            const escaped_label = std.mem.indexOfAny(u8, decoded_label, " \t\n\r\"") != null or
                std.mem.indexOf(u8, decoded_label, "\xc2\xa0") != null;
            const visible = if (escaped_label) resolved_target else decoded_label;
            if (s.kind == .external_link and safeUrl(resolved_target) and
                (parameter_proven or !unresolvedExternalActionTarget(resolved_target)))
                try self.externalUrlLabel(visible, s, parameter_proven or literalDefaultlessExternalPath(target) == null)
            else
                try self.text(visible, s);
            return;
        }
        const label_missing = try missingSlice(self.a, tracked, label);
        const previous_label = self.explicit_wiki_label;
        defer self.explicit_wiki_label = previous_label;
        if (self.explicit_wiki_label) |*scope| {
            if (scope.ordinary_closing_pair) |*closing| {
                // This is the same whole-label metadata slice, not a byte-equal
                // substitution. Keep the original issuer and action identities.
                if (closing.current_label.ptr == label.ptr and closing.current_label.len == label.len and
                    self.isExplicitLabelClosingPair(s, closing.current_pair))
                {
                    const offset = @intFromPtr(closing.current_pair.ptr) - @intFromPtr(label.ptr);
                    closing.current_label = label_missing.bytes;
                    closing.current_pair = label_missing.bytes[offset .. offset + 2];
                }
            }
        }
        try self.inlineTextWithMissing(label_missing, s, depth + 1);
    }
    fn plannedCitation(self: *Renderer, tag: syntax.Tag, style: Style) Error!void {
        const plan = self.context.citations orelse return error.InvalidPreContext;
        const raw = tag.attr(plan.attribute) orelse return error.InvalidPreContext;
        const event_id = std.fmt.parseInt(usize, raw, 10) catch return error.InvalidPreContext;
        if (event_id >= plan.events.items.len) return error.InvalidPreContext;
        const event = plan.events.items[event_id];
        if (!std.ascii.eqlIgnoreCase(@tagName(event.tag), tag.name)) return error.InvalidPreContext;
        _ = try self.semanticAttribute(tag, "name");
        _ = try self.semanticAttribute(tag, "group");
        _ = try self.semanticAttribute(tag, "follow");
        if (event.authored_error) {
            self.fallbacks.rendered_extension_error = true;
            try self.text("[Reference error: invalid citation]", .{ .role = .citation, .provenance = .protected_literal });
        }
        const item_id = event.item orelse return;
        if (item_id >= plan.items.items.len) return error.InvalidPreContext;
        const item = plan.items.items[item_id];
        var projection: ?usize = null;
        for (self.citation_locals.items, 0..) |value, index| if (value.plan == plan) {
            projection = index;
            break;
        };
        if (projection == null) {
            const indices = try self.a.alloc(?usize, plan.items.items.len);
            @memset(indices, null);
            try self.citation_locals.append(self.a, .{ .plan = plan, .indices = indices });
            projection = self.citation_locals.items.len - 1;
        }
        const indices = self.citation_locals.items[projection.?].indices;
        var local = indices[item_id];
        if (local == null) {
            var ordinal: ?u32 = null;
            if (item.kind == .note) {
                // The product consolidates footers: visible owner-local group
                // ordinals continue across source epochs; fragments consume none.
                if (item.group.len == 0) {
                    self.default_group_reference_count += 1;
                    ordinal = std.math.cast(u32, self.default_group_reference_count) orelse return error.RenderLimit;
                } else {
                    ordinal = 1;
                    for (self.refs.items) |ref_value| if (ref_value.kind == .note and std.mem.eql(u8, ref_value.group, item.group)) {
                        ordinal = std.math.add(u32, ordinal.?, 1) catch return error.RenderLimit;
                    };
                }
            }
            const index = self.refs.items.len;
            try self.refs.append(self.a, .{ .kind = item.kind, .number = index + 1, .group_number = ordinal, .name = item.name, .group = item.group, .body = if (item.body) |body_value| body_value.bytes else "", .missing = item.body, .citation_plan = plan, .citation_item = item_id });
            indices[item_id] = index;
            local = index;
        }
        if (event.marker) try self.referenceMarker(local.?, style);
    }
    fn plannedPoemScope(self: *Renderer, tag: syntax.Tag) Error!bool {
        const plan = self.context.citations orelse return false;
        const raw = tag.attr(plan.attribute) orelse return false;
        const id = std.fmt.parseInt(usize, raw, 10) catch return error.InvalidPreContext;
        if (id >= plan.events.items.len or plan.events.items[id].tag != .poem) return error.InvalidPreContext;
        return true;
    }
    fn citationFooterOrder(self: *Renderer) Error![]const Reference {
        if (self.citation_locals.items.len == 0) return self.refs.items;
        const FinalItem = struct {
            index: usize,
            position: usize,
            fragment: bool,
            fn lessThan(_: void, left: @This(), right: @This()) bool {
                if (left.position != right.position) return left.position < right.position;
                if (left.fragment != right.fragment) return left.fragment;
                return left.index < right.index;
            }
        };
        var result: std.ArrayList(Reference) = .empty;
        var seen_plans: std.ArrayList(*const CitationPlan) = .empty;
        defer seen_plans.deinit(self.a);
        for (self.refs.items) |ref_value| {
            const plan = ref_value.citation_plan orelse {
                try result.append(self.a, ref_value);
                continue;
            };
            var seen = false;
            for (seen_plans.items) |prior| if (prior == plan) {
                seen = true;
                break;
            };
            if (seen) continue;
            try seen_plans.append(self.a, plan);
            const indices = found: {
                for (self.citation_locals.items) |value| if (value.plan == plan) break :found value.indices;
                return error.InvalidPreContext;
            };
            const explicit_count = if (plan.final_batches.items.len == 0)
                plan.batches.items.len
            else
                plan.final_batches.items[0];
            if (explicit_count > plan.batches.items.len) return error.InvalidPreContext;
            for (plan.batches.items[0..explicit_count]) |batch| for (batch.items) |item_id| {
                if (item_id >= indices.len) return error.InvalidPreContext;
                if (indices[item_id]) |index| try result.append(self.a, self.refs.items[index]);
            };
            var final_items: std.ArrayList(FinalItem) = .empty;
            defer final_items.deinit(self.a);
            for (plan.final_batches.items, 0..) |batch_id, final_index| {
                if (batch_id != explicit_count + final_index or batch_id >= plan.batches.items.len)
                    return error.InvalidPreContext;
                const batch = plan.batches.items[batch_id];
                var first_local: usize = std.math.maxInt(usize);
                for (batch.items) |item_id| {
                    if (item_id >= indices.len) return error.InvalidPreContext;
                    if (indices[item_id]) |index| first_local = @min(first_local, index);
                }
                for (batch.items) |item_id| if (indices[item_id]) |index| {
                    const fragment = self.refs.items[index].kind == .fragment;
                    try final_items.append(self.a, .{
                        .index = index,
                        .position = if (fragment) first_local else index,
                        .fragment = fragment,
                    });
                };
            }
            std.mem.sort(FinalItem, final_items.items, {}, FinalItem.lessThan);
            for (final_items.items) |item| try result.append(self.a, self.refs.items[item.index]);
        }
        return result.toOwnedSlice(self.a);
    }
    fn referenceIndex(self: *Renderer, name: []const u8, group: []const u8, body: []const u8) Error!?usize {
        const use_short_name_compare = self.refs.items.len >= 16;
        if (name.len != 0) for (self.refs.items, 0..) |*ref, i| {
            const same_name = if (use_short_name_compare) referenceStringEqual(ref.name, name) else std.mem.eql(u8, ref.name, name);
            if (!same_name or !std.mem.eql(u8, ref.group, group)) continue;
            if (ref.body.len == 0 and body.len != 0) {
                ref.body = body;
                ref.missing = if (self.inline_missing) |parent| try missingSlice(self.a, parent, body) else if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
            }
            return i;
        };
        var resolved_body = body;
        var resolved_missing = if (self.inline_missing) |parent| try missingSlice(self.a, parent, body) else if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
        // Authenticated native phase definitions include opaque Poem bodies
        // in emitted page order. The legacy raw table cannot see those bodies.
        // Ordinary/legacy calls retain the exact previous table and precedence.
        const page_definitions = if (self.poem_definitions_complete) self.ref_defs.items else self.page_reference_definitions;
        if (name.len != 0) for (page_definitions) |definition| {
            if (definition.body.len != 0 and std.mem.eql(u8, definition.name, name) and std.mem.eql(u8, definition.group, group)) {
                resolved_body = definition.body;
                resolved_missing = definition.missing orelse MissingText.transformed(definition.body);
                break;
            }
        };
        if (name.len != 0 and resolved_body.len == 0) for (self.ref_defs.items) |definition| {
            if (std.mem.eql(u8, definition.name, name) and std.mem.eql(u8, definition.group, group)) {
                resolved_body = definition.body;
                resolved_missing = definition.missing orelse MissingText.transformed(definition.body);
                break;
            }
        };
        if (!self.spend()) return null;
        const index = self.refs.items.len;
        var group_number: usize = 1;
        if (group.len == 0) {
            self.default_group_reference_count += 1;
            group_number = self.default_group_reference_count;
        } else {
            for (self.refs.items) |ref| {
                if (ref.kind == .note and std.mem.eql(u8, ref.group, group)) group_number += 1;
            }
        }
        try self.refs.append(self.a, .{ .number = index + 1, .group_number = std.math.cast(u32, group_number) orelse return error.RenderLimit, .name = name, .group = group, .body = resolved_body, .missing = resolved_missing, .poem = self.poem_depth != 0, .poem_direction = self.poem_direction });
        return index;
    }
    fn reference(self: *Renderer, name: []const u8, group: []const u8, body: []const u8, style: Style) Error!void {
        if (self.in_reference) {
            try self.text("[nested reference]", style);
            return;
        }
        const index = (try self.referenceIndex(name, group, body)) orelse {
            try self.text("[render output truncated]", style);
            return;
        };
        try self.referenceMarker(index, style);
    }
    fn referenceMarker(self: *Renderer, index: usize, style: Style) Error!void {
        const ref = self.refs.items[index];
        const group = ref.group;
        var s = style;
        s.superscript = true;
        s.role = .reference;
        s.kind = .link;
        s.target = try std.fmt.allocPrint(self.a, "#reference-{d}", .{ref.number});
        const marker = if (group.len == 0)
            try std.fmt.allocPrint(self.a, "[{d}]", .{ref.group_number.?})
        else
            try std.fmt.allocPrint(self.a, "[{s} {d}]", .{ group, ref.group_number.? });
        // Cite armors its generated label with safeEncodeAttribute before
        // recursive parsing. The authored group is display-only here; its
        // exact identity stays in refs, and the synthesized target is validated.
        s.provenance = .protected_literal;
        try self.text(marker, s);
    }
    fn referenceDefinitions(self: *Renderer, content: []const u8, default_group: []const u8) Error!void {
        try self.referenceDefinitionsInner(content, default_group, 0, false);
    }
    fn referenceDefinitionsInner(self: *Renderer, content: []const u8, default_group: []const u8, depth: usize, list_defined: bool) Error!void {
        if (depth >= max_depth) {
            self.fallbacks.render_limit = true;
            return;
        }
        var pos: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        var next_tag = std.mem.indexOfScalar(u8, content, '<');
        var next_item = if (self.poem_items.items.len != 0) std.mem.indexOf(u8, content, poem_prefix) else null;
        while (true) {
            if (next_tag) |at| if (at < pos) {
                next_tag = std.mem.indexOfScalarPos(u8, content, pos, '<');
            };
            if (next_item) |at| if (at < pos) {
                next_item = std.mem.indexOfPos(u8, content, pos, poem_prefix);
            };
            const open = next_tag orelse content.len;
            const marker = next_item orelse content.len;
            if (open == content.len and marker == content.len) break;
            if (marker < open) {
                const item = self.poemItemAt(content[marker..]) orelse {
                    pos = marker + poem_prefix.len;
                    continue;
                };
                pos = marker + item.token.len;
                if (item.kind != .literal or !std.mem.eql(u8, item.tag, "poem")) continue;
                if (self.poem_definition_dispatches >= max_nodes) {
