    const ReferenceTableLink = struct { start: usize, inner_end: usize, end: usize };

    // Tables are parsed before internal links. Restrict this recovery to an
    // otherwise empty target surrounding one complete physical table; neither
    // a label nor an ordinary target may lend its body to this proof.
    fn referenceTableLink(input: []const u8, at: usize, scan: *syntax.OpaqueScan) ?ReferenceTableLink {
        if (!starts(input[at..], "[[")) return null;
        const pair = syntax.balancedWithOpaqueScan(input, at, scan) orelse return null;
        var first = at + 2;
        while (first < pair.inner_end and std.ascii.isWhitespace(input[first])) : (first += 1) {}
        if (first == at + 2 or input[first - 1] != '\n' or !starts(input[first..pair.inner_end], "{|")) return null;
        var last = pair.inner_end;
        while (last > first and std.ascii.isWhitespace(input[last - 1])) : (last -= 1) {}
        if (last < first + 4 or !std.mem.eql(u8, input[last - 2 .. last], "|}")) return null;
        const close = last - 2;
        if (close == 0 or input[close - 1] != '\n') return null;
        // Extra table delimiters, even in protected subdomains, remain outside
        // this finite proof. The ordinary parser still owns their validation.
        if (std.mem.indexOf(u8, input[first + 2 .. close], "{|") != null or
            std.mem.indexOf(u8, input[first + 2 .. close], "|}") != null) return null;
        return .{ .start = at, .inner_end = pair.inner_end, .end = pair.end };
    }

    fn referenceTableFormatting(name: []const u8) bool {
        return oneOf(name, &.{ "sup", "sub", "small", "big", "b", "strong", "i", "em", "u", "s", "strike", "del", "span", "font" });
    }

    fn nextReferenceTableLink(input: []const u8, start: usize) ?ReferenceTableLink {
        var scan: syntax.OpaqueScan = .{};
        var at = start;
        while (at < input.len) {
            if ((at == 0 or input[at - 1] == '\n') and (input[at] == ' ' or input[at] == '\t')) {
                at = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                if (at < input.len) at += 1;
                continue;
            }
            if (input[at] == '<') {
                if (scan.protectedEnd(input, at, null)) |end| { at = end; continue; }
                const tag = scan.tagAt(input, at, null) orelse return null;
                if (!tag.closing and !tag.self_closing and !referenceTableFormatting(tag.name)) {
                    at = if (syntax.matchingTagWithOpaqueScan(input, tag, &scan)) |pair| pair.end else input.len;
                } else {
                    if (!tag.closing and !tag.self_closing and syntax.matchingTagWithOpaqueScan(input, tag, &scan) == null) return null;
                    at = tag.end;
                }
                continue;
            }
            if (starts(input[at..], "{{")) {
                at = (syntax.balancedWithOpaqueScan(input, at, &scan) orelse return null).end;
                continue;
            }
            if (starts(input[at..], "[[")) {
                if (referenceTableLink(input, at, &scan)) |found| return found;
                at = (syntax.balancedWithOpaqueScan(input, at, &scan) orelse return null).end;
                continue;
            }
            if (input[at] == '[') {
                at = (std.mem.indexOfScalarPos(u8, input, at + 1, ']') orelse return null) + 1;
                continue;
            }
            at += 1;
        }
        return null;
    }

    fn prepareReferenceTableLinks(self: *Renderer, source: MissingText) Error!MissingText {
        if (!self.in_reference or source.unknown or self.pre_block or self.parsed_pre or
            self.block_formatting.code or self.in_template_literal_scope or
            self.body_link_target.len != 0 or self.inline_source_domain != null) return source;
        const input = source.bytes;
        if (std.mem.indexOf(u8, input, "[[") == null or std.mem.indexOf(u8, input, "{|") == null) return source;
        try generated_link.validateRanges(input, source.generated_source, source.generated_links);
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        var emitted: usize = 0;
        var cursor: usize = 0;
        while (nextReferenceTableLink(input, cursor)) |found| {
            cursor = found.end;
            var trusted = true;
            for (source.ranges) |range| if (range.start < found.end and range.end > found.start) { trusted = false; };
            for (source.generated_links) |range| if (range.start < found.end and range.end > found.start) { trusted = false; };
            if (!trusted) continue;
            try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, found.start);
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.start, "&#91;");
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.start + 1, "&#91;");
            try self.appendMissingHeadingSourceCopy(&out, &copies, source, found.start + 2, found.inner_end);
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.inner_end, "&#93;");
            try self.appendMissingHeadingSourceEdit(&out, &copies, source, found.inner_end + 1, "&#93;");
            emitted = found.end;
            self.fallbacks.literal_markup = true;
        }
        if (emitted == 0) return source;
        try self.appendMissingHeadingSourceCopy(&out, &copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, copies.items);
        return result;
    }

    // Table handling precedes inline formatting and link handling. Only
    // balanced supported formatting may expose its physical table lines here;
    // action, code, template and opaque domains remain separate.
    fn referenceHasWikiTableBody(input: []const u8) bool {
        return referenceHasWikiTableBodyDepth(input, 0, true);
    }
    fn referenceHasWikiTableBodyDepth(input: []const u8, depth: usize, begins_line: bool) bool {
        if (depth >= max_depth) return false;
        if (nextReferenceTableLink(input, 0) != null) return true;
        var scan: syntax.OpaqueScan = .{};
        var missing_nowiki = false;
        var at: usize = 0;
        while (at < input.len) {
            if ((at == 0 and begins_line) or (at != 0 and input[at - 1] == '\n')) {
                const end = std.mem.indexOfScalarPos(u8, input, at, '\n') orelse input.len;
                const line = std.mem.trimEnd(u8, input[at..end], "\r");
                if (line.len != 0 and line[0] != ' ' and line[0] != '\t' and wikiTableIndent(line) != null)
                    return true;
            }
            if (input[at] == '<') {
                if (scan.protectedEnd(input, at, &missing_nowiki)) |end| {
                    at = end;
                    continue;
                }
                if (scan.tagAt(input, at, &missing_nowiki)) |tag| {
                    if (!tag.closing and !tag.self_closing and knownInlineHtmlName(tag.name)) {
                        if (syntax.matchingTagWithOpaqueScan(input, tag, &scan)) |pair| {
                            if (referenceTableFormatting(tag.name) and referenceHasWikiTableBodyDepth(input[tag.end..pair.inner_end], depth + 1, false)) return true;
                            at = pair.end;
                            continue;
                        }
                        return false;
                    }
                    at = tag.end;
                    continue;
                }
            }
            if (starts(input[at..], "{{")) {
                if (syntax.balancedWithOpaqueScan(input, at, &scan)) |pair| {
                    at = pair.end;
                } else {
                    // Match the existing inline diagnostic recovery boundary.
                    // An unmatched prefix does not own later physical lines.
                    // Rendering still emits its diagnostic and retains unknown
                    // dependency state; this selects blocks, not literal text.
                    at = malformedTemplateRecoveryEnd(input, at);
                }
                continue;
            }
            if (starts(input[at..], "[[")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &scan) orelse return false;
                at = pair.end;
                continue;
            }
            at += 1;
        }
        return false;
    }
    fn hasFigureBody(self: *Renderer, source: []const u8) bool {
        var at: usize = 0;
        var scan: syntax.OpaqueScan = .{};
        while (at < source.len) {
            if (scan.protectedEnd(source, at, null)) |end| { at = end; continue; }
            if (starts(source[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(source, at, &scan) orelse return false;
                at = pair.end;
                continue;
            }
            if (starts(source[at..], "[[")) {
                const pair = syntax.balancedWithOpaqueScan(source, at, &scan) orelse return false;
                const body = source[at + 2 .. pair.end - 2];
                at = pair.end;
                const pipe = syntax.delimiter(body, "|", 0) orelse continue;
                const target = trim(body[0..pipe]);
                if (target.len == 0 or target[0] == ':' or self.namespaceOfTarget(target) != 6) continue;
                const colon = std.mem.indexOfScalar(u8, target, ':') orelse continue;
                const file = target[colon + 1 ..];
                if (media_types.referencedKind(file) != .image) continue;
                var seen_format = false;
                var pos = pipe + 1;
                while (pos <= body.len) {
                    const end = syntax.delimiter(body, "|", pos) orelse body.len;
                    if (self.mediaOption(trim(body[pos..end]), mediaOptionMode(file, false), &seen_format)) |option|
                        if (oneOf(option.id, &.{ "img_thumbnail", "img_framed" })) return true;
                    if (end == body.len) break;
                    pos = end + 1;
                }
                continue;
            }
            if (scan.tagAt(source, at, null)) |tag| { at = tag.end; continue; }
            at += 1;
        }
        return false;
    }
    pub fn finishReferences(self: *Renderer) Error![]const Reference {
        self.in_reference = true;
        defer self.in_reference = false;
        for (self.refs.items) |*ref| {
            const previous_citations = self.context.citations;
            self.context.citations = ref.citation_plan;
            defer self.context.citations = previous_citations;
            try self.loadPoemPhase();
            const previous_depth = self.poem_depth;
            const previous_direction = self.poem_direction;
            const previous_style = self.poem_base_style;
            const previous_indent = self.poem_line_indent;
            self.poem_depth = if (ref.poem) 1 else 0;
            self.poem_direction = ref.poem_direction;
            self.poem_base_style = .{};
            self.poem_line_indent = 0;
            defer {
                self.poem_depth = previous_depth;
                self.poem_direction = previous_direction;
                self.poem_base_style = previous_style;
                self.poem_line_indent = previous_indent;
            }
            const source = if (ref.body.len != 0) ref.missing orelse MissingText.transformed(ref.body) else MissingText.untracked("Reference text unavailable");
            if (referenceHasWikiTableBody(source.bytes) or self.hasFigureBody(source.bytes) or hasContainerBody(source.bytes, false) or try self.hasAlignedBlockScope(source.bytes)) {
                // Retain typed grids and proved paragraph alignment. A flat
                // span projection cannot preserve either block representation.
                // Reference bodies own a separate tracked source domain; their
                // headings must not publish main-page source offsets.
                const body_before = .{
                    .headings = self.page_html_heading_openings,
                    .pre = self.pre_block, .parsed_pre = self.parsed_pre,
                    .formatting = self.block_formatting,
                    .attributes = self.body_formatting_attributes,
                    .language_direction = self.body_language_direction,
                    .link_target = self.body_link_target,
                    .domain = self.inline_source_domain,
                    .table = self.inline_table_boundaries,
                    .blockquote_flow = self.html_blockquote_flow,
                    .quote_seed = self.next_quote_seed,
                    .table_style_scope = self.table_style_scope,
                    .table_css_ancestor_classes = self.table_css_ancestor_classes,
                    .table_style_unresolved = self.table_style_unresolved,
                    .table_style_font_unresolved = self.table_style_font_unresolved,
                };
                defer {
                    self.page_html_heading_openings = body_before.headings;
                    self.pre_block = body_before.pre;
                    self.parsed_pre = body_before.parsed_pre;
                    self.block_formatting = body_before.formatting;
                    self.body_formatting_attributes = body_before.attributes;
                    self.body_language_direction = body_before.language_direction;
                    self.body_link_target = body_before.link_target;
                    self.inline_source_domain = body_before.domain;
                    self.inline_table_boundaries = body_before.table;
                    self.html_blockquote_flow = body_before.blockquote_flow;
                    self.next_quote_seed = body_before.quote_seed;
                    self.table_style_scope = body_before.table_style_scope;
                    self.table_css_ancestor_classes = body_before.table_css_ancestor_classes;
                    self.table_style_unresolved = body_before.table_style_unresolved;
                    self.table_style_font_unresolved = body_before.table_style_font_unresolved;
                }
                self.page_html_heading_openings = null;
                self.pre_block = false;
                self.parsed_pre = false;
                self.block_formatting = .{};
                self.body_formatting_attributes = .{};
                self.body_language_direction = null;
                self.body_link_target = "";
                self.inline_source_domain = null;
                self.inline_table_boundaries = null;
                self.html_blockquote_flow = false;
                self.next_quote_seed = null;
                self.table_style_scope = 0;
                self.table_css_ancestor_classes = "";
                self.table_style_unresolved = false;
                self.table_style_font_unresolved = false;
                ref.blocks = try self.renderBodyWithMissing(source);
                ref.spans = &.{};
            } else {
                ref.blocks = null;
                ref.spans = try self.parseSpansWithMissing(source, .{});
            }
        }
        return self.citationFooterOrder();
    }
    fn gallery(self: *Renderer, input: []const u8, tag: syntax.Tag, style: Style, _: usize) Error!void {
        var lines = std.mem.splitScalar(u8, input, '\n');
        var emitted = false;
        // Gallery-wide captions are separately parsed extension attributes, not
        // filenames or one of the per-item media captions.
        if (try self.semanticAttribute(tag, "caption")) |caption| {
            if (trim(caption).len != 0) {
                if (self.media_depth >= max_depth) {
                    self.fallbacks.render_limit = true;
                    try self.protectedLiteral(caption, style);
                    emitted = true;
                } else {
                    self.media_depth += 1;
                    defer self.media_depth -= 1;
                    const caption_spans = try self.parseSpans(caption, style);
                    try self.spans.appendSlice(self.a, caption_spans);
                    emitted = caption_spans.len != 0;
                }
            }
        }
        while (lines.next()) |raw_line| {
            const line = trim(raw_line);
            if (line.len == 0) continue;
            const pipe = syntax.delimiter(line, "|", 0);
            const raw_file = trim(line[0 .. pipe orelse line.len]);
            const colon = std.mem.indexOfScalar(u8, raw_file, ':');
            const file = if (colon != null and self.namespaceOfTarget(raw_file) == 6) raw_file[colon.? + 1 ..] else raw_file;
            if (media_types.referencedKind(file) == null) continue;
            const options = if (pipe) |at_pipe| trim(line[at_pipe + 1 ..]) else "";
            const selected_label = self.mediaCaptionChoice(options, file, mediaOptionMode(file, true));
            const caption = selected_label.text;
            var media_style = style;
            media_style.classes = try self.mediaCaptionClasses("", style.classes);
            media_style = try self.mediaActionStyle(media_style, file, selected_label.link_target);
            const visible_label = if (caption.len == 0) file else caption;
            const caption_style: ?MediaCaptionCapture = if (std.mem.eql(u8, caption, visible_label)) .{ .style = mediaCaptionStyle(media_style, false, selected_label.authored_caption) } else null;
            const parsed = try self.mediaFileKindWithSpans(file, caption, null, caption_style);
            media_style.classes = try self.mediaCaptionClasses(try self.mediaClasses(file), style.classes);
            if (emitted) try self.lineBreak(style);
            emitted = true;
            try self.mediaLabel(visible_label, media_style, false, selected_label.authored_caption, false, parsed);
        }
    }
    const ImageMapRejection = struct { reason: []const u8, offset: usize };
    fn imageMapIncomplete(complete: *bool, first: *?ImageMapRejection, reason: []const u8, offset: usize) void {
        if (first.* == null) first.* = .{ .reason = reason, .offset = offset };
        complete.* = false;
    }
    fn imageMapUnavailable(self: *Renderer, input: []const u8, offset: usize, reason: []const u8, bits: u64) Error {
        self.tracePresentationRejection("imagemap", reason, input, offset, bits, error.UncompiledPresentation);
        self.fallbacks.unrepresented_image_map = true;
        self.fallbacks.unsupported_element = true;
        return error.UncompiledPresentation;
    }
    fn imageMapActionBudget(action: presentation_types.MapAction, remaining: *usize) bool {
        for ([_][]const u8{ action.target, action.target_fragment orelse "", action.label }) |value| {
            if (value.len > remaining.*) return false;
            remaining.* -= value.len;
        }
        return true;
    }
    fn imageMapAction(self: *Renderer, spans: []const Span, source_target: []const u8, external: bool) Error!?presentation_types.MapAction {
        const target = if (external) try self.externalUrlTarget(source_target) else source_target;
        if (target.len == 0 or (if (external) !safeUrl(target) or unresolvedExternalActionTarget(target) else unresolvedActionTarget(target))) return null;
        const current_page_action = current: {
            if (!external) for (spans) |span| {
                if (span.self_link) break :current try self.isSelfLink(target);
            };
            break :current false;
        };
        var label: std.ArrayList(u8) = .empty;
        defer label.deinit(self.a);
        const maximum: usize = 32 * 1024 * 1024;
        for (spans) |span| {
            if (span.image != null or span.generated_link != null or span.generated_diagnostic or
                span.external_literal_parameter != null or span.target_fragment != null or span.tooltip != null) return null;
            // ImageMap builds area/default hrefs directly from Title, including
            // the current page. Keep the ordinary text self-link nonaction;
            // only its separately validated spatial action retains the target.
            if (span.self_link) {
                if (!current_page_action or span.target.len != 0 or
                    (span.kind != .text and span.kind != .line_break)) return null;
            } else {
                const expected: ir.InlineKind = if (external) .external_link else .link;
                if (span.kind != expected and span.kind != .line_break) return null;
                if (!std.mem.eql(u8, span.target, target)) return null;
            }
            const visible = if (span.kind == .line_break) "\n" else span.text;
            if (visible.len > maximum - label.items.len) return null;
