    }
    const PreparedFigureGeometry = struct { value: Figure, caption_style: Style, missing_style: ?Style = null, caption_parent: ?PreparedCaptionParent = null, resolutions: ?[4]table_style_profile.FigureStyle = null, fonts: ?[3]f32 = null, image_style: ?Style = null, observed_caption: ?ObservedFigureCaptionSession = null };
    // Compare the complete pure preparation, including byte-valued colors.
    // Non-string borrowed slices/pointers retain identity; neither arm parses
    // captions or creates references/media/actions.
    fn sameFigurePreparationValue(left: anytype, right: @TypeOf(left)) bool {
        const T = @TypeOf(left);
        switch (@typeInfo(T)) {
            .@"struct" => |info| {
                inline for (info.field_names) |field| if (!sameFigurePreparationValue(@field(left, field), @field(right, field))) return false;
                return true;
            },
            .@"union" => |info| {
                const Tag = info.tag_type orelse return std.meta.eql(left, right);
                if (@as(Tag, left) != @as(Tag, right)) return false;
                return switch (left) { inline else => |value, tag| sameFigurePreparationValue(value, @field(right, @tagName(tag))) };
            },
            .optional => {
                const l = left orelse return right == null;
                const r = right orelse return false;
                return sameFigurePreparationValue(l, r);
            },
            .array => {
                for (left, right) |l, r| if (!sameFigurePreparationValue(l, r)) return false;
                return true;
            },
            .pointer => |info| {
                if (info.size == .slice) {
                    if (info.child == u8) return std.mem.eql(u8, left, right);
                    if (left.len == 0 and right.len == 0) return true;
                }
                return std.meta.eql(left, right);
            },
            else => return std.meta.eql(left, right),
        }
    }
    // Native quote normalization emits bare B nodes inside local-link labels.
    // This is only a node/class inventory; the ordinary parser owns every
    // action, byte and bold style. Keep all other label markup conservative.
    fn figureCaptionBoldLocalLabel(label: []const u8) bool {
        if (trim(label).len == 0 or !std.unicode.utf8ValidateSlice(label) or
            std.mem.indexOf(u8, label, "__") != null) return false;
        var pos: usize = 0;
        var representation: u2 = 0; // 1 is raw triple quotes, 2 is canonical B.
        var in_bold = false;
        var bold_start: usize = 0;
        var observed_bold = false;
        while (pos < label.len) {
            if (label[pos] == 39) {
                if (representation == 2) return false;
                var end = pos + 1;
                while (end < label.len and label[end] == 39) : (end += 1) {}
                if (end - pos != 3) return false;
                representation = 1;
                if (in_bold) {
                    if (trim(label[bold_start..pos]).len == 0) return false;
                    in_bold = false; observed_bold = true;
                } else { in_bold = true; bold_start = end; }
                pos = end;
                continue;
            }
            if (label[pos] == '<') {
                if (representation == 1) return false;
                representation = 2;
                if (starts(label[pos..], "<b>")) {
                    if (in_bold) return false;
                    in_bold = true; pos += 3; bold_start = pos;
                } else if (starts(label[pos..], "</b>")) {
                    if (!in_bold or trim(label[bold_start..pos]).len == 0) return false;
                    in_bold = false; observed_bold = true; pos += 4;
                } else return false;
                continue;
            }
            if (label[pos] < 0x20 or label[pos] == 0x7f or
                std.mem.indexOfScalar(u8, "[]:#|{}>&/\\", label[pos]) != null) return false;
            pos += 1;
        }
        return observed_bold and !in_bold;
    }

    // A finite literal caption may contain prose colons and numbered bracket
    // labels without introducing a node or class. Keep this separate from the
    // local/remote link inventories; the ordinary parser still emits its bytes.
    fn figureCaptionLiteralPunctuation(tracked: MissingText, caption: []const u8) bool {
        const begin = @intFromPtr(tracked.bytes.ptr);
        const at = @intFromPtr(caption.ptr);
        if (at < begin or at - begin > tracked.bytes.len or caption.len > tracked.bytes.len - (at - begin)) return false;
        if (caption.len == 0 or caption.len > 4096 or tracked.lost_missing_range or
            tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or
            tracked.generated_links.len != 0 or tracked.generated_source != null) return false;
        if (!std.unicode.utf8ValidateSlice(caption) or !figureCaptionInlineNodes(caption) or
            magicLinkStart(caption, 0) != null) return false;
        var punctuation = false;
        var pos: usize = 0;
        while (pos < caption.len) {
            const byte = caption[pos];
            if (byte < 0x20 or byte == 0x7f or std.mem.indexOfScalar(u8, "<>{}&|_'/\\*#;=", byte) != null) return false;
            if (byte == '[') {
                var end = pos + 1;
                while (end < caption.len and std.ascii.isDigit(caption[end])) : (end += 1) {}
                if (end == pos + 1 or end + 1 >= caption.len or caption[end] != '.' or caption[end + 1] != ']') return false;
                const normal_end = literalSquareGlossEnd(caption, pos) orelse return false;
                if (normal_end != end + 2) return false;
                punctuation = true;
                pos = normal_end;
                continue;
            }
            if (byte == ']') return false;
            if (byte == ':') {
                const numeric = pos != 0 and pos + 1 < caption.len and
                    std.ascii.isDigit(caption[pos - 1]) and std.ascii.isDigit(caption[pos + 1]);
                if (!numeric and pos + 1 != caption.len and caption[pos + 1] != ' ') return false;
                punctuation = true;
            }
            pos += 1;
        }
        if (!punctuation) return false;
        var it: ir.InlineIterator = .{ .input = caption, .renderer_boundaries = true };
        while (it.next()) |token| {
            if (token.kind != .text or token.target.len != 0 or token.literal_tail or
                token.rejected_external_opener or token.bold or token.italic) return false;
        }
        return true;
    }

    // Compose a literal prose prefix with an independently complete local-node
    // inventory. Neither half changes caption emission or grants remote classes.
    fn figureCaptionLiteralPrefix(tracked: MissingText, caption: []const u8) bool {
        if (caption.len == 0 or caption.len > 4096 or !figureCaptionInlineNodes(caption)) return false;
        var boundary = caption.len;
        if (std.mem.indexOfScalar(u8, caption, '<')) |at| boundary = @min(boundary, at);
        if (std.mem.indexOf(u8, caption, "[[")) |at| boundary = @min(boundary, at);
        if (boundary == 0 or boundary == caption.len) return false;
        return figureCaptionLiteralPunctuation(tracked, caption[0..boundary]) and
            figureCaptionClassless(tracked, caption[boundary..]);
    }

    // A no-rule converter body selects raw text (ConverterRule::parse R
    // fallback). These complete alphanumeric bodies cannot manufacture HTML,
    // classes, actions, or variant choices. Keep each surrounding source chunk
    // in the existing classless domain and leave caption parsing untouched.
    fn figureCaptionRuleFreeLetters(self: *const Renderer, tracked: MissingText, caption: []const u8) bool {
        if (caption.len == 0 or caption.len > 4096 or tracked.lost_missing_range or
            tracked.generated_source != null or !figureCaptionInlineNodes(caption) or
            !std.unicode.utf8ValidateSlice(caption)) return false;
        const ns = self.context.namespace_catalog orelse return false;
        const variants = ns.language_conversion orelse return false;
        const profile = ns.manual_conversion_context orelse return false;
        if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or
            !std.mem.eql(u8, profile.base, ns.content_language) or !manualVariantKnown(profile.base, variants) or
            !std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2") or
            profile.source_converter_sha256.len != 64 or profile.siteinfo_sha256.len != 64) return false;
        // The new domain is plain prose/quote formatting only. Existing links,
        // attributed/bare HTML, entities and protocol/list syntax gain nothing.
        if (std.mem.indexOfAny(u8, caption, "[]&|:\\\r\n") != null or
            std.mem.indexOf(u8, caption, "__") != null or magicLinkStart(caption, 0) != null) return false;
        for (caption) |byte| if (byte < 0x20 or byte == 0x7f) return false;
        var at: usize = 0;
        var count: usize = 0;
        while (std.mem.indexOfPos(u8, caption, at, "-{")) |opening| {
            // Ordinary File-label quote normalization runs before this proof.
            // Admit only its complete bare italic wrapper around this one
            // alphanumeric conversion; no attributed or enclosing HTML scope.
            const italic = opening >= at + 3 and std.mem.eql(u8, caption[opening - 3 .. opening], "<i>");
            const chunk = caption[at .. if (italic) opening - 3 else opening];
            if (std.mem.indexOfAny(u8, chunk, "<>/") != null or !figureCaptionClassless(tracked, chunk)) return false;
            const close = std.mem.indexOfPos(u8, caption, opening + 2, "}-") orelse return false;
            const body = caption[opening + 2 .. close];
            if (body.len == 0 or body.len > 128) return false;
            for (body) |byte| if (!std.ascii.isAlphanumeric(byte)) return false;
            at = close + 2;
            if (italic) {
                if (!starts(caption[at..], "</i>")) return false;
                at += 4;
            }
            count += 1;
        }
        return count != 0 and std.mem.indexOfAny(u8, caption[at..], "<>/") == null and
            figureCaptionClassless(tracked, caption[at..]);
    }

    fn figureCaptionClassless(tracked: MissingText, caption: []const u8) bool {
        return figureCaptionFiniteNodes(null, tracked, caption);
    }

    // The selected outer interwiki row owns the generated anchor class. A
    // chained title remains that row's URL argument; it is not a local language
    // or namespace transition. Keep explicit-colon handling and namespace
    // precedence aligned with the ordinary link path.
    fn figureCaptionRemoteTarget(self: *const Renderer, original: []const u8) bool {
        const registry = self.context.namespace_catalog orelse return false;
        const target = if (starts(original, ":")) original[1..] else original;
        if (registry.interwiki_magic == null or !safeInternalTarget(target) or
            self.namespaceOfTarget(target) != null) return false;
        const colon = std.mem.indexOfScalar(u8, target, ':') orelse return false;
        if (colon == 0 or colon + 1 == target.len or trim(target[colon + 1 ..]).len == 0) return false;
        const prefix = target[0..colon];
        for (prefix) |byte| if (!std.ascii.isAlphanumeric(byte) and byte != '-') return false;
        const body = target[colon + 1 ..];
        if (std.mem.indexOfAny(u8, body, "#[]|{}<>&/\\\r\n") != null or
            body[0] == ':' or body[body.len - 1] == ':' or std.mem.indexOf(u8, body, "::") != null) return false;
        for (target) |byte| if (byte < 0x20 or byte == 0x7f) return false;
        for (registry.interwiki_rows) |row| if (std.ascii.eqlIgnoreCase(row.prefix, prefix))
            return !row.is_current_wiki and !row.is_interlanguage;
        return false;
    }

    // Consume the ordinary parser's complete labelled HTTP(S) token. This is
    // only a finite node/class inventory, never an action or URL rewrite. In
    // particular, an unclosed bracket cannot become a labelled action here.
    fn figureCaptionHttpLinkEnd(self: *const Renderer, source: []const u8) ?usize {
        if (!starts(source, "[http://") and !starts(source, "[https://")) return null;
        var iterator: ir.InlineIterator = .{ .input = source, .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const token = iterator.next() orelse return null;
        if (token.kind != .external_link or iterator.cursor < 3 or iterator.cursor > source.len or
            source[iterator.cursor - 1] != ']' or token.external_label_prefix.len != 0 or
            token.text.ptr == token.target.ptr or trim(token.text).len == 0 or
            !safeUrl(token.target) or unresolvedExternalActionTarget(token.target)) return null;
        if (std.mem.indexOfAny(u8, token.target, "[]{}<>|&'\"\\\r\n\x00") != null) return null;
        for (token.target) |byte| if (byte <= 0x20 or byte == 0x7f) return null;
        if (std.mem.indexOfAny(u8, token.text, "[]:#|{}<>&/\\'\r\n\x00") != null and
            !figureCaptionBoldLocalLabel(token.text) and !figureCaptionItalicLocalLabel(token.text)) return null;
        return iterator.cursor;
    }

    fn figureCaptionNoLists(self: *const Renderer, tracked: MissingText, caption: []const u8) bool {
        var inventory: FigureCaptionAuthoredInventory = .{};
        return !tracked.lost_missing_range and figureCaptionInlineNodes(caption) and
            figureCaptionFiniteNodesWithInventory(self, tracked, caption, &inventory);
    }

    // Authored span attributes and separately selected remote-link classes
    // enter this inventory. The ordinary parser still owns paint and actions;
    // a class inventory alone never certifies absence of a language override.
    const FigureCaptionAuthoredInventory = struct {
        classes: [1024]u8 = undefined,
        classes_len: usize = 0,
        attributed_spans: usize = 0,
        has_language: bool = false,
        remote_links: usize = 0,
        http_links: usize = 0,

        fn remote(self: *FigureCaptionAuthoredInventory) bool {
            if (self.remote_links == 0) {
                const value = "extiw";
                const separator: usize = @intFromBool(self.classes_len != 0);
                if (value.len + separator > self.classes.len - self.classes_len) return false;
                if (separator != 0) { self.classes[self.classes_len] = ' '; self.classes_len += 1; }
                @memcpy(self.classes[self.classes_len..][0..value.len], value);
                self.classes_len += value.len;
            }
            self.remote_links += 1;
            return true;
        }

        fn http(self: *FigureCaptionAuthoredInventory) bool {
            if (self.http_links == 0) {
                // Both generated classes remain possible CSS subjects. They
                // cannot lend classless or outer-ancestor authority.
                const value = "external text";
                const separator: usize = @intFromBool(self.classes_len != 0);
                if (value.len + separator > self.classes.len - self.classes_len) return false;
                if (separator != 0) { self.classes[self.classes_len] = ' '; self.classes_len += 1; }
                @memcpy(self.classes[self.classes_len..][0..value.len], value);
                self.classes_len += value.len;
            }
            self.http_links += 1;
            return true;
        }

        fn span(self: *FigureCaptionAuthoredInventory, tag: syntax.Tag) bool {
            return tag.is("span") and self.inlineElement(tag);
        }

        // The same complete class/lang-only grammar also applies to literal I.
        // Keep the span-only entry point strict for independent observed routes.
        fn inlineElement(self: *FigureCaptionAuthoredInventory, tag: syntax.Tag) bool {
            if ((!tag.is("span") and !tag.is("i")) or tag.closing or tag.self_closing) return false;
            var class_value: ?[]const u8 = null;
            var language_value: ?[]const u8 = null;
            var at: usize = 0;
            while (at < tag.attrs.len) {
                while (at < tag.attrs.len and tag.attrs[at] == ' ') : (at += 1) {}
                if (at == tag.attrs.len) break;
                const start = at;
                while (at < tag.attrs.len and std.ascii.isAlphabetic(tag.attrs[at])) : (at += 1) {}
                const name = tag.attrs[start..at];
                while (at < tag.attrs.len and tag.attrs[at] == ' ') : (at += 1) {}
                if (at == tag.attrs.len or tag.attrs[at] != '=') return false;
                at += 1;
                while (at < tag.attrs.len and tag.attrs[at] == ' ') : (at += 1) {}
                if (at == tag.attrs.len or (tag.attrs[at] != '"' and tag.attrs[at] != 39)) return false;
                const quote = tag.attrs[at]; at += 1;
                const value_at = at;
                while (at < tag.attrs.len and tag.attrs[at] != quote) : (at += 1) {}
                if (at == tag.attrs.len) return false;
                const value = tag.attrs[value_at..at]; at += 1;
                if (at < tag.attrs.len and tag.attrs[at] != ' ') return false;
                if (std.ascii.eqlIgnoreCase(name, "class")) {
                    if (class_value != null or trim(value).len == 0 or value.len > 128) return false;
                    for (value) |byte| if (!std.ascii.isAlphanumeric(byte) and byte != '-' and byte != '_' and byte != ' ') return false;
                    class_value = value;
                } else if (std.ascii.eqlIgnoreCase(name, "lang")) {
                    if (language_value != null or value.len > 64) return false;
                    for (value) |byte| if (!std.ascii.isAlphanumeric(byte) and byte != '-') return false;
                    language_value = value;
                } else return false;
            }
            const classes = class_value orelse return false;
            if (htmlOwnAttributePresence(&tag, "class") != .present or
                !std.mem.eql(u8, tag.attr("class") orelse return false, classes)) return false;
            if (language_value) |language| {
                if (htmlOwnAttributePresence(&tag, "lang") != .present or
                    !std.mem.eql(u8, tag.attr("lang") orelse return false, language)) return false;
                self.has_language = true; // Empty lang is a barrier too.
            } else if (htmlOwnAttributePresence(&tag, "lang") != .absent) return false;
            const separator: usize = @intFromBool(self.classes_len != 0);
            if (classes.len + separator > self.classes.len - self.classes_len) return false;
            if (separator != 0) { self.classes[self.classes_len] = ' '; self.classes_len += 1; }
            @memcpy(self.classes[self.classes_len..][0..classes.len], classes);
            self.classes_len += classes.len;
            self.attributed_spans += 1;
            return true;
        }
    };

    fn figureCaptionAuthoredSpan(tracked: MissingText, caption: []const u8) ?FigureCaptionAuthoredInventory {
        if (caption.len == 0 or caption.len > 4096 or tracked.lost_missing_range or
            tracked.generated_source != null or !figureCaptionInlineNodes(caption)) return null;
        for (caption) |byte| if (byte < 0x20 or byte == 0x7f) return null;
        var inventory: FigureCaptionAuthoredInventory = .{};
        if (!figureCaptionFiniteNodesWithInventory(null, tracked, caption, &inventory) or
            inventory.attributed_spans == 0) return null;
        return inventory;
    }

    // Compose the existing ordinary remote and local-fragment grammars. This
    // inventory supplies only finite caption nodes/classes, never outer scope.
    // Attributed spans stay in their independently qualified existing route.
    fn figureCaptionRemoteInventory(self: *const Renderer, tracked: MissingText, caption: []const u8) ?FigureCaptionAuthoredInventory {
        if (caption.len == 0 or caption.len > 4096 or tracked.lost_missing_range or
            tracked.generated_source != null or !figureCaptionInlineNodes(caption)) return null;
        for (caption) |byte| if (byte < 0x20 or byte == 0x7f) return null;
        var inventory: FigureCaptionAuthoredInventory = .{};
        if (!figureCaptionFiniteNodesWithInventory(self, tracked, caption, &inventory) or
            inventory.attributed_spans != 0 or (inventory.remote_links == 0 and inventory.http_links == 0)) return null;
        return inventory;
    }

    fn figureCaptionLocalFragment(target: []const u8) bool {
        const hash = std.mem.indexOfScalar(u8, target, '#') orelse return false;
        if (hash == 0 or hash + 1 == target.len or trim(target[0..hash]).len == 0 or
            trim(target[hash + 1 ..]).len == 0 or !safeInternalTarget(target)) return false;
        if (std.mem.indexOfAny(u8, target, ":[]|{}<>&/\\\r\n\x00") != null or
            std.mem.indexOfScalarPos(u8, target, hash + 1, '#') != null) return false;
        for (target) |byte| if (byte < 0x20 or byte == 0x7f) return false;
        return true;
    }

    fn figureCaptionItalicLocalLabel(label: []const u8) bool {
        const body = if (label.len > 4 and starts(label, "''") and std.mem.endsWith(u8, label, "''"))
            label[2 .. label.len - 2]
        else if (label.len > 7 and starts(label, "<i>") and std.mem.endsWith(u8, label, "</i>"))
            label[3 .. label.len - 4]
        else return false;
        if (trim(body).len == 0 or std.mem.indexOfAny(u8, body, "[]:#|{}<>&/\\'\r\n\x00") != null) return false;
        for (body) |byte| if (byte < 0x20 or byte == 0x7f) return false;
        return true;
    }

    fn figureCaptionFiniteNodes(list_context: ?*const Renderer, tracked: MissingText, caption: []const u8) bool {
        return figureCaptionFiniteNodesWithInventory(list_context, tracked, caption, null);
    }

    fn figureCaptionFiniteNodesWithInventory(list_context: ?*const Renderer, tracked: MissingText, caption: []const u8, inventory: ?*FigureCaptionAuthoredInventory) bool {
        return figureCaptionFiniteNodesWithInventoryIn(list_context, tracked, caption, inventory, false);
    }

    fn figureCaptionFiniteNodesWithInventoryIn(list_context: ?*const Renderer, tracked: MissingText, caption: []const u8, inventory: ?*FigureCaptionAuthoredInventory, allow_categories: bool) bool {
        return figureCaptionFiniteNodesTracked(list_context, tracked, caption, inventory, allow_categories, false);
    }

    fn figureCaptionFiniteNodesTracked(list_context: ?*const Renderer, tracked: MissingText, caption: []const u8, inventory: ?*FigureCaptionAuthoredInventory, allow_categories: bool, recorded_templates: bool) bool {
        const begin = @intFromPtr(tracked.bytes.ptr);
        const at = @intFromPtr(caption.ptr);
        if (at < begin or at - begin > tracked.bytes.len or caption.len > tracked.bytes.len - (at - begin)) return false;
        if ((!recorded_templates and tracked.ranges.len != 0) or tracked.literal_curly_ranges.len != 0 or tracked.generated_links.len != 0) return false;
        if (!std.unicode.utf8ValidateSlice(caption) or std.mem.indexOf(u8, caption, "__") != null) return false;
        // This consumes the exact borrowed caption, not a normalized copy.
        // Unknown missing-phase state is retained: it does not manufacture new
        // nodes in these bytes. Local protected/generated occurrences refuse.
        // Quotes and balanced bare formatting tags create only classless nodes;
        // simple local links may additionally create the known selflink classes.
        var tags: [16]u8 = undefined;
        var depth: usize = 0;
        var occurrence_index: usize = 0;
        var pos: usize = 0;
        while (pos < caption.len) {
            if (recorded_templates and occurrence_index < tracked.ranges.len) {
                const range = tracked.ranges[occurrence_index];
                const offset = at - begin + pos;
                if (range.start < offset) return false;
                if (range.start == offset) {
                    if (range.end <= range.start or range.end - offset > caption.len - pos) return false;
                    var single = tracked;
                    single.ranges = tracked.ranges[occurrence_index..][0..1];
                    const renderer = list_context orelse return false;
                    if (!renderer.figureCaptionMissingTemplateLink(single, tracked.bytes[range.start..range.end])) return false;
                    var tokens: ir.InlineIterator = .{ .input = caption[pos..], .renderer_boundaries = true, .link_trail = renderer.context.link_trail };
                    const token = tokens.next() orelse return false;
                    if (token.kind != .link or tokens.cursor != range.end - range.start or token.trail.len != 0) return false;
                    pos += range.end - range.start;
                    occurrence_index += 1;
                    continue;
                }
            }
            const byte = caption[pos];
            if (byte == '<') {
                // A complete bare NOWIKI around ordinary text creates no
                // element/class/action. Keep its normal protected-text parse;
                // only the independent class/list inventory consumes this proof.
                if (starts(caption[pos..], "<nowiki>")) {
                    const nowiki_body_at = pos + "<nowiki>".len;
                    const nowiki_close_at = std.mem.indexOfPos(u8, caption, nowiki_body_at, "</nowiki>") orelse return false;
                    const caption_nowiki_body = caption[nowiki_body_at..nowiki_close_at];
                    if (trim(caption_nowiki_body).len == 0 or std.mem.indexOfAny(u8, caption_nowiki_body, "[]:#|{}<>&/\\'_") != null) return false;
                    for (caption_nowiki_body) |ch| if (ch < 0x20 or ch == 0x7f) return false;
                    pos = nowiki_close_at + "</nowiki>".len;
                    continue;
                }
                const close = pos + 1 < caption.len and caption[pos + 1] == '/';
                const name_at = pos + 1 + @intFromBool(close);
                var name_end = name_at;
                while (name_end < caption.len and std.ascii.isAlphabetic(caption[name_end])) : (name_end += 1) {}
                const name = caption[name_at..name_end];
                const kind: u8 = if (std.mem.eql(u8, name, "b")) 'b' else if (std.mem.eql(u8, name, "i")) 'i' else if (std.mem.eql(u8, name, "span")) 's' else if (std.mem.eql(u8, name, "small")) 'm' else if (std.mem.eql(u8, name, "sup")) 'u' else if (std.mem.eql(u8, name, "br")) 'r' else return false;
                var end = name_end;
                while (end < caption.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", caption[end]) != null) : (end += 1) {}
                // Bare BR is void. Only its optional closing slash is accepted;
                // ordinary caption parsing still emits the actual line break.
                if (kind == 'r' and !close and end < caption.len and caption[end] == '/') end += 1;
                if (end == caption.len) return false;
                if (caption[end] != '>') {
                    const authored = inventory orelse return false;
                    if (close or (kind != 's' and kind != 'i')) return false;
                    const tag = syntax.tagAt(caption, pos) orelse return false;
                    if (!authored.inlineElement(tag)) return false;
