        original: []const u8,
    };
    // Class inventory is scoped to the live fragment. Page-root anchors use
    // the selected original page, so translate only through the two current
    // bindings that Document installed for that exact fragment/projection.
    fn quoteClassPageOriginal(self: *const Renderer, scope: *const table_style_profile.BoundedTextClassScope, part: []const u8) ?[]const u8 {
        const original = self.registeredCaptionOriginal(part) orelse return null;
        const binding = self.figure_class_source_binding orelse return null;
        const observed = binding.projection.observedOriginal() orelse return null;
        if (binding.scope != scope or observed.scope != scope) return null;
        if (wikiClassContains(observed.source, original)) return original;
        const selected: FigureClassSourceDomain = .{ .scope = scope, .selected = observed.source };
        const paired = self.figureStyleOriginalBinding(selected) orelse return null;
        const current = self.source_element_binding orelse return null;
        const bounded = self.bounded_text_class_source orelse return null;
        if (self.bounded_text_class_scope != scope or bounded.ptr != paired.owner.bytes.ptr or
            bounded.len != paired.owner.bytes.len) return null;
        const start = paired.originalRange(original) orelse return null;
        if (current.originalRange(original) != start or start > observed.source.len or original.len > observed.source.len - start) return null;
        const restored = paired.ownerRange(start, original.len) orelse return null;
        if (restored.ptr != original.ptr or restored.len != original.len) return null;
        return observed.source[start..][0..original.len];
    }
    fn pageStyleQuoteAnchor(self: *const Renderer, known: QuoteClassTag) ?[]const u8 {
        if (self.pageStyleOriginalAnchor(known.original)) |anchor| return anchor;
        const original = self.quoteClassPageOriginal(known.scope, known.original) orelse return null;
        return self.pageStyleOriginalAnchor(original);
    }

    fn quoteClassOutputOwned(self: *const Renderer, map: *const QuoteSourceMap, quoted: MissingText,
        scope: *const table_style_profile.BoundedTextClassScope) bool
    {
        if (map.output.ptr != quoted.bytes.ptr or map.output.len != quoted.bytes.len) return false;
        if (wikiClassCleanText(quoted)) return true;
        // An unknown page can still contain an exact ordinary interval. Keep
        // unknown on the output and require the already observed projection,
        // complete registered input copy and locally clean normalized output.
        if (!QuoteSourceMap.cleanLocal(quoted) or map.original.len == 0) return false;
        const binding = self.figure_class_source_binding orelse return false;
        const observed = binding.projection.observedOriginal() orelse return false;
        if (binding.scope != scope or observed.scope != scope) return false;
        const original = self.quoteClassPageOriginal(scope, map.original) orelse return false;
        const start = std.math.sub(usize, @intFromPtr(original.ptr), @intFromPtr(observed.source.ptr)) catch return false;
        if (start > observed.source.len or original.len > observed.source.len - start or
            original.len != map.original.len or !std.mem.eql(u8, original, map.original)) return false;
        return binding.ownerRange(start, original.len) != null;
    }

    fn quoteClassOriginal(self: *const Renderer, domain: *const QuoteClassSource, part: []const u8) ?[]const u8 {
        const selected = self.figureClassSourceDomain() orelse return null;
        if (selected.scope != domain.scope or selected.selected.ptr != domain.selected.ptr or
            selected.selected.len != domain.selected.len or part.len == 0 or
            !wikiClassContains(domain.map.original, part)) return null;
        if (self.registeredCaptionOriginal(part)) |original|
            if (self.figureClassScopeForOriginal(original) == domain.scope) return original;
        const issued = domain.selected_original orelse return null;
        if (issued.copied.ptr != domain.map.original.ptr or issued.copied.len != domain.map.original.len) return null;
        const original = issued.selected;
        if (original.len != domain.map.original.len or !wikiClassContains(selected.selected, original) or
            !std.mem.eql(u8, original, domain.map.original)) return null;
        if (self.figure_class_source_binding) |binding| {
            const start = @intFromPtr(original.ptr) - @intFromPtr(selected.selected.ptr);
            if (binding.scope != domain.scope or binding.ownerRange(start, original.len) == null) return null;
        }
        const at = @intFromPtr(part.ptr) - @intFromPtr(domain.map.original.ptr);
        return original[at..][0..part.len];
    }
    fn quoteClassTag(self: *const Renderer, tag: syntax.Tag) ?QuoteClassTag {
        // An unknown selected-page map is useful to the completed Figure
        // factory, but does not publish generic body ancestry. Its class proof
        // is consumed only for a whole opening in the live captured caption.
        const captured: ?*const QuoteClassSource = captured: {
            const root = self.caption_class_parent orelse break :captured null;
            const source = self.caption_class_source orelse break :captured null;
            const current = self.inline_missing orelse break :captured null;
            const opening = localTrackedTagOpening(current, tag) orelse break :captured null;
            if (root.complete_ancestor_classes == null or !self.currentAncestorScope(root) or
                !wikiClassContains(source, opening) or !noLiParentSourceRange(current, opening)) break :captured null;
            break :captured self.figure_caption_quote_source;
        };
        var pending_captured = if (self.quote_class_source != null) captured else null;
        var next = self.quote_class_source orelse captured;
        var remaining: usize = max_depth + 1;
        while (next) |domain| {
            if (remaining == 0) return null;
            remaining -= 1;
            next = domain.parent;
            if (next == null) {
                next = pending_captured;
                pending_captured = null;
            }
            const selected = self.figureClassSourceDomain() orelse return null;
            const original_domain = self.quoteClassOriginal(domain, domain.map.original) orelse continue;
            if (selected.selected.ptr != domain.selected.ptr or selected.selected.len != domain.selected.len or
                selected.scope != domain.scope or self.figureClassScopeForOriginal(original_domain) != domain.scope) continue;
            if (domain.map.copiedOriginal(tag.name)) |original_name| {
                const original_at = @intFromPtr(original_name.ptr) - @intFromPtr(domain.map.original.ptr);
                const prefix: usize = if (tag.closing) 2 else 1;
                if (original_at < prefix) continue;
                const original_start = original_at - prefix;
                const original = syntax.tagAt(domain.map.original, original_start) orelse continue;
                if (original.name.ptr != original_name.ptr or original.name.len != tag.name.len or
                    original.closing != tag.closing or original.self_closing != tag.self_closing or original.html_pre != tag.html_pre or
                    !std.mem.eql(u8, original.attrs, tag.attrs)) continue;
                const output_at = @intFromPtr(tag.name.ptr) - @intFromPtr(domain.map.output.ptr);
                if (output_at < prefix) continue;
                const output_start = output_at - prefix;
                const token_len = original.end - original_start;
                if (output_start > domain.map.output.len or token_len > domain.map.output.len - output_start) continue;
                const copied = domain.map.copiedOriginal(domain.map.output[output_start .. output_start + token_len]) orelse continue;
                if (copied.ptr != domain.map.original[original_start..].ptr or copied.len != token_len) continue;
                const output = syntax.tagAt(domain.map.output, output_start) orelse continue;
                if (output.name.ptr != tag.name.ptr or output.name.len != tag.name.len or output.attrs.ptr != tag.attrs.ptr or
                    output.attrs.len != tag.attrs.len or output.closing != tag.closing or output.self_closing != tag.self_closing or
                    output.html_pre != tag.html_pre or output.end != output_start + token_len) continue;
                const selected_opening = self.quoteClassOriginal(domain, domain.map.original[original_start..original.end]) orelse continue;
                if (self.figureClassScopeForOriginal(selected_opening) != domain.scope) continue;
                return .{ .scope = domain.scope, .source_key = @intFromPtr(original.name.ptr), .generated = false, .original = selected_opening };
            }
            if (domain.map.generatedForName(tag.name)) |generated| {
                if (tag.attrs.len != 0 or tag.self_closing or tag.html_pre or generated.quote_end <= generated.quote_start or
                    generated.quote_end > domain.map.original.len) continue;
                const token = generated.token.bytes();
                const closing = generated.token == .b_close or generated.token == .i_close;
                const expected_name: []const u8 = switch (generated.token) { .b_open, .b_close => "b", .i_open, .i_close => "i" };
                if (tag.closing != closing or !std.mem.eql(u8, tag.name, expected_name)) continue;
                const observed = syntax.tagAt(domain.map.output, generated.output_start) orelse continue;
                if (observed.name.ptr != tag.name.ptr or observed.attrs.ptr != tag.attrs.ptr or observed.attrs.len != 0 or
                    observed.end != generated.output_start + token.len) continue;
                const selected_quotes = self.quoteClassOriginal(domain, domain.map.original[generated.quote_start..generated.quote_end]) orelse continue;
                if (self.figureClassScopeForOriginal(selected_quotes) != domain.scope) continue;
                // This is the normalizer's explicit classless b/i token, not an
                // authored tag occurrence or a sibling-position certificate.
                return .{ .scope = domain.scope, .source_key = @intFromPtr(tag.name.ptr), .generated = true, .original = selected_quotes };
            }
        }
        return null;
    }
    fn boundedTextClassScopeFor(self: *const Renderer, tag: syntax.Tag) ?*const table_style_profile.BoundedTextClassScope {
        if (self.classScopeForSource(tag.name)) |scope| {
            if (tag.attrs.len != 0 and self.classScopeForSource(tag.attrs) != scope) return null;
            return scope;
        }
        return if (self.quoteClassTag(tag)) |known| known.scope else null;
    }
    const PageStyleDomain = struct {
        scope: *const table_style_profile.BoundedTextClassScope,
        source: []const u8,
        owner: []const u8,
    };
    fn pageStyleDomain(self: *const Renderer) ?PageStyleDomain {
        if (self.content_root != .parser_output or self.in_reference or self.in_template_literal_scope) return null;
        const sizing = self.context.figure_sizing orelse return null;
        const observed = sizing.text_class_scope orelse return null;
        if (self.context.table_styles == null or observed.scope.page_styles != self.context.table_styles or
            observed.scope.page_style_root == null) return null;
        if (self.source_element_binding) |binding| {
            if (binding.scope != observed.scope or binding.projection.original.bytes.ptr != observed.source.ptr or
                binding.projection.original.bytes.len != observed.source.len) return null;
            return .{ .scope = observed.scope, .source = observed.source, .owner = binding.owner.bytes };
        }
        const selected = self.bounded_text_class_source orelse return null;
        if (self.bounded_text_class_scope != observed.scope or selected.ptr != observed.source.ptr or selected.len != observed.source.len) return null;
        return .{ .scope = observed.scope, .source = observed.source, .owner = selected };
    }
    fn observedCaptionPagePreflightCovered(self: *const Renderer, source: MissingText, parent: Style) bool {
        if (self.figure_caption_depth == 0 or source.bytes.len == 0 or !QuoteSourceMap.cleanLocal(source)) return false;
        const session = self.observed_figure_caption orelse return false;
        const proof = session.preflight orelse return false;
        if (proof.profile != self.context.table_styles or !std.meta.eql(proof.style, parent)) return false;
        const selected = self.observedFigureCanonicalOperation(session.operation) orelse return false;
        if (selected.scope != proof.scope or selected.scope.page_styles != proof.profile or
            selected.scope.page_style_root != proof.root) return false;
        if (!self.observedFigureCaptionLocalRange(session.operation, source, 0, source.bytes.len)) return false;
        const original = self.figureStyleOriginalSlice(selected, source.bytes) orelse return false;
        // Only the whole caption enters this proof. Substrings, unrelated text,
        // and quote-generated output still require their existing local issuers.
        return original.ptr == session.operation.caption.ptr and original.len == session.operation.caption.len;
    }

    // This cache is local to one rendering operation. Metadata is immutable;
    // the saved inventories additionally reject a rebound profile/rule slice.
    const TablePreflightInventory = struct {
        profile: *const table_style_profile.Profile,
        saved: table_style_profile.Profile,
        custom: ?table_style_profile.CustomProfile,
        fn current(self: @This()) bool {
            inline for (@typeInfo(table_style_profile.Profile).@"struct".field_names) |name| {
                if (comptime std.mem.eql(u8, name, "arena")) continue;
                if (!sameFigurePreparationValue(@field(self.saved, name), @field(self.profile.*, name))) return false;
            }
            if (self.custom) |old| {
                const now = self.profile.custom_properties orelse return false;
                if (!sameFigurePreparationValue(old, now.*)) return false;
            }
            return true;
        }
    };
    const TablePagePreflight = struct {
        selected: TableContainingDirectionSource,
        scope: *const table_style_profile.BoundedTextClassScope,
        saved_scope: table_style_profile.BoundedTextClassScope,
        inventories: []const TablePreflightInventory,
        contexts: []const table_style_profile.TableContainingDirectionContext,
        parsed: []const u8,
        source_bytes: []const u8,
        opening_start: usize,
        opening_end: usize,
        parent: Style,
        native: CellNativeContext,
        physical_parent: ?*const table_style_profile.TextElement,
        candidate: TableViewportCandidate,
    };
    fn tablePreflightInventories(self: *Renderer, profiles: []const *const table_style_profile.Profile) Error!?[]const TablePreflightInventory {
        var result: std.ArrayList(TablePreflightInventory) = .empty;
        for (profiles) |first| {
            var next: ?*const table_style_profile.Profile = first;
            var depth: usize = 0;
            while (next) |profile| : (depth += 1) {
                if (depth == 16) return null;
                var seen = false;
                for (result.items) |old| if (old.profile == profile) { seen = true; break; };
                if (seen) break;
                try result.append(self.a, .{ .profile = profile, .saved = profile.*,
                    .custom = if (profile.custom_properties) |value| value.* else null });
                next = profile.page_style_parent;
            }
        }
        return try result.toOwnedSlice(self.a);
    }
    fn tablePagePreflightCurrent(self: *const Renderer, held: *const TablePagePreflight) bool {
        const selected = self.tableDirectionSource() orelse return false;
        if (!selected.prefix_viewport or selected.intrinsic_viewport or !selected.root_only or
            selected.source.ptr != held.selected.source.ptr or selected.source.len != held.selected.source.len or
            !sameFigurePreparationValue(selected, held.selected)) return false;
        const issue = selected.preflight_scope orelse return false;
        const observed = issue(selected.context, selected.source) orelse return false;
        const active = (self.context.figure_sizing orelse return false).text_class_scope orelse return false;
        if (observed.scope != held.scope or active.scope != held.scope or
            observed.source.ptr != selected.source.ptr or observed.source.len != selected.source.len or
            active.source.ptr != selected.source.ptr or active.source.len != selected.source.len or
            !sameFigurePreparationValue(held.saved_scope, held.scope.*) or
            !std.mem.eql(u8, selected.source, held.source_bytes)) return false;
        for (held.inventories) |inventory| if (!inventory.current()) return false;
        if (held.contexts.len != held.candidate.preflight_contexts.len) return false;
        for (held.contexts, held.candidate.preflight_contexts) |old, current|
            if (!sameFigurePreparationValue(old, current)) return false;
        return true;
    }
    fn tablePreflightOriginal(self: *const Renderer, source: MissingText) ?[]const u8 {
        if (!QuoteSourceMap.cleanLocal(source)) return null;
        // This maintained mapper already binds unchanged copies and quote
        // segments to the current Cell; no distant page-root scope is lent.
        return self.tableLinkOriginalIn(source.bytes, self.table_link_quote_source, 0);
    }
    fn tablePagePreflightDecline(self: *Renderer, stage: []const u8) bool {
        if (self.context.table_viewport_trace) self.table_page_preflight_decline = stage;
        return false;
    }
    fn tracePagePreflightRefusal(self: *Renderer, stage: []const u8, source: MissingText) bool {
        if (self.context.table_viewport_trace) {
            if (!self.fallbacks.unresolved_table_style and !self.rejection_probe_scope and self.table_style_trace_branch == null) {
                diagnostics.logLine("presentation page_preflight_refusal stage={s} coverage_decline={s} source_bytes={d} lost_missing_range={any} generated_source={any}", .{
                    stage, self.table_page_preflight_decline orelse "not_attempted", source.bytes.len,
                    source.lost_missing_range, source.generated_source != null,
                });
                self.tracePageAncestorEffectBlocker(stage);
            }
            return self.traceUnresolvedTableStyle(true, stage, source.bytes);
        }
        return true;
    }
    // Print only the blocker already retained by the failed preflight. This
    // neither repeats a CSS query nor lends its distant root to a new subject.
    fn tracePageAncestorEffectBlocker(self: *const Renderer, stage: []const u8) void {
        if (!self.context.table_viewport_trace) return;
        const profile_ptr: ?usize = if (self.context.table_styles) |profile| @intFromPtr(profile) else null;
        const checked_profile_ptr: ?usize = if (self.checked_page_style_profile) |profile| @intFromPtr(profile) else null;
        const checked_root_ptr: ?usize = if (self.checked_page_style_root) |root| @intFromPtr(root) else null;
        const value = self.page_ancestor_effect orelse {
            diagnostics.logLine("presentation page_ancestor_blocker stage={s} renderer=0x{x} held=false profile={any} checked_profile={any} checked_root={any}", .{
                stage, @intFromPtr(self), profile_ptr, checked_profile_ptr, checked_root_ptr,
            });
            return;
        };
        const rule = value.rule;
        const provenance = if (rule) |known| known.provenance else null;
        const selector = if (provenance) |known| known.selector else "";
        const source_index: ?usize = if (provenance) |known| known.source_index else null;
        const css_byte_start: ?usize = if (provenance) |known| known.css_byte_start else null;
        const conditions_count: ?usize = if (provenance) |known| known.conditions.len else null;
        const css_bytes: ?usize = if (rule) |known| known.css.len else null;
        const order: ?u32 = if (rule) |known| known.order else null;
        const specificity: ?u64 = if (rule) |known| known.specificity else null;
        const rank_unknown: ?bool = if (rule) |known| known.rank_unknown else null;
        const viewport_limit: ?u32 = if (rule) |known| switch (known.viewport) {
            .screen_max_width_px => |limit| limit, else => null,
        } else null;
        var selector_buffer: [512]u8 = undefined;
        var declaration_buffer: [512]u8 = undefined;
        diagnostics.logLine("presentation page_ancestor_blocker stage={s} renderer=0x{x} held=true profile={any} checked_profile={any} checked_root={any} reason={s} ancestor_depth={d} rule_present={any} provenance_present={any} match={s} viewport={s} viewport_limit={any} rank_unknown={any} order={any} specificity={any} source_index={any} css_byte_start={any} css_bytes={any} conditions_count={any} selector_hex={s} selector_bytes={d} selector_truncated={any} declaration_hex={s} declaration_bytes={d} declaration_truncated={any} declaration_offset={d}", .{
            stage, @intFromPtr(self), profile_ptr, checked_profile_ptr, checked_root_ptr,
            @tagName(value.reason), value.ancestor_depth, rule != null, provenance != null,
            if (rule) |known| @tagName(known.match) else "null",
            if (rule) |known| @tagName(known.viewport) else "null", viewport_limit, rank_unknown, order, specificity,
            source_index, css_byte_start, css_bytes, conditions_count,
            boundedTraceHex(&selector_buffer, selector), selector.len, selector.len > selector_buffer.len / 2,
            boundedTraceHex(&declaration_buffer, value.declaration), value.declaration.len,
            value.declaration.len > declaration_buffer.len / 2, value.declaration_offset,
        });
    }

    fn observedTablePagePreflightCovered(self: *Renderer, source: MissingText, parent: Style) Error!bool {
        if (self.content_root != .parser_output or self.in_reference or self.in_template_literal_scope or
            self.figure_caption_depth != 0 or !QuoteSourceMap.cleanLocal(source) or source.bytes.len == 0) return self.tablePagePreflightDecline("table_preflight.source_scope");
        if (self.table_page_preflight) |held| {
            if (!self.tablePagePreflightCurrent(held)) return self.tablePagePreflightDecline("table_preflight.held_identity");
            if (source.bytes.ptr == held.parsed.ptr and source.bytes.len == held.parsed.len and
                self.context.table_styles == held.scope.page_styles and sameFigurePreparationValue(parent, held.parent)) return true;
            const cell = self.table_viewport_cell_source orelse return self.tablePagePreflightDecline("table_preflight.cell_absent");
            if (cell.page_preflight != held or !cell.closed_focus or cell.source_constructed or cell.captured_intrinsic_content or
                self.context.table_styles != held.candidate.profile) return self.tablePagePreflightDecline("table_preflight.cell_identity");
            const parents = cell.page_preflight_parents orelse return self.tablePagePreflightDecline("table_preflight.cell_parents_absent");
            if (!sameFigurePreparationValue(parent, parents.inline_style) and
                !sameFigurePreparationValue(parent, parents.block_style)) return self.tablePagePreflightDecline("table_preflight.cell_parent_style");
            var matched = false;
            for (held.candidate.cells) |known| if (known.body.ptr == cell.source.ptr and known.body.len == cell.source.len) { matched = true; break; };
            if (!matched) return self.tablePagePreflightDecline("table_preflight.cell_membership");
            const original = self.tablePreflightOriginal(source) orelse return self.tablePagePreflightDecline("table_preflight.cell_source_map");
            const contains = wikiClassContains(cell.source, original);
            if (!contains) _ = self.tablePagePreflightDecline("table_preflight.cell_range");
            return contains;
        }
        if (self.body_depth != 0 or self.table_viewport_cell_source != null or self.source_element_binding != null) return self.tablePagePreflightDecline("table_preflight.entry_scope");
        const domain = self.pageStyleDomain() orelse return self.tablePagePreflightDecline("table_preflight.page_domain");
        const selected = self.tableDirectionSource() orelse return self.tablePagePreflightDecline("table_preflight.table_source");
        if (!selected.prefix_viewport or selected.intrinsic_viewport or !selected.root_only or
            source.bytes.ptr != selected.source.ptr or source.bytes.len > selected.source.len or selected.source.len > 4 * 1024 * 1024 or
            domain.source.ptr != selected.source.ptr or domain.source.len != selected.source.len or
            domain.owner.ptr != selected.source.ptr or domain.owner.len != selected.source.len) return self.tablePagePreflightDecline("table_preflight.source_identity");
        const issue = selected.preflight_scope orelse return self.tablePagePreflightDecline("table_preflight.issuer_absent");
        const observed = issue(selected.context, selected.source) orelse return self.tablePagePreflightDecline("table_preflight.issuer_refused");
        if (observed.scope != domain.scope or observed.source.ptr != selected.source.ptr or observed.source.len != selected.source.len) return self.tablePagePreflightDecline("table_preflight.issuer_identity");
        var opening: usize = 0;
        while (opening < source.bytes.len and (source.bytes[opening] == '\n' or source.bytes[opening] == '\r')) : (opening += 1) {}
        if (!std.mem.startsWith(u8, source.bytes[opening..], "{|")) return self.tablePagePreflightDecline("table_preflight.table_opener");
        const end = std.mem.indexOfScalarPos(u8, source.bytes, opening, '\n') orelse return self.tablePagePreflightDecline("table_preflight.table_line");
        const native = self.cellNativeFlowContext(self.block_formatting);
        const physical = self.bodyFormattingStyle(.{}).text_element;
        var candidate = (self.prepareTableViewportMode(source.bytes, opening, end, native, physical, false) catch |err| switch (err) {
            error.InvalidFontScale => return self.tablePagePreflightDecline("table_preflight.font_scale"), else => return err,
        }) orelse return self.tablePagePreflightDecline("table_preflight.viewport_candidate");
        if (candidate.policy == null or !candidate.graph.prefix_media or candidate.graph.intrinsic or
            candidate.graph.end > source.bytes.len or trim(source.bytes[candidate.graph.end..]).len != 0) return self.tablePagePreflightDecline("table_preflight.candidate_shape");
        const bound = candidate.link_source orelse return self.tablePagePreflightDecline("table_preflight.link_source");
        if (bound.source_constructed or !bound.proof.closedSourceFocus()) return self.tablePagePreflightDecline("table_preflight.source_focus");
        const profiles = [_]*const table_style_profile.Profile{ domain.scope.page_styles orelse return self.tablePagePreflightDecline("table_preflight.page_profile"), candidate.profile };
        var all: std.ArrayList(*const table_style_profile.Profile) = .empty;
        try all.appendSlice(self.a, &profiles);
        if (candidate.preflight_contexts.len == 0 or candidate.preflight_contexts.len > 8) return self.tablePagePreflightDecline("table_preflight.head_count");
        for (candidate.preflight_contexts) |context| try all.append(self.a, context.styles);
        const inventories = (try self.tablePreflightInventories(all.items)) orelse return self.tablePagePreflightDecline("table_preflight.rule_inventories");
        const held = try self.a.create(TablePagePreflight);
        candidate.page_preflight = held;
        held.* = .{ .selected = selected, .scope = domain.scope, .saved_scope = domain.scope.*,
            .inventories = inventories, .contexts = try self.a.dupe(table_style_profile.TableContainingDirectionContext, candidate.preflight_contexts),
            .parsed = source.bytes, .source_bytes = try self.a.dupe(u8, selected.source),
            .opening_start = opening, .opening_end = end, .parent = parent, .native = native,
            .physical_parent = physical, .candidate = candidate };
        self.table_page_preflight = held;
        const current = self.tablePagePreflightCurrent(held);
        if (!current) _ = self.tablePagePreflightDecline("table_preflight.current");
        return current;
    }

    const RowColorCopyOwner = struct {
        scope: *const table_style_profile.BoundedTextClassScope,
        proof: *const table_style_profile.ClosedRowColorProof,
        original: MissingText,
        copied: MissingText,
        anchor: []const u8,
    };
    const RowColorAttributes = struct {
        proof: *const table_style_profile.ClosedRowColorProof,
        attribute: []const u8,
        presence: table_style_profile.AttributePresence,
        fn get(raw: ?*const anyopaque, name: []const u8) table_style_profile.AttributePresence {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return .unknown));
            return if (std.ascii.eqlIgnoreCase(name, self.attribute)) self.presence else .unknown;
        }
    };

    fn validClosedRowColors(scope: *const table_style_profile.BoundedTextClassScope, source: []const u8, profile: *const table_style_profile.Profile) ?*const table_style_profile.ClosedRowColorProof {
        const proof = if (scope.closed_row_colors) |*value| value else return null;
        if (proof.styles != profile or proof.root != scope.page_style_root or proof.source.len == 0 or
            proof.source.ptr != source.ptr or proof.source.len != source.len or
            !std.mem.eql(u8, proof.attribute, "bgcolor") or proof.owners.len > 4096) return null;
        if (proof.absent_source != null) return if (table_style_profile.closedRowColorAbsenceValid(proof)) proof else null;
        if (proof.owners.len == 0) return null;
        var previous: usize = 0;
        for (proof.owners) |owner| {
            if (owner.attrs_start < 2 or owner.attrs_start < previous or owner.attrs_start >= owner.attrs_end or owner.attrs_end > source.len or
                !std.mem.eql(u8, source[owner.attrs_start - 2..owner.attrs_start], "|-") or
                (owner.attrs_start != 2 and source[owner.attrs_start - 3] != '\n') or
                (owner.attrs_end != source.len and source[owner.attrs_end] != '\n')) return null;
            previous = owner.attrs_end;
        }
        return proof;
    }

    fn validUnobservedCounters(scope: *const table_style_profile.BoundedTextClassScope, source: []const u8,
        styles: *const table_style_profile.Profile) ?*const table_style_profile.UnobservedCounterResetProof
    {
        const proof = if (scope.unobserved_counter_resets) |*value| value else return null;
        const source_image = scope.page_source_image orelse return null;
        if (proof.source_image != source_image or proof.styles != styles or proof.root != scope.page_style_root or
            proof.source.ptr != source.ptr or proof.source.len != source.len or
            !table_style_profile.unobservedCounterSourceCurrent(proof) or
            proof.rules.ptr != styles.container_rules.ptr or proof.rules.len != styles.container_rules.len or
            proof.resets.len == 0 or proof.resets.len > 64) return null;
        for (proof.resets) |entry| if (entry.rule >= styles.container_rules.len) return null;
        return proof;
    }

    fn cleanEmptyRowCopy(source: MissingText) bool {
        return source.bytes.len == 0 and !source.unknown and !source.lost_missing_range and
            source.generated_source == null and source.ranges.len == 0 and
            source.literal_curly_ranges.len == 0 and source.generated_links.len == 0;
    }

    fn rowColorCopyOwnerCurrent(self: *const Renderer, held: *const RowColorCopyOwner) bool {
        if (self.source_element_binding != null) return false;
        const domain = self.pageStyleDomain() orelse return false;
        const styles = self.context.table_styles orelse return false;
        if (domain.scope != held.scope or validClosedRowColors(domain.scope, domain.source, styles) != held.proof or
            held.original.bytes.ptr != domain.owner.ptr or held.original.bytes.len != domain.owner.len or
            (!wikiClassCleanText(held.original) or held.original.bytes.len == 0)) return false;
        const current = self.inline_missing orelse self.body_missing orelse return false;
        if (held.copied.bytes.len == 0) return cleanEmptyRowCopy(held.copied) and cleanEmptyRowCopy(current) and
            held.anchor.len == 0 and held.anchor.ptr == held.copied.bytes.ptr and
            wikiClassContains(held.original.bytes, held.anchor) and current.bytes.ptr == held.copied.bytes.ptr;
        if (!wikiClassCleanText(held.copied)) return false;
        const original = self.registeredCaptionOriginal(held.copied.bytes) orelse return false;
        if (original.ptr != held.anchor.ptr or original.len != held.anchor.len or !wikiClassContains(held.original.bytes, original)) return false;
        if (!wikiClassCleanText(current)) return false;
        const current_original = self.registeredCaptionOriginal(current.bytes) orelse return false;
        return wikiClassContains(held.anchor, current_original);
    }

    fn rowColorCopiedOwner(self: *const Renderer, copied: MissingText) ?RowColorCopyOwner {
        if (self.source_element_binding != null or !wikiClassCleanText(copied)) return null;
        const domain = self.pageStyleDomain() orelse return null;
        const proof = self.rowColorSourceProof() orelse return null;
        var original = self.body_missing orelse return null;
        if (self.row_color_copy_owner) |held| if (self.rowColorCopyOwnerCurrent(held)) { original = held.original; };
        if (original.bytes.ptr != domain.owner.ptr or original.bytes.len != domain.owner.len or
            (!wikiClassCleanText(original) or original.bytes.len == 0)) return null;
        const anchor = if (copied.bytes.len == 0) copied.bytes else self.pageStyleCopiedAnchor(copied, copied.bytes) orelse return null;
        if (!wikiClassContains(original.bytes, anchor)) return null;
        return .{ .scope = domain.scope, .proof = proof, .original = original, .copied = copied, .anchor = anchor };
    }

    fn rowColorSourceProof(self: *const Renderer) ?*const table_style_profile.ClosedRowColorProof {
        const domain = self.pageStyleDomain() orelse return null;
        const styles = self.context.table_styles orelse return null;
        const proof = validClosedRowColors(domain.scope, domain.source, styles) orelse return null;
        // This fact is unavailable during foreign, generated, protected or
        // partially mapped parsing. It is never a tag-name default.
        const tracked = self.inline_missing orelse self.body_missing orelse return null;
        if ((!wikiClassContains(domain.owner, tracked.bytes) and self.pageStyleCopiedAnchor(tracked, tracked.bytes) == null) or
            tracked.lost_missing_range or tracked.generated_source != null or
            !ordinaryNormalizationRange(tracked, 0, tracked.bytes.len)) return null;
        return proof;
    }

    fn rowColorOwnerForTag(self: *const Renderer, proof: *const table_style_profile.ClosedRowColorProof, tag: syntax.Tag) bool {
        if (!tag.is("tr") or tag.closing or tag.self_closing or tag.html_pre or tag.end != 0) return false;
        const issued = self.page_style_wiki_tag orelse return false;
        if (issued.name.ptr != tag.name.ptr or issued.name.len != tag.name.len or issued.attrs.ptr != tag.attrs.ptr or issued.attrs.len != tag.attrs.len) return false;
        for (proof.owners) |owner| {
            const original = proof.source[owner.attrs_start..owner.attrs_end];
            const current = self.pageStyleOriginalAnchor(original) orelse continue;
            if (current.ptr == tag.attrs.ptr and current.len == tag.attrs.len and std.mem.eql(u8, current, original)) return true;
        }
        return false;
    }

    fn rowColorAttributesCurrent(self: *const Renderer, node: *const table_style_profile.TextElement) bool {
        const attributes = node.attribute_presence orelse return true;
        if (attributes.get != RowColorAttributes.get) return true;
        const facts: *const RowColorAttributes = @ptrCast(@alignCast(attributes.ctx orelse return false));
        return self.rowColorSourceProof() == facts.proof;
    }

    fn tableRowColorOwnAbsence(self: *const Renderer, tag: syntax.Tag, style: Style) ?[]const u8 {
        if (!tag.is("table") and !tag.is("td") and !tag.is("th")) return null;
        const proof = self.rowColorSourceProof() orelse return null;
        const owner = style.text_element orelse return null;
        if (owner.page_style_root != proof.root or !self.currentAncestorScope(owner) or
            htmlOwnAttributePresence(&tag, proof.attribute) != .absent) return null;
        // Attribute-free cells inherit the actual row font, not its own bgcolor.
        return proof.attribute;
    }

    fn rowColorAttributesForTag(self: *Renderer, tag: syntax.Tag) Error!?table_style_profile.AttributePresenceSource {
        const proof = self.rowColorSourceProof() orelse return null;
        var presence: table_style_profile.AttributePresence = .absent;
        if (tag.is("tr")) {
            if (self.rowColorOwnerForTag(proof, tag)) presence = .present else {
                // Only the ordinary generated row query may use the complete
                // census to refute an implicit/attribute-free row.
                const issued = self.page_style_wiki_tag orelse return null;
                if (issued.name.ptr != tag.name.ptr or issued.name.len != tag.name.len or issued.attrs.ptr != tag.attrs.ptr or issued.attrs.len != tag.attrs.len or
                    htmlOwnAttributePresence(&tag, proof.attribute) != .absent) return null;
                if (tag.attrs.len != 0 and !self.pageStyleSourceRange(tag.attrs)) return null;
            }
        }
        // A supplied contradictory owner cannot borrow the global absence
        // fact, even while another selected source parse is active.
        if (!tag.is("tr") and htmlOwnAttributePresence(&tag, proof.attribute) != .absent) return null;
        const facts = try self.a.create(RowColorAttributes);
        facts.* = .{ .proof = proof, .attribute = proof.attribute, .presence = presence };
        return .{ .ctx = facts, .get = RowColorAttributes.get };
    }

    fn requireRowColorConsumed(self: *Renderer, tag: syntax.Tag, style: Style) void {
        if (!tag.is("tr")) return;
        const domain = self.pageStyleDomain() orelse return;
        const owed = self.required_row_color_scope orelse return;
        const styles = self.context.table_styles orelse return;
        const proof = self.rowColorSourceProof();
        if (domain.scope != owed or validClosedRowColors(owed, domain.source, styles) == null or proof == null) {
            self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "row_color.source", tag.attrs); return;
        }
        if (htmlOwnAttributePresence(&tag, proof.?.attribute) == .absent) return;
        if (!self.rowColorOwnerForTag(proof.?, tag) or !style.table_text_color_consumed or style.foreground == null)
            self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "row_color.consumption", tag.attrs);
    }

    fn checkPageAncestorEffectsIn(self: *Renderer, source: MissingText, parent: Style) Error!void {
        if (self.context.table_viewport_trace) self.table_page_preflight_decline = null;
        // This proof belongs only to the whole caption currently being parsed.
        // It neither populates the page cache nor clears a previous report.
