    }

    const FigureClassSourceDomain = struct {
        scope: *const table_style_profile.BoundedTextClassScope,
        selected: []const u8,
    };
    fn figureClassSourceDomain(self: *const Renderer) ?FigureClassSourceDomain {
        if (self.content_root != .parser_output or self.in_reference or self.in_template_literal_scope) return null;
        if (self.bounded_text_class_scope) |scope| if (scope.complete_ancestor_class_superset != null) {
            if (self.bounded_text_class_source) |source| return .{ .scope = scope, .selected = source };
        };
        const binding = self.figure_class_source_binding orelse return null;
        const sizing = self.context.figure_sizing orelse return null;
        const observed = sizing.text_class_scope orelse return null;
        if (binding.scope != observed.scope or observed.scope.complete_ancestor_class_superset == null or
            binding.projection.original.bytes.ptr != observed.source.ptr or
            binding.projection.original.bytes.len != observed.source.len) return null;
        return .{ .scope = observed.scope, .selected = observed.source };
    }
    fn figureClassOriginal(self: *const Renderer, part: []const u8) ?[]const u8 {
        if (self.classScopeForSource(part) != null) return part;
        const domain = self.figureClassSourceDomain() orelse return null;
        if (part.len == 0) return null;
        if (wikiClassContains(domain.selected, part)) return part;
        const binding = self.figure_class_source_binding orelse return null;
        if (binding.scope != domain.scope) return null;
        const start = binding.originalRange(part) orelse return null;
        if (start > domain.selected.len or part.len > domain.selected.len - start) return null;
        return domain.selected[start..][0..part.len];
    }
    fn figureClassScopeForOriginal(self: *const Renderer, part: []const u8) ?*const table_style_profile.BoundedTextClassScope {
        if (self.classScopeForSource(part)) |scope| return scope;
        const domain = self.figureClassSourceDomain() orelse return null;
        return if (part.len != 0 and wikiClassContains(domain.selected, part)) domain.scope else null;
    }

    fn figureRootCompleteClasses(self: *const Renderer, tracked: MissingText, caption: []const u8, parent: Style) ?[]const u8 {
        if (parent.text_element) |node| if (!self.currentAncestorScope(node)) return null;
        const scope = self.captionClassScope(tracked, caption) orelse self.copiedFileCaptionClassScope(tracked, caption) orelse return null;
        return scope.complete_ancestor_class_superset;
    }

    // Failure-only evidence for the complete-class factory. All queries below
    // are read-only and retain the live copy/quote domains of this Figure call.
    fn traceFigureRootClassFailure(self: *const Renderer, tracked: MissingText, caption: []const u8, parent: Style, factory_complete: bool) void {
        const parent_current = if (parent.text_element) |node| self.currentAncestorScope(node) else true;
        const selected = self.bounded_text_class_source;
        const scope = self.bounded_text_class_scope;
        const token_original = self.registeredCaptionOriginal(tracked.bytes);
        const caption_original = self.registeredCaptionOriginal(caption);
        const direct = self.captionClassScope(tracked, caption);
        const copied = self.fileCaptionCopiedScope(tracked.bytes, caption);
        diagnostics.logLine("presentation figure_root_class_probe scope=renderer_fragment factory_complete={any} root={s} reference={any} template_literal={any} parent_present={any} parent_current={any} bounded_scope={any} bounded_source={any} complete_union={any} source_elements={any} token_bytes={d} caption_bytes={d} missing_ranges={d} literal_ranges={d} generated_links={d} lost_range={any} direct_caption_scope={any} registered_token={any} registered_caption={any} copied_file_scope={any}", .{
            factory_complete, @tagName(self.content_root), self.in_reference, self.in_template_literal_scope, parent.text_element != null, parent_current,
            scope != null, selected != null, if (scope) |value| value.complete_ancestor_class_superset != null else false,
            self.source_element_binding != null, tracked.bytes.len, caption.len, tracked.ranges.len, tracked.literal_curly_ranges.len,
            tracked.generated_links.len, tracked.lost_missing_range, direct != null, token_original != null, caption_original != null, copied != null,
        });
        var next = self.figure_caption_quote_source;
        var index: usize = 0;
        while (next) |domain| : (index += 1) {
            if (index == 8) {
                diagnostics.logLine("presentation figure_root_class_quote truncated=true limit=8", .{});
                break;
            }
            next = domain.parent;
            const token = domain.map.coveredOriginal(tracked.bytes, domain.map.original);
            const original_caption = domain.map.coveredOriginal(caption, domain.map.original);
            const file_scope = if (token) |whole| if (original_caption) |label| self.fileCaptionCopiedScope(whole, label) else null else null;
            const selected_current = if (selected) |value| domain.selected.ptr == value.ptr and domain.selected.len == value.len else false;
            diagnostics.logLine("presentation figure_root_class_quote index={d} scope_current={any} selected_current={any} input_bytes={d} output_bytes={d} token_covered={any} caption_covered={any} covered_file_scope={any}", .{
                index, domain.scope == scope, selected_current, domain.map.original.len, domain.map.output.len,
                token != null, original_caption != null, file_scope != null,
            });
        }
        if (index == 0) diagnostics.logLine("presentation figure_root_class_quote domains=0", .{});
    }

    // Resolve a complete immutable interval through registered copy operations.
    // An offset for its first byte or an equal string does not prove coverage.
    fn registeredCaptionOriginal(self: *const Renderer, part: []const u8) ?[]const u8 {
        return self.registeredOriginalInterval(part, null);
    }
    fn registeredOriginalInterval(self: *const Renderer, part: []const u8, issued: ?[]const u8) ?[]const u8 {
        if (part.len == 0) return null;
        var current = part;
        var depth: usize = 0;
        while (depth < max_depth) : (depth += 1) {
            if (issued) |selected| {
                if (wikiClassContains(selected, current)) return current;
            } else if (self.figureClassOriginal(current)) |original| return original;
            var mapped: ?[]const u8 = null;
            if (self.plain_body_source_copy) |copy| {
                if (copy.copied.len == copy.original.len and wikiClassContains(copy.copied, current)) {
                    const offset = @intFromPtr(current.ptr) - @intFromPtr(copy.copied.ptr);
                    const original = copy.original[offset..][0..current.len];
                    const owner = self.body_missing orelse return null;
                    if (!noLiParentSourceRange(owner, original)) return null;
                    if (!std.mem.eql(u8, current, original)) return null;
                    // A no-op copy adds no edge and cannot conflict with an
                    // independently registered copy to the original source.
                    if (original.ptr != current.ptr) mapped = original;
                }
            }
            for (self.heading_source_aliases.items) |alias| {
                const offset = std.math.sub(usize, @intFromPtr(current.ptr), @intFromPtr(alias.copied.ptr)) catch continue;
                if (offset > alias.copied.len or current.len > alias.copied.len - offset or
                    offset > alias.original.len or current.len > alias.original.len - offset) continue;
                const original = alias.original[offset .. offset + current.len];
                if (!std.mem.eql(u8, current, original)) return null;
                if (mapped) |prior| if (prior.ptr != original.ptr or prior.len != original.len) return null;
                mapped = original;
            }
            const next = mapped orelse return null;
            if (next.ptr == current.ptr and next.len == current.len) return null;
            current = next;
        }
        return null;
    }
    fn fileCaptionCopiedScope(self: *const Renderer, token: []const u8, caption: []const u8) ?*const table_style_profile.BoundedTextClassScope {
        if (!starts(token, "[[") or !std.mem.endsWith(u8, token, "]]")) return null;
        const pair = syntax.balanced(token, 0) orelse return null;
        if (pair.end != token.len) return null;
        const caption_at = std.math.sub(usize, @intFromPtr(caption.ptr), @intFromPtr(token.ptr)) catch return null;
        if (caption_at < 2 or caption.len == 0 or caption_at > token.len - 2 or caption.len > token.len - 2 - caption_at) return null;
        var iterator: ir.InlineIterator = .{ .input = token, .renderer_boundaries = true };
        const node = iterator.next() orelse return null;
        if (node.kind != .link or iterator.cursor != token.len or self.namespaceOfTarget(node.target) != 6) return null;
        const original_token = self.registeredCaptionOriginal(token) orelse return null;
        const original_caption = self.registeredCaptionOriginal(caption) orelse return null;
        if (original_caption.ptr != original_token[caption_at..].ptr or original_caption.len != caption.len) return null;
        const scope = self.figureClassScopeForOriginal(original_token) orelse return null;
        return if (self.figureClassScopeForOriginal(original_caption) == scope) scope else null;
    }
    fn copiedFileCaptionClassScope(self: *const Renderer, tracked: MissingText, caption: []const u8) ?*const table_style_profile.BoundedTextClassScope {
        if (tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or tracked.generated_links.len != 0 or tracked.lost_missing_range) return null;
        const caption_at = std.math.sub(usize, @intFromPtr(caption.ptr), @intFromPtr(tracked.bytes.ptr)) catch return null;
        if (caption_at > tracked.bytes.len or caption.len > tracked.bytes.len - caption_at) return null;
        if (self.fileCaptionCopiedScope(tracked.bytes, caption)) |scope| return scope;
        const current_domain = self.figureClassSourceDomain() orelse return null;
        const selected = current_domain.selected;
        var next = self.figure_caption_quote_source;
        var remaining: usize = max_depth + 1;
        while (next) |domain| {
            if (remaining == 0) return null;
            remaining -= 1; next = domain.parent;
            if (domain.scope != current_domain.scope or domain.selected.ptr != selected.ptr or domain.selected.len != selected.len) continue;
            // Complete quote-operation coverage maps the whole token and the
            // complete caption independently; only then may copy custody apply.
            const token = domain.map.coveredOriginal(tracked.bytes, domain.map.original) orelse continue;
            const original_caption = domain.map.coveredOriginal(caption, domain.map.original) orelse continue;
            const selected_token = self.quoteClassOriginal(domain, token) orelse continue;
            const selected_caption = self.quoteClassOriginal(domain, original_caption) orelse continue;
            if (self.fileCaptionCopiedScope(selected_token, selected_caption)) |scope| return scope;
        }
        return null;
    }

    fn captionClassScope(self: *const Renderer, tracked: MissingText, caption: []const u8) ?*const table_style_profile.BoundedTextClassScope {
        if (tracked.ranges.len != 0 or tracked.literal_curly_ranges.len != 0 or tracked.generated_links.len != 0 or tracked.lost_missing_range) return null;
        const token_begin = @intFromPtr(tracked.bytes.ptr);
        const caption_begin = @intFromPtr(caption.ptr);
        if (caption_begin < token_begin or caption_begin - token_begin > tracked.bytes.len or
            caption.len > tracked.bytes.len - (caption_begin - token_begin)) return null;
        if (self.classScopeForSource(tracked.bytes)) |scope|
            return if (self.classScopeForSource(caption) == scope) scope else null;
        const selected = self.bounded_text_class_source orelse return null;
        const before = caption_begin - token_begin;
        const after = before + caption.len;
        if (before == 0 or after == tracked.bytes.len or !wikiClassCleanText(tracked)) return null;
        var next = self.quote_class_source;
        var remaining: usize = max_depth + 1;
        while (next) |domain| {
            if (remaining == 0) return null;
            remaining -= 1;
            next = domain.parent;
            if (selected.ptr != domain.selected.ptr or selected.len != domain.selected.len or
                self.classScopeForSource(domain.map.original) != domain.scope) continue;
            const original_caption = domain.map.coveredOriginal(caption, selected) orelse continue;
            const prefix = domain.map.copiedOriginal(tracked.bytes[0..before]) orelse continue;
            const suffix = domain.map.copiedOriginal(tracked.bytes[after..]) orelse continue;
            // Only caption quote operations may differ. The original File token
            // prefix and suffix must be exact adjacent copies from this occurrence.
            if (@intFromPtr(prefix.ptr) + prefix.len != @intFromPtr(original_caption.ptr) or
                @intFromPtr(original_caption.ptr) + original_caption.len != @intFromPtr(suffix.ptr)) continue;
            const start = @intFromPtr(prefix.ptr) - @intFromPtr(domain.map.original.ptr);
            const len = prefix.len + original_caption.len + suffix.len;
            if (start > domain.map.original.len or len > domain.map.original.len - start) continue;
            const original_token = domain.map.original[start .. start + len];
            if (!starts(original_token, "[[") or !std.mem.endsWith(u8, original_token, "]]")) continue;
            if (self.classScopeForSource(original_token) != domain.scope or
                self.classScopeForSource(original_caption) != domain.scope) continue;
            return domain.scope;
        }
        return null;
    }

    // The direct source factory remains useful for untransformed owned nodes.
    fn sourceBoundCaptionStyle(self: *Renderer, tracked: MissingText, caption: []const u8, original: Style, prepared: Style) Error!Style {
        return self.sourceBoundCaptionStyleWithParent(tracked, caption, original, prepared, null);
    }
    fn sourceBoundCaptionStyleWithParent(self: *Renderer, tracked: MissingText, caption: []const u8, original: Style, prepared: Style, issued: ?PreparedCaptionParent) Error!Style {
        var result = prepared;
        const scope = self.captionClassScope(tracked, caption) orelse self.copiedFileCaptionClassScope(tracked, caption) orelse return result;
        const domain = self.figureClassSourceDomain() orelse return result;
        if (domain.scope != scope) return result;
        if (original.text_element) |element| {
            if (!self.currentAncestorScope(element)) return result;
            if (element.complete_ancestor_classes == null) {
                // Only the completed Figure capability may bind its caption.
                // The original table keeps its unscoped generic ancestry.
                if (issued == null) return result;
                const root = self.selectedPageStyleRoot(scope) orelse return result;
                if (element.page_style_root != root or
                    self.copiedFileCaptionClassScope(tracked, caption) != scope or
                    self.pageStyleCopiedAnchor(tracked, tracked.bytes) == null) return result;
            }
        }
        const node = prepared.text_element orelse return result;
        if (!std.ascii.eqlIgnoreCase(node.tag, "figcaption")) return result;
        const figure = node.parent orelse return result;
        if (!std.ascii.eqlIgnoreCase(figure.tag, "figure")) return result;
        if (issued) |proof| {
            if (proof.original != original.text_element or proof.prepared != figure.parent or proof.figure != figure or
                proof.caption != node or proof.caption_source.ptr != caption.ptr or proof.caption_source.len != caption.len) return result;
            if (proof.scope != scope or proof.source.ptr != domain.selected.ptr or proof.source.len != domain.selected.len) return result;
            if (proof.root_rtl == null and proof.prepared != proof.original) return result;
            if (proof.root_rtl != null and self.content_root != .parser_output) return result;
            var cursor = proof.prepared;
            for (proof.ancestors) |edge| {
                const current = cursor orelse return result;
                if (current != edge.node or current.parent != edge.parent or
                    current.classes.ptr != edge.classes.ptr or current.classes.len != edge.classes.len) return result;
                cursor = current.parent;
            }
            if (cursor != null) return result;
            if (proof.root_rtl) |rtl| {
                if (proof.ancestors.len == 0) return result;
                const root = proof.ancestors[proof.ancestors.len - 1].node;
                if (root.parent != null or !root.ancestry_complete or !std.mem.eql(u8, root.tag, "div") or
                    !std.mem.eql(u8, root.classes, if (rtl) "mw-content-rtl mw-parser-output" else "mw-content-ltr mw-parser-output")) return result;
            }
        } else if (figure.parent != original.text_element) return result;
        var classes: std.ArrayList(u8) = .empty;
        defer classes.deinit(self.a);
        try classes.appendSlice(self.a, scope.complete_ancestor_class_superset.?);
        // Include actual generated geometry classes conservatively. This is only
        // an absence certificate; it adds no positive CSS or adjacency authority.
        var ancestor: ?*const table_style_profile.TextElement = figure;
        var count: usize = 0;
        while (ancestor) |element| : (ancestor = element.parent) {
            if (count == max_html_normalization_frames + 2) return result;
            count += 1;
            if (element.classes.len != 0) {
                if (classes.items.len != 0) try classes.append(self.a, ' ');
                try classes.appendSlice(self.a, element.classes);
            }
        }
        const bound = try self.a.create(table_style_profile.TextElement);
        bound.* = node.*;
        bound.complete_ancestor_classes = try classes.toOwnedSlice(self.a);
        // Root transport remains independent of the class-absence certificate.
        const page_anchor = self.pageStyleCopiedAnchor(tracked, caption);
        bound.page_style_root = if (page_anchor != null) self.selectedPageStyleRoot(scope) else null;
        bound.page_style_source = if (bound.page_style_root != null) domain.selected else null;
        bound.page_style_anchor = if (bound.page_style_root != null) page_anchor else null;
        bound.ancestor_class_scope = scope;
        bound.ancestor_class_source = domain.selected;
        result.text_element = bound;
        return result;
    }
    fn textPaint(self: *Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement, inherited_language: []const u8) Error!table_style_profile.TextPaint {
        return self.textPaintWithCustom(tag, parent, inherited_language, null);
    }
    fn textPaintWithCustom(self: *Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement, inherited_language: []const u8, environment: ?table_style_profile.CustomEnvironment) Error!table_style_profile.TextPaint {
        if (self.tableInlineSourceForTag(tag)) |known| return known.paint.?;
        if (self.observedFigureCaptionTagStyle(tag)) |known| return .{
            .color = if (known.foreground) |color| .{ .value = color } else .inherit,
            .weight = .{ .value = known.bold }, .font_style = .{ .value = known.italic },
        };
        const profile = self.textPaintProfile() orelse return .{};
        if (!profile.hasTextPaint()) return .{};
        const element = try self.textElement(tag, parent, inherited_language);
        const css = (try self.semanticAttribute(tag, "style")) orelse "";
        if (!fontStyleListComplete(css)) return .{ .color = .unknown, .weight = .unknown, .font_style = .unknown, .color_inline = true, .weight_inline = true, .font_style_inline = true };
        const state = self.currentLiteralParentState();
        const paint_node = (try self.literalFirstDivQuery(tag, element, state, element)) orelse element;
        var paint = if (element.source_root_child != null or element.source_literal_div != null)
            try profile.resolveTextPaintWithObservedInheritance(self.a, element, css, environment)
        else try profile.resolveTextPaintWithCustom(self.a, paint_node, css, environment);
        // Only the independently proved foreground replaces this weak generic
        // query. Weight and italic evaluation, errors and refusals stay intact.
        if (self.tableConstructedForegroundForTag(tag)) |color| {
            paint.color = .{ .value = color };
            paint.color_inline = false;
        }
        return paint;
    }
    fn htmlFontWeightIn(self: *Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement, inherited_weight: bool, inherited_language: []const u8) Error!?bool {
        const paint = try self.textPaint(tag, parent, inherited_language);
        if (paint.weight) |weight| switch (weight) {
            .value => |value| return value,
            .inherit => return inherited_weight,
            .unknown => {
                if (paint.weight_inline) return self.htmlInlineFontWeight(tag);
                self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "htmlFontWeightIn.1", tag.attrs);
                return null;
            },
        };
        return self.htmlInlineFontWeight(tag);
    }
    fn htmlFontWeight(self: *Renderer, tag: syntax.Tag) Error!?bool {
        return self.htmlFontWeightIn(tag, (if (self.body_language_direction) |body_style| body_style.text_element else null), self.block_formatting.bold, (if (self.body_language_direction) |body_style| body_style.language else self.body_formatting_attributes.language));
    }
    fn tableTextWeightConsumed(self: *const Renderer, paint: table_style_profile.TextPaint, inherited: bool, result: bool) bool {
        const profile = self.context.table_styles orelse return false;
        if (self.textPaintProfile() != profile) return false;
        const weight = paint.weight orelse return false;
        return switch (weight) {
            .value => |value| value == result,
            .inherit => inherited == result,
            .unknown => false,
        };
    }
    fn tableTextColorConsumed(self: *const Renderer, paint: table_style_profile.TextPaint, inherited: Style, result: Style) bool {
        const profile = self.context.table_styles orelse return false;
        if (self.textPaintProfile() != profile) return false;
        const foreground = result.foreground orelse return false;
        const color = paint.color orelse return false;
        return switch (color) {
            .value => |value| std.mem.eql(u8, foreground, value),
            .inherit => if (inherited.foreground) |value| std.mem.eql(u8, foreground, value) else false,
            .unknown, .initial => false,
        };
    }
    fn textPaintForeground(self: *Renderer, paint: table_style_profile.TextPaint, inherited: Style, result: *Style) void {
        if (paint.color) |color| {
            switch (color) {
                .inherit => {
                    result.foreground = inherited.foreground;
                    if (inherited.foreground == null) self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "textPaintForeground.1", "");
                },
                .initial => { result.foreground = null; self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "textPaintForeground.2", ""); },
                .value => |value| result.foreground = value,
                .unknown => {
                    // Existing qualified inline var()/literal handling remains
                    // authoritative when that inline declaration won priority.
                    if (paint.color_inline) return;
                    result.foreground = null;
                    self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "textPaintForeground.3", "");
                },
            }
            result.foreground_set = true;
        }
    }

    // Resolve the literal weight subset with the qualified declaration policy.
    fn htmlInlineFontWeight(self: *Renderer, tag: syntax.Tag) Error!?bool {
        const css = (try self.semanticAttribute(tag, "style")) orelse return null;
        if (!fontStyleListComplete(css)) return null;
        var weight: ?bool = null;
        var important_seen = false;
        var position: usize = 0;
        while (try self.nextColorDeclaration(css, &position)) |raw| {
            defer self.a.free(raw);
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const property_name = trim(raw[0..colon]);
            const exact = std.ascii.eqlIgnoreCase(property_name, "font-weight");
            const reset = std.ascii.eqlIgnoreCase(property_name, "font") or std.ascii.eqlIgnoreCase(property_name, "all");
            const escaped_name = std.mem.indexOfScalar(u8, property_name, '\\') != null;
            if (!exact and !reset and !escaped_name) continue;
            var value = trim(raw[colon + 1 ..]);
            var important = false;
            if (displayPriorityBang(value)) |bang| {
                var priority_buffer: [256]u8 = undefined;
                const priority = displayLiteral(trim(value[bang + 1 ..]), &priority_buffer) orelse continue;
                if (!std.ascii.eqlIgnoreCase(priority, "important")) continue;
                important = true;
                value = trim(value[0..bang]);
            }
            if (value.len == 0) continue;
            if (important_seen and !important) continue;
            // Applicable resets and escaped names clear a prior projection at
            // their own priority, following the qualified font-style pattern.
            var selected: ?bool = null;
            if (!escaped_name) {
                if (std.ascii.eqlIgnoreCase(value, "initial")) {
                    selected = false;
                } else if (exact and std.ascii.eqlIgnoreCase(value, "normal")) {
                    selected = false;
                } else if (exact and std.ascii.eqlIgnoreCase(value, "bold")) {
                    selected = true;
                }
            }
            weight = selected;
            important_seen = important;
        }
        return weight;
    }

    // The shared declaration scanner deliberately tolerates unfinished CSS.
    // Font projection requires a complete attribute before selecting
    // a literal value; malformed siblings cannot manufacture an override.
    fn fontStyleListComplete(css: []const u8) bool {
        var delimiters: [32]u8 = undefined;
        var depth: usize = 0;
        var quote: u8 = 0;
        var at: usize = 0;
        while (at < css.len) : (at += 1) {
            const byte = css[at];
            if (byte == 0) return false;
            if (byte == '\\') {
                if (at + 1 == css.len or std.mem.indexOfScalar(u8, "\n\r\x0c", css[at + 1]) != null) return false;
                at += 1;
                continue;
            }
            if (quote != 0) {
                if (byte == '\n' or byte == '\r' or byte == '\x0c') return false;
                if (byte == quote) quote = 0;
                continue;
            }
            if (byte == '\'' or byte == '"') {
                quote = byte;
                continue;
            }
            if (byte == '/' and at + 1 < css.len and css[at + 1] == '*') {
                const close = std.mem.indexOfPos(u8, css, at + 2, "*/") orelse return false;
                at = close + 1;
                continue;
            }
            if (byte == '*' and at + 1 < css.len and css[at + 1] == '/') return false;
            if (byte == '(' or byte == '[' or byte == '{') {
                if (depth == delimiters.len) return false;
                delimiters[depth] = byte;
                depth += 1;
            } else if (byte == ')' or byte == ']' or byte == '}') {
                const opening: u8 = switch (byte) { ')' => '(', ']' => '[', else => '{' };
                if (depth == 0 or delimiters[depth - 1] != opening) return false;
                depth -= 1;
            }
        }
        return quote == 0 and depth == 0;
    }

    fn htmlFontStyleIn(self: *Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement, inherited_italic: bool, inherited_language: []const u8) Error!?bool {
        const paint = try self.textPaint(tag, parent, inherited_language);
        if (paint.font_style) |font_style| switch (font_style) {
            .value => |value| return value,
            .inherit => return inherited_italic,
            .unknown => {
                if (paint.font_style_inline) return self.htmlInlineFontStyle(tag);
                self.fallbacks.unresolved_table_style = self.traceUnresolvedTableStyle(true, "htmlFontStyleIn.1", tag.attrs);
                return null;
            },
        };
        return self.htmlInlineFontStyle(tag);
    }
    fn htmlFontStyle(self: *Renderer, tag: syntax.Tag) Error!?bool {
        return self.htmlFontStyleIn(tag, (if (self.body_language_direction) |body_style| body_style.text_element else null), self.block_formatting.italic, (if (self.body_language_direction) |body_style| body_style.language else self.body_formatting_attributes.language));
    }
    fn htmlInlineFontStyle(self: *Renderer, tag: syntax.Tag) Error!?bool {
        const css = (try self.semanticAttribute(tag, "style")) orelse return null;
        if (!fontStyleListComplete(css)) return null;
        var italic: ?bool = null;
        var important_seen = false;
        var position: usize = 0;
        while (try self.nextColorDeclaration(css, &position)) |raw| {
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const property_name = trim(raw[0..colon]);
            const exact = std.ascii.eqlIgnoreCase(property_name, "font-style");
            const reset = std.ascii.eqlIgnoreCase(property_name, "font") or std.ascii.eqlIgnoreCase(property_name, "all");
            const escaped_name = std.mem.indexOfScalar(u8, property_name, '\\') != null;
            if (!exact and !reset and !escaped_name) continue;
            var value = trim(raw[colon + 1 ..]);
            var important = false;
            if (displayPriorityBang(value)) |bang| {
                var priority_buffer: [256]u8 = undefined;
                const priority = displayLiteral(trim(value[bang + 1 ..]), &priority_buffer) orelse continue;
                if (!std.ascii.eqlIgnoreCase(priority, "important")) continue;
                important = true;
                value = trim(value[0..bang]);
            }
            if (value.len == 0) continue;
            if (important_seen and !important) continue;
            // Font/all shorthand, escaped names and unresolved applicable
            // values invalidate an earlier projection at their own priority.
            // They never evaluate a custom property or invent a font value.
            var selected: ?bool = null;
            if (!escaped_name) {
                if (std.ascii.eqlIgnoreCase(value, "initial")) {
                    selected = false;
                } else if (exact and std.ascii.eqlIgnoreCase(value, "normal")) {
                    selected = false;
                } else if (exact and (std.ascii.eqlIgnoreCase(value, "italic") or std.ascii.eqlIgnoreCase(value, "oblique"))) {
                    selected = true;
                }
            }
            italic = selected;
            important_seen = important;
        }
        return italic;
    }
    // Resolve literal display declarations using the shared CSS scanner.
    // null means unsupported display CSS, not a computed override.
    fn htmlTableInlineDisplay(self: *Renderer, tag: syntax.Tag) Error!?bool {
        const css = (try self.semanticAttribute(tag, "style")) orelse return false;
        if (!fontStyleListComplete(css)) return null;
        var inline_display: ?bool = false;
        var important_seen = false;
        var position: usize = 0;
        while (try self.nextColorDeclaration(css, &position)) |raw| {
            defer self.a.free(raw);
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const property_name = trim(raw[0..colon]);
            const exact = std.ascii.eqlIgnoreCase(property_name, "display");
            const reset = std.ascii.eqlIgnoreCase(property_name, "all");
            const escaped_name = std.mem.indexOfScalar(u8, property_name, '\\') != null;
            if (!exact and !reset and !escaped_name) continue;
            var value = trim(raw[colon + 1 ..]);
            var important = false;
            if (displayPriorityBang(value)) |bang| {
                var priority_buffer: [256]u8 = undefined;
                const priority = displayLiteral(trim(value[bang + 1 ..]), &priority_buffer) orelse continue;
                if (!std.ascii.eqlIgnoreCase(priority, "important")) continue;
                important = true;
                value = trim(value[0..bang]);
            }
            if (value.len == 0) continue;
            if (important_seen and !important) continue;
            // Only literal outer display categories are projected. Unknown
            // all/name resets suppress a stale inline result until overridden.
            var selected: ?bool = null;
            if (exact and !escaped_name) {
                if (oneOf(value, &.{ "inline", "inline-block", "inline-table" })) selected = true else if (oneOf(value, &.{ "block", "table" })) selected = false;
            }
            inline_display = selected;
            important_seen = important;
        }
        return inline_display;
    }

    fn displayLiteral(value: []const u8, buffer: *[256]u8) ?[]const u8 {
        var at: usize = 0;
        var used: usize = 0;
        while (at < value.len) {
            var byte = value[at];
            at += 1;
            if (byte == '\\') {
                if (at == value.len or value[at] == '\n' or value[at] == '\r' or value[at] == '\x0c') return null;
                const first = at;
                while (at < value.len and at - first < 6 and std.ascii.isHex(value[at])) : (at += 1) {}
                if (at != first) {
                    const raw_decoded = std.fmt.parseInt(u32, value[first..at], 16) catch return null;
                    const decoded: u21 = if (raw_decoded == 0 or raw_decoded > 0x10ffff or (raw_decoded >= 0xd800 and raw_decoded <= 0xdfff)) 0xfffd else @intCast(raw_decoded);
                    if (at < value.len and std.ascii.isWhitespace(value[at])) {
                        const cr = value[at] == '\r';
                        at += 1;
                        if (cr and at < value.len and value[at] == '\n') at += 1;
                    }
                    if (decoded > 0x7f) {
                        var encoded: [4]u8 = undefined;
                        const count = std.unicode.utf8Encode(decoded, &encoded) catch return null;
                        if (used + count > buffer.len) return null;
                        @memcpy(buffer[used..][0..count], encoded[0..count]);
                        used += count;
                        continue;
                    }
                    byte = @intCast(decoded);
                } else {
                    byte = value[at];
                    at += 1;
                }
                // An escaped delimiter remains inside one identifier, and
                // therefore cannot create a valid display keyword sequence.
                if (!(std.ascii.isAlphanumeric(byte) or byte == '-' or byte == '_')) return null;
            } else if (std.ascii.isWhitespace(byte)) {
                byte = ' ';
                if (used == 0 or buffer[used - 1] == ' ') continue;
            }
            if (used == buffer.len) return null;
            buffer[used] = byte;
            used += 1;
        }
        return trim(buffer[0..used]);
    }

    fn displayPriorityBang(value: []const u8) ?usize {
        var at: usize = 0;
        var depth: usize = 0;
        var quote: u8 = 0;
        while (at < value.len) : (at += 1) {
            const byte = value[at];
            if (byte == '\\') {
                if (at + 1 < value.len) at += 1;
                continue;
            }
            if (quote != 0) {
                if (byte == quote) quote = 0;
                continue;
            }
            if (byte == '\'' or byte == '"') quote = byte;
            if (byte == '(' or byte == '[' or byte == '{') depth += 1;
            if ((byte == ')' or byte == ']' or byte == '}') and depth != 0) depth -= 1;
            if (byte == '!' and depth == 0 and quote == 0) return at;
        }
        return null;
    }

    fn displayCompoundValid(value: []const u8) bool {
        var outside = false;
        var inside = false;
        var list_item = false;
        var list_inside = true;
        var count: usize = 0;
        var tokens = std.mem.tokenizeAny(u8, value, " \t\r\n\x0c");
        while (tokens.next()) |token| {
            count += 1;
            if (count > 3) return false;
            if (std.ascii.eqlIgnoreCase(token, "list-item")) {
                if (list_item) return false;
                list_item = true;
            } else if (std.ascii.eqlIgnoreCase(token, "block") or std.ascii.eqlIgnoreCase(token, "inline") or std.ascii.eqlIgnoreCase(token, "run-in")) {
                if (outside) return false;
                outside = true;
            } else {
                var valid_inside = false;
                for ([_][]const u8{ "flow", "flow-root", "table", "flex", "grid", "ruby", "math" }) |name| {
                    if (std.ascii.eqlIgnoreCase(token, name)) valid_inside = true;
                }
                if (!valid_inside or inside) return false;
                inside = true;
                list_inside = std.ascii.eqlIgnoreCase(token, "flow") or std.ascii.eqlIgnoreCase(token, "flow-root");
            }
        }
        return count > 1 and (!list_item or list_inside);
    }

    // CSS substitution functions defer display's grammar until computed-value
    // time. Arbitrary functions (calc, url, etc.) do not have that privilege.
    fn displaySubstitution(value: []const u8) bool {
        var at: usize = 0;
        var depth: usize = 0;
        var quote: u8 = 0;
        var found = false;
        var identifier_continuation = false;
        while (at < value.len) : (at += 1) {
            const byte = value[at];
            if (byte == '\\') {
                if (at + 1 == value.len or value[at + 1] == '\n' or value[at + 1] == '\r') return false;
                at += 1;
                if (std.ascii.isHex(value[at])) {
                    const first = at;
                    while (at + 1 < value.len and at + 1 - first < 6 and std.ascii.isHex(value[at + 1])) : (at += 1) {}
                    if (at + 1 < value.len and std.ascii.isWhitespace(value[at + 1])) at += 1;
                }
                identifier_continuation = true;
                continue;
            }
            if (quote != 0) {
                if (byte == quote) {
                    quote = 0;
                    identifier_continuation = false;
                }
                continue;
            }
            if (byte == '\'' or byte == '"') {
                quote = byte;
                identifier_continuation = false;
                continue;
            }
            const begins_identifier = !identifier_continuation;
            identifier_continuation = std.ascii.isAlphanumeric(byte) or byte == '-' or byte == '_' or byte >= 0x80;
            if (byte == '(') depth += 1;
            if (byte == ')') {
                if (depth == 0) return false;
                depth -= 1;
            }
            if (!begins_identifier) continue;
            const var_fn = value.len - at >= 4 and std.ascii.eqlIgnoreCase(value[at..][0..4], "var(");
            const env_fn = value.len - at >= 4 and std.ascii.eqlIgnoreCase(value[at..][0..4], "env(");
            if (!var_fn and !env_fn) continue;
            const argument = std.mem.trimStart(u8, value[at + 4 ..], " \t\r\n\x0c");
            const end = std.mem.indexOfAny(u8, argument, ",) \t\r\n\x0c") orelse return false;
            const name = argument[0..end];
            if (name.len == 0 or (var_fn and (name.len <= 2 or !starts(name, "--")))) return false;
            for (name) |ch| if (!(std.ascii.isAlphanumeric(ch) or ch == '-' or ch == '_' or ch >= 0x80)) return false;
            if (env_fn) {
                if (std.ascii.isDigit(name[0]) or (name[0] == '-' and (name.len == 1 or std.ascii.isDigit(name[1])))) return false;
                for ([_][]const u8{ "initial", "inherit", "unset", "revert", "revert-layer", "default" }) |reserved| {
                    if (std.ascii.eqlIgnoreCase(name, reserved)) return false;
                }
            }
            var tail = std.mem.trimStart(u8, argument[end..], " \t\r\n\x0c");
            while (env_fn and tail.len != 0 and tail[0] != ',' and tail[0] != ')') {
                const index_end = std.mem.indexOfAny(u8, tail, ",) \t\r\n\x0c") orelse return false;
                const index = tail[0..index_end];
                const digits = if (index.len != 0 and (index[0] == '+' or index[0] == '-')) index[1..] else index;
                if (digits.len == 0) return false;
                for (digits) |digit| if (!std.ascii.isDigit(digit) or (index[0] == '-' and digit != '0')) return false;
                tail = std.mem.trimStart(u8, tail[index_end..], " \t\r\n\x0c");
            }
            if (tail.len == 0 or (tail[0] != ',' and tail[0] != ')')) return false;
            found = true;
        }
        return found and depth == 0 and quote == 0;
    }

    // Resolve static source-profile and inline declarations with the same value
    // grammar. An uncertain winning selector or missing sheet preserves content.
    fn htmlDisplayNone(self: *Renderer, tag: syntax.Tag) Error!bool {
        return self.htmlDisplayNoneIn(tag, null);
    }
    fn htmlDisplayNoneIn(self: *Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement) Error!bool {
        return self.htmlDisplayNoneWithSource(tag, parent, null);
    }
    fn htmlDisplayNoneWithSource(self: *Renderer, tag: syntax.Tag, parent: ?*const table_style_profile.TextElement, inherited: ?Style) Error!bool {
        if (self.tableInlineDisplayVisible(tag, parent)) return false;
        if (self.observedFigureCaptionInlineGeometry(tag)) return false;
        var cascade: table_style_profile.DisplayCascade = .{};
        if (self.context.table_styles) |profile| if (profile.display_rules.len != 0) {
            var rules = profile.displayRules(tag.name,
                (try self.semanticAttribute(tag, "class")) orelse "",
                (try self.semanticAttribute(tag, "id")) orelse "");
            // Generated wiki TABLE names are not slices of the source. Only
            // the live selected parser opening can lend its distant root and
            // complete negative class inventory; it grants no physical edge.
            const wiki_scope = if (tag.is("table") and self.pageStyleWikiOpening(tag) != null and
                self.pageStyleRootForTag(tag, parent) != null) self.pageStyleDomain().?.scope else null;
            const node = if (wiki_scope != null or hasCompleteAncestorClasses(parent) or (parent == null and self.boundedTextClassScopeFor(tag) != null))
                try self.textElement(tag, parent, "") else null;
            rules.complete_ancestor_classes = if (node) |value| (if (wiki_scope) |scope|
                try self.negativePaintQueryClasses(scope.complete_ancestor_class_superset, value)
                else value.complete_ancestor_classes) else null;
            rules.physical_parent_tag = self.physicalDisplayParent(tag);
            var tried_native_source = false;
            while (rules.next()) |rule| {
                // Only an ambiguous rule requiring an ancestor class needs a
                // fresh source query. Its inventory can refute a match only.
                if (!tried_native_source and rules.complete_ancestor_classes == null and
                    rule.uncertain and profile.display_rules[rules.cursor - 1].selector.necessary_ancestor_classes.len != 0)
                {
                    tried_native_source = true;
                    if (inherited) |style| if (self.native_source_class_range != null) {
                        const element = try self.textElement(tag, parent, style.language);
                        const motion = try self.nativeInlineMotionEntry(tag, style.native_inline_motion);
                        var diagnostic: NativeSourceClassQueryDiagnostic = .{};
                        if (try self.nativeSourceClassQueryTokensDiagnosed(tag, profile, element, motion, &diagnostic, false)) |classes| {
                            rules.complete_ancestor_classes = classes;
                            rules.cursor -= 1;
                            continue;
                        }
                        if (self.context.table_viewport_trace and self.document_body_trace)
                            diagnostics.logLine("presentation display class query tag={s} reason={s}", .{tag.name, @tagName(diagnostic.reason)});
                    };
                }
                try self.applyDisplayCss(&cascade, rule.css, rule.specificity, rule.order, rule.uncertain, false);
            }
        };
        if (try self.semanticAttribute(tag, "style")) |css|
            try self.applyDisplayCss(&cascade, css, 0, 0, false, true);
        if (cascade.seen) if (self.context.table_styles) |profile| if (profile.globally_unresolved) {
            // An unavailable import may contain an important override. A known
            // inline important declaration still outranks author stylesheets.
            cascade.consider(null, true, std.math.maxInt(u32), std.math.maxInt(u32), false);
        };
        if (cascade.hidden) |resolved| return resolved;
        self.fallbacks.unsupported_element = true;
        return false;
    }

    fn applyDisplayCss(self: *Renderer, cascade: *table_style_profile.DisplayCascade, css: []const u8, specificity: u32, base_order: u32, uncertain: bool, inline_style: bool) Error!void {
        var pos: usize = 0;
        var order = base_order;
        while (try self.nextColorDeclaration(css, &pos)) |raw| {
            order += 1;
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const property = trim(raw[0..colon]);
            const all = std.ascii.eqlIgnoreCase(property, "all");
            const escaped_property = std.mem.indexOfScalar(u8, property, '\\') != null;
            if (!all and !escaped_property and !std.ascii.eqlIgnoreCase(property, "display")) continue;
            var value = trim(raw[colon + 1 ..]);
            var important = false;
            if (displayPriorityBang(value)) |bang| {
                var priority_buffer: [256]u8 = undefined;
                const priority = displayLiteral(trim(value[bang + 1 ..]), &priority_buffer) orelse continue;
                if (!std.ascii.eqlIgnoreCase(priority, "important")) continue;
                important = true;
                value = trim(value[0..bang]);
            }
            if (escaped_property) {
                cascade.consider(null, important, specificity, order, inline_style);
                continue;
            }
            var substitution = displaySubstitution(value);
            var literal_buffer: [256]u8 = undefined;
            if (!substitution) {
                value = displayLiteral(value, &literal_buffer) orelse continue;
                substitution = displaySubstitution(value);
            }
            if (all) {
                const initial = std.ascii.eqlIgnoreCase(value, "initial") or std.ascii.eqlIgnoreCase(value, "unset");
                const contextual = std.ascii.eqlIgnoreCase(value, "inherit") or std.ascii.eqlIgnoreCase(value, "revert") or std.ascii.eqlIgnoreCase(value, "revert-layer");
                if (!initial and !contextual and !substitution) continue;
                // all expands in place to display's CSS-wide reset. Display
                // is non-inherited, so both initial and unset remove none.
                cascade.consider(if (initial and !uncertain) false else null, important, specificity, order, inline_style);
                continue;
            }
            const none = std.ascii.eqlIgnoreCase(value, "none");
            var supported = none;
            for ([_][]const u8{ "inline", "block", "inline-block", "table", "inline-table", "table-row", "table-cell", "table-row-group", "table-header-group", "table-footer-group", "table-caption", "table-column", "table-column-group", "list-item", "flex", "inline-flex", "grid", "inline-grid", "contents", "flow", "flow-root", "initial", "unset" }) |name| {
                if (std.ascii.eqlIgnoreCase(value, name)) supported = true;
            }
            var unresolved = displayCompoundValid(value) or substitution;
            for ([_][]const u8{ "inherit", "revert", "revert-layer", "run-in", "ruby", "ruby-base", "ruby-text", "ruby-base-container", "ruby-text-container", "math" }) |name| {
                if (std.ascii.eqlIgnoreCase(value, name)) unresolved = true;
            }
            if (supported) {
                cascade.consider(if (uncertain) null else none, important, specificity, order, inline_style);
            } else if (unresolved) {
                // Preserve an explicit unsupported-style diagnostic rather than
                // silently projecting inherited, dynamic or compound display.
                cascade.consider(null, important, specificity, order, inline_style);
            } else continue; // An unknown standalone keyword is invalid CSS.
        }
    }

    // Span capture owns a separate presentation array but deliberately retains
    // reference registries and ordinals. Hidden boxes still participate in the
    // page's citation semantics, including definitions used outside the scope.
    fn consumeHiddenHtml(self: *Renderer, content: []const u8, style: Style, depth: usize) Error!void {
        const tracked = if (self.inline_missing) |parent|
            try missingSlice(self.a, parent, content)
        else if (self.body_missing) |parent|
