    fn literalDivCustomEnvironmentWithTail(self: *Renderer, first: LiteralDivContext,
        parent: ?*const table_style_profile.TextElement, custom: *const table_style_profile.CustomProfile,
        tail: []const syntax.Tag) Error!?table_style_profile.CustomEnvironment
    {
        // Each edge is the existing complete operation/physical-parent receipt.
        // Re-evaluate source declarations; a logical Style palette is not custody.
        if (!self.literalDivParent(first, parent)) return null;
        _ = self.pageStyleDomain() orelse return null;
        const binding = self.source_element_binding orelse return null;
        var openings: [max_depth]syntax.Tag = undefined;
        if (tail.len >= openings.len) return null;
        var count: usize = 0;
        var remaining = tail.len;
        while (remaining != 0) { remaining -= 1; openings[count] = tail[remaining]; count += 1; }
        var known = first;
        var node = parent;
        while (true) {
            if (count == openings.len) return null;
            openings[count] = syntax.tagAt(known.opening, 0) orelse return null;
            count += 1;
            if (known.proof.html_cell_parent != null) {
                const physical = self.literalHtmlCellParent(known, node) orelse return null;
                const live = self.literal_html_cell orelse return null;
                if (physical != live.physical or openings.len - count < live.tags.len) return null;
                var i = live.tags.len;
                while (i != 0) { i -= 1; openings[count] = live.tags[i]; count += 1; }
                break;
            }
            const parent_start = if (known.proof.wiki_cell_parent) |cell| blk: {
                const physical = self.literalWikiCellParent(known, node) orelse return null;
                const live = self.literal_wiki_cell orelse return null;
                if (physical != live.physical_parent or openings.len - count < live.tags.len) return null;
                var i = live.tags.len;
                while (i != 0) { i -= 1; openings[count] = live.tags[i]; count += 1; }
                node = live.outer_parent;
                break :blk cell.parent_start orelse break;
            } else known.proof.parent_start orelse break;
            const current = node orelse return null;
            const anchor = current.page_style_anchor orelse return null;
            const parent_tag = syntax.tagAt(anchor, 0) orelse return null;
            const fresh = self.literalDivContextForTrackedTag(parent_tag, binding.owner) orelse return null;
            if (fresh.proof != current.source_literal_div or fresh.proof.range.anchor_start != parent_start or
                parent_start >= known.proof.range.anchor_start) return null;
            known = fresh;
            node = current.parent;
