            const css = (try self.semanticAttribute(tag, "style")) orelse "";
            left = try custom.element(self.a, left, element, css);
            right = try custom.element(self.a, right, element, css);
        }
        return try table_style_profile.intersectCustomEnvironmentsAlloc(self.a, left, right);
    }

    fn customElement(self: *Renderer, tag: syntax.Tag, inherited: Style) Error!?table_style_profile.CustomEnvironment {
        if (self.tableParentContainerElement(tag, inherited.text_element) != null)
            return self.table_parent_container_operation.?.observation.environment;
        if (self.tableInlineSourceForTag(tag)) |known| return known.environment.?;
        const profile = self.context.table_styles orelse return null;
        const custom = profile.custom_properties orelse return null;
        if (!custom.appliesTo(self.context.title)) return null;
        if (self.literalRootWikiTableTag(tag, inherited.text_element) != null)
            return (try self.literalCustomEnvironmentFromRoot(custom, &.{tag})) orelse .{};
        if (try self.literalRootWikiRow(tag, inherited.text_element)) |row| {
