            const live = self.literal_wiki_cell_style.?;
            if (live.proof.parent_start == null) {
                const reversed = [_]syntax.Tag{ live.tags[3], live.tags[2], live.tags[1], live.tags[0] };
                return (try self.literalCustomEnvironmentFromRoot(custom, &reversed)) orelse .{};
            }
            const binding = self.source_element_binding orelse return .{};
            const outer_tag = syntax.tagAt(live.outer_parent.page_style_anchor orelse return .{}, 0) orelse return .{};
            const outer = self.literalDivContextForTrackedTag(outer_tag, binding.owner) orelse return .{};
            return (try self.literalDivCustomEnvironmentWithTail(outer, live.outer_parent.parent, custom, &live.tags)) orelse .{};
        }
