        const result = table_style_profile.resolveObservedRootTableContainingDirection(self.a,
            retained.observation.contexts, retained.native_direction, expected_style, retained.observation.parents.len == 1)
            catch |err| return self.authoredElementQueryError(err);
        if (result == null) self.traceRootTableDirectionRefusal("captured_query", opening, parent_style);
        return result;
    }

    fn traceRootTableDirectionRefusal(self: *const Renderer, stage: []const u8, opening: []const u8, parent_style: Style) void {
        if (!self.context.table_viewport_trace) return;
        var title_buffer: [128]u8 = undefined;
        var opening_buffer: [256]u8 = undefined;
        var direction_buffer: [64]u8 = undefined;
        const parent = parent_style.text_element;
        const binding = self.table_direction_binding;
        const owner_offset: ?usize = if (binding) |held|
            if (wikiClassContains(held.owner.bytes, opening)) @intFromPtr(opening.ptr) - @intFromPtr(held.owner.bytes.ptr) else null
        else null;
        diagnostics.logLine("presentation table_root_direction_refusal stage={s} renderer=0x{x} title_hex={s} opening_hex={s} opening_bytes={d} opening_truncated={any} owner_offset={any} binding={any} parent={any} parent_has_parent={any} parent_source_key={any} native_direction_hex={s} content_root={s} observe_structure_only={any} rejection_probe_scope={any} body_depth={d} table_depth={d}", .{
            stage, @intFromPtr(self), boundedTraceHex(&title_buffer, self.context.title),
            boundedTraceHex(&opening_buffer, opening), opening.len, opening.len > opening_buffer.len / 2,
            owner_offset, binding != null, parent != null,
            if (parent) |element| @as(?bool, element.parent != null) else null,
            if (parent) |element| @as(?usize, element.source_key) else null,
            boundedTraceHex(&direction_buffer, parent_style.captured_direction orelse parent_style.direction),
            @tagName(self.content_root), self.context.observe_structure_only, self.rejection_probe_scope, self.body_depth, self.typed_table_depth,
        });
    }

    fn tableRootNativeObservation(self: *Renderer, opening: []const u8, parent_style: Style) Error!?TableViewportNativeObservation {
        const selected = self.tableDirectionSource() orelse { self.traceRootTableDirectionRefusal("selected_source", opening, parent_style); return null; };
        if (!selected.root_only) { self.traceRootTableDirectionRefusal("root_only", opening, parent_style); return null; }
        if (self.typed_table_depth > 1) { self.traceRootTableDirectionRefusal("table_depth", opening, parent_style); return null; }
        const original = self.tableDirectionOriginal(opening) orelse { self.traceRootTableDirectionRefusal("original_opening", opening, parent_style); return null; };
        const offset = @intFromPtr(original.ptr) - @intFromPtr(selected.source.ptr);
        const observation = (try selected.observe(selected.context, self.a, selected.source, offset)) orelse { self.traceRootTableDirectionRefusal("source_callback", opening, parent_style); return null; };
        if (observation.contexts.len == 0) { self.traceRootTableDirectionRefusal("captured_contexts", opening, parent_style); return null; }
        if (observation.parents.len == 0) {
            if (parent_style.text_element != null) { self.traceRootTableDirectionRefusal("unexpected_native_parent", opening, parent_style); return null; }
        } else {
            // Only the independently observed plain aligned DIV is represented
            // here. Extra, styled, generated or unrelated ancestors remain unknown.
            if (observation.parents.len != 1) { self.traceRootTableDirectionRefusal("captured_parent_count", opening, parent_style); return null; }
            const opening_tag = syntax.tagAt(observation.parents[0], 0) orelse { self.traceRootTableDirectionRefusal("captured_parent_opener", opening, parent_style); return null; };
            if (!opening_tag.is("div") or opening_tag.closing or opening_tag.self_closing or
                opening_tag.end != observation.parents[0].len or
                !try self.observedWikiOwnAttributesEqual(opening_tag.attrs, .{ .tag = "div", .parent = null,
                    .attributes = &.{.{ .name = "align", .value = "center" }} })) { self.traceRootTableDirectionRefusal("captured_parent_shape", opening, parent_style); return null; }
            const parent = parent_style.text_element orelse { self.traceRootTableDirectionRefusal("missing_native_parent", opening, parent_style); return null; };
            if (parent.parent != null or !std.ascii.eqlIgnoreCase(parent.tag, "div")) { self.traceRootTableDirectionRefusal("native_parent_shape", opening, parent_style); return null; }
            const original_name = self.tableDirectionParentName(parent) orelse { self.traceRootTableDirectionRefusal("native_parent_source", opening, parent_style); return null; };
            if (original_name.ptr != opening_tag.name.ptr or original_name.len != opening_tag.name.len) { self.traceRootTableDirectionRefusal("parent_occurrence", opening, parent_style); return null; }
        }
        var known: ?presentation_types.TableContainingDirection = null;
        const native_direction = parent_style.captured_direction orelse parent_style.direction;
        if (native_direction.len != 0) {
            if (std.mem.eql(u8, native_direction, "ltr")) known = .ltr
            else if (std.mem.eql(u8, native_direction, "rtl")) known = .rtl
            else { self.traceRootTableDirectionRefusal("native_direction", opening, parent_style); return null; }
        }
        return .{ .observation = observation, .native_direction = known };
    }

    const CellNativeContext = struct {
        style: Style,
        formatting: SpanFlags,
        inherited_height: ?presentation_types.CellLineHeightValue = null,
