        if (image.font) |prior| if (!tableNestedFontOwnersAgree(prior, owner)) return false;
        const direction = (table_style_profile.resolveObservedTablePrefixImageDirectionWithMinimumProof(self.a, source.context,
            image.subjects, viewport, source.proof, minimum)
            catch |err| return self.authoredElementQueryError(err)) orelse return false;
        const box = (table_style_profile.resolveObservedTablePrefixInlineImageBoxWithProof(self.a, source.context, image.subjects,
            viewport, owner.font.font_scale orelse return false, owner.font.font_scale_basis, direction,
            @intCast(image.image.width_px orelse return false), source.proof) catch |err| return self.authoredElementQueryError(err)) orelse return false;
        if (image.box) |prior| if (!sameFigurePreparationValue(prior, box)) return false;
