            diagnostics.logLine("presentation table_prefix_image_refusal stage={s} title_hex={s} token_hex={s} token_bytes={d} token_truncated={any}",
                .{ stage, boundedTraceHex(&title_hex, self.context.title), boundedTraceHex(&token_hex, raw), raw.len, raw.len > token_hex.len / 2 });
        }
        return error.UncompiledPresentation;
    }
    fn tablePrefixImageChoice(self: *Renderer, raw: []const u8, original: Style,
        ordinary: ImageChoice) Error!?struct { style: Style, image: ImageChoice }
    {
        const scope = self.table_viewport_cell_source orelse return null;
        const mapped = self.tableLinkOriginalIn(raw, self.table_link_quote_source, 0) orelse return self.tablePrefixImageRefusal("source_map", raw);
        if (!scope.closed_focus or !wikiClassContains(scope.source, mapped)) return self.tablePrefixImageRefusal("closed_cell", raw);
        for (scope.links) |binding| {
            if (binding.token.ptr != mapped.ptr or binding.token.len != mapped.len) continue;
            const proof = binding.prefix_image orelse return self.tablePrefixImageRefusal("image_proof", raw);
            const owner = proof.font orelse return self.tablePrefixImageRefusal("font_proof", raw);
            const box = proof.box orelse return self.tablePrefixImageRefusal("box_proof", raw);
            const cell_owner = scope.prefix_font_owner orelse return self.tablePrefixImageRefusal("cell_font_owner", raw);
            if (!sameFigurePreparationValue(owner.font, cell_owner.font) or
                !sameFigurePreparationValue(owner.height, cell_owner.height)) return self.tablePrefixImageRefusal("font_identity", raw);
            var expected = proof.image; expected.vertical_align = null;
            var actual = ordinary.image; actual.file = (try self.resolvedMediaFile(actual.file)) orelse return self.tablePrefixImageRefusal("resolved_file", raw);
            if (ordinary.nonfloating or ordinary.alignment != null or !sameFigurePreparationValue(expected, actual)) return self.tablePrefixImageRefusal("ordinary_image", raw);
            const action = (try self.tableLinkStyle(original, .{ .target = binding.target }, raw)) orelse return self.tablePrefixImageRefusal("link_style", raw);
            var style = tableNestedOwnerStyle(action, owner);
            const focus = proof.focus orelse return self.tablePrefixImageRefusal("focus_proof", raw);
            const paint = binding.paint orelse return self.tablePrefixImageRefusal("paint_proof", raw);
            if (!sameFigurePreparationValue(focus.paint, paint)) return self.tablePrefixImageRefusal("paint_identity", raw);
            style.link_paint = focus.output();
            var chosen = ordinary; chosen.image = proof.image;
            if (chosen.image.vertical_align != box.alignment) return self.tablePrefixImageRefusal("vertical_align", raw);
            return .{ .style = style, .image = chosen };
        }
        return self.tablePrefixImageRefusal("binding_absent", raw);
    }

    fn tablePrefixImageBindingsAgree(left: ?TablePrefixImageBinding, right: ?TablePrefixImageBinding) bool {
        const first = left orelse return right == null;
        const second = right orelse return false;
        return sameFigurePreparationValue(first.image, second.image) and sameFigurePreparationValue(first.box, second.box) and
            sameFigurePreparationValue(first.focus, second.focus) and tableNestedFontOwnersAgree(first.font, second.font);
    }
