                var visible_text: std.ArrayList(u8) = .empty;
                var text_runs: std.ArrayList(IntrinsicTableSourceTextRun) = .empty;
                const source_body = source[cell.body_start..cell.body_end];
                // Parser.php's table pass trims initial cell data before HTML
                // parsing. Keep the full source receipt; only this single-line
                // ASCII-space view participates in the intrinsic identity join.
                // Continuation lines, tabs/CR and recursive inline gaps keep the
                // maintained strict source-body path unchanged.
                const identity_body = if (intrinsic and std.mem.indexOfAny(u8, source_body, "\t\r\n") == null)
                    std.mem.trim(u8, source_body, " ") else source_body;
                if (!try self.tableLinkSourceBodyWithFamily(identity_body, context.nodes,
                    mapping[cell.node], index, &links, 0, false, boundary_line_feed, prefix_media, intrinsic,
                    if (intrinsic) &visible_text else null, if (intrinsic) &text_runs else null, if (prefix_media) &entity_bindings else null,
                    if (prefix_media) &inline_fonts else null, "")) { traceIntrinsicIdentityRefusal(self.context, intrinsic, "identity.cell_body", scope.table, null, 0, source, null, null, null); return null; }
                if (intrinsic) try text_cells.append(self.a, .{ .subject = mapping[cell.node],
                    .source_body = source[cell.body_start..cell.body_end], .text = try visible_text.toOwnedSlice(self.a),
                    .text_runs = try text_runs.toOwnedSlice(self.a) });
            }
        }
        return .{ .context = context, .links = try links.toOwnedSlice(self.a), .literal_grids = try grids.toOwnedSlice(self.a),
            .cells = try text_cells.toOwnedSlice(self.a), .entities = try entity_bindings.toOwnedSlice(self.a),
            .inline_fonts = try inline_fonts.toOwnedSlice(self.a) };
    }

    fn tableLinkSourceIn(self: *Renderer, graph: TableViewportSourceGraph, source: []const u8,
        scope: table_style_profile.TableContainingDirectionContext,
        query_scope: table_style_profile.TableContainingDirectionContext,
        contexts: []const table_style_profile.TableContainingDirectionContext, comptime captured_viewport: bool) Error!?TableLinkSource
    {
        const intrinsic = scope.intrinsic_viewport;
        const identity = (try self.tableLinkSourceIdentity(graph, source, scope, query_scope, contexts, captured_viewport, intrinsic)) orelse return null;
        const context = identity.context;
        const prefix_media = scope.generated_prefix_section != null;
        const actions = try self.a.alloc(u32, identity.links.len);
        for (identity.links, actions) |binding, *action| action.* = binding.subject;
        var media: std.ArrayList(table_style_profile.TablePrefixMediaSubject) = .empty;
        defer media.deinit(self.a);
        for (identity.links) |binding| if (binding.prefix_image) |image| try media.append(self.a, image.subjects);
        var proof = ((if (prefix_media) table_style_profile.observedTablePrefixLinkPaintProofWithMediaAndEntities(self.a, context, query_scope, source, actions, media.items, identity.entities)
            else (if (captured_viewport) table_style_profile.observedTableLinkPaintProofWithViewportActions else table_style_profile.observedTableLinkPaintProofWithSourceActions)(self.a, context, query_scope, source, actions))
            catch |err| return self.authoredElementQueryError(err)) orelse return null;
        if (captured_viewport and !prefix_media and !intrinsic) {
            // Identity above closed the complete original source against every
            // captured cell/inline child/action. A shallow intake alone cannot
            // lend static pseudo absence to the source-derived query graph.
            if (query_scope.nodes.ptr != graph.nodes.ptr or query_scope.nodes.len != graph.nodes.len) return null;
            proof = (try proof.withJoinedCapturedSource(self.a, source, context, query_scope)) orelse return null;
        }
        return .{ .context = context, .proof = proof, .links = identity.links,
            .literal_grids = identity.literal_grids, .entities = identity.entities, .inline_fonts = identity.inline_fonts };
    }

    pub const IntrinsicTableSourceTextRun = struct {
        subject: u32,
        previous_child: ?u32,
        next_child: ?u32,
        text: []const u8,
    };
    pub const IntrinsicTableSourceCellIdentity = struct {
        subject: u32,
        source_body: []const u8,
        text: []const u8,
        text_runs: []const IntrinsicTableSourceTextRun,
    };
    const TableLinkIdentity = struct {
        context: table_style_profile.TableContainingDirectionContext,
        links: []TableSourceLink,
        literal_grids: []const TableLiteralSourceGrid,
        cells: []const IntrinsicTableSourceCellIdentity,
        entities: []const table_style_profile.TablePrefixEntitySubject,
        inline_fonts: []TableInlineSourceFont,
    };

    fn tableIntrinsicWikiAnchorMatches(self: *Renderer, expected: []const u8,
        actual: table_style_profile.ObservedStyleNode) Error!bool
    {
        if (!starts(expected, "/wiki/") or std.mem.indexOfAny(u8, expected, "?#") != null) return false;
        const class = tableViewportNodeAttribute(actual, "class");
        const redlink = if (class) |value| std.mem.eql(u8, value, "new") else false;
        if (class != null and !redlink) return false;
        var href_count: usize = 0; var title_count: usize = 0; var class_count: usize = 0;
        for (actual.attributes) |attribute| {
            if (std.ascii.eqlIgnoreCase(attribute.name, "href")) href_count += 1
            else if (std.ascii.eqlIgnoreCase(attribute.name, "title")) {
                if (attribute.value.len == 0) return false;
                title_count += 1;
            } else if (std.ascii.eqlIgnoreCase(attribute.name, "class")) class_count += 1
            else return false;
        }
        if (href_count != 1 or title_count != 1 or class_count != @as(usize, @intFromBool(redlink))) return false;
        const actual_href = tableViewportNodeAttribute(actual, "href") orelse return false;
        const prefix = "/w/index.php?title=";
        const suffix = "&action=edit&redlink=1";
        const actual_title = if (redlink) blk: {
            if (!starts(actual_href, prefix) or !std.mem.endsWith(u8, actual_href, suffix) or
                actual_href.len <= prefix.len + suffix.len) return false;
            const title = actual_href[prefix.len .. actual_href.len - suffix.len];
            if (std.mem.indexOfAny(u8, title, "&#?+") != null) return false;
            break :blk title;
        } else blk: {
            if (!starts(actual_href, "/wiki/") or std.mem.indexOfAny(u8, actual_href, "?#") != null) return false;
            break :blk actual_href["/wiki/".len..];
        };
        const expected_title = expected["/wiki/".len..];
        for ([_][]const u8{ expected_title, actual_title }) |value| {
            var at: usize = 0;
            while (at < value.len) : (at += 1) if (value[at] == '%') {
                if (value.len - at < 3 or !std.ascii.isHex(value[at + 1]) or !std.ascii.isHex(value[at + 2])) return false;
                at += 2;
            };
        }
        const one = std.Uri.percentDecodeInPlace(try self.a.dupe(u8, expected_title));
        const two = std.Uri.percentDecodeInPlace(try self.a.dupe(u8, actual_title));
        return std.unicode.utf8ValidateSlice(two) and std.mem.eql(u8, one, two);
    }

    fn intrinsicTableRectangular(graph: TableViewportSourceGraph) bool {
        if (!graph.intrinsic or graph.row_count == 0 or graph.cells.len == 0) return false;
        var row: usize = 0; var count: usize = 0; var width: ?usize = null;
        for (graph.cells) |cell| {
            if (cell.colspan != 1 or cell.rowspan != 1 or cell.needs_nested_source) return false;
            if (cell.row != row) {
                if (cell.row != row + 1 or count == 0 or (width != null and width.? != count)) return false;
                width = count; row = cell.row; count = 0;
            }
            count += 1;
        }
        return row + 1 == graph.row_count and count != 0 and (width == null or width.? == count);
    }

    // Book uses the same complete source grid/A walker to establish an
    // occurrence bijection before any CSS can select a winner. The returned
    // cell texts must also match the retained captured cell bodies; this does
    // not grant styles, focus, native context or viewport geometry.
    fn traceIntrinsicIdentityRefusal(context: Context, enabled: bool, comptime stage: []const u8,
        subject: ?u32, cell: ?usize, depth: usize, body: []const u8,
        source_text: ?bool, captured_text: ?bool, boundary_lf: ?bool) void
    {
        if (!@import("builtin").is_test or !enabled or !context.table_viewport_trace) return;
        var buffer: [320]u8 = undefined;
        std.debug.print("KU_INTRINSIC_DETAIL stage={s} subject={any} cell={any} depth={d} body_bytes={d} body_hex={s} body_truncated={any} source_has_text={any} captured_has_text={any} boundary_lf={any}\n", .{
            stage, subject, cell, depth, body.len, boundedTraceHex(&buffer, body),
            body.len > buffer.len / 2, source_text, captured_text, boundary_lf,
        });
    }

    pub fn intrinsicTableIdentityAlloc(a: A, source: []const u8, opening: usize,
        context: Context, full: table_style_profile.TableContainingDirectionContext) Error!?[]const IntrinsicTableSourceCellIdentity
    {
        if (source.len > 4 * 1024 * 1024 or opening >= source.len or
            (opening != 0 and source[opening - 1] != '\n') or !starts(source[opening..], "{|") or
            !full.intrinsic_viewport or full.table >= full.nodes.len or full.root >= full.table or
            full.nodes[full.table].parent != full.root) { traceIntrinsicIdentityRefusal(context, true, "entry.input_scope", full.table, null, 0, source, null, null, null); return null; }
        var renderer: Renderer = .{ .a = a, .context = context };
        const end = std.mem.indexOfScalarPos(u8, source, opening, '\n') orelse { traceIntrinsicIdentityRefusal(context, true, "entry.opening_line", full.table, null, 0, source, null, null, null); return null; };
        const raw = std.mem.trimEnd(u8, source[opening + 2 .. end], "\r");
        const attrs = try renderer.wikiTableViewAttrs(raw);
        const tag: syntax.Tag = .{ .name = "table", .attrs = attrs, .end = end, .closing = false, .self_closing = false };
        const inventory = (try renderer.tableViewportAttributes(tag)) orelse { traceIntrinsicIdentityRefusal(context, true, "entry.opening_attributes", full.table, null, 0, source, null, null, null); return null; };
        if (!tableLinkAttributesEqual(inventory, full.nodes[full.table].attributes) or
            table_style_profile.observedIntrinsicTableGeometry(full) == null) { traceIntrinsicIdentityRefusal(context, true, "entry.opening_identity_or_geometry", full.table, null, 0, source, null, null, null); return null; }
        const nodes = try a.alloc(table_style_profile.ObservedStyleNode, full.root + 2);
        @memcpy(nodes[0 .. full.root + 1], full.nodes[0 .. full.root + 1]);
        nodes[full.root + 1] = full.nodes[full.table];
        nodes[full.root + 1].known_previous_element_sibling = null;
        nodes[full.root + 1].known_next_element_sibling = null;
        nodes[full.root + 1].known_no_previous_element_sibling = false;
        nodes[full.root + 1].known_no_next_element_sibling = false;
        const shallow: table_style_profile.TableContainingDirectionContext = .{ .intrinsic_viewport = true,
            .styles = full.styles, .nodes = nodes, .root = full.root, .table = full.root + 1 };
        const graph = (try renderer.tableViewportWikiGraphWithFamily(source, opening, shallow, false, false, true)) orelse { traceIntrinsicIdentityRefusal(context, true, "entry.source_graph", full.table, null, 0, source, null, null, null); return null; };
        if (!intrinsicTableRectangular(graph)) { traceIntrinsicIdentityRefusal(context, true, "entry.rectangular_grid", full.table, null, 0, source, null, null, null); return null; }
        const query: table_style_profile.TableContainingDirectionContext = .{ .intrinsic_viewport = true,
            .styles = full.styles, .nodes = graph.nodes, .root = graph.root, .table = graph.table };
        const identity = (try renderer.tableLinkSourceIdentity(graph, source, shallow, query, &.{full}, true, true)) orelse { traceIntrinsicIdentityRefusal(context, true, "entry.source_identity", full.table, null, 0, source, null, null, null); return null; };
        return identity.cells;
    }

    // Recomputed custom bindings are owned values, not borrowed identity.
    // Keep every other Style field (including paint and source pointers) exact.
    fn tableLinkFontStyleEqual(left: ?Style, right: ?Style) bool {
        const first = left orelse return right == null;
        const second = right orelse return false;
        if (!tableViewportEnvironmentEqual(first.custom_properties, second.custom_properties)) return false;
        var one = first; var two = second;
        one.custom_properties = null; two.custom_properties = null;
        return sameFigurePreparationValue(one, two);
    }

    fn tableLinkFont(self: *Renderer, computed: table_style_profile.AuthoredElementComputedContext,
        context: table_style_profile.TableContainingDirectionContext) Error!?struct { own: Style, parent: Style }
    {
        var value: Style = .{ .font_scale = 1, .font_scale_basis = .normal_body, .font_scale_set = true };
        var parent: ?Style = null; var root_font: ?AuthoredRuleRelativeFontSize = null;
        for (computed.nodes) |node| {
            if (node.index >= context.nodes.len) return null;
            const tag = context.nodes[node.index].tag;
            if (oneOf(tag, &.{ "small", "big", "sup", "sub", "code", "pre", "font", "u", "s", "h1", "h2", "h3", "h4", "h5", "h6" })) return null;
            if (node.index == computed.element) parent = value;
            const initial: AuthoredRuleRelativeFontSize = .{ .value = 1, .basis = .normal_body };
            const metric = (try self.authoredRuleComputedFontSize(node.font_size orelse .inherit,
                value, true, if (node.index == 0) initial else root_font)) orelse return null;
            if (metric.unknown or metric.basis != .normal_body) return null;
            if (node.index == 0) root_font = metric;
            value.font_scale = metric.value; value.font_scale_basis = metric.basis;
            value.font_features = node.font_features;
            value.custom_properties = node.environment;
            if (node.paint.weight) |weight| switch (weight) {
                .inherit => {}, .value => |known| value.bold = known, .unknown => return null,
            } else if (oneOf(tag, &.{ "b", "strong", "th" })) value.bold = true;
            if (node.paint.font_style) |font_style| switch (font_style) {
                .inherit => {}, .value => |known| value.italic = known, .unknown => return null,
            } else if (oneOf(tag, &.{ "i", "em" })) value.italic = true;
        }
        return .{ .own = value, .parent = parent orelse return null };
    }

    fn tableLinkPaintAtViewport(self: *Renderer, source: *TableLinkSource, viewport: f64) Error!bool {
        return self.tableLinkPaintAtViewportWithMinimum(source, viewport, null);
    }

    fn tableLinkPaintAtViewportWithMinimum(self: *Renderer, source: *TableLinkSource, viewport: f64, minimum: ?table_style_profile.TableInlineMinimumProof) Error!bool {
        var inline_seen: [128]bool = @splat(false);
        if (source.inline_fonts.len > inline_seen.len) return false;
        const seen_owners = inline_seen[0..source.inline_fonts.len];
        if (source.entities.len != 0 and !(table_style_profile.observedTablePrefixEntitiesNeutralAtViewport(self.a, source.proof, viewport)
            catch |err| return self.authoredElementQueryError(err))) return false;
        for (source.links) |*binding| {
            const context = source.context;
            const typed_wrap = context.generated_prefix_section == null and !context.intrinsic_viewport;
            const computed = (if (typed_wrap)
                (table_style_profile.resolveObservedTableInlineTextWithWrapProof(self.a, context, binding.subject, binding.subject, viewport, source.proof)
                    catch |err| return self.authoredElementQueryError(err))
                else (table_style_profile.resolveObservedTableInlineTextWithMinimumProof(self.a, context, binding.subject, binding.subject, viewport, source.proof, minimum)
                    catch |err| return self.authoredElementQueryError(err))) orelse return false;
            var font = (try self.tableLinkFont(computed, context)) orelse return false;
            if (context.generated_prefix_section != null or context.intrinsic_viewport) {
                const metrics = (table_style_profile.resolveObservedNestedTableNodeFontMetrics(self.a, context,
                    binding.subject, null, viewport, null) catch |err| return self.authoredElementQueryError(err)) orelse return false;
                const owner = (try self.tableNestedFoldFontMetrics(context, metrics)) orelse return false;
                if (!try self.tableInlineFontsFromMetrics(source, metrics, computed, seen_owners)) return false;
                if (binding.prefix_font_owner) |prior| if (!tableNestedFontOwnersAgree(prior, owner)) return false;
                binding.prefix_font_owner = owner;
                font.own = tableNestedOwnerStyle(font.own, owner);
                var parent = owner; parent.font = owner.parent_font;
                font.parent = tableNestedOwnerStyle(font.parent, parent);
            }
            if (binding.font) |prior| { if (!tableLinkFontStyleEqual(prior, font.own) or
                !tableLinkFontStyleEqual(binding.parent_font.?, font.parent)) return false; }
            var agreed: ?presentation_types.LinkPaint = null;
            for (context.nodes, 0..) |node, index| {
                if (!tableLinkDescendant(context.nodes, @intCast(index), binding.subject) or node.has_text != true) continue;
                const paint = if (typed_wrap) checked: {
                    const result = (table_style_profile.resolveObservedTableLinkPaintWithWrap(self.a, source.proof,
                        binding.subject, @intCast(index), viewport, font.own.font_scale orelse 1)
                        catch |err| return self.authoredElementQueryError(err)) orelse return false;
                    // A single source A may contain multiple emitted text runs.
                    // Until per-child ownership is represented, divergent child
                    // or state wrapping stays refused rather than flattened.
                    if (result.wrap != computed.inline_wrap) return false;
                    break :checked result.paint;
                } else (table_style_profile.resolveObservedTableLinkPaint(self.a, source.proof,
                    binding.subject, @intCast(index), viewport, font.own.font_scale orelse 1)
                    catch |err| return self.authoredElementQueryError(err)) orelse return false;
                if (agreed) |prior| { if (!sameFigurePreparationValue(prior, paint)) return false; } else agreed = paint;
            }
            if (binding.prefix_image) |*image| {
                const focus = (table_style_profile.resolveObservedTablePrefixImageFocusWithMinimum(self.a, context, image.subjects,
                    viewport, font.own.font_scale orelse 1, source.proof, minimum)
                    catch |err| return self.authoredElementQueryError(err)) orelse return false;
                if (image.focus) |prior| if (!sameFigurePreparationValue(prior, focus)) return false;
                image.focus = focus; agreed = focus.paint;
            }
            const paint = agreed orelse return false;
            if (binding.paint) |prior| { if (!sameFigurePreparationValue(prior, paint)) return false; }
            if (binding.wrap_checked and binding.wrap != computed.inline_wrap) return false;
            binding.wrap = computed.inline_wrap; binding.wrap_checked = true;
            binding.paint = paint; binding.font = font.own; binding.parent_font = font.parent;
            if (!try self.tablePrefixImageAtViewportWithMinimum(source, binding, viewport, minimum)) return false;
        }
        for (source.inline_fonts, 0..) |binding, index| {
            if (seen_owners[index]) continue;
            // A format-only run need not be an A ancestor. Its own complete
            // query is authorized only by this viewport's existing minimum
            // proof, and supplies font and paint in the same traversal.
            const permit = minimum orelse {
                // A prior sample is not this invocation's authorization.
                if (binding.owner != null or binding.paint != null or binding.environment != null or binding.display_hidden != null) return false;
                continue;
            };
            const computed = (table_style_profile.resolveObservedTableInlineOwnerWithMinimumProof(self.a, source.context,
                binding.subject, viewport, source.proof, permit) catch |err| return self.authoredElementQueryError(err)) orelse return false;
            const metrics = try self.tableInlineMetricsFromText(computed);
            defer self.a.free(metrics.nodes);
            if (!try self.tableInlineFontsFromMetrics(source, metrics, computed, seen_owners)) return false;
            if (!seen_owners[index]) return false;
        }
        return true;
    }

    fn tableLinkTokenMatches(self: *const Renderer, scope: TableViewportCellScope,
        binding: TableSourceLink, mapped: []const u8) bool
    {
        if (binding.token.ptr == mapped.ptr and binding.token.len == mapped.len) return true;
        // Ordinary emission asks for the core [[...]] token, then paints its
        // language-selected trail with that same action. The captured binding
        // retains the complete occurrence; only its proved intrinsic scope may
        // use this exact suffix relation, under the current parser callback.
        if (!scope.captured_intrinsic_content or scope.source_constructed or
            binding.external or binding.prefix_image != null or binding.token.ptr != mapped.ptr or
            binding.token.len <= mapped.len or !wikiClassContains(scope.source, binding.token)) return false;
        var iterator: ir.InlineIterator = .{ .input = binding.token,
            .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const parsed = iterator.next() orelse return false;
        return parsed.kind == .link and !parsed.link_empty_label and !parsed.link_label_restored_close and
            iterator.cursor == binding.token.len and parsed.trail.len != 0 and
            mapped.len == binding.token.len - parsed.trail.len;
    }

    // Failure-only diagnostics for the existing strict source/native action
    // guard. The mask does not decide admission and is evaluated only after
    // the unchanged rejecting predicate, under the existing explicit opt-in.
    fn tableLinkParentRefusalMask(self: *const Renderer, original: Style, parent: Style) u32 {
        if (!self.context.table_viewport_trace) return 0;
        const failed = [_]bool{
            original.font_size_unknown, original.code, original.small, original.superscript,
            original.subscript, original.strike, original.underline, original.heading,
            self.block_formatting.code, self.block_formatting.small, self.block_formatting.superscript,
            self.block_formatting.subscript, self.block_formatting.strike, self.block_formatting.underline,
            original.font_scale_basis != parent.font_scale_basis, original.font_scale != parent.font_scale,
            (original.bold or self.block_formatting.bold) != parent.bold,
            (original.italic or self.block_formatting.italic) != parent.italic,
            !sameFigurePreparationValue(original.font_features, parent.font_features),
        };
        var mask: u32 = 0;
        for (failed, 0..) |value, bit| if (value) { mask |= @as(u32, 1) << @intCast(bit); };
        return mask;
    }
    fn tableLinkStyleRefusal(self: *const Renderer, stage: []const u8, mask: u32, original: Style,
        parent: ?Style, subject: u32, action_index: usize, token_bytes: usize,
        link_count: usize, seen_count: ?usize) Error
    {
        if (!self.context.table_viewport_trace) return error.UncompiledPresentation;
        var title_buffer: [128]u8 = undefined;
        const own_features = if (original.font_features) |value| @tagName(value) else "absent";
        const parent_features = if (parent) |value| if (value.font_features) |features|
            @tagName(features) else "absent" else "no_parent";
        diagnostics.logLine("presentation table_link_style_refusal stage={s} mask=0x{x} subject={d} action_index={d} token_bytes={d} link_count={d} seen_count={any} title_hex={s} parent_present={any} original_scale={any} original_basis={s} parent_scale={any} parent_basis={s} original_bold={any} parent_bold={any} original_italic={any} parent_italic={any} original_features={s} parent_features={s}", .{
            stage, mask, subject, action_index, token_bytes, link_count, seen_count,
            boundedTraceHex(&title_buffer, self.context.title), parent != null,
            original.font_scale, @tagName(original.font_scale_basis), if (parent) |value| value.font_scale else null,
            if (parent) |value| @tagName(value.font_scale_basis) else "absent",
            original.bold, if (parent) |value| value.bold else false,
            original.italic, if (parent) |value| value.italic else false, own_features, parent_features,
        });
        return error.UncompiledPresentation;
    }

    fn tableLinkStyle(self: *Renderer, original: Style, destination: LinkDestination, token: ?[]const u8) Error!?Style {
        const scope = self.table_viewport_cell_source orelse return null;
        if (scope.links.len == 0) return null;
        const source = token orelse return null;
        if (self.inline_missing) |tracked| if ((!wikiClassCleanText(tracked) and !self.selectedTableSourceRange(tracked, source)) or
            !wikiClassContains(tracked.bytes, source)) return null;
        const mapped = self.tableLinkOriginalIn(source, self.table_link_quote_source, 0) orelse return null;
        if (!wikiClassContains(scope.source, mapped) or self.figure_caption_depth != 0 or self.observed_figure_caption != null or
            original.image != null or original.self_link_target != null) return null;
        for (scope.links, 0..) |binding, action_index| {
            if (!self.tableLinkTokenMatches(scope, binding, mapped)) continue;
            if (destination.external != binding.external or
                !std.mem.eql(u8, trim(destination.target), trim(binding.target)))
                return self.tableLinkStyleRefusal("destination", if (self.context.table_viewport_trace)
                    @as(u32, @intFromBool(destination.external != binding.external)) |
                    (@as(u32, @intFromBool(!std.mem.eql(u8, trim(destination.target), trim(binding.target)))) << 1) else 0,
                    original, null, binding.subject, action_index, mapped.len, scope.links.len,
                    if (scope.actions_seen) |seen| seen.len else null);
            const font = binding.font orelse
                return self.tableLinkStyleRefusal("binding_font", 1, original, null, binding.subject,
                    action_index, mapped.len, scope.links.len, if (scope.actions_seen) |seen| seen.len else null);
            const parent = binding.parent_font orelse
                return self.tableLinkStyleRefusal("binding_parent", 2, original, null, binding.subject,
                    action_index, mapped.len, scope.links.len, if (scope.actions_seen) |seen| seen.len else null);
            if (original.font_size_unknown or original.code or original.small or original.superscript or original.subscript or
                original.strike or original.underline or original.heading or self.block_formatting.code or
                self.block_formatting.small or self.block_formatting.superscript or self.block_formatting.subscript or
                self.block_formatting.strike or self.block_formatting.underline or
                original.font_scale_basis != parent.font_scale_basis or original.font_scale != parent.font_scale or
                (original.bold or self.block_formatting.bold) != parent.bold or
                (original.italic or self.block_formatting.italic) != parent.italic or
                !sameFigurePreparationValue(original.font_features, parent.font_features))
                return self.tableLinkStyleRefusal("parent_style", self.tableLinkParentRefusalMask(original, parent),
                    original, parent, binding.subject, action_index, mapped.len, scope.links.len,
                    if (scope.actions_seen) |seen| seen.len else null);
            const paint = binding.paint orelse
                return self.tableLinkStyleRefusal("binding_paint", 4, original, null, binding.subject,
                    action_index, mapped.len, scope.links.len, if (scope.actions_seen) |seen| seen.len else null);
            var value = original;
            value.kind = if (destination.external) .external_link else .link; value.target = destination.target;
            value.link_paint = paint; value.table_link_source = binding.token; value.table_link_wrap = binding.wrap;
            value.foreground = paint.normal.foreground; value.foreground_set = true; value.underline = paint.normal.underline;
            value.font_scale = font.font_scale; value.font_scale_basis = font.font_scale_basis; value.font_scale_set = true;
            value.font_features = font.font_features; value.bold = font.bold; value.italic = font.italic;
            if (binding.prefix_font_owner != null) value.font_family = font.font_family;
            value.authored_link_font_override = true;
            // Keep the ordinary generated anchor in the logical text path.
            // Its own attributes come from this exact source/HTML action join;
            // the caller's existing parent authority is not promoted.
            const attributes = try self.a.create(TableViewportAttributeInventory);
            attributes.* = .{ .attributes = binding.attributes };
            const anchor = try self.a.create(table_style_profile.TextElement);
            anchor.* = .{ .tag = "a", .parent = original.text_element,
                .attribute_presence = .{ .ctx = attributes, .get = TableViewportAttributeInventory.presence },
                .observed_custom_environment = font.custom_properties };
            value.text_element = anchor; value.custom_properties = font.custom_properties;
            if (scope.closed_focus) {
                const seen = scope.actions_seen orelse
                    return self.tableLinkStyleRefusal("seen_absent", 1, original, parent, binding.subject,
                        action_index, mapped.len, scope.links.len, null);
                if (seen.len != scope.links.len)
                    return self.tableLinkStyleRefusal("seen_count", 2, original, parent, binding.subject,
                        action_index, mapped.len, scope.links.len, seen.len);
                seen[action_index] = true;
            }
            return value;
        }
        return null;
    }

    fn tableLinkWrapSpanMatches(span: Span, binding: TableSourceLink) bool {
        const expected: ?presentation_types.InlineTextStyle = if (binding.wrap) |wrap| .{ .wrap = wrap } else null;
        return sameFigurePreparationValue(span.inline_style, expected);
    }

    fn tableConstructedSpansMatch(spans: []const Span, owned: TableViewportCellScope) bool {
        return tableConstructedSpansMatchAt(spans, owned, 0);
    }
    fn tableConstructedSpansMatchAt(spans: []const Span, owned: TableViewportCellScope, depth: usize) bool {
        if (depth >= max_depth) return false;
        for (spans) |span| {
            if (depth != 0 and (span.ruby != null or span.inline_padding_group != null or span.inline_action_group != null)) return false;
            if (span.image != null or span.self_link or span.pending_figure != null or span.pending_bidi_scope != null or
                span.pending_container != null or span.captured_bidi_scope != null or span.generated_link != null or
                span.target_fragment != null or span.external_literal_parameter != null) return false;
            if (span.inline_box_group) |box| {
                // This source lane has no ancestor A grant. The plain owner can
                // contain independently source-joined actions, each checked here.
                if (span.kind != .text or span.target.len != 0 or span.link_paint != null or span.inline_style != null) return false;
                presentation_types.validateInlineBoxGroupTree(span, depth, 0) catch return false;
                // The existing constructed receipt proves empty decoration,
                // not an independently laid-out text paragraph.
                if (presentation_types.inlineBoxHasOverlayContent(box.*)) return false;
                if (!tableConstructedSpansMatchAt(box.spans, owned, depth + 1)) return false;
                continue;
            }
            if (span.kind == .text or span.kind == .line_break) {
                if (span.link_paint != null or span.inline_style != null or span.target.len != 0) return false;
                continue;
            }
            if (span.kind != .link and span.kind != .external_link) return false;
            var matched = false;
            for (owned.links) |binding| if (span.kind == (if (binding.external) ir.InlineKind.external_link else ir.InlineKind.link) and
                std.mem.eql(u8, trim(span.target), trim(binding.target)) and sameFigurePreparationValue(span.link_paint, binding.paint) and
                tableLinkWrapSpanMatches(span, binding)) {
                matched = true; break;
            };
            if (!matched) return false;
        }
        return true;
    }

    fn tableConstructedBlocksMatch(blocks: []const Block, owned: TableViewportCellScope, depth: usize) bool {
        if (depth >= max_depth) return false;
        for (blocks) |item| {
            if (item.feature != null or item.table != null or item.figure != null or item.flow != null or
                item.anchor.len != 0 or item.anchor_fallback.len != 0 or item.heading_authored_id.len != 0 or
                item.heading_source_offset != null or item.list_path.len != 0 or item.number.len != 0 or
                !oneOf(@tagName(item.kind), &.{"paragraph", "blank", "container"}) or
                !tableConstructedSpansMatch(item.spans, owned)) return false;
            if (item.container) |container| {
                if (item.kind != .container or !tableConstructedBlocksMatch(container.blocks, owned, depth + 1)) return false;
            } else if (item.kind == .container) return false;
        }
        return true;
    }

    fn tableClosedBlockActionsMatch(cell: Cell, owned: TableViewportCellScope) bool {
        if (!owned.closed_focus or cell.nested_table != null) return false;
        const seen = owned.actions_seen orelse return false;
        if (seen.len != owned.links.len) return false;
        for (seen) |present| if (!present) return false;
        if (!tableConstructedSpansMatch(cell.spans, owned)) return false;
        if (cell.blocks) |blocks| if (!tableConstructedBlocksMatch(blocks, owned, 0)) return false;
        return true;
    }

    fn tableConstructedActionsMatch(cell: Cell, owned: TableViewportCellScope) bool {
        return owned.source_constructed and tableClosedBlockActionsMatch(cell, owned);
    }

    fn tableSourceFocusActionsMatch(cell: Cell, owned: TableViewportCellScope) bool {
        if (owned.captured_intrinsic_content) {
            // Captured intrinsic cells retain their source/HTML identity; they
            // are not synthetic constructor proofs. Their admitted CENTER
            // content can produce blocks, still under the same closed actions.
            if (owned.source_constructed or owned.literal_grids.len != 0) return false;
            return tableClosedBlockActionsMatch(cell, owned);
        }
        if (owned.source_constructed) return tableConstructedActionsMatch(cell, owned);
        if (owned.literal_grids.len != 0) {
            if (!owned.closed_focus or !tableConstructedSpansMatch(cell.spans, owned) or
                (cell.nested_table != null and cell.blocks != null)) return false;
            const seen = owned.actions_seen orelse return false;
            if (seen.len != owned.links.len) return false;
            for (seen) |present| if (!present) return false;
            var next: usize = 0;
            const source_cell = owned.literal_grids[0].outer_cell;
            if (cell.nested_table) |nested| if (!tableNestedNativeTableActionsMatch(nested, owned,
                owned.literal_grids, &next, source_cell, 0)) return false;
            if (cell.blocks) |blocks| if (!tableNestedNativeBlocksActionsMatch(blocks, owned,
                owned.literal_grids, &next, source_cell, 0)) return false;
            return next == owned.literal_grids.len;
        }
        if (cell.blocks != null or cell.nested_table != null or !owned.closed_focus) return false;
        const seen = owned.actions_seen orelse return false;
        if (seen.len != owned.links.len) return false;
        for (seen) |present| if (!present) return false;
        var images: usize = 0;
        for (cell.spans) |span| {
            if (span.image) |image| {
                var found = false;
                for (owned.links) |binding| if (binding.prefix_image) |source_image| {
                    if (span.kind == .link and std.mem.eql(u8, trim(span.target), trim(binding.target)) and
                        span.inline_style == null and binding.wrap == null and source_image.focus != null and binding.paint != null and
                        sameFigurePreparationValue(source_image.focus.?.paint, binding.paint.?) and
                        sameFigurePreparationValue(span.link_paint, source_image.focus.?.output()) and
                        sameFigurePreparationValue(image, source_image.image) and tablePrefixImageSpanMatches(span, source_image)) { found = true; break; }
                };
                if (!found or span.pending_figure != null or span.pending_bidi_scope != null or span.pending_container != null or
                    span.captured_bidi_scope != null or span.generated_link != null or span.target_fragment != null or span.self_link) return false;
                images += 1;
                continue;
            }
            if (span.self_link or span.pending_figure != null or span.pending_bidi_scope != null or
                span.pending_container != null or span.captured_bidi_scope != null or span.generated_link != null or
                span.target_fragment != null or span.external_literal_parameter != null) return false;
            if (span.kind == .text) { if (span.link_paint != null or span.inline_style != null or span.target.len != 0) return false; continue; }
            if (span.kind != .link and span.kind != .external_link) return false;
            var matched = false;
            for (owned.links) |binding| if (span.kind == (if (binding.external) ir.InlineKind.external_link else ir.InlineKind.link) and
                std.mem.eql(u8, trim(span.target), trim(binding.target)) and sameFigurePreparationValue(span.link_paint, binding.paint) and
                tableLinkWrapSpanMatches(span, binding)) {
                matched = true; break;
            };
            if (!matched) return false;
        }
        var expected_images: usize = 0;
        for (owned.links) |binding| if (binding.prefix_image != null) { expected_images += 1; };
        return images == expected_images;
    }

    fn tableLinkSourcesEqual(left: ?TableLinkSource, right: ?TableLinkSource) bool {
        const first = left orelse return right == null;
        const second = right orelse return false;
        // Floating source alternatives can have different observed node indices.
        // Pair boxes by the exact enrolled source opening/cell, then compare the
        // complete results; the first context cannot lend its box to the others.
        if (first.constructed_boxes.len != second.constructed_boxes.len) return false;
        if (first.constructed_boxes.len != 0) {
            if (first.constructed_boxes.len != first.constructed_fonts.len or
                second.constructed_boxes.len != second.constructed_fonts.len) return false;
            for (first.constructed_boxes, second.constructed_boxes, first.constructed_fonts, second.constructed_fonts) |one, two, left_font, right_font| {
                if (one.subject != left_font.subject or two.subject != right_font.subject or
                    left_font.cell != right_font.cell or (left_font.quote != null) != (right_font.quote != null) or
                    (if (left_font.quote) |quotes| quotes.ptr != right_font.quote.?.ptr or quotes.len != right_font.quote.?.len or
                        !std.mem.eql(u8, left_font.opening.name, right_font.opening.name) else
                        left_font.opening.name.ptr != right_font.opening.name.ptr or left_font.opening.name.len != right_font.opening.name.len) or
                    left_font.opening.attrs.ptr != right_font.opening.attrs.ptr or left_font.opening.attrs.len != right_font.opening.attrs.len or
                    one.rejected != two.rejected or !sameFigurePreparationValue(one.resolution, two.resolution) or
                    !tableNestedFontOwnersAgree(left_font.owner, right_font.owner)) return false;
            }
        }
        if (first.constructed_foregrounds.len != second.constructed_foregrounds.len) return false;
        if (first.constructed_foregrounds.len != 0) {
            if (first.constructed_foregrounds.len != first.constructed_fonts.len or
                second.constructed_foregrounds.len != second.constructed_fonts.len or
                first.constructed_boxes.len != first.constructed_fonts.len) return false;
            // The preceding box/source pairing validates the corresponding exact
            // opening, cell and quote source in both alternative contexts.
            for (first.constructed_foregrounds, second.constructed_foregrounds, first.constructed_fonts, second.constructed_fonts) |one, two, left_font, right_font| {
                if (one.subject != left_font.subject or two.subject != right_font.subject or
                    one.rejected != two.rejected or !sameFigurePreparationValue(one.foreground, two.foreground)) return false;
            }
        }
        if (first.constructed_inline_boxes.len != second.constructed_inline_boxes.len) return false;
        if (first.constructed_inline_boxes.len != 0) {
            if (first.constructed_inline_boxes.len != first.constructed_fonts.len or
                second.constructed_inline_boxes.len != second.constructed_fonts.len or
                first.constructed_boxes.len != first.constructed_fonts.len) return false;
            // The existing source-opening/cell pairing above binds each result
            // to its own full descendant graph, not to the grid-node index.
            for (first.constructed_inline_boxes, second.constructed_inline_boxes, first.constructed_fonts, second.constructed_fonts) |one, two, left_font, right_font| {
                if (one.subject != left_font.subject or two.subject != right_font.subject or
                    one.candidate != two.candidate or one.selection_rejected != two.selection_rejected or
                    one.rejected != two.rejected or !sameFigurePreparationValue(one.resolution, two.resolution)) return false;
            }
        }
        if (first.inline_fonts.len != second.inline_fonts.len) return false;
        for (first.inline_fonts, second.inline_fonts) |one, two| if (one.cell != two.cell or
            ((one.quote != null) != (two.quote != null)) or
            (if (one.quote) |quotes| quotes.ptr != two.quote.?.ptr or quotes.len != two.quote.?.len or
                !std.mem.eql(u8, one.opening.name, two.opening.name) else
                one.opening.name.ptr != two.opening.name.ptr or one.opening.name.len != two.opening.name.len) or
            one.opening.attrs.ptr != two.opening.attrs.ptr or one.opening.attrs.len != two.opening.attrs.len or
            !tableNestedFontOwnersAgree(one.owner, two.owner) or
            !sameFigurePreparationValue(one.paint, two.paint) or
            !tableViewportEnvironmentEqual(one.environment, two.environment)) return false;
        if (first.entities.len != second.entities.len) return false;
        for (first.entities, second.entities) |one, two| if (one.subject != two.subject or
            one.source.ptr != two.source.ptr or one.source.len != two.source.len or !std.mem.eql(u8, one.text, two.text)) return false;
        if (first.links.len != second.links.len or first.source_constructed != second.source_constructed or
            !tableLiteralSourceGridsEqual(first.literal_grids, second.literal_grids) or
            first.proof.closedSourceFocus() != second.proof.closedSourceFocus()) return false;
        for (first.links, second.links) |one, two| {
            if (one.token.ptr != two.token.ptr or one.token.len != two.token.len or one.cell != two.cell or
                one.external != two.external or !std.mem.eql(u8, one.target, two.target) or
                one.wrap != two.wrap or one.wrap_checked != two.wrap_checked or
                !sameFigurePreparationValue(one.paint, two.paint) or !tableLinkFontStyleEqual(one.font, two.font) or
                !tableLinkFontStyleEqual(one.parent_font, two.parent_font) or
                !tablePrefixImageBindingsAgree(one.prefix_image, two.prefix_image) or
                !tableNestedFontOwnersAgree(one.prefix_font_owner, two.prefix_font_owner) or
                (first.source_constructed and !tableLinkAttributesEqual(one.attributes, two.attributes))) return false;
        }
        return true;
    }

    fn tableLiteralSourceGridsEqual(left: []const TableLiteralSourceGrid, right: []const TableLiteralSourceGrid) bool {
        if (left.len != right.len) return false;
        for (left, right) |one, two| {
            if (!tableNestedFontOwnersAgree(one.font_owner, two.font_owner)) return false;
            if (one.outer_cell != two.outer_cell or one.opening.name.ptr != two.opening.name.ptr or
                one.opening.name.len != two.opening.name.len or one.opening.attrs.ptr != two.opening.attrs.ptr or
                one.opening.attrs.len != two.opening.attrs.len or one.rows.len != two.rows.len) return false;
            for (one.rows, two.rows) |first, second| {
                if (first.opening.name.ptr != second.opening.name.ptr or first.cells.len != second.cells.len) return false;
                for (first.cells, second.cells) |a, b| if (!tableNestedFontOwnersAgree(a.font_owner, b.font_owner) or
                    a.empty_content_proved != b.empty_content_proved or a.opening.name.ptr != b.opening.name.ptr or
                    a.opening.name.len != b.opening.name.len or a.opening.attrs.ptr != b.opening.attrs.ptr or
                    a.opening.attrs.len != b.opening.attrs.len or a.body.ptr != b.body.ptr or a.body.len != b.body.len) return false;
            }
        }
        return true;
    }
    fn tableLiteralGridsForCell(self: *Renderer, candidate: TableViewportCandidate, body: []const u8) Error![]const TableLiteralSourceGrid {
        const source = candidate.link_source orelse return &.{};
        var result: std.ArrayList(TableLiteralSourceGrid) = .empty;
        for (source.literal_grids) |grid| if (wikiClassContains(body, grid.opening.name)) {
            if (result.items.len != 0 and result.items[0].outer_cell != grid.outer_cell) return error.UncompiledPresentation;
            try result.append(self.a, grid);
        };
        return try result.toOwnedSlice(self.a);
    }

    fn tableInlineFontsForCell(self: *Renderer, candidate: TableViewportCandidate, body: []const u8) Error![]const TableInlineSourceFont {
        const source = candidate.link_source orelse return &.{};
        var result: std.ArrayList(TableInlineSourceFont) = .empty;
        for (source.inline_fonts) |binding| if (wikiClassContains(body, binding.quote orelse binding.opening.name) and
            (binding.opening.attrs.len == 0 or wikiClassContains(body, binding.opening.attrs))) {
            // No occurrence proof was issued for this run. Generic rendering
            // keeps its existing strict queries and cannot borrow another run.
            if (binding.owner == null or binding.paint == null or binding.environment == null) continue;
            try result.append(self.a, binding);
        };
        return try result.toOwnedSlice(self.a);
    }

    fn tableConstructedFontsForCell(self: *Renderer, candidate: TableViewportCandidate, body: []const u8) Error![]const TableInlineSourceFont {
        const source = candidate.link_source orelse return &.{};
        if (!source.source_constructed) return &.{};
        var result: std.ArrayList(TableInlineSourceFont) = .empty;
        for (source.constructed_fonts) |binding| if (wikiClassContains(body, binding.quote orelse binding.opening.name) and
            (binding.opening.attrs.len == 0 or wikiClassContains(body, binding.opening.attrs))) {
            if (binding.owner == null) return error.UncompiledPresentation;
            try result.append(self.a, binding);
        };
        return try result.toOwnedSlice(self.a);
    }

    fn tableLinksForCell(self: *Renderer, candidate: TableViewportCandidate, body: []const u8) Error![]const TableSourceLink {
        const source = candidate.link_source orelse return &.{};
        var result: std.ArrayList(TableSourceLink) = .empty;
        for (source.links) |binding| if (wikiClassContains(body, binding.token)) try result.append(self.a, binding);
        return try result.toOwnedSlice(self.a);
    }

    fn tablePrefixImageActionCurrent(self: *const Renderer, style: Style) bool {
        const scope = self.table_viewport_cell_source orelse return false;
        if (!scope.closed_focus or scope.source_constructed or self.figure_caption_depth != 0 or self.observed_figure_caption != null) return false;
        if (self.inline_missing) |tracked| if (!wikiClassCleanText(tracked) and !self.selectedTableSourceState(tracked)) return false;
        const token = style.table_link_source orelse return false;
        const mapped = self.tableDirectionOriginal(token) orelse return false;
        if (mapped.ptr != token.ptr or mapped.len != token.len or !wikiClassContains(scope.source, token)) return false;
        const image = style.image orelse return false;
        for (scope.links) |binding| if (binding.token.ptr == token.ptr and binding.token.len == token.len) {
            const prefix = binding.prefix_image orelse return false;
            const focus = prefix.focus orelse return false;
            const owner = (prefix.font orelse return false).font;
            if (prefix.box == null or binding.paint == null or scope.prefix_font_owner == null) return false;
            return !binding.external and style.kind == .link and std.mem.eql(u8, trim(style.target), trim(binding.target)) and
                sameFigurePreparationValue(image, prefix.image) and sameFigurePreparationValue(focus.paint, binding.paint.?) and
                sameFigurePreparationValue(style.link_paint, focus.output()) and
                image.map == null and image.static_poster == null and (if (image.alt) |alt| alt.len == 0 else true) and
                style.font_scale == owner.font_scale and style.font_scale_basis == owner.font_scale_basis and
                style.bold == owner.bold and style.italic == owner.italic and style.font_features == owner.font_features and
                sameFigurePreparationValue(style.font_family, owner.font_family) and std.mem.eql(u8, style.language, owner.language) and
                !style.code and !style.small and !style.superscript and !style.subscript and !style.strike and style.role == .normal;
        };
        return false;
    }

    fn tableLinkActionCurrent(self: *const Renderer, style: Style, target: []const u8) bool {
        const scope = self.table_viewport_cell_source orelse return false;
        if (self.inline_missing) |tracked| if (!wikiClassCleanText(tracked) and !self.selectedTableSourceState(tracked)) return false;
        const token = style.table_link_source orelse return false;
        const mapped = self.tableDirectionOriginal(token) orelse return false;
        if (mapped.ptr != token.ptr or mapped.len != token.len or !wikiClassContains(scope.source, token)) return false;
        for (scope.links) |binding| if (binding.token.ptr == token.ptr and binding.token.len == token.len) {
            return binding.paint != null and style.link_paint != null and
                sameFigurePreparationValue(binding.paint, style.link_paint) and binding.wrap == style.table_link_wrap and
                std.mem.eql(u8, trim(target), trim(binding.target)) and
                style.kind == (if (binding.external) ir.InlineKind.external_link else ir.InlineKind.link);
        };
        return false;
    }

    const TableViewportSourceCell = struct {
        raw: []const u8,
        row_opening: ?[]const u8 = null,
        body_start: usize,
        body_end: usize,
        node: u32,
        row: usize,
        header: bool,
        colspan: u16,
        rowspan: u16,
        needs_nested_source: bool = false,
    };

    const TableViewportSourceGraph = struct {
        nodes: []const table_style_profile.ObservedStyleNode,
        root: u32,
        table: u32,
        cells: []const TableViewportSourceCell,
        row_count: usize,
        end: usize,
        nested_source: bool = false,
        prefix_media: bool = false,
        intrinsic: bool = false,
    };

    fn tableViewportAttributeInventoryComplete(tag: syntax.Tag) bool {
        // The generic probe refuses every self-closing node. Only empty
        // ordinary BR/WBR have the same closed body/attribute domain here.
        // Share this check with the descendant census; do not drop its proof.
        if (!tag.closing and !tag.html_pre and tag.self_closing and
            oneOf(tag.name, &.{ "br", "wbr" }) and trim(tag.attrs).len == 0) return true;
        return htmlOwnAttributePresence(&tag, "__table_inventory_probe__") != .unknown;
    }

    fn tableViewportAttributes(self: *Renderer, tag: syntax.Tag) Error!?[]const table_style_profile.FigureObservedAttribute {
        if (!tableViewportAttributeInventoryComplete(tag)) return null;
        var result: std.ArrayList(table_style_profile.FigureObservedAttribute) = .empty;
        var at: usize = 0;
        while (at < tag.attrs.len) {
            while (at < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[at])) : (at += 1) {}
            if (at == tag.attrs.len) break;
            const begin = at;
            while (at < tag.attrs.len and (std.ascii.isAlphanumeric(tag.attrs[at]) or
                std.mem.indexOfScalar(u8, "_:-", tag.attrs[at]) != null)) : (at += 1) {}
            if (at == begin) return null;
            const name = tag.attrs[begin..at];
            if (name.len >= 2 and std.ascii.eqlIgnoreCase(name[0..2], "on")) return null;
            const value = (try self.semanticAttribute(tag, name)) orelse "";
            try result.append(self.a, .{ .name = name, .value = value });
