                        .body_start = @intFromPtr(content.text.ptr) - @intFromPtr(source.ptr),
                        .body_end = body_end,
                        .node = index, .row = row_count - 1,
                        .header = header, .colspan = content.colspan, .rowspan = content.rowspan,
                        .needs_nested_source = needs_nested_source });
