        if (self.table_parent_container_operation != null or !tag.is("div") or tag.closing or tag.self_closing or
            tag.html_pre or self.content_root != .parser_output or self.in_reference or self.in_template_literal_scope or
            self.figure_caption_depth != 0 or self.typed_table_depth != 0 or self.pre_block or self.parsed_pre or
            native.text_element != null or native.provenance != .parsed or native.kind != .text or native.target.len != 0 or
            native.font_size_unknown or native.heading or native.code or native.small or native.superscript or native.subscript or
            self.block_formatting.code or self.block_formatting.small or self.block_formatting.superscript or self.block_formatting.subscript or
            native.self_link_target != null or native.image != null) return self.traceTableParentContainerRefusal("native_guard", source, tag, native, null);
