        if (self.context.text_paint_styles) |styles| if (styles.page_style_parent != null) return self.traceTableParentContainerRefusal("selected_paint_profile", source, tag, native, null);
        const selected = self.tableDirectionSource() orelse return self.traceTableParentContainerRefusal("selected_source", source, tag, native, null);
        if (!selected.root_only or selected.prefix_viewport or selected.intrinsic_viewport) return self.traceTableParentContainerRefusal("source_kind", source, tag, native, null);
