            self.native_inline_motion_epoch != epoch or epoch == 0 or root.reference != null or
            self.content_root != .parser_output or
            self.in_reference or self.media_depth != 0 or self.ruby_depth != 0 or self.figure_caption_depth != 0 or
            self.typed_table_depth != 0 or self.table_viewport_cell_source != null or self.figure_implicit_list_context or
            self.html_list_item_flow or self.html_blockquote_flow or self.in_template_literal_scope or
            self.pre_block or self.parsed_pre or self.poem_depth != 0 or self.context.observe_structure_only or
            self.rejection_probe_scope or actual.source_key != @intFromPtr(tag.name.ptr));
    }

    // Resolve physical facts for the selected opening within the active article.
    // Exterior ancestry stays open when the source supplies only a fragment.
    fn orderedLiteralQuery(self: *Renderer, tag: syntax.Tag, actual: *const table_style_profile.TextElement,
        parent_state: NativeInlineMotionState, fallback: *const table_style_profile.TextElement,
        original_opening: ?*[]const u8) Error!*const table_style_profile.TextElement
    {
        const held = switch (parent_state) { .proved => |known| known, else => return fallback };
        const host = self.native_article_host orelse return fallback;
        const body = self.body_missing orelse return fallback;
        if (!self.literalSubjectContext(tag, actual, held.root, held.epoch, host)) return fallback;
        if (self.literal_subject_work) |work| {
            work.snapshot_calls += 1;
            work.snapshot_source_bytes += held.root.source.bytes.len;
        }
        if (!host.matchesActive(self, held.root.source) or !wikiClassContains(body.bytes, tag.name)) return fallback;
        const current = liveLiteralOpening(body, tag) orelse return fallback;
        const parsed = syntax.tagAt(current, 0) orelse return fallback;
        const opening = self.nativeOriginalCopiedRange(held.root.source, current) orelse return fallback;
        // Both the parser and its HTML5 consumer must agree on this opening.
        // In particular, parse the raw delimiter before any attribute trimming.
        if (opening.len <= 1 + tag.name.len or !std.mem.eql(u8, opening, current) or
            std.mem.indexOfScalar(u8, " \t\n\r\x0c>", opening[1 + tag.name.len]) == null or
            htmlOwnAttributePresence(&parsed, "class") == .unknown or htmlOwnAttributePresence(&parsed, "id") == .unknown or
            actual.page_style_root != null or actual.alternative_ancestry != null or actual.physical_ancestry_complete or
            !self.currentAncestorScope(actual)) return fallback;
        const projection = try self.a.create(table_style_profile.TextElement);
        projection.* = fallback.*;
        projection.parent = null;
        projection.complete_ancestor_classes = null;
        projection.complete_ancestor_ids = null;
        projection.literal_subject_bound = true;
        const observed = self.literalRegionExclusions(host, held.root.source, opening);
        projection.observed_region_classes = if (observed) |facts| facts.classes else null;
        projection.literal_screen_root_box = if (observed) |facts| facts.screen_root_box else null;
        projection.source_nonlink_element = oneOf(tag.name, &.{ "div", "span", "i", "abbr" });
        projection.source_literal_previous = if (observed != null and observed.?.follows_observed_style) .{ .tag = "style" } else null;
        if (original_opening) |destination| destination.* = opening;
        return projection;
    }

    // Recover only the opening owned by this physical tag. The same check is
    // used for the literal selector query and for the exact observed screen root.
    fn liveLiteralOpening(body: MissingText, tag: syntax.Tag) ?[]const u8 {
        if (!wikiClassContains(body.bytes, tag.name) or tag.closing or tag.self_closing or tag.html_pre) return null;
        const name = @intFromPtr(tag.name.ptr) - @intFromPtr(body.bytes.ptr);
        if (name == 0) return null;
        const parsed = syntax.tagAt(body.bytes, name - 1) orelse return null;
        if (parsed.closing or parsed.self_closing or parsed.html_pre or parsed.name.ptr != tag.name.ptr or
            parsed.name.len != tag.name.len or parsed.attrs.ptr != tag.attrs.ptr or parsed.attrs.len != tag.attrs.len) return null;
        const opening = body.bytes[name - 1 .. parsed.end];
        return if (noLiParentSourceRange(body, opening)) opening else null;
    }

    fn observedScreenRootForOpening(self: *const Renderer, tag: syntax.Tag,
        element: *const table_style_profile.TextElement) ?*const table_style_profile.ObservedLiteralScreenBox
    {
        // Only a complete, already selected Book region can supply this box.
        // Its physical root does not depend on the generic selector query
        // having proved a new ancestry projection for the current element.
        const sizing = self.context.figure_sizing orelse return null;
        const region = sizing.literal_region orelse return null;
        if (region.screen_root_box == null or !tag.is("div") or element.source_key != @intFromPtr(tag.name.ptr) or
            self.content_root != .parser_output or self.in_reference or self.media_depth != 0 or self.ruby_depth != 0 or
            self.figure_caption_depth != 0 or self.typed_table_depth != 0 or self.table_viewport_cell_source != null or
            self.figure_implicit_list_context or self.html_list_item_flow or self.html_blockquote_flow or self.in_template_literal_scope or
            self.pre_block or self.parsed_pre or self.poem_depth != 0 or self.context.observe_structure_only or self.rejection_probe_scope) return null;
        const host = self.native_article_host orelse return null;
        if (!host.native_paragraph_css_subjects) return null;
        const active = host.active_source orelse return null;
        const body = self.body_missing orelse return null;
        const live = liveLiteralOpening(body, tag) orelse return null;
        const original = self.nativeOriginalCopiedRange(active, live) orelse return null;
        const facts = self.literalRegionExclusions(host, active, original) orelse return null;
        const box = facts.screen_root_box orelse return null;
        return if (host.matchesActive(self, active)) box else null;
    }

    fn literalRegionExclusions(self: *const Renderer, host: *const NativeArticleHost,
        root: MissingText, opening: []const u8) ?LiteralOpeningExclusions
    {
        const sizing = self.context.figure_sizing orelse return null;
        const region = sizing.literal_region orelse return null;
        if (!wikiClassContains(region.page, region.selected) or !wikiClassContains(root.bytes, opening)) return null;
        if (host.active_whole_page and NativeArticleHost.sameSource(root, host.source) and
            root.bytes.ptr == region.page.ptr and root.bytes.len == region.page.len)
            return region.exclusionsForOpening(root.bytes, opening);
        const fragment = host.active_fragment orelse return null;
        if (fragment.literal_prefix) |observed| return observed.exclusionsForOpening(region, fragment, root, opening);
        const original = fragment.original_page orelse return null;
        if (original.ptr != region.page.ptr or original.len != region.page.len or
            fragment.page.len != original.len or !std.mem.eql(u8, fragment.page, original) or
            fragment.prepared.ptr != root.bytes.ptr or fragment.prepared.len != root.bytes.len or
            fragment.start > original.len or root.bytes.len > original.len - fragment.start or
            !std.mem.eql(u8, root.bytes, original[fragment.start..][0..root.bytes.len])) return null;
        const off = fragment.start + (@intFromPtr(opening.ptr) - @intFromPtr(root.bytes.ptr));
        return region.exclusionsForOpening(original, original[off..][0..opening.len]);
    }

    fn currentLiteralParentState(self: *const Renderer) NativeInlineMotionState {
        if (self.body_language_direction) |style| if (style.native_inline_motion != .absent) return style.native_inline_motion;
        return self.body_formatting_attributes.native_inline_motion;
    }

    // Text between sibling DIVs can reconstruct an active inline element.
    // Admit only consecutive closed DIV siblings made of literal DIVs and
    // ordinary text within them, or the empty gap before the first child.
    fn literalDivPredecessor(gap: []const u8) ?[]const u8 {
        if (gap.len == 0) return "";
        if (gap.len > 65536) return null;
        var depth: usize = 0;
        var offset: usize = 0;
        while (offset < gap.len) {
            if (gap[offset] != '<') {
                if (depth == 0) return null;
                const end = std.mem.indexOfScalarPos(u8, gap, offset, '<') orelse return null;
                if (std.mem.indexOfAny(u8, gap[offset..end], "[]{}|'\r\n") != null) return null;
                offset = end;
                continue;
            }
            const tag = syntax.tagAt(gap, offset) orelse return null;
            if (!tag.is("div") or tag.self_closing or tag.html_pre or
                std.mem.indexOfAny(u8, tag.attrs, "<>[]{}\x0b") != null) return null;
            if (tag.closing) {
                if (depth == 0 or trim(tag.attrs).len != 0) return null;
                depth -= 1;
            } else {
                if (depth >= max_depth or !htmlNestedAttributes(tag.attrs, &.{ "class", "id", "style" }) or
                    htmlOwnAttributePresence(&tag, "class") == .unknown) return null;
                depth += 1;
            }
            offset = tag.end;
        }
        return if (depth == 0) "div" else null;
    }

    // Native opening/closing operations certify local edges. Exterior ancestry
    // stays open, including after any number of proved earlier sibling DIVs.
    fn literalFirstDivQuery(self: *Renderer, tag: syntax.Tag, node: *const table_style_profile.TextElement,
        state: NativeInlineMotionState, fallback: *const table_style_profile.TextElement) Error!?*const table_style_profile.TextElement
    {
        const held = switch (state) { .proved => |v| v, else => return null };
        // A nested flex item is a different live subject. Resolve its own
        // opening and declaration chain while retaining the enclosing cache.
        if (self.literal_subject) |bound| cached: {
            if (bound.key != node.source_key) break :cached;
            const body = self.body_missing orelse return null;
            const host = self.native_article_host orelse return null;
            const active = host.active_source orelse return null;
            const snapshot = host.active_snapshot orelse return null;
            const language = self.native_body_language orelse return null;
            if (host != bound.host or host.renderer != self or !std.mem.eql(u8, host.title, self.context.title) or
                !std.mem.eql(u8, host.language_code, language) or !std.mem.eql(u8, &snapshot, &bound.snapshot) or
                !NativeArticleHost.sameSource(bound.body, body) or !NativeArticleHost.sameSource(active, bound.root.source) or
                held.last != bound.declaration or !self.literalSubjectContext(tag, node, held.root, held.epoch, host) or
                bound.key != @intFromPtr(tag.name.ptr) or node.source_key != bound.key or
                !std.mem.eql(u8, bound.node.classes, node.classes) or !std.mem.eql(u8, bound.node.id, node.id) or
                self.native_inline_motion_root != bound.root or self.native_inline_motion_epoch != bound.epoch or
                held.root != bound.root or held.epoch != bound.epoch or self.context.table_styles != bound.profile or
                self.textPaintProfile() != bound.profile) return null;
            const result = try self.a.create(table_style_profile.TextElement);
            result.* = fallback.*;
            result.parent = bound.node.parent;
            result.complete_ancestor_classes = null;
            result.complete_ancestor_ids = null;
            result.source_literal_previous = bound.node.source_literal_previous;
            result.source_nonlink_element = bound.node.source_nonlink_element;
            result.literal_first_div_pair = bound.node.literal_first_div_pair;
            result.literal_subject_bound = bound.node.literal_subject_bound;
            result.observed_region_classes = bound.node.observed_region_classes;
            result.literal_screen_root_box = bound.node.literal_screen_root_box;
            return result;
        }
        if (!tag.is("div") or self.context.table_styles == null or self.textPaintProfile() != self.context.table_styles)
            return null;
        var child_open: []const u8 = "";
        const query = try self.orderedLiteralQuery(tag, node, state, fallback, &child_open);
        if (child_open.len == 0) return null;
        const last = held.last orelse return query;
        if (node.parent == null or !std.ascii.eqlIgnoreCase(node.parent.?.tag, "div") or
            last.origin != .html or node.parent.?.source_key == 0 or !starts(last.opening, "<")) return query;
        const tracked = held.root.source;
        const result = try self.a.create(table_style_profile.TextElement);
        result.* = query.*;
        var tail = result;
        var next = node.parent;
        var ancestor_entry = held.last;
        var budget: usize = max_depth + 1;
        while (next) |parent| {
            const entry = ancestor_entry orelse break;
            if (budget == 0 or entry.origin != .html or !std.ascii.eqlIgnoreCase(parent.tag, "div") or
                parent.alternative_ancestry != null or parent.physical_ancestry_complete or parent.ancestry_complete or
                parent.observed_custom_environment != null or parent.page_style_root != null or
                !std.mem.eql(u8, entry.opening, entry.opening_snapshot) or !noLiParentSourceRange(entry.source, entry.opening)) break;
            budget -= 1;
            const issuer = syntax.tagAt(entry.opening, 0) orelse break;
            if (!issuer.is("div") or issuer.closing or issuer.self_closing or issuer.html_pre or
                issuer.end != entry.opening.len or parent.source_key != @intFromPtr(issuer.name.ptr) or
                htmlOwnAttributePresence(&issuer, "class") == .unknown or htmlOwnAttributePresence(&issuer, "id") == .unknown or
                !std.mem.eql(u8, parent.classes, (try self.semanticAttribute(issuer, "class")) orelse "") or
                !std.mem.eql(u8, parent.id, (try self.semanticAttribute(issuer, "id")) orelse "") or
                !std.mem.eql(u8, entry.css, (try self.semanticAttribute(issuer, "style")) orelse "")) break;
            const original = self.nativeOriginalCopiedRange(tracked, entry.opening) orelse break;
            if (!std.mem.eql(u8, original, entry.opening) or @intFromPtr(original.ptr) >= @intFromPtr(child_open.ptr)) break;
            const parent_at = @intFromPtr(original.ptr) - @intFromPtr(tracked.bytes.ptr);
            const child_at = @intFromPtr(child_open.ptr) - @intFromPtr(tracked.bytes.ptr);
            if (original.len > child_at - parent_at) break;
            const gap = tracked.bytes[parent_at + original.len .. child_at];
            if (self.literal_subject_work) |work| if (gap.len != 0) {
                work.sibling_scans += 1;
                work.sibling_source_bytes += gap.len;
            };
            const previous_div = literalDivPredecessor(gap);
            const outer_tag = syntax.tagAt(tracked.bytes, parent_at) orelse break;
            const inner_tag = syntax.tagAt(tracked.bytes, child_at) orelse break;
            if (!outer_tag.is("div") or !inner_tag.is("div") or inner_tag.closing or outer_tag.closing or
                outer_tag.end != parent_at + original.len or inner_tag.end != child_at + child_open.len) break;
            const bounds = syntax.matchingTag(tracked.bytes, outer_tag) orelse break;
            const child = syntax.matchingTag(tracked.bytes, inner_tag) orelse break;
            if (child.end > bounds.inner_end or !noLiParentSourceRange(tracked, tracked.bytes[parent_at..bounds.end]) or
                !tableNestedSourceClose(tracked.bytes, "div", bounds, false) or !tableNestedSourceClose(tracked.bytes, "div", child, false)) break;
            const parent_source = tracked.bytes[parent_at..bounds.end];
            var clean_pair = false;
            if (self.literal_subject_work) |work| {
                work.pair_scans += 1;
                work.pair_source_bytes += parent_source.len;
            }
            _ = scanTranslatedLiteralPrefix(parent_source, parent_source.len, &clean_pair, false);
            if (!clean_pair) break;
            // A closed non-DIV flex item can rule out an adjacent selector
            // requiring a different element. It grants no positive parent or
            // first-child match. Its original direct parent is the one whose
            // complete opening and closing operations were proved above.
            const previous = previous_div orelse {
                if (scanTranslatedLiteralPrefix(parent_source, child_at - parent_at, null, true)) |seen| {
                    if (seen.len != 0) tail.source_literal_previous = .{ .tag = seen };
                }
                break;
            };
            const verified = try self.a.create(table_style_profile.TextElement);
            const observed = self.literalRegionExclusions(self.native_article_host.?, tracked, original);
            verified.* = .{ .tag = issuer.name, .classes = parent.classes, .id = parent.id,
                .own_language_attribute = try self.semanticAttribute(issuer, "lang"), .observed_inline_style = entry.css,
                .source_key = parent.source_key, .literal_subject_bound = true,
                // This parent may be outside the region that supplied its child.
                // Check its own original opener before issuing any exclusions.
                .observed_region_classes = if (observed) |facts| facts.classes else null,
                .literal_screen_root_box = if (observed) |facts| facts.screen_root_box else null,
                .source_literal_previous = if (observed != null and observed.?.follows_observed_style) .{ .tag = "style" } else null };
            tail.parent = verified;
            tail.source_literal_previous = .{ .tag = previous };
            tail.literal_first_div_pair = previous.len == 0;
            tail = verified;
            next = parent.parent;
            ancestor_entry = entry.previous;
            child_open = original;
        }
        if (result.parent == null and result.source_literal_previous == null) return query;
        return result;
    }

    fn translatedCardNode(self: *Renderer, tag: syntax.Tag, parent: Style, role: table_style_profile.TranslatedBoxRole,
        parent_line_px: ?f32, after_space: bool) Error!?TranslatedCardNode
    {
        if (tag.closing or tag.self_closing or tag.html_pre or !htmlNestedAttributes(tag.attrs, switch (role) {
            .relative_card, .flex_owner, .empty_vertical_edge, .flex_edge => &.{"style"}, .inline_atom => &.{ "class", "style" }, .absolute_label => if (tag.is("abbr")) &.{ "style", "title" } else &.{"style"},
        })) return null;
        const css = (try self.semanticAttribute(tag, "style")) orelse return null;
        const profile = self.textPaintProfile() orelse return null;
        if (self.context.table_styles) |other| if (other != profile) return null;
        const base = try self.textElement(tag, parent.text_element, parent.language);
        const query = try self.a.create(table_style_profile.TextElement);
        query.* = base.*;
        query.observed_inline_style = css;
        const general = (try self.nativeSourceClassQueryDiagnosed(tag, profile, query, parent.native_inline_motion, null)) orelse query;
        const in_operation = if (tag.is("div")) try self.literalFirstDivQuery(tag, query, parent.native_inline_motion, general) else null;
        const projected = in_operation orelse try self.orderedLiteralQuery(tag, query, parent.native_inline_motion, general, null);
        // The typed label owns the positive pixel strut and its non-inherited
        // background layer. Descendant ink/tooltip/action still follow the
        // ordinary HTML path; admission below proves each owning declaration.
        var label_style = try self.htmlInlineStyleWithLabelBox(tag, parent, role == .absolute_label);
        var font = self.positionedContainerInheritedFont(label_style) orelse return null;
        font.bold = label_style.bold;
        font.italic = label_style.italic;
        var box = (table_style_profile.translatedContainerStyle(self.a, profile, projected, css, self.customParent(label_style), font,
            role, parent_line_px, after_space) catch |err| return self.authoredElementQueryError(err)) orelse return null;
        if (tag.is("abbr")) {
            if (role != .absolute_label or !hasAuthoredTooltipTitle(tag) or label_style.explanation.len == 0) return null;
            try self.applyHtmlTooltip(tag, &label_style);
            box.translated_absolute.?.owns_abbreviation = true;
        }
        if ((role == .flex_owner or role == .empty_vertical_edge or role == .flex_edge) and !normalizeContainerStyle(&box,font.font_scale)) return null;
        // Query-local negative class/ID facts stay on the selected node.
        // Each descendant must earn its own projection against its source.
        label_style.text_element = query;
        label_style.font_scale = box.owner_font.?.font_scale;
        label_style.font_scale_basis = box.owner_font.?.font_scale_basis;
        label_style.font_scale_set = true;
        label_style.font_size_unknown = false;
        // The Container paints its own background once, including its radius
        // and colour alpha. The child inputs retain their ordinary ink/actions.
        label_style.background = null;
        return .{ .text = label_style, .box = box };
    }

    fn translatedCardParagraph(self: *Renderer, raw: []const u8, style: Style) Error!Block {
        const spans = try self.parseBodySpans(raw, style);
        if (spans.len == 0) return error.UncompiledPresentation;
        for (spans) |span| if (!presentation_types.validTranslatedTextLeaf(span)) return error.UncompiledPresentation;
        return .{ .kind = .paragraph, .spans = spans };
    }

    fn translatedStyledChild(tag: syntax.Tag, raw: []const u8) ?syntax.Pair {
        const pair = syntax.matchingTag(raw, tag) orelse return null;
        return if (tableNestedSourceClose(raw, tag.name, pair, false)) pair else null;
    }

    fn translatedGlossaryBox(self: *Renderer, node: TranslatedCardNode, raw: []const u8) Error!Container {
        if (!starts(raw, "[[")) return error.UncompiledPresentation;
        const link_pair = syntax.balanced(raw, 0) orelse return error.UncompiledPresentation;
        var blocks: std.ArrayList(Block) = .empty;
        const source_link = raw[0..link_pair.end];
        var iterator: ir.InlineIterator = .{ .input = source_link, .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const token = iterator.next() orelse return error.UncompiledPresentation;
        if (token.kind != .link or iterator.cursor != source_link.len or token.trail.len != 0) return error.UncompiledPresentation;
        var action_block = try self.translatedCardParagraph(source_link, node.text);
        const action = action_block.spans[0].target;
        for (action_block.spans) |span| {
            if (span.kind != .link or span.self_link or span.target_fragment != null or action.len == 0 or
                !std.mem.eql(u8, action, span.target)) return error.UncompiledPresentation;
        }
        // Ordinary title IR uses spaces for underscores. The physical link in
        // this glossary label also owns a URI fragment. Retain that fragment's
        // anchor spelling while keeping the parsed page and every label run.
        const source_title = try self.internalPercentTitleText(trim(token.target));
        if (std.mem.indexOfScalar(u8, source_title, '#')) |sep| {
            const source_fragment = source_title[sep + 1 ..];
            const hash = std.mem.indexOfScalar(u8, action, '#') orelse return error.UncompiledPresentation;
            const fragment = action[hash + 1 ..];
            if (fragment.len != source_fragment.len) return error.UncompiledPresentation;
            for (source_fragment, fragment) |authored, parsed| {
                if (authored != parsed and !(authored == '_' and parsed == ' ')) return error.UncompiledPresentation;
            }
            if (std.mem.indexOfScalar(u8, fragment, ' ') != null) {
                const href_target = try self.a.dupe(u8, action);
                std.mem.replaceScalar(u8, href_target[hash + 1 ..], ' ', '_');
                const spans = try self.a.dupe(Span, action_block.spans);
                for (spans) |*span| span.target = href_target;
                action_block.spans = spans;
            }
        }
        try self.appendBlockBudgeted(&blocks, action_block);
        if (link_pair.end != raw.len) {
            const tail = raw[link_pair.end..];
            const tag = syntax.tagAt(tail, 0) orelse return error.UncompiledPresentation;
            if (!tag.is("abbr")) return error.UncompiledPresentation;
            const pair = translatedStyledChild(tag, tail) orelse return error.UncompiledPresentation;
            if (pair.end != tail.len or !hasAuthoredTooltipTitle(tag)) return error.UncompiledPresentation;
            const leaf = (try self.translatedCardNode(tag, node.text, .absolute_label, node.box.line_height.?.length.value, false)) orelse return error.UncompiledPresentation;
            const content = tail[tag.end..pair.inner_end];
            if (content.len == 0 or std.mem.indexOfAny(u8, content, "<>[]{}\r\n") != null) return error.UncompiledPresentation;
            const body = try self.a.alloc(Block, 1);
            body[0] = try self.translatedCardParagraph(content, leaf.text);
            try self.appendBlockBudgeted(&blocks, .{ .kind = .container, .container = .{ .style = leaf.box, .blocks = body } });
        }
        return .{ .style = node.box, .blocks = try blocks.toOwnedSlice(self.a) };
    }

    fn measuredFlexTreeNode(self: *Renderer, source: []const u8, tag: syntax.Tag, pair: syntax.Pair,
        parent: Style, parent_layout: ?presentation_types.ContainerLayout, depth: usize) Error!?Container
    {
        if (depth >= presentation_types.max_content_depth or pair.end != source.len or
            !tableNestedSourceClose(source, tag.name, pair, false)) return null;
        const tracked = self.body_missing orelse return null;
        if (!noLiParentSourceRange(tracked, source)) return null;
        if (tag.is("span")) {
            // CSS blockifies an original direct flex item. Only this exact empty
            // input role can acquire a frame without any text or artificial line.
            if (parent_layout != .flex_column or tag.end != pair.inner_end) return null;
            const role: table_style_profile.TranslatedBoxRole = if (std.ascii.findIgnoreCase(tag.attrs,"align-self") != null)
                .flex_edge else .empty_vertical_edge;
            const edge = (try self.translatedCardNode(tag,parent,role,null,false)) orelse return null;
            return .{ .style = edge.box, .blocks = &.{} };
        }
        if (!tag.is("div") or self.positionedContainerOpening(tag) == null) return null;
        if (std.ascii.findIgnoreCase(tag.attrs, "border-radius") != null)
            return if (parent_layout == .flex_column) self.translatedCardSourceUnder(source, tag, pair, parent) else null;
        const box = (try self.translatedCardNode(tag, parent, .flex_owner, null, false)) orelse return null;
        const layout = box.box.layout orelse return null;
        if (parent_layout == .flex_row and layout != .flex_column) return null;
        var items: std.ArrayList(Block) = .empty;
        var offset = tag.end;
        while (offset < pair.inner_end) {
            // An all-whitespace anonymous flex item is suppressed in CSS.
            while (offset < pair.inner_end and std.ascii.isWhitespace(source[offset])) : (offset += 1) {}
            if (offset == pair.inner_end) break;
            const tail = source[offset..pair.inner_end];
            const child = syntax.tagAt(tail, 0) orelse return error.UncompiledPresentation;
            if (child.closing or child.self_closing or child.html_pre) return error.UncompiledPresentation;
            const bounds = translatedStyledChild(child, tail) orelse return error.UncompiledPresentation;
            const item = (try self.measuredFlexTreeNode(tail[0..bounds.end], child, bounds, box.text, layout, depth + 1)) orelse return error.UncompiledPresentation;
            try self.appendBlockBudgeted(&items, .{ .kind = .container, .container = item });
            offset += bounds.end;
        }
        if (items.items.len == 0) return null;
        const result: Container = .{ .style = box.box, .blocks = try items.toOwnedSlice(self.a) };
        return if (presentation_types.validContainerHeader(result)) result else error.UncompiledPresentation;
    }

    fn measuredFlexTreeSource(self: *Renderer, source: []const u8, tag: syntax.Tag, pair: syntax.Pair) Error!?Container {
        // Keep the ordinary flex emitter for its existing content families. The
        // lexical gate only identifies candidates; every owner and item below
        // must pass the ranked screen cascade and the original-range check.
        if (!tag.is("div") or tag.closing or tag.self_closing or tag.html_pre or
            std.ascii.findIgnoreCase(tag.attrs, "flex") == null or
            std.ascii.findIgnoreCase(source[tag.end..pair.inner_end], "border-radius") == null or
            self.context.observe_structure_only or self.rejection_probe_scope or self.in_reference or self.pre_block or self.parsed_pre or
            self.poem_depth != 0 or self.in_template_literal_scope or self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            self.navigation_target_probe != null or self.block_formatting.bold or self.block_formatting.italic) return null;
        return self.measuredFlexTreeNode(source, tag, pair, self.bodyFormattingStyle(self.body_language_direction orelse .{}), null, 0);
    }

    fn translatedCardSource(self: *Renderer, source: []const u8, tag: syntax.Tag, pair: syntax.Pair) Error!?Container {
        return self.translatedCardSourceUnder(source, tag, pair, self.bodyFormattingStyle(self.body_language_direction orelse .{}));
    }

    fn translatedCardSourceUnder(self: *Renderer, source: []const u8, tag: syntax.Tag, pair: syntax.Pair, parent: Style) Error!?Container {
        if (!tag.is("div") or self.context.observe_structure_only or self.rejection_probe_scope or self.in_reference or self.pre_block or
            self.parsed_pre or self.poem_depth != 0 or self.in_template_literal_scope or self.body_link_target.len != 0 or
            self.explicit_wiki_label != null or self.navigation_target_probe != null) return null;
        // A cheap source candidate only. Both geometry and ancestry are proved
        // below by the ranked profile, tracked byte range and paired children.
        if (std.ascii.findIgnoreCase(tag.attrs, "border-radius") == null or std.ascii.findIgnoreCase(tag.attrs, "position") == null) return null;
        const raw = source[tag.end..pair.inner_end];
        if (!starts(raw, "<span")) return null;
        if (self.block_formatting.bold or self.block_formatting.italic) return null;
        const tracked = self.body_missing orelse return null;
        if (!noLiParentSourceRange(tracked, source) or !tableNestedSourceClose(source, tag.name, pair, false) or self.positionedContainerOpening(tag) == null) return null;
        const owner = (try self.translatedCardNode(tag, parent, .relative_card, null, false)) orelse return null;
        var blocks: std.ArrayList(Block) = .empty;
        var cursor: usize = 0;
        var atoms: usize = 0;
        while (cursor < raw.len) {
            const after_space = raw[cursor] == ' ';
            if (after_space) cursor += 1;
            const rest = raw[cursor..];
            const child = syntax.tagAt(rest, 0) orelse return error.UncompiledPresentation;
            if (!child.is("span")) return error.UncompiledPresentation;
            const pair_child = translatedStyledChild(child, rest) orelse return error.UncompiledPresentation;
            const content = rest[child.end..pair_child.inner_end];
            if (content.len == 0 or std.mem.indexOfAny(u8, content, "\r\n") != null) return error.UncompiledPresentation;
            const css = (try self.semanticAttribute(child, "style")) orelse return error.UncompiledPresentation;
            const absolute = std.ascii.findIgnoreCase(css, "position") != null;
            const role: table_style_profile.TranslatedBoxRole = if (absolute) .absolute_label else .inline_atom;
            const box = (try self.translatedCardNode(child, owner.text, role, null, after_space)) orelse return error.UncompiledPresentation;
            if (absolute) {
                // Keep the original source position. This family has a suffix
                // label, with no intervening parent text or trailing siblings.
                if (after_space or atoms == 0 or pair_child.end != rest.len) return error.UncompiledPresentation;
                try self.appendBlockBudgeted(&blocks, .{ .kind = .container, .container = try self.translatedGlossaryBox(box, content) });
            } else {
                if (atoms == 0 and after_space) return error.UncompiledPresentation;
                const body = try self.a.alloc(Block, 1);
                body[0] = try self.translatedCardParagraph(content, box.text);
                try self.appendBlockBudgeted(&blocks, .{ .kind = .container, .container = .{ .style = box.box, .blocks = body } });
                atoms += 1;
            }
            cursor += pair_child.end;
        }
        if (atoms == 0) return error.UncompiledPresentation;
        const box: Container = .{ .style = owner.box, .blocks = try blocks.toOwnedSlice(self.a) };
        if (!presentation_types.validContainerHeader(box)) return error.UncompiledPresentation;
        return box;
    }

    fn appendEtymologyTree(self: *Renderer, blocks: *std.ArrayList(Block), input: []const u8, tag: syntax.Tag) Error!bool {
        if (!tag.is("div") or self.pre_block or self.parsed_pre) return false;
        var plan: EtymologyTreePlan = .{ .renderer = self };
        if (!(try plan.hasClass(tag, "etytree-body"))) return false;
        const roots = (try plan.sequence(input, &.{tag}, 0, false)) orelse {
            if (plan.limited) self.fallbacks.render_limit = true;
            return false;
        };
        const previous_implicit_list = self.figure_implicit_list_context;
        self.figure_implicit_list_context = true;
        defer self.figure_implicit_list_context = previous_implicit_list;
        // Indices are in source DOM order, including group labels after their
        // terms. Register content effects once before projecting parent-first.
        for (plan.nodes.items) |*node_value| {
            var hints: SemanticHints = .{ .relation_note = self.body_formatting_attributes.relation_note, .figure_blocks = true };
            const previous_capture = self.semantic_capture;
            self.semantic_capture = &hints;
            defer self.semantic_capture = previous_capture;
            const parent_italic = self.block_formatting.italic;
            const parent_poem_italic = self.poem_base_style.italic;
            defer self.block_formatting.italic = parent_italic;
            defer self.poem_base_style.italic = parent_poem_italic;
            var node_style = self.bodyFormattingStyle(self.body_language_direction orelse .{});
            for (node_value.scopes) |scope_tag| {
                node_style = try self.htmlInlineStyle(scope_tag, node_style);
                if (try self.htmlFontStyle(scope_tag)) |italic| {
                    self.block_formatting.italic = italic;
                    if (self.poem_depth != 0) self.poem_base_style.italic = italic;
                }
            }
            node_value.style = node_style;
            node_value.spans = try self.etymologyTreeSpans(node_value.*);
            node_value.relation_note = hints.relation_note;
        }
        try self.emitEtymologyTree(blocks, plan.nodes.items, roots[0], "");
        return true;
    }

    fn clippedAbsoluteEnclosurePrefix(source: MissingText, begin: usize, end: usize, text_allowed: bool) bool {
        if (begin > end or end > source.bytes.len) return false;
        if (begin != end and !noLiParentSourceRange(source, source.bytes[begin..end])) return false;
        var at = begin;
        while (at < end) {
            const byte = source.bytes[at];
            if (byte == '<') {
                if (syntax.protectedEnd(source.bytes, at)) |protected_end| {
                    if (protected_end > end or protected_end <= at) return false;
                    // The ordinary scanner may stop at an unmatched extension
                    // opener. Such a prefix cannot prove a root table enclosure.
                    if (syntax.tagAt(source.bytes, at)) |protected_tag| {
                        if (protected_tag.isOpaque() and !protected_tag.closing and
                            !protected_tag.self_closing and syntax.matchingTag(source.bytes, protected_tag) == null)
                            return false;
                    }
                    at = protected_end;
                    continue;
                }
                const tag = syntax.tagAt(source.bytes, at) orelse return false;
                if (tag.closing or tag.html_pre or tag.end > end) return false;
                if (tag.self_closing or oneOf(tag.name, &.{ "br", "hr", "wbr", "img", "meta", "link" })) {
                    at = tag.end;
                    continue;
                }
                const pair = syntax.matchingTag(source.bytes, tag) orelse return false;
                if (pair.end > end or pair.end <= tag.end) return false;
                const closing = syntax.tagAt(source.bytes, pair.inner_end) orelse return false;
                if (!closing.closing or !closing.is(tag.name) or closing.end != pair.end or trim(closing.attrs).len != 0)
                    return false;
                at = pair.end;
                continue;
            }
            if (!text_allowed and !std.ascii.isWhitespace(byte)) return false;
            // These physical line prefixes can create a non-HTML parent which
            // the native declaration chain does not contain. Refuse it rather
            // than treating a root-looking table/span as a complete enclosure.
            if (text_allowed and (at == begin or source.bytes[at - 1] == '\n') and
                std.mem.indexOfScalar(u8, " *#:;\t", byte) != null) return false;
            if (starts(source.bytes[at..], "{{") or starts(source.bytes[at..], "{|")) return false;
            if (byte == '[') {
                var tokens: ir.InlineIterator = .{ .input = source.bytes[at..], .renderer_boundaries = true };
                const token = tokens.next() orelse return false;
                if (token.kind != .link and token.kind != .external_link) return false;
                if (tokens.cursor == 0 or tokens.cursor > end - at) return false;
                at += tokens.cursor;
                continue;
            }
            at += 1;
        }
        return true;
    }

    fn positionedContainerInheritedFont(self: *Renderer, inherited: Style) ?presentation_types.InlineFontSnapshot {
        const effective = self.bodyFormattingStyle(inherited);
        if (effective.font_size_unknown or effective.heading or effective.code or effective.small or
            effective.superscript or effective.subscript or self.block_formatting.code or
            self.block_formatting.small or self.block_formatting.superscript or self.block_formatting.subscript) return null;
        var font = ordinaryActionScriptFont(effective, self.block_formatting);
        if (font.font_scale_basis == .context) {
            if (effective.font_scale_set or effective.font_scale != null or self.body_depth == 0 or self.in_reference or
                self.pre_block or self.parsed_pre or self.body_formatting_attributes.font_scale != null or
                self.body_formatting_attributes.font_scale_set or self.body_formatting_attributes.font_scale_basis != .context or
                self.body_formatting_attributes.font_size_unknown) return null;
            // This is the compiler's unchanged ordinary body metric, not an
            // observed CSS root or a guessed physical pixel font size.
            font.font_scale_basis = .normal_body; font.font_scale = 1;
        }
        return if (presentation_types.validContainerOwnerFont(font)) font else null;
    }

    const InlineOverlayParagraphSourceFact = struct {
        tag: syntax.Tag,
        entry: *const NativeInlineMotionDeclaration,
        source: MissingText,
        opening: []const u8,
        parent: ?*const table_style_profile.TextElement,
        source_key: usize,
        digest: [32]u8,
    };
    fn inlineOverlayParagraphNodeDigest(node: *const table_style_profile.TextElement, css: []const u8) [32]u8 {
        var hash = std.crypto.hash.sha2.Sha256.init(.{});
        for ([_][]const u8{ node.tag, node.classes, node.id, css }) |value| {
            NativeArticleHost.snapshotInteger(&hash, value.len); hash.update(value);
        }
        NativeArticleHost.snapshotInteger(&hash, @intFromBool(node.language != null));
        if (node.language) |value| { NativeArticleHost.snapshotInteger(&hash, value.len); hash.update(value); }
        NativeArticleHost.snapshotInteger(&hash, @intFromBool(node.observed_inline_style != null));
        if (node.observed_inline_style) |value| { NativeArticleHost.snapshotInteger(&hash, value.len); hash.update(value); }
        return hash.finalResult();
    }
    const InlineOverlayParagraphOperation = union(enum) {
        table: struct {
            pointer: *const LiteralWikiTableOperation,
            source: MissingText,
            snapshot: [32]u8,
            opening: []const u8,
            row: []const u8,
            attrs: []const u8,
            outer: ?*const table_style_profile.TextElement,
        },
        bullet: struct {
            pointer: *const OrdinaryBulletLink,
            source: []const u8,
            line: []const u8,
            body: []const u8,
            body_source: MissingText,
        },
    };
    // The Profile query borrows these exact source facts. current() is checked
    // afterward without rerunning CSS or allocating; deinit() always follows.
    const OwnedInlineOverlayParagraphSource = struct {
        path: table_style_profile.InlineOverlayParagraphSourcePath,
        host: *const NativeArticleHost,
        root: *const NativeInlineMotionRoot,
        source: MissingText,
        snapshot: [32]u8,
        epoch: u64,
        operation: InlineOverlayParagraphOperation,
        facts: []InlineOverlayParagraphSourceFact,
        fn deinit(value: @This(), a: A) void {
            a.free(value.path.current_first); a.free(value.facts); a.destroy(value.path.native_root);
        }
        fn current(value: @This(), renderer: *const Renderer) bool {
            if (!value.host.native_paragraph_css_subjects or !value.path.native_paragraph_css_subjects or
                renderer.context.observe_structure_only or renderer.content_root != .parser_output or
                renderer.in_reference or renderer.in_template_literal_scope or renderer.media_depth != 0 or
                renderer.poem_depth != 0 or renderer.ruby_depth != 0 or renderer.pre_block or renderer.parsed_pre or
                renderer.figure_caption_depth != 0 or renderer.html_list_item_flow or renderer.html_blockquote_flow or
                renderer.native_article_host != value.host or renderer.native_inline_motion_root != value.root or
                renderer.native_inline_motion_epoch != value.epoch or renderer.textPaintProfile() != value.path.profile or
                !NativeArticleHost.sameSource(value.root.source, value.source) or
                !value.host.matchesActive(renderer, value.source) or
                !std.mem.eql(u8, &value.snapshot, &(NativeArticleHost.snapshot(value.source) orelse return false)) or
                value.facts.len != value.path.current_first.len) return false;
            switch (value.operation) {
                .table => |operation| {
                    if (renderer.literal_wiki_table_operation != operation.pointer or renderer.typed_table_depth != 1 or
                        renderer.figure_implicit_list_context or renderer.table_viewport_cell_source != null) return false;
                    const live = operation.pointer;
                    if (!NativeArticleHost.sameSource(live.tracked, operation.source) or
                        !std.mem.eql(u8, &operation.snapshot, &(NativeArticleHost.snapshot(live.tracked) orelse return false)) or
                        !inlineOverlaySameSourceSlice(live.table_opening, operation.opening) or
                        !inlineOverlaySameSourceSlice(live.row_opening orelse return false, operation.row) or
                        !inlineOverlaySameSourceSlice(live.cell_attrs orelse return false, operation.attrs) or
                        live.outer_parent != operation.outer) return false;
                },
                .bullet => |operation| {
                    if (renderer.ordinary_bullet_link != operation.pointer or renderer.typed_table_depth != 0 or
                        !renderer.figure_implicit_list_context) return false;
                    const live = operation.pointer;
                    const body = renderer.body_missing orelse return false;
                    if (!NativeArticleHost.sameSource(body, operation.body_source) or
                        !inlineOverlaySameSourceSlice(live.source, operation.source) or
                        !inlineOverlaySameSourceSlice(live.line, operation.line) or
                        !inlineOverlaySameSourceSlice(live.body, operation.body) or
                        !noLiParentSourceRange(body, live.line)) return false;
                },
            }
            for (value.facts, value.path.current_first, 0..) |fact, node, index| {
                if (node.element.parent != fact.parent or node.element.source_key != fact.source_key or
                    node.element.observed_custom_environment != null or node.element.alternative_ancestry != null or
                    !NativeArticleHost.sameSource(fact.entry.source, fact.source) or
                    !inlineOverlaySameSourceSlice(fact.entry.opening, fact.opening) or
                    !noLiParentSourceRange(fact.entry.source, fact.entry.opening) or
                    !std.mem.eql(u8, fact.entry.opening, fact.entry.opening_snapshot) or
                    !std.mem.eql(u8, &fact.digest, &inlineOverlayParagraphNodeDigest(node.element, fact.entry.css)) or
                    fact.entry.previous != (if (index + 1 < value.facts.len) value.facts[index + 1].entry else null)) return false;
                if (value.path.kind == .bullet and renderer.nativeOriginalCopiedRange(value.source, fact.opening) == null) return false;
            }
            return true;
        }
    };

    fn inlineOverlayParagraphSourceOwned(self: *Renderer,
        kind: table_style_profile.InlineOverlayParagraphSourceKind,
        profile: *const table_style_profile.Profile, host: *const NativeArticleHost,
        root: *const NativeInlineMotionRoot, epoch: u64,
        tags: []const syntax.Tag, entries: []const *const NativeInlineMotionDeclaration,
        elements: []const *const table_style_profile.TextElement) Error!?OwnedInlineOverlayParagraphSource
    {
        if (tags.len != entries.len or entries.len != elements.len) return null;
        const snapshot = NativeArticleHost.snapshot(root.source) orelse return null;
        const operation: InlineOverlayParagraphOperation = switch (kind) {
            .wiki_table => table: {
                const live = self.literal_wiki_table_operation orelse return null;
                break :table .{ .table = .{ .pointer = live, .source = live.tracked,
                    .snapshot = NativeArticleHost.snapshot(live.tracked) orelse return null,
                    .opening = live.table_opening, .row = live.row_opening orelse return null,
                    .attrs = live.cell_attrs orelse return null, .outer = live.outer_parent } };
            },
            .bullet => bullet: {
                const live = self.ordinary_bullet_link orelse return null;
                break :bullet .{ .bullet = .{ .pointer = live, .source = live.source,
                    .line = live.line, .body = live.body, .body_source = self.body_missing orelse return null } };
            },
        };
        const facts = try self.a.alloc(InlineOverlayParagraphSourceFact, tags.len);
        errdefer self.a.free(facts);
        const nodes = try self.a.alloc(table_style_profile.InlineOverlayParagraphSourceNode, tags.len);
        errdefer self.a.free(nodes);
        for (tags, entries, elements, 0..) |tag, entry, element, index| {
            if (element.observed_custom_environment != null) { self.a.free(nodes); self.a.free(facts); return null; }
            facts[index] = .{ .tag = tag, .entry = entry, .source = entry.source, .opening = entry.opening,
                .parent = element.parent, .source_key = element.source_key,
                .digest = inlineOverlayParagraphNodeDigest(element, entry.css) };
            nodes[index] = .{ .element = element, .css = entry.css,
                .language = try self.semanticAttribute(tag, "lang"),
                .alignment_hint = try self.semanticAttribute(tag, "align"),
                .nowrap_present = (try self.semanticAttribute(tag, "nowrap")) != null,
                .attributes = .{ .ctx = &facts[index].tag, .get = htmlOwnAttributePresence } };
        }
        const native_root = try self.a.create(table_style_profile.TextElement);
        native_root.* = .{ .tag = "div", .classes = "mw-parser-output", .source_key = 0,
            .observed_inline_style = "", .ancestry_complete = true };
        const result: OwnedInlineOverlayParagraphSource = .{
            .path = .{ .kind = kind, .profile = profile, .current_first = nodes, .native_root = native_root,
                .native_paragraph_css_subjects = host.native_paragraph_css_subjects },
            .host = host, .root = root, .source = root.source, .snapshot = snapshot,
            .epoch = epoch, .operation = operation, .facts = facts };
        if (!result.current(self)) { result.deinit(self.a); return null; }
        return result;
    }

    fn inlineOverlaySameSourceSlice(left: []const u8, right: []const u8) bool {
        return left.ptr == right.ptr and left.len == right.len;
    }

    fn inlineOverlayCellPrefix(source: MissingText, begin: usize, end: usize) bool {
        if (begin > end or end > source.bytes.len or
            std.mem.indexOfAny(u8, source.bytes[begin..end], "\r\n") != null) return false;
        // Space after a cell delimiter is inline whitespace, not a page-level
        // preformatted-line marker. Preserve it in the body; skip only for proof.
        var at = begin;
        while (at < end and (source.bytes[at] == ' ' or source.bytes[at] == '\t')) : (at += 1) {}
        return (begin == at or noLiParentSourceRange(source, source.bytes[begin..at])) and
            clippedAbsoluteEnclosurePrefix(source, at, end, true);
    }

    fn inlineOverlayClosedWikiTable(source: MissingText, table_end: usize, cell_end: usize, category_owner: ?*const Renderer) bool {
        var at = table_end;
        if (at >= source.bytes.len or source.bytes[at] != '\n') return false;
        at += 1;
        var scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        while (at < source.bytes.len) {
            const end = wikiTableLineEndWithScan(source.bytes, at, &scan, &no_more_nowiki_close);
            if (end < at or end > source.bytes.len) return false;
            const line = trim(source.bytes[at..end]);
            if (wikiTableIndent(line) != null) return false;
            if (starts(line, "|}")) {
                if (at < cell_end or !noLiParentSourceRange(source, line)) return false;
                if (trim(line[2..]).len == 0) return true;
                // The normal table parser consumes exactly |}. Its already-qualified
                // category suffix is outside the closed table and remains available
                // to the ordinary parser. It cannot introduce an ancestor of a cell.
                const owner = category_owner orelse return false;
                return owner.context.namespace_catalog != null and owner.wikiFigureFontCloseTail(line[2..]);
            }
            at = if (end < source.bytes.len) end + 1 else end;
        }
        return false;
    }

    fn inlineBoxOverlayParagraphSource(self: *Renderer, element: *const table_style_profile.TextElement,
        state: NativeInlineMotionState) Error!?OwnedInlineOverlayParagraphSource
    {
        if (self.typed_table_depth == 0) return self.inlineBoxOverlayParagraphBulletSource(element, state);
        return self.inlineBoxOverlayTableSource(element, state, null);
    }

    const InlineBoxQuotedParagraph = struct {
        root: *const NativeInlineMotionRoot,
        epoch: u64,
        map: *const QuoteSourceMap,
    };

    // The body and whole-page parsers must agree before either a paired quote
    // map or a literal inline path can claim this physical paragraph.
    fn staticInlineParagraphInput(self: *Renderer, tracked: MissingText, inherited: Style, literal_owner: bool) bool {
        const raw = tracked.bytes;
        if (raw.len < 7 or raw.len > 16 * 1024 or
            std.mem.indexOfAny(u8, raw, "\r\n") != null or std.mem.indexOfScalar(u8, raw, '<') == null) return false;
        const hints = self.semantic_capture orelse return false;
        const host = self.native_article_host orelse return false;
        const held = switch (inherited.native_inline_motion) { .proved => |value| value, else => return false };
        if (!hints.ordinary_paragraph or !host.native_paragraph_css_subjects or !self.wikiClassOrdinaryDomain() or
            self.context.observe_structure_only or self.rejection_probe_scope or self.body_depth != 1 or
            self.media_depth != 0 or self.ruby_depth != 0 or self.figure_caption_depth != 0 or self.typed_table_depth != 0 or
            self.literal_wiki_table_operation != null or self.inline_table_boundaries != null or
            self.table_css_ancestor_classes.len != 0 or self.body_language_direction != null or inherited.text_element != null or
            held.last != null or held.epoch == 0 or self.native_inline_motion_root != held.root or
            self.native_inline_motion_epoch != held.epoch or held.root.reference != null or
            !QuoteSourceMap.clean(tracked) or !QuoteSourceMap.clean(held.root.source) or !QuoteSourceMap.clean(host.source) or
            !host.matchesActive(self, held.root.source)) return false;
        const line = self.wikiCellCurrentBodyRange(held.root.source, raw) orelse return false;
        if (literal_owner) {
            const dispatched = self.dispatched_static_paragraph orelse return false;
            if (!inlineOverlaySameSourceSlice(dispatched, line)) return false;
        }
        const local = @intFromPtr(line.ptr) - @intFromPtr(held.root.source.bytes.ptr);
        var page = held.root.source;
        var begin = local;
        if (host.active_fragment) |fragment| {
            // Whole-page and owner parsers separately dispatched the same source
            // line. A later rewrite cannot influence its source ancestry. The
            // Builder issued the unchanged original prefix on this page only.
            if (self.dispatched_static_paragraph) |dispatched| if (inlineOverlaySameSourceSlice(dispatched, line) and
                inlineOverlaySameSourceSlice(fragment.prepared, page.bytes) and fragment.start <= fragment.page.len and
                page.bytes.len <= fragment.page.len - fragment.start and
                std.mem.eql(u8, fragment.page[fragment.start..][0..page.bytes.len], page.bytes))
            {
                const start = fragment.start + local;
                const prefix = fragment.static_paragraph_original_prefix;
                if (start <= prefix.len and line.len <= prefix.len - start and
                    std.mem.eql(u8, prefix[start..][0..line.len], line) and
                    containsSortedOffset(fragment.static_paragraph_openings, start)) return true;
            };
            if (literal_owner) return false;
            const original = fragment.original_page orelse return false;
            if (!inlineOverlaySameSourceSlice(fragment.prepared, page.bytes) or fragment.start > fragment.page.len or
                page.bytes.len > fragment.page.len - fragment.start or original.len != fragment.page.len) return false;
            begin = fragment.start + local;
            if (begin > 16 * 1024 or !std.mem.eql(u8, original[0 .. begin + line.len], fragment.page[0 .. begin + line.len]) or
                !std.mem.eql(u8, fragment.page[begin..][0..line.len], line)) return false;
            page.bytes = fragment.page;
        } else if (!host.active_whole_page or !NativeArticleHost.sameSource(host.source, page)) return false;
        const end = begin + line.len;
        if (begin > 16 * 1024 or (begin != 0 and page.bytes[begin - 1] != '\n') or
            (end != page.bytes.len and page.bytes[end] != '\n' and page.bytes[end] != '\r') or
            !clippedAbsoluteEnclosurePrefix(page, 0, begin, true)) return false;
        return true;
    }

    fn inlineBoxQuotedSpanSiblings(interior: []const u8) bool {
        const special = "<>{}[]'\x7f\r\n";
        var cursor: usize = 0;
        var saw_span = false;
        while (std.mem.indexOfAnyPos(u8, interior, cursor, special)) |at| {
            const open = syntax.tagAt(interior, at) orelse return false;
            if (!open.is("span") or open.closing or open.self_closing or open.html_pre or
                !formattingAngleAttributesBalanced(open.attrs)) return false;
            const end = std.mem.indexOfAnyPos(u8, interior, open.end, special) orelse return false;
            const close = syntax.tagAt(interior, end) orelse return false;
            if (!close.closing or !close.is("span") or trim(close.attrs).len != 0) return false;
            cursor = close.end;
            saw_span = true;
        }
        return saw_span;
    }

    fn inlineBoxPairedBoldMap(map: *const QuoteSourceMap, raw: MissingText, quoted: MissingText) bool {
        if (!QuoteSourceMap.clean(raw) or !QuoteSourceMap.clean(quoted) or raw.bytes.len < 7 or quoted.bytes.len < 8 or
            !inlineOverlaySameSourceSlice(map.original, raw.bytes) or !inlineOverlaySameSourceSlice(map.output, quoted.bytes) or
            map.has_literal_quote_edits or map.generated.items.len < 2) return false;
        const open = map.generated.items[0];
        const close = map.generated.items[1];
        if (open.token != .b_open or open.output_start != 0 or open.quote_start != 0 or open.quote_end != 3 or
            close.token != .b_close or close.output_start < 3 or close.output_start > quoted.bytes.len - 4 or
            close.quote_start < 3 or close.quote_start > raw.bytes.len - 3 or close.quote_end != close.quote_start + 3 or
            !starts(quoted.bytes, "<b>") or !starts(raw.bytes, "'''") or !starts(raw.bytes[close.quote_start..], "'''") or
            !starts(quoted.bytes[close.output_start..], "</b>")) return false;
        const interior = map.copiedOriginal(quoted.bytes[3..close.output_start]) orelse return false;
        if (!inlineOverlaySameSourceSlice(interior, raw.bytes[3..close.quote_start]) or !inlineBoxQuotedSpanSiblings(interior)) return false;
        // The closed B and its copied children precede any independent italic runs.
        // A suffix with HTML or link structure is outside this paragraph grammar.
        if (std.mem.indexOfAny(u8, raw.bytes[close.quote_end..], "<>{}[]\x7f\r\n") != null) return false;
        var italic = false;
        for (map.generated.items[2..]) |record| {
            if (record.output_start < close.output_start + 4 or record.quote_start < close.quote_end or
                record.quote_start > raw.bytes.len - 2 or record.quote_end != record.quote_start + 2 or
                record.token != (if (italic) QuoteSourceMap.Token.i_close else .i_open) or
                !starts(raw.bytes[record.quote_start..], "''")) return false;
            italic = !italic;
        }
        return !italic;
    }

    fn inlineBoxQuotedParagraphClasses(self: *Renderer, element: *const table_style_profile.TextElement,
        state: NativeInlineMotionState) Error!?[]const u8
    {
        const issued = self.inline_box_quoted_paragraph orelse return null;
        const held = switch (state) { .proved => |value| value, else => return null };
        if (held.root != issued.root or held.root != self.native_inline_motion_root or
            held.epoch != issued.epoch or held.epoch != self.native_inline_motion_epoch) return null;
        const span = held.last orelse return null;
        const bold = span.previous orelse return null;
        const parent = element.parent orelse return null;
        if (span.origin != .html or bold.origin != .html or bold.previous != null or parent.parent != null or
            element.alternative_ancestry != null or parent.alternative_ancestry != null or
            !std.ascii.eqlIgnoreCase(parent.tag, "b") or parent.classes.len != 0 or parent.id.len != 0 or
            !std.ascii.eqlIgnoreCase(element.tag, "span") or !inlineOverlaySameSourceSlice(bold.opening, issued.map.output[0..3]) or
            parent.source_key != @intFromPtr(bold.opening[1..].ptr)) return null;
        const original = issued.map.copiedOriginal(span.opening) orelse return null;
        if (!wikiClassContains(issued.map.original[3..issued.map.generated.items[1].quote_start], original)) return null;
        const tag = syntax.tagAt(span.opening, 0) orelse return null;
        if (!tag.is("span") or tag.closing or tag.self_closing or tag.html_pre or tag.end != original.len or
            htmlOwnAttributePresence(&tag, "class") == .unknown or htmlOwnAttributePresence(&tag, "dir") != .absent or
            !std.mem.eql(u8, element.classes, (try self.semanticAttribute(tag, "class")) orelse "")) return null;
        if (element.source_key != @intFromPtr(tag.name.ptr)) {
            const mapped = self.quoteClassTag(tag) orelse return null;
            if (mapped.generated or mapped.source_key != element.source_key) return null;
        }
        // The static decoration resolver also revalidates every declaration and
        // its source opening before it consumes this property-local inventory.
        var classes: std.ArrayList(u8) = .empty;
        defer classes.deinit(self.a);
        try classes.appendSlice(self.a, native_source_root_class_tokens);
        nativeClassAppendTokens(self.a, &classes, element.classes) catch |failure| switch (failure) {
            error.OutOfMemory => return error.OutOfMemory,
            error.InvalidSourceClassInventory => return null,
        };
        return try classes.toOwnedSlice(self.a);
    }

    // This is a property-query-only inventory for a directly dispatched native table.
    // The existing positive selector and positioning APIs keep their own authorities.
    fn inlineBoxTableAncestorClasses(self: *Renderer, element: *const table_style_profile.TextElement,
        state: NativeInlineMotionState) Error!?[]const u8
    {
        const opening = self.inline_box_root_table_opening orelse return null;
        const receipt = (try self.inlineBoxOverlayTableSource(element, state, opening)) orelse return null;
        defer receipt.deinit(self.a);
        if (receipt.path.current_first.len != 4) return null;
        var classes: std.ArrayList(u8) = .empty;
        defer classes.deinit(self.a);
        try classes.appendSlice(self.a, native_source_root_class_tokens);
        for (receipt.path.current_first, receipt.facts) |node, fact| {
            if (htmlOwnAttributePresence(&fact.tag, "dir") != .absent or
                htmlOwnAttributePresence(&fact.tag, "class") == .unknown) return null;
            nativeClassAppendTokens(self.a, &classes, node.element.classes) catch |failure| switch (failure) {
                error.OutOfMemory => return error.OutOfMemory,
                error.InvalidSourceClassInventory => return null,
            };
        }
        if (!receipt.current(self) or !inlineOverlaySameSourceSlice(opening, self.inline_box_root_table_opening orelse return null)) return null;
        return try classes.toOwnedSlice(self.a);
    }

    fn inlineBoxOverlayTableSource(self: *Renderer, element: *const table_style_profile.TextElement,
        state: NativeInlineMotionState, dispatched_table: ?[]const u8) Error!?OwnedInlineOverlayParagraphSource
    {
        const held = switch (state) { .proved => |value| value, else => return null };
        const host = self.native_article_host orelse return null;
        const profile = self.textPaintProfile() orelse return null;
        if (!host.native_paragraph_css_subjects or self.context.observe_structure_only or self.content_root != .parser_output or
            self.native_inline_motion_root != held.root or self.native_inline_motion_epoch != held.epoch or
            held.epoch == 0 or held.root.reference != null or !host.matchesActive(self, held.root.source) or
            held.root.source.lost_missing_range or held.root.source.generated_source != null or
            self.typed_table_depth != 1 or self.table_viewport_cell_source != null or
            self.in_reference or self.media_depth != 0 or self.poem_depth != 0 or self.ruby_depth != 0 or
            self.pre_block or self.parsed_pre or self.figure_caption_depth != 0 or
            self.figure_implicit_list_context or self.html_list_item_flow or self.html_blockquote_flow)
            return null;
        const operation = self.literal_wiki_table_operation orelse return null;
        // This initial issuer handles a native fragment's own table. An outer
        // authored/generated holder needs its own paragraph authority.
        if (operation.outer_parent != null) return null;
        const operation_row = operation.row_opening orelse return null;
        const operation_attrs = operation.cell_attrs orelse return null;
        const declarations = (try self.nativeInlineMotionDeclarations(state)) orelse return null;
        defer self.a.free(declarations);
        if (declarations.len < 4 or declarations.len > max_depth + 1) return null;
        const html_count = declarations.len - 3;
        var entries: [max_depth + 1]*const NativeInlineMotionDeclaration = undefined;
        var tags: [max_depth + 1]syntax.Tag = undefined;
        var elements: [max_depth + 1]*const table_style_profile.TextElement = undefined;
        var cursor = held.last;
        var current: ?*const table_style_profile.TextElement = element;
        for (0..declarations.len) |index| {
            const entry = cursor orelse return null;
            const node = current orelse return null;
            if (node.alternative_ancestry != null) return null;
            for (entries[0..index]) |prior| if (prior == entry) return null;
            for (elements[0..index]) |prior| if (prior == node) return null;
            const expected_origin: NativeInlineMotionOrigin = if (index < html_count) .html
                else if (index == html_count) .wiki_td else if (index == html_count + 1) .wiki_row else .wiki_table;
            if (entry.origin != expected_origin) return null;
            const tag = if (entry.origin == .html) source: {
                const parsed = syntax.tagAt(entry.opening, 0) orelse return null;
                if (parsed.closing or parsed.self_closing or parsed.html_pre or parsed.end != entry.opening.len or
                    !(parsed.is("span") or parsed.is("bdi")) or
                    node.source_key != @intFromPtr(parsed.name.ptr)) return null;
                break :source parsed;
            } else (try self.nativeInlineMotionWikiTag(entry.origin, entry.opening)) orelse return null;
            if (!tag.is(node.tag) or !std.mem.eql(u8, declarations[index], entry.css) or
                !std.mem.eql(u8, node.classes, (try self.semanticAttribute(tag, "class")) orelse "") or
                !std.mem.eql(u8, node.id, (try self.semanticAttribute(tag, "id")) orelse "")) return null;
            if (index == 0 and !tag.is("span")) return null;
            entries[index] = entry; tags[index] = tag; elements[index] = node;
            cursor = entry.previous; current = node.parent;
        }
        if (cursor != null or current != operation.outer_parent) return null;
        const cell = entries[html_count];
        const row = entries[html_count + 1];
        const table = entries[html_count + 2];
        if (!inlineOverlaySameSourceSlice(row.opening, operation_row) or
            !inlineOverlaySameSourceSlice(tags[html_count].attrs, operation_attrs) or
            !noLiParentSourceRange(operation.tracked, cell.opening) or
            !noLiParentSourceRange(operation.tracked, operation_row) or
            !noLiParentSourceRange(operation.tracked, operation.table_opening)) return null;
        // A tracked-copy boundary is accepted only through the existing exact
        // registered-copy map. Equal text alone never joins two parser owners.
        const original_table = self.wikiCellCurrentBodyRange(held.root.source, table.opening) orelse return null;
        const operation_table = self.wikiCellCurrentBodyRange(held.root.source, operation.table_opening) orelse return null;
        const original_row = self.wikiCellCurrentBodyRange(held.root.source, row.opening) orelse return null;
        const original_cell = self.wikiCellCurrentBodyRange(held.root.source, cell.opening) orelse return null;
        if (!inlineOverlaySameSourceSlice(original_table, operation_table)) return null;
        const table_at = @intFromPtr(original_table.ptr) - @intFromPtr(held.root.source.bytes.ptr);
        const row_at = @intFromPtr(original_row.ptr) - @intFromPtr(held.root.source.bytes.ptr);
        const cell_at = @intFromPtr(original_cell.ptr) - @intFromPtr(held.root.source.bytes.ptr);
        if (table_at + original_table.len >= row_at or row_at + original_row.len >= cell_at or
            (table_at != 0 and held.root.source.bytes[table_at - 1] != '\n') or
            !(if (dispatched_table) |selected| inlineOverlaySameSourceSlice(original_table, selected) and
                inlineOverlaySameSourceSlice(selected, self.inline_box_root_table_opening orelse return null) and
                host.startsBoxTableRoot(self, held.root.source) else clippedAbsoluteEnclosurePrefix(held.root.source, 0, table_at, true)) or
            !inlineOverlayClosedWikiTable(held.root.source, table_at + original_table.len,
                cell_at + original_cell.len, if (dispatched_table != null) self else null)) return null;
        // The live cell delimiter owns its full first source line. Every HTML
        // ancestor must be an actually matched descendant in that same cell;
        // omitted PRE/list/foreign wrappers cannot acquire inherited defaults.
        const raw_cell = original_cell[1..];
        const content_at = if (cellAttributePipe(raw_cell)) |pipe| pipe + 1 else 0;
        var begin = cell_at + 1 + content_at;
        var end = cell_at + original_cell.len;
        var remaining = html_count;
        while (remaining != 0) {
            remaining -= 1;
            const original = self.wikiCellCurrentBodyRange(held.root.source, entries[remaining].opening) orelse return null;
            const at = @intFromPtr(original.ptr) - @intFromPtr(held.root.source.bytes.ptr);
            if (at < begin or at >= end or original.len > end - at or
                !inlineOverlayCellPrefix(held.root.source, begin, at)) return null;
            const opening = syntax.tagAt(held.root.source.bytes, at) orelse return null;
            if (opening.closing or opening.self_closing or opening.html_pre or
                opening.end != at + original.len or !opening.is(tags[remaining].name)) return null;
            const pair = syntax.matchingTag(held.root.source.bytes, opening) orelse return null;
            if (pair.inner_end < opening.end or pair.end > end) return null;
            const closing = syntax.tagAt(held.root.source.bytes, pair.inner_end) orelse return null;
            if (!closing.closing or !closing.is(opening.name) or closing.end != pair.end or
                trim(closing.attrs).len != 0 or
                !noLiParentSourceRange(held.root.source, held.root.source.bytes[pair.inner_end..pair.end])) return null;
            begin = opening.end; end = pair.inner_end;
        }
        return self.inlineOverlayParagraphSourceOwned(.wiki_table, profile, host, held.root, held.epoch,
            tags[0..declarations.len], entries[0..declarations.len], elements[0..declarations.len]);
    }

    // Map one continuous authored range through registered HTML and quote
    // copies. Generated or reconstructed bytes have no copy record.
    fn nativeOriginalCopiedRange(self: *const Renderer, root: MissingText, token: []const u8) ?[]const u8 {
        const mapped = self.nativeHtmlCopiedOpening(token) orelse return null;
        if (self.wikiCellCurrentBodyRange(root, mapped)) |original| return original;
        var cursor = self.native_quote_source;
        var remaining: usize = max_depth + 1;
        while (cursor) |domain| : (cursor = domain.parent) {
            if (remaining == 0) return null;
            remaining -= 1;
            if (!wikiClassContains(domain.output.bytes, mapped)) continue;
            if (!self.nativeQuoteDomainCurrent(domain) or
                domain.range.prepared.bytes.ptr != root.bytes.ptr or domain.range.prepared.bytes.len != root.bytes.len or
                !self.nativeQuoteContainingSourcesClean(mapped)) return null;
            const original = domain.map.copiedOriginal(mapped) orelse return null;
            return self.wikiCellCurrentBodyRange(root, original);
        }
        return null;
    }

    fn inlineBoxOverlayParagraphBulletSource(self: *Renderer, element: *const table_style_profile.TextElement,
        state: NativeInlineMotionState) Error!?OwnedInlineOverlayParagraphSource
    {
        const held = switch (state) { .proved => |value| value, else => return null };
        const host = self.native_article_host orelse return null;
        const profile = self.textPaintProfile() orelse return null;
        if (!host.native_paragraph_css_subjects or self.context.observe_structure_only or self.content_root != .parser_output or
            self.native_inline_motion_root != held.root or self.native_inline_motion_epoch != held.epoch or
            held.epoch == 0 or held.root.reference != null or !host.matchesActive(self, held.root.source) or
            held.root.source.lost_missing_range or held.root.source.generated_source != null or
            self.typed_table_depth != 0 or self.literal_wiki_table_operation != null or
            self.inline_table_boundaries != null or self.table_viewport_cell_source != null or
            !self.figure_implicit_list_context or self.html_list_item_flow or self.html_blockquote_flow or
            self.in_reference or self.in_template_literal_scope or self.media_depth != 0 or self.poem_depth != 0 or
            self.ruby_depth != 0 or self.pre_block or self.parsed_pre or self.block_formatting.code or
            self.figure_caption_depth != 0 or self.body_link_target.len != 0 or self.explicit_wiki_label != null)
            return null;
        // This existing receipt is installed only around the actual single '*'
        // native dispatch (not continuations, numbered or split list items).
        const operation = self.ordinary_bullet_link orelse return null;
        const body = self.body_missing orelse return null;
        if (!inlineOverlaySameSourceSlice(body.bytes, operation.source) or
            !noLiParentSourceRange(body, operation.line) or !wikiClassContains(operation.line, operation.body) or
            operation.line.len < 2 or operation.line[0] != '*' or
            std.mem.indexOfAny(u8, operation.line, "\r\n") != null or
            std.mem.indexOfScalar(u8, "*#:;", operation.line[1]) != null or
            !inlineOverlaySameSourceSlice(wikiListLineBody(operation.line[1..]), operation.body)) return null;
        const line = self.wikiCellCurrentBodyRange(held.root.source, operation.line) orelse return null;
        const raw_body = self.wikiCellCurrentBodyRange(held.root.source, operation.body) orelse return null;
        if (!inlineOverlaySameSourceSlice(wikiListLineBody(line[1..]), raw_body)) return null;
        const line_at = @intFromPtr(line.ptr) - @intFromPtr(held.root.source.bytes.ptr);
        if (line_at != 0 and held.root.source.bytes[line_at - 1] != '\n') return null;
        const declarations = (try self.nativeInlineMotionDeclarations(state)) orelse return null;
        defer self.a.free(declarations);
        if (declarations.len == 0 or declarations.len > max_depth + 1) return null;
        var entries: [max_depth + 1]*const NativeInlineMotionDeclaration = undefined;
        var tags: [max_depth + 1]syntax.Tag = undefined;
        var elements: [max_depth + 1]*const table_style_profile.TextElement = undefined;
        var original_openings: [max_depth + 1][]const u8 = undefined;
        var cursor = held.last;
        var current: ?*const table_style_profile.TextElement = element;
        for (0..declarations.len) |index| {
            const entry = cursor orelse return null;
            const node = current orelse return null;
            if (entry.origin != .html or node.alternative_ancestry != null) return null;
            for (entries[0..index]) |prior| if (prior == entry) return null;
            for (elements[0..index]) |prior| if (prior == node) return null;
            const tag = syntax.tagAt(entry.opening, 0) orelse return null;
            if (tag.closing or tag.self_closing or tag.html_pre or tag.end != entry.opening.len or
                !(tag.is("span") or tag.is("bdi")) or (index == 0 and !tag.is("span")) or
                !tag.is(node.tag) or node.source_key != @intFromPtr(tag.name.ptr) or
                !std.mem.eql(u8, declarations[index], entry.css) or
                !std.mem.eql(u8, node.classes, (try self.semanticAttribute(tag, "class")) orelse "") or
                !std.mem.eql(u8, node.id, (try self.semanticAttribute(tag, "id")) orelse "")) return null;
            const original = self.nativeOriginalCopiedRange(held.root.source, entry.opening) orelse return null;
            if (!wikiClassContains(raw_body, original) or !std.mem.eql(u8, original, entry.opening)) return null;
            entries[index] = entry; tags[index] = tag; elements[index] = node; original_openings[index] = original;
            cursor = entry.previous; current = node.parent;
        }
        if (cursor != null or current != null) return null;
        var begin = @intFromPtr(raw_body.ptr) - @intFromPtr(held.root.source.bytes.ptr);
        var end = begin + raw_body.len;
        var remaining = declarations.len;
        while (remaining != 0) {
            remaining -= 1;
            const original = original_openings[remaining];
            const at = @intFromPtr(original.ptr) - @intFromPtr(held.root.source.bytes.ptr);
            if (at < begin or at >= end or original.len > end - at or
                !inlineOverlayCellPrefix(held.root.source, begin, at)) return null;
            const tag = syntax.tagAt(held.root.source.bytes, at) orelse return null;
            if (tag.closing or tag.self_closing or tag.html_pre or tag.end != at + original.len or
                !tag.is(tags[remaining].name)) return null;
            const pair = syntax.matchingTag(held.root.source.bytes, tag) orelse return null;
            if (pair.inner_end < tag.end or pair.end > end) return null;
            const closing = syntax.tagAt(held.root.source.bytes, pair.inner_end) orelse return null;
            if (!closing.closing or !closing.is(tag.name) or closing.end != pair.end or trim(closing.attrs).len != 0 or
                !noLiParentSourceRange(held.root.source, held.root.source.bytes[pair.inner_end..pair.end])) return null;
            begin = tag.end; end = pair.inner_end;
        }
        return self.inlineOverlayParagraphSourceOwned(.bullet, profile, host, held.root, held.epoch,
            tags[0..declarations.len], entries[0..declarations.len], elements[0..declarations.len]);
    }

    fn inlineBoxOverlayText(self: *Renderer, tracked: MissingText, at: usize, tag: syntax.Tag,
        pair: syntax.Pair, effective: Style, inherited: Style, depth: usize) Error!*const presentation_types.InlineBoxOverlayContent(Span)
    {
        const owner = self.inline_box_owner orelse return error.UncompiledPresentation;
        const body = tracked.bytes[tag.end..pair.inner_end];
        if (!owner.text_content_allowed or tracked.unknown or !noLiParentSourceRange(tracked, tracked.bytes[at..pair.end]) or
            depth >= max_depth or body.len == 0 or std.mem.indexOfAny(u8, body, "<[{\r\n\t") != null or
            effective.kind != .text or effective.target.len != 0 or self.body_link_target.len != 0 or
            effective.self_link_target != null or effective.background != null or effective.image != null or
            effective.ordinary_action_origin != null or effective.ordinary_action_script != null or
            effective.ordinary_link_paint != null or effective.link_paint != null or effective.ruby_unitless_line_height != null or
            effective.underline or effective.strike or self.block_formatting.underline or self.block_formatting.strike or
            self.ruby_depth != 0 or self.spans.items.len > std.math.maxInt(u32)) return error.UncompiledPresentation;
        // A captured table's geometry-only receipt is not a text paragraph proof.
        if (self.table_viewport_cell_source) |scope| if (scope.closed_focus and scope.source_constructed)
            return error.UncompiledPresentation;
        var declaring = self.bodyFormattingStyle(effective);
        var font = self.positionedContainerInheritedFont(declaring) orelse return error.UncompiledPresentation;
        const flags: SpanFlags = .{ .bold = declaring.bold, .italic = declaring.italic, .code = declaring.code,
            .small = declaring.small, .superscript = declaring.superscript, .subscript = declaring.subscript,
            .underline = declaring.underline, .strike = declaring.strike };
        var used_flags: SpanFlags = @bitCast(@as(u8, @bitCast(flags)) | @as(u8, @bitCast(self.block_formatting)));
        if (declaring.authored_link_font_override or
            (if (comptime @hasField(Style, "paragraph_font_snapshot")) declaring.paragraph_font_snapshot else false)) {
            used_flags.bold = declaring.bold; used_flags.italic = declaring.italic;
        }
        font.bold = used_flags.bold; font.italic = used_flags.italic; font.code = used_flags.code;
        if (!presentation_types.validContainerOwnerFont(font)) return error.UncompiledPresentation;
        const profile = self.textPaintProfile() orelse return error.UncompiledPresentation;
        const css = (try self.semanticAttribute(tag, "style")) orelse "";
        const element = try self.textElement(tag, inherited.text_element, effective.language);
        const query_element = (try self.nativeSourceClassQuery(tag, profile, element, effective.native_inline_motion)) orelse element;
        const declarations = try self.nativeInlineMotionDeclarations(effective.native_inline_motion);
        defer if (declarations) |values| self.a.free(values);
        var metric_result = profile.resolveInlineBoxOverlayTextIn(self.a, query_element, css,
            self.customParent(effective), declarations, font) catch |failure| switch (failure) {
                error.OutOfMemory => return error.OutOfMemory,
                else => return error.UncompiledPresentation,
            };
        if (metric_result == null) {
            const paragraph_source = (try self.inlineBoxOverlayParagraphSource(query_element,
                effective.native_inline_motion)) orelse return error.UncompiledPresentation;
            defer paragraph_source.deinit(self.a);
            metric_result = profile.resolveInlineBoxOverlayTextFromSourceIn(self.a,
                self.customParent(effective), font, paragraph_source.path) catch |failure| switch (failure) {
                    error.OutOfMemory => return error.OutOfMemory,
                    else => return error.UncompiledPresentation,
                };
            if (!paragraph_source.current(self)) return error.UncompiledPresentation;
        }
        const metrics = metric_result orelse return error.UncompiledPresentation;
        const before_child: u32 = @intCast(self.spans.items.len);
        // The source grammar has no nested element or independent direction
        // owner. Its text inherits the completed Box/BDI context, not a second
        // auto-direction run over this detached paragraph.
        declaring.direction = ""; declaring.captured_direction = null;
        declaring.font_scale = font.font_scale; declaring.font_scale_basis = font.font_scale_basis;
        declaring.font_scale_set = true;
        const body_image = try self.a.dupe(u8, body);
        defer self.a.free(body_image);
        const previous_spans = self.spans;
        self.spans = .empty;
        defer self.spans = previous_spans;
        errdefer self.spans.deinit(self.a);
        const previous_owner = self.inline_box_owner;
        self.inline_box_owner = null;
        defer self.inline_box_owner = previous_owner;
        try self.inlineTextWithMissing(try self.borrowedInlineHtmlSlice(tracked, body), declaring, depth + 1);
        if (!std.mem.eql(u8, body, body_image) or !noLiParentSourceRange(tracked, tracked.bytes[at..pair.end]))
            return error.UncompiledPresentation;
        for (self.spans.items) |child| {
            if (!presentation_types.validInlineBoxOverlayTextChild(child) or child.font_size_unknown or
                child.pending_figure != null or child.pending_container != null or child.pending_bidi_scope != null or
                child.captured_bidi_scope != null or child.generated_link != null or child.external_literal_parameter != null or
                child.generated_diagnostic or (child.provenance != .parsed and child.provenance != .entity_literal))
                return error.UncompiledPresentation;
        }
        const value: presentation_types.InlineBoxOverlayContent(Span) = .{ .before_child = before_child, .owner_font = font, .line_height = metrics.line_height,
            .text_align = metrics.text_align, .spans = self.spans.items };
        if (!presentation_types.validInlineBoxOverlayContent(value)) return error.UncompiledPresentation;
        const content = try self.a.create(presentation_types.InlineBoxOverlayContent(Span));
        errdefer self.a.destroy(content);
        content.* = value;
        content.spans = try self.spans.toOwnedSlice(self.a);
        return content;
    }

    const BidiBoxSource = struct {
        renderer: *const Renderer,
        source: MissingText,
        body: []const u8,
        hash: [32]u8,
        profile: *const table_style_profile.Profile,
        element: *const table_style_profile.TextElement,
        input_domain: ?*const InlineSourceDomain,
        inherited_direction: []const u8,
        capture: ?*BidiCapture = null,
    };

    fn bidiBoxSourceShape(self: *Renderer, source: []const u8, parent: *const table_style_profile.TextElement,
        profile: *const table_style_profile.Profile, remaining: *usize, depth: usize) Error!bool
    {
        if (source.len == 0 or depth > max_depth or std.mem.indexOfAny(u8, source, "[]{}\r\n") != null) return false;
        var at: usize = 0;
        while (at < source.len) {
            if (source[at] != '<') { at += 1; continue; }
            if (remaining.* == 0) return false;
            remaining.* -= 1;
            const tag = syntax.tagAt(source, at) orelse return false;
            if (!tag.is("span") or tag.closing or tag.self_closing or tag.attr("dir") != null) return false;
            const pair = syntax.matchingTag(source, tag) orelse return false;
            if (pair.end > source.len) return false;
            const language = (try self.semanticAttribute(tag, "lang")) orelse (parent.language orelse "");
            const element = try self.textElement(tag, parent, language);
            const css = (try self.semanticAttribute(tag, "style")) orelse "";
            if (!try profile.sourceBidiScopeUnchanged(self.a, element, css)) return false;
            const content = source[tag.end..pair.inner_end];
            if (content.len != 0 and !try self.bidiBoxSourceShape(content, element, profile, remaining, depth + 1)) return false;
            at = pair.end;
        }
        return true;
    }

    fn beginBidiBoxSource(self: *Renderer, tracked: MissingText, at: usize, tag: syntax.Tag, pair: syntax.Pair,
        descriptor: BidiScope, style: Style, parent: ?*const table_style_profile.TextElement) Error!?BidiBoxSource
    {
        if (self.context.observe_structure_only or self.rejection_probe_scope or !tag.is("bdi") or
            descriptor.mode != .isolate or !descriptor.legacy_unicode or self.active_bidi_capture != null or
            self.bidi_scope_depth != 0 or self.bidi_box_source != null or
            (if (comptime @hasField(Renderer, "bidi_ruby_source")) self.bidi_ruby_source != null else false) or
            self.ruby_depth != 0 or self.explicit_wiki_label != null or self.body_link_target.len != 0 or
            self.in_reference or self.pre_block or self.parsed_pre or self.in_template_literal_scope or self.poem_depth != 0 or
            self.figure_caption_depth != 0 or self.inline_image_attribute or style.kind != .text or style.target.len != 0 or
            style.provenance != .parsed or style.code or style.self_link_target != null or !wikiClassCleanText(tracked) or
            !self.nativeQuoteContainingSourcesClean(tracked.bytes)) return null;
        const profile = self.context.table_styles orelse return null;
        if (self.textPaintProfile() != profile or profile.page_style_parent != null) return null;
        const body = tracked.bytes[tag.end..pair.inner_end];
        // A shape hint only selects this temporary receipt. An actual emitted
        // Box is required before choosing a typed scope at closure.
        if (std.mem.indexOfScalar(u8, body, '<') == null) return null;
        const element = try self.textElement(tag, parent, style.language);
        var remaining: usize = max_nodes;
        if (!try self.bidiBoxSourceShape(body, element, profile, &remaining, 0)) return null;
        if (!try self.bidiSourceEligible(try self.borrowedInlineHtmlSlice(tracked, tracked.bytes[at..tag.end]),
            try self.borrowedInlineHtmlSlice(tracked, tracked.bytes[pair.inner_end..pair.end]), body, element,
            (try self.semanticAttribute(tag, "style")) orelse "")) return null;
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(tracked.bytes, &digest, .{});
        return .{ .renderer = self, .source = tracked, .body = body, .hash = digest, .profile = profile,
            .element = element, .input_domain = self.inline_source_domain,
            .inherited_direction = style.captured_direction orelse style.direction };
    }

    fn bidiBoxSourceCurrent(self: *const Renderer, source: *const BidiBoxSource) bool {
        if (source.renderer != self or self.bidi_box_source != source or source.capture == null or
            self.active_bidi_capture != source.capture or self.bidi_scope_depth != 1 or
            self.context.observe_structure_only or self.rejection_probe_scope or self.context.table_styles != source.profile or
            self.textPaintProfile() != source.profile or source.profile.page_style_parent != null or
            !wikiClassCleanText(source.source) or !wikiClassContains(source.source.bytes, source.body) or
            !self.nativeQuoteContainingSourcesClean(source.source.bytes) or
            !nativeQuoteInlineDomainsClean(source.input_domain, source.source.bytes)) return false;
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(source.source.bytes, &digest, .{});
        return std.mem.eql(u8, &digest, &source.hash);
    }

    fn bidiBoxSourceChildren(self: *Renderer, values: []const Span, source: *const BidiBoxSource,
        remaining: *usize, depth: usize, found: *bool) Error![]const Span
    {
        if (depth >= presentation_types.max_content_depth or values.len > remaining.*) return error.RenderLimit;
        remaining.* -= values.len;
        const result = try self.a.dupe(Span, values);
        for (result) |*span| {
            if (span.kind != .text or span.target.len != 0 or span.direction.len != 0 or span.font_size_unknown or
                span.image != null or span.ruby != null or span.inline_padding_group != null or span.inline_action_group != null or
                presentation_types.spanHasClippedAbsolute(span.*) or span.pending_figure != null or span.pending_container != null or
                span.pending_bidi_scope != null or span.captured_bidi_scope != null or span.generated_link != null or
                span.generated_diagnostic or span.external_literal_parameter != null or span.bidi_auto_excluded or
                span.generated_bidi_boundary or (span.provenance != .parsed and span.provenance != .entity_literal))
                return error.UncompiledPresentation;
            if (span.captured_direction) |direction| {
                if (!std.mem.eql(u8, direction, source.inherited_direction)) return error.UncompiledPresentation;
                span.captured_direction = null;
            }
            if (span.inline_box_group) |original| {
                presentation_types.validateInlineBoxGroupTree(span.*, depth, 0) catch return error.UncompiledPresentation;
                found.* = true;
                const group = try self.a.create(presentation_types.InlineBoxGroup(Span)); group.* = original.*;
                group.spans = try self.bidiBoxSourceChildren(original.spans, source, remaining, depth + 1, found);
                if (original.overlays.len > remaining.*) return error.RenderLimit;
                remaining.* -= original.overlays.len;
                if (presentation_types.inlineBoxHasOverlayContent(original.*)) {
                    const overlays = try self.a.dupe(presentation_types.InlineBoxOverlayFor(Span), original.overlays);
                    for (overlays) |*overlay| if (overlay.content) |body| {
                        const content = try self.a.create(presentation_types.InlineBoxOverlayContent(Span)); content.* = body.*;
                        content.spans = try self.bidiBoxSourceChildren(body.spans, source, remaining, depth + 2, found);
                        overlay.content = content;
                    };
                    group.overlays = overlays;
                }
                span.inline_box_group = group;
            }
        }
        return result;
    }

    fn finishBidiBoxSource(self: *Renderer, source: *const BidiBoxSource, start: usize) Error!bool {
        if (!self.bidiBoxSourceCurrent(source)) return error.UncompiledPresentation;
        var has_box = false;
        for (self.spans.items[start..]) |span| has_box = has_box or span.inline_box_group != null;
        if (!has_box) return false; // Preserve the unchanged ordinary legacy path.
        var remaining: usize = max_nodes;
        if (!try self.bidiBoxSourceShape(source.body, source.element, source.profile, &remaining, 0))
            return error.UncompiledPresentation;
        remaining = max_nodes;
        var found = false;
        const children = try self.bidiBoxSourceChildren(self.spans.items[start..], source, &remaining, 0, &found);
        defer self.a.free(children);
        if (!found) return error.UncompiledPresentation;
        @memcpy(self.spans.items[start..], children);
        return true;
    }

    const BidiScope = struct {
        opening: []const u8,
        closing: []const u8 = "\xe2\x81\xa9",
        automatic: bool = false,
        mode: presentation_types.BidiMode = .isolate,
        authored_direction: ?presentation_types.BidiDirectionInput = null,
        language: ?[]const u8 = null,
        legacy_unicode: bool = true,
    };
    const unicode_bidi = @import("unicode_bidi.zig");

    fn firstBidiDirection(spans: []const Span) unicode_bidi.Direction {
        for (spans) |span| {
            if (span.bidi_auto_excluded) continue;
            var characters = (std.unicode.Utf8View.init(span.text) catch continue).iterator();
            while (characters.nextCodepoint()) |cp| if (unicode_bidi.strongDirection(cp)) |direction| return direction;
        }
        return .ltr; // HTML auto/undefined BDI with no strong descendant text.
    }

    const BidiTextScan = struct {
        remaining: usize = max_nodes,

        fn take(self: *BidiTextScan, count: usize) Error!void {
            if (count > self.remaining) return error.RenderLimit;
            self.remaining -= count;
        }
        fn spans(self: *BidiTextScan, values: []const Span, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            try self.take(values.len);
            var index: usize = 0;
            while (index < values.len) {
                const span = values[index];
                if (span.pending_figure) |pending| {
                    const end = try pendingFigureFallbackEnd(values, index, pending.*);
                    if (!span.bidi_auto_excluded) if (try self.figure(pending.*, depth)) |direction| return direction;
                    // Area labels are accessibility fallback siblings, not
                    // descendant DOM text. Match their occurrence ownership.
                    index = end;
                    continue;
                }
                index += 1;
                if (span.bidi_auto_excluded or span.generated_bidi_boundary or span.pending_bidi_scope != null) continue;
                if (span.inline_box_group) |group| {
                    presentation_types.validateInlineBoxGroupTree(span, depth.content, 0) catch return error.UncompiledPresentation;
                    const child_depth = try depth.contentChild();
                    try self.take(group.overlays.len);
                    var child_cursor: usize = 0;
                    for (group.overlays) |overlay| if (overlay.content) |body| {
                        if (try self.spans(group.spans[child_cursor..body.before_child], child_depth)) |direction| return direction;
                        if (try self.spans(body.spans, try child_depth.contentChild())) |direction| return direction;
                        child_cursor = body.before_child;
                    };
                    if (try self.spans(group.spans[child_cursor..], child_depth)) |direction| return direction;
                }
                var characters = (std.unicode.Utf8View.init(span.text) catch continue).iterator();
                while (characters.nextCodepoint()) |cp| if (unicode_bidi.strongDirection(cp)) |direction| return direction;
            }
            return null;
        }
        fn figure(self: *BidiTextScan, value: Figure, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            // The image's file, target, alternative and advice are attributes.
            return if (value.caption_blocks) |children| self.blocks(children, try depth.contentChild()) else self.spans(value.caption, depth);
        }
        fn flow(self: *BidiTextScan, parts: []const FlowPart, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            try self.take(parts.len);
            for (parts) |part| {
                const found = switch (part.kind) {
                    .@"inline" => try self.spans(part.spans, depth),
                    .figure => try self.figure(part.figure orelse return error.UncompiledPresentation, depth),
                    // A nested authored BDI/valid-dir scope is an exclusion,
                    // regardless of its own resolved direction or visible text.
                    .scope => null,
                };
                if (found) |direction| return direction;
            }
            return null;
        }
        fn blocks(self: *BidiTextScan, values: []const Block, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            try self.take(values.len);
            for (values) |value| {
                if (value.container) |container| if (try self.blocks(container.blocks, try depth.contentChild())) |direction| return direction;
                if (value.figure) |image| if (try self.figure(image, depth)) |direction| return direction;
                if (value.flow) |parts| if (try self.flow(parts, try depth.contentChild())) |direction| return direction;
                if (try self.spans(value.spans, depth)) |direction| return direction;
                if (value.table) |grid| if (try self.table(grid, try depth.nestedTable())) |direction| return direction;
            }
            return null;
        }
        fn table(self: *BidiTextScan, value: Table, depth: CaptionCatalogDepth) Error!?unicode_bidi.Direction {
            if (value.caption_blocks) |children| {
                if (try self.blocks(children, try depth.contentChild())) |direction| return direction;
            } else if (try self.spans(value.caption, depth)) |direction| return direction;
            try self.take(value.rows.len);
            for (value.rows) |row| {
                try self.take(row.cells.len);
                for (row.cells) |cell| {
                    if (cell.blocks) |children| {
                        if (try self.blocks(children, depth)) |direction| return direction;
                    } else {
                        if (try self.spans(cell.spans, depth)) |direction| return direction;
                        if (cell.nested_table) |grid| if (try self.table(grid, try depth.nestedTable())) |direction| return direction;
                    }
                }
            }
            return null;
        }
    };

    fn pendingFigureFallbackEnd(values: []const Span, index: usize, figure: Figure) Error!usize {
        const end = std.math.add(usize, index + 1, if (figure.map_fallback) |fallback| fallback.len else 0) catch return error.UncompiledPresentation;
        if (end > values.len) return error.UncompiledPresentation;
        if (figure.map_fallback) |fallback| for (fallback, values[index + 1 .. end]) |expected, actual| {
            if (!std.meta.eql(expected, actual) or actual.pending_figure != null or actual.pending_bidi_scope != null) return error.UncompiledPresentation;
        };
        return end;
    }

    fn resolvedBidiFigure(self: *Renderer, original: Figure, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error!Figure {
        var result = original;
        if (original.deferred_geometry) |deferred| {
            const direction = deferred.owner.resolved orelse return self.figureUnavailable();
            if (direction == .rtl) {
                result = deferred.rtl_geometry;
                result.content = original.content;
                result.intrinsic_size = original.intrinsic_size;
                result.caption = original.caption;
                result.caption_blocks = original.caption_blocks;
                result.map_fallback = original.map_fallback;
            }
            result.deferred_geometry = null;
        }
        result.content.spanPtr().* = (try self.resolvedBidiSpans(&.{result.content.span()}, depth, inherited_direction))[0];
        if (result.caption_blocks) |children| result.caption_blocks = try self.resolvedBidiBlocks(children, try depth.contentChild(), inherited_direction) else result.caption = try self.resolvedBidiSpans(result.caption, depth, inherited_direction);
        return result;
    }
    fn captureLegacyDirection(style: *Style) void {
        // Re-entering an implicit child owner must retain the pre-clear value.
        if (style.captured_direction == null) style.captured_direction = style.direction;
        style.direction = "";
    }
    fn resolvedBidiSpans(self: *Renderer, values: []const Span, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error![]const Span {
        var result: std.ArrayList(Span) = .empty;
        errdefer result.deinit(self.a);
        var index: usize = 0;
        while (index < values.len) {
            var span = values[index];
            if (span.captured_bidi_scope) |captured| {
                const count = captured.legacy_spans.len;
                if (!captured.source_eligible or count == 0 or count > values.len - index) return self.figureUnavailable();
                // Match the complete occurrence, not adjacent language/direction
                // values. A later mutation or partial copied interval refuses.
                for (captured.legacy_spans, values[index..][0..count]) |expected, actual| {
                    if (!std.meta.eql(expected, actual)) return self.figureUnavailable();
                }
                const nested = try self.resolvedBidiSpans(captured.spans, try depth.contentChild(), captured.authored_direction);
                const scope = try self.a.create(FlowScope);
                scope.* = .{ .mode = captured.mode, .authored_direction = captured.authored_direction,
                    .resolved_direction = captured.resolved_direction, .language = captured.language,
                    .parts = try self.bidiScopeParts(nested) };
                if (!presentation_types.validBidiScopeHeader(scope.*)) return self.figureUnavailable();
                if (!self.spend()) return error.RenderLimit;
                try result.append(self.a, .{ .text = "", .pending_bidi_scope = scope, .bidi_auto_excluded = true });
                index += count;
                continue;
            }
            // Validate the original occurrence before restoring any metadata.
            // A map's fallback is a paired sibling interval, not caption text.
            const fallback_end = if (span.pending_figure) |pending|
                try pendingFigureFallbackEnd(values, index, pending.*)
            else index + 1;
            if (span.captured_direction) |effective| {
                span.direction = effective;
                span.captured_direction = null;
            }
            // Direction remains effective span metadata. The typed scope owns
            // isolation; only a certified captured interval creates a child
            // scope, never equality with an inherited direction value.
            if (span.pending_figure) |pending| {
                const owned = try self.a.create(Figure);
                owned.* = try self.resolvedBidiFigure(pending.*, depth, inherited_direction);
                if (pending.map_fallback != null) {
                    // Transform once and retain these exact values in both the
                    // emitted sibling sequence and its private identity proof.
                    const fallback = try self.resolvedBidiSpans(values[index + 1 .. fallback_end], depth, inherited_direction);
                    owned.map_fallback = fallback;
                    span.pending_figure = owned;
                    try result.append(self.a, span);
                    try result.appendSlice(self.a, fallback);
                    index = fallback_end;
                    continue;
                }
                span.pending_figure = owned;
            }
            try result.append(self.a, span);
            index += 1;
        }
        return result.toOwnedSlice(self.a);
    }
    fn resolvedBidiFlow(self: *Renderer, values: []const FlowPart, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error![]const FlowPart {
        var result: std.ArrayList(FlowPart) = .empty;
        errdefer result.deinit(self.a);
        for (values) |part| switch (part.kind) {
            .@"inline" => {
                const spans = try self.resolvedBidiSpans(part.spans, depth, inherited_direction);
                if (hasPendingFigure(spans)) try result.appendSlice(self.a, try self.bidiScopeParts(spans)) else try result.append(self.a, .{ .kind = .@"inline", .spans = spans });
            },
            .figure => try result.append(self.a, .{ .kind = .figure, .figure = try self.resolvedBidiFigure(part.figure orelse return self.figureUnavailable(), depth, inherited_direction) }),
            .scope => {
                var scope = part.scope orelse return self.figureUnavailable();
                scope.parts = try self.resolvedBidiFlow(scope.parts, try depth.contentChild(), scope.authored_direction);
                try result.append(self.a, .{ .kind = .scope, .scope = scope });
            },
        };
        return result.toOwnedSlice(self.a);
    }
    fn resolvedBidiBlocks(self: *Renderer, values: []const Block, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error![]const Block {
        const result = try self.a.dupe(Block, values);
        for (result) |*value| {
            if (value.container) |*container| container.blocks = try self.resolvedBidiBlocks(container.blocks, try depth.contentChild(), inherited_direction);
            if (value.figure) |image| value.figure = try self.resolvedBidiFigure(image, depth, inherited_direction);
            if (value.flow) |parts| value.flow = try self.resolvedBidiFlow(parts, try depth.contentChild(), inherited_direction);
            value.spans = try self.resolvedBidiSpans(value.spans, depth, inherited_direction);
            if (value.table) |grid| value.table = try self.resolvedBidiTable(grid, try depth.nestedTable(), inherited_direction);
        }
        return result;
    }
    fn resolvedBidiTable(self: *Renderer, original: Table, depth: CaptionCatalogDepth, inherited_direction: ?presentation_types.BidiDirectionInput) Error!Table {
        var result = original;
        if (original.caption_blocks) |children| result.caption_blocks = try self.resolvedBidiBlocks(children, try depth.contentChild(), inherited_direction) else result.caption = try self.resolvedBidiSpans(original.caption, depth, inherited_direction);
        const rows = try self.a.dupe(Row, original.rows);
        result.rows = rows;
        for (rows) |*row| {
            const cells = try self.a.dupe(Cell, row.cells);
            row.cells = cells;
            for (cells) |*cell| {
                if (cell.blocks) |children| cell.blocks = try self.resolvedBidiBlocks(children, depth, inherited_direction) else {
                    cell.spans = try self.resolvedBidiSpans(cell.spans, depth, inherited_direction);
                    if (cell.nested_table) |grid| cell.nested_table = try self.resolvedBidiTable(grid, try depth.nestedTable(), inherited_direction);
                }
            }
        }
        return result;
    }

    fn validBidiDirection(self: *Renderer, tag: syntax.Tag) Error!bool {
        const raw = (try self.semanticAttribute(tag, "dir")) orelse return false;
        return std.ascii.eqlIgnoreCase(raw, "ltr") or std.ascii.eqlIgnoreCase(raw, "rtl") or std.ascii.eqlIgnoreCase(raw, "auto");
    }

    fn compiledBidiScope(self: *Renderer, tag: syntax.Tag) Error!?BidiScope {
        const raw = try self.semanticAttribute(tag, "dir");
        const direction: []const u8 = if (raw) |value|
            if (std.ascii.eqlIgnoreCase(value, "ltr")) "ltr" else if (std.ascii.eqlIgnoreCase(value, "rtl")) "rtl" else if (std.ascii.eqlIgnoreCase(value, "auto")) "auto" else ""
        else
            "";
        const authored = std.meta.stringToEnum(presentation_types.BidiDirectionInput, direction);
        const language = try self.semanticAttribute(tag, "lang");
        if (tag.is("bdo")) {
            if (std.mem.eql(u8, direction, "ltr")) return .{ .opening = "\xe2\x81\xa6\xe2\x80\xad", .closing = "\xe2\x80\xac\xe2\x81\xa9", .mode = .isolate_override, .authored_direction = authored, .language = language };
            if (std.mem.eql(u8, direction, "rtl")) return .{ .opening = "\xe2\x81\xa7\xe2\x80\xae", .closing = "\xe2\x80\xac\xe2\x81\xa9", .mode = .isolate_override, .authored_direction = authored, .language = language };
            return null; // Do not invent override semantics for an invalid/missing direction.
        }
        // BDI defaults to auto, not its DOM parent's direction. Explicit child
        // dir scopes inside a compiled bidi scope also span all styled atoms.
        if (!tag.is("bdi") and direction.len == 0) return null;
        return .{
            .opening = if (std.mem.eql(u8, direction, "rtl")) "\xe2\x81\xa7" else "\xe2\x81\xa6",
            .automatic = direction.len == 0 or std.mem.eql(u8, direction, "auto"),
            .authored_direction = authored,
            .language = language,
            .legacy_unicode = tag.is("bdi") or self.bidi_scope_depth != 0,
        };
    }

    fn independentBidiBlockOwner(self: *Renderer, source: []const u8) Error!bool {
        var scan: syntax.OpaqueScan = .{};
        var at: usize = 0;
        while (at < source.len) {
            if (starts(source[at..], "<!--")) {
                const end = std.mem.indexOfPos(u8, source, at + 4, "-->") orelse return false;
                at = end + 3;
                continue;
            }
            if (source[at] == '<') if (scan.tagAt(source, at, null)) |tag| {
                if (!tag.closing and (tag.isOpaque() or tag.html_pre or oneOf(tag.name, &.{ "nowiki", "script", "style", "textarea" }))) {
                    if (syntax.matchingTagWithOpaqueScan(source, tag, &scan)) |pair| { at = pair.end; continue; }
                }
                if (!tag.closing and oneOf(tag.name, &.{ "div", "p", "blockquote", "center", "ul", "ol", "dl", "li", "dt", "dd", "table", "tr", "td", "th", "caption", "h1", "h2", "h3", "h4", "h5", "h6" }) and try self.validBidiDirection(tag)) return true;
                at = tag.end;
                continue;
            };
            at += 1;
        }
        return false;
    }
    fn bidiSourceEligible(self: *Renderer, header: MissingText, closing: MissingText, content: []const u8, element: ?*const table_style_profile.TextElement, css: []const u8) Error!bool {
        if (header.ranges.len != 0 or header.literal_curly_ranges.len != 0 or header.generated_links.len != 0) return false;
        if (closing.ranges.len != 0 or closing.literal_curly_ranges.len != 0 or closing.generated_links.len != 0) return false;
        // A detached block's authored direction is not an inline-span proof.
        // Cross-array scope ownership remains an explicit unsupported case.
        if (try self.independentBidiBlockOwner(content)) return false;
        const profile = self.context.table_styles orelse return false;
        return profile.sourceBidiScopeUnchanged(self.a, element orelse return false, css);
    }
    fn bidiScopeParts(self: *Renderer, staged: []const Span) Error![]const FlowPart {
        // This temporary anonymous owner only extracts ordered parts. It does
        // not add a paragraph, margin, or list marker to the emitted document.
        const extracted = try self.extractFigures(&.{.{ .kind = .paragraph, .spans = staged }});
        if (extracted[0].flow) |ordered| return ordered;
        if (!self.spend()) return error.RenderLimit;
        const parts = try self.a.alloc(FlowPart, 1);
        parts[0] = if (extracted[0].figure) |image| .{ .kind = .figure, .figure = image } else .{ .kind = .@"inline", .spans = extracted[0].spans };
        return parts;
    }
    fn wrapFigureBidiSpans(self: *Renderer, start: usize, descriptor: BidiScope, capture: *BidiCapture, header: MissingText, closing: MissingText, content: []const u8, element: ?*const table_style_profile.TextElement, css: []const u8) Error!void {
        if (!(try self.bidiSourceEligible(header, closing, content, element, css))) return self.figureUnavailableAt("bidi_scope_source_unproven", header.bytes, 0, 0);
        const original = self.spans.items[start..];
        var scan: BidiTextScan = .{};
        const resolved: presentation_types.BidiResolvedDirection = if (descriptor.automatic)
            if (((try scan.spans(original, .{ .content = 2 })) orelse .ltr) == .rtl) .rtl else .ltr
        else if (descriptor.authored_direction == .rtl) .rtl else .ltr;
        capture.resolved = resolved;
        const staged = try self.resolvedBidiSpans(original, .{ .content = 2 }, descriptor.authored_direction);
        const parts = try self.bidiScopeParts(staged);
        const scope = try self.a.create(FlowScope);
        scope.* = .{ .mode = descriptor.mode, .authored_direction = descriptor.authored_direction, .resolved_direction = resolved, .language = descriptor.language, .parts = parts };
        if (!presentation_types.validBidiScopeHeader(scope.*)) return self.figureUnavailableAt("bidi_scope_header_invalid", header.bytes, 0, 0);
        if (!self.spend()) return error.RenderLimit;
        self.spans.items.len = start;
        try self.spans.append(self.a, .{ .text = "", .pending_bidi_scope = scope });
    }

    fn bidiBoundary(value: []const u8, neighbor: Span) Span {
        var result = neighbor;
        result.ruby = null;
        result.text = value;
        result.kind = .text;
        result.target = "";
        result.direction = "";
        result.captured_direction = null;
        result.explanation = "";
        result.explanation_set = false;
        result.tooltip = null;
        result.tooltip_set = false;
        result.provenance = .protected_literal;
        result.generated_bidi_boundary = true;
        result.generated_link = null;
        result.target_fragment = null;
        result.image = null;
        result.image_fields_compiled = false;
        result.pending_figure = null;
        result.pending_bidi_scope = null;
        result.captured_bidi_scope = null;
        result.nonfloating_image = false;
        result.nonfloating_image_alignment = null;
        // Retain layout classes (especially Poem) without creating an action.
        return result;
    }

    fn bidiSeparatorLength(value: []const u8) usize {
        if (value.len == 0) return 0;
        if (value[0] == '\n' or value[0] == '\r') return 1;
        if (starts(value, "\xe2\x80\xa8") or starts(value, "\xe2\x80\xa9")) return 3;
        return 0;
    }

    fn wrapBidiSpans(self: *Renderer, start: usize, scope: BidiScope) Error!void {
        const original = self.spans.items[start..];
        // Resolve auto once over the whole element, not once per output line.
        // Descendant text has already been decoded; raw link targets and HTML
        // attributes are not scan input. Authored Unicode isolates are not DOM
        // exclusions: their L/R/AL text still participates in this HTML rule.
        const opening: []const u8 = if (scope.automatic)
            if (firstBidiDirection(original) == .rtl) "\xe2\x81\xa7" else "\xe2\x81\xa6"
        else
            scope.opening;
        var wrapped: std.ArrayList(Span) = .empty;
        defer wrapped.deinit(self.a);
        var opened = false;
        var last: Span = .{ .text = "" };
        // Children have already consumed their normal budget. Build the entire
        // balanced replacement first; shortage preserves those children and
        // reports a limit, rather than dropping a generated PDF/PDI later.
        const maximum = original.len + (self.node_limit -| self.nodes);
        for (original) |span| {
            // This legacy Unicode wrapper cannot represent a compound Ruby scope.
            if (span.ruby != null or span.inline_padding_group != null or span.inline_action_group != null or span.inline_box_group != null) return error.UncompiledPresentation;
            if (span.text.len == 0) try wrapped.append(self.a, span);
            var offset: usize = 0;
            while (offset < span.text.len) {
                const separator = bidiSeparatorLength(span.text[offset..]);
                if (separator != 0 or span.kind == .line_break) {
                    if (opened) {
                        try wrapped.append(self.a, bidiBoundary(scope.closing, last));
                        opened = false;
                    }
                    var part = span;
                    const length = if (span.kind == .line_break) span.text.len - offset else separator;
                    part.text = span.text[offset .. offset + length];
                    if (span.generated_link != null) part = try generatedLabelSlice(span, part.text);
                    try wrapped.append(self.a, part);
                    offset += length;
                } else {
                    var end = offset + 1;
                    while (end < span.text.len and bidiSeparatorLength(span.text[end..]) == 0) : (end += 1) {}
                    if (!opened) {
                        try wrapped.append(self.a, bidiBoundary(opening, span));
                        opened = true;
                    }
                    var part = span;
                    part.text = span.text[offset..end];
                    if (span.generated_link != null) part = try generatedLabelSlice(span, part.text);
                    try wrapped.append(self.a, part);
                    last = part;
                    offset = end;
                }
                if (wrapped.items.len + @intFromBool(opened) > maximum) {
                    self.fallbacks.render_limit = true;
                    return;
                }
            }
        }
        if (opened) try wrapped.append(self.a, bidiBoundary(scope.closing, last));
        self.nodes += wrapped.items.len -| original.len;
        self.spans.items.len = start;
        try self.spans.appendSlice(self.a, wrapped.items);
    }

    fn htmlTag(self: *Renderer, input: []const u8, at: usize, style: Style, depth: usize, no_more_nowiki_close: ?*bool, opaque_scan: *syntax.OpaqueScan) Error!?usize {
        return self.htmlTagWithMissing(MissingText.untracked(input), at, style, depth, no_more_nowiki_close, opaque_scan, null);
    }
    // Select the existing block pass only for an authored physical closer in
    // this ordinary layout domain. Owned bodies and tag attributes cannot
    // trigger a change to surrounding layout merely by containing LF + |}.
    fn physicalLayoutTableClose(input: []const u8) bool {
        var scan: syntax.OpaqueScan = .{};
        var at: usize = 0;
        while (at < input.len) {
            if (at != 0 and input[at - 1] == '\n' and starts(input[at..], "|}")) return true;
            if (starts(input[at..], "<!--")) {
                const end = std.mem.indexOfPos(u8, input, at + 4, "-->") orelse return false;
                at = end + 3;
                continue;
            }
            if (input[at] == '<') if (scan.tagAt(input, at, null)) |tag| {
                if (!tag.closing and (tag.isOpaque() or tag.html_pre or
                    oneOf(tag.name, &.{ "nowiki", "pre", "ref", "references", "a", "script", "style", "iframe", "object", "embed" })))
                {
                    const pair = syntax.matchingTagWithOpaqueScan(input, tag, &scan) orelse return false;
                    at = pair.end;
                } else at = tag.end;
                continue;
            };
            if (starts(input[at..], "[[") or starts(input[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(input, at, &scan) orelse return false;
                at = pair.end;
                continue;
            }
            if (input[at] == '[') {
                if (!ir.hasExternalProtocol(input[at + 1 ..])) return false;
                var links: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true };
                const token = links.next() orelse return false;
                if (token.kind != .external_link) return false;
                at += links.cursor;
                continue;
            }
            at += 1;
        }
        return false;
    }

    fn knownInlineHtmlName(name: []const u8) bool {
        return oneOf(name, &.{
            "b",         "strong", "i",    "em", "u",          "s",      "del", "strike", "ins", "sup",  "sub", "small", "big",
            "span",      "font",   "code", "tt", "kbd",        "samp",   "var", "cite",   "dfn", "abbr", "q",   "time",  "mark",
            "bdi",       "bdo",    "ruby", "rb", "rt",         "rtc",    "rp",  "data",   "wbr", "h1",   "h2",  "h3",    "h4",
            "h5",        "h6",     "div",  "p",  "blockquote", "center", "ul",  "ol",     "li",  "dl",   "dt",  "dd",    "onlyinclude",
            "noinclude", "table",
        });
    }
    // Sanitizer::validateTag requires attribute presence, including minimized
    // and explicitly empty values. Ambiguous attribute syntax proves neither
    // validity nor absence; leave its existing strict handling unchanged.
    fn microdataRequiredAttributes(tag: syntax.Tag) ?bool {
        if (tag.closing or (!tag.is("link") and !tag.is("meta")) or tag.attrs.len > 4096) return null;
        var itemprop = false;
        var content = false;
        var href = false;
        var property = false;
        var at: usize = 0;
        while (at < tag.attrs.len) {
            while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) != null) : (at += 1) {}
            if (at == tag.attrs.len) break;
            const first = at;
            while (at < tag.attrs.len and (std.ascii.isAlphanumeric(tag.attrs[at]) or std.mem.indexOfScalar(u8, "_-:", tag.attrs[at]) != null)) : (at += 1) {}
            if (at == first) return null;
            const name = tag.attrs[first..at];
            if (!std.ascii.isAlphabetic(name[0]) and name[0] != '_' and name[0] != ':') return null;
            if (at < tag.attrs.len and tag.attrs[at] != '=' and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) == null) return null;
            itemprop = itemprop or std.ascii.eqlIgnoreCase(name, "itemprop");
            content = content or std.ascii.eqlIgnoreCase(name, "content");
            href = href or std.ascii.eqlIgnoreCase(name, "href");
            property = property or std.ascii.eqlIgnoreCase(name, "property");
            while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) != null) : (at += 1) {}
            if (at == tag.attrs.len or tag.attrs[at] != '=') continue;
            at += 1;
            while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) != null) : (at += 1) {}
            if (at == tag.attrs.len) break;
            const quote = tag.attrs[at];
            if (quote == '\'' or quote == '"') {
                at += 1;
                const close = std.mem.indexOfScalarPos(u8, tag.attrs, at, quote) orelse return null;
                if (std.mem.indexOfAny(u8, tag.attrs[at..close], "<>") != null) return null;
                at = close + 1;
                if (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) == null) return null;
            } else {
                while (at < tag.attrs.len and std.mem.indexOfScalar(u8, " \t\n\r\x0c", tag.attrs[at]) == null) : (at += 1) {
                    if (std.mem.indexOfScalar(u8, "<>'\"=", tag.attrs[at]) != null) return null;
                }
            }
        }
        const valid = itemprop and (if (tag.is("meta")) content else href);
        // The existing page-control handler decodes property before comparing
        // mw:PageProp/toc. Do not infer absence from its authored spelling.
        // Other property-bearing omissions retain their existing strict path.
        if (!valid and tag.is("meta") and property) return null;
        return valid;
    }

    fn rejectedMicrodataSource(tracked: MissingText, at: usize, tag: syntax.Tag) bool {
        if (microdataRequiredAttributes(tag) orelse return false) return false;
        return trackedMicrodataToken(tracked, at, tag);
    }

    // Sanitizer validates the attributes of closing tokens too. A bare
    // </link> has neither itemprop nor href, and its angles remain visible.
    fn rejectedBareLinkClose(tracked: MissingText, at: usize, tag: syntax.Tag) bool {
        if (!tag.closing or !tag.is("link") or tracked.lost_missing_range or !trackedMicrodataToken(tracked, at, tag)) return false;
        return std.ascii.eqlIgnoreCase(tracked.bytes[at..tag.end], "</link>");
    }

    fn trackedMicrodataToken(tracked: MissingText, at: usize, tag: syntax.Tag) bool {
        if (tracked.unknown or at >= tag.end or tag.end > tracked.bytes.len) return false;
        const original = syntax.tagAt(tracked.bytes, at) orelse return false;
        if (original.end != tag.end or original.name.ptr != tag.name.ptr or original.name.len != tag.name.len or
            original.attrs.ptr != tag.attrs.ptr or original.attrs.len != tag.attrs.len) return false;
        for (tracked.ranges) |range| if (range.start < tag.end and range.end > at) return false;
        for (tracked.literal_curly_ranges) |range| if (range.start < tag.end and range.end > at) return false;
        for (tracked.generated_links) |range| if (range.start < tag.end and range.end > at) return false;
        return true;
    }

    fn recognizedInlineHtmlName(name: []const u8) bool {
        return knownInlineHtmlName(name) or syntax.isOpaqueTag(name) or oneOf(name, &.{
            "br",     "meta",  "link",     "includeonly", "tr",     "td",    "th", "caption", "hr",
            "script", "style", "textarea", "iframe",      "object", "embed",
        });
    }
    fn ordinaryHtmlName(name: []const u8) bool {
        if (name.len == 0 or !std.ascii.isAlphabetic(name[0])) return false;
        for (name[1..]) |ch| if (!std.ascii.isAlphanumeric(ch) and ch != '-') return false;
        return true;
    }
    // Normalize escaped angles in the complete tracked inline stream.
    // Keep link/quote context continuous across the visible tag boundary.
    fn literalHtmlAnglesSourceWithMissing(self: *Renderer, tracked: MissingText) Error!MissingText {
        return self.literalHtmlAnglesSourceMapped(tracked, null, false);
    }
    fn prepareQuoteSource(self: *Renderer, tracked: MissingText, allow_quoted_terminal_dot: bool) Error!PreparedQuoteSource {
        var angles: std.ArrayList(usize) = .empty;
        errdefer angles.deinit(self.a);
        const source = try self.literalHtmlAnglesSourceMapped(tracked, &angles, allow_quoted_terminal_dot);
        errdefer {
            if (source.bytes.ptr != tracked.bytes.ptr) self.a.free(source.bytes);
            if (source.ranges.ptr != tracked.ranges.ptr) self.a.free(source.ranges);
            if (source.literal_curly_ranges.ptr != tracked.literal_curly_ranges.ptr) self.a.free(source.literal_curly_ranges);
        }
        return .{ .source = source, .angles = try angles.toOwnedSlice(self.a) };
    }
    fn normalizeBodyWikiQuotes(self: *Renderer, input: []const u8, seed: ?QuoteSeed) Error![]const u8 {
        const raw = MissingText.untracked(input);
        const prepared = try self.prepareQuoteSource(raw, false);
        errdefer prepared.release(self.a, raw, raw);
        const output = try normalizeWikiQuotesPreparedWithContext(self.a, prepared.source.bytes, 0, false, self.context, if (seed) |value| prepared.forwardSeed(value) else null);
        prepared.release(self.a, raw, MissingText.untracked(output));
        return output;
    }
    fn literalHtmlAnglesSourceMapped(self: *Renderer, tracked: MissingText, angles: ?*std.ArrayList(usize), allow_quoted_terminal_dot: bool) Error!MissingText {
        const input = tracked.bytes;
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var emitted: usize = 0;
        var scan: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        // Raw template arguments retain modifier syntax until their existing
        // handlers consume it. Complete unknown-name recovery applies only
        // outside these scopes; known-tag and extension dispatch is unchanged.
        const boundaries = QuoteBoundaries.init(input);
        var template_end: usize = 0;
        // Lookahead must not publish opaque misses into the earlier angle scan.
        var template_opaque_scan: syntax.OpaqueScan = .{};
        var quoted_bracket_depth: usize = 0;
        var quoted_html_end: usize = 0;
        var qualified_bracket_depth: usize = 0;
        const scan_bytes = "{<[]";
        while (std.mem.indexOfAnyPos(u8, input, scan, scan_bytes)) |at| {
            if (input[at] == '[' or input[at] == ']') {
                // Enter only at the maintained internal/external opener boundary.
                // A lone prose '[' is not an action. Once an action has started,
                // nested or unmatched brackets conservatively retain its hold.
                // Attributes and protected/template bodies are skipped separately.
                if (at >= template_end) {
                    if (input[at] == '[') {
                        if (qualified_bracket_depth != 0 or starts(input[at..], "[[") or
                            ir.hasExternalProtocol(input[at + 1 ..])) qualified_bracket_depth += 1;
                    } else if (qualified_bracket_depth != 0) qualified_bracket_depth -= 1;
                }
                // A new lexical proof never borrows a raw action/label domain.
                // Ambiguous unmatched brackets conservatively retain that hold.
                if (allow_quoted_terminal_dot and at >= template_end and at >= quoted_html_end) {
                    if (input[at] == '[') quoted_bracket_depth += 1 else if (quoted_bracket_depth != 0) quoted_bracket_depth -= 1;
                }
                scan = at + 1;
                continue;
            }
            if (input[at] == '{') {
                scan = at + 1;
