            std.mem.indexOfAny(u8, prior_label, ":;|{}[]<>&\r\n") != null or std.mem.indexOf(u8, prior_label, "''") != null) return null;
        for (input[start..links.cursor]) |byte| if (std.ascii.isControl(byte)) return null;
        const end = links.cursor + 2;
        const parent_start = offset + start;
        const parent_end = offset + end;
        for (tracked.ranges) |range| if (range.start < parent_end and range.end > parent_start) return null;
        for (tracked.literal_curly_ranges) |range| if (range.start < parent_end and range.end > parent_start) return null;
        for (tracked.generated_links) |range| if (range.start < parent_end and range.end > parent_start) return null;
        return end;
    }

    // Position only: a complete earlier formatted/multiple local-link scope
    // cannot contribute an unfinished ancestor to the current conversion.
    // This uses the original tracked bytes and admits only plain child labels;
    // it does not compile, flatten or grant converter choices to that sibling.
    fn precedingFormattedNestedLinksEnd(input: []const u8, start: usize, limit: usize, tracked: MissingText) ?usize {
        return precedingFormattedNestedLinksEndIn(input, start, limit, tracked, false);
    }
    fn precedingFormattedNestedLinksEndIn(input: []const u8, start: usize, limit: usize, tracked: MissingText, recursive_semantics: bool) ?usize {
        return precedingFormattedNestedLinksEndWithClassPipe(input, start, limit, tracked, recursive_semantics, null);
    }
    // Position only. The pinned ZH caller may cross a complete earlier form
    // whose quoted class pipe was armored before conversion upstream. Keep
    // the same balanced tags, plain labels and tracked interval requirements;
    // generic and KU callers retain their original pipe refusal.
    fn precedingFormattedNestedLinksEndWithClassPipe(input: []const u8, start: usize, limit: usize, tracked: MissingText, recursive_semantics: bool, class_owner: ?*const Renderer) ?usize {
        if (start > limit or limit > input.len or limit - start < 9 or limit - start > 4096 or
            !starts(input[start..limit], "-{") or (tracked.unknown and !recursive_semantics) or tracked.lost_missing_range or
            (recursive_semantics and tracked.generated_source != null)) return null;
        const input_ptr = @intFromPtr(input.ptr);
        const parent_ptr = @intFromPtr(tracked.bytes.ptr);
        if (input_ptr < parent_ptr) return null;
        const offset = input_ptr - parent_ptr;
        if (offset > tracked.bytes.len or input.len > tracked.bytes.len - offset) return null;
        var cursor = start + 2;
        var stack: [max_depth][]const u8 = undefined;
        var depth: usize = 0;
        var children: usize = 0;
        var formatted = false;
        var literal_sibling = false;
        while (cursor < limit) {
            if (starts(input[cursor..limit], "}-")) {
                // Preserve the old single bare-link/trailer refusal. New scope
                // is balanced formatting or multiple plain links with optional whitespace.
                if (depth != 0 or children == 0 or (!formatted and (children < 2 or literal_sibling))) return null;
                const end = cursor + 2;
                for (tracked.ranges) |range| if (range.start < offset + end and range.end > offset + start) return null;
                for (tracked.literal_curly_ranges) |range| if (range.start < offset + end and range.end > offset + start) return null;
                for (tracked.generated_links) |range| if (range.start < offset + end and range.end > offset + start) return null;
                return end;
            }
            if (input[cursor] == ' ' or input[cursor] == '\t') { cursor += 1; continue; }
            if (input[cursor] == '<') {
                const tag = syntax.tagAt(input[0..limit], cursor) orelse return null;
                const token = input[cursor..tag.end];
                if (!std.unicode.utf8ValidateSlice(token) or tag.self_closing or
                    !oneOf(tag.name, &.{ "b", "i", "strong", "em", "span", "sup", "small" }) or
                    !formattingAngleAttributesBalanced(tag.attrs) or
                    std.mem.indexOfAny(u8, token, "[]{}:;&\r\n") != null or
                    (std.mem.indexOfScalar(u8, token, '|') != null and
                        (!recursive_semantics or class_owner == null or !class_owner.?.sourceArmoredClassPipeTag(tag))) or
                    (tag.closing and trim(tag.attrs).len != 0)) return null;
                for (token) |byte| if (std.ascii.isControl(byte) and byte != '\t') return null;
                if (tag.closing) {
                    if (depth == 0 or !tag.is(stack[depth - 1])) return null;
                    depth -= 1;
                } else {
                    if (depth == stack.len) return null;
                    stack[depth] = tag.name;
                    depth += 1;
                }
                formatted = true;
                cursor = tag.end;
                continue;
            }
            if (starts(input[cursor..limit], "[[")) {
                var links: ir.InlineIterator = .{ .input = input[0..limit], .cursor = cursor, .renderer_boundaries = true };
                const link_node = links.next() orelse return null;
                if (link_node.kind != .link or !link_node.link_has_pipe or link_node.link_empty_label or link_node.link_label_restored_close or
                    links.cursor <= cursor or links.cursor > limit or link_node.trail.len != 0 or
                    !safeInternalTarget(link_node.target) or !manualConversionInternalTarget(link_node.target) or
                    !std.unicode.utf8ValidateSlice(input[cursor..links.cursor])) return null;
                for (input[cursor..links.cursor]) |byte| if (std.ascii.isControl(byte)) return null;
                const target = if (starts(link_node.target, ":")) link_node.target[1..] else link_node.target;
                const page = target[0 .. (std.mem.indexOfScalar(u8, target, '#') orelse target.len)];
                if (page.len == 0 or std.mem.indexOfScalar(u8, page, ':') != null or
                    link_node.text.len < 5 or !starts(link_node.text, "-{") or !std.mem.endsWith(u8, link_node.text, "}-")) return null;
                var title_buffer: [4096]u8 = undefined;
                var title_writer = std.Io.Writer.fixed(&title_buffer);
                @import("namespace_registry").normalizeSpacing(&title_writer, page) catch return null;
                if (title_writer.buffered().len == 0) return null;
                const label_ptr = @intFromPtr(link_node.text.ptr);
                if (label_ptr < input_ptr) return null;
                const label_at = label_ptr - input_ptr;
                if (label_at < cursor + 2 or label_at > links.cursor or link_node.text.len > links.cursor - label_at or
                    links.cursor - label_at - link_node.text.len != 2 or !starts(input[label_at + link_node.text.len .. links.cursor], "]]")) return null;
                const label = link_node.text[2 .. link_node.text.len - 2];
                if (trim(label).len == 0 or std.mem.indexOfAny(u8, label, ":;|{}[]<>&\r\n") != null or
                    std.mem.indexOf(u8, label, "''") != null or std.mem.indexOf(u8, label, "=>") != null) return null;
                children += 1;
                cursor = links.cursor;
                continue;
            }
            const begin = cursor;
            while (cursor < limit and input[cursor] != '<' and input[cursor] != '[' and
                !starts(input[cursor..limit], "}-")) : (cursor += 1) {}
            const literal_bytes = input[begin..cursor];
            if (literal_bytes.len == 0 or !std.unicode.utf8ValidateSlice(literal_bytes) or
                std.mem.indexOfAny(u8, literal_bytes, ":;|{}&]\"'") != null or std.mem.indexOf(u8, literal_bytes, "=>") != null) return null;
            for (literal_bytes) |byte| if (std.ascii.isControl(byte)) return null;
            literal_sibling = true;
        }
        return null;
    }

    fn recursivePositionInterval(source: MissingText, first: usize, last: usize) bool {
        if (first >= last or last > source.bytes.len or source.lost_missing_range or source.generated_source != null) return false;
        for (source.ranges) |range| if (range.start < last and range.end > first) return false;
        for (source.literal_curly_ranges) |range| if (range.start < last and range.end > first) return false;
        for (source.generated_links) |range| if (range.start < last and range.end > first) return false;
        return true;
    }

    fn recordConsumedUnclosedCenter(self: *Renderer, input: []const u8, at: usize, tag: syntax.Tag) Error!void {
        if (!tag.is("center") or tag.closing or tag.self_closing or trim(tag.attrs).len != 0) return;
        const domain = self.inline_source_domain orelse return;
        if (domain.source.ptr != input.ptr or domain.source.len != input.len) return;
        const tracked = domain.tracked orelse return;
        if (tracked.bytes.ptr != input.ptr or tracked.bytes.len != input.len or !recursivePositionInterval(tracked, at, tag.end)) return;
        const consumed = domain.consumed_unclosed_centers orelse return;
        if (consumed.items.len >= max_depth + 1) return;
        try consumed.append(self.a, at);
    }

    fn consumedUnclosedCenter(input: []const u8, at: usize, tag: syntax.Tag, live: ?*const InlineSourceDomain) bool {
        if (!tag.is("center") or tag.closing or tag.self_closing or trim(tag.attrs).len != 0) return false;
        const pointer = @intFromPtr(input.ptr);
        var current = live;
        var remaining: usize = max_depth + 1;
        while (current) |domain| {
            if (remaining == 0) return false;
            remaining -= 1; current = domain.parent;
            const base = @intFromPtr(domain.source.ptr);
            if (pointer < base or pointer - base > domain.source.len or input.len > domain.source.len - (pointer - base)) continue;
            const offset = pointer - base;
            const consumed = domain.consumed_unclosed_centers orelse continue;
            for (consumed.items) |start| if (start == offset + at) {
                const tracked = domain.tracked orelse return false;
                if (tracked.bytes.ptr != domain.source.ptr or tracked.bytes.len != domain.source.len or
                    !recursivePositionInterval(tracked, start, offset + tag.end)) return false;
                const original = syntax.tagAt(domain.source, start) orelse return false;
                return original.name.ptr == tag.name.ptr and original.end == offset + tag.end and
                    original.is("center") and !original.closing and !original.self_closing and trim(original.attrs).len == 0 and
                    syntax.matchingTag(domain.source, original) == null;
            };
        }
        return false;
    }

    // A successful ordinary inline parse can close a layout sibling before
    // a later converter label. This is position custody only: no source-clean,
    // ancestry, attribute, language, or stylesheet fact is issued here.
    fn recordConsumedClosedDiv(self: *Renderer, tracked: MissingText, at: usize, end: usize, style: Style) Error!void {
        if (self.context.content_conversion != true or !self.sourceRecursiveManualContext() or
            style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or self.in_reference or self.pre_block or self.parsed_pre or
            self.in_template_literal_scope or self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            self.navigation_target_probe != null or self.inline_image_attribute or
            tracked.bytes.len > 16 * 1024 or tracked.lost_missing_range or tracked.generated_source != null or
            at >= end or end > tracked.bytes.len) return;
        const frame = self.inline_source_domain orelse return;
        const ledger = frame.consumed_closed_divs orelse return;
        const own = frame.tracked orelse return;
        if (ledger.owner != frame or frame.source.ptr != tracked.bytes.ptr or frame.source.len != tracked.bytes.len or
            own.bytes.ptr != tracked.bytes.ptr or own.bytes.len != tracked.bytes.len or
            own.unknown != tracked.unknown or own.lost_missing_range or own.generated_source != null or
            own.ranges.ptr != tracked.ranges.ptr or own.ranges.len != tracked.ranges.len or
            own.literal_curly_ranges.ptr != tracked.literal_curly_ranges.ptr or own.literal_curly_ranges.len != tracked.literal_curly_ranges.len or
            own.generated_links.ptr != tracked.generated_links.ptr or own.generated_links.len != tracked.generated_links.len or
            ledger.source.ptr != tracked.bytes.ptr or ledger.source.len != tracked.bytes.len or ledger.ranges.items.len == 64) return;
        const tag = syntax.tagAt(tracked.bytes, at) orelse return;
        if (!tag.is("div") or tag.closing or tag.self_closing or tag.html_pre or !formattingAngleAttributesBalanced(tag.attrs)) return;
        const pair = syntax.matchingTag(tracked.bytes, tag) orelse return;
        if (pair.end != end or !recursivePositionInterval(tracked, at, end)) return;
        // The frame took this image before parsing any child, so a callback
        // mutation during the earlier DIV cannot enroll changed source bytes.
        const snapshot = ledger.snapshot orelse return;
        if (ledger.unknown != tracked.unknown or !std.mem.eql(u8, snapshot, tracked.bytes)) return;
        try ledger.ranges.append(self.a, .{ at, end });
    }

    fn consumedClosedDivEnd(input: []const u8, at: usize, limit: usize, tracked: MissingText,
        live: ?*const InlineSourceDomain) ?usize
    {
        if (at >= limit or limit > input.len or tracked.bytes.ptr != input.ptr or tracked.bytes.len != input.len or
            tracked.lost_missing_range or tracked.generated_source != null) return null;
        var frame = live;
        var remaining: usize = max_depth + 1;
        while (frame) |current| : (frame = current.parent) {
            if (remaining == 0) return null;
            remaining -= 1;
            if (current.source.ptr != input.ptr or current.source.len != input.len) continue;
            const ledger = current.consumed_closed_divs orelse return null;
            const owner = current.tracked orelse return null;
            const snapshot = ledger.snapshot orelse return null;
            if (ledger.owner != current or ledger.source.ptr != input.ptr or ledger.source.len != input.len or
                owner.bytes.ptr != input.ptr or owner.bytes.len != input.len or owner.unknown != tracked.unknown or
                ledger.unknown != tracked.unknown or owner.lost_missing_range or owner.generated_source != null or
                owner.ranges.ptr != tracked.ranges.ptr or owner.ranges.len != tracked.ranges.len or
                owner.literal_curly_ranges.ptr != tracked.literal_curly_ranges.ptr or owner.literal_curly_ranges.len != tracked.literal_curly_ranges.len or
                owner.generated_links.ptr != tracked.generated_links.ptr or owner.generated_links.len != tracked.generated_links.len or
                snapshot.len != input.len or !std.mem.eql(u8, snapshot, input)) return null;
            for (ledger.ranges.items) |range| {
                if (range[0] != at or range[1] > limit or range[0] >= range[1]) continue;
                if (!recursivePositionInterval(tracked, range[0], range[1])) return null;
                const tag = syntax.tagAt(input, at) orelse return null;
                if (!tag.is("div") or tag.closing or tag.self_closing or tag.html_pre or !formattingAngleAttributesBalanced(tag.attrs)) return null;
                const pair = syntax.matchingTag(input, tag) orelse return null;
                if (pair.end != range[1]) return null;
                return range[1];
            }
            return null;
        }
        return null;
    }

    // Position custody for the KU inherited no-rule evaluator only. The
    // preceding ordinary link has already been parsed by the caller. Crossing
    // its complete source interval does not issue an action or interwiki fact.
    fn precedingKuRuleFreeLabelLinkEnd(input: []const u8, start: usize, limit: usize, tracked: MissingText) ?usize {
        if (start >= limit or limit > input.len or limit - start > 4096 or !starts(input[start..limit], "[[")) return null;
        const base = @intFromPtr(tracked.bytes.ptr); const pointer = @intFromPtr(input.ptr);
        if (pointer < base or pointer - base > tracked.bytes.len or input.len > tracked.bytes.len - (pointer - base)) return null;
        var links: ir.InlineIterator = .{ .input = input[0..limit], .cursor = start, .renderer_boundaries = true };
        const prior_link = links.next() orelse return null;
        if (prior_link.kind != .link or !prior_link.link_has_pipe or prior_link.link_empty_label or prior_link.link_label_restored_close or
            prior_link.trail.len != 0 or links.cursor <= start or links.cursor > limit or
            !safeInternalTarget(prior_link.target) or !manualConversionInternalTarget(prior_link.target)) return null;
        const label_pointer = @intFromPtr(prior_link.text.ptr);
        if (label_pointer < pointer or label_pointer - pointer < start + 2 or label_pointer - pointer > links.cursor) return null;
        const label_start = label_pointer - pointer;
        if (prior_link.text.len > links.cursor - label_start or links.cursor - label_start - prior_link.text.len != 2 or
            !starts(input[label_start + prior_link.text.len .. links.cursor], "]]")) return null;
        if (!recursivePositionInterval(tracked, pointer - base + start, pointer - base + links.cursor) or
            !std.unicode.utf8ValidateSlice(prior_link.text)) return null;
        var cursor: usize = 0;
        var children: usize = 0;
        while (cursor < prior_link.text.len) {
            if (starts(prior_link.text[cursor..], "-{")) {
                const child = manualConversionExtent(prior_link.text, cursor) orelse return null;
                const body = child.body(prior_link.text);
                if (children == max_depth or trim(body).len == 0 or
                    std.mem.indexOfAny(u8, body, ":;|{}[]<>&\r\n") != null or
                    std.mem.indexOf(u8, body, "=>") != null or std.mem.indexOf(u8, body, "''") != null) return null;
                for (body) |byte| if (std.ascii.isControl(byte)) return null;
                children += 1;
                cursor = child.closing + 2;
                continue;
            }
            if (prior_link.text[cursor] == '&') {
                var scratch: [4]u8 = undefined;
                const decoded_entity = decodeEntity(prior_link.text[cursor..], &scratch, false) orelse return null;
                if (std.mem.indexOfAny(u8, decoded_entity.bytes, "[]{}<>&|\r\n") != null) return null;
                for (decoded_entity.bytes) |byte| if (std.ascii.isControl(byte)) return null;
                cursor += decoded_entity.consumed;
                continue;
            }
            if (std.mem.indexOfScalar(u8, "[]{}<>|:;", prior_link.text[cursor]) != null or
                std.ascii.isControl(prior_link.text[cursor]) or starts(prior_link.text[cursor..], "''")) return null;
            cursor += 1;
        }
        return if (children != 0) links.cursor else null;
    }

    fn formattingAngleBodyPositionWithTrackedSiblings(input: []const u8, at: usize, preceding_abbreviation: bool, tracked: ?MissingText) bool {
        return formattingAngleBodyPositionWithTrackedSiblingsIn(input, at, preceding_abbreviation, tracked, false);
    }
    fn formattingAngleBodyPositionWithTrackedSiblingsIn(input: []const u8, at: usize, preceding_abbreviation: bool, tracked: ?MissingText, recursive_semantics: bool) bool {
