        while (cursor < input.len and (input[cursor] >= 0x80 or std.ascii.isAlphanumeric(input[cursor]) or input[cursor] == '-')) : (cursor += 1) {}
        if (syntax.isOpaqueTag(input[name_start..cursor])) return false;
        if (cursor < input.len and !std.ascii.isWhitespace(input[cursor]) and input[cursor] != '<') return false;
        const boundary = std.mem.indexOfAnyPos(u8, input, cursor, "<>\r\n") orelse return true;
        return input[boundary] != '>';
    }
    // Sanitizer splits on each raw '<' before wiki-link parsing. These
    // source-local name fragments cannot be a registered HTML tag: either
    // the name is unfinished, or a wiki delimiter is part of the tag name.
    // No attribute, closing-tag, or complete HTML grammar is admitted here.
    fn wikiDelimitedHtmlName(input: []const u8, at: usize) bool {
        if (at >= input.len or input[at] != '<') return false;
        var cursor = at + 1;
        if (cursor >= input.len or !std.ascii.isAlphabetic(input[cursor])) return false;
        while (cursor < input.len and (std.ascii.isAlphanumeric(input[cursor]) or input[cursor] == '-')) : (cursor += 1) {}
        return cursor == input.len or input[cursor] == '#' or starts(input[cursor..], "]]");
    }

    fn hasExplicitWikiLabel(self: *const Renderer, style: Style) bool {
        const label = self.explicit_wiki_label orelse return false;
        return (style.kind == .link or style.kind == .external_link) and
            style.kind == label.kind and style.target.len != 0 and
            std.mem.eql(u8, style.target, label.target);
    }

    // Quote normalization can close B/I immediately before the parsed label's
    // end. Admit only that balanced suffix, never a pair before ordinary text.
    fn parsedLabelClosingPairSource(token: []const u8, label: []const u8) ?[]const u8 {
        if (label.len < 2 or !starts(token, "[[") or !std.mem.endsWith(u8, token, "]]")) return null;
        const base = @intFromPtr(token.ptr);
        const at = @intFromPtr(label.ptr);
        if (at < base or at - base < 3 or at - base > token.len - 2) return null;
        const offset = at - base;
        if (label.len != token.len - 2 - offset or token[offset - 1] != '|') return null;
        var first: usize = 0;
        var last = label.len;
        var seen: u2 = 0;
        for (0..3) |_| {
            if (last - first >= 2 and std.mem.endsWith(u8, label[first..last], "}}"))
                return label[last - 2 .. last];
            const bit: u2 = if (std.mem.endsWith(u8, label[first..last], "</b>")) 1 else
                if (std.mem.endsWith(u8, label[first..last], "</i>")) 2 else return null;
            if (seen & bit != 0) return null;
            seen |= bit;
            const close = last - 4;
            var scan = first;
            var opening_end: ?usize = null;
            while (std.mem.indexOfScalarPos(u8, label[0..close], scan, '<')) |opening| {
                if (syntax.protectedEnd(label, opening)) |end| {
                    if (end > close) return null;
                    scan = end;
                    continue;
                }
                const tag = syntax.tagAt(label, opening) orelse return null;
                if (!tag.closing and !tag.self_closing and tag.end - opening == 3 and
                    tag.is(if (bit == 1) "b" else "i"))
                {
                    const pair = syntax.matchingTag(label, tag) orelse return null;
                    if (pair.inner_end == close and pair.end == last) {
                        opening_end = tag.end;
                        break;
                    }
                }
                scan = tag.end;
                if (scan > close) return null;
            }
            first = opening_end orelse return null;
            last = close;
        }
        return null;
    }
    fn parsedLabelClosingPair(token: []const u8, label: []const u8) bool {
        return parsedLabelClosingPairSource(token, label) != null;
    }

    fn isExplicitLabelClosingPair(self: *const Renderer, style: Style, closing: []const u8) bool {
        if (!self.hasExplicitWikiLabel(style)) return false;
        const scope = self.explicit_wiki_label.?;
        const proof = scope.ordinary_closing_pair orelse return false;
        const token = scope.ordinary_token orelse return false;
        const label = scope.ordinary_label orelse return false;
        const source_pair = parsedLabelClosingPairSource(token, proof.source_label) orelse return false;
        const base = @intFromPtr(proof.current_label.ptr);
        const at = @intFromPtr(proof.current_pair.ptr);
        return style.target.ptr == scope.target.ptr and style.target.len == scope.target.len and
            token.ptr == proof.token.ptr and token.len == proof.token.len and
            label.ptr == proof.issued_label.ptr and label.len == proof.issued_label.len and
            source_pair.ptr == proof.source_pair.ptr and source_pair.len == proof.source_pair.len and
            at >= base and at - base <= proof.current_label.len and
            proof.current_pair.len == 2 and proof.current_pair.len <= proof.current_label.len - (at - base) and
            closing.len == 2 and closing.ptr == proof.current_pair.ptr and std.mem.eql(u8, closing, "}}");
    }

    // This exact metadata slice may allocate. Transport the already issued pair
    // by its source offset while preserving the original token and action.
    fn inlineTextWithLabelSourceSlice(self: *Renderer, parent: MissingText, child: []const u8, style: Style, depth: usize, borrowed: bool) Error!void {
        const sliced = if (borrowed) try self.borrowedInlineHtmlSlice(parent, child) else try missingSlice(self.a, parent, child);
        const previous_label = self.explicit_wiki_label;
        defer self.explicit_wiki_label = previous_label;
        if (self.explicit_wiki_label) |*scope| if (scope.ordinary_closing_pair) |*proof| {
            const base = @intFromPtr(parent.bytes.ptr);
            const start = @intFromPtr(child.ptr);
            const pair = @intFromPtr(proof.current_pair.ptr);
            if (start >= base and start - base <= parent.bytes.len and child.len <= parent.bytes.len - (start - base) and
                pair >= start and pair - start <= child.len and 2 <= child.len - (pair - start) and
                self.isExplicitLabelClosingPair(style, proof.current_pair))
            {
                proof.current_label = sliced.bytes;
                proof.current_pair = sliced.bytes[pair - start .. pair - start + 2];
            }
        };
        try self.inlineTextWithMissing(sliced, style, depth);
    }

    // A raw child tag interrupts this attempted attribute before its first
    // greater-than. Only the rejected opener's angle becomes literal; its
    // attribute text and the complete child keep ordinary inline processing.
    fn interruptedHtmlAttributeOpening(input: []const u8, at: usize) bool {
        var cursor = at + 1;
        const name_start = cursor;
        if (cursor >= input.len or !std.ascii.isAlphabetic(input[cursor])) return false;
        while (cursor < input.len and (std.ascii.isAlphanumeric(input[cursor]) or input[cursor] == '-')) : (cursor += 1) {}
        const name = input[name_start..cursor];
        if (!knownInlineHtmlName(name) or syntax.isOpaqueTag(name) or
            cursor >= input.len or !std.ascii.isWhitespace(input[cursor])) return false;
        const boundary = std.mem.indexOfAnyPos(u8, input, cursor, "<>") orelse return false;
        if (input[boundary] != '<') return false;
        // Wiki/action delimiters in the failed attribute prefix may own this
        // tag as a label child. They cannot prove an independent HTML child.
        if (std.mem.indexOfAny(u8, input[cursor..boundary], "[]{}") != null) return false;
        const child = syntax.tagAt(input, boundary) orelse return false;
        if (child.closing or child.self_closing or !knownInlineHtmlName(child.name) or syntax.isOpaqueTag(child.name)) return false;
        // Prove this complete child locally, including nested paired HTML.
        // Unknown, opaque, control, misnested and unfinished children cannot
        // promote the rejected outer opener into literal text. No outer
        // attribute/style authority or unbounded recursive search is added.
        var names: [max_depth][]const u8 = undefined;
        names[0] = child.name;
        var depth: usize = 1;
        cursor = child.end;
        while (true) {
            const next_at = std.mem.indexOfScalarPos(u8, input, cursor, '<') orelse return false;
            const next = syntax.tagAt(input, next_at) orelse return false;
            if (next.closing) {
                if (!next.is(names[depth - 1]) or trim(next.attrs).len != 0) return false;
                depth -= 1;
                if (depth == 0) return true;
            } else {
                if (next.self_closing or !syntax.pairedHtmlTag(next.name) or
                    !knownInlineHtmlName(next.name) or syntax.isOpaqueTag(next.name) or
                    depth == names.len) return false;
                names[depth] = next.name;
                depth += 1;
            }
            cursor = next.end;
        }
    }
    fn listSwitcherEditEnd(self: *Renderer, input: []const u8, tag: syntax.Tag) Error!?usize {
        if (!tag.is("span") or tag.closing or tag.self_closing) return null;
        const classes = (try self.semanticAttribute(tag, "class")) orelse return null;
        var tokens = std.mem.tokenizeAny(u8, classes, " \t\r\n\x0b\x0c");
        var edit_control = false;
        while (tokens.next()) |name| if (std.mem.eql(u8, name, "list-switcher-edit")) {
            edit_control = true;
            break;
        };
        if (!edit_control) return null;
        const pair = syntax.matchingTag(input, tag) orelse return null;
        const body = trim(input[tag.end..pair.inner_end]);
        var iterator: ir.InlineIterator = .{ .input = body, .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const token = iterator.next() orelse return null;
        const target_prefix = "Special:Edit/Template:list:";
        if (token.kind != .link or !token.link_has_pipe or token.trail.len != 0 or iterator.cursor != body.len or
            !starts(token.target, target_prefix) or token.target.len == target_prefix.len or
            !safeInternalTarget(token.target) or unresolvedActionTarget(token.target)) return null;
        // This complete list-template editing control is authoring chrome.
        // Its neighboring heading text and dictionary links remain ordinary data.
        return pair.end;
    }
    fn formattingBracketPrefixLink(raw: []const u8, label: []const u8) bool {
        const base = @intFromPtr(raw.ptr);
        const pointer = @intFromPtr(label.ptr);
        if (pointer < base or pointer - base > raw.len or label.len > raw.len - (pointer - base)) return false;
        const label_start = pointer - base;
        const label_end = label_start + label.len;
        var at: usize = 0;
        while (at < raw.len) {
            if (raw[at] == '<') {
                // Core leaves an explicit label's neutral empty strip marker
                // intact until its own parse. No other HTML earns prefix proof.
                const tag = syntax.tagAt(raw, at) orelse return false;
                if (at < label_start or tag.end > label_end or !tag.is("nowiki") or
                    tag.closing or !tag.self_closing or trim(tag.attrs).len != 0) return false;
                at = tag.end;
                continue;
            }
            if (std.mem.indexOfScalar(u8, ">{}", raw[at]) != null) return false;
            at += 1;
        }
        return true;
    }

    // A complete formatting child separates authored single brackets. Core
    // recognizes internal links before apostrophe formatting, so these visible
    // doubles must not become deferred link syntax after span concatenation.
    fn formattingBracketBodyPosition(input: []const u8, at: usize) bool {
        if (at > input.len or at > 4096) return false;
        var stack: [max_depth + 1][]const u8 = undefined;
        var depth: usize = 0;
        var cursor: usize = 0;
        while (cursor < at) {
            if (starts(input[cursor..], "{{")) return false;
            if (starts(input[cursor..], "[[")) {
                const pair = syntax.balanced(input[0..at], cursor) orelse return false;
                if (std.mem.indexOfAny(u8, input[cursor..pair.end], "<>{}") != null) return false;
                cursor = pair.end;
                continue;
            }
            if (input[cursor] == '[') {
                var links: ir.InlineIterator = .{ .input = input[cursor..at], .renderer_boundaries = true };
                const token = links.next() orelse return false;
                if (token.kind != .external_link or links.cursor > at - cursor) return false;
                const raw_link = input[cursor .. cursor + links.cursor];
                if (token.text.ptr == token.target.ptr) {
                    if (std.mem.indexOfAny(u8, raw_link, "<>{}") != null) return false;
                } else if (!formattingBracketPrefixLink(raw_link, token.text)) return false;
                cursor += links.cursor;
                continue;
            }
            if (input[cursor] == '<') {
                const tag = syntax.tagAt(input[0..at], cursor) orelse return false;
                var quote: u8 = 0;
                for (tag.attrs) |byte| {
                    if (quote != 0) {
                        if (byte == quote) quote = 0;
                    } else if (byte == '\'' or byte == '"') quote = byte;
                }
                if (quote != 0) return false;
                if (tag.is("br") and !tag.closing) {
                    cursor = tag.end;
                    continue;
                }
                if (tag.self_closing or !oneOf(tag.name, &.{ "b", "i", "strong", "em", "span", "u", "small", "big", "sub", "sup", "s", "strike", "del" })) return false;
                if (tag.closing) {
                    if (trim(tag.attrs).len != 0 or depth == 0 or !tag.is(stack[depth - 1])) return false;
                    depth -= 1;
                } else {
                    if (depth == stack.len) return false;
                    stack[depth] = tag.name;
                    depth += 1;
                }
                cursor = tag.end;
                continue;
            }
            cursor += 1;
        }
        return true;
    }

    // A complete ordinary [<format>text]</format>] contains two distinct
    // source closes. Removing the tag must not synthesize a deferred link close.
    // Protect only the last borrowed body byte; the body retains normal style.
    fn formattingCloseSeparatedBracket(self: *const Renderer, tracked: MissingText, at: usize, content: []const u8, style: Style) bool {
        const input = tracked.bytes;
        if (tracked.unknown or style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or self.parsed_pre or self.pre_block or
            self.in_template_literal_scope or self.in_reference or self.explicit_wiki_label != null or
            self.body_link_target.len != 0 or self.navigation_target_probe != null or self.inline_image_attribute or
            at == 0 or at >= input.len or input[at - 1] != '[' or (at > 1 and input[at - 2] == '[') or
            content.len < 2 or content.len > 4096 or content[content.len - 1] != ']' or
            trim(content[0 .. content.len - 1]).len == 0 or
            std.mem.indexOfAny(u8, content[0 .. content.len - 1], "[]<>{}&|'\"/:\r\n") != null) return false;
        const tag = syntax.tagAt(input, at) orelse return false;
        if (tag.closing or tag.self_closing or trim(tag.attrs).len != 0 or
            !oneOf(tag.name, &.{ "b", "i", "strong", "em", "u", "small", "big", "sub", "sup", "s", "strike", "del" }) or
            content.ptr != input[tag.end..].ptr) return false;
        const pair = syntax.matchingTag(input, tag) orelse return false;
        if (pair.inner_end != tag.end + content.len or pair.end >= input.len or input[pair.end] != ']' or
            (pair.end + 1 < input.len and input[pair.end + 1] == ']')) return false;
        const close = syntax.tagAt(input, pair.inner_end) orelse return false;
        if (!close.closing or close.self_closing or !close.is(tag.name) or trim(close.attrs).len != 0 or close.end != pair.end) return false;
        const first = at - 1;
        const last = pair.end + 1;
        for (tracked.ranges) |range| if (range.start < last and range.end > first) return false;
        for (tracked.literal_curly_ranges) |range| if (range.start < last and range.end > first) return false;
        for (tracked.generated_links) |range| if (range.start < last and range.end > first) return false;
        if (!formattingBracketBodyPosition(input, first)) return false;
        var domain = self.inline_source_domain orelse return false;
        var remaining: usize = max_depth + 1;
        while (true) {
            if (remaining == 0) return false;
            remaining -= 1;
            const base = @intFromPtr(domain.source.ptr);
            const pointer = @intFromPtr(input.ptr);
            if (pointer < base) return false;
            const relative = pointer - base;
            if (relative > domain.source.len or input.len > domain.source.len - relative or
                !formattingBracketBodyPosition(domain.source, relative + first) or
                (relative + last < domain.source.len and domain.source[relative + last] == ']')) return false;
            domain = domain.parent orelse break;
        }
        return true;
    }

    // A matched code example may deliberately spell its second opening brace
    // as an entity, keeping the enclosed wiki link active without invoking a
    // template. Only that complete borrowed example owns its raw closing pair.
    fn entityOpenedCodeExample(self: *const Renderer, tracked: MissingText, at: usize, content: []const u8, style: Style) bool {
        const input = tracked.bytes;
        if (tracked.unknown or style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or self.parsed_pre or self.pre_block or
            self.in_template_literal_scope or self.in_reference or self.explicit_wiki_label != null or
            self.body_link_target.len != 0 or self.navigation_target_probe != null or self.inline_image_attribute or
            content.len < 10 or content.len > 4096 or content[0] != '{' or !std.mem.endsWith(u8, content, "}}")) return false;
        const tag = syntax.tagAt(input, at) orelse return false;
        if (!tag.is("code") or tag.closing or tag.self_closing or trim(tag.attrs).len != 0 or
            content.ptr != input[tag.end..].ptr) return false;
        const pair = syntax.matchingTag(input, tag) orelse return false;
        if (pair.inner_end != tag.end + content.len) return false;
        const close = syntax.tagAt(input, pair.inner_end) orelse return false;
        if (!close.closing or !close.is("code") or trim(close.attrs).len != 0) return false;
        for (tracked.ranges) |range| if (range.start < pair.end and range.end > at) return false;
        for (tracked.literal_curly_ranges) |range| if (range.start < pair.end and range.end > at) return false;
        for (tracked.generated_links) |range| if (range.start < pair.end and range.end > at) return false;
        var buffer: [4]u8 = undefined;
        const opening = decodeEntity(content[1..], &buffer, false) orelse return false;
        if (!std.mem.eql(u8, opening.bytes, "{") or 1 + opening.consumed > content.len - 2) return false;
        const body = content[1 + opening.consumed .. content.len - 2];
        if (body.len <= 4 or !starts(body, "[[") or !std.mem.endsWith(u8, body, "]]")) return false;
        // Child action validation stays on the ordinary path. Refuse nested
        // syntax instead of granting literal authority to an arbitrary code body.
        return trim(body[2 .. body.len - 2]).len != 0 and
            std.mem.indexOfAny(u8, body[2 .. body.len - 2], "[]{}<>&'\"\r\n") == null;
    }

    fn pairedFormattingBrackets(self: *const Renderer, tracked: MissingText, at: usize, content: []const u8, style: Style) bool {
        const input = tracked.bytes;
        if (tracked.unknown or style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or self.parsed_pre or self.pre_block or
            self.in_template_literal_scope or self.in_reference or self.explicit_wiki_label != null or
            self.body_link_target.len != 0 or self.navigation_target_probe != null or self.inline_image_attribute or
            at == 0 or at >= input.len or input[at - 1] != '[' or (at > 1 and input[at - 2] == '[') or
            content.len < 3 or content.len > 256 or content[0] != '[' or content[content.len - 1] != ']' or
            trim(content[1 .. content.len - 1]).len == 0 or
            std.mem.indexOfAny(u8, content[1 .. content.len - 1], "[]<>{}&|'\"/:\r\n") != null) return false;
        const tag = syntax.tagAt(input, at) orelse return false;
        if (!oneOf(tag.name, &.{ "b", "i", "strong", "em" }) or tag.closing or tag.self_closing or trim(tag.attrs).len != 0 or
            content.ptr != input[tag.end..].ptr) return false;
        const pair = syntax.matchingTag(input, tag) orelse return false;
        if (pair.inner_end != tag.end + content.len or pair.end >= input.len or input[pair.end] != ']' or
            (pair.end + 1 < input.len and input[pair.end + 1] == ']')) return false;
        const close = syntax.tagAt(input, pair.inner_end) orelse return false;
        if (!close.closing or !close.is(tag.name) or trim(close.attrs).len != 0) return false;
        const first = at - 1;
        const last = pair.end + 1;
        for (tracked.ranges) |range| if (range.start < last and range.end > first) return false;
        for (tracked.literal_curly_ranges) |range| if (range.start < last and range.end > first) return false;
        for (tracked.generated_links) |range| if (range.start < last and range.end > first) return false;
        if (!formattingBracketBodyPosition(input, first)) return false;
        var domain = self.inline_source_domain orelse return false;
        var remaining: usize = max_depth + 1;
        while (true) {
            if (remaining == 0) return false;
            remaining -= 1;
            const base = @intFromPtr(domain.source.ptr);
            const pointer = @intFromPtr(input.ptr);
            if (pointer < base) return false;
            const relative = pointer - base;
            if (relative > domain.source.len or input.len > domain.source.len - relative or
                !formattingBracketBodyPosition(domain.source, relative + first) or
                (relative + last < domain.source.len and domain.source[relative + last] == ']')) return false;
            domain = domain.parent orelse break;
        }
        if (self.spans.items.len == 0) return false;
        const previous = self.spans.items[self.spans.items.len - 1];
        return previous.kind == .text and previous.provenance == .parsed and previous.target.len == 0 and !previous.self_link and
            previous.image == null and !previous.generated_diagnostic and !previous.flags.code and previous.text.len != 0 and
            previous.text[previous.text.len - 1] == '[' and previous.text[previous.text.len - 1 ..].ptr == input[first..].ptr;
    }

    fn protectFormattingBracketTail(self: *Renderer, borrowed: []const u8) Error!void {
        if (borrowed.len != 1 or self.spans.items.len == 0) return error.InvalidLiteralProvenance;
        const index = self.spans.items.len - 1;
        const last = self.spans.items[index];
        if (last.kind != .text or last.provenance != .parsed or last.target.len != 0 or last.self_link or
            last.image != null or last.generated_diagnostic or last.flags.code or last.text.len == 0 or
            last.text[last.text.len - 1 ..].ptr != borrowed.ptr) return error.InvalidLiteralProvenance;
        var bracket = last;
        bracket.text = borrowed;
        bracket.provenance = .protected_literal;
        if (last.text.len == 1) self.spans.items[index] = bracket else {
            try self.spans.append(self.a, bracket);
            self.spans.items[index].text = last.text[0 .. last.text.len - 1];
        }
    }

    // Two authored single closes separated by a complete formatting element
    // are visible punctuation, not a reconstructed wiki-link instruction.
    // Preserve only the borrowed preceding byte; the child keeps normal style.
    fn preserveFormattingClosingBracket(self: *Renderer, input: []const u8, at: usize, content: []const u8, style: Style) Error!void {
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.body_link_target.len != 0 or
            self.in_template_literal_scope or at == 0 or at >= input.len or
            input[at - 1] != ']' or (at > 1 and input[at - 2] == ']') or
            content.len != 1 or content[0] != ']' or self.spans.items.len == 0) return;
        const tag = syntax.tagAt(input, at) orelse return;
        const flags = blockFormattingFlags(tag) orelse return;
        if (flags.code or trim(tag.attrs).len != 0 or content.ptr != input[tag.end..].ptr) return;
        const pair = syntax.matchingTag(input, tag) orelse return;
        if (pair.inner_end != tag.end + 1 or (pair.end < input.len and input[pair.end] == ']')) return;
        const close = syntax.tagAt(input, pair.inner_end) orelse return;
        if (!close.closing or !close.is(tag.name) or trim(close.attrs).len != 0) return;
        var domain = self.inline_source_domain orelse return;
        var remaining: usize = max_depth + 1;
        while (true) {
            if (remaining == 0) return;
            remaining -= 1;
            const base = @intFromPtr(domain.source.ptr);
            const pointer = @intFromPtr(input.ptr);
            if (pointer < base) return;
            const relative = pointer - base;
            if (relative > domain.source.len or input.len > domain.source.len - relative) return;
            const preceding = relative + at - 1;
            if (preceding != 0 and domain.source[preceding - 1] == ']') return;
            domain = domain.parent orelse break;
        }
        const last = self.spans.items[self.spans.items.len - 1];
        if (last.kind != .text or last.provenance != .parsed or last.target.len != 0 or last.self_link or
            last.image != null or last.generated_diagnostic or last.flags.code or
            last.text.len == 0 or last.text[last.text.len - 1] != ']' or
            last.text[last.text.len - 1 ..].ptr != input[at - 1 ..].ptr) return;
        var bracket = last;
        bracket.text = last.text[last.text.len - 1 ..];
        bracket.provenance = .protected_literal;
        if (last.text.len == 1) {
            self.spans.items[self.spans.items.len - 1] = bracket;
        } else {
            try self.spans.append(self.a, bracket);
            self.spans.items[self.spans.items.len - 2].text = last.text[0 .. last.text.len - 1];
        }
    }
    // An ordinary matched span opener can separate two authored single '['
    // bytes. Preserve only the preceding raw byte, never a decoded bracket or
    // a raw internal opener, while the child keeps ordinary parsing and style.
    fn preserveSpanOpeningBracket(self: *Renderer, input: []const u8, at: usize, content: []const u8, style: Style) Error!void {
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.code or style.preserve_whitespace or
            self.body_link_target.len != 0 or at == 0 or at > input.len or input[at - 1] != '[' or
            (at > 1 and input[at - 2] == '[') or content.len == 0 or content[0] != '[' or
            self.spans.items.len == 0) return;
        var child: ir.InlineIterator = .{ .input = content, .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const first = child.next() orelse return;
        if (first.literal_tail or first.rejected_external_opener or first.text.len == 0 or first.text[0] != '[') return;
        if (first.kind == .text) {
            if (first.text.ptr != content.ptr) return;
        } else if (first.kind == .link) {
            // A piped label can author the second single '[' across this span.
            // Only the preceding byte is protected; the child keeps normal action validation.
            if (!first.link_has_pipe or first.text.len > 1 and first.text[1] == '[' or
                first.target.len == 0 or !safeInternalTarget(first.target) or unresolvedActionTarget(first.target) or
                std.mem.indexOfAny(u8, first.target, "<>&") != null) return;
            const base = @intFromPtr(content.ptr);
            const label = @intFromPtr(first.text.ptr);
            if (label < base or label - base < 3 or label - base >= content.len) return;
            const offset = label - base;
            if (first.text.len > content.len - offset or content[offset - 1] != '|') return;
        } else return;
        var domain = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        while (domain) |current| {
            if (remaining == 0) return;
            remaining -= 1;
            const base = @intFromPtr(current.source.ptr);
            const pointer = @intFromPtr(input.ptr);
            if (pointer < base) return;
            const relative = pointer - base;
            if (relative > current.source.len or input.len > current.source.len - relative) return;
            const opening = relative + at - 1;
            if (opening != 0 and current.source[opening - 1] == '[') return;
            domain = current.parent;
        }
        const last = self.spans.items[self.spans.items.len - 1];
        if (last.kind != .text or last.provenance != .parsed or last.target.len != 0 or last.self_link or
            last.text.len == 0 or last.text[last.text.len - 1] != '[' or
            last.text[last.text.len - 1 ..].ptr != input[at - 1 ..].ptr) return;
        var bracket = last;
        bracket.text = last.text[last.text.len - 1 ..];
        bracket.provenance = .protected_literal;
        if (last.text.len == 1) {
            self.spans.items[self.spans.items.len - 1] = bracket;
        } else {
            self.spans.items[self.spans.items.len - 1].text = last.text[0 .. last.text.len - 1];
            try self.spans.append(self.a, bracket);
        }
    }
    // The borrowed angle may be protected only across an authored, unaffected
    // empty marker. Unknown/generated or clipped source cannot supply proof.
    fn emptyNowikiAngleSource(tracked: MissingText, at: usize, end: usize) bool {
        if (tracked.unknown or tracked.lost_missing_range or tracked.generated_source != null or
            at == 0 or at >= end or end > tracked.bytes.len) return false;
        for (tracked.ranges) |range| if (range.start < end and range.end > at - 1) return false;
        for (tracked.literal_curly_ranges) |range| if (range.start < end and range.end > at - 1) return false;
        for (tracked.generated_links) |range| if (range.start < end and range.end > at - 1) return false;
        return true;
    }
    // An explicit empty nowiki remains a strip marker through template and
    // link parsing upstream. Preserve only the borrowed brace or closing
    // bracket before that source boundary; generated/copy/style facts cannot.
    fn preserveEmptyNowikiBraceBoundary(self: *Renderer, input: []const u8, at: usize, style: Style) Error!void {
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.missing_nonaction or at == 0 or at >= input.len or
            self.spans.items.len == 0) return;
        const tag = syntax.tagAt(input, at) orelse return;
        if (!tag.is("nowiki") or tag.closing or !tag.self_closing or trim(tag.attrs).len != 0 or tag.end >= input.len) return;
        const brace = input[at - 1];
        const name_at = tag.end + @as(usize, @intFromBool(input[tag.end] == '/'));
        const angle = brace == '<' and name_at < input.len and std.ascii.isAlphabetic(input[name_at]);
        if ((!angle and ((brace != '{' and brace != '}' and brace != ']') or input[tag.end] != brace)) or
            (at > 1 and input[at - 2] == brace) or
            (!angle and tag.end + 1 < input.len and input[tag.end + 1] == brace)) return;
        const last = self.spans.items[self.spans.items.len - 1];
        if (last.provenance != .parsed or last.kind != .text or last.target.len != 0 or last.self_link or
            last.generated_diagnostic or last.image != null or
            last.text.len == 0 or last.text[last.text.len - 1] != brace or
            last.text[last.text.len - 1 ..].ptr != input[at - 1 ..].ptr) return;
        var delimiter_span = last;
        delimiter_span.text = last.text[last.text.len - 1 ..];
        delimiter_span.provenance = .protected_literal;
        if (last.text.len == 1) {
            self.spans.items[self.spans.items.len - 1] = delimiter_span;
        } else {
            try self.spans.append(self.a, delimiter_span);
            self.spans.items[self.spans.items.len - 2].text = last.text[0 .. last.text.len - 1];
        }
    }
    // Rebasing an unrelated missing range may copy a matched HTML child's
    // bytes. Keep that exact borrowed interval when the child has no affected
    // provenance, so nested literal-boundary proofs still see their parent.
    // Clipped/missing/generated children retain the existing copied path.
    fn borrowedInlineHtmlSlice(self: *Renderer, parent: MissingText, child: []const u8) Error!MissingText {
        var result = try missingSlice(self.a, parent, child);
        if (result.bytes.ptr == child.ptr or result.ranges.len != 0 or
            result.literal_curly_ranges.len != 0 or result.generated_links.len != 0 or
            result.lost_missing_range) return result;
        const base = @intFromPtr(parent.bytes.ptr);
        const pointer = @intFromPtr(child.ptr);
        if (pointer < base or pointer - base > parent.bytes.len or child.len > parent.bytes.len - (pointer - base)) return result;
        const copied = result.bytes;
        result.bytes = child;
        self.a.free(copied);
        return result;
    }

    const RubyPart = struct {
        raw: []const u8,
        tag: ?syntax.Tag = null,
        pair: ?syntax.Pair = null,
    };

    fn rubyWhitespace(raw: []const u8) bool {
        for (raw) |byte| if (std.mem.indexOfScalar(u8, " \t\r\n\x0c", byte) == null) return false;
        return true;
    }

    fn rubyParts(self: *Renderer, input: []const u8) Error![]const RubyPart {
        var parts: std.ArrayList(RubyPart) = .empty;
        var cursor: usize = 0;
        var body_start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |opening_at| {
            if (syntax.protectedEnd(input, opening_at)) |protected_end| {
                cursor = protected_end;
                continue;
            }
            const child_tag = syntax.tagAt(input, opening_at) orelse {
                cursor = opening_at + 1;
                continue;
            };
            if (oneOf(child_tag.name, &.{ "rb", "rt", "rtc", "rp" })) {
                if (child_tag.closing or child_tag.self_closing) return error.UncompiledPresentation;
                const child_pair = syntax.matchingTag(input, child_tag) orelse return error.UncompiledPresentation;
                if (opening_at > body_start) {
                    if (!self.spend()) return error.RenderLimit;
                    try parts.append(self.a, .{ .raw = input[body_start..opening_at] });
                }
                if (!self.spend()) return error.RenderLimit;
                try parts.append(self.a, .{ .raw = input[opening_at..child_pair.end], .tag = child_tag, .pair = child_pair });
                cursor = child_pair.end;
                body_start = cursor;
            } else if (!child_tag.closing and !child_tag.self_closing) {
                // Structural ruby children belong to this owner only. Ordinary
                // inline wrappers and nested ruby retain their own parser scope.
                const child_pair = syntax.matchingTag(input, child_tag) orelse return error.UncompiledPresentation;
                cursor = child_pair.end;
            } else cursor = child_tag.end;
        }
        if (body_start < input.len) {
            if (!self.spend()) return error.RenderLimit;
            try parts.append(self.a, .{ .raw = input[body_start..] });
        }
        return try parts.toOwnedSlice(self.a);
    }

    fn rubyBodyStructure(raw: []const u8) bool {
        var cursor: usize = 0;
        while (std.mem.indexOfScalarPos(u8, raw, cursor, '<')) |opening_at| {
            if (syntax.protectedEnd(raw, opening_at)) |protected_end| {
                cursor = protected_end;
                continue;
            }
            const child_tag = syntax.tagAt(raw, opening_at) orelse {
                cursor = opening_at + 1;
                continue;
            };
            if (oneOf(child_tag.name, &.{ "rb", "rt", "rtc", "rp" })) return false;
            if (oneOf(child_tag.name, &.{ "table", "tr", "td", "th", "div", "p", "pre", "br", "hr", "ul", "ol", "li", "dl", "dt", "dd", "h1", "h2", "h3", "h4", "h5", "h6" })) return false;
            if (child_tag.is("ruby") and !child_tag.closing) {
                const child_pair = syntax.matchingTag(raw, child_tag) orelse return false;
                cursor = child_pair.end;
            } else cursor = child_tag.end;
        }
        return true;
    }

    fn rubyFontDefault(self: *const Renderer, tag: syntax.Tag) bool {
        const selected = self.ruby_annotation_font_tag orelse return false;
        return tag.name.ptr == selected.name.ptr and tag.name.len == selected.name.len and
            tag.end == selected.end and tag.attrs.ptr == selected.attrs.ptr and tag.attrs.len == selected.attrs.len and
            tag.closing == selected.closing and tag.self_closing == selected.self_closing and tag.html_pre == selected.html_pre and
            (tag.is("rt") or tag.is("rtc"));
    }

    fn rubyLayoutRefusal(self: *const Renderer, stage: []const u8, tag: syntax.Tag, raw: []const u8) bool {
        if (self.context.table_viewport_trace) std.debug.print("RUBY_LAYOUT_REFUSAL stage={s} tag={s} observe_structure_only={any} source_binding={any} cell={any} ruby_depth={d} raw_bytes={d} raw_prefix={s}\n", .{
            stage, tag.name, self.context.observe_structure_only, self.source_element_binding != null,
            self.cell_line_source_observation, self.ruby_depth, raw.len, raw[0..@min(raw.len, 256)],
        });
        return false;
    }

    fn rubyParentInlineSourceStable(content: []const u8) bool {
        // Reuse the normal inline tokenizer for nested actions. Parameters and
        // manual-conversion/control braces are outside this negative receipt.
        if (std.mem.indexOfAny(u8, content, "{}") != null) return false;
        var tokens: ir.InlineIterator = .{ .input = content, .renderer_boundaries = true };
        while (tokens.next()) |token| if (token.kind != .text or token.literal_tail or
            token.empty_target_link or token.rejected_external_opener or token.bold or token.italic) return false;
        var cursor: usize = 0;
        while (std.mem.indexOfScalarPos(u8, content, cursor, '<')) |at| {
            if (syntax.protectedEnd(content, at) != null) return false;
            const child = syntax.tagAt(content, at) orelse return false;
            if (child.isOpaque() or child.html_pre or !knownInlineHtmlName(child.name) or
                oneOf(child.name, &.{ "a", "ruby", "button", "input", "select", "option", "textarea", "form" })) return false;
            // Structural RB/RT/RP/RTC are owned by the existing Ruby parser.
            // Every other opening must stay inside its ordinary inline subset.
            if (!oneOf(child.name, &.{ "rb", "rt", "rp", "rtc" }) and
                !rubyBodyStructure(content[at..child.end])) return false;
            cursor = child.end;
        }
        return true;
    }

    // A completed RT may contain one ordinary explicit anchor before a later
    // structural child. Its action stays owned by normal inline parsing; this
    // proves only that the closed sibling cannot reconstruct the child's parent.
    fn rubyClosedReadingSiblingStable(self: *const Renderer, content: []const u8) bool {
        if (content.len == 0 or content.len > 16 * 1024 or !rubyBodyStructure(content) or
            std.mem.indexOfAny(u8, content, "{}<>") != null) return false;
        var tokens: ir.InlineIterator = .{ .input = content, .renderer_boundaries = true,
            .link_trail = self.context.link_trail };
        var anchors: usize = 0;
        while (tokens.next()) |token| {
            if (token.literal_tail or token.empty_target_link or token.rejected_external_opener or
                token.bold or token.italic) return false;
            if (token.kind == .text) {
                if (std.mem.indexOfAny(u8, token.text, "[]") != null or !rubyParentInlineSourceStable(token.text)) return false;
                continue;
            }
            if (token.kind != .link or anchors != 0 or !token.link_has_pipe or token.link_empty_label or
                token.link_label_restored_close or token.text.len == 0 or
                !manualConversionInternalTarget(token.target) or
                std.mem.indexOfAny(u8, token.text, "[]") != null or !rubyParentInlineSourceStable(token.text)) return false;
            const target = if (starts(token.target, ":")) token.target[1..] else token.target;
            const page = target[0 .. (std.mem.indexOfScalar(u8, target, '#') orelse target.len)];
            if (page.len == 0 or std.mem.indexOfScalar(u8, page, ':') != null) return false;
            anchors += 1;
        }
        return anchors == 1;
    }

    fn rubyGeneratedAnchorParentStable(raw: []const u8) bool {
        const opening = syntax.tagAt(raw, 0) orelse return false;
        if (!opening.is("ruby") or opening.closing or opening.self_closing or opening.html_pre) return false;
        const pair = syntax.matchingTag(raw, opening) orelse return false;
        return pair.end == raw.len and rubyParentInlineSourceStable(raw[opening.end..pair.inner_end]);
    }

    const NativeRubyLabelParent = struct {
        frame: *const InlineSourceDomain,
        token: []const u8,
        label: MissingText,
        anchor: *const table_style_profile.TextElement,
    };

    fn nativeRubyLabelParent(self: *const Renderer, token: []const u8, label: MissingText, inherited: Style, style: Style) ?NativeRubyLabelParent {
        if (self.explicit_wiki_label != null or self.in_reference or self.in_template_literal_scope or
            self.pre_block or self.parsed_pre or self.block_formatting.code or self.poem_depth != 0 or
            self.html_list_item_flow or self.html_blockquote_flow or self.typed_table_depth != 0 or
            self.inline_table_boundaries != null or self.table_viewport_cell_source != null or
            self.figure_caption_depth != 0 or self.inline_image_attribute or inherited.kind != .text or
            inherited.target.len != 0 or inherited.self_link_target != null or style.kind != .link or
            style.target.len == 0 or style.self_link_target != null or label.unknown or
            !noLiParentSourceRange(label, label.bytes) or !rubyGeneratedAnchorParentStable(label.bytes)) return null;
        const frame = self.inline_source_domain orelse return null;
        const source = frame.tracked orelse return null;
        if (frame.source.ptr != source.bytes.ptr or frame.source.len != source.bytes.len or
            source.unknown or !noLiParentSourceRange(source, token)) return null;
        const anchor = style.text_element orelse return null;
        if (!std.ascii.eqlIgnoreCase(anchor.tag, "a") or anchor.alternative_ancestry != null) return null;
        var tokens: ir.InlineIterator = .{ .input = token, .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const parsed = tokens.next() orelse return null;
        if (parsed.kind != .link or !parsed.link_has_pipe or parsed.empty_target_link or parsed.literal_tail or
            parsed.text.ptr != label.bytes.ptr or parsed.text.len != label.bytes.len or
            tokens.cursor != token.len or tokens.next() != null) return null;
        return .{ .frame = frame, .token = token, .label = label, .anchor = anchor };
    }

    // A local native constructor owns this A-to-Ruby edge even when the page's
    // distant ancestry is unknown. The receipt never supplies classes or a root.
    fn nativeRubyDirectParent(self: *const Renderer, tag: syntax.Tag, style: Style,
        element: *const table_style_profile.TextElement) ?*const table_style_profile.TextElement
    {
        if (!tag.is("ruby") or self.in_reference or self.in_template_literal_scope or self.pre_block or
            self.parsed_pre or self.block_formatting.code or self.poem_depth != 0 or self.html_list_item_flow or
            self.html_blockquote_flow or self.typed_table_depth != 0 or self.inline_table_boundaries != null or
            self.table_viewport_cell_source != null or self.figure_caption_depth != 0 or self.inline_image_attribute or
            element.alternative_ancestry != null) return null;
        const operation = self.explicit_wiki_label orelse return null;
        const issued = operation.native_parent orelse return null;
        if (operation.kind != .link or style.kind != .link or style.self_link_target != null or
            style.target.ptr != operation.target.ptr or style.target.len != operation.target.len or
            (style.text_element != issued.anchor and style.text_element != element) or element.parent != issued.anchor or
            issued.anchor.alternative_ancestry != null or !std.ascii.eqlIgnoreCase(issued.anchor.tag, "a")) return null;
        const label = operation.ordinary_label orelse return null;
        const tracked = self.inline_missing orelse return null;
        const raw = tracked.bytes;
        if (label.ptr != issued.label.bytes.ptr or label.len != issued.label.bytes.len or
            raw.ptr != label.ptr or raw.len != label.len or
            tracked.unknown or issued.label.unknown or !noLiParentSourceRange(tracked, raw) or
            !noLiParentSourceRange(issued.label, raw) or !rubyGeneratedAnchorParentStable(raw)) return null;
        const opening = syntax.tagAt(raw, 0) orelse return null;
        if (opening.name.ptr != tag.name.ptr or opening.name.len != tag.name.len or opening.end != tag.end or
            opening.attrs.ptr != tag.attrs.ptr or opening.attrs.len != tag.attrs.len) return null;
        const key = if (self.quoteClassTag(tag)) |known| known.source_key else @intFromPtr(tag.name.ptr);
        if (element.source_key != key) return null;
        var frame = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        while (frame) |current| : (frame = current.parent) {
            if (remaining == 0) return null;
            remaining -= 1;
            if (current != issued.frame) continue;
            const source = current.tracked orelse return null;
            if (current.source.ptr != source.bytes.ptr or current.source.len != source.bytes.len or
                source.unknown or !noLiParentSourceRange(source, issued.token)) return null;
            var tokens: ir.InlineIterator = .{ .input = issued.token, .renderer_boundaries = true, .link_trail = self.context.link_trail };
            const parsed = tokens.next() orelse return null;
            if (parsed.kind != .link or !parsed.link_has_pipe or parsed.empty_target_link or parsed.literal_tail or
                parsed.text.ptr != label.ptr or parsed.text.len != label.len or tokens.cursor != issued.token.len or tokens.next() != null) return null;
            return issued.anchor;
        }
        return null;
    }

    fn rubyPlainAnchorSibling(raw: []const u8) bool {
        if (!std.unicode.utf8ValidateSlice(raw) or std.mem.indexOfAny(u8, raw, "<>{}[]&'") != null or
            magicLinkStart(raw, 0) != null) return false;
        for (raw) |byte| if (std.ascii.isControl(byte)) return false;
        // The maintained tokenizer excludes free URLs and other nested actions.
        return rubyParentInlineSourceStable(raw);
    }

    fn rubyAnchorLabelBody(label: []const u8, selected: []const u8) ?[]const u8 {
        if (label.len == 0 or label.len > 16 * 1024 or selected.len == 0 or
            !wikiClassContains(label, selected)) return null;
        var cursor: usize = 0;
        var remaining: usize = max_depth + 1;
        var found: ?[]const u8 = null;
        while (std.mem.indexOfScalarPos(u8, label, cursor, '<')) |at| {
            if (remaining == 0 or !rubyPlainAnchorSibling(label[cursor..at])) return null;
            remaining -= 1;
            const opening = syntax.tagAt(label, at) orelse return null;
            if (!opening.is("ruby") or opening.closing or opening.self_closing) return null;
            const pair = syntax.matchingTag(label, opening) orelse return null;
            const body = label[at..pair.end];
            if (!rubyGeneratedAnchorParentStable(body)) return null;
            if (wikiClassContains(body, selected)) {
                if (found != null) return null;
                found = body;
            }
            cursor = pair.end;
        }
        // Validate the entire label, including siblings after the selected one.
        // Equal text in another occurrence never substitutes for its byte range.
        if (!rubyPlainAnchorSibling(label[cursor..])) return null;
        return found;
    }

    fn rubyLiveAnchorLabel(self: *const Renderer, selected: FigureClassSourceDomain,
        binding: SourceElementBinding, known: []const u8) bool
    {
        const operation = self.explicit_wiki_label orelse return false;
        const token = operation.ordinary_token orelse return false;
        const issued_frame = operation.ordinary_frame orelse return false;
        var frame = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        var current_operation = false;
        while (frame) |current| : (frame = current.parent) {
            if (remaining == 0) return false;
            remaining -= 1;
            if (current != issued_frame) continue;
            const source = current.tracked orelse return false;
            if (current.source.ptr != source.bytes.ptr or current.source.len != source.bytes.len or
                !noLiParentSourceRange(source, token)) return false;
            var tokens: ir.InlineIterator = .{ .input = token, .renderer_boundaries = true,
                .link_trail = self.context.link_trail };
            const parsed = tokens.next() orelse return false;
            if (parsed.kind != .link or !parsed.link_has_pipe or parsed.link_empty_label or
                parsed.link_label_restored_close or parsed.empty_target_link or parsed.literal_tail or
                tokens.cursor != token.len or tokens.next() != null) return false;
            const parsed_label = self.ordinaryLinkOriginal(selected, parsed.text) orelse return false;
            if (parsed_label.bytes.ptr != known.ptr or parsed_label.bytes.len != known.len) return false;
            const original_token = self.ordinaryLinkOriginal(selected, token) orelse return false;
            const token_start = std.math.sub(usize, @intFromPtr(original_token.bytes.ptr), @intFromPtr(selected.selected.ptr)) catch return false;
            if (binding.ownerRange(token_start, original_token.bytes.len) == null) return false;
            current_operation = true;
            break;
        }
        return current_operation;
    }

    // The already-issued explicit label owns the A. A plain prefix/suffix cannot
    // manufacture another parent. Reconstruct its current copy by the exact
    // mapped Ruby offset, never by searching for a same-text occurrence.
    fn rubyMappedAnchorLabel(self: *const Renderer, selected: FigureClassSourceDomain,
        binding: SourceElementBinding, tracked: MissingText, label: []const u8,
        whole: []const u8, mapped: []const u8) bool
    {
        const known = self.ordinaryLinkOriginal(selected, label) orelse return false;
        if (label.len == whole.len)
            return known.bytes.ptr == mapped.ptr and known.bytes.len == mapped.len;
        if (!self.rubyLiveAnchorLabel(selected, binding, known.bytes)) return false;
        if (!wikiClassContains(known.bytes, mapped) or known.bytes.len != label.len or
            mapped.len != whole.len or !std.mem.eql(u8, mapped, whole)) return false;
        const occurrence = rubyAnchorLabelBody(known.bytes, mapped) orelse return false;
        if (occurrence.ptr != mapped.ptr or occurrence.len != mapped.len) return false;
        const offset = @intFromPtr(mapped.ptr) - @intFromPtr(known.bytes.ptr);
        const start = std.math.sub(usize, @intFromPtr(known.bytes.ptr), @intFromPtr(selected.selected.ptr)) catch return false;
        if (binding.ownerRange(start, known.bytes.len) == null or !wikiClassContains(tracked.bytes, whole)) return false;
        const current_offset = @intFromPtr(whole.ptr) - @intFromPtr(tracked.bytes.ptr);
        if (current_offset < offset) return false;
        const label_start = current_offset - offset;
        if (known.bytes.len > tracked.bytes.len - label_start) return false;
        const current_label = tracked.bytes[label_start .. label_start + known.bytes.len];
        if (!noLiParentSourceRange(tracked, current_label) or !std.mem.eql(u8, current_label, known.bytes)) return false;
        const current_known = self.ordinaryLinkOriginal(selected, current_label) orelse return false;
        return current_known.bytes.ptr == known.bytes.ptr and current_known.bytes.len == known.bytes.len;
    }

    // This is a negative own-query fact, not physical ancestry. The current
    // complete source occurrence must establish the immediate parser parent.
    fn rubySourceParentTag(self: *const Renderer, tag: syntax.Tag, element: *const table_style_profile.TextElement) ?[]const u8 {
        if (self.content_root != .parser_output or self.in_reference or self.in_template_literal_scope or
            self.pre_block or self.parsed_pre or self.block_formatting.code or self.poem_depth != 0 or
            self.html_list_item_flow or self.html_blockquote_flow or element.alternative_ancestry != null) return null;
        const parent = element.parent orelse return null;
        if (parent.alternative_ancestry != null or !self.currentAncestorScope(element) or !self.currentAncestorScope(parent)) return null;
        const selected = self.figureClassSourceDomain() orelse return null;
        const binding = self.figureStyleOriginalBinding(selected) orelse return null;
        for ([_]*const table_style_profile.TextElement{ element, parent }) |node| {
            const source = node.ancestor_class_source orelse return null;
            if (node.ancestor_class_scope != selected.scope or node.complete_ancestor_classes == null or
                source.ptr != selected.selected.ptr or source.len != selected.selected.len) return null;
        }
        const tracked = self.inline_missing orelse return null;
        if (!wikiClassContains(tracked.bytes, tag.name)) return null;
        const name_at = @intFromPtr(tag.name.ptr) - @intFromPtr(tracked.bytes.ptr);
        if (name_at == 0) return null;
        const current = syntax.tagAt(tracked.bytes, name_at - 1) orelse return null;
        if (current.name.ptr != tag.name.ptr or current.name.len != tag.name.len or
            current.attrs.ptr != tag.attrs.ptr or current.attrs.len != tag.attrs.len or
            current.closing or current.self_closing or current.html_pre or current.isOpaque()) return null;
        const current_pair = syntax.matchingTag(tracked.bytes, current) orelse return null;
        const whole = tracked.bytes[name_at - 1..current_pair.end];
        if (!noLiParentSourceRange(tracked, whole)) return null;
        const mapped = self.ordinaryLinkOriginal(selected, whole) orelse return null;
        // textElement prefers the live quote-map key even when a registered
        // alias also maps this same occurrence. Mapping and node identity are
        // independent checks; neither substitutes for the other.
        const current_key = if (self.quoteClassTag(tag)) |known| known.source_key else @intFromPtr(tag.name.ptr);
        if (current_key != element.source_key) return null;
        const start = std.math.sub(usize, @intFromPtr(mapped.bytes.ptr), @intFromPtr(selected.selected.ptr)) catch return null;
        if (binding.ownerRange(start, mapped.bytes.len) == null) return null;
        if (std.ascii.eqlIgnoreCase(parent.tag, "a")) {
            const operation = self.explicit_wiki_label orelse return null;
            const label = operation.ordinary_label orelse return null;
            if (operation.kind != .link or operation.ordinary_anchor != parent or !tag.is("ruby") or
                !rubyGeneratedAnchorParentStable(whole) or
                !self.rubyMappedAnchorLabel(selected, binding, tracked, label, whole, mapped.bytes)) return null;
            return parent.tag;
        }
        // Literal Ruby structural parents use the same complete tag parser as
        // rubyParts. Skip only closed direct siblings; protected/control syntax
        // and an enclosing intervening wrapper cannot supply this fact.
        const literal_strong = tag.is("ruby") and std.ascii.eqlIgnoreCase(parent.tag, "strong");
        if (literal_strong) {
            // This additional literal edge is confined to an ordinary complete
            // wrapper. Table/foster, caption and explicit wiki-label domains keep
            // their existing refusal rather than borrowing this local proof.
            if (self.explicit_wiki_label != null or self.typed_table_depth != 0 or
                self.inline_table_boundaries != null or self.table_viewport_cell_source != null or
                self.figure_caption_depth != 0 or self.inline_image_attribute) return null;
        } else if (!oneOf(parent.tag, &.{ "ruby", "rb", "rt", "rtc", "rp" })) return null;
        const parent_name = self.ordinaryLinkOriginal(selected, parent.tag) orelse return null;
        var parent_key = @intFromPtr(parent.tag.ptr);
        var quote = self.quote_class_source;
        var remaining: usize = max_depth + 1;
        while (quote) |domain| : (quote = domain.parent) {
            if (remaining == 0) return null;
            remaining -= 1;
            if (!wikiClassContains(domain.map.output, parent.tag)) continue;
            const name_offset = @intFromPtr(parent.tag.ptr) - @intFromPtr(domain.map.output.ptr);
            if (name_offset == 0) return null;
            const current_parent = syntax.tagAt(domain.map.output, name_offset - 1) orelse return null;
            if (current_parent.name.ptr != parent.tag.ptr or current_parent.name.len != parent.tag.len or
                current_parent.closing or current_parent.self_closing or current_parent.html_pre or current_parent.isOpaque()) return null;
            if (self.quoteClassTag(current_parent)) |known| { parent_key = known.source_key; break; }
        }
        if (parent_key != parent.source_key) return null;
        const parent_at = std.math.sub(usize, @intFromPtr(parent_name.bytes.ptr), @intFromPtr(selected.selected.ptr)) catch return null;
        if (parent_at == 0) return null;
        const opening = syntax.tagAt(selected.selected, parent_at - 1) orelse return null;
        if (opening.name.ptr != parent_name.bytes.ptr or opening.name.len != parent_name.bytes.len or
            opening.closing or opening.self_closing or opening.html_pre or opening.isOpaque()) return null;
        const pair = syntax.matchingTag(selected.selected, opening) orelse return null;
        if (start < opening.end or mapped.bytes.len > pair.inner_end -| start or start > pair.inner_end or
            binding.ownerRange(parent_at - 1, pair.end - (parent_at - 1)) == null) return null;
        if (literal_strong) {
            // Both the complete original parent and current Ruby are mapped to
            // this owner. Exact whole-inner-body equality excludes skipped
            // siblings, protected prefixes and intervening literal wrappers.
            if (start != opening.end or mapped.bytes.len != pair.inner_end - opening.end) return null;
            return parent.tag;
        }
        var cursor = opening.end;
        while (cursor < start) {
            if (std.mem.indexOfScalar(u8, "[{}'", selected.selected[cursor]) != null) return null;
            if (selected.selected[cursor] != '<') { cursor += 1; continue; }
            if (syntax.protectedEnd(selected.selected, cursor) != null) return null;
            const sibling = syntax.tagAt(selected.selected, cursor) orelse return null;
            if (sibling.closing or sibling.self_closing or sibling.html_pre or sibling.isOpaque() or
                !knownInlineHtmlName(sibling.name)) return null;
            const sibling_pair = syntax.matchingTag(selected.selected, sibling) orelse return null;
            if (sibling_pair.end > start or sibling_pair.end <= cursor or
                !rubyBodyStructure(selected.selected[sibling.end..sibling_pair.inner_end]) or
                (!rubyParentInlineSourceStable(selected.selected[sibling.end..sibling_pair.inner_end]) and
                    !(sibling.is("rt") and self.rubyClosedReadingSiblingStable(selected.selected[sibling.end..sibling_pair.inner_end]))) or
                oneOf(sibling.name, &.{ "a", "button", "input", "select", "option", "textarea", "form" }) or
                (!oneOf(sibling.name, &.{ "rb", "rt", "rtc", "rp" }) and
                    !rubyBodyStructure(selected.selected[cursor..sibling_pair.end]))) return null;
            cursor = sibling_pair.end;
        }
        return if (cursor == start) parent.tag else null;
    }

    fn rubyBulletAncestorClasses(self: *const Renderer, tag: syntax.Tag, element: *const table_style_profile.TextElement) ?[]const u8 {
        // Reuse the exact live local-parent proof before considering the more
        // distant negative inventory. Neither operation grants physical edges.
        if (self.rubySourceParentTag(tag, element) == null or !self.figure_implicit_list_context) return null;
        const operation = self.ordinary_bullet_link orelse return null;
        const selected = self.figureClassSourceDomain() orelse return null;
        const binding = self.figureStyleOriginalBinding(selected) orelse return null;
        const source = selected.scope.source_bullet_rubies_source orelse return null;
        if (source.ptr != selected.selected.ptr or source.len != selected.selected.len) return null;
        const root = selected.scope.page_style_complete_root orelse return null;
        const held = self.body_missing orelse return null;
        if (held.bytes.ptr != operation.source.ptr or held.bytes.len != operation.source.len or
            !noLiParentSourceRange(held, operation.line) or !wikiClassContains(operation.line, operation.body)) return null;
        const line = self.figureStyleOriginalSlice(selected, operation.line) orelse return null;
        const body = self.figureStyleOriginalSlice(selected, operation.body) orelse return null;
        if (line.len == 0 or line[0] != '*' or std.mem.indexOfAny(u8, line, "\r\n") != null) return null;
        const parsed = wikiListLineBody(line[1..]);
        if (parsed.ptr != body.ptr or parsed.len != body.len) return null;
        const line_start = @intFromPtr(line.ptr) - @intFromPtr(source.ptr);
        if (line_start != 0 and source[line_start - 1] != '\n') return null;
        const owner_line = binding.ownerRange(line_start, line.len) orelse return null;
        if (!std.mem.eql(u8, owner_line, operation.line)) return null;
        const label_operation = self.explicit_wiki_label orelse return null;
        const label = label_operation.ordinary_label orelse return null;
        if (label_operation.kind != .link or label_operation.ordinary_anchor == null) return null;
        const whole_label = rubyGeneratedAnchorParentStable(label);
        const mapped = self.ordinaryLinkOriginal(selected, label) orelse return null;
        const mapped_name = self.ordinaryLinkOriginal(selected, tag.name) orelse return null;
        const ruby = if (whole_label) mapped.bytes else rubyAnchorLabelBody(mapped.bytes, mapped_name.bytes) orelse return null;
        if (!whole_label and (!std.mem.eql(u8, label, mapped.bytes) or
            !self.rubyLiveAnchorLabel(selected, binding, mapped.bytes))) return null;
        if (!wikiClassContains(body, mapped.bytes) or !wikiClassContains(ruby, mapped_name.bytes)) return null;
        const ruby_start = @intFromPtr(ruby.ptr) - @intFromPtr(source.ptr);
        var found: ?[]const u8 = null;
        for (selected.scope.source_bullet_rubies) |proof| {
            if (proof.line_start != line_start or proof.line_end != line_start + line.len or
                proof.ruby_start != ruby_start or proof.ruby_end != ruby_start + ruby.len) continue;
            if (found != null or proof.root != root or !root.physical_ancestry_complete or
                proof.classes.len > 65536 or binding.ownerRange(ruby_start, ruby.len) == null) return null;
            found = proof.classes;
        }
        return found;
    }

    fn rubyInlineAncestorClasses(self: *const Renderer, tag: syntax.Tag, element: *const table_style_profile.TextElement) ?[]const u8 {
        // The complete ordinary root line was joined separately. Revalidate the
        // actual current tag, source copy and local parent before using its
        // occurrence-only negative class inventory; no physical edge is added.
        if (self.rubySourceParentTag(tag, element) == null or self.figure_implicit_list_context or
            self.ordinary_bullet_link != null or self.explicit_wiki_label != null or
            self.typed_table_depth != 0 or self.inline_table_boundaries != null or
            self.table_viewport_cell_source != null or self.figure_caption_depth != 0 or self.inline_image_attribute) return null;
        const selected = self.figureClassSourceDomain() orelse return null;
        const binding = self.figureStyleOriginalBinding(selected) orelse return null;
        const source = selected.scope.source_inline_rubies_source orelse return null;
        if (source.ptr != selected.selected.ptr or source.len != selected.selected.len) return null;
        const root = selected.scope.page_style_complete_root orelse return null;
        const mapped_name = self.ordinaryLinkOriginal(selected, tag.name) orelse return null;
        if (!wikiClassContains(source, mapped_name.bytes)) return null;
        const name_at = @intFromPtr(mapped_name.bytes.ptr) - @intFromPtr(source.ptr);
        if (name_at == 0) return null;
        const original = syntax.tagAt(source, name_at - 1) orelse return null;
        if (!std.ascii.eqlIgnoreCase(original.name, tag.name) or original.closing or original.self_closing) return null;
        const original_pair = syntax.matchingTag(source, original) orelse return null;
        var found: ?[]const u8 = null;
        for (selected.scope.source_inline_rubies) |proof| {
            if (proof.ruby_start > name_at - 1 or proof.ruby_end < original_pair.end) continue;
            if (found != null or proof.line_start >= proof.line_end or proof.line_end > source.len or
                proof.ruby_start < proof.line_start or proof.ruby_end > proof.line_end or
                proof.ruby_start >= proof.ruby_end or proof.root != root or !root.physical_ancestry_complete or
                proof.classes.len > 65536 or (proof.line_start != 0 and source[proof.line_start - 1] != '\n') or
                (proof.line_end != source.len and source[proof.line_end] != '\n') or
                std.mem.indexOfAny(u8, source[proof.line_start..proof.line_end], "\r\n") != null or
                binding.ownerRange(proof.line_start, proof.line_end - proof.line_start) == null) return null;
            const ruby = syntax.tagAt(source, proof.ruby_start) orelse return null;
            const pair = syntax.matchingTag(source, ruby) orelse return null;
            if (!ruby.is("ruby") or ruby.closing or ruby.self_closing or pair.end != proof.ruby_end) return null;
            // Stay on the currently issued Ruby/STRONG chain, including RT/RP
            // descendants. A sibling occurrence cannot lend its inventory.
            var current: ?*const table_style_profile.TextElement = element;
            var remaining: usize = max_depth + 1;
            var same_ruby = false;
            while (current) |node| : (current = node.parent) {
                if (remaining == 0 or node.alternative_ancestry != null or !self.currentAncestorScope(node) or
                    node.ancestor_class_scope != selected.scope) return null;
                remaining -= 1;
                if (!std.ascii.eqlIgnoreCase(node.tag, "ruby")) continue;
                const mapped = self.ordinaryLinkOriginal(selected, node.tag) orelse return null;
                if (mapped.bytes.ptr != ruby.name.ptr or mapped.bytes.len != ruby.name.len) return null;
                const strong = node.parent orelse return null;
                if (!std.ascii.eqlIgnoreCase(strong.tag, "strong") or strong.alternative_ancestry != null or
                    !self.currentAncestorScope(strong) or strong.ancestor_class_scope != selected.scope) return null;
                same_ruby = true;
                break;
            }
            if (!same_ruby) return null;
            found = proof.classes;
        }
        return found;
    }

    fn rubyUnitlessLineHeight(self: *Renderer, tracked: MissingText, tag: syntax.Tag, parent: Style) Error!?NativeRubyUnitlessLineHeight {
        if (self.ruby_depth == 0 or !tag.is("span") or tag.closing or tag.self_closing or tag.html_pre or
            self.in_reference or self.in_template_literal_scope or self.pre_block or self.parsed_pre or
            self.poem_depth != 0 or self.typed_table_depth != 0 or self.inline_table_boundaries != null or
            self.table_viewport_cell_source != null or self.figure_caption_depth != 0 or self.inline_image_attribute or
            self.bidi_scope_depth != 0 or self.active_bidi_capture != null or parent.provenance != .parsed or
            parent.missing_nonaction or parent.image != null or parent.font_size_unknown or parent.ruby_script_ambiguous or
            parent.code or self.block_formatting.code or parent.preserve_whitespace or
            try self.compiledBidiScope(tag) != null) return null;
        const opening = projectedTrackedTagOpening(tracked, tag) orelse return null;
        const start = @intFromPtr(opening.ptr) - @intFromPtr(tracked.bytes.ptr);
        const raw_tag = syntax.tagAt(tracked.bytes, start) orelse return null;
        const pair = syntax.matchingTag(tracked.bytes, raw_tag) orelse return null;
        const whole = tracked.bytes[start..pair.end];
        if (!noLiParentSourceRange(tracked, whole)) return null;
        const frame = self.inline_source_domain orelse return null;
        const owner = frame.tracked orelse return null;
        if (frame.source.ptr != owner.bytes.ptr or frame.source.len != owner.bytes.len or
            !noLiParentSourceRange(owner, whole)) return null;
        const element = try self.textElement(tag, parent.text_element, parent.language);
        var query = element.*;
        query.source_parent_tag_nonmatch = self.rubySourceParentTag(tag, element);
        query.constructed_direct_parent = self.nativeRubyDirectParent(tag, parent, element);
        if (self.rubyBulletAncestorClasses(tag, element)) |classes| query.complete_ancestor_classes = classes;
        if (self.rubyInlineAncestorClasses(tag, element)) |classes| query.complete_ancestor_classes = classes;
        const css = (try self.semanticAttribute(tag, "style")) orelse "";
        const motion = try self.nativeInlineMotionEntry(tag, parent.native_inline_motion);
        const declarations = (try self.nativeInlineMotionDeclarations(motion)) orelse return null;
        defer self.a.free(declarations);
        const selected_profile = self.textPaintProfile();
        const factor = if (selected_profile) |profile|
            try profile.sourceRubyUnitlessLineHeightAlloc(self.a, &query, css, declarations, self.context.table_viewport_trace)
        else empty: {
            var profile = table_style_profile.parseAlloc(self.a, "") catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory, else => return null,
            };
            defer profile.deinit();
            break :empty try profile.sourceRubyUnitlessLineHeightAlloc(self.a, &query, css, declarations, self.context.table_viewport_trace);
        };
        return .{ .factor = factor orelse return null, .motion = motion,
            .profile = selected_profile, .parent = self.ruby_unitless_scope };
    }

    fn rubyUnitlessLineHeightCurrent(self: *Renderer, style: Style) Error!f32 {
        const proof = style.ruby_unitless_line_height orelse return error.UncompiledPresentation;
        const saved = switch (proof.motion) { .proved => |value| value, else => return error.UncompiledPresentation };
        if (self.ruby_depth == 0 or self.native_inline_motion_root != saved.root or
            self.native_inline_motion_epoch != saved.epoch or proof.profile != self.textPaintProfile() or
            !std.math.isFinite(proof.factor) or proof.factor < 0) return error.UncompiledPresentation;
        // Traverse only the live lexical stack, never a parent retained by a
        // copied Style. A new opener has a new arena-owned declaration identity.
        var active = self.ruby_unitless_scope;
        var remaining: usize = max_depth + 1;
        var found = false;
        while (active) |entry| : (active = entry.parent) {
            if (remaining == 0) return error.UncompiledPresentation;
            remaining -= 1;
            const current = switch (entry.motion) { .proved => |value| value, else => return error.UncompiledPresentation };
            if (current.root == saved.root and current.epoch == saved.epoch and current.last == saved.last and
                entry.factor == proof.factor and entry.profile == proof.profile) { found = true; break; }
        }
        if (!found) return error.UncompiledPresentation;
        const inherited = switch (style.native_inline_motion) { .proved => |value| value, else => return error.UncompiledPresentation };
        if (inherited.root != saved.root or inherited.epoch != saved.epoch) return error.UncompiledPresentation;
        // htmlInlineStyle can issue another receipt for the same own opener;
        // both complete chains are revalidated, including current declarations.
        const own_declarations = (try self.nativeInlineMotionDeclarations(proof.motion)) orelse return error.UncompiledPresentation;
        defer self.a.free(own_declarations);
        const current_declarations = (try self.nativeInlineMotionDeclarations(style.native_inline_motion)) orelse return error.UncompiledPresentation;
        defer self.a.free(current_declarations);
        return proof.factor;
    }

    fn rubyUnitlessLineHeightStrut(self: *Renderer, style: Style) Error!void {
        var metric = style;
        metric.ruby_unitless_metric = true;
        metric.kind = .text; metric.target = ""; metric.self_link_target = null;
        metric.link_paint = null; metric.ordinary_link_paint = null;
        metric.table_link_source = null; metric.table_link_wrap = null;
        metric.explanation = ""; metric.explanation_set = false;
        metric.tooltip = null; metric.tooltip_set = false;
        try self.textRawGeneratedWithRich("", metric, null, null, null);
    }

    fn rubyLayoutSupported(self: *Renderer, tag: syntax.Tag, parent: Style, raw: []const u8) Error!bool {
        if (parent.ruby_script_ambiguous) return self.rubyLayoutRefusal("script_ambiguous", tag, raw);
        if ((tag.is("sup") or tag.is("sub")) and
            (parent.superscript or parent.subscript or self.block_formatting.superscript or self.block_formatting.subscript)) return self.rubyLayoutRefusal("repeated_script", tag, raw);
        const css = (try self.semanticAttribute(tag, "style")) orelse "";
        if (self.textPaintProfile()) |profile| {
            const element = try self.textElement(tag, parent.text_element, parent.language);
            var query = element.*;
            query.source_parent_tag_nonmatch = self.rubySourceParentTag(tag, element);
            query.constructed_direct_parent = self.nativeRubyDirectParent(tag, parent, element);
            if (self.rubyBulletAncestorClasses(tag, element)) |classes| query.complete_ancestor_classes = classes;
            if (self.rubyInlineAncestorClasses(tag, element)) |classes| query.complete_ancestor_classes = classes;
            if (!try profile.sourceRubyLayoutUnchanged(self.a, &query, css, self.context.table_viewport_trace)) return self.rubyLayoutRefusal("profile_layout", tag, raw);
        } else if (!try table_style_profile.rubyLayoutUnchangedAlloc(self.a, css)) return self.rubyLayoutRefusal("inline_layout", tag, raw);
        if (tag.is("bdi") or tag.is("bdo")) return self.rubyLayoutRefusal("bidi_tag", tag, raw);
        if (try self.compiledBidiScope(tag)) |scope| {
            if (scope.automatic or scope.mode == .isolate_override) return self.rubyLayoutRefusal("bidi_scope", tag, raw);
        }
        return true;
    }

    // This route owns one complete SPAN directly inside an already admitted RT.
    // Its borrowed source interval and declaring font survive as one data group.
    fn rubyInlinePaddingCapture(self: *Renderer, tracked: MissingText, content: []const u8,
        parent: Style, depth: usize) Error!bool
    {
        const raw_tag = syntax.tagAt(content, 0) orelse return false;
        if (!raw_tag.is("span") or raw_tag.closing or raw_tag.self_closing or raw_tag.html_pre) return false;
        const pair = syntax.matchingTag(content, raw_tag) orelse return false;
        if (pair.end != content.len) return false;
        const tag = try self.normalizedTag(raw_tag);
        const css = (try self.semanticAttribute(tag, "style")) orelse return false;
        if (try table_style_profile.rubyInlinePaddingAlloc(self.a, css) == null) return false;
        if (parent.ruby_unitless_line_height != null or self.ruby_depth == 0 or depth >= max_depth or self.in_reference or self.in_template_literal_scope or
            self.pre_block or self.parsed_pre or self.block_formatting.code or self.poem_depth != 0 or
            self.typed_table_depth != 0 or self.inline_table_boundaries != null or self.table_viewport_cell_source != null or
            self.figure_caption_depth != 0 or self.inline_image_attribute or self.bidi_scope_depth != 0 or
            self.active_bidi_capture != null or parent.provenance != .parsed or parent.missing_nonaction or
            parent.self_link_target != null or parent.image != null or parent.font_size_unknown or parent.ruby_script_ambiguous or
            parent.code or parent.preserve_whitespace or (parent.direction.len != 0 and !std.mem.eql(u8, parent.direction, "ltr")) or
            !noLiParentSourceRange(tracked, content)) return error.UncompiledPresentation;
        const frame = self.inline_source_domain orelse return error.UncompiledPresentation;
        const owner_source = frame.tracked orelse return error.UncompiledPresentation;
        if (frame.source.ptr != owner_source.bytes.ptr or frame.source.len != owner_source.bytes.len or
            !noLiParentSourceRange(owner_source, content)) return error.UncompiledPresentation;
        const body = content[tag.end..pair.inner_end];
        if (body.len == 0 or trim(body).len == 0 or std.mem.indexOfAny(u8, body, "\t\r\n\x0c") != null)
            return error.UncompiledPresentation;
        const inherited_action = parent.kind == .link or parent.kind == .external_link;
        if (inherited_action) {
            // The currently installed ordinary link owns this whole label. A
            // plain reading cannot introduce another action below that owner.
            const operation = self.explicit_wiki_label orelse return error.UncompiledPresentation;
            const label = operation.ordinary_label orelse return error.UncompiledPresentation;
            if (operation.kind != parent.kind or parent.kind != .link or operation.target.ptr != parent.target.ptr or
                operation.target.len != parent.target.len or parent.target.len == 0 or !wikiClassContains(label, content) or
                std.mem.indexOfAny(u8, body, "[]{}<>&|") != null or std.mem.indexOf(u8, body, "''") != null)
