            var remaining: usize = max_depth + 1;
            var found = false;
            while (current) |domain| : (current = domain.parent) {
                if (remaining == 0) return error.UncompiledPresentation;
                remaining -= 1;
                if (domain.source.ptr != label.ptr or domain.source.len != label.len) continue;
                const source = domain.tracked orelse return error.UncompiledPresentation;
                if (source.bytes.ptr != label.ptr or source.bytes.len != label.len or
                    !noLiParentSourceRange(source, content)) return error.UncompiledPresentation;
                found = true; break;
            }
            if (!found) return error.UncompiledPresentation;
