        const previous_classes = self.table_css_ancestor_classes;
        const previous_flags = self.block_formatting;
        const previous_poem_italic = self.poem_base_style.italic;
        defer self.table_css_ancestor_classes = previous_classes;
        defer self.block_formatting = previous_flags;
        defer self.poem_base_style.italic = previous_poem_italic;
        self.table_css_ancestor_classes = try self.cssClassesWith(previous_classes, tag);
