        if (effective.font_size_unknown or effective.ruby_script_ambiguous or
            (effective.direction.len != 0 and !std.mem.eql(u8, effective.direction, "ltr"))) return error.UncompiledPresentation;
        if (try self.htmlFontWeightIn(tag, source_parent.text_element, source_parent.bold or previous_flags.bold, source_parent.language)) |bold|
            self.block_formatting.bold = bold;
