    }

    const NativeInlineMotionScope = struct {
        renderer: *Renderer,
        changed: bool = false,
        active: bool = false,
        root: ?*const NativeInlineMotionRoot = null,
        epoch: u64 = 0,
        attributes: NativeInlineMotionState = .absent,
        language: NativeInlineMotionState = .absent,
        fn deinit(scope: NativeInlineMotionScope) void {
            if (!scope.changed) return;
            const renderer = scope.renderer;
            renderer.native_inline_motion_active = scope.active;
            renderer.native_inline_motion_root = scope.root;
            renderer.native_inline_motion_epoch = scope.epoch;
            renderer.body_formatting_attributes.native_inline_motion = scope.attributes;
            if (renderer.body_language_direction) |*style| style.native_inline_motion = scope.language;
        }
    };

    fn nativeInlineMotionBegin(self: *Renderer, root: *const NativeInlineMotionRoot, fragment_unknown: bool) NativeInlineMotionScope {
        var scope: NativeInlineMotionScope = .{ .renderer = self };
        if (self.native_inline_motion_active and !fragment_unknown) return scope;
        scope.changed = true;
        scope.active = self.native_inline_motion_active;
        scope.root = self.native_inline_motion_root;
        scope.epoch = self.native_inline_motion_epoch;
        scope.attributes = self.body_formatting_attributes.native_inline_motion;
        scope.language = if (self.body_language_direction) |style| style.native_inline_motion else .absent;
        self.native_inline_motion_active = true;
        self.native_inline_motion_root = null;
        self.native_inline_motion_epoch = 0;
        if (self.native_inline_motion_next != std.math.maxInt(u64)) {
            self.native_inline_motion_next += 1;
            self.native_inline_motion_epoch = self.native_inline_motion_next;
        }
        // This allocation fast-path grants no semantics. Typed Ruby padding
        // and unitless line-height both require complete native declarations.
        const candidate = candidate: {
            if (self.content_root == .parser_output) if (self.native_source_class_range) |range| {
                if (nativeSourceClassRangeCurrent(range, root.source, self.context.table_styles)) break :candidate true;
            };
            for (0..root.source.bytes.len) |at|
                if (std.ascii.startsWithIgnoreCase(root.source.bytes[at..], "padding") or
                    std.ascii.startsWithIgnoreCase(root.source.bytes[at..], "background") or
                    std.ascii.startsWithIgnoreCase(root.source.bytes[at..], "line-height") or
                    std.ascii.startsWithIgnoreCase(root.source.bytes[at..], "position") or
                    std.ascii.startsWithIgnoreCase(root.source.bytes[at..], "border") or
                    std.ascii.startsWithIgnoreCase(root.source.bytes[at..], "<ruby")) break :candidate true;
            break :candidate false;
        };
        if (!fragment_unknown and candidate and self.native_inline_motion_epoch != 0 and !root.source.lost_missing_range and
            root.source.generated_source == null and self.body_language_direction == null and
            std.meta.eql(self.body_formatting_attributes, FormattingAttributes{}) and
            self.table_css_ancestor_classes.len == 0 and self.body_link_target.len == 0 and
            !self.pre_block and !self.parsed_pre and !self.in_reference and self.poem_depth == 0)
            self.native_inline_motion_root = root;
        self.body_formatting_attributes.native_inline_motion = if (self.native_inline_motion_root) |current|
            .{ .proved = .{ .root = current, .epoch = self.native_inline_motion_epoch } } else .unknown;
        if (self.body_language_direction) |*style| style.native_inline_motion = .unknown;
        return scope;
    }

    fn nativeInlineMotionEntry(self: *Renderer, tag: syntax.Tag, parent: NativeInlineMotionState) Error!NativeInlineMotionState {
        const state = switch (parent) { .proved => |value| value, else => return .unknown };
        if (self.native_inline_motion_root != state.root or self.native_inline_motion_epoch != state.epoch) return .unknown;
        const css = (try self.semanticAttribute(tag, "style")) orelse "";
        for ([_]?MissingText{ self.inline_missing, self.body_missing }) |maybe| if (maybe) |tracked| {
            if (!wikiClassContains(tracked.bytes, tag.name)) continue;
            const name_at = @intFromPtr(tag.name.ptr) - @intFromPtr(tracked.bytes.ptr);
            if (name_at == 0) continue;
            const raw = syntax.tagAt(tracked.bytes, name_at - 1) orelse continue;
            // Tag.end is relative to its parser input, which can be a borrowed
            // suffix. Pointer identity plus the exact attrs identifies the same
            // opener without transplanting that relative end coordinate.
            if (raw.name.ptr != tag.name.ptr or raw.name.len != tag.name.len or raw.closing or
                raw.self_closing or raw.html_pre or raw.end > tracked.bytes.len or
                !std.mem.eql(u8, raw.attrs, tag.attrs)) continue;
            const opening = tracked.bytes[name_at - 1..raw.end];
            if (!noLiParentSourceRange(tracked, opening)) continue;
            const actual = (try self.semanticAttribute(raw, "style")) orelse "";
            if (!std.mem.eql(u8, actual, css)) continue;
            const snapshot = try self.a.dupe(u8, opening);
            errdefer self.a.free(snapshot);
            const owned_css = try self.a.dupe(u8, css);
            errdefer self.a.free(owned_css);
            const declaration = try self.a.create(NativeInlineMotionDeclaration);
            declaration.* = .{ .previous = state.last, .source = tracked, .opening = opening,
                .opening_snapshot = snapshot, .css = owned_css };
            return .{ .proved = .{ .root = state.root, .epoch = state.epoch, .last = declaration } };
        };
        return .unknown;
    }

    fn nativeInlineMotionWikiTag(self: *Renderer, origin: NativeInlineMotionOrigin, raw_boundary: []const u8) Error!?syntax.Tag {
        if (raw_boundary.len == 0 or std.mem.indexOfAny(u8, raw_boundary, "\r\n") != null) return null;
        const raw_attributes = switch (origin) {
            .html => return null,
            .wiki_table => if (starts(raw_boundary, "{|")) raw_boundary[2..] else return null,
            .wiki_row => if (starts(raw_boundary, "|-")) raw_boundary[2..] else return null,
            .wiki_td, .wiki_th => cell: {
                if (raw_boundary[0] != '|' and raw_boundary[0] != '!') return null;
                const raw_cell = raw_boundary[1..];
                break :cell if (cellAttributePipe(raw_cell)) |pipe| raw_cell[0..pipe] else raw_cell[0..0];
            },
        };
        const attributes = try self.wikiTableViewAttrs(raw_attributes);
        // Derived attributes cannot certify the complete authored boundary.
        if (attributes.ptr != raw_attributes.ptr or attributes.len != raw_attributes.len) return null;
        return .{ .name = switch (origin) {
            .html => unreachable, .wiki_table => "table", .wiki_row => "tr", .wiki_td => "td", .wiki_th => "th",
        }, .attrs = attributes, .end = 0, .closing = false, .self_closing = false };
    }

    fn nativeInlineMotionWikiEntry(self: *Renderer, origin: NativeInlineMotionOrigin, raw_boundary: []const u8,
        expected_tag: syntax.Tag, parent: NativeInlineMotionState) Error!NativeInlineMotionState
    {
        const state = switch (parent) { .proved => |value| value, else => return .unknown };
        if (self.native_inline_motion_root != state.root or self.native_inline_motion_epoch != state.epoch) return .unknown;
        const actual = (try self.nativeInlineMotionWikiTag(origin, raw_boundary)) orelse return .unknown;
        if (expected_tag.closing or expected_tag.self_closing or expected_tag.html_pre or
            !actual.is(expected_tag.name) or !std.mem.eql(u8, actual.attrs, expected_tag.attrs)) return .unknown;
        const operation_source: ?MissingText = if (self.literal_wiki_table_operation) |operation| operation.tracked else null;
        var selected_source: ?MissingText = null;
        for ([_]?MissingText{ self.inline_missing, self.body_missing, operation_source }) |maybe| {
          if (maybe) |tracked| {
            if (!wikiClassContains(tracked.bytes, raw_boundary)) continue;
            // Check every containing domain before retaining the parser source;
            // a clean inline view cannot override tainted body/operation metadata.
            if (!noLiParentSourceRange(tracked, raw_boundary)) return .unknown;
            selected_source = tracked;
          }
        }
        const tracked = selected_source orelse return .unknown;
        const css = (try self.semanticAttribute(actual, "style")) orelse "";
        const snapshot = try self.a.dupe(u8, raw_boundary);
        errdefer self.a.free(snapshot);
        const owned_css = try self.a.dupe(u8, css);
        errdefer self.a.free(owned_css);
        const declaration = try self.a.create(NativeInlineMotionDeclaration);
        declaration.* = .{ .previous = state.last, .source = tracked, .opening = raw_boundary,
            .opening_snapshot = snapshot, .css = owned_css, .origin = origin };
        return .{ .proved = .{ .root = state.root, .epoch = state.epoch, .last = declaration } };
    }

    // Failure-only detail; the established rejection operation/reason/bits stay
    // unchanged. No caller needs to re-evaluate the retained source chain.
    const NativeInlineMotionDeclarationDiagnostic = enum {
        none, absent_without_root, absent_with_root, unknown_without_root, unknown_with_root,
        root_mismatch, epoch_mismatch, root_lost_missing, root_generated, reference_stale,
        depth, declaration_source, opening_changed, opening_parse, opening_shape, wiki_opening, css_changed,
    };
    fn nativeInlineMotionDeclarationRejected(diagnostic: ?*NativeInlineMotionDeclarationDiagnostic,
        reason: NativeInlineMotionDeclarationDiagnostic) void
    {
        if (diagnostic) |out| out.* = reason;
    }
    fn nativeInlineMotionDeclarations(self: *Renderer, state: NativeInlineMotionState) Error!?[]const []const u8 {
        return self.nativeInlineMotionDeclarationsDiagnosed(state, null);
    }
    fn nativeInlineMotionDeclarationsDiagnosed(self: *Renderer, state: NativeInlineMotionState,
        diagnostic: ?*NativeInlineMotionDeclarationDiagnostic) Error!?[]const []const u8
    {
        return self.nativeInlineMotionDeclarationsWithScriptAbsence(state, diagnostic, null);
    }
    fn nativeInlineMotionDeclarationsWithScriptAbsence(self: *Renderer, state: NativeInlineMotionState,
        diagnostic: ?*NativeInlineMotionDeclarationDiagnostic, no_sup_sub: ?*bool) Error!?[]const []const u8
    {
        return self.nativeInlineMotionDeclarationsForQuery(state, diagnostic, no_sup_sub, null);
    }

    fn nativeInlineMotionDeclarationsForQuery(self: *Renderer, state: NativeInlineMotionState,
        diagnostic: ?*NativeInlineMotionDeclarationDiagnostic, no_sup_sub: ?*bool, tags: ?[][]const u8) Error!?[]const []const u8
    {
        if (no_sup_sub) |out| out.* = false;
        var script_absent = true;
        const held = switch (state) {
            .proved => |value| value,
            .absent => {
                nativeInlineMotionDeclarationRejected(diagnostic, if (self.native_inline_motion_root == null) .absent_without_root else .absent_with_root);
                return null;
            },
            .unknown => {
                nativeInlineMotionDeclarationRejected(diagnostic, if (self.native_inline_motion_root == null) .unknown_without_root else .unknown_with_root);
                return null;
            },
        };
        // Compare the active pointer before dereferencing any retained receipt.
        if (self.native_inline_motion_root != held.root) {
            nativeInlineMotionDeclarationRejected(diagnostic, .root_mismatch); return null;
        }
        if (self.native_inline_motion_epoch != held.epoch) {
            nativeInlineMotionDeclarationRejected(diagnostic, .epoch_mismatch); return null;
        }
        if (held.root.source.lost_missing_range) {
            nativeInlineMotionDeclarationRejected(diagnostic, .root_lost_missing); return null;
        }
        if (held.root.source.generated_source != null) {
            nativeInlineMotionDeclarationRejected(diagnostic, .root_generated); return null;
        }
        if (held.root.reference != null) {
            nativeInlineMotionDeclarationRejected(diagnostic, .reference_stale); return null;
        }
        var result: std.ArrayList([]const u8) = .empty;
        errdefer result.deinit(self.a);
        var next = held.last;
        var remaining: usize = max_depth + 1;
        while (next) |declaration| : (next = declaration.previous) {
            if (remaining == 0) {
                nativeInlineMotionDeclarationRejected(diagnostic, .depth);
                result.deinit(self.a); return null;
            }
            if (!noLiParentSourceRange(declaration.source, declaration.opening)) {
                nativeInlineMotionDeclarationRejected(diagnostic, .declaration_source);
                result.deinit(self.a); return null;
            }
            if (!std.mem.eql(u8, declaration.opening, declaration.opening_snapshot)) {
                nativeInlineMotionDeclarationRejected(diagnostic, .opening_changed);
                result.deinit(self.a); return null;
            }
            remaining -= 1;
            const opening = declaration.opening;
            const tag = if (declaration.origin == .html) html: {
                const parsed = syntax.tagAt(opening, 0) orelse {
                    nativeInlineMotionDeclarationRejected(diagnostic, .opening_parse);
                    result.deinit(self.a); return null;
                };
                if (parsed.closing or parsed.self_closing or parsed.html_pre or parsed.end != opening.len) {
                    nativeInlineMotionDeclarationRejected(diagnostic, .opening_shape);
                    result.deinit(self.a); return null;
                }
                break :html parsed;
            } else (try self.nativeInlineMotionWikiTag(declaration.origin, opening)) orelse {
                nativeInlineMotionDeclarationRejected(diagnostic, .wiki_opening);
                result.deinit(self.a); return null;
            };
            const css = (try self.semanticAttribute(tag, "style")) orelse "";
            if (!std.mem.eql(u8, css, declaration.css)) {
                nativeInlineMotionDeclarationRejected(diagnostic, .css_changed);
                result.deinit(self.a); return null;
            }
            if (tag.is("sup") or tag.is("sub")) script_absent = false;
            if (tags) |names| {
                if (result.items.len < names.len) names[result.items.len] = tag.name;
            }
            try result.append(self.a, css);
        }
        const declarations = try result.toOwnedSlice(self.a);
        if (no_sup_sub) |out| out.* = script_absent;
        return declarations;
    }

    fn observerFormattingAttributes(self: *Renderer) FormattingAttributes {
        var value = self.formattingAttributes();
        // Probe callbacks can retain attributes beyond this renderer's arena.
        value.native_inline_motion = .unknown;
        return value;
    }

    const RubyCaptured = struct { spans: []const Span, style: Style, flags: SpanFlags };

    fn rubyCapture(self: *Renderer, tracked: MissingText, raw: []const u8, inherited: Style, depth: usize, annotation_default: bool, wrapped: bool, gap: bool) Error!RubyCaptured {
        var content = raw;
        var reading_container = false;
        var effective = inherited;
        // RT's existing UA/default metric is independently owned. A numeric
        // factor from a base span cannot become an annotation or group metric.
        if (annotation_default) effective.ruby_unitless_line_height = null;
        const parent_cell_context = self.cell_line_context;
        const parent_classes = self.table_css_ancestor_classes;
        const parent_flags = self.block_formatting;
        const parent_poem_italic = self.poem_base_style.italic;
        const parent_poem_underline = self.poem_base_style.underline;
        const parent_poem_strike = self.poem_base_style.strike;
        defer {
            self.cell_line_context = parent_cell_context;
            self.table_css_ancestor_classes = parent_classes;
            self.block_formatting = parent_flags;
            self.poem_base_style.italic = parent_poem_italic;
            self.poem_base_style.underline = parent_poem_underline;
            self.poem_base_style.strike = parent_poem_strike;
        }
        // The outer Ruby owns inherited base-container decoration. Children,
        // readings and explicit RP fallback carry only their own decorations.
        effective.underline = false;
        effective.strike = false;
        self.block_formatting.underline = false;
        self.block_formatting.strike = false;
        self.poem_base_style.underline = false;
        self.poem_base_style.strike = false;
        if (wrapped) {
            const raw_tag = syntax.tagAt(raw, 0) orelse return error.UncompiledPresentation;
            const child_pair = syntax.matchingTag(raw, raw_tag) orelse return error.UncompiledPresentation;
            const child_tag = try self.normalizedTag(raw_tag);
            reading_container = child_tag.is("rt");
            if (child_pair.end != raw.len or !try self.rubyLayoutSupported(child_tag, effective, raw)) return error.UncompiledPresentation;
            content = raw[child_tag.end..child_pair.inner_end];
            if (self.cell_line_source_observation)
                self.cell_line_context = try self.cellScopeNativeContext(self.cellNativeFlowContext(self.block_formatting), child_tag);
            if (hasCompleteAncestorClasses(effective.text_element) or (effective.text_element == null and self.boundedTextClassScopeFor(child_tag) != null))
                effective.text_element = try self.textElement(child_tag, effective.text_element, effective.language);
            self.table_css_ancestor_classes = try self.cssClassesWith(parent_classes, child_tag);
            if (try self.htmlDisplayNoneIn(child_tag, effective.text_element)) return error.UncompiledPresentation;
            const parent_font_tag = self.ruby_annotation_font_tag;
            self.ruby_annotation_font_tag = if (annotation_default) child_tag else null;
            defer self.ruby_annotation_font_tag = parent_font_tag;
            const style_parent = effective;
            effective = try self.htmlInlineStyle(child_tag, style_parent);
            if (try self.htmlFontWeightIn(child_tag, style_parent.text_element, style_parent.bold or parent_flags.bold, style_parent.language)) |bold|
                self.block_formatting.bold = bold;
            if (try self.htmlFontStyleIn(child_tag, style_parent.text_element, style_parent.italic or parent_flags.italic, style_parent.language)) |italic| {
                self.block_formatting.italic = italic;
                if (self.poem_depth != 0) self.poem_base_style.italic = italic;
            }
        }
        if (!rubyBodyStructure(content)) return error.UncompiledPresentation;
        if (effective.font_size_unknown or effective.ruby_script_ambiguous) return error.UncompiledPresentation;
        const parent_spans = self.spans;
        self.spans = .empty;
        defer self.spans = parent_spans;
        if (!reading_container or !try self.rubyInlinePaddingCapture(tracked, content, effective, depth))
            try self.inlineTextWithMissing(try self.borrowedInlineHtmlSlice(tracked, content), effective, depth);
        // Image-attribute probes classify unresolved template diagnostics before
        // flattening. Preserve that error domain before Ruby body validation;
        // render-limit and literal-markup failures retain their earlier priority.
        if (self.inline_image_attribute and !self.truncated and !self.fallbacks.render_limit and
            !self.fallbacks.literal_markup and self.unresolved_templates != self.protected_bare_parameter_events)
            return error.UncompiledTemplate;
        for (self.spans.items, 0..) |span, child_index| {
            if (!(if (gap) presentation_types.validRubyChild(span) else presentation_types.validRubyBodyChild(span)) or span.pending_figure != null or
                span.pending_container != null or span.pending_bidi_scope != null or span.captured_bidi_scope != null or span.font_size_unknown)
            {
                if (self.context.table_viewport_trace) std.debug.print(
                    "RUBY_CHILD_REFUSAL cell={any} raw={s} child={d} kind={s} text={s} child_valid={any} body_valid={any} inline_valid={any} paint_valid={any} scale={any} basis={s} unknown={any} figure={any} container={any} bidi={any} captured_bidi={any}\n",
                    .{ self.cell_line_source_observation, raw[0..@min(raw.len, 256)], child_index, @tagName(span.kind), span.text[0..@min(span.text.len, 128)],
                        presentation_types.validRubyChild(span), presentation_types.validRubyBodyChild(span), presentation_types.validSpanInlineStyle(span),
                        presentation_types.validSpanLinkPaint(span), span.font_scale, @tagName(span.font_scale_basis), span.font_size_unknown,
                        span.pending_figure != null, span.pending_container != null, span.pending_bidi_scope != null, span.captured_bidi_scope != null });
                return error.UncompiledPresentation;
            }
        }
        if (gap and !presentation_types.validRubyGap(self.spans.items)) return error.UncompiledPresentation;
