        const surrounding = self.bodyFormattingStyle(.{});
        if (style.font_features == null) style.font_features = surrounding.font_features;
        if (style.font_family == null) style.font_family = surrounding.font_family;
        if (style.font_scale == null and !style.font_scale_set) {
