        bases: std.ArrayList(presentation_types.RubyBase(Span)) = .empty,
        annotations: std.ArrayList(presentation_types.RubyAnnotation(Span)) = .empty,
        segment_gap: []const Span = &.{},
        pending_gap: []const u8 = "",
        pending_fallback: ?[]const Span = null,
        fallback_after_set: bool = false,
