                if (seed.correction) |*value| if (value.* >= at) { value.* += len; };
                if (seed.boundaries.link_close) |*value| if (value.* >= at) { value.* += len; };
                if (seed.boundaries.template_close) |*value| if (value.* >= at) { value.* += len; };
