                if (manualExternalAngleEnd(input, at)) |end| {
                    at = end;
                    continue;
                }
                const tag = syntax.tagAt(input, at) orelse return false;
                if (oneOf(tag.name, &.{"nowiki"})) {
                    // With identity conversion, delimiter-free literal text commutes
                    // with nowiki stripping. Keep its source bytes and provenance.
                    if (tag.closing or tag.self_closing or trim(tag.attrs).len != 0) return false;
                    const pair = syntax.matchingTag(input, tag) orelse return false;
                    const closing = syntax.tagAt(input, pair.inner_end) orelse return false;
                    if (!closing.closing or closing.self_closing or !oneOf(closing.name, &.{"nowiki"}) or
                        trim(closing.attrs).len != 0 or closing.end != pair.end or
                        std.mem.indexOfAny(u8, input[tag.end..pair.inner_end], "<>{}&") != null) return false;
                    at = pair.end;
                    continue;
                }
                if (!formattingAngleAttributesBalanced(tag.attrs) or (tag.closing and trim(tag.attrs).len != 0) or
                    std.mem.indexOf(u8, tag.attrs, "{{") != null or
                    std.mem.indexOf(u8, tag.attrs, "-{") != null or std.mem.indexOf(u8, tag.attrs, "}-") != null or
                    oneOf(tag.name, &.{ "nowiki", "ref", "references", "pre", "code", "math", "syntaxhighlight", "source", "script", "style", "svg", "textarea" })) return false;
                // Do not jump to tag.end: raw delimiters in attributes still count.
            }
            if (starts(input[at..], "-{")) {
                if (depth == opens.len) return false;
                opens[depth] = at;
                depth += 1;
                at += 2;
                continue;
            }
            if (starts(input[at..], "}-")) {
                depth -= 1;
                if (depth == 0) return false;
                if (!manualRuleHasNoMutationFlags(input[opens[depth] + 2 .. at])) return false;
                at += 2;
                continue;
            }
            at += 1;
        }
        return depth == 1;
    }
    // Parser::doQuotes treats a sole four-apostrophe run as one literal
    // apostrophe plus bold, closed at the physical line end. Its no-rule
    // conversion wrapper may therefore end before the generated bold scope.
    // Remove only that wrapper before the ordinary quote phase; no arbitrary
    // unbalanced HTML or cross-line quote scope is admitted here.
    fn manualFourQuoteLine(input: []const u8, opening: usize, close: usize) bool {
        if (opening > close or close > input.len or close - opening != 6 or
            !std.mem.eql(u8, input[opening + 2 .. close], "''''")) return false;
        const line_start = if (std.mem.lastIndexOfScalar(u8, input[0..opening], '\n')) |pos| pos + 1 else 0;
        const line_end = std.mem.indexOfScalarPos(u8, input, close, '\n') orelse input.len;
        const prefix = input[line_start..opening];
        if ((opening != line_start and input[opening - 1] != ' ' and input[opening - 1] != '\t') or
            starts(prefix, " ") or starts(prefix, "\t") or starts(trim(prefix), "=") or
            starts(trim(prefix), "|") or starts(trim(prefix), "!") or starts(trim(prefix), "{|") or
            !formattingAngleBodyPosition(input[line_start..], opening - line_start)) return false;
        // Any additional apostrophe could change doQuotes' odd bold/italic
        // heuristic or merge a run. Preserve that unsupported domain exactly.
        return std.mem.indexOfScalar(u8, input[line_start..opening], '\'') == null and
            std.mem.indexOfScalar(u8, input[close..line_end], '\'') == null and
            std.mem.indexOfScalar(u8, input[line_start..line_end], '\r') == null;
    }

    // ConverterRule's no-rule display retains ordinary text and its line
    // separators. Prepare only a complete plain body whose closer occupies its
    // own line, before physical list/paragraph parsing. Retain every LF; never
    // join source lines or lend rule/link/parameter semantics to their contents.
    fn preparePlainMultilineManualWithMissing(self: *Renderer, source: MissingText) Error!MissingText {
        const ns = self.context.namespace_catalog orelse return source;
        if (ns.language_conversion == null or self.context.content_conversion != true or
            self.context.citations != null or self.context.external_links_prepared or self.context.poem_phase != null or
            self.in_reference or self.pre_block or self.parsed_pre or self.block_formatting.code or
            self.in_template_literal_scope or self.body_link_target.len != 0 or self.inline_source_domain != null or
            source.unknown or source.ranges.len != 0 or source.literal_curly_ranges.len != 0 or source.generated_links.len != 0)
            return source;
        const input = source.bytes;
        if (!std.unicode.utf8ValidateSlice(input) or std.mem.indexOf(u8, input, "{{") != null) return source;
        var edits: missing_dependency.Builder = .{};
        defer edits.deinit(self.a);
        var emitted: usize = 0;
        var at: usize = 0;
        var wiki_table_boundary_seen = false;
        while (at < input.len) {
            if (starts(input[at..], "<!--")) {
                at = (std.mem.indexOfPos(u8, input, at + 4, "-->") orelse return source) + 3;
                continue;
            }
            if (input[at] == '<') {
                const tag = syntax.tagAt(input, at) orelse return source;
                if (!formattingAngleAttributesBalanced(tag.attrs) or (tag.closing and trim(tag.attrs).len != 0)) return source;
                if (!tag.closing and !tag.self_closing and oneOf(tag.name, &.{ "nowiki", "ref", "references", "pre", "code", "math", "syntaxhighlight", "source", "script", "style", "svg", "textarea", "poem", "a", "includeonly", "noinclude", "onlyinclude", "table", "caption", "tr", "td", "th", "ul", "ol", "li", "dl", "dt", "dd" })) {
                    at = (syntax.matchingTag(input, tag) orelse return source).end;
                } else at = tag.end;
                continue;
            }
            if (starts(input[at..], "[[")) {
                at = (syntax.balanced(input, at) orelse return source).end;
                continue;
            }
            if (input[at] == '[') {
                var links: ir.InlineIterator = .{ .input = input, .cursor = at, .renderer_boundaries = true };
                const link_token = links.next() orelse return source;
                if (link_token.kind == .external_link) { at = links.cursor; continue; }
            }
            if (starts(input[at..], "{|") or starts(input[at..], "|}")) wiki_table_boundary_seen = true;
            if (!starts(input[at..], "-{")) { at += 1; continue; }
            const close = std.mem.indexOfPos(u8, input, at + 2, "}-") orelse return source;
            const body = input[at + 2 .. close];
            // An inner delimiter or unsupported rule can affect later manual
            // conversion. Do not partly prepare such a page.
            if (std.mem.indexOf(u8, body, "-{") != null or !manualRuleHasNoMutationFlags(body)) return source;
            if (std.mem.eql(u8, body, "''''")) {
                if (!manualFourQuoteLine(input, at, close)) return source;
                try edits.appendSlice(self.a, source, emitted, at);
                try edits.appendSlice(self.a, source, at + 2, close);
                emitted = close + 2;
                at = close + 2;
                continue;
            }
            if (std.mem.indexOfScalar(u8, body, '\n') == null) { at = close + 2; continue; }
            // No table ancestry is inferred from textual closers. A candidate
            // after any encountered wiki-table boundary stays on the old path.
            if (wiki_table_boundary_seen) return source;
            if (body.len < 2 or body[body.len - 1] != '\n' or
                std.mem.indexOfAny(u8, body, "{}[]<>&|:;=\"'#!*_") != null) return source;
            // A new adjacency must not construct a bare URL or join a numeric
            // ISBN/RFC/PMID operand to text before the original wrapper.
            if ((at != 0 and input[at - 1] != '\n' and input[at - 1] != ' ' and input[at - 1] != '\t') or
                !std.ascii.isAlphabetic(body[0])) return source;
            for (body) |byte| if (std.ascii.isControl(byte) and byte != '\n') return source;
            // Empty/interior blank lines and leading spaces can introduce
            // block structure before conversion; only ordinary text lines pass.
            var lines = std.mem.splitScalar(u8, body[0 .. body.len - 1], '\n');
            while (lines.next()) |line| {
                if (line.len == 0 or std.ascii.isWhitespace(line[0]) or line[0] == '-' or line[0] == '~') return source;
            }
            const physical_start = if (std.mem.lastIndexOfScalar(u8, input[0..at], '\n')) |pos| pos + 1 else 0;
            const prefix = input[physical_start..at];
            if (!formattingAngleBodyPosition(input[physical_start..], at - physical_start) or
                std.mem.indexOf(u8, prefix, "''") != null or starts(prefix, " ") or starts(prefix, "\t") or
                starts(trim(prefix), "=")) return source;
            const physical_end = std.mem.indexOfScalarPos(u8, input, close + 2, '\n') orelse input.len;
            if (trim(input[close + 2 .. physical_end]).len != 0) return source;
            // Removing a nonempty closer line must not create a new paragraph
            // break between ordinary lines. An existing following blank/EOF
            // already supplies the same physical boundary.
            if (physical_end < input.len) {
                const following_end = std.mem.indexOfScalarPos(u8, input, physical_end + 1, '\n') orelse input.len;
                if (trim(input[physical_end + 1 .. following_end]).len != 0) return source;
            }
            try edits.appendSlice(self.a, source, emitted, at);
            try edits.appendSlice(self.a, source, at + 2, close);
            emitted = close + 2;
            at = close + 2;
        }
        if (emitted == 0) return source;
        try edits.appendSlice(self.a, source, emitted, input.len);
        return edits.finish(self.a);
    }

    fn unmatchedManualIdentity(self: *const Renderer) bool {
        const ns = self.context.namespace_catalog orelse return false;
        const profile = ns.manual_conversion_context orelse return false;
        const effective = profile.effective_override orelse return false;
        const variants = ns.language_conversion orelse return false;
        const title = ns.ofTitle(effective.namespace_title);
        if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or !std.mem.eql(u8, profile.base, ns.content_language) or
            !manualVariantKnown(profile.base, variants) or profile.source_core.len != 40 or profile.source_converter_sha256.len != 64 or profile.siteinfo_sha256.len != 64 or
            title.id != 8 or !starts(title.text, "Conversiontable/") or !std.mem.eql(u8, title.text["Conversiontable/".len..], profile.base) or
            !starts(effective.message_key, "conversiontable/") or !std.mem.eql(u8, effective.message_key["conversiontable/".len..], profile.base) or
            !profile.automatic_identity or self.context.content_conversion != true or
            effective.interface_messages_sha256.len != 64 or effective.language_fallbacks_sha256.len != 64 or
            effective.page_index_sha256.len != 64 or effective.page_index_bytes == 0 or
            effective.title_index_sha256.len != 64 or effective.title_index_bytes == 0) return false;
        return true;
    }
    // The unmatched-rule converter keeps its opening marker, then converts the
    // tail. Only whole-page identity preparation may attest that marker below.
    // This local proof keeps TT formatting intact; it grants no code exemption.
    // A closed, plain rowless table is recovered outside its empty table box.
    // In this finite translation form, link rejection precedes the block pass,
    // then conversion removes the first generated </li></ul> with its prefix.
    // The following independent UL groups therefore remain inside that LI.
    fn translationListRuleAt(line: []const u8) ?usize {
        if (line.len < 10 or line[0] != '*') return null;
        const label_end = std.mem.indexOf(u8, line, ": [") orelse return null;
        const label = line[1..label_end];
        if (trim(label).len == 0 or std.mem.indexOfAny(u8, label, "<>[]{}&|;:\"'\r\n\t*#=") != null) return null;
        for (label) |byte| if (std.ascii.isControl(byte)) return null;
        var at = label_end + 3;
        const number = at;
        while (at < line.len and std.ascii.isDigit(line[at])) : (at += 1) {}
        if (at == number or !starts(line[at..], "] ")) return null;
        at += 2;
        while (at < line.len and line[at] == ' ') : (at += 1) {}
        return if (starts(line[at..], "-{")) at else null;
    }
    const RowlessManualPair = struct { opening: usize, suffix: usize, close: usize, end: usize, line_feeds: usize };
    fn rowlessManualPairAt(input: []const u8, begin: usize) ?RowlessManualPair {
        const first_lf = std.mem.indexOfScalarPos(u8, input, begin, '\n') orelse return null;
        const opening = begin + (translationListRuleAt(input[begin..first_lf]) orelse return null);
        const close = std.mem.indexOfPos(u8, input, opening + 2, "}-") orelse return null;
        var at = opening + 2;
        while (at < close and input[at] == ' ') : (at += 1) {}
        if (!starts(input[at..close], "[[")) return null;
        const target_start = at + 2;
        const target_end = std.mem.indexOfPos(u8, input, target_start, "]]") orelse return null;
        if (target_end >= close) return null;
        const target = input[target_start..target_end];
        if (target.len == 0 or target.len > 4096 or (std.mem.count(u8, target, "\n") < 1 or std.mem.count(u8, target, "\n") > 3) or
            std.mem.indexOfAny(u8, target, "[]{}<>&|;=\"'\r\t") != null) return null;
        if (trim(target).len == 0) return null;
        var lines = std.mem.splitScalar(u8, target, '\n');
        var line_number: usize = 0;
        while (lines.next()) |line| : (line_number += 1) {
            // The complete plain TABLE keeps BlockLevelPass in block mode:
            // blank lines and spaces cannot create paragraph or PRE wrappers.
            // Physical list/heading syntax remains excluded even after spaces.
            const content = std.mem.trimStart(u8, line, " ");
            if (line_number != 0 and content.len != 0 and std.mem.indexOfScalar(u8, "*#:;!=-", content[0]) != null) return null;
            for (line) |byte| if (std.ascii.isControl(byte)) return null;
        }
        at = target_end + 2;
        const gap = at;
        while (at < close and input[at] == ' ') : (at += 1) {}
        if (at == gap or !starts(input[at..close], "[[:")) return null;
        const code_start = at + 3;
        const code_end = std.mem.indexOfScalarPos(u8, input, code_start, ':') orelse return null;
        if (code_end >= close) return null;
        const code = input[code_start..code_end];
        if (code.len == 0 or code.len > 16) return null;
        for (code) |byte| if (!std.ascii.isAlphabetic(byte) and byte != '-') return null;
        at = code_end + 1;
        if (target.len > close - at or !std.mem.eql(u8, input[at .. at + target.len], target)) return null;
        at += target.len;
        if (at >= close or input[at] != '|') return null;
        const suffix = at + 1;
        at = suffix;
        if (!starts(input[at..close], "\xe2\x98\x9e<sup>")) return null;
        at += "\xe2\x98\x9e<sup>".len;
        if (code.len > close - at or !std.mem.eql(u8, input[at .. at + code.len], code)) return null;
        at += code.len;
        if (!starts(input[at..close], "</sup>]]")) return null;
        at += "</sup>]]".len;
        while (at < close and input[at] == ' ') : (at += 1) {}
        if (at != close) return null;
        const end = std.mem.indexOfScalarPos(u8, input, close + 2, '\n') orelse input.len;
        if (trim(input[close + 2 .. end]).len != 0) return null;
        return .{ .opening = opening, .suffix = suffix, .close = close, .end = end, .line_feeds = std.mem.count(u8, target, "\n") };
    }
    fn rowlessLiteralListLabel(line: []const u8) bool {
        if (line.len < 3 or line[0] != '*' or line[line.len - 1] != ':') return false;
        const label = line[1 .. line.len - 1];
        if (trim(label).len == 0 or label[0] == ' ' or label[label.len - 1] == ' ') return false;
        for (label) |byte| if (byte < 0x80 and !std.ascii.isAlphabetic(byte) and byte != ' ' and byte != '-') return false;
        return std.unicode.utf8ValidateSlice(label);
    }

    fn prepareRowlessManualList(self: *Renderer, input: []const u8, complete: bool, plain_mode: bool) Error!?MissingText {
        if (!complete or !plain_mode or input.len > 32 * 1024 or !std.unicode.utf8ValidateSlice(input) or
            self.pre_block or self.parsed_pre or self.in_reference or self.in_template_literal_scope or
            self.block_formatting.code or self.poem_depth != 0 or self.body_link_target.len != 0 or
            self.explicit_wiki_label != null or self.navigation_target_probe != null or
            self.inline_image_attribute or self.inline_source_domain != null or !self.unmatchedManualIdentity()) return null;
        const ns = self.context.namespace_catalog orelse return null;
        const profile = ns.manual_conversion_context orelse return null;
        if (!std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2")) return null;
        const parent = self.body_missing orelse return null;
        if (parent.unknown or parent.lost_missing_range or parent.ranges.len != 0 or
            parent.literal_curly_ranges.len != 0 or parent.generated_links.len != 0) return null;
        const base = @intFromPtr(parent.bytes.ptr);
        const pointer = @intFromPtr(input.ptr);
        if (pointer < base or pointer - base > parent.bytes.len or input.len > parent.bytes.len - (pointer - base) or
            !formattingAngleBodyPosition(parent.bytes, pointer - base)) return null;
        // Each rejected multiline pair removes one generated LI/UL closure.
        // Complete ordinary groups before it stay flat; subsequent groups are
        // children of the surviving item until the enclosing rowless table ends.
        const Group = struct { begin: usize, pair: RowlessManualPair };
        var pairs: [2]Group = undefined;
        var pair_count: usize = 0;
        var ordinary_since_pair: usize = 0;
        var group_count: usize = 0;
        var begin: usize = 0;
        while (begin < input.len and input[begin] == '\n') : (begin += 1) {}
        if (begin == input.len) return null;
        var following = begin;
        var separated = true;
        while (following < input.len) {
            const line_begin = following;
            const line_end = std.mem.indexOfScalarPos(u8, input, following, '\n') orelse input.len;
            const line = input[following..line_end];
            following = if (line_end < input.len) line_end + 1 else line_end;
            if (line.len == 0) { separated = true; continue; }
            if (!separated or group_count >= 34 or std.mem.indexOfScalar(u8, line, '\r') != null) return null;
            if (rowlessManualPairAt(input, line_begin)) |pair| {
                if (pair_count == pairs.len or (pair_count != 0 and ordinary_since_pair == 0)) return null;
                pairs[pair_count] = .{ .begin = line_begin, .pair = pair };
                pair_count += 1;
                ordinary_since_pair = 0;
                following = if (pair.end < input.len) pair.end + 1 else pair.end;
            } else {
                const tail = std.mem.trimEnd(u8, line, " ");
                if (!rowlessLiteralListLabel(tail)) {
                    const rule = translationListRuleAt(tail) orelse return null;
                    if (!std.mem.endsWith(u8, tail, "}-") or
                        !self.manualConversionLinkedScope(tail[rule + 2 .. tail.len - 2], true)) return null;
                }
                ordinary_since_pair += 1;
            }
            group_count += 1;
            separated = false;
        }
        if (pair_count == 0 or ordinary_since_pair == 0) return null;
        var output: missing_dependency.Builder = .{};
        errdefer output.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        const source: MissingText = .{ .bytes = input };
        var copied_until = begin;
        for (pairs[0..pair_count]) |group| {
            try self.appendMissingHeadingSourceCopy(&output, &copies, source, copied_until, group.begin);
            try output.append(self.a, MissingText.untracked("<ul><li>"));
            try self.appendMissingHeadingSourceCopy(&output, &copies, source, group.begin + 1, group.pair.opening);
            try self.appendMissingHeadingSourceCopy(&output, &copies, source, group.pair.suffix, group.pair.close);
            copied_until = group.pair.end;
        }
        try self.appendMissingHeadingSourceCopy(&output, &copies, source, copied_until, input.len);
        for (0..pair_count) |_| try output.append(self.a, MissingText.untracked("</li></ul>"));
        const prepared = try output.finish(self.a);
        try self.registerHeadingSourceCopies(prepared.bytes, copies.items);
        return prepared;
    }

    fn unmatchedTtPair(input: []const u8, at: usize) ?syntax.Pair {
        if (at >= input.len) return null;
        const tag = syntax.tagAt(input, at) orelse return null;
        if (!tag.is("tt") or tag.closing or tag.self_closing or trim(tag.attrs).len != 0) return null;
        const pair = syntax.matchingTag(input, tag) orelse return null;
        const closing = syntax.tagAt(input, pair.inner_end) orelse return null;
        if (!closing.is("tt") or !closing.closing or closing.self_closing or
            trim(closing.attrs).len != 0 or closing.end != pair.end) return null;
        const body = input[tag.end..pair.inner_end];
        if (body.len <= 2 or body.len > 4096 or !starts(body, "-{") or
            !std.unicode.utf8ValidateSlice(body) or
            std.mem.indexOfAny(u8, body[2..], "[]{}<>&|:;=\"'") != null) return null;
        for (body[2..]) |byte| if (std.ascii.isControl(byte)) return null;
        return pair;
    }
    fn unmatchedTtBodyPosition(input: []const u8, at: usize) bool {
        if (at > input.len) return false;
        const opening = std.mem.lastIndexOfScalar(u8, input[0..at], '<') orelse return false;
        _ = unmatchedTtPair(input, opening) orelse return false;
        const tag = syntax.tagAt(input, opening) orelse return false;
        return tag.end == at and formattingAngleBodyPosition(input, opening);
    }
    fn unmatchedTtLiteralOpen(self: *const Renderer, tracked: MissingText, at: usize, pair: syntax.Pair, style: Style) bool {
        if (tracked.unknown or style.provenance != .parsed or style.kind != .text or
            style.target.len != 0 or style.self_link_target != null or style.image != null or
            style.missing_nonaction or style.code or style.preserve_whitespace or
            self.block_formatting.code or self.pre_block or self.parsed_pre or self.in_reference or
            self.in_template_literal_scope or self.body_link_target.len != 0 or
            self.explicit_wiki_label != null or self.navigation_target_probe != null or
            self.inline_image_attribute) return false;
        if (!formattingAngleBodyPosition(tracked.bytes, at)) return false;
        const proved = unmatchedTtPair(tracked.bytes, at) orelse return false;
        if (proved.inner_end != pair.inner_end or proved.end != pair.end) return false;
        const tag = syntax.tagAt(tracked.bytes, at) orelse return false;
        for (tracked.ranges) |range| if (range.start < pair.end and range.end > at) return false;
        for (tracked.generated_links) |range| if (range.start < pair.end and range.end > at) return false;
