            }
            if (starts(input[at..], "-{")) {
                var frames = ManualConversionFrames.init(input, at);
                var complete: ?ManualConversionFrame = null;
                while (frames.next()) |frame| if (frame.parent_opening == null) { complete = frame; break; };
                if (frames.overflow) return source;
                if (complete) |frame| {
                    if (!manualRuleHasNoMutationFlags(frame.body(input))) return source;
                    at = frame.closing + 2;
                    continue;
                }
                const line = if (std.mem.lastIndexOfScalar(u8, input[0..at], '\n')) |newline| newline + 1 else 0;
                if ((!formattingAngleBodyPosition(input[line..], at - line) and !unmatchedTtBodyPosition(input[line..], at - line)) or
                    std.mem.indexOf(u8, input[line..at], "''") != null or !self.unmatchedManualTail(input, at, !source.lost_missing_range)) return source;
                var out: missing_dependency.Builder = .{};
                defer out.deinit(self.a);
                try out.appendSlice(self.a, source, 0, at + 1);
                try out.appendLiteralCurly(self.a, "{");
                try out.appendSlice(self.a, source, at + 2, input.len);
                return out.finish(self.a);
            }
            at += 1;
        }
        return source;
    }
    // Extents only: no source, grammar, action or converter capability is issued.
    // recursiveConvertRule scans raw child delimiters before ConverterRule parses
    // their displays. Keep borrowed coordinates and report children before owners.
    const ManualConversionFrame = struct {
        opening: usize,
        closing: usize,
        parent_opening: ?usize,
        fn body(frame: @This(), input: []const u8) []const u8 {
            return input[frame.opening + 2 .. frame.closing];
        }
    };
    const ManualConversionFrames = struct {
        input: []const u8,
        cursor: usize,
        openings: [max_depth]usize = undefined,
        count: usize = 0,
        overflow: bool = false,
        fn init(input: []const u8, opening: usize) @This() {
            var result: @This() = .{ .input = input, .cursor = input.len };
            if (opening <= input.len and input.len - opening >= 2 and starts(input[opening..], "-{")) {
                result.cursor = opening + 2;
                result.openings[0] = opening;
                result.count = 1;
            }
            return result;
        }
        fn next(frames: *@This()) ?ManualConversionFrame {
            while (frames.count != 0 and frames.cursor < frames.input.len and !frames.overflow) {
                const position = frames.cursor;
                if (starts(frames.input[position..], "-{")) {
                    if (frames.count == frames.openings.len) { frames.overflow = true; return null; }
                    frames.openings[frames.count] = position;
                    frames.count += 1;
                    frames.cursor += 2;
                } else if (starts(frames.input[position..], "}-")) {
                    frames.count -= 1;
                    frames.cursor += 2;
                    return .{ .opening = frames.openings[frames.count], .closing = position,
                        .parent_opening = if (frames.count == 0) null else frames.openings[frames.count - 1] };
                } else frames.cursor += 1;
            }
            return null;
        }
    };
    fn manualConversionExtent(input: []const u8, opening: usize) ?ManualConversionFrame {
        var frames = ManualConversionFrames.init(input, opening);
        while (frames.next()) |frame| if (frame.parent_opening == null) return frame;
        return null;
    }
    const ManualConversion = struct { body: []const u8, end: usize, multiline_boundary_lfs: bool = false };
    // The ordinary link parser already owns this complete explicit label.
    // Select only a whole-label plain choice before applying its unchanged
    // action. No destination, attribute, generated label or nested rule is
    // reinterpreted as converter source.
    fn manualChoiceWikiLabel(self: *Renderer, input: []const u8, begin: usize, end: usize, label: MissingText, style: Style) Error!?MissingText {
        if (self.context.content_conversion != true or begin >= end or end > input.len or
            label.bytes.len < 5 or label.bytes.len > 16 * 1024 or
            !starts(label.bytes, "-{") or !std.mem.endsWith(u8, label.bytes, "}-") or
            label.lost_missing_range or !ordinaryNormalizationRange(label, 0, label.bytes.len)) return null;
        const body = label.bytes[2 .. label.bytes.len - 2];
        if (std.mem.indexOfAny(u8, body, "{}[]<>&|\r\n") != null or
            std.mem.indexOf(u8, body, "''") != null or std.mem.indexOf(u8, body, "=>") != null) return null;
        const parent = self.inline_missing orelse return null;
        if (parent.lost_missing_range or parent.bytes.ptr != input.ptr or parent.bytes.len != input.len or
            !ordinaryNormalizationRange(parent, begin, end)) return null;
        var links: ir.InlineIterator = .{ .input = input[0..end], .cursor = begin, .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const node = links.next() orelse return null;
        if (node.kind != .link or !node.link_has_pipe or node.link_empty_label or node.link_label_restored_close or
            links.cursor != end or node.trail.len != 0 or node.text.ptr != label.bytes.ptr or node.text.len != label.bytes.len or
            !safeInternalTarget(node.target) or !formattingAngleBodyPosition(input, begin)) return null;
