    fn sourceRecursiveFormattingExternalLabel(self: *Renderer, source: MissingText, begin: usize, end: usize, target: []const u8, label: []const u8, style: Style) Error!?MissingText {
        if (self.context.content_conversion != true or !self.sourceRecursiveManualContext() or
            begin >= end or end > source.bytes.len or end - begin > 16 * 1024 or
            source.lost_missing_range or source.generated_source != null or
            label.len < 5 or !starts(label, "-{") or !std.mem.endsWith(u8, label, "}-") or
            style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or self.in_reference or
            self.pre_block or self.parsed_pre or self.in_template_literal_scope or self.body_link_target.len != 0 or
            self.explicit_wiki_label != null or self.navigation_target_probe != null or self.inline_image_attribute) return null;
        if (source.bytes[begin] != '[' or starts(source.bytes[begin..], "[[") or source.bytes[end - 1] != ']') return null;
        var links: ir.InlineIterator = .{ .input = source.bytes[0..end], .cursor = begin,
            .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const node = links.next() orelse return null;
        if (node.kind != .external_link or links.cursor != end or node.external_label_prefix.len != 0 or
            node.link_empty_label or node.link_label_restored_close or node.text.ptr == node.target.ptr or
            node.text.ptr != label.ptr or node.text.len != label.len or
            node.target.ptr != target.ptr or node.target.len != target.len or
