        const pointer = @intFromPtr(label.ptr);
        if (pointer <= base + begin or pointer > base + end or label.len >= base + end - pointer) return null;
        for (source.ranges) |range| if (range.start < end and range.end > begin) return null;
        for (source.literal_curly_ranges) |range| if (range.start < end and range.end > begin) return null;
        for (source.generated_links) |range| if (range.start < end and range.end > begin) return null;
        if (!formattingAngleBodyPosition(source.bytes, begin)) return null;
