        if (tracked_label.bytes.ptr != label.ptr or tracked_label.bytes.len != label.len) return null;
        const previous_domain = self.inline_source_domain;
        const previous_missing = self.inline_missing;
        self.inline_source_domain = null;
        self.inline_missing = tracked_label;
        defer {
            self.inline_source_domain = previous_domain;
            self.inline_missing = previous_missing;
        }
        const result = try self.sourceRecursiveRuleFreeFormattingBody(label, 0, style) orelse return null;
        if (result.end != label.len) return null;
