                style.target.len != 0 or style.self_link_target != null or style.image != null or style.missing_nonaction or
                style.code or style.preserve_whitespace or self.block_formatting.code or self.in_reference or
                self.pre_block or self.parsed_pre or self.in_template_literal_scope or self.body_link_target.len != 0 or
                self.explicit_wiki_label != null or self.navigation_target_probe != null or self.inline_image_attribute) return null;
            const local = if (starts(target, ":")) target[1..] else target;
            const page = local[0 .. (std.mem.indexOfScalar(u8, local, '#') orelse local.len)];
            if (page.len == 0 or std.mem.indexOfScalar(u8, page, ':') != null) return null;
            return try self.borrowedInlineHtmlSlice(label, plain_label_body);
        }
        const selected = try self.manualAlternativeIn(label.bytes, choice_at, close, style, true) orelse return null;
        const selected_at = @intFromPtr(selected.ptr) - @intFromPtr(label.bytes.ptr);
        var result: missing_dependency.Builder = .{};
        defer result.deinit(self.a);
        try result.appendSlice(self.a, label, 0, choice_at);
        try result.appendSlice(self.a, label, selected_at, selected_at + selected.len);
        try result.appendSlice(self.a, label, close + 2, label.bytes.len);
        return try result.finish(self.a);
    }

    fn manualAlternative(self: *Renderer, input: []const u8, at: usize, close: usize, style: Style) Error!?[]const u8 {
        return self.manualAlternativeIn(input, at, close, style, false);
    }
    fn manualAlternativeIn(self: *Renderer, input: []const u8, at: usize, close: usize, style: Style, semantic_source: bool) Error!?[]const u8 {
        return self.manualAlternativePayloadIn(input, at, close, style, semantic_source, false);
    }
    fn manualAlternativePayloadIn(self: *Renderer, input: []const u8, at: usize, close: usize, style: Style, semantic_source: bool, title_only: bool) Error!?[]const u8 {
        if (semantic_source and !self.sourceRecursiveManualContext()) return null;
        if (at > close or close - at > 16 * 1024 or close + 2 > input.len) return null;
        if (title_only) {
            if (semantic_source or self.context.content_conversion != true or close - at < 4 or
                !starts(input[at..], "-{T|") or !starts(input[close..], "}-")) return null;
            if (self.context.display_title_precedence) |accepted| {
                if (self.context.title.ptr != accepted.title.ptr or self.context.title.len != accepted.title.len or
                    self.context.namespace_catalog != accepted.namespace_catalog or accepted.display.bytes.len == 0 or
                    accepted.display.lost_missing_range or accepted.display.generated_source != null or
                    !ordinaryNormalizationRange(accepted.display, 0, accepted.display.bytes.len)) return null;
            } else {
                const defaults = self.context.normal_title_defaults orelse return null;
                if (!defaults.current(self.context.title, self.context.namespace_catalog)) return null;
            }
        }
        const ns = self.context.namespace_catalog orelse return null;
        const profile = ns.manual_conversion_context orelse return null;
        const variants = ns.language_conversion orelse return null;
        if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or
            !std.mem.eql(u8, profile.base, ns.content_language) or
            !manualVariantKnown(profile.base, variants) or profile.fallbacks.len > 32 or profile.source_core.len == 0 or
            profile.source_converter_sha256.len != 64 or profile.siteinfo_sha256.len != 64) return null;
        if (profile.separator_variants.len == 0 or profile.separator_variants.len > 64) return null;
        for (profile.separator_variants, 0..) |separator, index| {
            if (!manualVariantKnown(separator, variants)) return null;
            for (profile.separator_variants[0..index]) |previous| if (std.mem.eql(u8, previous, separator)) return null;
        }
        for (profile.fallbacks, 0..) |fallback, index| {
            if (!manualVariantKnown(fallback, variants)) return null;
            for (profile.fallbacks[0..index]) |previous| if (std.ascii.eqlIgnoreCase(previous, fallback)) return null;
        }
        if (title_only) {
            if (!std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2")) return null;
            for (profile.source_converter_sha256) |byte| if (!std.ascii.isHex(byte)) return null;
            for (profile.siteinfo_sha256) |byte| if (!std.ascii.isHex(byte)) return null;
        }
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or
            self.in_reference or self.pre_block or self.parsed_pre or self.in_template_literal_scope or
            self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            self.navigation_target_probe != null or self.inline_image_attribute) return null;
        if (!formattingAngleBodyPosition(input, at)) return null;
        var domain = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        while (domain) |current| {
            if (remaining == 0) return null;
            remaining -= 1;
            const base = @intFromPtr(current.source.ptr);
            const pointer = @intFromPtr(input.ptr);
            if (pointer < base) return null;
            const relative = pointer - base;
            if (relative > current.source.len or input.len > current.source.len - relative or
                !formattingAngleBodyPosition(current.source, relative + at)) return null;
            if (title_only) {
                const tracked = current.tracked orelse return null;
                if (tracked.bytes.ptr != current.source.ptr or tracked.bytes.len != current.source.len or
                    tracked.lost_missing_range or tracked.generated_source != null or
                    !ordinaryNormalizationRange(tracked, relative + at, relative + close + 2)) return null;
            }
            domain = current.parent;
        }
        const parent = self.inline_missing orelse return null;
        if (title_only) {
            const pointer = @intFromPtr(input.ptr);
            const base = @intFromPtr(parent.bytes.ptr);
            if (pointer < base or pointer - base > parent.bytes.len or input.len > parent.bytes.len - (pointer - base) or
                parent.lost_missing_range or parent.generated_source != null or
                !ordinaryNormalizationRange(parent, pointer - base + at, pointer - base + close + 2) or
                !formattingAngleBodyPosition(parent.bytes, pointer - base + at)) return null;
        }
        const original = try missingSlice(self.a, parent, input[at .. close + 2]);
        if ((original.unknown and !semantic_source) or original.ranges.len != 0 or original.literal_curly_ranges.len != 0 or
            original.generated_links.len != 0) return null;
        const body = input[at + 2 + @as(usize, if (title_only) 2 else 0) .. close];
        if (!std.unicode.utf8ValidateSlice(body)) return null;
        for (body) |byte| if (std.ascii.isControl(byte)) return null;
        const Alternative = struct { code: []const u8, value: []const u8 };
        var choices: [32]Alternative = undefined;
        var count: usize = 0;
        var start: usize = 0;
        while (start < body.len) {
            const colon = std.mem.indexOfScalarPos(u8, body, start, ':') orelse return null;
            const code = trim(body[start..colon]);
            if (!manualVariantKnown(code, variants)) return null;
            for (choices[0..count]) |previous| if (std.ascii.eqlIgnoreCase(previous.code, code)) return null;
            var end = body.len;
            var scan = colon + 1;
            while (std.mem.indexOfScalarPos(u8, body, scan, ';')) |semicolon| {
                scan = semicolon + 1;
                // ConverterRule shields entity terminators before splitting.
                var entity_start = semicolon;
                while (entity_start > colon + 1 and
                    (std.ascii.isAlphanumeric(body[entity_start - 1]) or body[entity_start - 1] == '#')) : (entity_start -= 1) {}
                if (entity_start < semicolon and entity_start > colon + 1 and body[entity_start - 1] == '&') continue;
                const following = trim(body[scan..]);
                if (following.len == 0) { end = semicolon; break; }
                const next_colon = std.mem.indexOfScalar(u8, following, ':') orelse continue;
                // Separator spellings are case-sensitive upstream, unlike
                // validateVariant applied to a recognized choice's first code.
                const separator_code = trim(following[0..next_colon]);
                var separator = false;
                for (profile.separator_variants) |variant| if (std.mem.eql(u8, separator_code, variant)) { separator = true; break; };
                if (separator) { end = semicolon; break; }
            }
            const value = trim(body[colon + 1 .. end]);
            if (value.len == 0 or !self.manualConversionInlineScope(value, true, true) or count == choices.len) return null;
            // No pre-conversion link, extension, entity or rule-table effect is
            // hidden by the title-only subset. Only literal choice values qualify.
            if (title_only and (std.mem.indexOfAny(u8, value, "{}[]<>&|:;\\\"'\r\n") != null or
                std.mem.indexOf(u8, value, "__") != null)) return null;
            choices[count] = .{ .code = code, .value = value };
            count += 1;
            if (end == body.len) break;
            start = end + 1;
            if (trim(body[start..]).len == 0) break;
        }
        if (count == 0) return null;
        // Lone T implies H, but never + or -. Accepted DISPLAYTITLE wins.
        // Otherwise the normal native policy selects the pinned static MAIN
        // variant: ConverterRule uses only its exact choice, never the body's
        // fallback. No MAIN choice leaves the original page title unchanged.
        if (title_only) {
            if (self.context.display_title_precedence == null) {
                const defaults = self.context.normal_title_defaults orelse return null;
                const selected = defaults.profile.static_default_variant orelse return null;
                for (choices[0..count]) |choice| if (std.ascii.eqlIgnoreCase(choice.code, selected)) {
                    // A changed title needs a separate title carrier; this
                    // subset must not silently discard that authored effect.
                    if (!std.mem.eql(u8, choice.value, self.context.title)) return null;
                };
            }
            return input[close..close];
        }
        for (choices[0..count]) |choice| if (std.ascii.eqlIgnoreCase(choice.code, profile.base)) return choice.value;
        for (profile.fallbacks) |fallback| for (choices[0..count]) |choice| {
            if (std.ascii.eqlIgnoreCase(choice.code, fallback)) return choice.value;
        };
        return null;
    }
    // Conversion runs after ordinary link parsing. Reduce only a complete
    // no-rule wrapper occupying an entire local link label for this grammar
    // check; emission still borrows the original body and parses each child.
    // This does not admit nested choices, flags, or arbitrary recursive syntax.
    fn nestedRuleFreeLinkLabels(self: *Renderer, input: []const u8, at: usize, style: Style) Error!?ManualConversion {
        // The original source-proof path still refuses unknown output. A pinned
        // converter operation below is a separate semantic evaluation, never a
        // certificate that any slice of unknown output has clean provenance.
        const parent = self.inline_missing orelse return null;
        if (parent.unknown) return null;
        return self.nestedRuleFreeLinkLabelsBody(input, at, style, false);
    }

    fn sourceKuRecursiveRuleFreeBody(self: *Renderer, input: []const u8, at: usize, style: Style) Error!?ManualConversion {
        return self.sourceKuRecursiveRuleFreeBodyDiagnosed(input, at, style, null);
    }
    fn sourceKuRecursiveRuleFreeBodyDiagnosed(self: *Renderer, input: []const u8, at: usize, style: Style, trace: ?*u64) Error!?ManualConversion {
        if (self.context.content_conversion != true) return null;
        const ns = self.context.namespace_catalog orelse return null;
        const profile = ns.manual_conversion_context orelse return null;
        const variants = ns.language_conversion orelse return null;
        // KuConverter -> LanguageConverterSpecific -> LanguageConverter at
        // 79b81 uses the inherited child-first manual evaluator. The intermediate
        // class only overrides findVariantLink. A recursively rule-free body
        // becomes raw display; this grants no choice, title or automatic rule.
        if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or
            !std.mem.eql(u8, ns.content_language, "ku") or !std.mem.eql(u8, profile.base, ns.content_language) or
            !manualVariantKnown(profile.base, variants) or
            !std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2") or
            !std.mem.eql(u8, profile.source_converter_sha256, "1f610f299bfc5b2976c440312a30958325006c36fb7b67e33810324f4c50e47e") or
            profile.siteinfo_sha256.len != 64) return null;
        for (profile.siteinfo_sha256) |byte| if (!std.ascii.isHex(byte)) return null;
        recursiveManualStage(trace, 2);
        const parent = self.inline_missing orelse return null;
        recursiveManualStage(trace, 3);
        if (parent.lost_missing_range or parent.generated_source != null) return null;
        // The common proof checks all nested frames and physical source domains.
        // Its reduced scratch text is never emitted: the result borrows the
        // original body, retaining its formatting, actions and Missing metadata.
        return self.nestedRuleFreeLinkLabelsBodyDiagnosedIn(input, at, style, true, trace, true);
    }

    fn sourceRecursiveManualContext(self: *const Renderer) bool {
        const ns = self.context.namespace_catalog orelse return false;
        const profile = ns.manual_conversion_context orelse return false;
        const variants = ns.language_conversion orelse return false;
        // These are the existing issuer's audited core/converter source IDs,
        // not a title or edition shortcut. This core recursively evaluates each
        // child rule; a complete rule-free outer body becomes raw display and
        // creates no conversion table. It does not invoke automatic conversion.
        if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or
            !std.mem.eql(u8, profile.base, ns.content_language) or !manualVariantKnown(profile.base, variants) or
            !std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2") or
            !std.mem.eql(u8, profile.source_converter_sha256, "6b8e52d8d9b415c91c6a70d34e51f18ef34a34d04551a2fd62e1318f34740558") or
            profile.siteinfo_sha256.len != 64) return false;
        for (profile.siteinfo_sha256) |byte| if (!std.ascii.isHex(byte)) return false;
        return true;
    }

    // Parser79b sanitizes ordinary HTML attributes before final conversion.
    // Sanitizer::safeEncodeAttribute armors a literal class pipe as &#124;.
    // This bounded grammar grants only that transformation in a proof buffer;
    // the emitted body and its class value remain the original borrowed bytes.
    fn sourceArmoredClassPipeTag(self: *const Renderer, tag: syntax.Tag) bool {
        if (!self.sourceRecursiveManualContext() or tag.closing or tag.self_closing) return false;
        var cursor: usize = 0;
        var seen_class = false;
        var seen_language = false;
        var saw_pipe = false;
        while (cursor < tag.attrs.len) {
            while (cursor < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[cursor])) : (cursor += 1) {}
            if (cursor == tag.attrs.len) break;
            const name_start = cursor;
            while (cursor < tag.attrs.len and std.ascii.isAlphabetic(tag.attrs[cursor])) : (cursor += 1) {}
            if (cursor == name_start) return false;
            const name = tag.attrs[name_start..cursor];
            const is_class = std.ascii.eqlIgnoreCase(name, "class");
            const is_language = std.ascii.eqlIgnoreCase(name, "lang");
            if ((!is_class and !is_language) or (is_class and seen_class) or (is_language and seen_language)) return false;
            while (cursor < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[cursor])) : (cursor += 1) {}
            if (cursor == tag.attrs.len or tag.attrs[cursor] != '=') return false;
            cursor += 1;
            while (cursor < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[cursor])) : (cursor += 1) {}
            if (cursor == tag.attrs.len or (tag.attrs[cursor] != '\'' and tag.attrs[cursor] != '"')) return false;
            const quote = tag.attrs[cursor];
            cursor += 1;
            const value_start = cursor;
            while (cursor < tag.attrs.len and tag.attrs[cursor] != quote) : (cursor += 1) {
                const byte = tag.attrs[cursor];
                if (std.ascii.isControl(byte) or std.mem.indexOfScalar(u8, "<>[]{}:;&=\"'`", byte) != null) return false;
                if (byte == '|') {
                    if (!is_class) return false;
                    saw_pipe = true;
                }
            }
            if (cursor == tag.attrs.len or cursor == value_start) return false;
            cursor += 1;
            if (cursor < tag.attrs.len and !std.ascii.isWhitespace(tag.attrs[cursor])) return false;
            seen_class = seen_class or is_class;
            seen_language = seen_language or is_language;
        }
        return seen_class and saw_pipe;
    }

    // The pinned recursive converter evaluates complete children before its
    // parent. This buffer is an admission proof only; emitted source stays the
    // original borrowed body, including all formatting and link boundaries.
    fn appendRecursiveRuleFreeProof(self: *Renderer, output: *std.ArrayList(u8), body: []const u8,
        allow_links: bool, depth: usize, frames: *usize) Error!bool
    {
        if (depth >= max_depth or body.len == 0 or body.len > 16 * 1024 or !std.unicode.utf8ValidateSlice(body)) return false;
        const output_start = output.items.len;
        var admitted = false;
        defer { if (!admitted) output.items.len = output_start; }
        var cursor: usize = 0;
        while (cursor < body.len) {
            if (starts(body[cursor..], "-{")) {
                const frame = manualConversionExtent(body, cursor) orelse return false;
                const child = frame.body(body);
                if (child.len == 0 or frame.closing + 2 <= cursor or frame.closing + 2 > body.len or
                    child.len >= frame.closing + 2 - cursor) return false;
                if (!try self.appendRecursiveRuleFreeProof(output, child, allow_links, depth + 1, frames)) return false;
                frames.* += 1;
                cursor = frame.closing + 2;
                continue;
            }
            if (body[cursor] == '<') {
                const tag = syntax.tagAt(body, cursor) orelse return false;
                const tag_bytes = body[cursor..tag.end];
                const has_pipe = std.mem.indexOfScalar(u8, tag_bytes, '|') != null;
                if (!(tag.is("b") or tag.is("i") or tag.is("strong") or tag.is("em") or
                    tag.is("span") or tag.is("sup") or tag.is("small")) or tag.self_closing or
                    !formattingAngleAttributesBalanced(tag.attrs) or
                    std.mem.indexOfAny(u8, tag_bytes, "[]{}:;&\r\n") != null or
                    (has_pipe and !self.sourceArmoredClassPipeTag(tag)) or
                    (tag.closing and trim(tag.attrs).len != 0)) return false;
                for (tag_bytes) |byte| if (std.ascii.isControl(byte) and byte != '\t') return false;
                if (has_pipe) {
                    for (tag_bytes) |byte| {
                        if (byte == '|') try output.appendSlice(self.a, "&#124;") else try output.append(self.a, byte);
                    }
                } else try output.appendSlice(self.a, tag_bytes);
                cursor = tag.end;
                continue;
            }
            if (body[cursor] == '[') {
                if (!allow_links or !starts(body[cursor..], "[[")) return false;
                var links: ir.InlineIterator = .{ .input = body, .cursor = cursor,
                    .renderer_boundaries = true, .link_trail = self.context.link_trail };
                const node = links.next() orelse return false;
                if (node.kind != .link or links.cursor <= cursor or node.link_empty_label or node.link_label_restored_close or
                    !manualConversionInternalTarget(node.target)) return false;
                const target = if (starts(node.target, ":")) node.target[1..] else node.target;
                const page = target[0 .. (std.mem.indexOfScalar(u8, target, '#') orelse target.len)];
                if (page.len == 0 or std.mem.indexOfScalar(u8, page, ':') != null) return false;
                const base = @intFromPtr(body.ptr); const label_pointer = @intFromPtr(node.text.ptr);
                if (label_pointer < base or label_pointer - base < cursor or label_pointer - base > links.cursor or
                    node.text.len > links.cursor - (label_pointer - base)) return false;
                const label_at = label_pointer - base;
                if (std.mem.indexOf(u8, node.text, "-{") != null) {
                    const label_frame = manualConversionExtent(node.text, 0) orelse return false;
                    if (!node.link_has_pipe or label_frame.closing + 2 != node.text.len) return false;
                    if (std.mem.indexOf(u8, label_frame.body(node.text), "-{") != null and
                        repeatedPlainManualLabelBody(node.text) == null) return false;
                }
                if (!node.link_has_pipe) {
                    if (!self.manualConversionLinkedScope(body[cursor..links.cursor], true)) return false;
                    try output.appendSlice(self.a, body[cursor..links.cursor]);
                } else {
                    try output.appendSlice(self.a, body[cursor..label_at]);
                    if (!try self.appendRecursiveRuleFreeProof(output, node.text, false, depth + 1, frames)) return false;
                    try output.appendSlice(self.a, body[label_at + node.text.len..links.cursor]);
                }
                cursor = links.cursor;
                continue;
            }
            const byte = body[cursor];
            if (std.mem.indexOfScalar(u8, ":;|{}&]", byte) != null or (std.ascii.isControl(byte) and byte != '\t') or
                starts(body[cursor..], "=>") or starts(body[cursor..], "''")) return false;
            try output.append(self.a, byte);
            cursor += 1;
        }
        // Each child must close its own HTML/link scope; a parent may not use
        // removal to repair a child's unfinished tag or manufacture a link.
        if (!self.manualConversionLinkedScope(output.items[output_start..], allow_links)) return false;
        admitted = true;
        return true;
    }

    fn recursiveRuleFreeFrameBody(self: *Renderer, input: []const u8, at: usize, parent: MissingText, trace: ?*u64) Error!?ManualConversion {
        recursiveManualStage(trace, 13);
        const frame = manualConversionExtent(input, at) orelse return null;
        const body = frame.body(input);
        const input_base = @intFromPtr(input.ptr); const parent_base = @intFromPtr(parent.bytes.ptr);
        recursiveManualStage(trace, 14);
        if (input_base < parent_base or input_base - parent_base > parent.bytes.len or
            input.len > parent.bytes.len - (input_base - parent_base) or
            !recursivePositionInterval(parent, input_base - parent_base + at, input_base - parent_base + frame.closing + 2)) return null;
        var domain = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        while (domain) |current| {
            recursiveManualStage(trace, 15);
            if (remaining == 0) return null;
            remaining -= 1;
            const tracked = current.tracked orelse return null;
            const base = @intFromPtr(current.source.ptr);
            if (tracked.bytes.ptr != current.source.ptr or tracked.bytes.len != current.source.len or input_base < base or
                input_base - base > current.source.len or input.len > current.source.len - (input_base - base) or
                !recursivePositionInterval(tracked, input_base - base + at, input_base - base + frame.closing + 2)) return null;
            domain = current.parent;
        }
        var reduced: std.ArrayList(u8) = .empty;
        defer reduced.deinit(self.a);
        var children: usize = 0;
        recursiveManualStage(trace, 16);
        if (!try self.appendRecursiveRuleFreeProof(&reduced, body, true, 0, &children) or children == 0) return null;
        recursiveManualStage(trace, 17);
        return .{ .body = body, .end = frame.closing + 2 };
    }

    // A complete explicit label may contain repeated whole no-rule frames.
    // Every frame is parsed, bounded and strictly smaller; only the final
    // plain borrowed text is eligible, never flags, choices or nested actions.
    fn repeatedPlainManualLabelBody(label: []const u8) ?[]const u8 {
        var body = label;
        var frames: usize = 0;
        while (starts(body, "-{")) {
            if (frames >= max_depth) return null;
            const frame = manualConversionExtent(body, 0) orelse return null;
            const child = frame.body(body);
            if (frame.closing + 2 != body.len or child.len == 0 or child.len >= body.len) return null;
            frames += 1;
            body = child;
        }
        if (frames < 2 or !std.unicode.utf8ValidateSlice(body) or
            std.mem.indexOfAny(u8, body, ":;|{}[]<>&\r\n") != null or
            std.mem.indexOf(u8, body, "=>") != null or std.mem.indexOf(u8, body, "''") != null) return null;
        for (body) |byte| if (std.ascii.isControl(byte)) return null;
        return body;
    }

    // Diagnostic output is local to this one attempted evaluator. It records
    // existing guard progress only and is published only on final rejection.
    fn recursiveManualStage(trace: ?*u64, stage: u8) void {
        if (trace) |bits| bits.* = (bits.* & ~@as(u64, 255)) | stage;
    }
    fn sourceRecursiveRuleFreeLinkLabels(self: *Renderer, input: []const u8, at: usize, style: Style) Error!?ManualConversion {
        return self.sourceRecursiveRuleFreeLinkLabelsDiagnosed(input, at, style, null);
    }
    fn sourceRecursiveRuleFreeLinkLabelsDiagnosed(self: *Renderer, input: []const u8, at: usize, style: Style, trace: ?*u64) Error!?ManualConversion {
        recursiveManualStage(trace, 1); // pinned context
        if (!self.sourceRecursiveManualContext()) return null;
        recursiveManualStage(trace, 2); // Missing owner present
