            if (byte != ';') continue;
            // Match ConverterRule's entity shielding, not arbitrary ampersands.
            var begin = index;
            while (begin > 0 and (std.ascii.isAlphanumeric(body[begin - 1]) or body[begin - 1] == '#')) : (begin -= 1) {}
