    fn manualRuleBodyPositionAfterNumericNote(input: []const u8, at: usize) bool {
        if (formattingAngleBodyPosition(input, at)) return true;
        if (at > input.len or at > 4096) return false;
        const prefix = std.mem.trimEnd(u8, input[0..at], " \t");
        if (prefix.len == at or prefix.len < 3 or prefix[prefix.len - 1] != ']') return false;
        const end = prefix.len - 1;
        var begin = end;
        while (begin != 0 and std.ascii.isDigit(prefix[begin - 1])) begin -= 1;
        if (begin == end or begin == 0 or end - begin > 20 or prefix[begin - 1] != '[') return false;
        return formattingAngleBodyPosition(input, begin - 1);
    }

    // Both targets are invalid before conversion: raw braces are not legal
    // title characters. Core therefore retains their complete link spelling.
    // Its first surviving pipe is consumed by parseFlags even when the prefix
    // names no flag; the rule-free suffix is then displayed under R. This is
    // not an action or a general permission for unresolved parameter bodies.
    fn invalidParameterLinkRuleSuffix(self: *Renderer, input: []const u8, at: usize, close: usize, style: Style) ?[]const u8 {
        if (at > close or close - at < 2 or close - at > 4096 or close > input.len or
            input.len - close < 2 or !starts(input[at..], "-{")) return null;
        const ns = self.context.namespace_catalog orelse return null;
        const profile = ns.manual_conversion_context orelse return null;
        const variants = ns.language_conversion orelse return null;
        if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or
            !std.mem.eql(u8, profile.base, ns.content_language) or !manualVariantKnown(profile.base, variants) or
            !std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2") or
            profile.source_converter_sha256.len != 64 or profile.siteinfo_sha256.len != 64) return null;
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or
            self.in_reference or self.pre_block or self.parsed_pre or self.in_template_literal_scope or
            self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            self.navigation_target_probe != null or self.inline_image_attribute) return null;
        if (!manualRuleBodyPositionAfterNumericNote(input, at)) return null;
        var domain = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        while (domain) |current| {
            if (remaining == 0) return null;
            remaining -= 1;
            const base = @intFromPtr(current.source.ptr);
            const pointer = @intFromPtr(input.ptr);
            if (pointer < base) return null;
            const relative = pointer - base;
            if (relative > current.source.len or input.len > current.source.len - relative or
                !manualRuleBodyPositionAfterNumericNote(current.source, relative + at)) return null;
            domain = current.parent;
        }
        const parent = self.inline_missing orelse return null;
        if (parent.lost_missing_range) return null;
        const base = @intFromPtr(parent.bytes.ptr);
        const pointer = @intFromPtr(input.ptr);
        if (pointer < base or pointer - base > parent.bytes.len or input.len > parent.bytes.len - (pointer - base)) return null;
        const first = pointer - base + at;
        if (!manualRuleBodyPositionAfterNumericNote(parent.bytes, first)) return null;
        const last = pointer - base + close + 2;
        for (parent.ranges) |range| if (range.start < last and range.end > first) return null;
        for (parent.literal_curly_ranges) |range| if (range.start < last and range.end > first) return null;
        for (parent.generated_links) |range| if (range.start < last and range.end > first) return null;
        // An unrelated unknown dependency remains unknown. This certificate
        // neither creates an action nor changes metadata; it returns a borrowed
        // suffix whose later ordinary compilation retains the original domain.
        const body = input[at + 2 .. close];
        var cursor: usize = 0;
        while (cursor < body.len and body[cursor] == ' ') : (cursor += 1) {}
        if (!starts(body[cursor..], "[[{{{")) return null;
        const name_start = cursor + 5;
        const name_end = std.mem.indexOfPos(u8, body, name_start, "}}}]]") orelse return null;
        const name = body[name_start..name_end];
        if (!literalBareParameterName(name)) return null;
        cursor = name_end + 5;
        const gap = cursor;
        while (cursor < body.len and body[cursor] == ' ') : (cursor += 1) {}
        if (cursor == gap or !starts(body[cursor..], "[[:")) return null;
        const code_start = cursor + 3;
        const code_end = std.mem.indexOfScalarPos(u8, body, code_start, ':') orelse return null;
        const code = body[code_start..code_end];
        if (code.len == 0 or code.len > 16) return null;
        for (code) |byte| if (!std.ascii.isAlphabetic(byte) and byte != '-') return null;
        cursor = code_end + 1;
        if (!starts(body[cursor..], "{{{")) return null;
        cursor += 3;
        if (body.len - cursor < name.len or !std.mem.eql(u8, body[cursor .. cursor + name.len], name)) return null;
        cursor += name.len;
        if (!starts(body[cursor..], "}}}|")) return null;
        cursor += 4;
        const suffix_start = cursor;
        if (!starts(body[cursor..], "\xe2\x98\x9e<sup>")) return null;
        cursor += "\xe2\x98\x9e<sup>".len;
        if (body.len - cursor < code.len or !std.mem.eql(u8, body[cursor .. cursor + code.len], code)) return null;
        cursor += code.len;
        if (!starts(body[cursor..], "</sup>]]")) return null;
        cursor += "</sup>]]".len;
        while (cursor < body.len and body[cursor] == ' ') : (cursor += 1) {}
        if (cursor != body.len) return null;
        // Exactly one pipe survives, no flags or choices can match its prefix,
        // and the suffix has only a complete attribute-free SUP and literal ]].
        return body[suffix_start..];
    }

    // Exact duplicated nested targets leave incomplete outer chunks before
    // the ordinary link pass. The first literal pipe belongs to the second
    // inner link's trail, so conversion consumes that prefix as invalid flags.
    // This proof returns only the borrowed ordinary suffix, never a new link.
    // LinkHolderArray::makeHolder appends the split trail outside its token;
    // replacement changes that token alone before ConverterRule::parseFlags.
    fn nestedTargetLinkRuleSuffix(self: *Renderer, input: []const u8, at: usize, close: usize, style: Style) ?[]const u8 {
        if (at > close or close - at < 2 or close - at > 4096 or close > input.len or
            input.len - close < 2 or !starts(input[at..], "-{") or !starts(input[close..], "}-")) return null;
        const ns = self.context.namespace_catalog orelse return null;
        const profile = ns.manual_conversion_context orelse return null;
        const variants = ns.language_conversion orelse return null;
        if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or
            !std.mem.eql(u8, profile.base, ns.content_language) or !manualVariantKnown(profile.base, variants) or
            !std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2") or
            profile.source_converter_sha256.len != 64 or profile.siteinfo_sha256.len != 64) return null;
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or
            self.in_reference or self.pre_block or self.parsed_pre or self.in_template_literal_scope or
            self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            self.navigation_target_probe != null or self.inline_image_attribute) return null;
        if (!manualRuleBodyPositionAfterNumericNote(input, at)) return null;
        var domain = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        while (domain) |current| {
            if (remaining == 0) return null;
            remaining -= 1;
            const base = @intFromPtr(current.source.ptr);
            const pointer = @intFromPtr(input.ptr);
            if (pointer < base) return null;
            const relative = pointer - base;
            if (relative > current.source.len or input.len > current.source.len - relative or
                !manualRuleBodyPositionAfterNumericNote(current.source, relative + at)) return null;
            domain = current.parent;
        }
        const parent = self.inline_missing orelse return null;
        if (parent.unknown or parent.lost_missing_range) return null;
        const base = @intFromPtr(parent.bytes.ptr);
        const pointer = @intFromPtr(input.ptr);
        if (pointer < base or pointer - base > parent.bytes.len or input.len > parent.bytes.len - (pointer - base)) return null;
        const first = pointer - base + at;
        if (!manualRuleBodyPositionAfterNumericNote(parent.bytes, first)) return null;
        const last = pointer - base + close + 2;
        for (parent.ranges) |range| if (range.start < last and range.end > first) return null;
        for (parent.literal_curly_ranges) |range| if (range.start < last and range.end > first) return null;
        for (parent.generated_links) |range| if (range.start < last and range.end > first) return null;
        const body = input[at + 2 .. close];
        var cursor: usize = 0;
        while (cursor < body.len and body[cursor] == ' ') : (cursor += 1) {}
        if (!starts(body[cursor..], "[[[[")) return null;
        const title_start = cursor + 4;
        const title_end = std.mem.indexOfPos(u8, body, title_start, "]]]]") orelse return null;
        const title = body[title_start..title_end];
        if (title.len == 0 or title.len > 255 or !std.mem.eql(u8, title, trim(title)) or
            title[0] == '.' or title[0] == '/' or !safeInternalTarget(title) or
            !manualConversionInternalTarget(title) or
            std.mem.indexOfAny(u8, title, ":/&%#;[]{}|<>\"'\r\n\t") != null) return null;
        cursor = title_end + 4;
        const gap = cursor;
        while (cursor < body.len and body[cursor] == ' ') : (cursor += 1) {}
        if (cursor == gap or !starts(body[cursor..], "[[:")) return null;
        const code_start = cursor + 3;
        const code_end = std.mem.indexOfScalarPos(u8, body, code_start, ':') orelse return null;
        const code = body[code_start..code_end];
        if (code.len == 0 or code.len > 16) return null;
        for (code) |byte| if (!std.ascii.isAlphabetic(byte) and byte != '-') return null;
        if (self.namespaceOfTarget(body[code_start .. code_end + 1]) != null) return null;
        var remote = false;
        for (ns.interwiki_rows) |row| if (std.ascii.eqlIgnoreCase(row.prefix, code)) {
            remote = !row.is_current_wiki;
            break;
        };
        if (!remote) return null;
        cursor = code_end + 1;
        const second_link_start = cursor;
        if (!starts(body[cursor..], "[[")) return null;
        cursor += 2;
        if (body.len - cursor < title.len or !std.mem.eql(u8, body[cursor .. cursor + title.len], title)) return null;
        cursor += title.len;
        if (!starts(body[cursor..], "]]|")) return null;
        cursor += 3;
        const suffix_start = cursor;
        if (!starts(body[cursor..], "\xe2\x98\x9e<sup>")) return null;
        cursor += "\xe2\x98\x9e<sup>".len;
        if (body.len - cursor < code.len or !std.mem.eql(u8, body[cursor .. cursor + code.len], code)) return null;
        cursor += code.len;
        if (!starts(body[cursor..], "</sup>]]")) return null;
        cursor += "</sup>]]".len;
        while (cursor < body.len and body[cursor] == ' ') : (cursor += 1) {}
        if (cursor != body.len) return null;
        // Use the ordinary source parser and selected trail callbacks. Both
        // inner links must end before the unmatched brackets or literal pipe.
        // A different trail policy must not move that pipe into a holder.
        for ([_]usize{ title_start - 2, second_link_start }) |link_start| {
            var iterator: ir.InlineIterator = .{ .input = body, .cursor = link_start,
                .renderer_boundaries = true, .link_trail = self.context.link_trail };
            const ordinary = iterator.next() orelse return null;
            if (ordinary.kind != .link or ordinary.link_has_pipe or ordinary.trail.len != 0 or
                !std.mem.eql(u8, ordinary.target, title) or !std.mem.eql(u8, ordinary.text, title) or
                iterator.cursor != link_start + title.len + 4) return null;
        }
        return body[suffix_start..];
    }

    // Core consumes unescaped category metadata before ConverterRule sees its
    // text. Prove a complete no-rule body, then let the ordinary link parser
    // consume the original borrowed metadata; no category becomes an action or
    // a visible anchor prefix for interpreting a later colon.
    fn manualCategoryMetadataBody(self: *Renderer, input: []const u8, at: usize, close: usize, style: Style) ?[]const u8 {
        if (self.context.content_conversion != true or at > close or close - at < 2 or
            close - at > 4096 or close > input.len or input.len - close < 2 or
            !starts(input[at..], "-{") or !starts(input[close..], "}-")) return null;
        const ns = self.context.namespace_catalog orelse return null;
        const profile = ns.manual_conversion_context orelse return null;
        const variants = ns.language_conversion orelse return null;
        if (!std.mem.eql(u8, profile.policy, "bundle-base-content-v1") or
            !std.mem.eql(u8, profile.base, ns.content_language) or !manualVariantKnown(profile.base, variants) or
            !std.mem.eql(u8, profile.source_core, "79b81ba96674efc8a803fc956bc501d347d440d2") or
            profile.source_converter_sha256.len != 64 or profile.siteinfo_sha256.len != 64) return null;
        for (profile.source_converter_sha256) |byte| if (!std.ascii.isHex(byte)) return null;
        for (profile.siteinfo_sha256) |byte| if (!std.ascii.isHex(byte)) return null;
        if (style.provenance != .parsed or style.kind != .text or style.target.len != 0 or
            style.self_link_target != null or style.image != null or style.missing_nonaction or
            style.code or style.preserve_whitespace or self.block_formatting.code or self.in_reference or
            self.pre_block or self.parsed_pre or self.in_template_literal_scope or self.body_link_target.len != 0 or
            self.explicit_wiki_label != null or self.navigation_target_probe != null or self.inline_image_attribute) return null;
        const parent = self.inline_missing orelse return null;
        if (parent.unknown or parent.lost_missing_range or parent.generated_source != null or
            !formattingAngleBodyPosition(input, at)) return null;
        const pointer = @intFromPtr(input.ptr);
        const parent_base = @intFromPtr(parent.bytes.ptr);
        if (pointer < parent_base) return null;
        const offset = pointer - parent_base;
        if (offset > parent.bytes.len or input.len > parent.bytes.len - offset or
            !ordinaryNormalizationRange(parent, offset + at, offset + close + 2) or
            !formattingAngleBodyPosition(parent.bytes, offset + at)) return null;
        var domain = self.inline_source_domain;
        var remaining: usize = max_depth + 1;
        while (domain) |current| {
            if (remaining == 0) return null;
            remaining -= 1;
            const base = @intFromPtr(current.source.ptr);
            if (pointer < base) return null;
            const relative = pointer - base;
            const tracked = current.tracked orelse return null;
            if (tracked.bytes.ptr != current.source.ptr or tracked.bytes.len != current.source.len or
                tracked.lost_missing_range or tracked.generated_source != null or relative > current.source.len or
                input.len > current.source.len - relative or
                !ordinaryNormalizationRange(tracked, relative + at, relative + close + 2) or
                !formattingAngleBodyPosition(current.source, relative + at)) return null;
            domain = current.parent;
        }
        const body = input[at + 2 .. close];
        if (!std.unicode.utf8ValidateSlice(body)) return null;
        var cursor: usize = 0;
        var categories: usize = 0;
        var visible = false;
        while (cursor < body.len) {
            if (body[cursor] == '[') {
                if (!starts(body[cursor..], "[[")) return null;
                var links: ir.InlineIterator = .{ .input = body, .cursor = cursor,
                    .renderer_boundaries = true, .link_trail = self.context.link_trail };
                const node = links.next() orelse return null;
                if (node.kind != .link or links.cursor <= cursor or node.link_has_pipe or
                    node.link_empty_label or node.link_label_restored_close or node.trail.len != 0 or
                    node.target.len == 0 or starts(node.target, ":") or
                    !std.mem.eql(u8, node.target, trim(node.target)) or
                    !std.mem.eql(u8, node.text, node.target) or !safeInternalTarget(node.target) or
                    !manualConversionInternalTarget(node.target) or self.namespaceOfTarget(node.target) != 14 or
                    std.mem.indexOfAny(u8, node.target, "[]{}|<>&%#\"'\r\n\t") != null or
                    !std.mem.endsWith(u8, body[cursor..links.cursor], "]]")) return null;
                const colon = std.mem.indexOfScalar(u8, node.target, ':') orelse return null;
                const name = node.target[colon + 1 ..];
                if (trim(name).len == 0 or std.mem.indexOfAny(u8, name, ":;") != null) return null;
                for (body[cursor..links.cursor]) |byte| if (std.ascii.isControl(byte)) return null;
                categories += 1;
                cursor = links.cursor;
                continue;
            }
            const byte = body[cursor];
            if (std.ascii.isControl(byte) or std.mem.indexOfScalar(u8, "]{}<>|:;&\"'", byte) != null or
                starts(body[cursor..], "=>")) return null;
            if (byte != ' ') visible = true;
            cursor += 1;
        }
        if (categories == 0 or !visible) return null;
        return body;
    }

    fn manualMultilineLocalLinkLine(self: *Renderer, line: []const u8) bool {
        if (!starts(line, "[[") or !self.manualConversionLinkedScope(line, true)) return false;
        var links: ir.InlineIterator = .{ .input = line, .renderer_boundaries = true, .link_trail = self.context.link_trail };
        const token = links.next() orelse return false;
        if (token.kind != .link or links.cursor != line.len or token.trail.len != 0 or token.link_empty_label or
            token.link_label_restored_close or token.target.len == 0 or token.text.len == 0) return false;
        if (self.namespaceOfTarget(token.target)) |namespace| return namespace != 6 and namespace != 14;
        return std.mem.indexOfScalar(u8, token.target, ':') == null;
    }
    fn manualMultilineInlineLine(self: *Renderer, line: []const u8, style: Style) bool {
        if (line.len == 0 or std.mem.indexOfAny(u8, line, "\r\n{}&;") != null or std.mem.indexOf(u8, line, "''") != null) return false;
        for (line) |byte| if (std.ascii.isControl(byte)) return false;
        if (self.manualMultilineLocalLinkLine(line)) return true;
        const opening = syntax.tagAt(line, 0) orelse return false;
        if (opening.closing or opening.self_closing or !formattingAngleAttributesBalanced(opening.attrs)) return false;
        const pair = syntax.matchingTag(line, opening) orelse return false;
        if (pair.end != line.len) return false;
        return self.manualConversionLinkedScope(line, true) or self.manualConversionHtmlScope(line, style);
    }
    fn manualMultilineLinkBody(self: *Renderer, body: []const u8, style: Style) bool {
        if (body.len < 4 or body.len > 16 * 1024 or body[0] != '\n' or body[body.len - 1] != '\n' or
            !std.unicode.utf8ValidateSlice(body) or std.mem.indexOfAny(u8, body, "\r{}&;") != null or
            std.mem.indexOf(u8, body, "=>") != null or std.mem.indexOf(u8, body, "''") != null or
            !manualRuleHasNoMutationFlags(body)) return false;
        for (body) |byte| if (std.ascii.isControl(byte) and byte != '\n') return false;
        var lines = std.mem.splitScalar(u8, body[1 .. body.len - 1], '\n');
        var count: usize = 0;
        while (lines.next()) |line| {
            if ((count == 0 and !self.manualMultilineLocalLinkLine(line)) or !self.manualMultilineInlineLine(line, style)) return false;
            count += 1;
        }
        return count != 0;
    }
    fn manualMultilineLinkPosition(self: *Renderer, input: []const u8, at: usize, style: Style) bool {
        if (at > input.len or at > 16 * 1024 or (at != 0 and input[at - 1] != '\n') or
            !std.unicode.utf8ValidateSlice(input[0..at])) return false;
        var cursor: usize = 0;
        while (cursor < at) {
            if (starts(input[cursor..at], "-{\n")) {
                const close = std.mem.indexOfPos(u8, input, cursor + 3, "}-") orelse return false;
                if (close + 2 >= at or input[close + 2] != '\n' or
                    !self.manualMultilineLinkBody(input[cursor + 2 .. close], style)) return false;
                cursor = close + 3;
                continue;
            }
            const end = std.mem.indexOfScalarPos(u8, input, cursor, '\n') orelse return false;
            if (end >= at or !self.manualMultilineInlineLine(input[cursor..end], style)) return false;
            cursor = end + 1;
        }
        return cursor == at;
    }
    fn manualMultilineLinkedScope(self: *Renderer, input: []const u8, at: usize, close: usize, style: Style) bool {
        if (!self.sourceRecursiveManualContext() or self.context.content_conversion != true or
            style.provenance != .parsed or style.kind != .text or style.target.len != 0 or style.self_link_target != null or
            style.image != null or style.missing_nonaction or style.code or style.preserve_whitespace or
            self.block_formatting.code or self.in_reference or self.pre_block or self.parsed_pre or
            self.in_template_literal_scope or self.body_link_target.len != 0 or self.explicit_wiki_label != null or
            self.navigation_target_probe != null or self.inline_image_attribute or
            at > close or close - at < 2 or close > input.len or input.len - close < 2 or !starts(input[at..], "-{") or
            !starts(input[close..], "}-") or (close + 2 != input.len and input[close + 2] != '\n') or
            !self.manualMultilineLinkBody(input[at + 2 .. close], style)) return false;
        const tracked = self.inline_missing orelse return false;
        if (!wikiClassCleanText(tracked) or !wikiClassContains(tracked.bytes, input)) return false;
        var domain = self.inline_source_domain orelse return false;
        var remaining: usize = max_depth + 1;
        while (true) {
            if (remaining == 0 or !wikiClassContains(domain.source, input)) return false;
            remaining -= 1;
            const held = domain.tracked orelse return false;
            if (!wikiClassCleanText(held) or held.bytes.ptr != domain.source.ptr or held.bytes.len != domain.source.len) return false;
            const offset = @intFromPtr(input.ptr) - @intFromPtr(domain.source.ptr);
            if (!self.manualMultilineLinkPosition(domain.source, offset + at, style)) return false;
            domain = domain.parent orelse break;
        }
        // Parser79b resolves paragraphs and link holders before conversion.
        // Keep the original LF bytes inside that already-created paragraph;
        // never run block parsing again or manufacture adjacent source tokens.
        return true;
    }

    // A proved own-line conversion does not introduce another paragraph or
    // another separator. Keep its borrowed body intact, and fold only a boundary
    // LF already represented by the adjacent LF in this same inline input.
    // Exact ordinary paragraph edges use the existing block-owned source copy;
    // normalized/foreign fragments cannot manufacture that edge authority.
    fn manualConversionDisplayBody(self: *const Renderer, input: []const u8, at: usize, rule: ManualConversion) []const u8 {
        if (!rule.multiline_boundary_lfs or rule.body.len < 4 or at > input.len or input.len - at < 4 or
            rule.end > input.len or rule.end < at + 4 or rule.body.len != rule.end - at - 4 or
            rule.body.ptr != input[at + 2 ..].ptr or !starts(input[at..], "-{") or
            !std.mem.eql(u8, input[rule.end - 2 .. rule.end], "}-") or
            rule.body[0] != '\n' or rule.body[rule.body.len - 1] != '\n') return rule.body;
        const tracked = self.inline_missing orelse return rule.body;
        const frame = self.inline_source_domain orelse return rule.body;
        const held = frame.tracked orelse return rule.body;
        if (tracked.bytes.ptr != input.ptr or tracked.bytes.len != input.len or !wikiClassCleanText(tracked) or
            frame.source.ptr != input.ptr or frame.source.len != input.len or
            held.bytes.ptr != input.ptr or held.bytes.len != input.len or !wikiClassCleanText(held)) return rule.body;
        const paragraph_edge = frame.parent == null and
            (if (self.semantic_capture) |capture| capture.ordinary_paragraph else false) and
            (if (self.plain_body_source_copy) |copy| copy.copied.ptr == input.ptr and copy.copied.len == input.len else false);
        const begin: usize = if ((at != 0 and input[at - 1] == '\n') or (at == 0 and paragraph_edge)) 1 else 0;
        const end = rule.body.len - @as(usize, if ((rule.end < input.len and input[rule.end] == '\n') or
            (rule.end == input.len and paragraph_edge)) 1 else 0);
        return rule.body[begin..end];
    }

    fn manualConversion(self: *Renderer, input: []const u8, at: usize, style: Style) Error!ManualConversion {
        const variants = (self.context.namespace_catalog orelse return self.manualConversionRejected(input, at, "namespace_catalog", error.UncompiledPresentation)).language_conversion orelse return self.manualConversionRejected(input, at, "language_variants", error.UncompiledPresentation);
