    fn formattingVisibleEndsSpace(spans: []const Span) bool {
        var at = spans.len;
        while (at != 0) {
            at -= 1;
            if (spans[at].image != null) return false;
            if (spans[at].kind == .line_break) return true;
            const visible_text = spans[at].text;
            if (visible_text.len != 0) return std.ascii.isWhitespace(visible_text[visible_text.len - 1]);
        }
        return false;
    }

    pub fn isPureColorSwatchPrefix(self: *Renderer, source: []const u8) Error!bool {
        var cursor: usize = 0;
        var table_source: ?[]const u8 = null;
        while (cursor < source.len) {
            if (std.ascii.isWhitespace(source[cursor])) {
                cursor += 1;
                continue;
            }
            if (starts(source[cursor..], "<!--")) {
                const end = std.mem.indexOfPos(u8, source, cursor + 4, "-->") orelse return false;
                cursor = end + 3;
                continue;
            }
            const control = if (self.context.behavior_switches) |registry| try registry.matchAt(self.a, source, cursor) else syntax.behaviorSwitchEnd(source, cursor);
            if (control) |end| {
                cursor = end;
                continue;
            }
            if (table_source != null) return false;
            const begin = cursor;
            if (starts(source[cursor..], "{|")) {
                if (cursor != 0 and source[cursor - 1] != '\n') return false;
                var at = syntax.logicalEnd(source, cursor);
                var close: ?usize = null;
                while (at < source.len) {
                    at += 1;
                    const end = syntax.logicalEnd(source, at);
                    if (starts(trim(source[at..end]), "|}")) {
                        const line = trim(source[at..end]);
                        close = @intFromPtr(line.ptr) - @intFromPtr(source.ptr) + 2;
                        break;
                    }
                    at = end;
                }
                cursor = close orelse return false;
            } else {
                const tag = try self.semanticTagAt(source, cursor) orelse return false;
                if (!tag.is("table") or tag.closing or tag.self_closing) return false;
                const pair = syntax.matchingTag(source, tag) orelse return false;
                cursor = pair.end;
            }
            table_source = source[begin..cursor];
        }
        const table = table_source orelse return false;
        const blocks = probe: {
            // This optional classification cannot reject the ordinary body or
            // consume its first rejection evidence. An unproved table remains
            // ordinary source; operational failures still propagate.
            const previous_probe_scope = self.rejection_probe_scope;
            self.rejection_probe_scope = true;
            defer self.rejection_probe_scope = previous_probe_scope;
            const suspended = RejectedCompilerCapture.suspendCapture();
            defer suspended.deinit();
            break :probe self.renderBody(table) catch |err| switch (err) {
                error.UncompiledPresentation => return false,
                else => return err,
            };
        };
        if (self.fallbacks.any() or self.truncated or self.refs.items.len != 0 or self.media.items.len != 0 or blocks.len != 1 or blocks[0].kind != .table) return false;
        const feature = blocks[0].feature orelse return false;
        return std.mem.eql(u8, feature.kind, "color_swatch");
    }

    pub fn renderBody(self: *Renderer, source: []const u8) Error![]const Block {
        return self.renderBodyWithMissing(MissingText.untracked(source));
    }
    pub fn renderBodyWithMissing(self: *Renderer, tracked: MissingText) Error![]const Block {
        const previous_literal_root = self.literal_url_root;
        if (previous_literal_root == null) self.literal_url_root = tracked.bytes;
        defer self.literal_url_root = previous_literal_root;
        return self.renderBodyWithMissingAndInlineStart(tracked, false);
    }
    fn renderBodyWithMissingAndInlineStart(self: *Renderer, tracked: MissingText, initial_inline: bool) Error![]const Block {
        const previous_body_links = self.context.body_link_continuations;
        defer self.context.body_link_continuations = previous_body_links;
        const motion_root: NativeInlineMotionRoot = .{ .source = tracked };
        const motion_scope = self.nativeInlineMotionBegin(&motion_root, false);
        defer motion_scope.deinit();
        const previous_citations = self.context.citations;
        defer self.context.citations = previous_citations;
        const numbered_missing = try self.prepareNumberedWithMissing(tracked, .{});
        const input = numbered_missing.bytes;
        const numbering_before = self.context.external_links_prepared;
        self.context.external_links_prepared = true;
        defer self.context.external_links_prepared = numbering_before;
