        } else {
            const previous = blocks.items[index].spans;
            const spans = try self.a.alloc(Span, previous.len + @intFromBool(separator) + extra.len);
            @memcpy(spans[0..previous.len], previous);
            var next = previous.len;
            if (separator) {
                spans[next] = self.formattingSeparator();
                next += 1;
            }
            @memcpy(spans[next..], extra);
            blocks.items[index].spans = spans;
        }
        blocks.items[index].text = "";
        validateInlineBoxRunStructure(blocks.items[index].spans) catch |failure| {
            self.tracePresentationRejection("static_inline_box", "joined_paragraph_domain", "", 0, 0, failure);
            return failure;
        };
    }

    fn joinBodyParagraphs(self: *Renderer, blocks: *std.ArrayList(Block), first: usize, separator: bool) Error!void {
        if (first == 0 or first >= blocks.items.len or blocks.items[first - 1].kind != .paragraph or blocks.items[first].kind != .paragraph) return;
        const leading = blocks.items[first];
        try self.appendParagraphSpans(blocks, first - 1, leading.spans, separator);
        blocks.items[first - 1].relation_note = blocks.items[first - 1].relation_note or leading.relation_note;
        _ = blocks.orderedRemove(first);
    }

    fn rawBodyQuoteSeed(self: *Renderer, source: []const u8, raw: []const u8, quotes: *?QuoteBoundaryScan) Error!?QuoteSeed {
        if (quotes.* == null) return null;
        const base = @intFromPtr(source.ptr);
        const at = @intFromPtr(raw.ptr);
        if (at < base or at - base > source.len or raw.len > source.len - (at - base)) return null;
        return try quotes.*.?.at(self.a, at - base, self.context.behavior_switches);
    }
    const InterruptedBodyPrefix = struct {
        source: MissingText,
        opening: usize,
        aliases_before: usize,

        fn forward(self: @This(), position: usize) usize {
            return position + @as(usize, if (position >= self.opening) 8 else 0) +
                @as(usize, if (position >= self.opening + 2) 9 else 0);
        }
        fn forwardSeed(self: @This(), seed: QuoteSeed) QuoteSeed {
            var result = seed;
            result.line_end = self.forward(seed.line_end);
            if (seed.opaque_cut) |value| result.opaque_cut = self.forward(value);
            if (seed.correction) |position| result.correction = self.forward(position);
            if (seed.boundaries.link_close) |position| result.boundaries.link_close = self.forward(position);
            if (seed.boundaries.template_close) |position| result.boundaries.template_close = self.forward(position);
            return result;
        }
        fn discard(self: @This(), renderer: *Renderer) void {
            // On failure no retained alias may borrow the released preparation.
            renderer.heading_source_aliases.shrinkRetainingCapacity(self.aliases_before);
            renderer.a.free(self.source.bytes);
            renderer.a.free(self.source.ranges);
            renderer.a.free(self.source.literal_curly_ranges);
        }
    };
    fn prepareInterruptedBodyPrefix(self: *Renderer, source: []const u8, raw: []const u8, opening: usize) Error!InterruptedBodyPrefix {
        if (!self.interruptedBodyTargetDomain()) return error.InvalidPreContext;
        const base = @intFromPtr(source.ptr);
        const raw_address = @intFromPtr(raw.ptr);
        if (raw_address < base or raw_address - base > source.len or raw.len > source.len - (raw_address - base))
            return error.InvalidPreContext;
        const parsed = trim(raw);
        const begin = @intFromPtr(parsed.ptr) - base;
        const end = begin + parsed.len;
        if (opening < begin or opening > end or end - opening < 2 or
            !(htmlInterruptedInternalOpening(source, opening) or labeledListLinkOpening(source, opening)))
            return error.InvalidPreContext;
        var tracked = MissingText.untracked(source);
        var tracked_offset: usize = 0;
        if (self.body_missing) |parent| {
            const parent_base = @intFromPtr(parent.bytes.ptr);
            if (base >= parent_base and base - parent_base <= parent.bytes.len and source.len <= parent.bytes.len - (base - parent_base)) {
                tracked = parent;
                tracked_offset = base - parent_base;
            } else tracked = MissingText.transformedFrom(parent, source);
        }
        var output: missing_dependency.Builder = .{};
        errdefer output.deinit(self.a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer copies.deinit(self.a);
        // The scanner proved these exact authored bytes before cutting away the
        // following HTML or an empty labeled list opener. Copy their phase
        // ranges unchanged; only the wrapper
        // is generated. No page input or phase descriptor is rewritten.
        try self.appendMissingHeadingSourceCopy(&output, &copies, tracked, tracked_offset + begin, tracked_offset + opening);
        try output.append(self.a, MissingText.untracked("<nowiki>"));
        try self.appendMissingHeadingSourceCopy(&output, &copies, tracked, tracked_offset + opening, tracked_offset + opening + 2);
        try output.append(self.a, MissingText.untracked("</nowiki>"));
        try self.appendMissingHeadingSourceCopy(&output, &copies, tracked, tracked_offset + opening + 2, tracked_offset + end);
        const prepared: InterruptedBodyPrefix = .{
            .source = try output.finish(self.a),
            .opening = opening - begin,
            .aliases_before = self.heading_source_aliases.items.len,
        };
        errdefer prepared.discard(self);
        try self.registerHeadingSourceCopies(prepared.source.bytes, copies.items);
        return prepared;
    }
    fn bodyRawInterruptedParagraph(self: *Renderer, blocks: *std.ArrayList(Block), source: []const u8, raw: []const u8, opening: usize, fallback: ?QuoteSeed, quotes: *?QuoteBoundaryScan, pending_join: *?bool) Error!void {
        const seed = (try self.rawBodyQuoteSeed(source, trim(raw), quotes)) orelse fallback;
        const prepared = try self.prepareInterruptedBodyPrefix(source, raw, opening);
        errdefer prepared.discard(self);
        const previous_missing = self.body_missing;
        self.body_missing = prepared.source;
        defer self.body_missing = previous_missing;
        self.fallbacks.literal_markup = true;
        // Successful paragraph spans/aliases retain this arena-owned buffer.
        // The original raw quote scan keeps its original coordinates.
        try self.bodyParagraph(blocks, prepared.source.bytes, if (seed) |value| prepared.forwardSeed(value) else null, pending_join);
    }

    // These are the complete authored H2 bodies of Plantilla:-noun.masc-
    // (3152/32844) and -noun.fem- (3153/32845). The linked declaration supplies
    // the noun role; neither a decimal-looking paragraph nor the edition does.
    fn aragoneseDecimalNounDomain(self: *const Renderer, blocks: []const Block, source: []const u8, start: usize, line: []const u8) bool {
        const code = self.source_classified_language orelse return false;
        const catalog = self.context.namespace_catalog orelse return false;
        if (!std.mem.eql(u8, code, "an") or !std.mem.eql(u8, catalog.wiki, "anwiktionary") or
            self.body_depth != 1 or self.in_reference or self.pre_block or self.parsed_pre or
            self.figure_caption_depth != 0 or self.in_template_literal_scope or self.block_formatting.code or
            self.body_link_target.len != 0 or self.navigation_target_probe != null or self.orphan_close_inline_origin) return false;
        const root = self.literal_url_root orelse return false;
        const tracked = self.body_missing orelse return false;
        if (root.ptr != source.ptr or root.len != source.len or tracked.bytes.ptr != source.ptr or tracked.bytes.len != source.len or
            tracked.unknown or tracked.lost_missing_range or start >= source.len or
            (start != 0 and source[start - 1] != '\n') or line.ptr != source[start..].ptr or line.len > source.len - start) return false;
        var heading: ?Block = null;
        var at = blocks.len;
        while (at != 0) {
            at -= 1;
            if (blocks[at].kind == .heading) { heading = blocks[at]; break; }
        }
        const declared = heading orelse return false;
        if (declared.level != 2 or declared.depth != 0 or declared.list_path.len != 0 or declared.container != null) return false;
        const male = "<H3>[[Image:Open_book_01.svg|30px]] ''[[Wiktionary:Sustantibo|Sustantivo masculín]]''</H3>";
        const female = "<H3>[[Image:Open_book_01.svg|30px]] ''[[Wiktionary:Sustantibo|Sustantivo femenín]]''</H3>";
        if (!std.mem.eql(u8, declared.text, male) and !std.mem.eql(u8, declared.text, female)) return false;
        const heading_at = std.math.sub(usize, @intFromPtr(declared.text.ptr), @intFromPtr(source.ptr)) catch return false;
        if (heading_at < 2 or heading_at >= start or declared.text.len + 2 > start - heading_at or
            (heading_at != 2 and source[heading_at - 3] != '\n') or
            !std.mem.eql(u8, source[heading_at - 2 .. heading_at], "==") or
            !std.mem.eql(u8, source[heading_at + declared.text.len ..][0..2], "==")) return false;
        for (tracked.ranges) |range| if (range.start < start + line.len and range.end > heading_at) return false;
        for (tracked.literal_curly_ranges) |range| if (range.start < start + line.len and range.end > heading_at) return false;
        for (tracked.generated_links) |range| if (range.start < start + line.len and range.end > heading_at) return false;
        return aragoneseDecimalLine(line);
    }
    fn aragoneseDecimalLine(line: []const u8) bool {
        if (line.len < 3 or line[0] < '1' or line[0] > '9') return false;
        var at: usize = 1;
        if (at < line.len and std.ascii.isDigit(line[at])) at += 1;
        if (at >= line.len or line[at] != '.' or trim(line[at + 1 ..]).len == 0) return false;
        at += 1;
        // Complete physical prose and ordinary internal actions only. Brackets,
        // templates, protected text, tables and multiline labels cannot lend a
        // numeric boundary. A terminal authored BR remains in the same block.
        while (at < line.len) {
            if (starts(line[at..], "[[")) {
                const end = std.mem.indexOfPos(u8, line, at + 2, "]]") orelse return false;
                const inner = line[at + 2 .. end];
                if (inner.len == 0 or std.mem.indexOfAny(u8, inner, "[]{}<>\r\n") != null) return false;
                const target_end = std.mem.indexOfScalar(u8, inner, '|') orelse inner.len;
                if (target_end == 0 or std.mem.indexOfAny(u8, inner[0..target_end], ":#") != null) return false;
                at = end + 2;
            } else if (line[at] == '<') {
                return std.mem.eql(u8, trim(line[at..]), "<br />") or std.mem.eql(u8, trim(line[at..]), "<br>") or std.mem.eql(u8, trim(line[at..]), "<br/>");
            } else {
                if (std.mem.indexOfScalar(u8, "[]{}\r\n", line[at]) != null or line[at] < 0x20 and line[at] != '\t') return false;
                at += 1;
            }
        }
        return true;
    }

    // Both the whole-page structural pass and the final owner must dispatch
    // this complete physical line as an ordinary, unjoined root paragraph.
    fn literalParagraphCopy(map: *const QuoteSourceMap, original: MissingText, output: MissingText) bool {
        if (!QuoteSourceMap.clean(original) or !QuoteSourceMap.clean(output) or map.has_literal_quote_edits or
            map.generated.items.len != 0 or map.copies.items.len != 1 or
            !inlineOverlaySameSourceSlice(map.original, original.bytes) or !inlineOverlaySameSourceSlice(map.output, output.bytes)) return false;
        const copied = map.copiedOriginal(output.bytes) orelse return false;
        return inlineOverlaySameSourceSlice(copied, original.bytes);
    }

    // Both the whole-page parser and the active section must select the same
    // unjoined physical paragraph. A copied SPAN in its inline-only source
    // can have a P, formatting element or ordinary link parent, never a LI.
    fn ordinaryParagraphSpanInput(self: *Renderer, tracked: MissingText) bool {
        const line = self.dispatched_static_paragraph orelse return false;
        const root = self.native_inline_motion_root orelse return false;
        const host = self.native_article_host orelse return false;
        const fragment = host.active_fragment orelse return false;
        const original = fragment.original_page orelse return false;
        const catalog = self.context.namespace_catalog orelse return false;
        const hints = self.semantic_capture orelse return false;
        if (!hints.ordinary_paragraph or !host.native_paragraph_css_subjects or !self.wikiClassOrdinaryDomain() or
            self.context.observe_structure_only or self.rejection_probe_scope or self.body_depth != 1 or
            self.media_depth != 0 or self.ruby_depth != 0 or self.figure_caption_depth != 0 or self.typed_table_depth != 0 or
            self.table_viewport_cell_source != null or self.native_inline_motion_epoch == 0 or root.reference != null or
            !host.matchesActive(self, root.source) or !QuoteSourceMap.cleanLocal(tracked) or
            !noLiParentSourceRange(root.source, line) or !inlineOverlaySameSourceSlice(fragment.prepared, root.source.bytes) or
            rootStaticParagraphLine(root.source.bytes, line) != null) return false;
        const current = self.wikiCellCurrentBodyRange(root.source, tracked.bytes) orelse return false;
        if (!inlineOverlaySameSourceSlice(current, line)) return false;
        const local = rootPhysicalParagraphLine(root.source.bytes, line) orelse return false;
        if (fragment.start > fragment.page.len or root.source.bytes.len > fragment.page.len - fragment.start) return false;
        const start = fragment.start + local;
        if (start > original.len or line.len > original.len - start or !containsSortedOffset(fragment.static_paragraph_openings, start) or
            !std.mem.eql(u8, line, original[start..][0..line.len]) or !std.mem.eql(u8, line, fragment.page[start..][0..line.len])) return false;
        return ordinaryParagraphInlineLine(catalog, line);
    }

    fn ordinaryParagraphInlineLine(catalog: *const @import("namespace_registry").Registry, line: []const u8) bool {
        if (line.len == 0 or line.len > 16 * 1024 or std.ascii.findIgnoreCase(line, "<span") == null or
            std.mem.indexOfAny(u8, line, "{}\x7f\r\n") != null or !staticListClosedSiblings(line, true, true, true)) return false;
        var at: usize = 0;
        while (std.mem.indexOfPos(u8, line, at, "[[")) |opening| {
            const pair = syntax.balanced(line, opening) orelse return false;
            const inner = line[opening + 2 .. pair.end - 2];
            if (std.mem.indexOfAny(u8, inner, "<>[]{}") != null or std.mem.count(u8, inner, "|") > 1) return false;
            const target = inner[0 .. std.mem.indexOfScalar(u8, inner, '|') orelse inner.len];
            if (target.len == 0 or target[0] == ':' or !std.mem.eql(u8, target, trim(target)) or !safeInternalTarget(target)) return false;
            const ns = catalog.ofTitle(target).id;
            if (ns < 0 or ns == 6) return false;
            at = pair.end;
        }
        return true;
    }

    fn rootStaticParagraphLine(source: []const u8, line: []const u8) ?usize {
        if (!starts(line, "'''") and !table_style_profile.staticInlineOwnerCandidate(line)) return null;
        return rootPhysicalParagraphLine(source, line);
    }

    fn rootPhysicalParagraphLine(source: []const u8, line: []const u8) ?usize {
        if (line.len < 7 or line.len > 16 * 1024 or
            std.mem.indexOfScalar(u8, line, '<') == null or std.mem.indexOfAny(u8, line, "\r\n") != null or
            !wikiClassContains(source, line)) return null;
        const start = @intFromPtr(line.ptr) - @intFromPtr(source.ptr);
        const end = start + line.len;
        if ((start != 0 and source[start - 1] != '\n') or
            (end != source.len and source[end] != '\r' and source[end] != '\n')) return null;
        return start;
    }

    fn bodyRawParagraph(self: *Renderer, blocks: *std.ArrayList(Block), source: []const u8, raw: []const u8, fallback: ?QuoteSeed, quotes: *?QuoteBoundaryScan, pending_join: *?bool) Error!void {
        const parsed = if (self.parsed_pre) raw else trim(raw);
        const seed = (try self.rawBodyQuoteSeed(source, parsed, quotes)) orelse fallback;
        const previous = self.dispatched_static_paragraph;
        self.dispatched_static_paragraph = null;
        defer self.dispatched_static_paragraph = previous;
        const unjoined_root = pending_join.* == null and self.body_depth == 1 and !self.rejection_probe_scope and !self.in_reference and !self.pre_block and !self.parsed_pre and
            !self.in_template_literal_scope and self.body_link_target.len == 0 and self.explicit_wiki_label == null and
            !self.figure_implicit_list_context and !self.html_list_item_flow and !self.html_blockquote_flow;
        const previous_blocks = blocks.items.len;
        const paint_start = if (unjoined_root) rootStaticParagraphLine(source, parsed) else null;
        // Paint candidates retain their existing pre-emission registration.
        // A plain inline paragraph can borrow the same ordered offset vector
        // only after the whole-page parser has emitted one complete paragraph.
        const span_start = if (unjoined_root and paint_start == null and
            (self.page_static_paragraph_openings != null or self.native_inline_motion_root != null) and
            std.ascii.findIgnoreCase(parsed, "<span") != null) rootPhysicalParagraphLine(source, parsed) else null;
        if (unjoined_root) {
            if (paint_start) |start| {
                if (self.page_static_paragraph_openings) |openings| {
                    const root = self.heading_source;
                    if (self.page_html_heading_openings != null and self.page_wiki_heading_openings != null and
                        root != null and inlineOverlaySameSourceSlice(source, root.?)) try openings.append(self.a, start);
                }
            }
            if (paint_start != null or span_start != null) if (self.native_inline_motion_root) |root| {
                if (inlineOverlaySameSourceSlice(source, root.source.bytes)) self.dispatched_static_paragraph = parsed;
            };
        }
        try self.bodyParagraph(blocks, raw, seed, pending_join);
        if (unjoined_root and pending_join.* == null and blocks.items.len == previous_blocks + 1 and blocks.items[previous_blocks].kind == .paragraph) {
            if (span_start) |start| if (self.page_static_paragraph_openings) |openings| {
                const whole = self.heading_source;
                if (self.page_html_heading_openings != null and self.page_wiki_heading_openings != null and
                    whole != null and inlineOverlaySameSourceSlice(source, whole.?)) try openings.append(self.a, start);
            };
