            self.manualConversionLinkedScope(body[0..at], true)) return .{ 0, 0 };
        if (at == 0 or at > body.len or at > 4096) return null;
        const source_ptr = @intFromPtr(tracked.bytes.ptr);
        const body_ptr = @intFromPtr(body.ptr);
        if (body_ptr < source_ptr or body_ptr - source_ptr > tracked.bytes.len or
            body.len > tracked.bytes.len - (body_ptr - source_ptr)) return null;
        const offset = body_ptr - source_ptr;
        // BR precedes the outer rule and is never deleted. Prove the complete
        // original prefix, including its void separators, is not protected or
        // generated. Unknown remains unknown; no style or ancestry is issued.
        if (!recursivePositionInterval(tracked, offset, offset + at)) return null;
        var start: usize = 0;
        var cursor: usize = 0;
        var found = false;
        while (cursor < at) {
            if (body[cursor] != '<') { cursor += 1; continue; }
            const tag = syntax.tagAt(body[0..at], cursor) orelse return null;
            if (tag.is("br")) {
