            cursor = tag.end;
        }
        const tail = body[start..at];
        if (!found or !formattingAngleBodyPosition(tail, tail.len) or
            !self.manualConversionLinkedScope(tail, true)) return null;
        return .{ offset, offset + at };
    }

    fn tableManualInlinePart(self: *Renderer, body: []const u8, style: Style, first: bool) Error!bool {
