        if (std.mem.indexOfScalar(u8, line, '\n') != null) return null;
        const tag = syntax.tagAt(line, 0) orelse return null;
        if (!tag.is("noinclude") or tag.self_closing or trim(tag.attrs).len != 0) return null;
        if (tag.closing) {
