const Heading = struct { level: u8, title: []const u8 };
fn headingLine(line: []const u8) ?Heading {
    return headingLineControlled(line, null);
}

fn headingLineControlled(line: []const u8, matcher: ?syntax.ControlMatcher) ?Heading {
    const heading = syntax.controlHeading(line, matcher) orelse return null;
    const title = trim(heading.title);
    return .{ .level = heading.level, .title = title };
}
const CellContent = struct { text: []const u8, attrs: ?[]const u8 = null, colspan: u16 = 1, rowspan: u16 = 1, swatch_color: ?[]const u8 = null };

fn rubyFallbackSpans(a: A, spans: []const Span) Error![]const Span {
    var present = false;
    for (spans) |span| present = present or span.ruby != null or span.inline_padding_group != null or span.inline_action_group != null or span.inline_box_group != null;
    if (!present) return spans;
    const Capture = struct {
        a: A,
        values: std.ArrayList(Span) = .empty,
        fn emit(self: *@This(), span: Span) A.Error!void { try self.values.append(self.a, span); }
    };
    var capture: Capture = .{ .a = a };
    errdefer capture.values.deinit(a);
    presentation_types.visitRubyFallback(spans, &capture, Capture.emit) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return error.UncompiledPresentation,
    };
    return try capture.values.toOwnedSlice(a);
}

fn flattened(a: A, spans: []const Span) ![]u8 {
    for (spans) |span| if (span.ruby != null or span.inline_padding_group != null or span.inline_action_group != null or span.inline_box_group != null) return rubyPlainText(a, spans, false);
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(a);
    for (spans) |s| try out.appendSlice(a, s.text);
    return out.toOwnedSlice(a);
}
