pub fn hasInlineImage(spans: []const Span) bool {
    for (spans) |span| if (span.image != null) return true;
    return false;
}

fn rubyPlainText(a: A, spans: []const Span, comptime plain_policy: bool) Error![]u8 {
    const Emit = struct {
        a: A,
        out: std.ArrayList(u8) = .empty,
        fn span(self: *@This(), value: Span) A.Error!void {
            if (comptime !plain_policy) return self.out.appendSlice(self.a, value.text);
            // Preserve the existing compiler plain-text policy: images vanish,
            // templates retain their diagnostic, and build spans have no trail.
            if (value.image != null) return;
            if (value.kind == .template) {
                try self.out.appendSlice(self.a, "[unavailable template: ");
                try self.out.appendSlice(self.a, value.target);
                try self.out.append(self.a, ']');
            } else if (value.kind == .line_break) try self.out.append(self.a, '\n')
            else try self.out.appendSlice(self.a, value.text);
        }
    };
    var emit: Emit = .{ .a = a };
    errdefer emit.out.deinit(a);
    // This callback can fail only allocation; the visitor's own failure is an
    // invalid Ruby shape. Neither becomes a silently empty display string.
    presentation_types.visitRubyFallback(spans, &emit, Emit.span) catch |failure| switch (failure) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return error.UncompiledPresentation,
    };
    return emit.out.toOwnedSlice(a);
}

pub fn plainText(a: A, spans: []const Span) Error![]u8 {
    for (spans) |span| if (span.ruby != null or span.inline_padding_group != null or span.inline_action_group != null or span.inline_box_group != null) return rubyPlainText(a, spans, true);
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(a);
    for (spans) |span| {
        if (span.image != null) continue;
        if (span.kind == .template) {
            try out.appendSlice(a, "[unavailable template: ");
            try out.appendSlice(a, span.target);
            try out.append(a, ']');
        } else if (span.kind == .line_break) try out.append(a, '\n') else try out.appendSlice(a, span.text);
    }
    return out.toOwnedSlice(a);
}

