    // An unmatched nowiki spelling is literal; malformed attribute markup remains visible.
    var quoted: Renderer = .{ .a = a, .context = .{} };
    const quoted_blocks = try quoted.renderBody(
        "<table class=\"translations\"><tr><td>\n" ++
