        .{ .source = "ISBN 979-0-306-40615-8.", .label = "ISBN 979-0-306-40615-8", .number = "9790306406158" },
        .{ .source = "ISBN 123456789x 2020", .label = "ISBN 123456789x", .number = "123456789X" },
