        try std.testing.expect(!std.mem.eql(u8, span.target, "Page"));
        if (std.mem.eql(u8, span.text, "one")) {
            try std.testing.expect(span.kind == .text and span.flags.bold and span.target.len == 0);
            one = true;
        }
        if (std.mem.eql(u8, span.text, "two")) {
