    for ([_]Case{
        .{ .source = "''a'''''b'''", .a_bold = false, .a_italic = true, .b_bold = true, .b_italic = false },
        .{ .source = "'''a'''''b''", .a_bold = true, .a_italic = false, .b_bold = false, .b_italic = true },
