    }
    for ([_]u32{ 0, 1, 8, 11, 12, 13, 14, 31, 0x7f, 0x80, 0x9f, 0xd800, 0xdfff, 0xfffe, 0xffff, 0x110000 }) |cp| {
        const source = try std.fmt.allocPrint(a, "&#x{x};", .{cp});
