    const normal = try ordinary.renderBody("{|\n| loose\n|}");
    try std.testing.expectEqual(@as(usize, 1), normal.len);
    try std.testing.expectEqualStrings("loose", try flattened(a, normal[0].table.?.rows[0].cells[0].spans));
}

