test "unknown parser entity braces reject malformed external targets and keep intended labels" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var renderer: Renderer = .{ .a = a, .context = .{ .title = "शारदा", .language = "Hindi" } };
    const spans = try renderer.parseSpans("[https://hindwidictionary.com/search?keyword=&#123;&#123;#urlencode:शारदा&#125;&#125; शारदा]", .{});
    try std.testing.expectEqualStrings("शारदा", try flattened(a, spans));
    try std.testing.expect(spans.len != 0);
    for (spans) |span| {
        try std.testing.expectEqual(ir.InlineKind.text, span.kind);
        try std.testing.expectEqualStrings("", span.target);
    }
    // Entity-authored closing braces in the label remain literal after target rejection.
    const entity_label = try renderer.parseSpans("[https://example.test/?q=&#123;&#123;#urlencode:alpha beta&#125;&#125; label]", .{});
    try std.testing.expectEqualStrings("beta}} label", try flattened(a, entity_label));
    for (entity_label) |span| {
        try std.testing.expectEqual(ir.InlineKind.text, span.kind);
        try std.testing.expectEqualStrings("", span.target);
        if (std.mem.indexOfAny(u8, span.text, "{}") != null)
            try std.testing.expectEqual(Provenance.entity_literal, span.provenance);
    }
    try std.testing.expect(renderer.fallbacks.rejected_external_target);
    // The rejected entity-authored URL remains nonaction. Its independently
    // parsed raw closing pair follows the ordinary orphan-template policy.
    var raw_renderer: Renderer = .{ .a = a, .context = .{} };
    const raw_label = try raw_renderer.parseSpans("[https://example.test/?q=&#123;&#123;#urlencode:alpha beta}} label]", .{});
    try std.testing.expectEqualStrings("beta[malformed template] label", try flattened(a, raw_label));
    var generated: usize = 0;
    for (raw_label) |span| {
        try std.testing.expect(span.kind == .text and span.target.len == 0 and !span.self_link);
        if (span.generated_diagnostic) {
            generated += 1;
            try std.testing.expectEqualStrings("[malformed template]", span.text);
            try std.testing.expectEqual(Provenance.parsed, span.provenance);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), generated);
    try std.testing.expect(raw_renderer.fallbacks.rejected_external_target and raw_renderer.fallbacks.literal_markup);
    // The original empty nowiki survives executable/link parsing upstream.
    // Only its preceding single brace is protected; the URL remains rejected.
    var split_renderer: Renderer = .{ .a = a, .context = .{} };
    const split_source = "[https://example.test/?q=&#123;&#123;#urlencode:alpha beta}<nowiki/>} label]";
    const split_label = try split_renderer.parseSpans(split_source, .{});
    try std.testing.expectEqualStrings("beta}} label", try flattened(a, split_label));
    try std.testing.expectEqual(@as(usize, 3), split_label.len);
    const split_text = [_][]const u8{ "beta", "}", "} label" };
    for (split_label, 0..) |span, index| {
        try std.testing.expectEqualStrings(split_text[index], span.text);
        try std.testing.expectEqual(if (index == 1) Provenance.protected_literal else Provenance.parsed, span.provenance);
        try std.testing.expect(span.kind == .text and span.target.len == 0 and !span.self_link and !span.generated_diagnostic);
    }
    try std.testing.expect(split_renderer.fallbacks.rejected_external_target);
    try std.testing.expectError(error.UncompiledPresentation, requireCompiledText(try flattened(a, split_label)));
    const authored_nowiki = try renderer.parseSpans("[https://example.test/?q=<nowiki>{{alpha beta}}</nowiki> label]", .{});
    try std.testing.expectEqualStrings("{{alpha beta}} label", try flattened(a, authored_nowiki));
    for (authored_nowiki) |span| try std.testing.expectEqualStrings("https://example.test/?q=", span.target);
    const html_label = try renderer.parseSpans("[https://example.test/?q=x <i>label</i>]", .{});
    try std.testing.expectEqualStrings("label", try flattened(a, html_label));
    for (html_label) |span| try std.testing.expectEqualStrings("https://example.test/?q=x", span.target);
    var literal: Renderer = .{ .a = a, .context = .{} };
    const protected = try literal.parseSpans("<nowiki>{{#urlencode:x}}</nowiki>", .{});
    try std.testing.expectEqualStrings("{{#urlencode:x}}", try flattened(a, protected));
    for (protected) |span| {
        try std.testing.expectEqual(Provenance.protected_literal, span.provenance);
        try std.testing.expectEqual(ir.InlineKind.text, span.kind);
    }
}

