    }
    for ([_][]const u8{ "&#62;", "&#x3E;", "&GT;" }) |entity| {
        var buf: [160]u8 = undefined;
        const source = try std.fmt.bufPrint(&buf, "[https://example.test/a{s}b label]", .{entity});
        try externalDelimiterCheck(source, "label", "https://example.test/a%3Eb");
    }
