test "wiki caption blocks preserve opener-line literals protected tables and DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var protected_renderer: Renderer = .{ .a = a, .context = .{} };
    const protected = try protected_renderer.renderBody("{|\n|+ * literal <nowiki>{| [[A|protected]] |}</nowiki>\n|}");
    const literal = protected[0].table.?.caption;
    try std.testing.expectEqualStrings("* literal {| [[A|protected]] |}", try plainText(a, literal));
    try std.testing.expect(!unclosedExternalRecoveryHasLink(literal, .link, "A"));
    var provenance = false;
    for (literal) |span| if (std.mem.indexOf(u8, span.text, "[[A|protected]]") != null) {
        try std.testing.expectEqual(Provenance.protected_literal, span.provenance);
        provenance = true;
    };
    try std.testing.expect(provenance);
    const blob = @import("blob_encoder");
    const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
    var r: Renderer = .{ .a = a, .context = .{} };
    const blocks = try r.renderBody("{|\n|+ Outer caption\n{|\n| [[A|''Inner lexical'']]\n|}\n|+ Following caption\n| outer cell\n|}");
    const sections = [_]Section{.{ .blocks = blocks }};
    const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, r.refs.items, r.media.items);
    const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "caption blocks", .language, .{ .code = "en", .heading = "English" });
    const table = decoded.entry.sections[0].blocks[0].table.?;
    try std.testing.expectEqual(@as(usize, 0), table.caption.len);
    const children = table.caption_blocks orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 4), children.len);
    try std.testing.expect(children[0].kind == .paragraph and children[1].kind == .table);
    try std.testing.expect(children[2].kind == .paragraph and children[3].kind == .paragraph);
    const separator = try FigureProducerTest.bodySpans(a, children[2..3]);
    try std.testing.expectEqual(@as(usize, 1), separator.len);
    try std.testing.expect(separator[0].kind == .line_break);
    var visible: std.ArrayList(u8) = .empty;
    var linked = false;
    // Preserve the original lexical trace across the real paragraph/table
    // boundary, then consume the explicit repeated-caption separator as stored.
    try visible.appendSlice(a, try FormattingScopeTest.text(a, try FigureProducerTest.bodySpans(a, children[0..1])));
    try visible.append(a, '\n');
    try visible.appendSlice(a, try FormattingScopeTest.text(a, try FigureProducerTest.bodySpans(a, children[1..])));
    const caption = try FigureProducerTest.bodySpans(a, children);
    for (caption) |span| {
        if (span.kind == .link) {
            try std.testing.expectEqualStrings("A", span.target);
            try std.testing.expect(span.italic);
            linked = true;
        }
    }
    try std.testing.expectEqualStrings("Outer caption\nInner lexical\nFollowing caption", visible.items);
    try std.testing.expect(linked);
    try std.testing.expectEqualSlices(u8, bytes, try blob.presentation_codec.encodeAlloc(a, decoded));
    var cell: std.ArrayList(u8) = .empty;
    for (table.rows[0].cells[0].spans) |span| try cell.appendSlice(a, span.text);
    try std.testing.expectEqualStrings("outer cell", cell.items);
}

fn freeExternalBoundaryCheck(source: []const u8, visible: []const u8, target: []const u8) !void {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    const spans = try r.parseSpans(source, .{});
    try std.testing.expectEqualStrings(visible, try plainText(a, spans));
    var linked: usize = 0;
    for (spans) |span| {
        if (span.kind == .external_link) {
            linked += 1;
            try std.testing.expectEqualStrings(target, span.target);
            try std.testing.expectEqualStrings(target, span.text);
        } else {
            try std.testing.expectEqual(.text, span.kind);
            try std.testing.expectEqualStrings("", span.target);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), linked);
}

test "free URL angle boundaries retain linked prefix and visible suffix" {
    for ([_][]const u8{ "&lt;", "&#60;", "&#x3C;", "&#X3c;", "&#00060;" }) |entity| {
        var source: [160]u8 = undefined;
        const input = try std.fmt.bufPrint(&source, "https://example.test/a{s}b tail", .{entity});
        try freeExternalBoundaryCheck(input, "https://example.test/a<b tail", "https://example.test/a");
    }
    for ([_][]const u8{ "&gt;", "&#62;", "&#x3E;" }) |entity| {
        var source: [160]u8 = undefined;
        const input = try std.fmt.bufPrint(&source, "https://example.test/a{s}b", .{entity});
        try freeExternalBoundaryCheck(input, "https://example.test/a>b", "https://example.test/a");
    }
    try freeExternalBoundaryCheck("https://example.test/a.&lt;b", "https://example.test/a.<b", "https://example.test/a");
    try freeExternalBoundaryCheck("https://example.test/?a=1&amp;b=2&lt;tail", "https://example.test/?a=1&b=2<tail", "https://example.test/?a=1&b=2");
    try freeExternalBoundaryCheck("https://example.test/a<tail", "https://example.test/a<tail", "https://example.test/a");
}

test "free URL boundary does not broaden schemes or bracketed angle admission" {
    try externalDelimiterCheck("http://&lt;word", "http://<word", null);
    try externalDelimiterCheck("javascript:alert(1)&lt;b", "javascript:alert(1)<b", null);
    try externalDelimiterCheck("<nowiki>https://example.test/a&lt;b</nowiki>", "https://example.test/a<b", null);
    try externalDelimiterCheck("https://example.test/?a=1&amp;b=2", "https://example.test/?a=1&b=2", "https://example.test/?a=1&b=2");
    try externalDelimiterCheck("https://example.test/a&amp;lt;b", "https://example.test/a&lt;b", "https://example.test/a&lt;b");
    try externalDelimiterCheck("https://example.test/a&LT;b", "https://example.test/a<b", "https://example.test/a%3Cb");
    try externalDelimiterCheck("https://example.test/a&GT;b", "https://example.test/a>b", "https://example.test/a%3Eb");
    try externalDelimiterCheck("[https://example.test/a&lt;b label]", "<b label", "https://example.test/a");
    try externalDelimiterCheck("[https://example.test/a&#60;b label]", "label", "https://example.test/a%3Cb");
    try externalDelimiterCheck("[https://example.test/a&LT;b label]", "label", "https://example.test/a%3Cb");
}

