        .{ .source = "<gallery>A.png|Body</gallery>", .visible = "Body" },
        .{ .source = "<gallery caption=''>A.png|Body</gallery>", .visible = "Body" },
        .{ .source = "<gallery caption='&lt;nowiki&gt;[[Literal]]&lt;/nowiki&gt;'>A.png|Body</gallery>", .visible = "[[Literal]]\nBody" },
    };
    for (cases) |case| {
