        .{ .source = "<-i-t:n:ra-Ax-x:n->", .signs = "𓍹𓐼𓇋𓏏𓐰𓈖𓐰𓇳𓅜𓐍𓐰𓈖𓐽𓍺" },
    }) |case| {
