        try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "مستعارة من {s} المصرية رابط بعد", .{case.signs}), try plainText(a, spans));
        try std.testing.expect(!renderer.fallbacks.any());
        var found = false;
