    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{ "link", "link=''", "link='maybe'", "dir='rtl'", "link='true' dir='rtl'", "link='false' link='true'", "link='true' class='x'", "link='true' extra", "link='true'junk" }) |attrs| {
