        try std.testing.expectEqualStrings("K3-N36 رابط", try plainText(a, spans));
        try std.testing.expect(renderer.fallbacks.unsupported_element);
        var coded: std.ArrayList(u8) = .empty;
        for (spans) |span| if (span.flags.code) try coded.appendSlice(a, span.text);
        try std.testing.expectEqualStrings("K3-N36", coded.items);
        try std.testing.expect(unclosedExternalRecoveryHasLink(spans, .link, "مصر"));
    }
    try std.testing.expect(!supportedHieroAttributes("link='true"));
    var unknown: Renderer = .{ .a = a, .context = .{} };
    const unknown_spans = try unknown.parseSpans("<hiero link='true'>K3-NotASign</hiero>", .{});
    try std.testing.expectEqualStrings("K3-NotASign", try plainText(a, unknown_spans));
    try std.testing.expect(unknown.fallbacks.unsupported_element);
    var protected: Renderer = .{ .a = a, .context = .{} };
    const literal = try protected.parseSpans("<nowiki><hiero link='true'>K3-N36</hiero></nowiki>", .{});
    try std.testing.expectEqualStrings("<hiero link='true'>K3-N36</hiero>", try plainText(a, literal));
    try std.testing.expect(!protected.fallbacks.unsupported_element);
}

test "wiki header rows accept both separators while preserving protected delimiters" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    // Verbatim Sjabloon:nl-vervoeging page 27799 revision 171813 header row.
    const blocks = try r.renderBody("{|\n! colspan=\"2\" bgcolor=\"#FFF0E0\"| Gebiedende wys || bgcolor=\"FFF0E0\"| Aanvoegende wys  !!colspan=\"3\" bgcolor=\"#FFFFE0\"| Onvoltooide deelwoord || colspan=\"3\" bgcolor=\"#FFFFE0\"| Voltooide deelwoord \n|-\n| [[sterven|sterf]] || [[sterven|sterve]] || stervend || gestorven\n|}\n");
    const table = blocks[0].table.?;
    try std.testing.expectEqual(@as(usize, 2), table.rows.len);
    try std.testing.expectEqual(@as(usize, 4), table.rows[0].cells.len);
    const labels = [_][]const u8{ "Gebiedende wys", "Aanvoegende wys", "Onvoltooide deelwoord", "Voltooide deelwoord" };
    const widths = [_]u16{ 2, 1, 3, 3 };
    for (table.rows[0].cells, labels, widths) |cell, label, width| {
        try std.testing.expect(cell.header and cell.colspan == width and cell.rowspan == 1);
        try std.testing.expectEqualStrings(label, std.mem.trim(u8, try flattened(a, cell.spans), " \t\r\n"));
    }
    try std.testing.expectEqual(@as(usize, 4), table.rows[1].cells.len);
    var found_action = false;
    for (table.rows[1].cells[0].spans) |span| {
        if (span.kind == .link and std.mem.eql(u8, span.target, "sterven") and std.mem.eql(u8, span.text, "sterf")) found_action = true;
    }
    try std.testing.expect(found_action);
    const protected = try r.renderBody("{|\n! [[Target|A||B!!C]] || <nowiki>{{unknown|a||b!!c}}</nowiki> !! <nowiki>D||E!!F</nowiki>\n|-\n| alpha !! beta || omega\n|}\n");
    const shielded = protected[0].table.?;
    // handleTables follows variable expansion and precedes internal links:
    // raw link punctuation is not protection. An intentionally unexpanded
    // template is protected explicitly by nowiki at this Renderer boundary.
    const protected_labels = [_][]const u8{ "[malformed link] Target|A", "B", "C]]", "{{unknown|a||b!!c}}", "D||E!!F" };
    try std.testing.expectEqual(protected_labels.len, shielded.rows[0].cells.len);
    for (shielded.rows[0].cells, protected_labels) |cell, label| {
        try std.testing.expect(cell.header and cell.colspan == 1 and cell.rowspan == 1);
        try std.testing.expectEqualStrings(label, std.mem.trim(u8, try flattened(a, cell.spans), " \t\r\n"));
        for (cell.spans) |span| try std.testing.expect(span.kind == .text and span.target.len == 0);
    }
    try std.testing.expectEqual(@as(usize, 2), shielded.rows[1].cells.len);
    try std.testing.expect(!shielded.rows[1].cells[0].header);
    try std.testing.expectEqualStrings("alpha !! beta", std.mem.trim(u8, try flattened(a, shielded.rows[1].cells[0].spans), " \t\r\n"));
}

test "DIV scope retains complete wiki tables across inner closing tags" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var stage: []const u8 = "top typed cells";
    errdefer std.debug.print("DIV table regression stage={s}\n", .{stage});
    const ExactCell = struct {
        fn body(cell: Cell, column: usize) ![]const Span {
            const retained_count: ?usize = if (cell.blocks) |children| children.len else null;
            errdefer std.debug.print("DIV table cell column={d} direct_spans={d} retained_blocks={any}\n", .{ column, cell.spans.len, retained_count });
            try std.testing.expect(cell.nested_table == null);
            if (column == 0) {
                try std.testing.expect(cell.blocks == null and cell.spans.len != 0);
                try std.testing.expectEqual(@as(?presentation_types.CellTextAlign, .right), (cell.style orelse return error.TestUnexpectedResult).text_align);
                return cell.spans;
            }
            try std.testing.expectEqual(@as(usize, 1), column);
            try std.testing.expectEqual(@as(usize, 0), cell.spans.len);
            if (cell.style) |style| try std.testing.expect(style.text_align == null);
            const children = cell.blocks orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(@as(usize, 1), children.len);
            const child = children[0];
            errdefer std.debug.print("DIV CENTER child kind={s} style={any} align={any}\n", .{ @tagName(child.kind), child.style, child.text_align });
            try std.testing.expectEqual(Kind.paragraph, child.kind);
            try std.testing.expect(child.style == null and child.table == null and child.figure == null and child.flow == null and child.container == null and child.feature == null);
            try std.testing.expect(child.depth == 0 and child.level == 0 and child.list_path.len == 0 and child.number.len == 0);
            try std.testing.expectEqual(@as(?presentation_types.CellTextAlign, .center), child.text_align);
            try std.testing.expect(child.spans.len != 0);
            return child.spans;
        }
        fn paint(table: Table) !void {
            // The no-profile path now retains finite authored inline Table
            // paint. Require exactly that border, with no unrelated style fields.
            try std.testing.expectEqualDeep(presentation_types.TableStyle{ .border = .{ .solid = .{
                .width = .{ .unit = .px, .value = 1 }, .color = "#dfdfdf",
            } } }, table.style orelse return error.TestUnexpectedResult);
            try geometry(table);
        }
        fn geometry(table: Table) !void {
            try std.testing.expectEqualDeep(presentation_types.TableGeometry{ .width = .{ .unit = .percent, .value = 100 } }, table.geometry orelse return error.TestUnexpectedResult);
        }
        fn selectedPaint(table: Table) !void {
            try std.testing.expectEqualDeep(presentation_types.TableStyle{ .border = .{ .solid = .{
                .width = .{ .unit = .px, .value = 1 }, .color = "#dfdfdf",
            } } }, table.style orelse return error.TestUnexpectedResult);
            try geometry(table);
        }
        const calls = [_][]const u8{
            "PAGESINCATEGORY:صفحات للحذف السريع",
            "PAGESINCATEGORY:صفحات للحذف السريع يطلب التمهل في حذفها",
        };
        fn templates(table: Table) !void {
            var count: usize = 0;
            for (table.rows, 0..) |row, ri| for (row.cells, 0..) |cell, ci| {
                for (try body(cell, ci)) |span| if (span.kind == .template) {
                    try std.testing.expect(ri == 2 and ci == 1 and count < calls.len);
                    try std.testing.expectEqualStrings(calls[count], span.target);
                    try std.testing.expectEqualStrings(calls[count], span.text);
                    try std.testing.expect(!span.generated_diagnostic and span.provenance == .parsed);
                    count += 1;
                };
            };
            try std.testing.expectEqual(calls.len, count);
        }
        fn literalSource(allocator: A, original: []const u8) ![]const u8 {
            var protected = original;
            for (calls) |call| {
                const token = try std.fmt.allocPrint(allocator, "{{{{{s}}}}}", .{call});
                // This is separate authored literal coverage, not expansion or
                // a fabricated category count. Every original byte survives.
                const wrapped = try std.fmt.allocPrint(allocator, "<nowiki>{s}</nowiki>", .{token});
                try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, original, token));
                protected = try std.mem.replaceOwned(u8, allocator, protected, token, wrapped);
            }
            try std.testing.expectEqualStrings(original, try std.mem.replaceOwned(u8, allocator,
                try std.mem.replaceOwned(u8, allocator, protected, "<nowiki>", ""), "</nowiki>", ""));
            return protected;
        }
        fn literalBody(allocator: A, original: []const Span, protected: []const Span) !void {
            var observed_index: usize = 0;
            var observed_offset: usize = 0;
            for (original) |source_span| {
                var wanted = source_span;
                if (wanted.kind == .template) {
                    wanted.kind = .text;
                    wanted.target = "";
                    wanted.provenance = .protected_literal;
                    wanted.text = try std.fmt.allocPrint(allocator, "{{{{{s}}}}}", .{source_span.text});
                }
                const text = wanted.text;
                wanted.text = "";
                for (text) |byte| {
                    while (observed_index < protected.len and observed_offset == protected[observed_index].text.len) {
                        observed_index += 1;
                        observed_offset = 0;
                    }
                    try std.testing.expect(observed_index < protected.len);
                    var observed = protected[observed_index];
                    try std.testing.expectEqual(byte, observed.text[observed_offset]);
                    observed.text = "";
                    // Ignore span splitting only. Every source-owned action,
                    // font, language, paint and protection attribute is exact.
                    try std.testing.expectEqualDeep(wanted, observed);
                    observed_offset += 1;
                }
            }
            while (observed_index < protected.len and observed_offset == protected[observed_index].text.len) {
                observed_index += 1;
                observed_offset = 0;
            }
            try std.testing.expectEqual(protected.len, observed_index);
        }
        fn literalCodec(allocator: A, context: Context, source: []const u8, original: []const Block, wanted_tables: usize) !presentation_types.Stored {
            var rendered: Renderer = .{ .a = allocator, .context = context };
            const values = try rendered.renderBody(source);
            try std.testing.expectEqual(@as(usize, 0), rendered.unresolved_templates);
            var count: usize = 0;
            for (values) |block| if (block.table) |table| {
                count += 1;
                var source_table: ?Table = null;
                var source_index: usize = 0;
                for (original) |raw_block| if (raw_block.table) |raw_table| {
                    source_index += 1;
                    if (source_index == count) source_table = raw_table;
                };
                const raw_table = source_table orelse return error.TestUnexpectedResult;
                try std.testing.expectEqual(@as(usize, 4), table.rows.len);
                if (context.table_styles != null) try selectedPaint(table) else try paint(table);
                for (table.rows, raw_table.rows) |row, raw_row| {
                    try std.testing.expectEqual(@as(usize, 2), row.cells.len);
                    for (row.cells, raw_row.cells, 0..) |cell, raw_cell, ci| {
                        const spans = try body(cell, ci);
                        for (spans) |span| try std.testing.expect(span.kind != .template);
                        try literalBody(allocator, try body(raw_cell, ci), spans);
                    }
                }
                const literal = try flattened(allocator, try body(table.rows[2].cells[1], 1));
                for (calls) |call| {
                    const token = try std.fmt.allocPrint(allocator, "{{{{{s}}}}}", .{call});
                    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, literal, token));
                }
            };
            try std.testing.expectEqual(wanted_tables, count);
            return (try parity(allocator, &rendered, values,
                try std.mem.replaceOwned(u8, allocator, source, "<center>", "<center style='text-align:center'>"), false)) orelse return error.TestUnexpectedResult;
        }
        fn parity(allocator: A, actual: *Renderer, values: []const Block, explicit_source: []const u8, unexpanded: bool) !?presentation_types.Stored {
            var reference: Renderer = .{ .a = allocator, .context = actual.context };
            const expected_blocks = try reference.renderBody(explicit_source);
            try std.testing.expectEqualDeep(expected_blocks, values);
            try std.testing.expectEqualDeep(reference.fallbacks, actual.fallbacks);
            if (unexpanded) {
                // The retained template fixture is deliberately pre-expansion.
                // Full build-graph equality does not permit shipping its calls.
                try std.testing.expectError(error.UncompiledTemplate, FormattingScopeTest.encode(allocator, &reference, expected_blocks));
                try std.testing.expectError(error.UncompiledTemplate, FormattingScopeTest.encode(allocator, actual, values));
                return null;
            }
            const expected = try FormattingScopeTest.encode(allocator, &reference, expected_blocks);
            const stored = try FormattingScopeTest.encode(allocator, actual, values);
            try std.testing.expectEqualDeep(expected, stored);
            return stored;
        }
    };
    // Exact retained included template body. Category-count calls are deliberately
    // not evaluated here; the fixture checks table syntax and existing actions.
    const captured = "<DIV STYLE=\"font-size: 80%\">\n{| width=\"100%\" style=\"border: 1px solid #dfdfdf;\"\n|-\n| align=\"right\" | '''مساهمات:'''\n| <center>[[خاص:صفحات جديدة|صفحات جديدة]] – [[خاص:ملفات جديدة|ملفات جديدة]] – [[خاص:RecentChanges/hideliu|مساهمات غير المسجلين]].</center>\n|-\n| align=\"right\" | '''صفحــات:'''\n| <center>[[ويكاموس:الميدان|الميدان]] – [[ويكاموس:بوابة المجتمع|بوابة المجتمع]] – [https://lists.wikimedia.org/postorius/lists/wikiar-l.lists.wikimedia.org/ القائمة البريدية] – [[ويكاموس:أسئلة متكررة|أسئلة متكررة]] – [[ويكاموس:صيغة الكتابة|صيغة الكتابة]] – [[خاص:صفحات مطلوبة|وصلات حمراء]] – [[ويكاموس:إداريون|الإداريون]] – [[ويكاموس:استطلاع رأي|استطلاع الآراء]] – [[ويكاموس:مفردة تعاون الأسبوع|مفردة تعاون الأسبوع]].</center>\n|- \n| align=\"right\" | '''متابعـــــة:'''\n| <center>[[خاص:صفحات قصيرة|صفحات قصيرة]] – [[خاص:صفحات يتيمة|صفحات يتيمة]] – [[خاص:صفحات غير مصنفة|صفحات غير مصنفة]] – [[ويكاموس:طلبات الصلاحيات|طلبات الصلاحيات]] – [[ويكاموس:إخطار الإداريين|إخطار الإداريين]] – [[:تصنيف:صفحات للحذف السريع|للحذف السريع]] <small>({{PAGESINCATEGORY:صفحات للحذف السريع}})</small> – [[:تصنيف:صفحات للحذف السريع يطلب التمهل في حذفها|نقاش الحذف]] <small>({{PAGESINCATEGORY:صفحات للحذف السريع يطلب التمهل في حذفها}})</small>.</center>\n|-\n| align=\"right\" | '''مشاريــــع:'''\n| <center>[[w:خاص:أحدث التغييرات|ويكيبيديا]] – [[b:خاص:أحدث التغييرات|ويكي الكتب]] – [[q:خاص:أحدث التغييرات|ويكي الاقتباس]] – [[s:خاص:أحدث التغييرات|ويكي مصدر]] – [[n:خاص:أحدث التغييرات|ويكي الأخبار]] – [[v:خاص:أحدث التغييرات|ويكي الجامعة]] – [[commons:Special:RecentChanges|كومنز]] – [[d:Special:RecentChanges|ويكي بيانات]] – [[m:Special:RecentChanges|ميتا]] – [[wikispecies:Special:RecentChanges|ويكي أنواع]].</center>\n</div>\n|}</div>";
    var registry = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").english_test_fixture);
    defer registry.deinit();
    // Interwiki actions require explicit site context even in a structural fixture.
    try registry.attachInterwikiMap("commons\t1\t0\t0\t0\thttps://commons.wikimedia.org/wiki/$1\n");
    var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &registry } };
    const blocks = try renderer.renderBody(try std.fmt.allocPrint(a, "{s}\n[[after]]", .{captured}));
    var tables: usize = 0;
    var after = false;
    var community = false;
    var wikimedia = false;
    for (blocks) |block| {
        try std.testing.expect(std.mem.indexOf(u8, try flattened(a, block.spans), "|}") == null);
        for (block.spans) |span| if (span.kind == .link and std.mem.eql(u8, span.target, "after")) {
            after = true;
        };
        if (block.table) |table| {
            tables += 1;
            try std.testing.expectEqual(@as(usize, 4), table.rows.len);
            try ExactCell.paint(table);
            try ExactCell.templates(table);
            for (table.rows) |row| {
                try std.testing.expectEqual(@as(usize, 2), row.cells.len);
                for (row.cells, 0..) |cell, column| {
                    const spans = try ExactCell.body(cell, column);
                    try std.testing.expect(std.mem.indexOf(u8, try flattened(a, spans), "|}") == null);
                    for (spans) |span| {
                        if (span.kind == .link and std.mem.eql(u8, span.target, "ويكاموس:بوابة المجتمع")) community = true;
                        if (span.kind == .external_link and std.mem.indexOf(u8, span.target, "commons.wikimedia.org") != null) wikimedia = true;
                    }
                }
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 1), tables);
    try std.testing.expect(after and community and wikimedia);
    try std.testing.expect(!renderer.fallbacks.malformed_table);
    // Keep the retained template bytes unchanged. The explicit declaration is
    // an independent existing alignment path for the entire typed body/codec.
    const explicit_captured = try std.mem.replaceOwned(u8, a, captured, "<center>", "<center style='text-align:center'>");
    try std.testing.expectEqual(@as(usize, 4), std.mem.count(u8, captured, "<center>"));
    stage = "top complete codec";
    try std.testing.expect((try ExactCell.parity(a, &renderer, blocks, try std.fmt.allocPrint(a, "{s}\n[[after]]", .{explicit_captured}), true)) == null);
    // A separate controlled selected Profile exercises the complete retained
    // body and its authored paint. It does not attest the real page's cascade.
    stage = "controlled selected-profile paint and complete codec";
    var selected_profile = try table_style_profile.parseAlloc(a, ""); defer selected_profile.deinit();
    var painted: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &registry, .table_styles = &selected_profile } };
    const painted_blocks = try painted.renderBody(try std.fmt.allocPrint(a, "{s}\n[[after]]", .{captured}));
    var painted_tables: usize = 0;
    for (painted_blocks) |block| if (block.table) |table| {
        painted_tables += 1;
        try ExactCell.selectedPaint(table);
        try ExactCell.templates(table);
        try std.testing.expectEqual(@as(usize, 4), table.rows.len);
        for (table.rows) |row| {
            try std.testing.expectEqual(@as(usize, 2), row.cells.len);
            for (row.cells, 0..) |cell, column| _ = try ExactCell.body(cell, column);
        }
    };
    try std.testing.expectEqual(@as(usize, 1), painted_tables);
    try std.testing.expect((try ExactCell.parity(a, &painted, painted_blocks,
        try std.fmt.allocPrint(a, "{s}\n[[after]]", .{explicit_captured}), true)) == null);
    try std.testing.expectEqualDeep(renderer.fallbacks, painted.fallbacks);
    // A separate explicitly protected source keeps both full calls as literal
    // text. It is not the captured template's evaluated output or count data.
    stage = "protected literal full codec and selected paint";
    const literal_captured = try ExactCell.literalSource(a, captured);
    const literal_top = try std.fmt.allocPrint(a, "{s}\n[[after]]", .{literal_captured});
    const unprofiled_stored = try ExactCell.literalCodec(a, renderer.context, literal_top, blocks, 1);
    const painted_stored = try ExactCell.literalCodec(a, painted.context, literal_top, painted_blocks, 1);
    // Both paths retain the same independently checked authored border. Compare
    // the entire Stored value and bytes without erasing any paint or body field.
    try std.testing.expectEqual(@as(usize, 1), painted_stored.entry.sections.len);
    var painted_literal_tables: usize = 0;
    for (painted_stored.entry.sections[0].blocks) |block| if (block.table) |table| {
        painted_literal_tables += 1;
        try std.testing.expectEqualDeep(presentation_types.TableStyle{ .border = .{ .solid = .{
            .width = .{ .unit = .px, .value = 1 }, .color = "#dfdfdf",
        } } }, table.style orelse return error.TestUnexpectedResult);
    };
    try std.testing.expectEqual(@as(usize, 1), painted_literal_tables);
    try std.testing.expectEqualDeep(unprofiled_stored, painted_stored);
    const codec = @import("blob_encoder").presentation_codec;
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, unprofiled_stored), try codec.encodeAlloc(a, painted_stored));
    // The real References caller adds a small scope and three wiki bullets
    // around the same included body; a top-level DIV alone misses this path.
    stage = "listed typed cells";
    const caller = try std.fmt.allocPrint(a, "<small>* هذه الصفحة معتمدة جزئيا أو كليا على \n* {s}\n* {s}\n* {s}\n</small>\n[[after]]", .{ captured, captured, captured });
    var listed: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &registry } };
    // The newer list/DIV heading splice must defer this wider table owner.
    // The complete caller below proves scope, actions, paint and all three tables.
    const crossing = try std.fmt.allocPrint(a, "* {s}", .{captured});
    const crossing_line_end = std.mem.indexOfScalar(u8, crossing, '\n').?;
    const crossing_tag = syntax.tagAt(captured, 0).?;
    try std.testing.expect(blockWrapperPair(captured, crossing_tag, null).?.end > syntax.matchingTag(captured, crossing_tag).?.end);
    try std.testing.expect((try listed.htmlListItemFormattingAt(crossing, 0, crossing_line_end, 2)) == null);
    for ([_][]const u8{ "**", "#" }) |other_path| {
        const other = try std.fmt.allocPrint(a, "{s} {s}", .{ other_path, captured });
        const other_line_end = std.mem.indexOfScalar(u8, other, '\n').?;
        try std.testing.expect((try listed.htmlListItemFormattingAt(other, 0, other_line_end, other_path.len + 1)) != null);
    }
    const listed_blocks = try listed.renderBody(caller);
    var listed_tables: usize = 0;
    var listed_community: usize = 0;
    var listed_commons: usize = 0;
    var listed_after = false;
    var caller_text = false;
    for (listed_blocks) |block| {
        const text = try flattened(a, block.spans);
        try std.testing.expect(std.mem.indexOf(u8, text, "|}") == null);
        caller_text = caller_text or std.mem.indexOf(u8, text, "هذه الصفحة معتمدة جزئيا أو كليا على") != null;
        for (block.spans) |span| if (span.kind == .link and std.mem.eql(u8, span.target, "after")) {
            listed_after = true;
            try std.testing.expect(!span.flags.small);
        };
        if (block.table) |table| {
            listed_tables += 1;
            try std.testing.expectEqualStrings("*", block.list_path);
            try std.testing.expectEqual(@as(usize, 4), table.rows.len);
            try ExactCell.paint(table);
            try ExactCell.templates(table);
            for (table.rows) |row| {
                try std.testing.expectEqual(@as(usize, 2), row.cells.len);
                for (row.cells, 0..) |cell, column| {
                    const spans = try ExactCell.body(cell, column);
                    try std.testing.expect(std.mem.indexOf(u8, try flattened(a, spans), "|}") == null);
                    for (spans) |span| {
                        if (span.kind == .link and std.mem.eql(u8, span.target, "ويكاموس:بوابة المجتمع")) {
                            listed_community += 1;
                            { try std.testing.expect(!span.flags.small); try std.testing.expectApproxEqAbs(@as(f32, 0.8 / 1.2), span.font_scale orelse return error.TestUnexpectedResult, 0.000001); }
                        }
                        if (span.kind == .external_link and std.mem.indexOf(u8, span.target, "commons.wikimedia.org") != null) listed_commons += 1;
                    }
                }
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 3), listed_tables);
    try std.testing.expectEqual(@as(usize, 3), listed_community);
    try std.testing.expectEqual(@as(usize, 3), listed_commons);
    try std.testing.expect(caller_text and listed_after);
    try std.testing.expect(!listed.fallbacks.malformed_table);
    stage = "listed complete codec";
    try std.testing.expect((try ExactCell.parity(a, &listed, listed_blocks, try std.mem.replaceOwned(u8, a, caller, "<center>", "<center style='text-align:center'>"), true)) == null);
    const literal_caller = try std.fmt.allocPrint(a, "<small>* هذه الصفحة معتمدة جزئيا أو كليا على \n* {s}\n* {s}\n* {s}\n</small>\n[[after]]", .{ literal_captured, literal_captured, literal_captured });
    _ = try ExactCell.literalCodec(a, listed.context, literal_caller, listed_blocks, 3);
    // A close-tag suffix cannot invent another physical wiki list boundary.
    stage = "suffix boundaries";
    var suffix: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &registry } };
    const suffix_blocks = try suffix.renderBody(try std.fmt.allocPrint(a, "* {s} # [[same-line]]\n[[tail]]", .{captured}));
    var suffix_tables: usize = 0;
    var same_line = false;
    var suffix_tail = false;
    for (suffix_blocks) |block| {
        if (block.table != null) {
            suffix_tables += 1;
            try std.testing.expectEqualStrings("*", block.list_path);
        }
        for (block.spans) |span| {
            if (span.kind == .link and std.mem.eql(u8, span.target, "same-line")) {
                same_line = true;
                try std.testing.expectEqual(Kind.paragraph, block.kind);
                try std.testing.expect(std.mem.indexOf(u8, try flattened(a, block.spans), "#") != null);
            }
            if (span.kind == .link and std.mem.eql(u8, span.target, "tail")) suffix_tail = true;
        }
    }
    try std.testing.expectEqual(@as(usize, 1), suffix_tables);
    try std.testing.expect(same_line and suffix_tail);
    stage = "suffix complete codec";
    try std.testing.expect((try ExactCell.parity(a, &suffix, suffix_blocks, try std.fmt.allocPrint(a, "* {s} # [[same-line]]\n[[tail]]", .{explicit_captured}), true)) == null);
    _ = try ExactCell.literalCodec(a, suffix.context, try std.fmt.allocPrint(a, "* {s} # [[same-line]]\n[[tail]]", .{literal_captured}), suffix_blocks, 1);
    stage = "original boundary controls";
    const controls = [_][]const u8{
        "<div>\n{|\n| <div>[[nested]]</div>\n</div>\n|}</div>\n[[tail]]",
        "<div><nowiki>\n{|\n</div>\n|}</nowiki>[[inside]]</div>[[tail]]",
        "<div>\n{|\n| [[cell]]\n</div>\n<div>[[sibling]]</div>",
        "<div>\n{|\n| [[cell]]\n</div>\n:|}</div>\n[[tail]]",
        "<div>\n: : {|\n| [[cell]]\n</div>\n|}</div>\n[[tail]]",
    };
    for (controls, 0..) |input, index| {
        const tag = syntax.tagAt(input, 0).?;
        const pair = blockWrapperPair(input, tag, null).?;
        if (index == 0) {
            try std.testing.expectEqual(std.mem.lastIndexOf(u8, input, "</div>").?, pair.inner_end);
        } else {
            const ordinary = syntax.matchingTag(input, tag).?;
            try std.testing.expectEqual(ordinary, pair);
        }
        var control: Renderer = .{ .a = a, .context = .{} };
        const rendered = try control.renderBody(input);
        var found_tail = false;
        for (rendered) |block| for (block.spans) |span| {
            if (span.kind == .link and std.mem.eql(u8, span.target, if (index == 2) "sibling" else "tail")) found_tail = true;
        };
        try std.testing.expect(found_tail);
    }
}

fn expectBalancedCompiledBidi(spans: anytype) !void {
    var stack: [64]u8 = undefined;
    var depth: usize = 0;
    for (spans) |span| {
        var offset: usize = 0;
        while (offset < span.text.len) : (offset += 1) {
            const rest = span.text[offset..];
            const isolate = starts(rest, "\xe2\x81\xa6") or starts(rest, "\xe2\x81\xa7") or starts(rest, "\xe2\x81\xa8");
            const override = starts(rest, "\xe2\x80\xad") or starts(rest, "\xe2\x80\xae");
            const pdi = starts(rest, "\xe2\x81\xa9");
            const pdf = starts(rest, "\xe2\x80\xac");
            if (isolate or override) {
                try std.testing.expect(depth < stack.len);
                stack[depth] = if (isolate) 1 else 2;
                depth += 1;
            } else if (pdi or pdf) {
                try std.testing.expect(depth != 0);
                depth -= 1;
                try std.testing.expectEqual(@as(u8, if (pdi) 1 else 2), stack[depth]);
            } else if (Renderer.bidiSeparatorLength(rest) != 0) try std.testing.expectEqual(@as(usize, 0), depth);
            if (isolate or override or pdi or pdf) {
                try std.testing.expect(span.kind == .text and span.target.len == 0 and span.direction.len == 0 and span.explanation.len == 0);
                offset += 2;
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 0), depth);
}

test "compiled bidi scopes retain overrides across styled actions and default auto nesting" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    const spans = try r.parseSpans("before <bdo dir=rtl lang=he>a<b>b</b>[[C|c]]</bdo> after [[Tail]]", .{ .direction = "ltr" });
    try std.testing.expectEqualStrings("before \u{2067}\u{202e}abc\u{202c}\u{2069} after Tail", try flattened(a, spans));
    try expectBalancedCompiledBidi(spans);
    var bold = false;
    var link = false;
    var tail = false;
    for (spans) |span| {
        if (std.mem.eql(u8, span.text, "b")) bold = span.flags.bold and std.mem.eql(u8, span.language, "he") and span.direction.len == 0;
        if (span.kind == .link and std.mem.eql(u8, span.target, "C")) link = std.mem.eql(u8, span.text, "c") and std.mem.eql(u8, span.language, "he") and span.direction.len == 0;
        if (span.kind == .link and std.mem.eql(u8, span.target, "Tail")) tail = std.mem.eql(u8, span.direction, "ltr");
    }
    try std.testing.expect(bold and link and tail);
    const nested = try r.parseSpans("<bdi>a<bdo dir=ltr>אב</bdo>z</bdi>", .{ .direction = "rtl" });
    try std.testing.expectEqualStrings("\u{2066}a\u{2066}\u{202d}אב\u{202c}\u{2069}z\u{2069}", try flattened(a, nested));
    try expectBalancedCompiledBidi(nested);
    const child = try r.parseSpans("<bdo dir=rtl>a<span dir=ltr>b<b>c</b>[[D|d]]</span>e</bdo>", .{});
    try std.testing.expectEqualStrings("\u{2067}\u{202e}a\u{2066}bcd\u{2069}e\u{202c}\u{2069}", try flattened(a, child));
    try expectBalancedCompiledBidi(child);
    try std.testing.expect(unclosedExternalRecoveryHasLink(child, .link, "D"));
    const empty = try r.parseSpans("<bdi></bdi>tail", .{});
    try std.testing.expectEqualStrings("tail", try flattened(a, empty));
    try std.testing.expect(!r.fallbacks.any());
    const auto_cases = [_]struct { source: []const u8, expected: []const u8 }{
        .{ .source = "<bdi>A<br>א</bdi>", .expected = "\u{2066}A\u{2069}\n\u{2066}א\u{2069}" },
        .{ .source = "<bdi>א<br>A</bdi>", .expected = "\u{2067}א\u{2069}\n\u{2067}A\u{2069}" },
        .{ .source = "<bdi>123 !</bdi>", .expected = "\u{2066}123 !\u{2069}" },
        .{ .source = "<bdi><bdi>א</bdi>A</bdi>", .expected = "\u{2066}\u{2067}א\u{2069}A\u{2069}" },
        .{ .source = "<bdi>א<span dir=ltr>A</span>B</bdi>", .expected = "\u{2067}א\u{2066}A\u{2069}B\u{2069}" },
        .{ .source = "<bdi><span dir=invalid>א</span>A</bdi>", .expected = "\u{2067}אA\u{2069}" },
        .{ .source = "<bdi>&#x5d0;A</bdi>", .expected = "\u{2067}אA\u{2069}" },
        .{ .source = "<bdi>&amp;#x5d0;א</bdi>", .expected = "\u{2066}&#x5d0;א\u{2069}" },
        .{ .source = "<bdi>[[File:Example.jpg|thumb|<bdi>א</bdi>A]]</bdi>", .expected = "\u{2066}\u{2067}א\u{2069}A\u{2069}" },
        .{ .source = "<bdi>[[File:Example.jpg|thumb|<bdi>A</bdi>א]]</bdi>", .expected = "\u{2067}\u{2066}A\u{2069}א\u{2069}" },
        .{ .source = "<bdi>[[English target|א]]A</bdi>", .expected = "\u{2067}אA\u{2069}" },
        .{ .source = "<bdi>\u{2068}א\u{2069}A</bdi>", .expected = "\u{2067}\u{2068}א\u{2069}A\u{2069}" },
        .{ .source = "<bdi>&#x200f;A</bdi>", .expected = "\u{2067}\u{200f}A\u{2069}" },
        .{ .source = "<bdi>&#x061c;A</bdi>", .expected = "\u{2067}\u{061c}A\u{2069}" },
        .{ .source = "<bdi>&#x200e;א</bdi>", .expected = "\u{2066}\u{200e}א\u{2069}" },
    };
    for (auto_cases) |case| {
        if (std.mem.indexOf(u8, case.source, "[[File:") != null) {
            const owned = try FigureProducerTest.scopeFigure(a, case.source);
            try std.testing.expectEqual(if (starts(case.expected, "\u{2067}")) presentation_types.BidiResolvedDirection.rtl else .ltr, owned.scope.resolved_direction);
            try std.testing.expect(owned.scope.mode == .isolate and owned.scope.authored_direction == null);
            // Keep the old complete scope/text trace as an independent oracle;
            // generated boundaries now belong to typed owners, not caption runs.
            try std.testing.expectEqualStrings(case.expected, try FigureProducerTest.scopeTrace(a, owned.scope));
            try std.testing.expect(owned.figure.caption.len == 0 and owned.figure.caption_blocks != null);
            continue;
        }
        const result = try r.parseSpans(case.source, .{ .direction = "rtl" });
        try std.testing.expectEqualStrings(case.expected, try flattened(a, result));
        try expectBalancedCompiledBidi(result);
    }
    // Authored controls stay in the visible caption. The image owns the File
    // action independently, as in the source figure/caption construction.
    const authored = try FigureProducerTest.scopeFigure(a, "<bdi>[[File:Example.jpg|thumb|\u{2068}א\u{2069}A]]</bdi>");
    try std.testing.expect(authored.scope.resolved_direction == .rtl);
    try std.testing.expectEqualStrings("\u{2068}א\u{2069}A", try flattened(a, authored.figure.caption));
    var authored_text = false;
    for (authored.figure.caption) |span| {
        try std.testing.expect(!span.generated_bidi_boundary);
        if (span.text.len != 0) {
            try std.testing.expectEqualStrings("\u{2068}א\u{2069}A", span.text);
            try std.testing.expect(span.kind == .text and span.target.len == 0);
            authored_text = true;
        }
    }
    try std.testing.expect(authored_text);
    try std.testing.expectEqualStrings("File:Example.jpg", authored.figure.content.image.span.target);
    for ([_][]const u8{ "script", "style", "textarea" }) |tag| {
        const source = try std.fmt.allocPrint(a, "<bdi><{s}>A</{s}>א</bdi>", .{ tag, tag });
        const result = try r.parseSpans(source, .{});
        try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "\u{2067}<{s}>A</{s}>א\u{2069}", .{ tag, tag }), try flattened(a, result));
        try expectBalancedCompiledBidi(result);
    }
}

test "compiled bidi scopes keep protected source literal and remain balanced at normal limits" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const literal = "<bdo dir=rtl>abc</bdo>";
    for ([_][]const u8{ "nowiki", "source", "syntaxhighlight", "pre" }) |tag| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const spans = try r.parseSpans(try std.fmt.allocPrint(a, "<{s}>{s}</{s}> [[Tail]]", .{ tag, literal, tag }), .{});
        try std.testing.expectEqualStrings(literal ++ " Tail", try flattened(a, spans));
        try std.testing.expect(unclosedExternalRecoveryHasLink(spans, .link, "Tail"));
    }
    var escaped: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectEqualStrings("<bdi>plain</bdi>", try flattened(a, try escaped.parseSpans("&lt;bdi&gt;plain&lt;/bdi&gt;", .{})));
    // Exercise the ordinary emission-budget seam with one existing child, not
    // a large input: no generated opener may survive without its closer.
    var limited: Renderer = .{ .a = a, .context = .{} };
    try limited.spans.append(a, .{ .text = "abc", .kind = .link, .target = "A" });
    limited.nodes = max_nodes - 1;
    try limited.wrapBidiSpans(0, .{ .opening = "\xe2\x81\xa7\xe2\x80\xae", .closing = "\xe2\x80\xac\xe2\x81\xa9" });
    try std.testing.expect(limited.fallbacks.render_limit);
    try std.testing.expectEqualStrings("abc", try flattened(a, limited.spans.items));
    try std.testing.expectEqualStrings("A", limited.spans.items[0].target);
    try expectBalancedCompiledBidi(limited.spans.items);
}

test "compiled bidi scopes close within paragraph Poem pre and table cell domains through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    const broken = try r.parseSpans("<bdo dir=rtl>a<br>b</bdo> [[Tail]]", .{});
    try std.testing.expectEqualStrings("\u{2067}\u{202e}a\u{202c}\u{2069}\n\u{2067}\u{202e}b\u{202c}\u{2069} Tail", try flattened(a, broken));
    try expectBalancedCompiledBidi(broken);
    var poem: Renderer = .{ .a = a, .context = .{} };
    const poem_spans = try poem.parseSpans("<poem><bdo dir=rtl>a\nb</bdo></poem> [[Outside]]", .{});
    try expectBalancedCompiledBidi(poem_spans);
    const poem_text = try flattened(a, poem_spans);
    try std.testing.expect(std.mem.indexOf(u8, poem_text, "\u{2067}\u{202e}a\u{202c}\u{2069}\n\u{2067}\u{202e}b\u{202c}\u{2069}") != null);
    try std.testing.expect(unclosedExternalRecoveryHasLink(poem_spans, .link, "Outside"));
    for (poem_spans) |span| {
        if (std.mem.indexOf(u8, span.text, "\u{2067}") != null or std.mem.indexOf(u8, span.text, "\u{202c}") != null)
            try std.testing.expect(std.mem.indexOf(u8, span.classes, "wikidict-poem") != null);
    }
    var pre: Renderer = .{ .a = a, .context = .{} };
    pre.parsed_pre = true;
    const pre_spans = try pre.parseSpans("<bdi>A\nא</bdi>", .{});
    try std.testing.expectEqualStrings("\u{2066}A\u{2069}\n\u{2066}א\u{2069}", try flattened(a, pre_spans));
    try expectBalancedCompiledBidi(pre_spans);
    var leading: Renderer = .{ .a = a, .context = .{} };
    const leading_blocks = try leading.renderBody(" <bdi>abc</bdi>\n");
    try std.testing.expectEqual(@as(usize, 1), leading_blocks.len);
    try std.testing.expectEqual(Kind.preformatted, leading_blocks[0].kind);
    try std.testing.expectEqualStrings("\u{2066}abc\u{2069}", try flattened(a, leading_blocks[0].spans));
    try expectBalancedCompiledBidi(leading_blocks[0].spans);
    var body: Renderer = .{ .a = a, .context = .{} };
    const blocks = try body.renderBody("first <bdi>abc</bdi>\n\nnext [[Tail]]\n<table><tr><th><bdo dir=rtl>row</bdo></th><td><bdi lang=he>[[Cell|אב]]</bdi></td></tr></table>");
    var table_seen = false;
    for (blocks) |block_value| {
        try expectBalancedCompiledBidi(block_value.spans);
        if (block_value.table) |table| {
            table_seen = true;
            try std.testing.expect(table.rows[0].cells[0].header);
            try std.testing.expectEqualStrings("\u{2067}\u{202e}row\u{202c}\u{2069}", try flattened(a, table.rows[0].cells[0].spans));
            try std.testing.expectEqualStrings("\u{2067}אב\u{2069}", try flattened(a, table.rows[0].cells[1].spans));
            for (table.rows) |row| for (row.cells) |cell| try expectBalancedCompiledBidi(cell.spans);
            try std.testing.expect(unclosedExternalRecoveryHasLink(table.rows[0].cells[1].spans, .link, "Cell"));
        }
    }
    try std.testing.expect(table_seen);
    const Section = struct { level: u8 = 2, title: []const u8 = "English", blocks: []const Block };
    const blob = @import("blob_encoder");
    const bytes = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &[_]Section{.{ .blocks = blocks }}, blob.presentation_types.Layout{}, body.refs.items, body.media.items);
    const decoded = try blob.presentation_codec.decodeAlloc(a, bytes, "bidi scopes", .language, .{ .code = "en", .heading = "English" });
    // Exact typed wire equality detects missing controls, actions, layout
    // classes and flags; balance alone would also accept an empty result.
    try std.testing.expectEqualSlices(u8, bytes, try blob.presentation_codec.encodeAlloc(a, decoded));
    for (decoded.entry.sections[0].blocks) |block_value| {
        try expectBalancedCompiledBidi(block_value.spans);
        if (block_value.table) |table| for (table.rows) |row| for (row.cells) |cell| try expectBalancedCompiledBidi(cell.spans);
    }
}

