    const items = [_]PoemPhaseItem{
        .{ .token = scope, .kind = .scope },
        .{ .token = token, .kind = .literal, .tag = "poem", .body = original_body },
    };
    const wire = try poemPhaseTestRecord(a, source, "", &items);
