    const unknown = "|<unknown title='a||b'>text</unknown>||tail";
    try std.testing.expectEqual(std.mem.indexOf(u8, unknown, "||").?, Renderer.wikiCellDelimiter(unknown, "||", 1).?);
    const attr = "|title='a||b'|text||tail";
