test "wiki row font styles reach owned cells and respect local normal overrides" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    const blocks = try r.renderBody("{|\n|+ [[Caption]]\n|- style='font-weight:bold; font-style:italic'\n| [[N|Nominatief]]\n| form<div>roman</div>\n| style='font-weight:normal; font-style:normal' | [[Reset]] <b>Strong</b>\n| <span style='font-weight:normal; font-style:normal'>[[Child]]</span> [[Restored]]\n|-\n| [[Following]]\n|}\n[[Outside]]");
    const cases = [_]struct { text: []const u8, bold: bool, italic: bool, target: []const u8 = "" }{
        .{ .text = "Nominatief", .bold = true, .italic = true, .target = "N" },
        .{ .text = "form", .bold = true, .italic = true },
        .{ .text = "roman", .bold = true, .italic = true },
        .{ .text = "Reset", .bold = false, .italic = false, .target = "Reset" },
        .{ .text = "Strong", .bold = true, .italic = false },
        .{ .text = "Child", .bold = false, .italic = false, .target = "Child" },
        .{ .text = "Restored", .bold = true, .italic = true, .target = "Restored" },
        .{ .text = "Following", .bold = false, .italic = false, .target = "Following" },
    };
    var seen: [cases.len]bool = @splat(false);
    var table_found = false;
    var outside_found = false;
    for (blocks) |b| {
        if (b.table) |table| {
            table_found = true;
            try std.testing.expectEqual(@as(usize, 2), table.rows.len);
            try std.testing.expectEqual(@as(usize, 4), table.rows[0].cells.len);
            try std.testing.expectEqual(@as(usize, 1), table.rows[1].cells.len);
            var caption_found = false;
            for (table.caption) |value| if (std.mem.eql(u8, value.target, "Caption")) {
                caption_found = true;
                try std.testing.expect(!value.flags.bold and !value.flags.italic);
            };
            try std.testing.expect(caption_found);
            for (table.rows) |row| for (row.cells) |cell| for (cell.spans) |value| {
                for (cases, 0..) |case, i| if (std.mem.eql(u8, trim(value.text), case.text)) {
                    seen[i] = true;
                    try std.testing.expectEqual(case.bold, value.flags.bold);
                    try std.testing.expectEqual(case.italic, value.flags.italic);
                    try std.testing.expectEqualStrings(case.target, value.target);
                };
            };
        }
        for (b.spans) |value| if (std.mem.eql(u8, value.target, "Outside")) {
            outside_found = true;
            try std.testing.expect(!value.flags.bold and !value.flags.italic);
        };
    }
    try std.testing.expect(table_found and outside_found);
    for (seen) |found| try std.testing.expect(found);
    // The stored DPR2 path must retain the same new row inheritance and
    // explicit normal overrides; this is not only an in-memory renderer check.
    const stored = try FormattingScopeTest.encode(a, &r, blocks);
    const decoded = stored.entry.sections[0].blocks;
    var decoded_seen: [cases.len]bool = @splat(false);
    var decoded_table_found = false;
    for (decoded) |b| if (b.table) |table| {
        decoded_table_found = true;
        try std.testing.expectEqual(@as(usize, 2), table.rows.len);
        try std.testing.expectEqual(@as(usize, 4), table.rows[0].cells.len);
        try std.testing.expectEqual(@as(usize, 1), table.rows[1].cells.len);
        for (table.rows) |row| for (row.cells) |cell| for (cell.spans) |value| {
            for (cases, 0..) |case, i| if (std.mem.eql(u8, trim(value.text), case.text)) {
                decoded_seen[i] = true;
                try std.testing.expectEqual(case.bold, value.bold);
                try std.testing.expectEqual(case.italic, value.italic);
                try std.testing.expectEqualStrings(case.target, value.target);
            };
        };
    };
    try std.testing.expect(decoded_table_found);
    for (decoded_seen) |found| try std.testing.expect(found);
    try std.testing.expect(!r.block_formatting.bold and !r.block_formatting.italic);
}

test "wiki row font scope preserves nested overrides and excludes fostered caption and sibling text" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    const blocks = try r.renderBody("{|\n[[Fostered]]\n|+ [[Caption]]\n|- style='font-weight:bold; font-style:italic'\n| [[Outer]]\n{|\n|- style='font-weight:normal; font-style:normal'\n| [[NestedReset]] <b>NestedStrong</b>\n|-\n| [[NestedInherited]]\n|}\n[[OuterRestored]]\n|- style='font-weight:normal; font-style:normal'\n| [[Sibling]]\n|}\n[[After]]");
    const cases = [_]struct { text: []const u8, bold: bool, italic: bool }{
        .{ .text = "Outer", .bold = true, .italic = true },
        .{ .text = "NestedReset", .bold = false, .italic = false },
        .{ .text = "NestedStrong", .bold = true, .italic = false },
        .{ .text = "NestedInherited", .bold = true, .italic = true },
        .{ .text = "OuterRestored", .bold = true, .italic = true },
        .{ .text = "Sibling", .bold = false, .italic = false },
    };
    var seen: [cases.len]bool = @splat(false);
    var fostered = false;
    var caption = false;
    var after = false;
    for (blocks) |b| {
        for (b.spans) |value| {
            if (std.mem.eql(u8, value.target, "Fostered")) fostered = true else if (std.mem.eql(u8, value.target, "After")) after = true else continue;
            try std.testing.expect(!value.flags.bold and !value.flags.italic);
        }
        if (b.table) |table| {
            try std.testing.expectEqual(@as(usize, 2), table.rows.len);
            for (table.caption) |value| if (std.mem.eql(u8, value.target, "Caption")) {
                caption = true;
                try std.testing.expect(!value.flags.bold and !value.flags.italic);
            };
            for (table.rows) |row| for (row.cells) |cell| {
                var projection: Renderer = .{ .a = a, .context = .{} };
                const values = if (cell.blocks) |ordered| projected: {
                    try projection.blocksInline(ordered, .{});
                    break :projected projection.spans.items;
                } else cell.spans;
                for (values) |value| for (cases, 0..) |case, i| if (std.mem.eql(u8, trim(value.text), case.text)) {
                    seen[i] = true;
                    try std.testing.expectEqual(case.bold, value.flags.bold);
                    try std.testing.expectEqual(case.italic, value.flags.italic);
                    if (!std.mem.eql(u8, case.text, "NestedStrong")) try std.testing.expectEqualStrings(case.text, value.target);
                };
            };
        }
    }
    try std.testing.expect(fostered and caption and after);
    for (seen) |found| try std.testing.expect(found);
    try std.testing.expect(!r.block_formatting.bold and !r.block_formatting.italic);
}

const ChemicalScriptStackTest = struct {
    const outer = "font-size:80%; display:-moz-inline-box; -moz-box-orient:vertical; display:inline-block; vertical-align: bottom; /*Horizontal positioning, affects IE&FF*/margin-bottom:-0.4em; min-height:1em; line-height:1em; ";
    const upper = "display:block; min-height:1em; /*Horizontal positioning, affects IE only*/margin-top:-1.4em;";
    const lower = "display:block; min-height:1em;";

    fn source(a: A, charge: []const u8, count: []const u8) ![]const u8 {
        return std.fmt.allocPrint(a, "<SPAN style=\"{s}\"><SPAN style=\"{s}\">{s}</SPAN><SPAN style=\"{s}\">{s}</SPAN></SPAN>", .{ outer, upper, charge, lower, count });
    }

    fn scripts(spans: anytype, count: []const u8, charge: []const u8, inherited: Style) !void {
        var counts: usize = 0;
        var charges: usize = 0;
        for (spans) |item| {
            const sub = if (@hasField(@TypeOf(item), "flags")) item.flags.subscript else item.subscript;
            const super = if (@hasField(@TypeOf(item), "flags")) item.flags.superscript else item.superscript;
            if (!sub and !super) continue;
            try std.testing.expect(sub != super);
            if (sub) {
                try std.testing.expectEqual(@as(usize, 0), charges);
                try std.testing.expectEqualStrings(count, item.text);
                counts += 1;
            } else {
                try std.testing.expectEqual(@as(usize, 1), counts);
                try std.testing.expectEqualStrings(charge, item.text);
                charges += 1;
            }
            try std.testing.expectEqualStrings("text", @tagName(item.kind));
            try std.testing.expectEqualStrings("", item.target);
            try std.testing.expectEqualStrings(inherited.language, item.language);
            try std.testing.expectEqualStrings(inherited.direction, item.direction);
            try std.testing.expectEqualStrings(inherited.classes, item.classes);
            try std.testing.expectEqualStrings(inherited.explanation, item.explanation);
            try std.testing.expectEqualStrings(@tagName(inherited.role), @tagName(item.role));
            try std.testing.expectEqual(inherited.bold, if (@hasField(@TypeOf(item), "flags")) item.flags.bold else item.bold);
            try std.testing.expectEqual(inherited.italic, if (@hasField(@TypeOf(item), "flags")) item.flags.italic else item.italic);
            try std.testing.expectEqual(inherited.small, if (@hasField(@TypeOf(item), "flags")) item.flags.small else item.small);
            try std.testing.expectEqual(inherited.code, if (@hasField(@TypeOf(item), "flags")) item.flags.code else item.code);
            try std.testing.expectEqual(inherited.underline, if (@hasField(@TypeOf(item), "flags")) item.flags.underline else item.underline);
            try std.testing.expectEqual(inherited.strike, if (@hasField(@TypeOf(item), "flags")) item.flags.strike else item.strike);
        }
        try std.testing.expectEqual(@as(usize, 1), counts);
        try std.testing.expectEqual(@as(usize, 1), charges);
    }

    fn unscripted(spans: anytype) !void {
        for (spans) |item| {
            try std.testing.expect(!(if (@hasField(@TypeOf(item), "flags")) item.flags.subscript else item.subscript));
            try std.testing.expect(!(if (@hasField(@TypeOf(item), "flags")) item.flags.superscript else item.superscript));
        }
    }
};

test "captured chemical Su count and charge retain canonical scripts through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { count: []const u8, charge: []const u8 }{
        .{ .count = "4", .charge = "4−" },
        .{ .count = "12", .charge = "3+" },
        .{ .count = "2", .charge = "−" },
        .{ .count = "10", .charge = "2-" },
    };
    for (cases) |case| {
        // Exact retained Su both-arguments branch: w=70% still emits 80%.
        // Source top-before-bottom CSS geometry becomes conventional chemical
        // count-below then charge-above linear order, not a pixel stack claim.
        const stack = try ChemicalScriptStackTest.source(a, case.charge, case.count);
        const source = try std.fmt.allocPrint(a, "<b><i><span class=\"chemf\" lang=\"af\">SiO{s}</span></i></b> tail [[Target|next]]", .{stack});
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(source);
        const visible = try std.fmt.allocPrint(a, "SiO{s}{s} tail next", .{ case.count, case.charge });
        try FormattingScopeTest.shapes(a, blocks, &.{"paragraph"}, &.{visible});
        const inherited: Style = .{ .bold = true, .italic = true, .classes = "chemf", .language = "af" };
        try ChemicalScriptStackTest.scripts(blocks[0].spans, case.count, case.charge, inherited);
        try FormattingScopeTest.word(a, blocks, "SiO", inherited);
        try FormattingScopeTest.word(a, blocks, "tail", .{});
        try FormattingScopeTest.word(a, blocks, "next", .{ .kind = .link, .target = "Target" });
        const stored = try FormattingScopeTest.encode(a, &renderer, blocks);
        try FormattingScopeTest.shapes(a, stored.entry.sections[0].blocks, &.{"paragraph"}, &.{visible});
        try ChemicalScriptStackTest.scripts(stored.entry.sections[0].blocks[0].spans, case.count, case.charge, inherited);
        try FormattingScopeTest.word(a, stored.entry.sections[0].blocks, "tail", .{});
        try FormattingScopeTest.word(a, stored.entry.sections[0].blocks, "next", .{ .kind = .link, .target = "Target" });
        try std.testing.expect(!renderer.fallbacks.any());
    }
    // Exercise inherited direction/role/explanation and every non-script flag
    // on the actual inline API, independently of explicit HTML bidi isolation.
    const stack = try ChemicalScriptStackTest.source(a, "4−", "4");
    const source = try std.fmt.allocPrint(a, "SiO{s}", .{stack});
    const inherited: Style = .{ .bold = true, .italic = true, .small = true, .code = true, .underline = true, .strike = true, .classes = "chemf inherited", .language = "af", .direction = "rtl", .role = .label, .explanation = "chemical count and charge", .explanation_set = true };
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const spans = try renderer.parseSpans(source, inherited);
    try std.testing.expectEqualStrings("SiO44−", try FormattingScopeTest.text(a, spans));
    try ChemicalScriptStackTest.scripts(spans, "4", "4−", inherited);
    const blocks = [_]Block{.{ .kind = .paragraph, .spans = spans }};
    const stored = try FormattingScopeTest.encode(a, &renderer, &blocks);
    try ChemicalScriptStackTest.scripts(stored.entry.sections[0].blocks[0].spans, "4", "4−", inherited);
    const after = try renderer.parseSpans("outside", .{});
    try ChemicalScriptStackTest.unscripted(after);
    try std.testing.expectEqualStrings("", after[0].classes);
    try std.testing.expectEqualStrings("", after[0].language);
    try std.testing.expectEqualStrings("", after[0].direction);
}

test "chemical Su conversion refuses actions arbitrary layouts and nested script bodies" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const exact = try ChemicalScriptStackTest.source(a, "4−", "4");
    const altered_at = std.mem.indexOf(u8, exact, "margin-top:-1.4em").?;
    const altered = try std.fmt.allocPrint(a, "{s}margin-top:-1.2em{s}", .{ exact[0..altered_at], exact[altered_at + "margin-top:-1.4em".len ..] });
    const cases = [_]struct { stack: []const u8, chemical: bool = true, visible: []const u8 }{
        .{ .stack = exact, .chemical = false, .visible = "SiO4−4" },
        .{ .stack = altered, .visible = "SiO4−4" },
        .{ .stack = try ChemicalScriptStackTest.source(a, "[[Charge|4−]]", "4"), .visible = "SiO4−4" },
        .{ .stack = try ChemicalScriptStackTest.source(a, "<span>4−</span>", "4"), .visible = "SiO4−4" },
        .{ .stack = try ChemicalScriptStackTest.source(a, "<nowiki>4−</nowiki>", "4"), .visible = "SiO4−4" },
        .{ .stack = try ChemicalScriptStackTest.source(a, "4−", "four"), .visible = "SiO4−four" },
        .{ .stack = try ChemicalScriptStackTest.source(a, "4", "4"), .visible = "SiO44" },
        .{ .stack = try ChemicalScriptStackTest.source(a, "", "4"), .visible = "SiO4" },
        .{ .stack = try ChemicalScriptStackTest.source(a, "4−", " 4"), .visible = "SiO4− 4" },
    };
    for (cases) |case| {
        const source = if (case.chemical) try std.fmt.allocPrint(a, "<span class=\"chemf\">SiO{s}</span>", .{case.stack}) else try std.fmt.allocPrint(a, "SiO{s}", .{case.stack});
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(source, .{});
        try std.testing.expectEqualStrings(case.visible, try FormattingScopeTest.text(a, spans));
        try ChemicalScriptStackTest.unscripted(spans);
    }
    // The action is not flattened, moved to a different target, or discarded.
    const linked = try ChemicalScriptStackTest.source(a, "[[Charge|4−]]", "4");
    var actions: Renderer = .{ .a = a, .context = .{} };
    const action_spans = try actions.parseSpans(try std.fmt.allocPrint(a, "<span class=\"chemf\">SiO{s}</span>", .{linked}), .{});
    var action_seen = false;
    for (action_spans) |item| if (item.kind == .link) {
        try std.testing.expectEqualStrings("Charge", item.target);
        try std.testing.expectEqualStrings("4−", item.text);
        action_seen = true;
    };
    try std.testing.expect(action_seen);
    const media = try ChemicalScriptStackTest.source(a, "[[File:Charge.png|4−]]", "4");
    var images: Renderer = .{ .a = a, .context = .{} };
    const image_spans = try images.parseSpans(try std.fmt.allocPrint(a, "<span class=\"chemf\">SiO{s}</span>", .{media}), .{});
    try ChemicalScriptStackTest.unscripted(image_spans);
    var inline_image_count: usize = 0;
    for (image_spans) |span| if (span.image) |image| {
        inline_image_count += 1;
        try std.testing.expectEqualStrings("Charge.png", image.file);
        try std.testing.expectEqualStrings("4−", image.alt.?);
        try std.testing.expectEqualStrings("4−", image.tooltip.?);
        try std.testing.expectEqualStrings("File:Charge.png", span.target);
        try std.testing.expect(span.text.len == 0 and !span.flags.superscript and !span.flags.subscript);
    };
    try std.testing.expectEqual(@as(usize, 1), inline_image_count);
    try std.testing.expectEqual(@as(usize, 1), images.media.items.len);
    try std.testing.expectEqualStrings("Charge.png", images.media.items[0].file);
    // Existing action/script scopes decline rather than changing their meaning.
    for ([_]Style{
        .{ .classes = "chemf", .kind = .link, .target = "Holder" },
        .{ .classes = "chemf", .superscript = true },
        .{ .classes = "chemf", .subscript = true },
    }) |inherited| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(try std.fmt.allocPrint(a, "SiO{s}", .{exact}), inherited);
        try std.testing.expectEqualStrings("SiO4−4", try FormattingScopeTest.text(a, spans));
        for (spans) |item| {
            try std.testing.expectEqual(inherited.kind, item.kind);
            try std.testing.expectEqualStrings(inherited.target, item.target);
            try std.testing.expectEqual(inherited.superscript, item.flags.superscript);
            try std.testing.expectEqual(inherited.subscript, item.flags.subscript);
        }
    }
    var unclosed: Renderer = .{ .a = a, .context = .{} };
    const open_source = try std.fmt.allocPrint(a, "SiO{s}", .{exact[0 .. exact.len - "</SPAN>".len]});
    const open_spans = try unclosed.parseSpans(open_source, .{ .classes = "chemf" });
    try std.testing.expectEqualStrings("SiO4−4", try FormattingScopeTest.text(a, open_spans));
    try ChemicalScriptStackTest.unscripted(open_spans);
    try std.testing.expect(unclosed.fallbacks.unclosed_formatting);
}

test "captured chem2 paired class preserves canonical count charge and scope through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { charge: []const u8, count: []const u8, decoded_charge: []const u8 }{
        .{ .charge = "−", .count = "2", .decoded_charge = "−" },
        .{ .charge = "3+", .count = "12", .decoded_charge = "3+" },
        .{ .charge = "4&#8722;", .count = "4", .decoded_charge = "4−" },
    };
    for (cases) |case| {
        // Exact paired emitter: upper charge first, lower count second.
        const source = try std.fmt.allocPrint(a, "<span class=\"template-chem2-su\"><span>{s}</span><span>{s}</span></span>", .{ case.charge, case.count });
        const inherited: Style = .{ .bold = true, .italic = true, .small = true, .code = true, .underline = true, .strike = true, .classes = "chemf nowrap", .language = "en", .direction = "rtl", .role = .label, .explanation = "chemical count and charge", .explanation_set = true };
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(source, inherited);
        var expected = inherited;
        expected.classes = "chemf nowrap template-chem2-su";
        try ChemicalScriptStackTest.scripts(spans, case.count, case.decoded_charge, expected);
        const visible = try std.fmt.allocPrint(a, "{s}{s}", .{ case.count, case.decoded_charge });
        try std.testing.expectEqualStrings(visible, try FormattingScopeTest.text(a, spans));
        const blocks = [_]Block{.{ .kind = .paragraph, .spans = spans }};
        const stored = try FormattingScopeTest.encode(a, &renderer, &blocks);
        try ChemicalScriptStackTest.scripts(stored.entry.sections[0].blocks[0].spans, case.count, case.decoded_charge, expected);
        const after = try renderer.parseSpans("outside [[Target|next]]", .{});
        try ChemicalScriptStackTest.unscripted(after);
        var action = false;
        for (after) |span| if (span.kind == .link) {
            try std.testing.expectEqualStrings("Target", span.target);
            try std.testing.expectEqualStrings("next", span.text);
            try std.testing.expectEqualStrings("", span.classes);
            action = true;
        };
        try std.testing.expect(action);
        try std.testing.expect(!renderer.fallbacks.any());
    }
    const exact = "<span class=\"template-chem2-su\"><span>−</span><span>2</span></span>";
    const declined = [_][]const u8{
        "<span class=\"template-chem2-su extra\"><span>−</span><span>2</span></span>",
        "<span class=\"template-chem2-su\" style=\"color:red\"><span>−</span><span>2</span></span>",
        "<span class=\"template-chem2-su\"><span title=\"charge\">−</span><span>2</span></span>",
        "<span class=\"template-chem2-su\"><span><span>−</span></span><span>2</span></span>",
        "<span class=\"template-chem2-su\"><span>−</span><span>2</span><span>x</span></span>",
        "<span class=\"template-chem2-su\"><span>4</span><span>2</span></span>",
        "<span class=\"template-chem2-su\"><span>−</span><span>two</span></span>",
    };
    for (declined) |source| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        try ChemicalScriptStackTest.unscripted(try renderer.parseSpans(source, .{ .classes = "chemf" }));
    }
    var plain: Renderer = .{ .a = a, .context = .{} };
    const plain_spans = try plain.parseSpans(exact, .{});
    try std.testing.expectEqualStrings("−2", try FormattingScopeTest.text(a, plain_spans));
    try ChemicalScriptStackTest.unscripted(plain_spans);
    for ([_]Style{
        .{ .classes = "chemf", .kind = .link, .target = "Holder" },
        .{ .classes = "chemf", .superscript = true },
        .{ .classes = "chemf", .subscript = true },
    }) |inherited| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(exact, inherited);
        try std.testing.expectEqualStrings("−2", try FormattingScopeTest.text(a, spans));
        for (spans) |span| {
            try std.testing.expectEqual(inherited.kind, span.kind);
            try std.testing.expectEqualStrings(inherited.target, span.target);
            try std.testing.expectEqual(inherited.superscript, span.flags.superscript);
            try std.testing.expectEqual(inherited.subscript, span.flags.subscript);
        }
    }
    var actions: Renderer = .{ .a = a, .context = .{} };
    const linked = try actions.parseSpans("<span class=\"template-chem2-su\"><span>[[Charge|−]]</span><span>2</span></span>", .{ .classes = "chemf" });
    try ChemicalScriptStackTest.unscripted(linked);
    var seen = false;
    for (linked) |span| if (span.kind == .link) {
        try std.testing.expectEqualStrings("Charge", span.target);
        try std.testing.expectEqualStrings("−", span.text);
        seen = true;
    };
    try std.testing.expect(seen);
    var images: Renderer = .{ .a = a, .context = .{} };
    const media = try images.parseSpans("<span class=\"template-chem2-su\"><span>[[File:Charge.png|−]]</span><span>2</span></span>", .{ .classes = "chemf" });
    try ChemicalScriptStackTest.unscripted(media);
    var inline_image_count: usize = 0;
    for (media) |span| if (span.image) |image| {
        inline_image_count += 1;
        try std.testing.expectEqualStrings("Charge.png", image.file);
        try std.testing.expectEqualStrings("−", image.alt.?);
        try std.testing.expectEqualStrings("−", image.tooltip.?);
        try std.testing.expectEqualStrings("File:Charge.png", span.target);
        try std.testing.expect(span.text.len == 0 and !span.flags.superscript and !span.flags.subscript);
    };
    try std.testing.expectEqual(@as(usize, 1), inline_image_count);
    try std.testing.expectEqual(@as(usize, 1), images.media.items.len);
    try std.testing.expectEqualStrings("Charge.png", images.media.items[0].file);
    var unclosed: Renderer = .{ .a = a, .context = .{} };
    const open = try unclosed.parseSpans(exact[0 .. exact.len - "</span>".len], .{ .classes = "chemf" });
    try std.testing.expectEqualStrings("−2", try FormattingScopeTest.text(a, open));
    try ChemicalScriptStackTest.unscripted(open);
    try std.testing.expect(unclosed.fallbacks.unclosed_formatting);
    // The existing one-sided HTML scripts retain their authored order and roles.
    var single: Renderer = .{ .a = a, .context = .{} };
    const one_sided = try single.renderBody("<span class=\"chemf\">H<sub class=\"template-chem2-sub\">2</sub><sup class=\"template-chem2-sup\">−</sup></span>");
    try FormattingScopeTest.word(a, one_sided, "2", .{ .classes = "chemf template-chem2-sub", .subscript = true });
    try FormattingScopeTest.word(a, one_sided, "−", .{ .classes = "chemf template-chem2-sup", .superscript = true });
}

test "closing-only external URL braces retain actions and isolate literal runs" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { raw: []const u8, target: []const u8, visible: []const u8, literal: bool }{
        .{ .raw = "https://example.test/a}}tail", .target = "https://example.test/a}}tail", .visible = "https://example.test/a}}tail", .literal = true },
        .{ .raw = "https://example.test/a&#125;&#125;tail", .target = "https://example.test/a}}tail", .visible = "https://example.test/a}}tail", .literal = true },
        .{ .raw = "https://example.test/a%7D%7Dtail", .target = "https://example.test/a%7D%7Dtail", .visible = "https://example.test/a%7D%7Dtail", .literal = false },
    };
    for (cases) |item| {
        var r: Renderer = .{ .a = a, .context = .{} };
        try r.link(item.raw, item.raw, .{ .bold = true, .italic = true, .language = "okm", .direction = "rtl", .classes = "source-url", .role = .example }, 0, true);
        try std.testing.expectEqualStrings(item.visible, try plainText(a, r.spans.items));
        var literal_count: usize = 0;
        var parsed_count: usize = 0;
        for (r.spans.items) |span| {
            try std.testing.expect(span.kind == .external_link and span.flags.bold and span.flags.italic);
            try std.testing.expectEqualStrings(item.target, span.target);
            try std.testing.expectEqualStrings("okm", span.language);
            try std.testing.expectEqualStrings("rtl", span.direction);
            try std.testing.expectEqualStrings("source-url", span.classes);
            try std.testing.expect(span.role == .example);
            if (span.provenance == .protected_literal) {
                literal_count += 1;
                try std.testing.expectEqualStrings("}}", span.text);
            } else {
                parsed_count += 1;
                try std.testing.expect(span.provenance == .parsed);
            }
        }
        try std.testing.expectEqual(@as(usize, if (item.literal) 1 else 0), literal_count);
        try std.testing.expect(parsed_count != 0);
        try std.testing.expect(!r.fallbacks.rejected_external_target);
    }
    var labeled: Renderer = .{ .a = a, .context = .{} };
    try labeled.link("<b>clean</b> <i>label</i>", "https://example.test/a}}", .{}, 0, true);
    for (labeled.spans.items) |span| {
        try std.testing.expect(span.provenance == .parsed and span.kind == .external_link);
        if (std.mem.eql(u8, span.text, "clean")) try std.testing.expect(span.flags.bold);
        if (std.mem.eql(u8, span.text, "label")) try std.testing.expect(span.flags.italic);
    }
    try std.testing.expect(unresolvedActionTarget("https://example.test/a}}"));
    try std.testing.expect(unresolvedExternalActionTarget("not-a-url}}"));
    try std.testing.expect(unresolvedExternalActionTarget("https://example.test/{{missing}}"));
    var refused: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectError(error.UncompiledTemplate, refused.link("https://example.test/{{missing}}", "https://example.test/{{missing}}", .{}, 0, true));
}

test "HTML list font inheritance preserves nested overrides and continuation scope through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "<ul style='font-weight:bold;font-style:italic'><li>parent<ol><li>nested</li><li style='font-weight:normal;font-style:normal'>clear<ul><li>ordinary</li></ul></li></ol>tail</li><li>sibling</li></ul>outside";
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody(source);
    const stored = try FormattingScopeTest.encode(a, &renderer, blocks);
    for ([_][]const u8{ "parent", "nested", "tail", "sibling" }) |word| {
        try FormattingScopeTest.word(a, blocks, word, .{ .bold = true, .italic = true });
        try FormattingScopeTest.word(a, stored.entry.sections[0].blocks, word, .{ .bold = true, .italic = true });
    }
    for ([_][]const u8{ "clear", "ordinary", "outside" }) |word| {
        try FormattingScopeTest.word(a, blocks, word, .{});
        try FormattingScopeTest.word(a, stored.entry.sections[0].blocks, word, .{});
    }
    try std.testing.expect(!renderer.fallbacks.any());
    // Item font scope also encloses a nested typed table without styling later siblings.
    var table_renderer: Renderer = .{ .a = a, .context = .{} };
    const table_blocks = try table_renderer.renderBody("<ul><li style='font-weight:bold;font-style:italic'>lead<table><tr><td>cell</td></tr></table>end</li><li>plain</li></ul>");
    const TableCheck = struct {
        fn check(allocator: A, values: anytype) !void {
            var table_count: usize = 0;
            for (values) |value| if (value.table) |table| {
                table_count += 1;
                try std.testing.expectEqual(@as(usize, 1), table.rows.len);
                try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
                const cell = table.rows[0].cells[0];
                try std.testing.expect(cell.spans.len != 0);
                try std.testing.expectEqualStrings("cell", try FormattingScopeTest.text(allocator, cell.spans));
                for (cell.spans) |span| {
                    const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                    const italic = if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                    try std.testing.expect(bold and italic);
                }
            };
            try std.testing.expectEqual(@as(usize, 1), table_count);
        }
    };
    try TableCheck.check(a, table_blocks);
    const table_stored = try FormattingScopeTest.encode(a, &table_renderer, table_blocks);
    try TableCheck.check(a, table_stored.entry.sections[0].blocks);
    try FormattingScopeTest.word(a, table_blocks, "end", .{ .bold = true, .italic = true });
    try FormattingScopeTest.word(a, table_blocks, "plain", .{});
    try FormattingScopeTest.word(a, table_stored.entry.sections[0].blocks, "end", .{ .bold = true, .italic = true });
    try FormattingScopeTest.word(a, table_stored.entry.sections[0].blocks, "plain", .{});
    // Weight overrides mirror the existing italic scopes on typed table parts.
    const TableScopeCheck = struct {
        fn check(allocator: A, values: anytype, row_cells: []const usize, texts: []const []const u8, weights: []const bool, caption_text: []const u8) !void {
            var table_count: usize = 0;
            for (values) |value| if (value.table) |table| {
                table_count += 1;
                try std.testing.expectEqualStrings(caption_text, try FormattingScopeTest.text(allocator, table.caption));
                for (table.caption) |span| {
                    const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                    const italic = if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                    try std.testing.expect(!bold and italic);
                }
                try std.testing.expectEqual(row_cells.len, table.rows.len);
                var cell_index: usize = 0;
                for (table.rows, row_cells) |row, wanted_cells| {
                    try std.testing.expectEqual(wanted_cells, row.cells.len);
                    for (row.cells) |cell| {
                        try std.testing.expect(!cell.header);
                        try std.testing.expect(cell.spans.len != 0);
                        try std.testing.expect(cell_index < texts.len);
                        try std.testing.expectEqualStrings(texts[cell_index], try FormattingScopeTest.text(allocator, cell.spans));
                        for (cell.spans) |span| {
                            const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                            const italic = if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                            try std.testing.expectEqual(weights[cell_index], bold);
                            try std.testing.expect(italic);
                        }
                        cell_index += 1;
                    }
                }
                try std.testing.expectEqual(texts.len, cell_index);
            };
            try std.testing.expectEqual(@as(usize, 1), table_count);
        }
    };
    const table_cases = [_]struct { body: []const u8, rows: []const usize, texts: []const []const u8, weights: []const bool, caption: []const u8 = "" }{
        .{ .body = "<table><tr><td style='font-weight:normal'>reset</td><td>inherited</td></tr><tr style='font-weight:normal'><td>rowPlain</td><td style='font-weight:bold'>local</td></tr><tr><td>restored</td><td>final</td></tr></table>", .rows = &.{ 2, 2, 2 }, .texts = &.{ "reset", "inherited", "rowPlain", "local", "restored", "final" }, .weights = &.{ false, true, false, true, true, true } },
        .{ .body = "<table style='font-weight:normal'><caption>caption</caption><tr><td>container</td></tr></table>", .rows = &.{1}, .texts = &.{"container"}, .weights = &.{false}, .caption = "caption" },
        .{ .body = "<table><caption style='font-weight:normal'>caption</caption><tr><td>body</td></tr></table>", .rows = &.{1}, .texts = &.{"body"}, .weights = &.{true}, .caption = "caption" },
    };
    for (table_cases) |case| {
        const scoped_source = try std.fmt.allocPrint(a, "<ul><li style='font-weight:bold;font-style:italic'>lead{s}scopeEnd</li><li>scopeSibling</li></ul>scopeOutside", .{case.body});
        var scoped_renderer: Renderer = .{ .a = a, .context = .{} };
        const scoped_blocks = try scoped_renderer.renderBody(scoped_source);
        const scoped_stored = try FormattingScopeTest.encode(a, &scoped_renderer, scoped_blocks);
        try TableScopeCheck.check(a, scoped_blocks, case.rows, case.texts, case.weights, case.caption);
        try TableScopeCheck.check(a, scoped_stored.entry.sections[0].blocks, case.rows, case.texts, case.weights, case.caption);
        try FormattingScopeTest.word(a, scoped_blocks, "scopeEnd", .{ .bold = true, .italic = true });
        try FormattingScopeTest.word(a, scoped_stored.entry.sections[0].blocks, "scopeEnd", .{ .bold = true, .italic = true });
        for ([_][]const u8{ "scopeSibling", "scopeOutside" }) |word| {
            try FormattingScopeTest.word(a, scoped_blocks, word, .{});
            try FormattingScopeTest.word(a, scoped_stored.entry.sections[0].blocks, word, .{});
        }
        try std.testing.expect(!scoped_renderer.fallbacks.any());
    }
    // A lexical prefix forces the shorthand wrapper through the inline HTML
    // route, where inherited Style fonts need not already be block flags.
    const inline_source = "prefix <b><i><ul><li>lead<table><tr><td>inheritedCell</td><td style='font-weight:normal;font-style:normal'>normalCell</td></tr></table>itemTail</li><li style='font-weight:normal;font-style:normal'>normalItem</li><li>afterItem</li></ul></i></b> suffix";
    var inline_renderer: Renderer = .{ .a = a, .context = .{} };
    const inline_blocks = try inline_renderer.renderBody(inline_source);
    const inline_stored = try FormattingScopeTest.encode(a, &inline_renderer, inline_blocks);
    for ([_][]const u8{ "lead", "inheritedCell", "itemTail", "afterItem" }) |word| {
        try FormattingScopeTest.word(a, inline_blocks, word, .{ .bold = true, .italic = true });
        try FormattingScopeTest.word(a, inline_stored.entry.sections[0].blocks, word, .{ .bold = true, .italic = true });
    }
    for ([_][]const u8{ "prefix", "normalCell", "normalItem", "suffix" }) |word| {
        try FormattingScopeTest.word(a, inline_blocks, word, .{});
        try FormattingScopeTest.word(a, inline_stored.entry.sections[0].blocks, word, .{});
    }
    try std.testing.expect(!inline_renderer.fallbacks.any());
}

test "captured Bleoh swatches and BEN dialect colors preserve typed RGB through DPR4" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "== Englisc bleoh ==\n\n{| cellpadding=\"5\" cellspacing=\"0\" border=\"1\"\n|-  bgcolor=\"#eeeeee\"\n| [[blæc]]\n| bgcolor=\"black\" | &nbsp;\n|-  bgcolor=\"#eeeeee\"\n| [[grǣg]]\n| bgcolor=\"gray\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[hwīt]]\n| bgcolor=\"white\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[Seolfor|seolfor]]\n| bgcolor=\"silver\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[gold]]\n| bgcolor=\"gold\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[rēod]]\n| bgcolor=\"red\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[basu]]\n| bgcolor=\"purple\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[hǣwen]]\n| bgcolor=\"blue\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[grēne]]\n| bgcolor=\"green\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[geolu]]\n| bgcolor=\"yellow\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[geolorēad]]\n| bgcolor=\"orange\" | &nbsp;\n|}\n\n\n[[Category:Portas]]";
    const labels = [_][]const u8{ "blæc", "grǣg", "hwīt", "seolfor", "gold", "rēod", "basu", "hǣwen", "grēne", "geolu", "geolorēad" };
    const targets = [_][]const u8{ "blæc", "grǣg", "hwīt", "Seolfor", "gold", "rēod", "basu", "hǣwen", "grēne", "geolu", "geolorēad" };
    const colors = [_][]const u8{ "#000000", "#808080", "#ffffff", "#c0c0c0", "#ffd700", "#ff0000", "#800080", "#0000ff", "#008000", "#ffff00", "#ffa500" };
    const Check = struct {
        fn table(blocks: anytype, expected_labels: []const []const u8, expected_targets: []const []const u8, expected_colors: []const []const u8) !void {
            var found: usize = 0;
            for (blocks) |block| if (block.table) |table_value| {
                found += 1;
                try std.testing.expectEqual(@as(usize, 11), table_value.rows.len);
                for (table_value.rows, expected_labels, expected_targets, expected_colors) |row, label, target, color| {
                    try std.testing.expectEqual(@as(usize, 2), row.cells.len);
                    const left = row.cells[0];
                    const right = row.cells[1];
                    try std.testing.expectEqualStrings("#eeeeee", left.background.?);
                    try std.testing.expectEqualStrings(color, right.background.?);
                    try std.testing.expectEqual(@as(usize, 1), left.spans.len);
                    try std.testing.expectEqual(@as(usize, 1), right.spans.len);
                    try std.testing.expectEqualStrings(label, left.spans[0].text);
                    try std.testing.expectEqualStrings(target, left.spans[0].target);
                    try std.testing.expect(left.spans[0].kind == .link);
                    try std.testing.expectEqualStrings(" ", right.spans[0].text);
                    try std.testing.expect(right.spans[0].kind == .text and right.spans[0].target.len == 0);
                    for (row.cells) |cell| {
                        try std.testing.expect(!cell.header and cell.colspan == 1 and cell.rowspan == 1);
                        try std.testing.expect(cell.spans[0].foreground == null);
                    }
                }
            };
            try std.testing.expectEqual(@as(usize, 1), found);
        }
        fn ben(allocator: A, blocks: anytype) !void {
            var seen = [_]bool{ false, false, false, false };
            const words = [_][]const u8{ "berda", "asul", "turquesa", "bas aiguanebar" };
            const expected = [_][]const u8{ "#008000", "#1c39bb", "#01796f", "#ff4040" };
            var tables: usize = 0;
            for (blocks) |block| if (block.table) |table_value| {
                tables += 1;
                try std.testing.expectEqual(@as(usize, 2), table_value.rows.len);
                for (table_value.rows, 0..) |row, row_index| for (row.cells) |cell| {
                    try std.testing.expectEqualStrings(if (row_index == 0) "#e2e4c0" else "#f0f0f0", cell.background.?);
                    try std.testing.expect(cell.colspan == (if (row_index == 0) @as(u16, 8) else 1));
                    for (cell.spans) |span| for (words, expected, 0..) |word, color, i| if (std.mem.eql(u8, span.text, word)) {
                        try std.testing.expectEqualStrings(color, span.foreground.?);
                        if (comptime @hasField(@TypeOf(span), "flags")) {
                            if (i == 3) try std.testing.expect(span.flags.bold) else { try std.testing.expect(!span.flags.small); try std.testing.expectApproxEqAbs(@as(f32, 1.0 / 1.2), span.font_scale orelse return error.TestUnexpectedResult, 0.000001); }
                        } else {
                            if (i == 3) try std.testing.expect(span.bold) else { try std.testing.expect(!span.small); try std.testing.expectApproxEqAbs(@as(f32, 1.0 / 1.2), span.font_scale orelse return error.TestUnexpectedResult, 0.000001); }
                        }
                        seen[i] = true;
                    };
                };
                const caption_text = try FormattingScopeTest.text(allocator, table_value.rows[0].cells[0].spans);
                try std.testing.expectEqualStrings("En color berda les diferensies dan el primer, en asul les que ten dan el segundo. Dan el turquesa se marquen les que fan diferensia d'es dos.", caption_text);
            };
            for (seen) |present| try std.testing.expect(present);
            try std.testing.expectEqual(@as(usize, 1), tables);
        }
    };
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody(source);
    try Check.table(blocks, &labels, &targets, &colors);
    const stored = try FormattingScopeTest.encode(a, &renderer, blocks);
    try Check.table(stored.entry.sections[0].blocks, &labels, &targets, &colors);
    var ben_renderer: Renderer = .{ .a = a, .context = .{} };
    const ben_blocks = try ben_renderer.renderBody("<table style=\"background:#F0F0F0\"><tr><th colspan=\"8\" style=\"background:#e2e4c0\"><small>En color <span style=\"color:#008000;\">berda</span> les diferensies dan el primer, en <span style=\"color:#1C39BB;\">asul</span> les que ten dan el segundo. Dan el <span style=\"color:#01796F;\">turquesa</span> se marquen les que fan diferensia d'es dos.</small></th></tr><tr><td><span style=\"color:#FF4040;\">'''bas aiguanebar'''</span></td></tr></table>");
    try Check.ben(a, ben_blocks);
    const ben_stored = try FormattingScopeTest.encode(a, &ben_renderer, ben_blocks);
    try Check.ben(a, ben_stored.entry.sections[0].blocks);
}

test "authored RGB declaration precedence preserves scopes actions and unrelated CSS" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const source = "{| class=wikitable bgcolor='#abc'\n|- bgcolor='#eeeeee'\n| style=\"font-family:'x;y';background-color:RED\" | [[A|red]]\n| style='background-color:blue!important;background-color:green' | [[B|blue]]\n| style='background-color:transparent' | row\n| style='background:url(x)' | unsupported\n|-\n| fallback\n|}";
    const blocks = try renderer.renderBody(source);
    const stored = try FormattingScopeTest.encode(a, &renderer, blocks);
    const Check = struct {
        fn table(blocks_value: anytype) !void {
            var tables: usize = 0;
            for (blocks_value) |block| if (block.table) |table_value| {
                tables += 1;
                try std.testing.expectEqual(@as(usize, 2), table_value.rows.len);
                try std.testing.expectEqual(@as(usize, 4), table_value.rows[0].cells.len);
                const cells = table_value.rows[0].cells;
                try std.testing.expectEqualStrings("#ff0000", cells[0].background.?);
                try std.testing.expectEqualStrings("#0000ff", cells[1].background.?);
                try std.testing.expectEqualStrings("#eeeeee", cells[2].background.?);
                try std.testing.expect(cells[3].background == null);
                try std.testing.expectEqualStrings("A", cells[0].spans[0].target);
                try std.testing.expectEqualStrings("B", cells[1].spans[0].target);
                try std.testing.expectEqualStrings("#aabbcc", table_value.rows[1].cells[0].background.?);
            };
            try std.testing.expectEqual(@as(usize, 1), tables);
        }
        fn spans(values: anytype) !void {
            var text: std.ArrayList(u8) = .empty;
            defer text.deinit(std.testing.allocator);
            var actions: usize = 0;
            var green: usize = 0;
            var blue: usize = 0;
            var reset: usize = 0;
            for (values) |span| {
                try text.appendSlice(std.testing.allocator, span.text);
                if (span.target.len != 0) {
                    actions += 1;
                    try std.testing.expectEqualStrings("A", span.target);
                    try std.testing.expectEqualStrings("#008000", span.foreground.?);
                }
                if (std.mem.indexOf(u8, span.text, "green") != null) {
                    green += 1;
                    try std.testing.expectEqualStrings("#008000", span.foreground.?);
                }
                if (std.mem.eql(u8, span.text, "blue")) {
                    blue += 1;
                    try std.testing.expectEqualStrings("#1c39bb", span.foreground.?);
                }
                if (std.mem.eql(u8, span.text, "reset")) {
                    reset += 1;
                    try std.testing.expect(span.foreground == null);
                }
            }
            try std.testing.expectEqualStrings("green link italicbluegreenresetgreen plain", text.items);
            try std.testing.expect(actions == 1 and green == 3 and blue == 1 and reset == 1);
            try std.testing.expect(values[values.len - 1].foreground == null);
        }
    };
    try Check.table(blocks);
    try Check.table(stored.entry.sections[0].blocks);
    var inline_renderer: Renderer = .{ .a = a, .context = .{} };
    const inline_blocks = try inline_renderer.renderBody("<span class=note style=\"font-family:'x;y';color:#008000\">green [[A|link]] <i>italic</i><span style='color:#1C39BB'>blue</span>green<span style='color:initial'>reset</span>green</span> plain");
    try Check.spans(inline_blocks[0].spans);
    const inline_stored = try FormattingScopeTest.encode(a, &inline_renderer, inline_blocks);
    try Check.spans(inline_stored.entry.sections[0].blocks[0].spans);
    // Local declaration parsing must not discover color inside a quoted value.
    const tag: syntax.Tag = .{ .name = "td", .attrs = "class=wikitable style=\"font-family:'x;background-color:blue';background-color:red;background-image:url(x)\"", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expectEqualStrings("#ff0000", (try renderer.tableCellBackground(tag, "#ffffff")).?);
    const reset_tag: syntax.Tag = .{ .name = "td", .attrs = "style='background-color:red;background:var(--sample)'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expect((try renderer.tableCellBackground(reset_tag, "#ffffff")) == null);
    const shorthand: syntax.Tag = .{ .name = "td", .attrs = "class=wikitable style='background:#c0e4c0;background-image:none'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expectEqualStrings("#c0e4c0", (try renderer.tableCellBackground(shorthand, null)).?);
    const invalid: syntax.Tag = .{ .name = "font", .attrs = "color=red style='color:banana!important;color:green'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expectEqualStrings("#008000", (try renderer.authoredColor(invalid, "color", "color", null)).value.?);
    const legacy: syntax.Tag = .{ .name = "font", .attrs = "color=red style='color:banana'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expectEqualStrings("#ff0000", (try renderer.authoredColor(legacy, "color", "color", null)).value.?);
    const unsupported: syntax.Tag = .{ .name = "td", .attrs = "style='background-color:rgba(0,0,0,0.5)'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expect((try renderer.tableCellBackground(unsupported, "#eeeeee")) == null);
    var span_renderer: Renderer = .{ .a = a, .context = .{} };
    const spanning = try span_renderer.renderBody("<table><tr bgcolor=red><td rowspan=2>unresolved</td><td rowspan=2 bgcolor=blue>own</td></tr><tr bgcolor=green></tr></table>");
    try std.testing.expect(spanning[0].table.?.rows[0].cells[0].background == null);
    try std.testing.expectEqualStrings("#0000ff", spanning[0].table.?.rows[0].cells[1].background.?);
}

test "HTML heading single physical colon items retain heading depth and protected literal controls" {
