test "internal title comments remain suppressed before invalid HTML title checks" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const valid = [_]struct { source: []const u8, target: []const u8 }{
        .{ .source = "[[ክብድ ትዕምርት<!--ገለፃ ወይም ትርጉም እዚህ ያስገቡ-->]]", .target = "ክብድ ትዕምርት" },
        .{ .source = "[[ ተጨማሪ መረጃ<!--ተጨማሪ መረጃን እዚህ ያስገቡ -->]]", .target = "ተጨማሪ መረጃ" },
        .{ .source = "[[fo<!--hidden {{deferred}} <nowiki>\n-->o]]", .target = "foo" },
    };
    for (valid) |case| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(case.source, .{});
        try std.testing.expectEqual(@as(usize, 1), spans.len);
        try std.testing.expectEqual(ir.InlineKind.link, spans[0].kind);
        try std.testing.expectEqualStrings(case.target, spans[0].target);
        try std.testing.expectEqualStrings(case.target, spans[0].text);
        try std.testing.expect(!renderer.fallbacks.literal_markup and !renderer.fallbacks.missing_template);
    }
    const retained = [_][]const u8{
        "foo&lt;!--hidden--&gt;bar",
        "<nowiki>foo<!--hidden-->bar</nowiki>",
        "<pre>foo<!--hidden-->bar</pre>",
        "foo<!--unfinished",
    };
    for (retained) |value|
        try std.testing.expectEqualStrings(value, try internalTargetWithoutCommentsAlloc(a, value));
    // Comment preprocessing precedes ordinary HTML attribute parsing.
    try std.testing.expectEqualStrings(
        "<span title=''>foo</span>",
        try internalTargetWithoutCommentsAlloc(a, "<span title='<!--attribute-->'>foo</span>"),
    );
    var invalid: Renderer = .{ .a = a, .context = .{} };
    const rejected = try invalid.parseSpans("[[<!--hidden--><span lang=ar>حاسوب</span>]]", .{});
    try std.testing.expectEqualStrings("[[حاسوب]]", try flattened(a, rejected));
    var language_seen = false;
    for (rejected) |span| {
        try std.testing.expect(span.kind == .text and span.target.len == 0);
        if (std.mem.eql(u8, span.text, "حاسوب")) {
            language_seen = true;
            try std.testing.expectEqualStrings("ar", span.language);
        }
    }
    try std.testing.expect(language_seen and invalid.fallbacks.literal_markup);
    var entity: Renderer = .{ .a = a, .context = .{} };
    const literal = try entity.parseSpans("[[foo&lt;!--hidden--&gt;bar]]", .{});
    try std.testing.expectEqualStrings("[[foo<!--hidden-->bar]]", try flattened(a, literal));
    for (literal) |span| try std.testing.expect(span.kind == .text and span.target.len == 0);
    try std.testing.expectEqualStrings("foo{{deferred}}", try internalTargetWithoutCommentsAlloc(a, "foo<!--hidden-->{{deferred}}"));
}


test "empty target pairs preserve inner text styles and child actions as diagnosed content" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { source: []const u8, visible: []const u8 }{
        .{ .source = "[[|]]", .visible = "[[|]]" },
        .{ .source = "[[|label]]", .visible = "[[|label]]" },
        .{ .source = "[[ |label]]", .visible = "[[ |label]]" },
    };
    for (cases) |case| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const spans = try r.parseSpans(case.source, .{ .italic = true, .language = "cy" });
        const visible = try flattened(a, spans);
        try std.testing.expectEqualStrings(case.visible, visible);
        // The display contains literal rejected syntax; only its proved
        // wrapper bytes, rather than a flattened string, carry provenance.
        try std.testing.expectError(error.UncompiledPresentation, requireCompiledText(visible));
        var delimiters: usize = 0;
        for (spans) |span| {
            try std.testing.expect(span.kind == .text and span.target.len == 0 and !span.self_link);
            try std.testing.expect(span.flags.italic and !span.generated_diagnostic);
            try std.testing.expectEqualStrings("cy", span.language);
            if (std.mem.eql(u8, span.text, "[[") or std.mem.eql(u8, span.text, "]]")) {
                try std.testing.expect(span.provenance == .protected_literal);
                delimiters += 1;
            } else try std.testing.expect(span.provenance == .parsed);
        }
        try std.testing.expectEqual(@as(usize, 2), delimiters);
        try std.testing.expect(r.fallbacks.literal_markup);
    }
    var nested: Renderer = .{ .a = a, .context = .{} };
    const spans = try nested.parseSpans("[[|<b>label</b> [[Target|child]]]]s", .{});
    try std.testing.expectEqualStrings("[[|label child]]s", try flattened(a, spans));
    var actions: usize = 0;
    var bold_label = false;
    for (spans) |span| {
        if (std.mem.eql(u8, span.text, "label")) bold_label = span.flags.bold;
        if (span.kind == .link) {
            actions += 1;
            try std.testing.expectEqualStrings("Target", span.target);
            try std.testing.expectEqualStrings("child", span.text);
        }
    }
    try std.testing.expect(bold_label);
    try std.testing.expectEqual(@as(usize, 1), actions);
    var valid: Renderer = .{ .a = a, .context = .{} };
    const normal = try valid.parseSpans("[[Target|]]", .{});
    try std.testing.expect(unclosedExternalRecoveryHasLink(normal, .link, "Target"));
    try std.testing.expect(!valid.fallbacks.literal_markup);
    try std.testing.expectError(error.UncompiledPresentation, requireCompiledText("[[|"));
    try std.testing.expectError(error.UncompiledPresentation, requireCompiledText("{{deferred}}"));
}


test "captured GV empty translation row preserves warning and protected literals" {
    const source = "* <span title=\"Bretnish\">Bretnish:</span> <span lang=\"cy\" xml:lang=\"cy\">[[|]]</span>&nbsp;<span class=\"trad-sup-code\"><sup>[[:cy:|(cy)]]</sup></span><span style=\"\">My vel shiu abyl, cur stiagh y çhyndaa shoh my sailliu. [[Category:Bretnish: Çhyndaaghyn ry-laccal]]";
