        "<ref lang=\"a</br>\">", "<script lang=\"a</br>\">",
    }) |rejected| try std.testing.expect(!Renderer.interruptedSpanAttributeOpening(rejected, 0));
    for ([_][]const u8{
        "{{unexpanded|<span lang=\"a</br>\">}}",
