    for ([_][]const u8{
        "<cf. plain>", "<cf. 'word'>", "<cf. '''word'''>", "<cf. ''''word''''>",
        "<cf. ''word>", "<cf. word''>", "<cf. '' ''>", "<cf. ''word' ''>",
        "<cf. ''word'' title=x>", "<cf. ''word'' \"x\">", "<cf. ''word''/>",
        "<cf. ''[[Child]]''>", "<cf. ''[https://example.test label]''>",
        "<cf. ''{{x}}''>", "<cf. ''{{{x}}}''>", "<cf. ''&amp;''>",
        "<cf. ''<b>word</b>''>", "<cf. ''word\nword''>", "<cf. ''word\rword''>",
        "<cf. ''\xff''>", "<cf. ''\u{200b}word''>", "<b. ''word''>",
