    const blocks = try table_renderer.renderBody("{|\n| cell\n|}");
    try std.testing.expectEqual(@as(usize, 1), blocks.len);
    try std.testing.expect(blocks[0].table != null and !table_renderer.fallbacks.malformed_table);
