        .{ .self_link_target = "entry" }, .{ .provenance = .entity_literal }, .{ .provenance = .protected_literal },
        .{ .code = true }, .{ .preserve_whitespace = true }, .{ .missing_nonaction = true },
    }) |style| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
