        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, visible.items, "[["));
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, visible.items, "]]"));
        try std.testing.expect(action and italic and actual_renderer.fallbacks.literal_markup);
    }
}

