    var curly = MissingText.untracked(curly_source);
    curly.literal_curly_ranges = &.{.{ .start = @intCast(curly_at), .end = @intCast(curly_at + 1) }};
    _ = try missing_dependency.slice(a, curly, 0, curly.bytes.len);
