        const source = try std.mem.concat(a, u8, &.{ "<nowiki>[</nowiki>before\n-{T\n# [[Target|kept]] ''italic''\n", list, "\n[[After|tail]]" });
        const reference = try std.mem.replaceOwned(u8, a, source, "-{T", "<nowiki>-{</nowiki>T");
