    }
    for ([_][]const u8{ "text &unknown;", "text &mdash", "text &#xZZ;", "text &#;", "text &", "<nowiki>&mdash;</nowiki>", "<span lang=vi>&mdash;</span>", "<ol><li>&mdash;</li></ol>", "[[Target|&mdash;]]" }) |source| {
        errdefer std.debug.print("entity inventory refusal={s}\n", .{source});
