    const expected = try control.renderBodyWithMissing(.{ .bytes = reference, .unknown = true });
    try std.testing.expectEqual(@as(usize, 2), blocks.len);
    var text: std.ArrayList(u8) = .empty;
    var actions: usize = 0;
