    for ([_]MissingText{ .{ .bytes = raw, .unknown = true }, .{ .bytes = raw, .lost_missing_range = true }, .{ .bytes = raw, .generated_source = raw } }) |tracked| {
        var refused: Renderer = .{ .a = a, .context = try ImageMapNoLinkTest.context(a, raw) };
