        }
    };
    try std.testing.expectEqual(@as(usize, 1), try TableCheck.count(stored.entry.sections[0].blocks));
    const spans = try FigureProducerTest.bodySpans(a, stored.entry.sections[0].blocks);
    var found: usize = 0;
