    try std.testing.expectEqual(@as(u8, 128 | 4), bytes[bytes.len - 1]);
    const saved = try codec.decodeAlloc(a, bytes, "prefix", .language, .{ .code = "de", .heading = "German" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, saved));
    var stored_table: ?presentation_types.Table = null;
    for (saved.entry.sections[0].blocks) |block| if (block.table) |value| {
        try std.testing.expect(stored_table == null); stored_table = value;
    };
    const decoded = stored_table orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(table.geometry, decoded.geometry);
    try std.testing.expectEqualDeep(table.style, decoded.style);
    try std.testing.expectEqualDeep(policy.*, decoded.block_viewport.?.*);
    for (table.rows[0].cells, decoded.rows[0].cells) |before, after| {
        try std.testing.expectEqualDeep(before.style, after.style);
        try std.testing.expectEqual(before.spans.len, after.spans.len);
        for (before.spans, after.spans) |left, right| {
            try std.testing.expectEqualStrings(left.text, right.text); try std.testing.expectEqualStrings(left.target, right.target);
            try std.testing.expectEqualDeep(left.image, right.image);
            try std.testing.expectEqualDeep(left.font_family, right.font_family);
            try std.testing.expectEqualDeep(left.link_paint, right.link_paint);
            try std.testing.expectEqual(left.flags.bold, right.bold); try std.testing.expectEqual(left.flags.italic, right.italic);
        }
    }
    try std.testing.expectEqualStrings("\n{|class=\"baniera-jereo\" style=\"" ++ T.style ++ "\"\n|[[File:Arrowyellow.png|30px]]\n|''[[Kept|kept]]''\n|-\n|}", T.source);
    }
}


test "intrinsic parent metric projection requires independent origins and preserves every nonmetric field" {
    var renderer: Renderer = .{ .a = std.testing.allocator, .context = .{}, .body_depth = 1 };
    const body: Renderer.AuthoredRuleRelativeFontSize = .{ .value = 0.875, .basis = .normal_body };
    const native: Style = .{ .font_scale = 2, .font_scale_basis = .normal_body, .font_scale_set = true,
        .bold = true, .italic = true, .foreground = "#202122", .foreground_set = true,
        .background = "#ffff00", .language = "de", .direction = "ltr" };
    var expected = native; expected.font_scale = 1.75;
    try std.testing.expectEqualDeep(expected, renderer.intrinsicTableSourceParent(native, body).?);
    const ordinary = renderer.intrinsicTableSourceParent(.{}, body) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(?f32, 0.875), ordinary.font_scale);
    try std.testing.expectEqual(FontScaleBasis.normal_body, ordinary.font_scale_basis);
    const pixels: Style = .{ .font_scale = 14, .font_scale_basis = .css_px, .font_scale_set = true };
    try std.testing.expectEqualDeep(pixels, renderer.intrinsicTableSourceParent(pixels, body).?);
    // A pixel value stays absolute for the existing comparison; it is not
    // divided by a symbolic body metric or accepted as the same source parent.
    for (0..8) |mode| {
        var parent = native; var changed = body;
        renderer.body_depth = 1;
        switch (mode) {
            0 => changed.unknown = true,
            1 => changed.value = null,
            2 => changed.value = 0,
            3 => changed.basis = .context,
            4 => changed.basis = .css_px,
            5 => parent.font_size_unknown = true,
            6 => { parent = .{}; renderer.body_depth = 0; },
            7 => parent = .{ .font_scale = 0.875, .font_scale_basis = .context, .font_scale_set = true },
            else => unreachable,
        }
        try std.testing.expect(renderer.intrinsicTableSourceParent(parent, changed) == null);
    }
}

test "intrinsic captured body ratio retains native parent mismatch and trait refusals" {
