const PrefixEntityProducerTesting = struct {
    fn nodes(a: A) ![]table_style_profile.ObservedStyleNode {
        const result = try a.alloc(table_style_profile.ObservedStyleNode, 16);
        @memcpy(result[0..13], PrefixCornerTableProducerTest.nodes[0..13]);
        result[13] = .{ .tag = "span", .parent = 12, .attributes = &.{.{ .name = "typeof", .value = "mw:Entity" }},
            .empty = false, .has_text = true, .captured_entity_text = "\xc2\xa0" };
        result[14] = PrefixCornerTableProducerTest.nodes[13];
        result[15] = .{ .tag = "span", .parent = 12, .attributes = &.{.{ .name = "typeof", .value = "mw:Entity" }},
            .empty = false, .has_text = true, .captured_entity_text = " " };
        return result;
    }
};

