test "Table link font equality compares complete custom bindings semantically and retains every other Style field" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const first = try a.dupe(table_style_profile.CustomBinding, &.{
        .{ .name = "--ink", .value = .{ .known = "#3366cc" } },
        .{ .name = "--invalid", .value = .invalid },
        .{ .name = "--uncertain", .value = .unknown },
    });
    const second = try a.dupe(table_style_profile.CustomBinding, &.{ first[2], first[0], first[1] });
    for (second) |*binding| {
        binding.name = try a.dupe(u8, binding.name);
        if (binding.value == .known) binding.value.known = try a.dupe(u8, binding.value.known);
    }
    try std.testing.expect(first.ptr != second.ptr);
    const left: Style = .{ .custom_properties = .{ .values = first, .complete = true },
        .font_scale = 1, .font_scale_basis = .normal_body, .font_scale_set = true, .font_family = .sans_serif,
        .foreground = "#3366cc", .background = "#f5f4aa", .language = "de", .direction = "ltr" };
    var right = left; right.custom_properties = .{ .values = second, .complete = true };
    // Keep generic preparation's borrowed-slice identity contract unchanged.
    try std.testing.expect(!Renderer.sameFigurePreparationValue(left, right));
    try std.testing.expect(Renderer.tableLinkFontStyleEqual(left, right));
    try std.testing.expect(Renderer.tableLinkFontStyleEqual(null, null));
    try std.testing.expect(!Renderer.tableLinkFontStyleEqual(left, null));
    try std.testing.expect(!Renderer.tableLinkFontStyleEqual(null, right));
    for (0..6) |mode| {
        const changed = try a.dupe(table_style_profile.CustomBinding, second);
        var different = right;
        different.custom_properties = .{ .values = changed, .complete = true };
        switch (mode) {
            0 => changed[1].value = .{ .known = "#233566" },
            1 => changed[1].value = .unknown,
            2 => changed[1].value = .invalid,
            3 => different.custom_properties.?.complete = false,
            4 => different.custom_properties.?.values = changed[0..2],
            5 => changed[0].value = .invalid,
            else => unreachable,
        }
        try std.testing.expect(!Renderer.tableLinkFontStyleEqual(left, different));
    }
    var absent = right; absent.custom_properties = null;
    try std.testing.expect(!Renderer.tableLinkFontStyleEqual(left, absent));
    // In contrast to tableViewportTextEqual, background is not projected out.
    for (0..7) |mode| {
        var different = right;
        switch (mode) {
            0 => different.background = "#ffffff",
            1 => different.foreground = "#233566",
            2 => different.bold = true,
            3 => different.font_scale = 2,
            4 => different.font_size_unknown = true,
            5 => different.language = "fr",
            6 => different.direction = "rtl",
            else => unreachable,
        }
        try std.testing.expect(!Renderer.tableLinkFontStyleEqual(left, different));
    }
    const state: presentation_types.LinkState = .{ .foreground = "#3366cc", .underline = false };
    var painted = right;
    painted.link_paint = .{ .normal = state, .hover = state, .active = state, .hover_active = state,
        .visited = state, .visited_hover = state, .visited_active = state, .visited_hover_active = state, .underline_on_focus = false };
    try std.testing.expect(!Renderer.tableLinkFontStyleEqual(left, painted));
    const source_anchor = try a.create(table_style_profile.TextElement); source_anchor.* = .{ .tag = "a" };
    const foreign_anchor = try a.create(table_style_profile.TextElement); foreign_anchor.* = .{ .tag = "a" };
    try std.testing.expect(source_anchor != foreign_anchor);
    var anchored = left; anchored.text_element = source_anchor;
    var borrowed = right; borrowed.text_element = source_anchor;
    try std.testing.expect(Renderer.tableLinkFontStyleEqual(anchored, borrowed));
    borrowed.text_element = foreign_anchor;
    try std.testing.expect(!Renderer.tableLinkFontStyleEqual(anchored, borrowed));
}

test "single inline cell custom environments preserve viewport and independent captured head font parity" {
    var q_phase = @src();
    errdefer std.debug.print("TABLE_LINK_FONT_ENVIRONMENT checkpoint={s}:{d}\n", .{ q_phase.file, q_phase.line });
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = PrefixCornerTableProducerTest;
    const input = "\n{|class=\"baniera-jereo\" style=\"" ++ T.style ++ "\"\n|[[File:Arrowyellow.png|30px]] [[Kept|Long]]''Unbroken''Run\n|-\n|}";
    const captured = changed: {
        var result: [13]table_style_profile.ObservedStyleNode = undefined;
        @memcpy(result[0..11], T.nodes[0..11]); result[7].has_text = true;
        result[0].attributes = &.{.{ .name = "lang", .value = "de" }, .{ .name = "class", .value = "client-nojs" }};
        result[11] = .{ .tag = "a", .parent = 7, .attributes = &.{.{ .name = "href", .value = "https://de.wiktionary.org/wiki/Kept" }},
            .empty = false, .has_text = true };
        result[12] = .{ .tag = "i", .parent = 7, .attributes = &.{}, .empty = false, .has_text = true };
        break :changed result;
    };
    const css = T.css ++ ".mw-parser-output a{word-wrap:break-word}" ++
        "a{text-decoration:none;color:var(--color-progressive,#36c);background:none}" ++
        ".client-nojs a.mw-editsection-visualeditor:first-of-type + .mw-editsection-divider + a::before,.ve-not-available a.mw-editsection-visualeditor:first-of-type + .mw-editsection-divider + a::before,.client-nojs a.mw-editsection-visualeditor:first-of-type + a::before,.ve-not-available a.mw-editsection-visualeditor:first-of-type + a::before{content:'[';content:'[' / '';margin-right:0.25em;margin-inline:0 0.25em}.client-nojs a:has(+ .mw-editsection-divider + a.mw-editsection-visualeditor:last-of-type)::after,.ve-not-available a:has(+ .mw-editsection-divider + a.mw-editsection-visualeditor:last-of-type)::after,.client-nojs a:has(+ a.mw-editsection-visualeditor:last-of-type)::after,.ve-not-available a:has(+ a.mw-editsection-visualeditor:last-of-type)::after{content:']';content:']' / '';margin-left:0.25em;margin-inline:0.25em 0}";
    const actual_css = css ++ ":root{--unused-alpha:alpha;--unused-beta:beta}";
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    var first = try table_style_profile.parseForTargetAlloc(a, actual_css, .screen); defer first.deinit();
    var second = try table_style_profile.parseForTargetAlloc(a, actual_css, .screen); defer second.deinit();
    const first_nodes = try a.dupe(table_style_profile.ObservedStyleNode, &captured);
    const second_nodes = try a.dupe(table_style_profile.ObservedStyleNode, &captured);
    try std.testing.expect(first_nodes.ptr != second_nodes.ptr);
    q_phase = @src();
    var renderer = try T.renderer(a, &ns, input, .{ &first, &second }, .{ first_nodes, second_nodes });
    q_phase = @src();
    const blocks = try renderer.renderBodyWithMissing(MissingText.untracked(input));
    q_phase = @src();
    const table = try T.onlyTable(blocks);
    q_phase = @src();
    try std.testing.expect(!renderer.fallbacks.any());
    try std.testing.expectEqual(@as(usize, 1), table.rows.len);
    try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
    try std.testing.expectEqual(@as(?u16, 2), table.geometry.?.cell_spacing);
    try std.testing.expectEqual(@as(?u16, 1), table.geometry.?.cell_padding);
    try std.testing.expect(table.geometry.?.border == null and table.geometry.?.width == null);
    try std.testing.expectEqual(presentation_types.BorderCollapse.separate, table.style.?.collapse.?);
    try std.testing.expectEqual(@as(f32, 8), table.style.?.corner_radii.?.top_left.value);
    q_phase = @src();
    const policy = table.block_viewport orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 639), policy.max_viewport_width_px);
    try std.testing.expect(policy.focus_paint != null and table.float_viewport == null);
    try std.testing.expect(policy.box_style.containing_direction != null and table.style.?.containing_direction != null);
    try std.testing.expectEqualStrings("#f5f4aa", policy.box_style.background.?);
    try std.testing.expectEqual(@as(f32, 0.1), policy.box_style.padding.?.left.value);
    try std.testing.expectEqual(@as(usize, 0), table.caption.len);
    q_phase = @src();
    const picture = table.rows[0].cells[0];
    try std.testing.expect(picture.blocks == null and picture.nested_table == null);
    try std.testing.expectEqualStrings(" LongUnbrokenRun", try plainText(a, picture.spans));
    var linked_text = false; var italic_text = false;
    for (picture.spans) |span| {
        if (std.mem.eql(u8, span.text, "Long")) {
            try std.testing.expectEqualStrings("Kept", span.target);
            try std.testing.expect(span.kind == .link and span.link_paint != null and !span.flags.italic);
            linked_text = true;
        }
        if (std.mem.eql(u8, span.text, "Unbroken")) {
            try std.testing.expect(span.flags.italic); italic_text = true;
        }
    }
    try std.testing.expect(linked_text and italic_text);
    const image = picture.spans[0].image orelse return error.TestUnexpectedResult;
    try std.testing.expect(picture.spans[0].link_paint == null);
    try std.testing.expectEqualStrings("Arrowyellow.png", image.file);
    try std.testing.expectEqual(@as(?u32, 30), image.width_px); try std.testing.expect(image.height_px == null);
    try std.testing.expectEqual(presentation_types.InlineImageVerticalAlign.middle, image.vertical_align.?);
    try std.testing.expectEqualStrings("File:Arrowyellow.png", picture.spans[0].target);
    try std.testing.expectEqualStrings("", picture.spans[0].text);
    q_phase = @src();
    const owner = picture.style.?.line_height.?.strut.?.owner_font.?;
    try std.testing.expectEqualDeep(owner.font_family, picture.spans[0].font_family);
    try std.testing.expectEqual(owner.font_scale, picture.spans[0].font_scale);
    try std.testing.expectEqual(owner.bold, picture.spans[0].flags.bold);
    try std.testing.expectEqual(@as(usize, 1), renderer.media.items.len);
    try std.testing.expectEqualStrings("Arrowyellow.png", renderer.media.items[0].file);
    const codec = @import("blob_encoder").presentation_codec;
    q_phase = @src();
    const bytes = try codec.encodeBuildAlloc(a, &[_]Span{},
        &[_]struct { level: u8 = 0, title: []const u8 = "", blocks: []const Block }{.{ .blocks = blocks }},
        presentation_types.Layout{}, &.{}, renderer.media.items);
    try std.testing.expectEqualStrings("DPRQ", bytes[0..4]);
    // The capability feature byte follows the complete payload. These
    // sections have no heading styles, so no heading tail follows it.
    try std.testing.expectEqual(@as(u8, 0), bytes[4]); // empty display-title spans
    try std.testing.expectEqual(@as(u8, 128 | 4), bytes[bytes.len - 1]);
    q_phase = @src();
    const saved = try codec.decodeAlloc(a, bytes, "prefix", .language, .{ .code = "de", .heading = "German" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, saved));
    var stored_table: ?presentation_types.Table = null;
    for (saved.entry.sections[0].blocks) |block| if (block.table) |value| {
        try std.testing.expect(stored_table == null); stored_table = value;
    };
    q_phase = @src();
    const decoded = stored_table orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(table.geometry, decoded.geometry);
    try std.testing.expectEqualDeep(table.style, decoded.style);
    try std.testing.expectEqualDeep(policy.*, decoded.block_viewport.?.*);
    q_phase = @src();
    for (table.rows[0].cells, decoded.rows[0].cells) |before, after| {
        try std.testing.expectEqualDeep(before.style, after.style);
        try std.testing.expectEqual(before.spans.len, after.spans.len);
        for (before.spans, after.spans) |left, right| {
            try std.testing.expectEqualStrings(left.text, right.text); try std.testing.expectEqualStrings(left.target, right.target);
            try std.testing.expectEqualDeep(left.image, right.image);
            try std.testing.expectEqualDeep(left.font_family, right.font_family);
            try std.testing.expectEqualDeep(left.link_paint, right.link_paint);
            try std.testing.expectEqual(left.flags.bold, right.bold); try std.testing.expectEqual(left.flags.italic, right.italic);
        }
    }
    // An independent ordinary-wrap renderer on identical source/captures
    // provides complete serialized body/action/font/image/style equality.
    // The CSS aliases are consumed only by the issued minimum proof.
    var baseline_first = try table_style_profile.parseForTargetAlloc(a, T.css, .screen); defer baseline_first.deinit();
    var baseline_second = try table_style_profile.parseForTargetAlloc(a, T.css, .screen); defer baseline_second.deinit();
    const baseline_nodes1 = try a.dupe(table_style_profile.ObservedStyleNode, &captured);
    const baseline_nodes2 = try a.dupe(table_style_profile.ObservedStyleNode, &captured);
    var baseline = try T.renderer(a, &ns, input, .{ &baseline_first, &baseline_second }, .{ baseline_nodes1, baseline_nodes2 });
    const baseline_blocks = try baseline.renderBodyWithMissing(MissingText.untracked(input));
    try std.testing.expect(!baseline.fallbacks.any());
    const baseline_table = try T.onlyTable(baseline_blocks);
    try std.testing.expectEqual(@as(usize, 1), baseline_table.rows[0].cells.len);
    const baseline_bytes = try codec.encodeBuildAlloc(a, &[_]Span{},
        &[_]struct { level: u8 = 0, title: []const u8 = "", blocks: []const Block }{.{ .blocks = baseline_blocks }},
        presentation_types.Layout{}, &.{}, baseline.media.items);
    try std.testing.expectEqualSlices(u8, baseline_bytes, bytes);
}


test "joined captured Table source refutes absent static pseudo rules without lending ordinary capture authority" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = OrdinaryTableLinkProducerTest;
    const absent = "a[rel='mw:referencedBy']::before{font-weight:bold}";
    const css = T.css ++ absent;
    var styles = try table_style_profile.parseForTargetAlloc(a, css, .screen); defer styles.deinit();
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    var renderer = try T.renderer(a, T.source, &styles); renderer.context.namespace_catalog = &ns;
    var nodes = T.nodes;
    for (&nodes) |*node| { node.empty = false; if (node.has_text == null) node.has_text = false; }
    const intake = T.scope(&styles, nodes[0..4]);
    const full = T.scope(&styles, &nodes);
    const graph = (try renderer.tableViewportWikiGraphIn(T.source, 0, intake, false)) orelse return error.TestUnexpectedResult;
    const query: table_style_profile.TableContainingDirectionContext = .{ .styles = &styles,
        .nodes = graph.nodes, .root = graph.root, .table = graph.table };
    const inventory = (try renderer.tableViewportDescendantInventory(graph, T.source)) orelse return error.TestUnexpectedResult;
    const ordinary = (try table_style_profile.observedTableLinkPaintProofWithViewportActions(a, full, query, T.source, &.{7})) orelse return error.TestUnexpectedResult;
    try std.testing.expect(!try table_style_profile.observedTableFloatDescendantsCoveredWithLinks(a, query, inventory, T.source, null, ordinary));
    const joined = (try renderer.tableLinkSourceIn(graph, T.source, intake, query, &.{full}, true)) orelse return error.TestUnexpectedResult;
    try std.testing.expect(joined.proof.closedSourceFocus() and !joined.source_constructed);
    try std.testing.expectEqualStrings("Hilfe:Singular", joined.links[0].target);
    try std.testing.expect(try table_style_profile.observedTableFloatDescendantsCoveredWithLinks(a, query, inventory, T.source, null, joined.proof));
    // Source and both graph identities are borrowed, never compared by contents.
    const foreign_source = try a.dupe(u8, T.source);
    try std.testing.expect((try ordinary.withJoinedCapturedSource(a, foreign_source, full, query)) == null);
    var foreign = full; foreign.nodes = try a.dupe(table_style_profile.ObservedStyleNode, full.nodes);
    try std.testing.expect((try ordinary.withJoinedCapturedSource(a, T.source, foreign, query)) == null);
    foreign = query; foreign.nodes = try a.dupe(table_style_profile.ObservedStyleNode, query.nodes);
    try std.testing.expect((try ordinary.withJoinedCapturedSource(a, T.source, full, foreign)) == null);
    const revoked = ordinary; revoked.operation.focus_domain = null;
    try std.testing.expect((try revoked.withJoinedCapturedSource(a, T.source, full, query)) == null);
    // Incomplete source/captured identity cannot reach the enrichment call.
    try std.testing.expect((try renderer.tableLinkSourceIn(graph, foreign_source, intake, query, &.{full}, true)) == null);
    try std.testing.expect((try renderer.tableLinkSourceIn(graph, T.source, intake, intake, &.{full}, true)) == null);
    try std.testing.expect((try renderer.tableLinkSourceIn(graph, T.source, intake, query, &.{}, true)) == null);
    try std.testing.expect((try renderer.tableLinkSourceIn(graph, T.source, intake, query, &.{full, full}, true)) == null);
    const original = nodes;
    nodes[7].attributes = &.{.{ .name = "href", .value = "/wiki/Hilfe:Singular" }, .{ .name = "title", .value = "Hilfe:Singular" },
        .{ .name = "rel", .value = "mw:referencedBy" }};
    try std.testing.expect((try renderer.tableLinkSourceIn(graph, T.source, intake, query, &.{full}, true)) == null);
    nodes = original;
    nodes[8].parent = 6;
    try std.testing.expect((try renderer.tableLinkSourceIn(graph, T.source, intake, query, &.{full}, true)) == null);
    nodes = original;
    // Descendant coverage rejects possible effects on the actual source A.
    // Ancestor effects remain a separate obligation below.
    for ([_][]const u8{ "a::before{font-weight:bold}", "@media(prefers-contrast:more){a::before{content:'x'}}",
        "html::before{content:'x'}" }) |suffix| {
        var other = try table_style_profile.parseForTargetAlloc(a, try std.mem.concat(a, u8, &.{T.css, suffix}), .screen); defer other.deinit();
        const one = T.scope(&other, nodes[0..4]); const complete = T.scope(&other, &nodes);
        const other_graph = (try renderer.tableViewportWikiGraphIn(T.source, 0, one, false)) orelse return error.TestUnexpectedResult;
        const other_query: table_style_profile.TableContainingDirectionContext = .{ .styles = &other,
            .nodes = other_graph.nodes, .root = other_graph.root, .table = other_graph.table };
        if (std.mem.eql(u8, suffix, "html::before{content:'x'}")) {
            const possible = (try renderer.tableLinkSourceIn(other_graph, T.source, one, other_query, &.{complete}, true)) orelse
                return error.TestUnexpectedResult;
            try std.testing.expect(possible.proof.closedSourceFocus());
            var ancestor_rules: usize = 0;
            for (other.observed_figure_rules, 0..) |rule, index| {
                if (!std.mem.eql(u8, rule.raw_selector, "html::before")) continue;
                ancestor_rules += 1;
                try std.testing.expectEqualStrings("content:'x'", rule.css);
                try std.testing.expect(std.mem.indexOfScalar(usize, possible.proof.rules, index) == null);
            }
            try std.testing.expectEqual(@as(usize, 1), ancestor_rules);
            // HTML is outside the cell descendant inventory. Its effect is not
            // waived by that narrower query or by the joined link proof.
            try std.testing.expect(try table_style_profile.observedTableFloatDescendantsCoveredWithLinks(a, other_query, inventory, T.source, null, possible.proof));
            const html: table_style_profile.TextElement = .{ .tag = nodes[0].tag };
            const body: table_style_profile.TextElement = .{ .tag = nodes[1].tag, .parent = &html };
            const root: table_style_profile.TextElement = .{ .tag = nodes[2].tag, .classes = "mw-parser-output", .parent = &body };
            var base = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer base.deinit();
            var clean = try table_style_profile.joinPageSourcesAlloc(a, &base, &.{}, &.{}); defer clean.deinit();
            try std.testing.expect((try clean.pageUnprovedInheritanceBlockerIn(a, &root)) == null);
            var page = try table_style_profile.joinPageSourcesAlloc(a, &base,
                &.{.{ .css = suffix, .base_url = "https://example.invalid/ancestor.css" }}, &.{}); defer page.deinit();
            // This is the ordinary checkPageAncestorEffects query, with the
            // actual HTML/body/root chain and no missing-root escape.
            const failure = (try page.pageUnprovedInheritanceBlockerIn(a, &root)) orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(table_style_profile.PageAncestorEffectBlocker.Reason.declaration, failure.reason);
            try std.testing.expectEqual(@as(usize, 2), failure.ancestor_depth);
            try std.testing.expectEqualStrings("html::before", failure.rule.?.provenance.?.selector);
            try std.testing.expectEqualStrings("content:'x'", failure.declaration);
            try std.testing.expectEqual(@as(usize, 0), failure.rule.?.provenance.?.source_index);
        } else if (try renderer.tableLinkSourceIn(other_graph, T.source, one, other_query, &.{complete}, true)) |possible|
            try std.testing.expect(!try table_style_profile.observedTableFloatDescendantsCoveredWithLinks(a, other_query, inventory, T.source, null, possible.proof));
    }
}

