    try std.testing.expectEqualDeep(table.geometry, decoded.geometry);
    try std.testing.expectEqualDeep(table.style, decoded.style);
    try std.testing.expectEqualDeep(policy.*, decoded.block_viewport.?.*);
    q_phase = @src();
    for (table.rows[0].cells, decoded.rows[0].cells) |before, after| {
        try std.testing.expectEqualDeep(before.style, after.style);
        try std.testing.expectEqual(before.spans.len, after.spans.len);
        for (before.spans, after.spans) |left, right| {
            try std.testing.expectEqualStrings(left.text, right.text); try std.testing.expectEqualStrings(left.target, right.target);
            try std.testing.expectEqualDeep(left.image, right.image);
            try std.testing.expectEqualDeep(left.font_family, right.font_family);
            try std.testing.expectEqualDeep(left.link_paint, right.link_paint);
            try std.testing.expectEqual(left.flags.bold, right.bold); try std.testing.expectEqual(left.flags.italic, right.italic);
        }
    }
    // An independent ordinary-wrap renderer on identical source/captures
    // with literal-equivalent outline policy provides complete serialized equality.
    // The CSS aliases are consumed only by the issued minimum proof.
    var baseline_first = try table_style_profile.parseForTargetAlloc(a, baseline_css, .screen); defer baseline_first.deinit();
    var baseline_second = try table_style_profile.parseForTargetAlloc(a, baseline_css, .screen); defer baseline_second.deinit();
    const baseline_nodes1 = try a.dupe(table_style_profile.ObservedStyleNode, &captured);
    const baseline_nodes2 = try a.dupe(table_style_profile.ObservedStyleNode, &captured);
    var baseline = try T.renderer(a, &ns, input, .{ &baseline_first, &baseline_second }, .{ baseline_nodes1, baseline_nodes2 });
    const baseline_blocks = try baseline.renderBodyWithMissing(MissingText.untracked(input));
    try std.testing.expect(!baseline.fallbacks.any());
    const baseline_table = try T.onlyTable(baseline_blocks);
    try std.testing.expectEqual(@as(usize, 1), baseline_table.rows[0].cells.len);
    const baseline_bytes = try codec.encodeBuildAlloc(a, &[_]Span{},
        &[_]struct { level: u8 = 0, title: []const u8 = "", blocks: []const Block }{.{ .blocks = baseline_blocks }},
        presentation_types.Layout{}, &.{}, baseline.media.items);
    try std.testing.expectEqualSlices(u8, baseline_bytes, bytes);
}

test "ordinary Table typed wrapping preserves source action ranges formatting codec and scope cleanup" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, OrdinaryTableLinkProducerTest.css ++ ".mw-parser-output a{word-wrap:break-word}", .screen); defer styles.deinit();
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    const source = OrdinaryTableLinkProducerTest.source;
    var renderer = try OrdinaryTableLinkProducerTest.renderer(a, source, &styles);
    renderer.context.namespace_catalog = &ns;
    const scope = OrdinaryTableLinkProducerTest.scope(&styles, OrdinaryTableLinkProducerTest.nodes[0..4]);
    const full = OrdinaryTableLinkProducerTest.scope(&styles, &OrdinaryTableLinkProducerTest.nodes);
    const graph = (try renderer.tableViewportWikiGraphIn(source, 0, scope, false)) orelse return error.TestUnexpectedResult;
    var bound = (try renderer.tableLinkSourceIn(graph, source, scope, scope, &.{full}, false)) orelse return error.TestUnexpectedResult;
    try std.testing.expect(try renderer.tableLinkPaintAtViewport(&bound, 900));
    const body = source[graph.cells[0].body_start..graph.cells[0].body_end];
    renderer.table_viewport_cell_source = .{ .source = body, .links = bound.links, .language = "de", .direction = .ltr,
        .font_scale = 1, .font_scale_basis = .normal_body };
    const parent: Style = .{ .font_scale = 1, .font_scale_basis = .normal_body, .font_scale_set = true, .bold = true };
    const action = (try renderer.tableLinkStyle(parent, .{ .target = "Hilfe:Singular" }, bound.links[0].token)) orelse return error.TestUnexpectedResult;
    try std.testing.expect(renderer.tableLinkActionCurrent(action, action.target));
    const foreign = try a.dupe(u8, bound.links[0].token);
    try std.testing.expect((try renderer.tableLinkStyle(parent, .{ .target = "Hilfe:Singular" }, foreign)) == null);
    var quote_map: QuoteSourceMap = .{ .original = "", .output = "" }; defer quote_map.deinit(a);
    const quoted = try normalizeWikiQuotesMappedWithMissing(a, MissingText.untracked(body), 0, false, renderer.context, null, &quote_map);
    const quoted_token = quoted.bytes[std.mem.indexOf(u8, quoted.bytes, "[[").?..std.mem.lastIndexOf(u8, quoted.bytes, "]]").? + 2];
    var domain: Renderer.TableLinkQuoteDomain = .{ .map = &quote_map, .cell = body, .parent = null };
    renderer.table_link_quote_source = &domain;
    const mapped = renderer.tableLinkOriginalIn(quoted_token, &domain, 0) orelse return error.TestUnexpectedResult;
    try std.testing.expect(mapped.ptr == bound.links[0].token.ptr and mapped.len == bound.links[0].token.len);
    try std.testing.expect((try renderer.tableLinkStyle(parent, .{ .target = "Hilfe:Singular" }, quoted_token)) != null);
    const foreign_body = try a.dupe(u8, body);
    domain.cell = foreign_body;
    try std.testing.expect(renderer.tableLinkOriginalIn(quoted_token, &domain, 0) == null);
    domain.cell = body;
    const original_input = quote_map.original;
    quote_map.original = foreign_body;
    try std.testing.expect(renderer.tableLinkOriginalIn(quoted_token, &domain, 0) == null);
    quote_map.original = original_input;
    renderer.inline_missing = .{ .bytes = quoted.bytes, .unknown = true };
    try std.testing.expect((try renderer.tableLinkStyle(parent, .{ .target = "Hilfe:Singular" }, quoted_token)) == null);
    try std.testing.expect(!renderer.tableLinkActionCurrent(action, action.target));
    renderer.inline_missing = null;
    renderer.table_link_quote_source = null;
    try std.testing.expect((try renderer.tableLinkStyle(parent, .{ .target = "Hilfe:Singular" }, quoted_token)) == null);
    renderer.context.table_styles = &styles;
    const spans = try renderer.parseBodySpans(body, parent);
    try std.testing.expect(renderer.table_link_quote_source == null);
    var linked: usize = 0; var italic = false;
    for (spans) |span| {
        if (span.kind == .link) {
            linked += 1; italic = italic or span.flags.italic;
            try std.testing.expectEqualStrings("Hilfe:Singular", span.target);
            try std.testing.expectEqualDeep(bound.links[0].paint.?, span.link_paint.?);
            try std.testing.expectEqual(presentation_types.TextWrap.break_word, span.inline_style.?.wrap.?);
            try std.testing.expect(span.flags.underline == span.link_paint.?.normal.underline);
        } else try std.testing.expect(span.link_paint == null and span.inline_style == null);
    }
    try std.testing.expect(linked >= 2 and italic and !renderer.fallbacks.unresolved_table_style);
    var static_styles = try table_style_profile.parseForTargetAlloc(a, "a{color:#3366cc;text-decoration:none}", .screen);
    defer static_styles.deinit();
    var reference = try OrdinaryTableLinkProducerTest.renderer(a, source, &static_styles);
    reference.context.namespace_catalog = &ns; reference.context.table_styles = &static_styles;
    reference.table_viewport_cell_source = renderer.table_viewport_cell_source;
    reference.table_viewport_cell_source.?.links = &.{};
    const expected = try reference.parseBodySpans(body, parent);
    const restored = try a.dupe(Span, spans);
    for (restored) |*span| { span.link_paint = null; span.inline_style = null; }
    try std.testing.expectEqualDeep(expected, restored);
    try std.testing.expectEqualDeep(reference.fallbacks, renderer.fallbacks);
    const codec = @import("blob_encoder").presentation_codec;
    const sections = [_]struct { level: u8 = 2, title: []const u8 = "Deutsch", blocks: []const Block }{
        .{ .blocks = &.{.{ .kind = .paragraph, .spans = spans }} },
    };
    const bytes = try codec.encodeBuildAlloc(a, &[_]Span{}, &sections, presentation_types.Layout{}, &.{}, &.{});
    try std.testing.expectEqualStrings("DPRP", bytes[0..4]);
    try std.testing.expectEqual(@as(u8, 16), bytes[bytes.len - 1]);
    const saved = try codec.decodeAlloc(a, bytes, "Mai link", .language, .{ .code = "de", .heading = "Deutsch" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, saved));
    renderer.table_direction_binding.?.owner.unknown = true;
    try std.testing.expect(!renderer.tableLinkActionCurrent(action, action.target));
    renderer.table_direction_binding.?.owner.unknown = false;
    renderer.table_viewport_cell_source = null;
    try std.testing.expect(!renderer.tableLinkActionCurrent(action, action.target));
    const ordinary = try renderer.parseSpans("outside", .{});
    for (ordinary) |span| try std.testing.expect(span.link_paint == null and span.inline_style == null);
    const count = renderer.spans.items.len;
    try std.testing.expectError(error.UncompiledPresentation, renderer.textRaw("spoof", .{ .kind = .link, .target = "Hilfe:Singular", .table_link_wrap = .break_word }));
    try std.testing.expectEqual(count, renderer.spans.items.len);
}


test "ordinary eight row seventy percent source retains distinct per action normal and break word ranges" {
    var q_phase = @src();
    var q_width: f64 = -1;
    var q_row: usize = 0;
    errdefer std.debug.print("ORDINARY_EIGHT_ROW_WRAP checkpoint={s}:{d} viewport={d} row={d}\n", .{ q_phase.file, q_phase.line, q_width, q_row });
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = OrdinaryTableLinkProducerTest;
    var raw: std.ArrayList(u8) = .empty;
    try raw.appendSlice(a, "{|style=\"width:70%\"\n");
    var nodes: [29]table_style_profile.ObservedStyleNode = undefined;
    @memcpy(nodes[0..5], T.nodes[0..5]);
    nodes[3].attributes = &.{.{ .name = "style", .value = "width:70%" }};
    for (0..8) |row| {
        const plural = row % 2 != 0;
        const target: []const u8 = if (plural) "Hilfe:Plural" else "Hilfe:Singular";
        try raw.appendSlice(a, if (row == 0) "|" else "|-\n|");
        try raw.appendSlice(a, try std.fmt.allocPrint(a, "style=\"width:9%\"|[[{s}|LongUnbrokenRun{d}]]\n", .{target, row}));
        const tr: u32 = @intCast(5 + row * 3);
        nodes[tr] = .{ .tag = "tr", .parent = 4, .attributes = &.{} };
        nodes[tr + 1] = .{ .tag = "td", .parent = tr, .attributes = &.{.{ .name = "style", .value = "width:9%" }}, .has_text = true };
        nodes[tr + 2] = .{ .tag = "a", .parent = tr + 1, .attributes = try a.dupe(table_style_profile.FigureObservedAttribute, &.{
            .{ .name = "href", .value = if (plural) "/wiki/Hilfe:Plural" else "/wiki/Hilfe:Singular" },
            .{ .name = "title", .value = target },
        }), .has_text = true };
    }
    try raw.appendSlice(a, "|}"); const input = try raw.toOwnedSlice(a);
    for (0..8) |row| {
        q_row = row; q_phase = @src();
        const node = nodes[7 + row * 3];
        try std.testing.expectEqualStrings(if (row % 2 != 0) "Hilfe:Plural" else "Hilfe:Singular",
            Renderer.tableViewportNodeAttribute(node, "title") orelse return error.TestUnexpectedResult);
        try std.testing.expectEqualStrings(if (row % 2 != 0) "/wiki/Hilfe:Plural" else "/wiki/Hilfe:Singular",
            Renderer.tableViewportNodeAttribute(node, "href") orelse return error.TestUnexpectedResult);
    }
    q_row = 0;
    var styles = try table_style_profile.parseForTargetAlloc(a, T.css ++
        ".mw-parser-output a{word-wrap:break-word}a[href='/wiki/Hilfe:Plural']{overflow-wrap:normal}", .screen); defer styles.deinit();
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    var renderer = try T.renderer(a, input, &styles); renderer.context.namespace_catalog = &ns; renderer.context.table_styles = &styles;
    const scope = T.scope(&styles, nodes[0..4]); const full = T.scope(&styles, &nodes);
    q_phase = @src();
    const graph = (try renderer.tableViewportWikiGraphIn(input, 0, scope, false)) orelse return error.TestUnexpectedResult;
    q_phase = @src();
    try std.testing.expectEqual(@as(usize, 8), graph.row_count); try std.testing.expectEqual(@as(usize, 8), graph.cells.len);
    q_phase = @src();
    const identity = (try renderer.tableLinkSourceIdentity(graph, input, scope, scope, &.{full}, false, false)) orelse return error.TestUnexpectedResult;
    q_phase = @src();
    try std.testing.expectEqual(@as(usize, 8), identity.links.len);
    q_phase = @src();
    var bound = (try renderer.tableLinkSourceIn(graph, input, scope, scope, &.{full}, false)) orelse return error.TestUnexpectedResult;
    q_phase = @src();
    try std.testing.expectEqual(@as(usize, 8), bound.links.len);
    // Serialized policy, not the unrelated one-cell intrinsic-minimum permit.
    for ([_]f64{ 0, 1, 639, 900 }) |width| {
        q_width = width;
        q_phase = @src();
        try std.testing.expect(try renderer.tableLinkPaintAtViewportWithMinimum(&bound, width, null));
    }
    var blocks: [8]Block = undefined;
    const parent: Style = .{ .font_scale = 1, .font_scale_basis = .normal_body, .font_scale_set = true };
    for (graph.cells, 0..) |cell, row| {
        q_row = row;
        const policy: presentation_types.TextWrap = if (row % 2 != 0) .normal else .break_word;
        q_phase = @src();
        try std.testing.expectEqual(@as(?presentation_types.TextWrap, policy), bound.links[row].wrap);
        const body = input[cell.body_start..cell.body_end];
        renderer.table_viewport_cell_source = .{ .source = body, .links = bound.links[row..row + 1], .language = "de", .direction = .ltr,
            .font_scale = 1, .font_scale_basis = .normal_body };
        q_phase = @src();
        const spans = try renderer.parseBodySpans(body, parent);
        q_phase = @src();
        try std.testing.expect(Renderer.tableConstructedSpansMatch(spans, renderer.table_viewport_cell_source.?));
        var seen: usize = 0;
        for (spans) |span| if (span.kind == .link) {
            seen += 1;
            q_phase = @src();
            try std.testing.expectEqual(policy, span.inline_style.?.wrap.?);
            q_phase = @src();
            try std.testing.expectEqualStrings(if (row % 2 != 0) "Hilfe:Plural" else "Hilfe:Singular", span.target);
            q_phase = @src();
            try std.testing.expectEqualDeep(bound.links[row].paint, span.link_paint);
        } else try std.testing.expect(span.inline_style == null);
        q_phase = @src();
        try std.testing.expectEqual(@as(usize, 1), seen);
        blocks[row] = .{ .kind = .paragraph, .spans = spans };
    }
    renderer.table_viewport_cell_source = null;
    q_phase = @src();
    try std.testing.expect(!renderer.fallbacks.any());
    const codec = @import("blob_encoder").presentation_codec;
    q_phase = @src();
    const bytes = try codec.encodeBuildAlloc(a, &[_]Span{},
        &[_]struct { level: u8 = 0, title: []const u8 = "", blocks: []const Block }{.{ .blocks = &blocks }},
        presentation_types.Layout{}, &.{}, &.{});
    q_phase = @src();
    try std.testing.expectEqualStrings("DPRP", bytes[0..4]); try std.testing.expectEqual(@as(u8, 16), bytes[bytes.len - 1]);
    q_phase = @src();
    const decoded = try codec.decodeAlloc(a, bytes, "eight source rows", .language, .{ .code = "de", .heading = "German" });
    q_phase = @src();
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));
    for (blocks, decoded.entry.sections[0].blocks) |before, after| for (before.spans, after.spans) |left, right| {
        q_phase = @src();
        try std.testing.expectEqualStrings(left.text, right.text); try std.testing.expectEqualStrings(left.target, right.target);
        q_phase = @src();
        try std.testing.expectEqualDeep(left.inline_style, right.inline_style); try std.testing.expectEqualDeep(left.link_paint, right.link_paint);
        q_phase = @src();
        try std.testing.expectEqual(left.flags.bold, right.bold); try std.testing.expectEqual(left.flags.italic, right.italic);
    };
}

