test "intrinsic Table link trails retain complete captured action source and real R body" {
    const Failure = struct {
        fn at(comptime stage: []const u8, comptime location: std.builtin.SourceLocation) error{TestUnexpectedResult} {
            std.debug.print("INTRINSIC_TRAIL_NONNULL stage={s} source={s}:{d}:{d}\n", .{ stage, location.file, location.line, location.column });
            return error.TestUnexpectedResult;
        }
    };
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = IntrinsicTableProducerTest;
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    const original = "[[Kept|kept]]";
    const at = std.mem.indexOf(u8, T.source, original) orelse return Failure.at("original source link", @src());
    const source = try std.mem.concat(a, u8, &.{ T.source[0..at], "[[d]]a", T.source[at + original.len..] });
    var styles = try table_style_profile.parseForTargetAlloc(a, T.css, .screen); defer styles.deinit();
    var second_styles = try table_style_profile.parseForTargetAlloc(a, T.css, .screen); defer second_styles.deinit();
    const profiles = [_]*const table_style_profile.Profile{ &styles, &second_styles };
    const contexts = try a.alloc(table_style_profile.TableContainingDirectionContext, 2);
    const full = try a.alloc(table_style_profile.TableContainingDirectionContext, 2);
    for (contexts, full, profiles) |*shallow, *captured, profile| {
        const nodes = try a.dupe(table_style_profile.ObservedStyleNode, &T.nodes);
        nodes[7].attributes = &.{.{ .name = "href", .value = "/wiki/d" }, .{ .name = "title", .value = "d" }};
        shallow.* = .{ .intrinsic_viewport = true, .styles = profile, .nodes = nodes[0..4], .root = 2, .table = 3 };
        captured.* = .{ .intrinsic_viewport = true, .styles = profile, .nodes = nodes, .root = 2, .table = 3 };
    }
    const bound = try a.create(T.Bound); bound.* = .{ .source = source, .contexts = contexts, .full = full };
    var renderer = try OrdinaryTableLinkProducerTest.renderer(a, source, &styles);
    renderer.body_depth = 0; renderer.context.namespace_catalog = &ns;
    const sizing = if (renderer.context.figure_sizing) |*value| value else return Failure.at("fixture FigureSizing", @src());
    sizing.table_containing_direction = .{ .intrinsic_viewport = true,
        .source = source, .context = bound, .observe = T.Bound.observe };
    var phase: []const u8 = "render complete intrinsic trail body";
    errdefer std.debug.print("INTRINSIC_TRAIL phase={s}\n", .{phase});
    const blocks = try renderer.renderBodyWithMissing(MissingText.untracked(source));
    const table = try PrefixCornerTableProducerTest.onlyTable(blocks);
    try std.testing.expect(!renderer.fallbacks.any());
    const policy = table.block_viewport orelse return Failure.at("rendered intrinsic policy", @src());
    try std.testing.expect(policy.intrinsic_containing_direction == .ltr and table.float_viewport == null);
    const geometry = table.geometry orelse return Failure.at("rendered legacy geometry", @src());
    try std.testing.expectEqualDeep(TableGeometry{ .border = 1, .cell_padding = 4, .cell_spacing = 0 }, geometry);
    try std.testing.expectEqual(@as(usize, 2), table.rows.len);
    for (table.rows) |row| try std.testing.expectEqual(@as(usize, 2), row.cells.len);
    const spans = table.rows[0].cells[0].spans;
    try std.testing.expectEqualStrings("da", try plainText(a, spans));
    try std.testing.expect(spans.len != 0);
    for (spans) |span| {
        try std.testing.expect(span.kind == .link and span.link_paint != null);
        try std.testing.expectEqualStrings("d", span.target);
    }
    const centered_blocks = table.rows[0].cells[1].blocks orelse return Failure.at("rendered CENTER cell blocks", @src());
    try std.testing.expectEqualStrings("-", try plainText(a, centered_blocks[0].spans));
    try std.testing.expect(centered_blocks[0].text_align == .center);
    try std.testing.expectEqualStrings("plain", try plainText(a, table.rows[1].cells[0].spans));
    try std.testing.expectEqualStrings("missing", try plainText(a, table.rows[1].cells[1].spans));
    phase = "complete R codec and independent action trail scope negatives";
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeBuildAlloc(a, &[_]Span{}, &[_]struct { level:u8=2,title:[]const u8="Deutsch",blocks:[]const Block }{.{.blocks=blocks}}, presentation_types.Layout{}, &.{}, &.{});
    try std.testing.expectEqualStrings("DPRR", bytes[0..4]);
    const stored = try codec.decodeAlloc(a, bytes, "Intrinsic trail", .language, .{ .code="de",.heading="Deutsch" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
    const complete = source[at..][0..6];
    const core = complete[0..5];
    const binding: Renderer.TableSourceLink = .{ .token = complete, .target = "d", .external = false,
        .subject = 7, .cell = 0, .attributes = full[0].nodes[7].attributes };
    const scope: Renderer.TableViewportCellScope = .{ .source = source, .language = "de", .direction = .ltr,
        .font_scale = 1, .font_scale_basis = .normal_body, .captured_intrinsic_content = true };
    try std.testing.expect(renderer.tableLinkTokenMatches(scope, binding, core));
    for (0..7) |mode| {
        var denied = scope; var action = binding; var mapped: []const u8 = core;
        var probe: Renderer = .{ .a = a, .context = renderer.context };
        switch (mode) {
            0 => denied.captured_intrinsic_content = false,
            1 => denied.source_constructed = true,
            2 => denied.source = source[0 .. at + 5],
            3 => mapped = try a.dupe(u8, core),
            4 => action.external = true,
            5 => probe.context.link_trail = .{ .contains_fn = struct { fn contains(_: ?*const anyopaque, _: u21) bool { return false; } }.contains },
            6 => mapped = complete[0..4],
            else => unreachable,
        }
        try std.testing.expect(!probe.tableLinkTokenMatches(denied, action, mapped));
    }
    // The old non-intrinsic source mapper still refuses this family.
    var links: std.ArrayList(Renderer.TableSourceLink) = .empty;
    try std.testing.expect(!try renderer.tableLinkSourceBody(complete, full[0].nodes, 6, 0, &links, 0, false, false));
}


