test "table viewport opt in preserves exact trial line and independent failure diagnostics" {
    const linux = std.os.linux;
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var reports: [2][]const u8 = undefined;
    for ([_]bool{ false, true }, 0..) |enabled, index| {
        var fds: [2]linux.fd_t = undefined;
        if (linux.errno(linux.pipe2(&fds, .{ .CLOEXEC = true })) != .SUCCESS) return error.DiagnosticTestPipeFailed;
        defer _ = linux.close(fds[0]);
        var write_open = true;
        defer if (write_open) { _ = linux.close(fds[1]); };
        const saved_raw = linux.dup(2);
        if (linux.errno(saved_raw) != .SUCCESS) return error.DiagnosticTestDupFailed;
        const saved: linux.fd_t = @intCast(saved_raw);
        defer _ = linux.close(saved);
        var redirected = false;
        defer if (redirected) { _ = linux.dup2(saved, 2); };
        if (linux.errno(linux.dup2(fds[1], 2)) != .SUCCESS) return error.DiagnosticTestDupFailed;
        redirected = true;
        var renderer: Renderer = .{ .a = a, .context = .{ .title = "Trial", .table_viewport_trace = enabled } };
        const native: Renderer.CellNativeContext = .{ .style = .{}, .formatting = .{} };
        // Exercise the real first candidate refusal, not the logging helper alone.
        const candidate = try renderer.prepareTableViewportMode("<table>", 0, 7, native, null, false);
        const candidate_unchanged = candidate == null and !renderer.fallbacks.any() and renderer.rejection_trace_events == 0;
        renderer.fallbacks.unresolved_table_style = renderer.traceUnresolvedTableStyle(true, "retained-first", "padding:1em");
        const failure = renderer.figureUnavailableAt("retained-failure", "[[File:X.svg]]", 0, 3);
        if (linux.errno(linux.dup2(saved, 2)) != .SUCCESS) return error.DiagnosticTestDupFailed;
        redirected = false;
        _ = linux.close(fds[1]);
        write_open = false;
        try std.testing.expect(candidate_unchanged);
        try std.testing.expect(failure == error.UncompiledPresentation);
        try std.testing.expect(renderer.fallbacks.unresolved_table_style and renderer.fallbacks.unrepresented_figure);
        try std.testing.expectEqualStrings("retained-first", renderer.table_style_trace_branch.?);
        try std.testing.expectEqual(@as(usize, 1), renderer.rejection_trace_events);
        var buffer: [8192]u8 = undefined;
        var used: usize = 0;
        while (true) {
            var ready = [_]std.posix.pollfd{.{ .fd = fds[0], .events = std.posix.POLL.IN, .revents = 0 }};
            if (try std.posix.poll(&ready, 5_000) == 0) return error.DiagnosticTestTimeout;
            if (used == buffer.len) return error.DiagnosticTestOversizedLine;
            const n = linux.read(fds[0], buffer[used..].ptr, buffer.len - used);
            if (linux.errno(n) == .INTR) continue;
            if (linux.errno(n) != .SUCCESS) return error.DiagnosticTestReadFailed;
            if (n == 0) break;
            used += n;
        }
        reports[index] = try a.dupe(u8, buffer[0..used]);
    }
    try std.testing.expect(std.mem.indexOf(u8, reports[0], "table_viewport_refusal") == null);
    try std.testing.expect(std.mem.indexOf(u8, reports[0], "presentation fallback phase=table_style") != null);
    try std.testing.expect(std.mem.indexOf(u8, reports[0], "presentation rejected phase=figure_admission") != null);
    const original_line = try std.fmt.allocPrint(a, "pid={d} presentation table_viewport_refusal stage=prepareTableViewportMode.1 viewport=null subject=null title_hex=547269616c opening_start=0 opening_end=7 source_bytes=7 opening_hex=3c7461626c653e opening_truncated=false native_known=false native_scale=null native_basis=context native_set=false native_unknown=false native_language_hex= native_direction_hex= body_depth=0 floating=false\n", .{linux.getpid()});
    try std.testing.expect(std.mem.startsWith(u8, reports[1], original_line));
    try std.testing.expectEqualStrings(reports[0], reports[1][original_line.len..]);
}

