const LiteralDivCustomRootTest = struct {
    const body = "<div class='standard-box zhpron' style='overflow:auto;max-width:500px;font-size:100%'>body '''bold''' [[Target#part|label]]</div>\n\ntail [[After|action]]";
    const variable_css = ".standard-box{background-color:var(--paper,#f8f9fa);border:1px solid var(--ink,#9e9e9e);padding:5px}";
    const literal_css = ".standard-box{background-color:#ffffe0;border:1px solid #235923;padding:5px}";
    const environment: table_style_profile.CustomEnvironment = .{ .complete = true, .values = &.{
        .{ .name = "--ink", .value = .{ .known = "#235923" } },
        .{ .name = "--paper", .value = .{ .known = "#ffffe0" } },
    } };
    fn init(a: A, styles: *const table_style_profile.Profile, operation: []const u8) !LiteralDivFlexTest {
        const fixture = try LiteralDivFlexTest.init(a, styles, operation);
        fixture.scope.subtree_classes = "standard-box zhpron";
        fixture.scope.complete_ancestor_class_superset = "mw-parser-output client-js standard-box zhpron";
        const root = @constCast(fixture.scope.page_style_complete_root.?);
        root.observed_custom_environment = environment;
        @constCast(root.alternative_ancestry.?).observed_custom_environment = environment;
        // This page-wide intersection has no palette. Only the complete exact
        // root-parent receipt can supply the separately retained environments.
        fixture.scope.page_custom_invariant = .{};
        return fixture;
    }
    fn attach(styles: *table_style_profile.Profile) !void {
        // Deliberately different from the two captured parser-root values.
        // Neither the generic root default nor an inherited logical Style may
        // stand in for the operation's actual physical parent.
        try table_style_profile.attachCustomProperties(styles, &.{.{
            .css = ":root{--ink:red;--paper:white}" ++ variable_css, .base_url = "",
        }}, .{ .ancestors = &.{.{ .tag = "html", .root = true }} });
    }
};

