            6 => "@media(prefers-reduced-motion:reduce){:root{--unproved-wrapper-display:none}}",
            7 => "span[title]{display:none}",
            else => "",
        };
        const changed_css = try std.mem.concat(a, u8, &.{ actual_css, suffix });
        var changed_first = try table_style_profile.parseForTargetAlloc(a, if (mode == 7) actual_css else changed_css, .screen); defer changed_first.deinit();
        var changed_second = try table_style_profile.parseForTargetAlloc(a, changed_css, .screen); defer changed_second.deinit();
        changed_first.page_style_parent = &parent_profile; changed_second.page_style_parent = &parent_profile;
        const changed_nodes1 = try a.dupe(table_style_profile.ObservedStyleNode, &captured);
        const changed_nodes2 = try a.dupe(table_style_profile.ObservedStyleNode, &captured);
        for ([_][]table_style_profile.ObservedStyleNode{ changed_nodes1, changed_nodes2 }) |changed_nodes| {
            if (mode == 0) changed_nodes[8].attributes = &.{.{ .name = "title", .value = "foreign owner" }};
            if (mode == 1) changed_nodes[8].parent = 6;
        }
        var changed_renderer = try T.renderer(a, &ns, input, .{ &changed_first, &changed_second }, .{ changed_nodes1, changed_nodes2 });
        // Keep each negative on the same complete page-domain path; its
        // wrapper/source/state mismatch must not be masked by a missing scope.
        try Scope.bind(a, &changed_renderer, input, &changed_first, changed_nodes1);
        if (changed_renderer.renderBodyWithMissing(MissingText.untracked(input))) |_| {
            try std.testing.expect(changed_renderer.fallbacks.any());
        } else |err| try std.testing.expectEqual(error.UncompiledPresentation, err);
    }
}

