test "source bound local target retains literal label trail and codec without copied or revoked authority" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    const source = try a.dupe(u8, "before [[gh|visible]]a after [[g_h|second]]");
    const TestTarget = struct {
        source: []const u8,
        fn resolve(ctx: ?*const anyopaque, _: A, op: TableSourceAnchorOperation) Error!?[]const u8 {
            const self: *const @This() = @ptrCast(@alignCast(ctx orelse return null));
            if (op.source.ptr != self.source.ptr or op.source.len != self.source.len or
                !Renderer.wikiClassContains(self.source, op.token) or !Renderer.wikiClassContains(op.token, op.target) or
                (!std.mem.eql(u8, op.target, "gh") and !std.mem.eql(u8, op.target, "g_h"))) return null;
            return "Resolved";
        }
    };
    const selected = TestTarget{ .source = source };
    const proof: LocalLinkTargetSource = .{ .source = source, .namespace_sha256 = ns.source_sha256,
        .context = &selected, .resolve = TestTarget.resolve };
    // Select the actual parser core instead of an independently guessed extent.
    var iterator: ir.InlineIterator = .{ .input = source, .renderer_boundaries = true };
    var target: []const u8 = ""; var core: []const u8 = "";
    while (iterator.next()) |node| if (node.kind == .link) {
        target = node.target;
        const at = @intFromPtr(target.ptr) - @intFromPtr(source.ptr) - 2;
        core = source[at .. iterator.cursor - node.trail.len];
        break;
    };
    try std.testing.expect(core.len != 0);
    var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .local_link_targets = proof },
        .body_missing = .{ .bytes = source } };
    try std.testing.expectEqualStrings("Resolved", (try renderer.localLinkTarget(core, target)).?);
    const equal = try a.dupe(u8, core);
    try std.testing.expect(try renderer.localLinkTarget(equal, equal[2..4]) == null);
    try renderer.heading_source_aliases.append(a, .{ .copied = equal, .original = core });
    try std.testing.expectEqualStrings("Resolved", (try renderer.localLinkTarget(equal, equal[2..4])).?);
    const saved_proof = renderer.context.local_link_targets.?;
    renderer.context.local_link_targets.?.namespace_sha256[0] ^= 1;
    try std.testing.expect(try renderer.localLinkTarget(core, target) == null);
    renderer.context.local_link_targets = saved_proof;
    renderer.body_missing.?.lost_missing_range = true;
    try std.testing.expect(try renderer.localLinkTarget(core, target) == null);
    renderer.body_missing.?.lost_missing_range = false;
    renderer.body_missing.?.unknown = true;
    try std.testing.expect(try renderer.localLinkTarget(core, target) == null);
    renderer.body_missing.?.unknown = false;
    renderer.inline_missing = .{ .bytes = core, .ranges = &.{.{ .start = 2, .end = 4, .occurrence = 1 }} };
    try std.testing.expect(try renderer.localLinkTarget(core, target) == null);
    renderer.inline_missing = null;
    var source_copy = saved_proof; source_copy.source = try a.dupe(u8, source);
    renderer.context.local_link_targets = source_copy;
    try std.testing.expect(try renderer.localLinkTarget(core, target) == null);
    renderer.context.local_link_targets = saved_proof;
    const spans = try renderer.parseBodySpans(source, .{});
    var text: std.ArrayList(u8) = .empty;
    var link_text: std.ArrayList(u8) = .empty;
    for (spans) |span| {
        try text.appendSlice(a, span.text);
        if (span.kind == .link) {
            try std.testing.expectEqualStrings("Resolved", span.target);
            try link_text.appendSlice(a, span.text);
        }
    }
    try std.testing.expectEqualStrings("before visiblea after second", text.items);
    try std.testing.expectEqualStrings("visibleasecond", link_text.items);
    const codec = @import("blob_encoder").presentation_codec;
    const blocks = [_]Block{.{ .kind = .paragraph, .spans = spans }};
    const bytes = try codec.encodeBuildAlloc(a, &[_]Span{},
        &[_]struct { level: u8 = 0, title: []const u8 = "", blocks: []const Block }{.{ .blocks = &blocks }},
        presentation_types.Layout{}, &.{}, &.{});
    const stored = try codec.decodeAlloc(a, bytes, "Entry", .language, .{ .code = "en", .heading = "English" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
    for (spans, stored.entry.sections[0].blocks[0].spans) |before, after| {
        try std.testing.expectEqualStrings(before.text, after.text);
        try std.testing.expectEqualStrings(before.target, after.target);
    }
}

test "prefix quote font receipt authenticates generated opening and current cell map" {
    var q_phase = @src();
    errdefer std.debug.print("PREFIX_QUOTE_RECEIPT checkpoint={s}:{d}\n", .{ q_phase.file, q_phase.line });
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    for ([_][]const u8{ "''", "'''" }) |marker| {
        const body = try std.mem.concat(a, u8, &.{ marker, "text", marker });
        var styles = try table_style_profile.parseForTargetAlloc(a,
            "html{font-family:sans-serif;font-size:100%;font-feature-settings:normal;line-height:normal}", .screen); defer styles.deinit();
        var nodes = OrdinaryTableLinkProducerTest.nodes;
