        q_phase = @src();
        const metrics = (try table_style_profile.resolveObservedNestedTableNodeFontMetrics(a, context, 8, null, 0, null)) orelse return error.TestUnexpectedResult;
        q_phase = @src();
        const owner = (try renderer.tableNestedFoldFontMetrics(context, metrics)) orelse return error.TestUnexpectedResult;
        if (marker.len == 3) {
            var bold_parent = nodes; bold_parent[6].tag = "th";
            const bold_context = OrdinaryTableLinkProducerTest.scope(&styles, &bold_parent);
            const bold_metrics = (try table_style_profile.resolveObservedNestedTableNodeFontMetrics(a, bold_context, 8, null, 0, null)) orelse return error.TestUnexpectedResult;
            try std.testing.expect((try renderer.tableNestedFoldFontMetrics(bold_context, bold_metrics)) == null);
        }
        var map: QuoteSourceMap = .{}; defer map.deinit(a);
        q_phase = @src();
        const quoted = try normalizeWikiQuotesMappedWithMissing(a, MissingText.untracked(body), 0, false, renderer.context, null, &map);
        const tag = syntax.tagAt(quoted.bytes, 0) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(name, tag.name);
        const binding: Renderer.TableInlineSourceFont = .{ .opening = .{ .name = name, .attrs = "", .end = 0,
            .closing = false, .self_closing = false }, .quote = body[0..marker.len], .subject = 8, .cell = 0,
            .owner = owner, .paint = .{}, .environment = metrics.nodes[metrics.nodes.len - 1].environment };
        renderer.table_viewport_cell_source = .{ .source = body, .inline_fonts = &.{binding}, .closed_focus = true,
            .language = "de", .direction = .ltr, .font_scale = 1, .font_scale_basis = .normal_body };
        var domain: Renderer.TableLinkQuoteDomain = .{ .map = &map, .cell = body, .parent = null };
        renderer.table_link_quote_source = &domain; renderer.inline_missing = quoted;
        q_phase = @src();
        try std.testing.expect(Renderer.tableNestedFontOwnersAgree(owner, renderer.tableNestedFontForTag(tag)));
        q_phase = @src();
        const resolved = try renderer.htmlLanguageDirection(tag, .{ .font_scale = 1, .font_scale_basis = .normal_body,
            .font_scale_set = true, .foreground = "#202122", .foreground_set = true });
        try std.testing.expect(!resolved.font_size_unknown and resolved.font_scale == owner.font.font_scale);
        try std.testing.expectEqual(owner.font.bold, resolved.bold);
        try std.testing.expectEqual(owner.font.italic, resolved.italic);
        const copy = try a.dupe(u8, body);
        domain.cell = copy;
        try std.testing.expect(renderer.tableNestedFontForTag(tag) == null);
        domain.cell = body;
        const old_original = map.original; map.original = copy;
        try std.testing.expect(renderer.tableNestedFontForTag(tag) == null);
        map.original = old_original;
        const old_output = map.output; map.output = try a.dupe(u8, old_output);
        try std.testing.expect(renderer.tableNestedFontForTag(tag) == null);
        map.output = old_output;
        const first_event = map.generated.items[0];
        map.generated.items[0].quote_start += 1;
        try std.testing.expect(renderer.tableNestedFontForTag(tag) == null);
        map.generated.items[0] = first_event;
        map.generated.items[0].token = if (name[0] == 'b') .b_close else .i_close;
        try std.testing.expect(renderer.tableNestedFontForTag(tag) == null);
        map.generated.items[0] = first_event;
        var wrong = tag; wrong.closing = true;
        try std.testing.expect(renderer.tableNestedFontForTag(wrong) == null);
        wrong = tag; wrong.attrs = "title='foreign'";
        try std.testing.expect(renderer.tableNestedFontForTag(wrong) == null);
        renderer.inline_missing = .{ .bytes = quoted.bytes, .unknown = true };
        try std.testing.expect(renderer.tableNestedFontForTag(tag) == null);
        renderer.inline_missing = quoted;
        renderer.table_link_quote_source = null;
        try std.testing.expect(renderer.tableNestedFontForTag(tag) == null);
        renderer.table_viewport_cell_source = null;
    }
}

