            1 => projection.observed_source = null,
            2 => refused.figure_class_source_binding.?.scope = &scope,
            3 => refused.figure_class_source_binding.?.owner.lost_missing_range = true,
            4 => changed_output.ranges = &.{.{ .start = 0, .end = 1, .occurrence = 1 }},
            5 => changed_map.original = try a.dupe(u8, map.original),
            6 => changed_map.output = try a.dupe(u8, map.output),
            else => refused.heading_source_aliases = .empty,
