    try std.testing.expect(!fixture.renderer.quoteClassOutputOwned(&map, quoted, fixture.scope));
    fixture.renderer.figure_class_source_binding.?.owner = prior;
    try std.testing.expect(fixture.renderer.quoteClassOutputOwned(&map, quoted, fixture.scope));
}


