    try ns.attachInterwikiMap("w\t1\t0\t0\t0\thttps://th.wikipedia.org/wiki/$1\nself\t1\t1\t0\t0\thttps://unused.example/$1\n");
    const context: Context = .{ .namespace_catalog = &ns };
    for ([_]struct { encoded: []const u8, literal: []const u8, target: ?[]const u8 }{
        .{ .encoded = "w:แบกซเตอร์%27s_transcription_for_Middle_Chinese", .literal = "w:แบกซเตอร์'s_transcription_for_Middle_Chinese", .target = "https://th.wikipedia.org/wiki/%E0%B9%81%E0%B8%9A%E0%B8%81%E0%B8%8B%E0%B9%80%E0%B8%95%E0%B8%AD%E0%B8%A3%E0%B9%8C%27s_transcription_for_Middle_Chinese" },
        .{ .encoded = "Page%20Name", .literal = "Page Name", .target = "Page Name" },
        .{ .encoded = "Caf%C3%A9", .literal = "Café", .target = "Café" },
        .{ .encoded = "Page%23Part%20one", .literal = "Page#Part one", .target = "Page#Part one" },
        .{ .encoded = "%3ACategory%3AKnown", .literal = ":Category:Known", .target = "Category:Known" },
        .{ .encoded = "Category%3AKnown", .literal = "Category:Known", .target = null },
        .{ .encoded = "self%3APage%23Part", .literal = "self:Page#Part", .target = "Page#Part" },
        .{ .encoded = "Plus%2Bsign", .literal = "Plus+sign", .target = "Plus+sign" },
        .{ .encoded = "100%25", .literal = "100%", .target = "100%" },
        .{ .encoded = "Page%GG", .literal = "Page%GG", .target = "Page%GG" },
        .{ .encoded = "Page%2", .literal = "Page%2", .target = "Page%2" },
    }) |case| {
        var actual: Renderer = .{ .a = a, .context = context };
        var reference: Renderer = .{ .a = a, .context = context };
        const suffix = "|''caption'']] after [[Other|other]] [https://example.test/%27?q=%2527 external]";
        const body = try actual.renderBody(try std.mem.concat(a, u8, &.{ "before [[", case.encoded, suffix }));
        const expected_body = try reference.renderBody(try std.mem.concat(a, u8, &.{ "before [[", case.literal, suffix }));
        try std.testing.expect(!actual.fallbacks.any());
        try std.testing.expectEqualDeep(reference.fallbacks, actual.fallbacks);
        const stored = try FormattingScopeTest.encode(a, &actual, body);
        const expected = try FormattingScopeTest.encode(a, &reference, expected_body);
        try std.testing.expectEqualDeep(expected, stored);
        const codec = @import("blob_encoder").presentation_codec;
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), try codec.encodeAlloc(a, stored));
        try FigureProducerTest.roundtrip(a, &actual, body);
        var caption: usize = 0; var other: usize = 0; var external: usize = 0;
        for (body) |block| for (block.spans) |span| {
            if (std.mem.eql(u8, span.text, "caption")) {
                caption += 1; try std.testing.expect(span.flags.italic);
                try std.testing.expectEqualStrings(case.target orelse return error.TestUnexpectedResult, span.target);
            }
            if (std.mem.eql(u8, span.text, "other")) { other += 1; try std.testing.expectEqualStrings("Other", span.target); }
            if (std.mem.eql(u8, span.text, "external")) { external += 1; try std.testing.expectEqualStrings("https://example.test/%27?q=%2527", span.target); }
        };
        try std.testing.expectEqual(@as(usize, if (case.target != null) 1 else 0), caption);
        try std.testing.expectEqual(@as(usize, 1), other); try std.testing.expectEqual(@as(usize, 1), external);
    }
    // Decode once before fragment splitting; residual escapes in fragments
    // remain literal fragment characters, whereas a residual page escape is invalid.
    var fragment: Renderer = .{ .a = a, .context = context };
    const spans = try fragment.parseSpans("[[Page%23part%2527|fragment]] [[Page%23part%GG|malformed]]", .{});
    var links: usize = 0;
    for (spans) |span| if (span.kind == .link) {
        try std.testing.expectEqualStrings(if (links == 0) "Page#part%27" else "Page#part%GG", span.target); links += 1;
    };
    try std.testing.expectEqual(@as(usize, 2), links); try std.testing.expect(!fragment.fallbacks.any());
    for ([_][]const u8{ "Page%2527", "Page%00", "Page%FF", "Page%C3%28", "Page%EF%BF%BD", "Page%3C", "Page%7C", "https%3A//example.test/" }) |raw| {
        var refused: Renderer = .{ .a = a, .context = context };
        const source = try std.mem.concat(a, u8, &.{ "[[", raw, "|label]]" });
        const values = try refused.parseSpans(source, .{});
        try std.testing.expect(refused.fallbacks.literal_markup);
        try std.testing.expectEqualStrings(source, try flattened(a, values));
        for (values) |span| try std.testing.expectEqualStrings("", span.target);
    }
    var protected: Renderer = .{ .a = a, .context = context };
    const unchanged = try protected.parseSpans("<nowiki>[[Page%27]]</nowiki>", .{});
    try std.testing.expectEqualStrings("[[Page%27]]", try flattened(a, unchanged));
    for (unchanged) |span| try std.testing.expectEqualStrings("", span.target);
    var languages = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").english_test_fixture); defer languages.deinit();
    try languages.attachInterwikiMap(interlanguage_test_map);
    const language_context: Context = .{ .title = "Host", .namespace_catalog = &languages };
    const prepared = try preparePageExternalLinksAlloc(a, "A\n[[%65n%3AOther]]\nB", language_context);
    try std.testing.expectEqualStrings("A\nB", prepared.source);
    for ([_][]const u8{ "A\n[[en%3APage%2527]]\nB", "A\n[[%3Aen%3AOther|visible]]\nB", "<nowiki>[[%65n%3AOther]]</nowiki>" }) |raw| {
        const kept = try preparePageExternalLinksAlloc(a, raw, language_context);
        try std.testing.expectEqualStrings(raw, kept.source);
    }
}


test "ordinary body paragraph copy retains page preflight custody across a Missing tail without token authority" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = ":root{--paper:white}", .base_url = "" }}, &.{}); defer styles.deinit();
    const operation = "<div>prefix</div>\n\ntail [[After|action]]";
    for (0..4) |mode| {
        var fixture = try LiteralDivCustomRootTest.init(a, &styles, operation);
        const renderer = &fixture.renderer;
        const start = std.mem.indexOf(u8, fixture.source, "tail ").?;
        const original = fixture.source[start..];
        const input = if (mode == 1) try a.dupe(u8, original) else original;
        if (mode == 2) renderer.body_missing.?.lost_missing_range = true;
        if (mode == 3) renderer.source_element_binding = null;
        const spans = try renderer.parseBodySpans(input, .{});
        try std.testing.expectEqualStrings("tail action missing", try flattened(a, spans));
        var actions: usize = 0;
        for (spans) |span| if (span.kind == .link) {
            actions += 1; try std.testing.expectEqualStrings("After", span.target);
            try std.testing.expectEqualStrings("action", span.text);
        };
        try std.testing.expectEqual(@as(usize, 1), actions);
        try std.testing.expect(renderer.plain_body_source_copy == null);
        try std.testing.expect(renderer.body_missing.?.unknown and renderer.body_missing.?.ranges.len == 1);
        try std.testing.expectEqual(mode != 0, renderer.fallbacks.unresolved_table_style);
        if (mode != 0) continue;
        try std.testing.expect(!renderer.fallbacks.any() and renderer.page_ancestor_effect == null);
        try std.testing.expect(renderer.heading_source_aliases.items.len != 0);
        const copy = renderer.heading_source_aliases.items[0];
        try std.testing.expect(copy.original.ptr == original.ptr and copy.original.len == original.len);
        try std.testing.expect(copy.copied.ptr != original.ptr and std.mem.eql(u8, copy.copied, original));
        try std.testing.expect(renderer.pagePreflightCopyOwned(fixture.source, copy.copied));
        // Its Missing overlap remains unavailable to token-level factories.
        const tracked = try missingSlice(a, renderer.body_missing.?, original);
        try std.testing.expect(tracked.ranges.len == 1 and tracked.unknown);
        try std.testing.expect(renderer.pageStyleCopiedAnchor(tracked, tracked.bytes) == null);
        const blocks = [_]Block{.{ .kind = .paragraph, .spans = spans }};
        const stored = try FormattingScopeTest.encode(a, renderer, &blocks);
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeAlloc(a, stored);
        try std.testing.expectEqualDeep(stored, try codec.decodeAlloc(a, bytes, stored.entry.title, .language,
            .{ .heading = stored.entry.language.?, .code = stored.entry.language_code }));
    }
}


const LiteralDivNestedCustomTest = struct {
    const variable_source = "<div style='--paper:var(--ink);padding:1px'><div style='--ink:blue;background-color:var(--paper);border:1px solid var(--ink);padding:5px'>body '''bold''' [[Target#part|label]]</div></div>\n\ntail [[After|action]]";
    const literal_source = "<div style='padding:1px'><div style='background-color:#235923;border:1px solid blue;padding:5px'>body '''bold''' [[Target#part|label]]</div></div>\n\ntail [[After|action]]";
    const chain = "<div style='--paper:var(--ink)'><div><div>nested [[Target|label]]</div></div></div>";
    fn nodes(fixture: *LiteralDivFlexTest) !struct { parent: *const table_style_profile.TextElement, inner: syntax.Tag } {
        const outer = try fixture.renderer.textElement(fixture.outer, null, "");
        const middle = syntax.tagAt(fixture.source, fixture.outer.end).?;
        return .{ .parent = try fixture.renderer.textElement(middle, outer, ""), .inner = syntax.tagAt(fixture.source, middle.end).? };
    }
};

test "nested literal DIV custom cascade preserves both root environments complete body actions and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = LiteralDivCustomRootTest; const N = LiteralDivNestedCustomTest;
    var phase = @src(); errdefer std.debug.print("TH_NESTED_CUSTOM source={s}:{d}\n", .{ phase.file, phase.line });
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = ":root{--ink:red;--paper:white}", .base_url = "" }}, &.{}); defer styles.deinit();
    try T.attach(&styles);
    var fixture = try T.init(a, &styles, N.variable_source); const renderer = &fixture.renderer;
    const outer = try renderer.textElement(fixture.outer, null, "");
    const inner = syntax.tagAt(fixture.source, fixture.outer.end).?;
    const known = renderer.literalDivContextForTag(inner) orelse return error.TestUnexpectedResult;
    try std.testing.expect(known.proof.parent_start == 0 and renderer.literalDivParent(known, outer));
    // The outer declaration computes --paper before the child's own --ink
    // override. A logical palette or re-evaluation of inherited var() is wrong.
    const palette = (try renderer.customElement(inner, .{ .text_element = outer,
        .custom_properties = styles.custom_properties.?.root_environment })).?;
    try std.testing.expect(palette.complete);
    try std.testing.expectEqualStrings("#235923", palette.get("--paper").known);
    try std.testing.expectEqualStrings("blue", palette.get("--ink").known);
    phase = @src();
    const body = try renderer.renderBodyWithMissing(renderer.body_missing.?);
    try std.testing.expect(!renderer.fallbacks.any());
    const outer_box = body[0].container orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(presentation_types.StyleEdges.all(.{ .unit = .px, .value = 1 }), outer_box.style.padding.?);
    const inner_box = outer_box.blocks[0].container orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("#235923", inner_box.style.background.?.rgb);
    try std.testing.expectEqualDeep(presentation_types.StyleEdges.all(.{ .unit = .px, .value = 5 }), inner_box.style.padding.?);
    try std.testing.expect(inner_box.style.border != null);
    try std.testing.expectEqualStrings("body bold label", try flattened(a, inner_box.blocks[0].spans));
    var bold = false; var actions: usize = 0;
    for (inner_box.blocks[0].spans) |span| {
        bold = bold or (span.flags.bold and std.mem.eql(u8, span.text, "bold"));
        if (span.kind == .link) {
            actions += 1; try std.testing.expectEqualStrings("Target#part", span.target);
            try std.testing.expectEqualStrings("label", span.text);
        }
    }
    try std.testing.expect(bold and actions == 1);
    var tail = false;
    for (body[1..]) |block| for (block.spans) |span| if (span.kind == .link) {
        try std.testing.expectEqualStrings("After", span.target); try std.testing.expectEqualStrings("action", span.text); tail = true;
    };
    try std.testing.expect(tail);
    phase = @src();
    var reference_styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = ":root{--ink:red;--paper:white}", .base_url = "" }}, &.{}); defer reference_styles.deinit();
    var reference = try T.init(a, &reference_styles, N.literal_source);
    const expected = try FormattingScopeTest.encode(a, &reference.renderer, try reference.renderer.renderBodyWithMissing(reference.renderer.body_missing.?));
    const actual = try FormattingScopeTest.encode(a, renderer, body);
    try std.testing.expect(!reference.renderer.fallbacks.any());
    try std.testing.expectEqualDeep(expected, actual);
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeAlloc(a, actual);
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, expected));
    try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, bytes, actual.entry.title, .language,
        .{ .heading = actual.entry.language.?, .code = actual.entry.language_code }));
    try std.testing.expect(renderer.body_missing.?.unknown and fixture.projection.original.unknown);
    try std.testing.expectEqual(@as(usize, 1), fixture.projection.original.ranges.len);
    // A registered child copy retains the same parent chain and local cascade.
    phase = @src();
    var copied = try T.init(a, &styles, N.variable_source);
    const copied_parent = try copied.renderer.textElement(copied.outer, null, "");
    const opening = syntax.tagAt(copied.source, copied.outer.end).?;
    const pair = syntax.matchingTag(copied.source, opening).?;
    const owned = try copied.renderer.missingSliceWithHeadingSource(copied.renderer.body_missing.?, copied.source[copied.outer.end..pair.end]);
    copied.renderer.body_missing = owned;
    const tag = syntax.tagAt(owned.bytes, 0).?;
    try std.testing.expect(owned.bytes.ptr != copied.source[copied.outer.end..].ptr and owned.unknown and owned.ranges.len == 0);
    const copied_palette = (try copied.renderer.customElement(tag, .{ .text_element = copied_parent })).?;
    try std.testing.expectEqualDeep(palette, copied_palette);
    copied.renderer.heading_source_aliases.clearRetainingCapacity();
    try std.testing.expect((try copied.renderer.customElement(tag, .{ .text_element = copied_parent })).?.get("--paper") == .unknown);
}

test "nested literal DIV palette refuses broken physical chains taint foreign roots and uncertain custom declarations" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = LiteralDivCustomRootTest; const N = LiteralDivNestedCustomTest;
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = ":root{--ink:red;--paper:white}", .base_url = "" }}, &.{}); defer styles.deinit();
    try T.attach(&styles);
    for (0..14) |mode| {
        errdefer std.debug.print("TH_NESTED_CUSTOM_REFUSAL mode={d}\n", .{mode});
        var fixture = try T.init(a, &styles, N.chain);
        const chain = try N.nodes(&fixture); const middle = @constCast(chain.parent);
        const root = @constCast(fixture.scope.page_style_complete_root.?);
        const other = @constCast(root.alternative_ancestry.?);
        var tag = chain.inner;
        switch (mode) {
            0 => middle.source_literal_div = null,
            1 => middle.source_literal_div_current = try a.dupe(u8, middle.source_literal_div_current.?),
            2 => middle.parent = root,
            3 => middle.physical_ancestry_complete = false,
            4 => middle.ancestor_class_source = try a.dupe(u8, fixture.source),
            5 => fixture.projection.observed_source = null,
            6 => fixture.projection.copies = &.{},
            7 => fixture.renderer.body_missing.?.lost_missing_range = true,
            8 => fixture.projection.original.ranges = &.{.{ .start = 1, .end = 2, .occurrence = 2 }},
            9 => fixture.scope.source_literal_divs_source = try a.dupe(u8, fixture.source),
            10 => {
                const foreign = try a.dupe(u8, fixture.source);
                const start = @intFromPtr(chain.inner.name.ptr) - @intFromPtr(fixture.source.ptr) - 1;
                tag = syntax.tagAt(foreign, start).?;
            },
            11 => root.observed_custom_environment = null,
            12 => other.observed_custom_environment = null,
            13 => other.observed_custom_environment = .{ .complete = true, .values = &.{
                .{ .name = "--ink", .value = .{ .known = "blue" } }, .{ .name = "--paper", .value = .{ .known = "#ffffe0" } },
            } },
            else => unreachable,
        }
        const denied = (try fixture.renderer.customElement(tag, .{ .text_element = middle, .custom_properties = T.environment })).?;
        try std.testing.expect(denied.get("--paper") == .unknown);
    }
    // A possible own custom declaration keeps its existing unknown winner. Both
    // roots agreeing does not discharge a pseudo/conditional selector obligation.
    var uncertain = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = "div:hover{--ink:purple}", .base_url = "" }}, &.{}); defer uncertain.deinit();
    try table_style_profile.attachCustomProperties(&uncertain, &.{.{ .css = "div:hover{--ink:purple}", .base_url = "" }},
        .{ .ancestors = &.{.{ .tag = "html", .root = true }} });
    var unknown = try T.init(a, &uncertain, N.chain); const chain = try N.nodes(&unknown);
    try std.testing.expect((try unknown.renderer.customElement(chain.inner, .{ .text_element = chain.parent })).?.get("--paper") == .unknown);
}


test "literal Table body identity uses the trimmed closing DIV coordinate without widening ordinary tails" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const prefix = "<div>\n{|\n|-\n| [[Target#part|label]]\n|}";
    const opening = std.mem.indexOf(u8, prefix, "{|").?;
    const nodes = [_]table_style_profile.ObservedStyleNode{
        .{ .tag = "div", .attributes = &.{}, .parent = null },
        .{ .tag = "table", .attributes = &.{}, .parent = 0 },
        .{ .tag = "tbody", .attributes = &.{}, .parent = 1 },
        .{ .tag = "tr", .attributes = &.{}, .parent = 2 },
        .{ .tag = "td", .attributes = &.{}, .parent = 3 },
    };
    var styles = try table_style_profile.parseAlloc(a, ""); defer styles.deinit();
    const shallow: table_style_profile.TableContainingDirectionContext = .{ .styles = &styles, .nodes = nodes[0..2], .root = 0, .table = 1 };
    var renderer: Renderer = .{ .a = a, .context = .{} };
    // The maintained HTML tokenizer normalizes the lexical slash on a paired
    // DIV closer. Exercise both spellings through the same complete body proof.
    for ([_][]const u8{ "", " ", "\t", " \t " }) |space| {
      for ([_][]const u8{ "</div>", "</div/>" }) |closing| {
        const tag = syntax.tagAt(closing, 0) orelse return error.TestUnexpectedResult;
        try std.testing.expect(tag.closing and !tag.self_closing and tag.attrs.len == 0);
        const source = try std.mem.concat(a, u8, &.{ prefix, space, closing });
        const identity = (try Renderer.literalTableBodyIdentityAlloc(a, source, opening, .{}, &nodes, 1)) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(prefix.len, identity.end);
        try std.testing.expectEqual(@as(usize, 1), identity.cells.len);
        try std.testing.expectEqual(@as(u32, 4), identity.cells[0].subject);
        try std.testing.expectEqualStrings("[[Target#part|label]]", identity.cells[0].source_body);
        try std.testing.expect(Renderer.wikiClassContains(source, identity.cells[0].source_body));
        // The exception belongs to the complete literal-body join only.
        try std.testing.expect((try renderer.tableViewportWikiGraphWithFamily(source, opening, shallow, false, false, false)) == null);
        try std.testing.expect((try renderer.tableViewportWikiGraphWithFamily(source, opening, shallow, true, false, false)) == null);
        try std.testing.expect((try Renderer.literalTableBodyIdentityAlloc(a, source, opening + 1, .{}, &nodes, 1)) == null);
        try std.testing.expect((try Renderer.literalTableBodyIdentityAlloc(a, source, opening, .{}, &nodes, 0)) == null);
      }
    }
    for ([_][]const u8{ " x</div>", " </span>", " </div class='x'>", " </div x/>", " <!--x--></div>", " <div>", " </div" }) |tail| {
        const source = try std.mem.concat(a, u8, &.{ prefix, tail });
        try std.testing.expect((try Renderer.literalTableBodyIdentityAlloc(a, source, opening, .{}, &nodes, 1)) == null);
    }
}


test "seeded ordinary local targets retain exact quote copies formatting actions and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    const Proof = struct {
        source: []const u8,
        fn resolve(raw: ?*const anyopaque, _: A, operation: TableSourceAnchorOperation) Error!?[]const u8 {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
            if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
                !Renderer.wikiClassContains(self.source, operation.token) or !Renderer.wikiClassContains(operation.token, operation.target) or
                !std.mem.eql(u8, operation.target, "gh")) return null;
            return "Resolved";
        }
    };
    for ([_][]const u8{ "", "''" }) |marker| {
        const source = try std.mem.concat(a, u8, &.{ "before ", marker, "[[gh|visible]]a", marker, " after\n[https://example.org]\n" });
        const proof = Proof{ .source = source };
        const context: Context = .{ .namespace_catalog = &ns, .observe_source_elements = true,
            .local_link_targets = .{ .source = source, .namespace_sha256 = ns.source_sha256, .context = &proof, .resolve = Proof.resolve } };
        const numbered = try preparePageExternalLinksWithMissingAlloc(a, MissingText.untracked(source), context);
        const projection = numbered.source_element_projection orelse return error.TestUnexpectedResult;
        var renderer: Renderer = .{ .a = a, .context = context, .body_missing = numbered.missing,
            .local_link_binding = .{ .projection = &projection, .owner = numbered.missing, .page_start = 0 } };
        renderer.context.external_links_prepared = true;
        var scan = QuoteBoundaryScan.initWithContext(numbered.source, null, context); defer scan.deinit();
        renderer.next_quote_seed = try scan.at(a, 0, null);
        const aliases_before = renderer.heading_source_aliases.items.len;
        const spans = try renderer.parseBodySpans(numbered.source, .{});
        try std.testing.expectEqual(aliases_before, renderer.heading_source_aliases.items.len);
        var label: std.ArrayList(u8) = .empty; var external: usize = 0;
        for (spans) |span| {
            if (span.kind == .link) {
                try std.testing.expectEqualStrings("Resolved", span.target);
                try std.testing.expectEqual(marker.len != 0, span.flags.italic);
                try label.appendSlice(a, span.text);
            }
            if (span.kind == .external_link) {
                try std.testing.expectEqualStrings("https://example.org", span.target);
                try std.testing.expectEqualStrings("[1]", span.text); external += 1;
            }
        }
        try std.testing.expectEqualStrings("visiblea", label.items);
        try std.testing.expectEqual(@as(usize, 1), external);
        const codec = @import("blob_encoder").presentation_codec;
        const blocks = [_]Block{.{ .kind = .paragraph, .spans = spans }};
        const bytes = try codec.encodeBuildAlloc(a, &[_]Span{}, &[_]struct { level:u8=0,title:[]const u8="",blocks:[]const Block }{.{.blocks=&blocks}}, presentation_types.Layout{}, &.{}, &.{});
        const stored = try codec.decodeAlloc(a, bytes, "Entry", .language, .{ .code="en",.heading="English" });
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
    }
}

test "local target quote copies refuse foreign maps missing source and revoked authority" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    const source = try a.dupe(u8, "''[[gh|visible]]a''");
    const Callback = struct {
        fn resolve(_: ?*const anyopaque, _: A, _: TableSourceAnchorOperation) Error!?[]const u8 { return "Resolved"; }
    };
    const selected: LocalLinkTargetSource = .{ .source = source, .namespace_sha256 = ns.source_sha256, .context = null, .resolve = Callback.resolve };
    for (0..7) |mode| {
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .local_link_targets = selected }, .body_missing = MissingText.untracked(source) };
        var map: QuoteSourceMap = .{}; defer map.deinit(a);
        const quoted = try normalizeWikiQuotesMappedWithMissing(a, MissingText.untracked(source), 0, false, renderer.context, null, &map);
        var output = quoted;
        switch (mode) {
            1 => renderer.context.local_link_targets.?.source = try a.dupe(u8, source),
            2 => renderer.body_missing.?.lost_missing_range = true,
            3 => renderer.body_missing.?.unknown = true,
            4 => renderer.context.local_link_targets.?.namespace_sha256[0] ^= 1,
            5 => output.bytes = try a.dupe(u8, output.bytes),
            6 => output.ranges = &.{.{ .start = 0, .end = 1, .occurrence = 1 }},
            else => {},
        }
        try renderer.registerLocalTargetQuoteCopies(&map, output);
        try std.testing.expectEqual(@as(usize, if (mode == 0) 1 else 0), renderer.heading_source_aliases.items.len);
        if (mode == 0) {
            const copy = renderer.heading_source_aliases.items[0];
            try std.testing.expectEqualStrings("[[gh|visible]]", copy.copied);
            try std.testing.expectEqualStrings("[[gh|visible]]", copy.original);
            try std.testing.expect(Renderer.wikiClassContains(source, copy.original));
            try std.testing.expect(!Renderer.wikiClassContains(source, copy.copied));
            renderer.context.local_link_targets.?.source = try a.dupe(u8, source);
            try std.testing.expect(try renderer.localLinkTarget(copy.copied, copy.copied[2..4]) == null);
        }
    }
}

const LiteralWikiCellTest = struct {
    const operation = "<div style='--paper:var(--ink);padding:1px'>\n{| style='margin:0'\n|- style='--ink:blue'\n|colspan=2 style='font-size:90%;--paper:yellow'|<div style='background-color:var(--paper);padding:2px'>first [[A|alpha]]\n<div style='border:1px solid var(--ink)'>second [[B#part|beta]]</div>\n</div>\n|}\n</div>";
    const literal = "<div style='padding:1px'>\n{| style='margin:0'\n|-\n|colspan=2 style='font-size:90%'|<div style='background-color:yellow;padding:2px'>first [[A|alpha]]\n<div style='border:1px solid blue'>second [[B#part|beta]]</div>\n</div>\n|}\n</div>";
    fn init(a: A, styles: *const table_style_profile.Profile, value: []const u8) !LiteralDivFlexTest {
        var fixture = try LiteralDivCustomRootTest.init(a, styles, value);
        fixture.renderer.heading_source = fixture.source;
        const source = fixture.source;
        const table = std.mem.indexOf(u8, source, "{| ").?;
        const table_open_end = std.mem.indexOfScalarPos(u8, source, table, '\n').?;
        const row = std.mem.indexOfPos(u8, source, table_open_end, "|-").?;
        const row_end = std.mem.indexOfScalarPos(u8, source, row, '\n').?;
        const attrs = row_end + 2;
        const empty = source[attrs] == '\n';
        const body = if (empty) attrs else std.mem.indexOfPos(u8, source, attrs, "|<div").? + 1;
        const table_end = std.mem.indexOfPos(u8, source, body, "|}").? + 2;
        const body_end = table_end - 3;
        const cap: table_style_profile.SourceWikiCellParentProof = .{ .parent_start = 0,
            .table_start = table, .table_open_end = table_open_end, .table_end = table_end,
            .row_start = row, .row_end = row_end, .attrs_start = attrs, .attrs_end = if (empty) attrs else body - 1,
            .body_start = body, .body_end = body_end, .header = false };
        for (@constCast(fixture.scope.source_literal_divs)) |*proof| if (proof.range.anchor_start == body + @as(usize, if (empty) 1 else 0)) {
            proof.parent_start = null; proof.wiki_cell_parent = cap;
        };
        return fixture;
    }
    fn getCapability(fixture: LiteralDivFlexTest) table_style_profile.SourceWikiCellParentProof {
        for (fixture.scope.source_literal_divs) |proof| if (proof.wiki_cell_parent) |value| return value;
        unreachable;
    }
    fn copies(a: A, source: []const u8) ![]HeadingSourceCopy {
        var result: std.ArrayList(HeadingSourceCopy) = .empty;
        var at: usize = 0;
        while (at < source.len) {
            const stop = std.mem.indexOfScalarPos(u8, source, at, '\n') orelse source.len;
            if (stop != at) try result.append(a, .{ .start = at, .original = source[at..stop] });
            at = if (stop == source.len) stop else stop + 1;
        }
        return result.toOwnedSlice(a);
    }
};

test "literal wiki cell copied interval preserves exact LF gaps and refuses foreign lost generated or incomplete custody" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer styles.deinit();
    var fixture = try LiteralWikiCellTest.init(a, &styles, LiteralWikiCellTest.operation);
    const renderer = &fixture.renderer; const cap = LiteralWikiCellTest.getCapability(fixture);
    const original = fixture.source[cap.body_start..cap.body_end];
    const copied = try a.dupe(u8, original);
    const copies = try LiteralWikiCellTest.copies(a, original);
    const replay: MissingText = .{ .bytes = copied, .unknown = true };
    try std.testing.expect(copies.len >= 3 and renderer.literalWikiCellCopies(original, replay, copies));
    try std.testing.expect(renderer.registeredCaptionOriginal(copied) == null);
    for (0..10) |mode| {
        errdefer std.debug.print("LITERAL_CELL_COPY mode={d}\n", .{mode});
        var changed = replay;
        const records = try a.dupe(HeadingSourceCopy, copies);
        var selected: []const HeadingSourceCopy = records;
        const ranges = [_]missing_dependency.Range{.{ .start = 0, .end = 1, .occurrence = 1 }};
        switch (mode) {
            0 => records[0].original = try a.dupe(u8, records[0].original),
            1 => selected = records[1..],
            2 => { const first = records[0]; records[0] = records[1]; records[1] = first; },
            3 => records[1].start -= 1,
            4 => changed.lost_missing_range = true,
            5 => changed.ranges = &ranges,
            6 => { const bytes = try a.dupe(u8, copied); bytes[records[0].original.len] = ' '; changed.bytes = bytes; },
            7 => changed.bytes = copied[0 .. copied.len - 1],
            8 => changed.generated_source = copied,
            9 => renderer.source_element_binding = null,
            else => unreachable,
        }
        try std.testing.expect(!renderer.literalWikiCellCopies(original, changed, selected));
    }
}

