test "literal wiki cell parent is operation bound and preserves physical ancestry and alternative custom states" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = ":root{--paper:white;--ink:red}", .base_url = "" }}, &.{}); defer styles.deinit();
    try LiteralDivCustomRootTest.attach(&styles);
    var fixture = try LiteralWikiCellTest.init(a, &styles, LiteralWikiCellTest.operation);
    const renderer = &fixture.renderer; const cap = LiteralWikiCellTest.getCapability(fixture);
    const outer = try renderer.textElement(fixture.outer, null, "");
    // Controlled normal-parser nodes deliberately have no physical edge or
    // distant-root anchors. The operation supplies exact live token custody.
    var table: table_style_profile.TextElement = .{ .tag = "table", .parent = outer };
    var row: table_style_profile.TextElement = .{ .tag = "tr", .parent = &table };
    var cell: table_style_profile.TextElement = .{ .tag = "td", .parent = &row };
    var operation: Renderer.LiteralWikiTableOperation = .{ .tracked = renderer.body_missing.?,
        .table_opening = fixture.source[cap.table_start..cap.table_open_end], .row_opening = fixture.source[cap.row_start..cap.row_end],
        .cell_attrs = fixture.source[cap.attrs_start..cap.attrs_end], .outer_parent = outer };
    renderer.literal_wiki_table_operation = &operation; renderer.typed_table_depth = 1;
    const original = fixture.source[cap.body_start..cap.body_end];
    const copied = try a.dupe(u8, original); const copies = try LiteralWikiCellTest.copies(a, original);
    const replay: MissingText = .{ .bytes = copied, .unknown = true };
    var live = (try renderer.bindLiteralWikiCell(replay, copies, .{ .text_element = &cell })) orelse return error.TestUnexpectedResult;
    renderer.literal_wiki_cell = &live; renderer.body_missing = replay;
    const tag = syntax.tagAt(copied, 0).?;
    const known = renderer.literalDivContextForTag(tag) orelse return error.TestUnexpectedResult;
    const physical = renderer.literalWikiCellParent(known, &cell) orelse return error.TestUnexpectedResult;
    var node = physical;
    for ([_][]const u8{ "td", "tr", "tbody", "table" }) |name| {
        try std.testing.expectEqualStrings(name, node.tag);
        try std.testing.expect(node.ancestry_complete and node.physical_ancestry_complete and node.alternative_ancestry != null);
        try std.testing.expectEqualStrings(name, node.alternative_ancestry.?.tag);
        node = node.parent.?;
    }
    try std.testing.expect(node == outer);
    const generated = try renderer.textElement(tag, &cell, "");
    try std.testing.expect(generated.parent == physical and generated.source_literal_div == known.proof);
    try std.testing.expect(generated.alternative_ancestry.?.parent == physical.alternative_ancestry);
    const environment = (try renderer.literalDivCustomEnvironment(known, &cell, styles.custom_properties.?)).?;
    try std.testing.expectEqualStrings("yellow", environment.get("--paper").known);
    try std.testing.expectEqualStrings("blue", environment.get("--ink").known);
    const alternate_root = @constCast(fixture.scope.page_style_complete_root.?.alternative_ancestry.?);
    const saved_environment = alternate_root.observed_custom_environment;
    alternate_root.observed_custom_environment = null;
    try std.testing.expect((try renderer.literalDivCustomEnvironment(known, &cell, styles.custom_properties.?)) == null);
    alternate_root.observed_custom_environment = saved_environment;
    @constCast(outer).physical_ancestry_complete = false;
    try std.testing.expect(renderer.literalWikiCellParent(known, &cell) == null);
    @constCast(outer).physical_ancestry_complete = true;
    live.copied.lost_missing_range = true;
    try std.testing.expect(renderer.literalWikiCellParent(known, &cell) == null);
    live.copied.lost_missing_range = false;
    var foreign: table_style_profile.TextElement = .{ .tag = "td", .parent = &row };
    try std.testing.expect(renderer.literalWikiCellParent(known, &foreign) == null);
    const saved_scope = live.scope;
    var foreign_scope = saved_scope.*; live.scope = &foreign_scope;
    try std.testing.expect(renderer.literalWikiCellParent(known, &cell) == null);
    live.scope = saved_scope;
    renderer.literal_wiki_cell = null;
    try std.testing.expect(renderer.literalWikiCellParent(known, &cell) == null);
    renderer.body_missing = fixture.projection.original;
    for (0..8) |mode| {
        errdefer std.debug.print("LITERAL_CELL_BIND mode={d}\n", .{mode});
        var changed = operation;
        const saved = renderer.source_element_binding;
        defer renderer.source_element_binding = saved;
        switch (mode) {
            0 => changed.table_opening = try a.dupe(u8, changed.table_opening),
            1 => changed.row_opening = try a.dupe(u8, changed.row_opening.?),
            2 => changed.cell_attrs = try a.dupe(u8, changed.cell_attrs.?),
            3 => changed.row_opening = null,
            4 => changed.outer_parent = fixture.scope.page_style_complete_root,
            5 => changed.tracked.lost_missing_range = true,
            6 => changed.tracked.generated_source = changed.tracked.bytes,
            7 => renderer.source_element_binding = null,
            else => unreachable,
        }
        renderer.literal_wiki_table_operation = &changed;
        try std.testing.expect((try renderer.bindLiteralWikiCell(replay, copies, .{ .text_element = &cell })) == null);
    }
    renderer.literal_wiki_table_operation = &operation;
    // The old copy registration cannot rescue a different issued source range.
    const old_cap = @constCast(known.proof).wiki_cell_parent;
    @constCast(known.proof).wiki_cell_parent.?.row_start += 1;
    try std.testing.expect((try renderer.bindLiteralWikiCell(replay, copies, .{ .text_element = &cell })) == null);
    @constCast(known.proof).wiki_cell_parent = old_cap;
}

