test "empty wiki cell delimiter computes own TD cascade and retains exact leading LF source custody" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = ":root{--paper:white}td{--paper:yellow;font-size:80%;font-weight:bold}", .base_url = "" }}, &.{}); defer styles.deinit();
    try table_style_profile.attachCustomProperties(&styles, &.{.{
        .css = ":root{--paper:white}td{--paper:yellow}", .base_url = "",
    }}, .{ .ancestors = &.{.{ .tag = "html", .root = true }} });
    var fixture = try LiteralWikiCellTest.init(a, &styles, EmptyLiteralWikiCellTest.source);
    const renderer = &fixture.renderer; const cap = LiteralWikiCellTest.getCapability(fixture);
    try std.testing.expectEqual(cap.attrs_start, cap.attrs_end);
    try std.testing.expectEqual(cap.attrs_end, cap.body_start);
    const outer = try renderer.textElement(fixture.outer, null, "");
    var table: table_style_profile.TextElement = .{ .tag = "table", .parent = outer };
    var row: table_style_profile.TextElement = .{ .tag = "tr", .parent = &table };
    var cell: table_style_profile.TextElement = .{ .tag = "td", .parent = &row };
    var operation: Renderer.LiteralWikiTableOperation = .{ .tracked = renderer.body_missing.?,
        .table_opening = fixture.source[cap.table_start..cap.table_open_end], .row_opening = fixture.source[cap.row_start..cap.row_end],
        .cell_attrs = fixture.source[cap.attrs_start..cap.attrs_end], .outer_parent = outer };
    renderer.literal_wiki_table_operation = &operation; renderer.typed_table_depth = 1;
    const tag: syntax.Tag = .{ .name = "td", .attrs = operation.cell_attrs.?, .end = 0, .closing = false, .self_closing = false };
    const inherited: Style = .{ .text_element = &row, .font_scale = 0.9, .font_scale_set = true, .font_scale_basis = .normal_body };
    const selected = (try renderer.emptyLiteralWikiCellStyle(tag, inherited, .{ .style = inherited, .formatting = .{} }, .{})) orelse return error.TestUnexpectedResult;
    try std.testing.expect(renderer.literal_wiki_cell_style == null);
    try std.testing.expect(selected.style.text_element != &row and selected.style.text_element != null);
    try std.testing.expectEqualStrings("td", selected.style.text_element.?.tag);
    try std.testing.expectApproxEqAbs(@as(f32, 0.72), selected.style.font_scale.?, 0.00001);
    try std.testing.expect(!selected.style.font_size_unknown and selected.formatting.bold);
    try std.testing.expectEqualStrings("yellow", selected.style.custom_properties.?.get("--paper").known);
    try std.testing.expect(selected.style.text_element.?.parent.?.parent.?.tag.len == "tbody".len);
    try std.testing.expectEqualStrings("tbody", selected.style.text_element.?.parent.?.parent.?.tag);
    // The complete source interval includes LF; the real cell replay starts
    // at its first DIV. Only that one omitted source byte is permitted.
    const original = fixture.source[cap.body_start..cap.body_end];
    try std.testing.expectEqual(@as(u8, '\n'), original[0]);
    const copied_source = try a.dupe(u8, fixture.source);
    var copied_operation = operation;
    copied_operation.tracked = MissingText.untracked(copied_source);
    copied_operation.table_opening = copied_source[cap.table_start..cap.table_open_end];
    copied_operation.row_opening = copied_source[cap.row_start..cap.row_end];
    copied_operation.cell_attrs = copied_source[cap.attrs_start..cap.attrs_end];
    renderer.literal_wiki_table_operation = &copied_operation;
    try std.testing.expect((try renderer.emptyLiteralWikiCellStyle(tag, inherited,
        .{ .style = inherited, .formatting = .{} }, .{})) == null);
    const saved_aliases = renderer.heading_source_aliases.items.len;
    try renderer.heading_source_aliases.append(a, .{ .copied = copied_source, .original = fixture.source });
    try std.testing.expect((try renderer.emptyLiteralWikiCellStyle(tag, inherited,
        .{ .style = inherited, .formatting = .{} }, .{})) != null);
    renderer.heading_source_aliases.shrinkRetainingCapacity(saved_aliases);
    renderer.literal_wiki_table_operation = &operation;
    const kept = original[1..]; const copied = try a.dupe(u8, kept);
    const records = try LiteralWikiCellTest.copies(a, kept);
    const replay: MissingText = .{ .bytes = copied, .unknown = true };
    var live = (try renderer.bindLiteralWikiCell(replay, records, selected.style)) orelse return error.TestUnexpectedResult;
    renderer.literal_wiki_cell = &live; renderer.body_missing = replay;
    const child = syntax.tagAt(copied, 0).?;
    const known = renderer.literalDivContextForTag(child) orelse return error.TestUnexpectedResult;
    const physical = renderer.literalWikiCellParent(known, selected.style.text_element) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("td", physical.tag);
    const mapped = renderer.registeredCaptionOriginal(copied) orelse return error.TestUnexpectedResult;
    try std.testing.expect(mapped.ptr == kept.ptr and mapped.len == kept.len);
    renderer.literal_wiki_cell = null; renderer.body_missing = fixture.projection.original;
    // A complete untrimmed replay is also valid; no general whitespace trim.
    const full = try a.dupe(u8, original);
    try std.testing.expect((try renderer.bindLiteralWikiCell(.{ .bytes = full, .unknown = true },
        try LiteralWikiCellTest.copies(a, original), .{ .text_element = &cell })) != null);
    for (0..10) |mode| {
        errdefer std.debug.print("EMPTY_TD_BIND mode={d}\n", .{mode});
        var changed = operation; var bad_replay = replay;
        const records_copy = try a.dupe(HeadingSourceCopy, records);
        const saved_binding = renderer.source_element_binding;
        defer renderer.source_element_binding = saved_binding;
        switch (mode) {
            0 => changed.cell_attrs = null,
            1 => { const other = try a.dupe(u8, fixture.source); changed.cell_attrs = other[cap.attrs_start..cap.attrs_start]; },
            2 => changed.row_opening = null,
            3 => changed.table_opening = try a.dupe(u8, changed.table_opening),
            4 => changed.outer_parent = fixture.scope.page_style_complete_root,
            5 => changed.tracked.lost_missing_range = true,
            6 => renderer.source_element_binding = null,
            7 => bad_replay.lost_missing_range = true,
            8 => records_copy[0].original = try a.dupe(u8, records_copy[0].original),
            9 => { const bytes = try a.dupe(u8, copied); bytes[0] = ' '; bad_replay.bytes = bytes; },
            else => unreachable,
        }
        renderer.literal_wiki_table_operation = &changed;
        try std.testing.expect((try renderer.bindLiteralWikiCell(bad_replay, records_copy, selected.style)) == null);
    }
    renderer.literal_wiki_table_operation = &operation;
    const proof = @constCast(known.proof); const saved = proof.wiki_cell_parent;
    defer proof.wiki_cell_parent = saved;
    proof.wiki_cell_parent.?.body_start += 1;
    try std.testing.expect((try renderer.bindLiteralWikiCell(replay, records, selected.style)) == null);
}

test "empty wiki cell full render keeps own font nested paint actions and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var phase = @src(); errdefer std.debug.print("EMPTY_TD_RENDER source={s}:{d}\n", .{phase.file, phase.line});
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    // This fixture proves the local physical cell cascade, not a complete
    // joined-page rule inventory. Exercise the unchanged joined CSS below.
    const css = ":root{--paper:white}td{--paper:yellow;font-size:80%;font-weight:bold}";
    var styles = try table_style_profile.parseForTargetAlloc(a, css, .screen); defer styles.deinit();
    try table_style_profile.attachCustomProperties(&styles, &.{.{
        .css = ":root{--paper:white}td{--paper:yellow}", .base_url = "",
    }}, .{ .ancestors = &.{.{ .tag = "html", .root = true }} });
    var fixture = try LiteralWikiCellTest.init(a, &styles, EmptyLiteralWikiCellTest.source);
    const renderer = &fixture.renderer;
    errdefer std.debug.print("EMPTY_TD_RENDER report={any} ancestor={any}\n", .{ renderer.fallbacks, renderer.page_ancestor_effect });
    phase = @src();
    const blocks = try renderer.renderBodyWithMissing(renderer.body_missing.?);
    try std.testing.expect(!renderer.fallbacks.any());
    try std.testing.expect(renderer.literal_wiki_cell == null and renderer.literal_wiki_cell_style == null);
    const outer = blocks[0].container orelse return error.TestUnexpectedResult;
    const table = outer.blocks[0].table orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), table.rows.len);
    try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
    const children = table.rows[0].cells[0].blocks orelse return error.TestUnexpectedResult;
    const box = children[0].container orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("#ffff00", box.style.background.?.rgb);
    try std.testing.expectEqualStrings("first alpha", try flattened(a, box.blocks[0].spans));
    const inner = box.blocks[1].container orelse return error.TestUnexpectedResult;
    try std.testing.expect(inner.style.height != null);
    try std.testing.expectEqualStrings("second beta", try flattened(a, inner.blocks[0].spans));
    var actions: usize = 0;
    for (box.blocks[0].spans) |span| if (span.kind == .link) {
        try std.testing.expectEqualStrings("A", span.target); try std.testing.expect(span.flags.bold);
        try std.testing.expectApproxEqAbs(@as(f32, 0.8), span.font_scale.?, 0.00001); actions += 1;
    };
    for (inner.blocks[0].spans) |span| if (span.kind == .link) { try std.testing.expectEqualStrings("B#part", span.target); actions += 1; };
    try std.testing.expectEqual(@as(usize, 2), actions);
    phase = @src();
    const stored = try FormattingScopeTest.encode(a, renderer, blocks);
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeAlloc(a, stored);
    try std.testing.expectEqualDeep(stored, try codec.decodeAlloc(a, bytes, stored.entry.title, .language,
        .{ .heading = stored.entry.language.?, .code = stored.entry.language_code }));
    // Exact same source and declarations under the joined-page contract must
    // still report the unproved ordinary TD rule. Own paint cannot waive it.
    phase = @src();
    var joined_styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = css, .base_url = "" }}, &.{}); defer joined_styles.deinit();
    try table_style_profile.attachCustomProperties(&joined_styles, &.{.{
        .css = ":root{--paper:white}td{--paper:yellow}", .base_url = "",
    }}, .{ .ancestors = &.{.{ .tag = "html", .root = true }} });
    var denied = try LiteralWikiCellTest.init(a, &joined_styles, EmptyLiteralWikiCellTest.source);
    const expected = (try joined_styles.pageUnprovedInheritanceBlockerWithCompleteClassesIn(a,
        denied.scope.page_style_root, null, null, denied.scope.complete_ancestor_class_superset)) orelse return error.ExpectedAncestorObligation;
    try std.testing.expectEqual(table_style_profile.PageAncestorEffectBlocker.Reason.unproved_ancestor_path, expected.reason);
    const rule = expected.rule orelse return error.ExpectedAncestorRule;
    const provenance = rule.provenance orelse return error.ExpectedAncestorProvenance;
    try std.testing.expectEqualStrings("td", provenance.selector);
    try std.testing.expectEqualStrings("font-size:80%", std.mem.trim(u8, expected.declaration, " \t\r\n;"));
    const denied_blocks = try denied.renderer.renderBodyWithMissing(denied.renderer.body_missing.?);
    try std.testing.expectEqualDeep(expected, denied.renderer.page_ancestor_effect orelse return error.ExpectedRenderedAncestorObligation);
    const expected_report: @import("presentation_fallback.zig").Report = .{ .unresolved_table_style = true };
    try std.testing.expectEqualDeep(expected_report, denied.renderer.fallbacks);
    try std.testing.expect(denied.renderer.container_geometry_refusal == null);
    const denied_stored = try FormattingScopeTest.encode(a, &denied.renderer, denied_blocks);
    // Full Stored equality retains every checked body, paint, font, action,
    // independent footer and owner field while the report remains refused.
    try std.testing.expectEqualDeep(stored, denied_stored);
    const denied_bytes = try codec.encodeAlloc(a, denied_stored);
    try std.testing.expectEqualDeep(denied_stored, try codec.decodeAlloc(a, denied_bytes, denied_stored.entry.title, .language,
        .{ .heading = denied_stored.entry.language.?, .code = denied_stored.entry.language_code }));

}


test "registered copied nonempty wiki cell attributes retain only their exact distant root and font basis" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = LiteralWikiCellTest;
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = ":root{--paper:white;--ink:red}", .base_url = "" }}, &.{}); defer styles.deinit();
    try LiteralDivCustomRootTest.attach(&styles);
    var fixture = try T.init(a, &styles, T.operation); const renderer = &fixture.renderer;
    const cap = T.getCapability(fixture);
    const outer = try renderer.textElement(fixture.outer, null, "");
    const pair = syntax.matchingTag(fixture.source, fixture.outer).?;
    const original = fixture.source[fixture.outer.end..pair.inner_end];
    const copied = try renderer.missingSliceWithHeadingSource(renderer.body_missing.?, original);
    try std.testing.expect(copied.bytes.ptr != original.ptr and copied.unknown and copied.ranges.len == 0);
    renderer.body_missing = copied;
    const base = fixture.outer.end;
    const opening = copied.bytes[cap.table_start - base..cap.table_open_end - base];
    const tag: syntax.Tag = .{ .name = "table", .attrs = opening[2..], .end = 0, .closing = false, .self_closing = false };
    renderer.page_style_wiki_opening = .{ .tag = tag, .source = opening };
    renderer.page_style_wiki_tag = tag;
    const table_style = try renderer.wikiTableForegroundAt(tag, .{ .text_element = outer }, opening);
    const row_opening = copied.bytes[cap.row_start - base..cap.row_end - base];
    const row_tag: syntax.Tag = .{ .name = "tr", .attrs = row_opening[2..], .end = 0, .closing = false, .self_closing = false };
    renderer.page_style_wiki_opening = .{ .tag = row_tag, .source = row_opening, .row_parent = table_style.text_element };
    renderer.page_style_wiki_tag = row_tag;
    const row_style = try renderer.wikiTableForegroundAt(row_tag, table_style, row_opening);
    const attrs = copied.bytes[cap.attrs_start - base..cap.attrs_end - base];
    const cell_tag: syntax.Tag = .{ .name = "td", .attrs = attrs, .end = 0, .closing = false, .self_closing = false };
    var operation: Renderer.LiteralWikiTableOperation = .{ .tracked = copied, .table_opening = opening,
        .row_opening = row_opening, .cell_attrs = attrs, .outer_parent = outer };
    renderer.literal_wiki_table_operation = &operation;
    renderer.page_style_wiki_tag = cell_tag;
    const anchor = renderer.pageStyleCopiedWikiCellAttrs(cell_tag) orelse return error.TestUnexpectedResult;
    try std.testing.expect(anchor.ptr == fixture.source[cap.attrs_start..].ptr and anchor.len == cap.attrs_end - cap.attrs_start);
    try std.testing.expectEqualStrings(attrs, anchor);
    // A direct helper call has no live body basis. Preserve that contrast,
    // then reproduce the ordinary body context used by the actual cell parser.
    const outside_body = try renderer.cellOwnerStyle(cell_tag, row_style, true,
        .{ .style = row_style, .formatting = .{} });
    try std.testing.expect(!outside_body.font_size_unknown and outside_body.font_scale_basis == .context);
    try std.testing.expectApproxEqAbs(@as(f32, 0.9), outside_body.font_scale.?, 0.0001);
    renderer.body_depth = 1;
    const cell_style = try renderer.cellOwnerStyle(cell_tag, row_style, true,
        .{ .style = row_style, .formatting = .{} });
    const cell = cell_style.text_element orelse return error.TestUnexpectedResult;
    try std.testing.expect(cell.page_style_root == fixture.scope.page_style_root and renderer.currentAncestorScope(cell));
    try std.testing.expect(cell.page_style_anchor.?.ptr == anchor.ptr and cell.page_style_anchor.?.len == anchor.len);
    try std.testing.expect(!cell_style.font_size_unknown and cell_style.font_scale_basis == .normal_body);
    try std.testing.expectApproxEqAbs(@as(f32, 0.9), cell_style.font_scale.?, 0.0001);
    // This early query does not fabricate a physical TD or custom environment.
    try std.testing.expect(!cell.physical_ancestry_complete and !cell.ancestry_complete);
    try std.testing.expect(cell.source_literal_div == null and renderer.literal_wiki_cell == null);
    try std.testing.expect(!renderer.fallbacks.any());
    // The earlier formatting query must issue its own live tag and restore it.
    renderer.page_style_wiki_tag = null;
    const formatting = try renderer.wikiCellFontFormatting(cell_tag, row_style, .{ .bold = true, .italic = true });
    try std.testing.expect(formatting.bold and formatting.italic and !renderer.fallbacks.any());
    try std.testing.expect(renderer.page_style_wiki_tag == null);
    for (0..5) |mode| {
        errdefer std.debug.print("COPIED_CELL_FORMAT mode={d}\n", .{mode});
        var changed = operation;
        var changed_tag = cell_tag;
        var changed_parent = row_style;
        var detached_row = row_style.text_element.?.*;
        switch (mode) {
            0 => changed.tracked.lost_missing_range = true,
            1 => changed.tracked.generated_source = copied.bytes,
            2 => changed.cell_attrs = try a.dupe(u8, attrs),
            3 => { changed_tag.name = "caption"; },
            4 => { detached_row.page_style_anchor = try a.dupe(u8, detached_row.page_style_anchor.?); changed_parent.text_element = &detached_row; },
            else => unreachable,
        }
        renderer.literal_wiki_table_operation = &changed;
        const refused = try renderer.wikiCellFontFormatting(changed_tag, changed_parent, .{});
        try std.testing.expect(!refused.bold and !refused.italic);
        try std.testing.expect(renderer.fallbacks.unresolved_table_style);
        try std.testing.expect(renderer.page_style_wiki_tag == null);
        renderer.fallbacks = .{};
    }
    renderer.literal_wiki_table_operation = &operation;
    renderer.page_style_wiki_tag = cell_tag;
    const aliases = renderer.heading_source_aliases;
    for (0..12) |mode| {
        errdefer std.debug.print("COPIED_CELL_ROOT mode={d}\n", .{mode});
        var changed = operation;
        var changed_tag = cell_tag;
        renderer.heading_source_aliases = aliases;
        defer renderer.heading_source_aliases = aliases;
        switch (mode) {
            0 => changed.tracked.lost_missing_range = true,
            1 => changed.tracked.generated_source = copied.bytes,
            2 => changed.tracked.ranges = &.{.{ .start = @intCast(cap.attrs_start - base), .end = @intCast(cap.attrs_end - base), .occurrence = 1 }},
            3 => {
                const foreign = try a.dupe(u8, copied.bytes);
                changed.tracked.bytes = foreign;
                changed.cell_attrs = foreign[cap.attrs_start - base..cap.attrs_end - base];
                changed_tag.attrs = changed.cell_attrs.?;
            },
            4 => changed.cell_attrs = null,
            5 => changed.cell_attrs = attrs[0..attrs.len - 1],
            6 => changed_tag.attrs = try a.dupe(u8, attrs),
            7 => changed_tag.name = "caption",
            8 => changed_tag.self_closing = true,
            9 => {
                // An authenticated prefix cannot authenticate the entire attrs.
                renderer.heading_source_aliases = .empty;
                try renderer.heading_source_aliases.append(a, .{ .copied = attrs[0..attrs.len - 1],
                    .original = fixture.source[cap.attrs_start..cap.attrs_end - 1] });
            },
            10 => {
                // Nor can an equal-byte foreign original terminate the chain.
                renderer.heading_source_aliases = .empty;
                try renderer.heading_source_aliases.append(a, .{ .copied = attrs, .original = try a.dupe(u8, anchor) });
            },
            11 => changed_tag.attrs = attrs[0..0],
            else => unreachable,
        }
        renderer.literal_wiki_table_operation = &changed;
        renderer.page_style_wiki_tag = changed_tag;
        try std.testing.expect(renderer.pageStyleCopiedWikiCellAttrs(changed_tag) == null);
        try std.testing.expect(renderer.pageStyleRootForTag(changed_tag, row_style.text_element) == null);
    }
    renderer.literal_wiki_table_operation = &operation;
    renderer.page_style_wiki_tag = cell_tag;
    renderer.heading_source_aliases = aliases;
    try std.testing.expect(renderer.pageStyleRootForTag(cell_tag, null) == null);
    var unproved_row = row_style.text_element.?.*; unproved_row.page_style_root = null;
    try std.testing.expect(renderer.pageStyleRootForTag(cell_tag, &unproved_row) == null);
    renderer.literal_wiki_table_operation = null;
    try std.testing.expect(renderer.pageStyleRootForTag(cell_tag, row_style.text_element) == null);
    try std.testing.expect(fixture.projection.original.unknown and fixture.projection.original.ranges.len == 1);
}

const RootTableParentContainerTesting = struct {
    const own_style = "width:auto;margin:0px;overflow:auto;";
    const grid_style = "width:70%;border-collapse:collapse;";
    const source = "<div style=\"" ++ own_style ++ "\">\n{| style=\"" ++ grid_style ++ "\"\n|-\n| kept\n|}\n</div>";
    const css = "html{font-size:100%;font-family:sans-serif;font-feature-settings:normal;color:#202122}" ++
        "#observed{padding-left:3px}";
    const nodes = [_]table_style_profile.ObservedStyleNode{
        .{ .tag = "html", .parent = null, .attributes = &.{.{ .name = "lang", .value = "de" }} },
        .{ .tag = "body", .parent = 0, .attributes = &.{} },
        .{ .tag = "div", .parent = 1, .attributes = &.{.{ .name = "class", .value = "mw-parser-output" }} },
        .{ .tag = "section", .parent = 2, .attributes = &.{.{ .name = "data-mw-section-id", .value = "1" }, .{ .name = "id", .value = "first" }, .{ .name = "aria-labelledby", .value = "first-label" }} },
        .{ .tag = "section", .parent = 3, .attributes = &.{.{ .name = "data-mw-section-id", .value = "5" }, .{ .name = "id", .value = "second" }, .{ .name = "aria-labelledby", .value = "second-label" }} },
        .{ .tag = "div", .parent = 4, .attributes = &.{.{ .name = "style", .value = own_style }, .{ .name = "id", .value = "observed" },
            .{ .name = "about", .value = "#mwt1" }, .{ .name = "typeof", .value = "mw:Transclusion" }, .{ .name = "data-mw", .value = "{}" }} },
        .{ .tag = "table", .parent = 5, .attributes = &.{.{ .name = "style", .value = grid_style }} },
    };
    const Bound = struct {
        context: table_style_profile.TableContainingDirectionContext,
        fn observe(raw: ?*const anyopaque, a: A, whole: []const u8, at: usize) A.Error!?TableContainingDirectionObservation {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
            if (whole.ptr != source.ptr or whole.len != source.len or at != std.mem.indexOf(u8, source, "{|").?) return null;
            const parents = try a.alloc([]const u8, 1); parents[0] = source[0..syntax.tagAt(source, 0).?.end];
            return .{ .contexts = @as([*]const table_style_profile.TableContainingDirectionContext, @ptrCast(&self.context))[0..1], .parents = parents };
        }
        fn container(raw: ?*const anyopaque, _: A, operation: AuthoredElementStyleOperation) A.Error!?TableParentContainerObservation {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
            if (operation.source.ptr != source.ptr or operation.source.len != source.len or operation.element.ptr != source.ptr or operation.element.len != source.len) return null;
            return .{ .context = self.context, .element = 5, .environment = .{ .complete = true } };
        }
        fn sizing(_: ?*const anyopaque, _: A, _: []const u8, _: presentation_types.FigureFormat, _: ?u32, _: ?u32) A.Error!?presentation_types.FigureSizingPolicy { return null; }
    };
    fn renderer(a: A, old: *const table_style_profile.Profile, fresh: *const table_style_profile.Profile) !struct { value: Renderer, bound: *Bound } {
        const bound = try a.create(Bound); bound.* = .{ .context = .{ .styles = fresh, .nodes = &nodes, .root = 2, .table = 6 } };
        const projection = try a.create(SourceElementProjection);
        const copies = try a.alloc(SourceElementProjection.Copy, 1); copies[0] = .{ .original_start = 0, .prepared_start = 0, .len = source.len };
        projection.* = .{ .original = MissingText.untracked(source), .prepared = source, .copies = copies };
        return .{ .bound = bound, .value = .{ .a = a, .content_root = .parser_output, .body_missing = MissingText.untracked(source),
            .context = .{ .title = "root operation", .table_styles = old, .text_paint_styles = old,
                .figure_sizing = .{ .resolve_fn = Bound.sizing, .table_containing_direction = .{
                    .root_only = true, .source = source, .context = bound, .observe = Bound.observe, .observe_parent_container = Bound.container } } },
            .table_direction_binding = .{ .projection = projection, .owner = MissingText.untracked(source), .page_start = 0 } } };
    }
};

test "root-only enclosing Table Container retains captured SECTION metadata and native child graph codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = RootTableParentContainerTesting;
    var old = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer old.deinit();
    var fresh = try table_style_profile.parseForTargetAlloc(a, T.css, .screen); defer fresh.deinit();
    var setup = try T.renderer(a, &old, &fresh); const renderer = &setup.value;
    const tag = syntax.tagAt(T.source, 0).?;
    const operation = (try renderer.prepareTableParentContainer(T.source, tag, .{})) orelse return error.TestUnexpectedResult;
    renderer.table_parent_container_operation = operation;
    renderer.context.table_styles = &fresh; renderer.context.text_paint_styles = &fresh;
    const scoped = try renderer.htmlLanguageDirection(tag, .{});
    try std.testing.expect(scoped.text_element == operation.element);
    try std.testing.expectEqualStrings("observed", operation.element.id);
    try std.testing.expectEqualStrings("section", operation.element.parent.?.tag);
    try std.testing.expect(operation.element.physical_ancestry_complete and operation.element.ancestry_complete);
    try std.testing.expect(operation.element.page_style_root == null and operation.element.source_literal_div == null);
    try std.testing.expect(renderer.bounded_text_class_scope == null and renderer.source_element_binding == null);
    const opening = std.mem.indexOf(u8, T.source, "{|").?;
    const opening_end = std.mem.indexOfScalarPos(u8, T.source, opening, '\n').?;
    const native: Renderer.CellNativeContext = .{ .style = .{ .text_element = operation.element }, .formatting = .{}, .source_context_known = true };
    try std.testing.expect((try renderer.tableViewportNativeObservation(T.source[opening..opening_end], native, operation.element, false)) != null);
    var foreign_parent = operation.element.*;
    try std.testing.expect((try renderer.tableViewportNativeObservation(T.source[opening..opening_end], native, &foreign_parent, false)) == null);
    const pair = syntax.matchingTag(T.source, tag).?;
    var baseline: Renderer = .{ .a = a, .context = .{ .table_styles = &old, .text_paint_styles = &old } };
    const children = try baseline.renderBody(T.source[tag.end..pair.inner_end]);
    try std.testing.expect(!baseline.fallbacks.any());
    try std.testing.expect(children.len != 0 and children[0].table != null);
    const resolution = try renderer.containerResolution(tag, .{}, scoped);
    try std.testing.expect(!resolution.unresolved);
    const container = (try renderer.containerGeometry(tag, .{}, scoped, T.source[tag.end..pair.inner_end], children, resolution, false)) orelse return error.TestUnexpectedResult;
    try std.testing.expect(container.style.width.? == .auto);
    try std.testing.expectEqual(presentation_types.ContainerOverflow.auto, container.style.overflow.?);
    try std.testing.expectEqualDeep(presentation_types.StyleEdges.all(.{ .unit = .px, .value = 0 }), container.style.margins.?);
    try std.testing.expectEqual(@as(f32, 3), container.style.padding.?.left.value);
    try std.testing.expectEqualDeep(children, container.blocks);
    try std.testing.expect(!renderer.fallbacks.any());
    const saved = try FormattingScopeTest.encode(a, renderer, &.{.{ .kind = .container, .container = container }});
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeAlloc(a, saved);
    const decoded = try codec.decodeAlloc(a, bytes, saved.entry.title, .language, .{ .heading = saved.entry.language.?, .code = saved.entry.language_code });
    try std.testing.expectEqualDeep(saved, decoded);
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));
    renderer.table_parent_container_operation = null;
    renderer.context.table_styles = &old; renderer.context.text_paint_styles = &old;
    try std.testing.expect(renderer.tableParentContainerElement(tag, null) == null);
    try std.testing.expect(renderer.context.table_styles == &old and renderer.context.text_paint_styles == &old);
}

test "root-only parent Container refuses unknown foreign native parent and unregistered source" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = RootTableParentContainerTesting;
    var old = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer old.deinit();
