    for ([_]Style{ .{ .font_size_unknown = true }, .{ .font_scale = 2, .font_scale_basis = .normal_body, .font_scale_set = true }, .{ .bold = true }, .{ .italic = true }, .{ .code = true } }) |native|
        try std.testing.expect((try renderer.prepareTableParentContainer(T.source, tag, native)) == null);
    const foreign_parent: table_style_profile.TextElement = .{ .tag = "div", .physical_ancestry_complete = true, .ancestry_complete = true };
    try std.testing.expect((try renderer.prepareTableParentContainer(T.source, tag, .{ .text_element = &foreign_parent })) == null);
    const copied = try a.dupe(u8, T.source);
    renderer.body_missing = MissingText.untracked(copied);
    try std.testing.expect((try renderer.prepareTableParentContainer(copied, syntax.tagAt(copied, 0).?, .{})) == null);
    renderer.body_missing = MissingText.untracked(T.source);
    var lost = renderer.body_missing.?; lost.lost_missing_range = true; renderer.body_missing = lost;
    try std.testing.expect((try renderer.prepareTableParentContainer(T.source, tag, .{})) == null);
    renderer.body_missing = MissingText.untracked(T.source);
    var uncertain = try table_style_profile.parseForTargetAlloc(a, T.css ++ "section:hover{font-size:110%}", .screen); defer uncertain.deinit();
    setup.bound.context.styles = &uncertain;
    try std.testing.expect((try renderer.prepareTableParentContainer(T.source, tag, .{})) == null);
    setup.bound.context.styles = &fresh;
    for ([_][]const u8{
        "@media(min-width:640px){section{font-size:110%}}",
        "@media(min-width:639px) and (max-width:640px){section{font-style:italic}}",
        "@media(min-width:900px){html{font-size:110%}}",
    }) |conditional| {
        var changed = try table_style_profile.parseForTargetAlloc(a, try std.mem.concat(a, u8, &.{ T.css, conditional }), .screen); defer changed.deinit();
        setup.bound.context.styles = &changed;
        try std.testing.expect((try renderer.prepareTableParentContainer(T.source, tag, .{})) == null);
    }
    setup.bound.context.styles = &fresh;
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    old.page_style_parent = &parent;
    try std.testing.expect((try renderer.prepareTableParentContainer(T.source, tag, .{})) == null);
    old.page_style_parent = null;
    const selected = renderer.context.figure_sizing.?.table_containing_direction.?;
    renderer.context.figure_sizing.?.table_containing_direction.?.observe_parent_container = null;
    try std.testing.expect((try renderer.prepareTableParentContainer(T.source, tag, .{})) == null);
    renderer.context.figure_sizing.?.table_containing_direction = selected;
}

const ParserRootWikiTableTest = struct {
    const source = "<div></div>\n{| style='margin:0'\n|-\n|\n<div style='background-color:var(--paper);padding:2px'>first [[A|alpha]]\n<div style='height:1.6em;font-weight:bold'>second [[B#part|beta]]</div>\n</div>\n<div style='clear:both'></div>\n|}\n<div style='padding:3px'>footer [[Tail|tail]]</div>";
    fn init(a: A, styles: *const table_style_profile.Profile) !LiteralDivFlexTest {
        const fixture = try LiteralWikiCellTest.init(a, styles, source);
        var cap = LiteralWikiCellTest.getCapability(fixture); cap.parent_start = null;
        for (@constCast(fixture.scope.source_literal_divs)) |*proof| if (proof.parent_start == null and
            proof.range.anchor_start >= cap.body_start and proof.range.anchor_end <= cap.body_end) { proof.wiki_cell_parent = cap; };
        return fixture;
    }
};

test "parser root Table proof requires whole live source and refuses foreign missing and revoked scope" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer styles.deinit();
    var fixture = try ParserRootWikiTableTest.init(a, &styles); const renderer = &fixture.renderer;
    const cap = LiteralWikiCellTest.getCapability(fixture);
    const opening = fixture.source[cap.table_start..cap.table_open_end];
    const tag: syntax.Tag = .{ .name = "table", .attrs = opening[2..], .end = 0, .closing = false, .self_closing = false };
    renderer.page_style_wiki_opening = .{ .tag = tag, .source = opening };
    const original = renderer.literalRootWikiTableOpening(opening, null) orelse return error.TestUnexpectedResult;
    // The ordinary generated-tag factory issues both live records. An opener
    // alone is deliberately insufficient to authenticate a generated TABLE.
    try std.testing.expect(renderer.literalRootWikiTableTag(tag, null) == null);
    renderer.page_style_wiki_tag = tag;
    const node = try renderer.textElement(tag, null, "");
    try std.testing.expect(node.source_wiki_root_table == original and node.parent == fixture.scope.page_style_complete_root);
    try std.testing.expect(node.physical_ancestry_complete and node.ancestry_complete);
    try std.testing.expect(node.alternative_ancestry.?.parent == fixture.scope.page_style_complete_root.?.alternative_ancestry);
    try std.testing.expect((try renderer.textElement(tag, node, "")).source_wiki_root_table == original);
    var stale = node.*;
    stale.page_style_anchor = fixture.source[0.."<div></div>".len];
    try std.testing.expect(!renderer.currentAncestorScope(&stale));
    try std.testing.expect(renderer.literalRootWikiTableTag(tag, &stale) == null);
    stale = node.*; stale.tag = "div";
    try std.testing.expect(!renderer.currentAncestorScope(&stale));
    const copied = try a.dupe(u8, fixture.source);
    const copied_opening = copied[cap.table_start..cap.table_open_end];
    const before = renderer.heading_source_aliases.items.len;
    try renderer.heading_source_aliases.append(a, .{ .copied = copied, .original = fixture.source });
    // parseTable retains the old body owner until cell rendering begins. Even
    // a registered new buffer is not the current parser-input interval yet.
    try std.testing.expect(renderer.literalRootWikiTableOpening(copied_opening, null) == null);
    try std.testing.expect(renderer.literalRootWikiTableOpening(opening, null) == original);
    renderer.heading_source_aliases.shrinkRetainingCapacity(before);
    renderer.body_missing = MissingText.untracked(copied);
    try std.testing.expect(renderer.literalRootWikiTableOpening(copied_opening, null) == null);
    try renderer.heading_source_aliases.append(a, .{ .copied = copied, .original = fixture.source });
    try std.testing.expect(renderer.literalRootWikiTableOpening(copied_opening, null) == original);
    renderer.heading_source_aliases.shrinkRetainingCapacity(before);
    renderer.body_missing = fixture.projection.original;
    for (0..8) |mode| {
        errdefer std.debug.print("ROOT_TABLE_CUSTODY mode={d}\n", .{mode});
        const saved_body = renderer.body_missing; defer renderer.body_missing = saved_body;
        const saved_binding = renderer.source_element_binding; defer renderer.source_element_binding = saved_binding;
        const saved_source = fixture.scope.source_literal_divs_source; defer fixture.scope.source_literal_divs_source = saved_source;
        const saved_proofs = fixture.scope.source_literal_divs; defer fixture.scope.source_literal_divs = saved_proofs;
        const saved_observed = fixture.projection.observed_source; defer fixture.projection.observed_source = saved_observed;
        var foreign: table_style_profile.TextElement = .{ .tag = "div" };
        var parent: ?*const table_style_profile.TextElement = null;
        var selected = opening;
        switch (mode) {
            0 => renderer.body_missing.?.lost_missing_range = true,
            1 => renderer.source_element_binding = null,
            2 => fixture.scope.source_literal_divs_source = try a.dupe(u8, fixture.source),
            3 => fixture.scope.source_literal_divs = &.{},
            4 => fixture.projection.observed_source = null,
            5 => parent = &foreign,
            6 => renderer.body_missing.?.bytes = fixture.source[0..cap.table_open_end],
            7 => selected = try a.dupe(u8, opening),
            else => unreachable,
        }
        try std.testing.expect(renderer.literalRootWikiTableOpening(selected, parent) == null);
    }
    const saved = fixture.scope.source_literal_divs;
    fixture.scope.source_literal_divs = &.{};
    try std.testing.expect(!renderer.currentAncestorScope(node));
    const revoked = try renderer.textElement(tag, node, "");
    try std.testing.expect(revoked.source_wiki_root_table == null and !revoked.physical_ancestry_complete);
    fixture.scope.source_literal_divs = saved;
}

test "parser root bare TD full render retains own cascade complete body footer actions and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var phase = @src(); errdefer std.debug.print("ROOT_TABLE_RENDER source={s}:{d}\n", .{phase.file, phase.line});
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    // This fixture proves the local physical cell cascade, not a complete
    // joined-page rule inventory. Exercise the unchanged joined CSS below.
    const css = ":root{--paper:white}td{--paper:yellow;font-size:80%;font-weight:bold}";
    var styles = try table_style_profile.parseForTargetAlloc(a, css, .screen); defer styles.deinit();
    try table_style_profile.attachCustomProperties(&styles, &.{.{ .css = ":root{--paper:white}td{--paper:yellow}", .base_url = "" }},
        .{ .ancestors = &.{.{ .tag = "html", .root = true }} });
    var fixture = try ParserRootWikiTableTest.init(a, &styles); const renderer = &fixture.renderer;
    phase = @src(); const blocks = try renderer.renderBodyWithMissing(renderer.body_missing.?);
    errdefer std.debug.print("ROOT_TABLE_RENDER report={any}\n", .{renderer.fallbacks});
    try std.testing.expect(!renderer.fallbacks.any());
    try std.testing.expect(renderer.literal_wiki_table_operation == null and renderer.literal_wiki_cell == null and renderer.literal_wiki_cell_style == null);
    var table_index: ?usize = null;
    for (blocks, 0..) |block, index| if (block.table != null) { try std.testing.expect(table_index == null); table_index = index; };
    const index = table_index orelse return error.TestUnexpectedResult;
    const table = blocks[index].table.?;
    try std.testing.expectEqual(@as(usize, 1), table.rows.len);
    try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
    const cell = table.rows[0].cells[0];
    const children = cell.blocks orelse return error.TestUnexpectedResult;
    const frame = children[0].container orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("#ffff00", frame.style.background.?.rgb);
    try std.testing.expectEqualStrings("first alpha", try flattened(a, frame.blocks[0].spans));
    const heading = frame.blocks[1].container orelse return error.TestUnexpectedResult;
    try std.testing.expect(heading.style.height != null);
    try std.testing.expectEqualStrings("second beta", try flattened(a, heading.blocks[0].spans));
    var links: usize = 0;
    for (frame.blocks[0].spans) |span| if (span.kind == .link) {
        try std.testing.expectEqualStrings("A", span.target); try std.testing.expect(span.flags.bold);
        try std.testing.expectApproxEqAbs(@as(f32, 0.8), span.font_scale.?, 0.00001); links += 1;
    };
    for (heading.blocks[0].spans) |span| if (span.kind == .link) { try std.testing.expectEqualStrings("B#part", span.target); links += 1; };
    // A root padding-only DIV retains the established paragraph BlockStyle.
    // Recursive cell boxes above remain Containers; neither may consume this footer.
    const footer = blocks[index + 1];
    try std.testing.expectEqual(Kind.paragraph, footer.kind);
    try std.testing.expect(footer.container == null and footer.table == null);
    try std.testing.expectEqualDeep(presentation_types.BlockStyle{
        .padding = presentation_types.StyleEdges.all(.{ .unit = .px, .value = 3 }),
    }, footer.style orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings("footer tail", try flattened(a, footer.spans));
    for (footer.spans) |span| if (span.kind == .link) {
        try std.testing.expectEqualStrings("Tail", span.target);
        try std.testing.expect(span.font_scale == null or span.font_scale.? == 1); links += 1;
    };
    try std.testing.expectEqual(@as(usize, 3), links);
    phase = @src();
    const stored = try FormattingScopeTest.encode(a, renderer, blocks);
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeAlloc(a, stored);
    try std.testing.expectEqualDeep(stored, try codec.decodeAlloc(a, bytes, stored.entry.title, .language,
        .{ .heading = stored.entry.language.?, .code = stored.entry.language_code }));
    // Exact same source and declarations under the joined-page contract must
    // still report the unproved ordinary TD rule. Own paint cannot waive it.
    phase = @src();
    var joined_styles = try table_style_profile.joinPageSourcesAlloc(a, &parent,
        &.{.{ .css = css, .base_url = "" }}, &.{}); defer joined_styles.deinit();
    try table_style_profile.attachCustomProperties(&joined_styles, &.{.{ .css = ":root{--paper:white}td{--paper:yellow}", .base_url = "" }},
        .{ .ancestors = &.{.{ .tag = "html", .root = true }} });
    var denied = try ParserRootWikiTableTest.init(a, &joined_styles);
    const expected = (try joined_styles.pageUnprovedInheritanceBlockerWithCompleteClassesIn(a,
        denied.scope.page_style_root, null, null, denied.scope.complete_ancestor_class_superset)) orelse return error.ExpectedAncestorObligation;
    try std.testing.expectEqual(table_style_profile.PageAncestorEffectBlocker.Reason.unproved_ancestor_path, expected.reason);
    const rule = expected.rule orelse return error.ExpectedAncestorRule;
    const provenance = rule.provenance orelse return error.ExpectedAncestorProvenance;
    try std.testing.expectEqualStrings("td", provenance.selector);
    try std.testing.expectEqualStrings("font-size:80%", std.mem.trim(u8, expected.declaration, " \t\r\n;"));
    const denied_blocks = try denied.renderer.renderBodyWithMissing(denied.renderer.body_missing.?);
    try std.testing.expectEqualDeep(expected, denied.renderer.page_ancestor_effect orelse return error.ExpectedRenderedAncestorObligation);
    const expected_report: @import("presentation_fallback.zig").Report = .{ .unresolved_table_style = true };
    try std.testing.expectEqualDeep(expected_report, denied.renderer.fallbacks);
    try std.testing.expect(denied.renderer.container_geometry_refusal == null);
    const denied_stored = try FormattingScopeTest.encode(a, &denied.renderer, denied_blocks);
    // Full Stored equality retains every checked body, paint, font, action,
    // independent footer and owner field while the report remains refused.
    try std.testing.expectEqualDeep(stored, denied_stored);
    const denied_bytes = try codec.encodeAlloc(a, denied_stored);
    try std.testing.expectEqualDeep(denied_stored, try codec.decodeAlloc(a, denied_bytes, denied_stored.entry.title, .language,
        .{ .heading = denied_stored.entry.language.?, .code = denied_stored.entry.language_code }));

}

test "literal wiki cell whole replay preserves immediate copy edges for nested single line owners" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer styles.deinit();
    var fixture = try LiteralWikiCellTest.init(a, &styles, EmptyLiteralWikiCellTest.source);
    const renderer = &fixture.renderer; const cap = LiteralWikiCellTest.getCapability(fixture);
    const original = fixture.source[cap.body_start + 1..cap.body_end];
    const copied_page = try a.dupe(u8, fixture.source);
    try renderer.heading_source_aliases.append(a, .{ .copied = copied_page, .original = fixture.source });
    const immediate = copied_page[cap.body_start + 1..cap.body_end];
    const replay: MissingText = .{ .bytes = try a.dupe(u8, immediate), .unknown = true };
    const tracked: MissingText = .{ .bytes = copied_page, .unknown = true };
    const copies = try LiteralWikiCellTest.copies(a, immediate);
    try renderer.registerHeadingSourceCopies(replay.bytes, copies);
    try std.testing.expect(renderer.literalWikiCellCopies(original, replay, copies));
    const source = renderer.literalWikiCellReplayOrigin(tracked, original, replay, copies) orelse return error.TestUnexpectedResult;
    try std.testing.expect(source.ptr == immediate.ptr and source.len == immediate.len);
    const at = std.mem.indexOf(u8, replay.bytes, "<div style='height:").?;
    const tag = syntax.tagAt(replay.bytes, at).?;
    const pair = syntax.matchingTag(replay.bytes, tag).?;
    const child = replay.bytes[at..pair.end];
    const count = renderer.heading_source_aliases.items.len;
    // The prior canonical shortcut conflicts with the already registered line.
    try renderer.heading_source_aliases.append(a, .{ .copied = replay.bytes, .original = original });
    try std.testing.expect(renderer.registeredCaptionOriginal(child) == null);
    renderer.heading_source_aliases.shrinkRetainingCapacity(count);
    try renderer.heading_source_aliases.append(a, .{ .copied = replay.bytes, .original = source });
    const mapped = renderer.registeredCaptionOriginal(child) orelse return error.TestUnexpectedResult;
    try std.testing.expect(mapped.ptr == original[at..].ptr and mapped.len == child.len);
    try std.testing.expectEqualStrings(child, mapped);
    for (0..6) |mode| {
        var changed = tracked;
        var target = original;
        const records = try a.dupe(HeadingSourceCopy, copies);
        switch (mode) {
            0 => changed.bytes = try a.dupe(u8, copied_page),
            1 => changed.lost_missing_range = true,
            2 => changed.generated_source = copied_page,
            3 => records[1].original = try a.dupe(u8, records[1].original),
            4 => target = try a.dupe(u8, original),
            5 => changed.bytes = copied_page[0..cap.body_end - 1],
            else => unreachable,
        }
        try std.testing.expect(renderer.literalWikiCellReplayOrigin(changed, target, replay, records) == null);
    }
    // An independently conflicting destination must still fail the shared map.
    const foreign = try a.dupe(u8, original);
    try renderer.heading_source_aliases.append(a, .{ .copied = replay.bytes, .original = foreign });
    try std.testing.expect(renderer.registeredCaptionOriginal(child) == null);
}

