test "pinned recursive conversion preserves retained ZH multi-form cells body actions separators and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = T.profile();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior };
    for ([_][2][]const u8{
        .{ RecursivePosition153Test.cell0, RecursivePosition153Test.reference0 },
        .{ RecursivePosition153Test.cell1, RecursivePosition153Test.reference1 },
    }, 0..) |pair, index| {
        errdefer std.debug.print("recursive position153 cell={d}\n", .{index});
        const prefix = "[[Before|before]]\n\n{|\n";
        const suffix = "|}\n\n[[After#part|after]]\n\n" ++ T.marked;
        const source = try std.mem.concat(a, u8, &.{ prefix, pair[0], suffix });
        const reference = try std.mem.concat(a, u8, &.{ prefix, pair[1], suffix });
        const tracked = try T.tracked(a, source);
        const expected_tracked = try T.tracked(a, reference);
        var renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
        var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = expected_tracked };
        const blocks = try renderer.renderBodyWithMissing(tracked);
        const reference_blocks = try expected_renderer.renderBodyWithMissing(expected_tracked);
        const actual = try FormattingScopeTest.encode(a, &renderer, blocks);
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, reference_blocks);
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, renderer.fallbacks);
        try std.testing.expect(renderer.body_missing.?.unknown and !renderer.body_missing.?.lost_missing_range);
        try std.testing.expectEqualDeep(tracked.ranges, renderer.body_missing.?.ranges);
        var table_count: usize = 0;
        var link_count: usize = 0;
        var break_count: usize = 0;
        var numbered_label: usize = 0;
        var transliterations: usize = 0;
        const targets: []const []const u8 = if (index == 0)
            &.{ "द्वितीया विभक्त्या#梵語", "द्वितीया विभक्ती#梵語" }
        else
            &.{ "द्वितीया विभक्तये#梵語", "द्वितीया विभक्त्यै#梵語", "द्वितीया विभक्ती#梵語" };
        const labels: []const []const u8 = if (index == 0)
            &.{ "द्वितीया विभक्त्या", "द्वितीया विभक्ती1" }
        else
            &.{ "द्वितीया विभक्तये", "द्वितीया विभक्त्यै2", "द्वितीया विभक्ती1" };
        for (blocks) |block| if (block.table) |table| {
            table_count += 1;
            try std.testing.expectEqual(@as(usize, 1), table.rows.len);
            try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            const cell = table.rows[0].cells[0];
            try std.testing.expect(cell.blocks == null);
            for (cell.spans) |span| {
                try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
                if (span.kind == .link) {
                    try std.testing.expect(link_count < targets.len);
                    try std.testing.expectEqualStrings(targets[link_count], span.target);
                    try std.testing.expectEqualStrings(labels[link_count], span.text);
                    try std.testing.expectEqualStrings("sa", span.language);
                    try std.testing.expectEqualStrings("Deva", span.classes);
                    if (std.mem.eql(u8, span.text, "द्वितीया विभक्ती1")) numbered_label += 1;
                    link_count += 1;
                }
                if (span.kind == .line_break) { break_count += 1; try std.testing.expectEqualStrings("\n", span.text); }
                if (std.mem.eql(u8, span.language, "sa-Latn") and std.mem.startsWith(u8, span.text, "dvitīyā ")) {
                    transliterations += 1;
                    try std.testing.expectEqualStrings("tr Latn", span.classes);
                }
            }
        };
        try std.testing.expectEqual(@as(usize, 1), table_count);
        try std.testing.expectEqual(targets.len, link_count);
        try std.testing.expectEqual(index + 1, break_count);
        try std.testing.expectEqual(@as(usize, 1), numbered_label);
        try std.testing.expectEqual(targets.len, transliterations);
        const codec = @import("blob_encoder").presentation_codec;
        const encoded = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), encoded);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, encoded, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    }
}

test "pinned recursive predecessor positions retain generic unknown custody and grammar refusals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = T.profile();
    const first = "-{[[First#part|-{first}-]]}-";
    const last = "-{[[Second#part|-{second1}-]]}-";
    const prefix = "<span>" ++ first ++ "</span><br><span>";
    const source = prefix ++ last ++ "</span>";
    const child = source[prefix.len..][0..last.len];
    for ([_]bool{ false, true }) |unknown| {
        const parent: MissingText = .{ .bytes = source, .unknown = unknown };
        const domain: InlineSourceDomain = .{ .source = source, .parent = null, .tracked = parent };
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns },
            .inline_missing = .{ .bytes = child, .unknown = unknown }, .inline_source_domain = &domain };
        try std.testing.expect(!Renderer.formattingAngleBodyPositionWithTrackedSiblings(source, prefix.len, true, parent));
        try std.testing.expect((try renderer.nestedRuleFreeLinkLabels(child, 0, .{})) == null);
        const result = (try renderer.sourceRecursiveRuleFreeLinkLabels(child, 0, .{})) orelse return error.TestUnexpectedResult;
        try std.testing.expect(result.body.ptr == child.ptr + 2 and result.end == child.len);
        try std.testing.expectEqualStrings("[[Second#part|-{second1}-]]", result.body);
        try std.testing.expectEqual(unknown, renderer.inline_missing.?.unknown);
        try std.testing.expectEqual(unknown, (try missingSlice(a, renderer.inline_missing.?, result.body)).unknown);
    }
    const first_at = "<span>".len;
    const br_at = "<span>".len + first.len + "</span>".len;
    for (0..11) |mode| {
        errdefer std.debug.print("recursive position153 custody={d}\n", .{mode});
        var parent: MissingText = .{ .bytes = source, .unknown = true };
        var domain: InlineSourceDomain = .{ .source = source, .parent = null, .tracked = parent };
        switch (mode) {
            0 => parent.bytes = try a.dupe(u8, source),
            1 => parent.bytes = source[0 .. prefix.len - 1],
            2 => parent.lost_missing_range = true,
            3 => parent.generated_source = source,
            4 => parent.ranges = &.{.{ .start = first_at, .end = first_at + 1, .occurrence = 1 }},
            5 => parent.literal_curly_ranges = &.{.{ .start = first_at, .end = first_at + 1 }},
            6 => parent.ranges = &.{.{ .start = br_at, .end = br_at + 1, .occurrence = 1 }},
            7 => parent.literal_curly_ranges = &.{.{ .start = br_at, .end = br_at + 1 }},
            8 => domain.source = try a.dupe(u8, source),
            9 => domain.source = source[0 .. prefix.len - 1],
            10 => {},
            else => unreachable,
        }
        domain.tracked = if (mode == 10) null else parent;
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns },
            .inline_missing = .{ .bytes = child, .unknown = true }, .inline_source_domain = &domain };
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(child, 0, .{})) == null);
    }
    for ([_][]const u8{
        "<span>" ++ first ++ "</span><br title='owned'><span>",
        "<span>" ++ first ++ "</span></br><span>",
        "<span>" ++ first ++ "</span><br\n<span>",
        "<span>-{R|[[First|-{first}-]]}-</span><br><span>",
        "<span>-{[[First|-{zh-hans:first;zh-hant:other}-]]}-</span><br><span>",
        "<span>-{[[First|-{<b>first</b>}-]]}-</span><br><span>",
        "<span>-{[[First|-{first}-]]trailer}-</span><br><span>",
        "<span>-{[[First|-{first}-]]</span><br><span>",
        "<span>" ++ first ++ "</i><br><span>",
        "<nowiki>" ++ first ++ "<br><span>",
        "<pre>" ++ first ++ "<br><span>",
        "<span title='" ++ first ++ "<br><span>",
        "[[Outer|" ++ first ++ "<br><span>",
    }) |bad_prefix| {
        const value = try std.mem.concat(a, u8, &.{ bad_prefix, last, "</span>" });
        const part = value[bad_prefix.len..][0..last.len];
        const parent: MissingText = .{ .bytes = value, .unknown = true };
        const domain: InlineSourceDomain = .{ .source = value, .parent = null, .tracked = parent };
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns },
            .inline_missing = .{ .bytes = part, .unknown = true }, .inline_source_domain = &domain };
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(part, 0, .{})) == null);
    }
    // Converter identity is still mandatory even when the local body is clean.
    for ([_]bool{ false, true }) |unknown| {
        const parent: MissingText = .{ .bytes = source, .unknown = unknown };
        const domain: InlineSourceDomain = .{ .source = source, .parent = null, .tracked = parent };
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns },
            .inline_missing = .{ .bytes = child, .unknown = unknown }, .inline_source_domain = &domain };
        ns.manual_conversion_context.?.source_core = "foreign";
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(child, 0, .{})) == null);
        ns.manual_conversion_context = T.profile();
        const outside = source ++ " missing";
        const tracked: MissingText = .{ .bytes = outside, .unknown = unknown,
            .ranges = &.{.{ .start = source.len + 1, .end = outside.len, .occurrence = 1 }} };
        renderer.inline_source_domain = null;
        renderer.inline_missing = tracked;
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(outside, prefix.len, .{})) != null);
        try std.testing.expect(renderer.inline_missing.?.ranges[0].occurrence == 1);
    }
}


