        const operation = try proof.manualConversion(source, prefix.len, .{});
        try std.testing.expect(operation.body.ptr == source.ptr + prefix.len + 2);
        try std.testing.expectEqualStrings(body, operation.body);
        try std.testing.expectEqual(prefix.len + token.len, operation.end);
        try std.testing.expect(!operation.multiline_boundary_lfs);
        try std.testing.expectEqual(unknown, (try missingSlice(a, tracked, operation.body)).unknown);
        var actual_renderer: Renderer = .{ .a = a, .context = context };
