        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, bytes, "formatting scope", .language,
            .{ .heading = "English", .code = "en" }));
    }
}


