test "pinned complete choice labels retain genuine Korean BR audio Unknown actions body and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = SemanticChoiceLabel153Test; const M = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    try ns.attachInterwikiMap("w\t1\t0\t0\t0\thttps://zh.wikipedia.org/wiki/$1\n");
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = M.profile();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior, .content_conversion = true };
    const Case = struct { source: []const u8, reference: []const u8, target: []const u8, external: bool };
    for ([_]Case{
        .{ .source = T.korean, .reference = T.korean_reference, .target = T.korean_target, .external = true },
        .{ .source = T.audio, .reference = T.audio_reference, .target = T.audio_target, .external = false },
    }) |case| for ([_]bool{ false, true }) |unknown| {
        const prefix = "before [[Before|before]]\n\n";
        const suffix = "\n\nafter [[After#part|after]]\n\n" ++ M.marked;
        const source = try std.mem.concat(a, u8, &.{ prefix, case.source, suffix });
        const reference = try std.mem.concat(a, u8, &.{ prefix, case.reference, suffix });
        var tracked = try M.tracked(a, source); tracked.unknown = unknown;
        var expected_tracked = try M.tracked(a, reference); expected_tracked.unknown = unknown;
        var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
        var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = expected_tracked };
        const blocks = try actual_renderer.renderBodyWithMissing(tracked);
        const expected_blocks = try expected_renderer.renderBodyWithMissing(expected_tracked);
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, expected_blocks);
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
        try std.testing.expectEqual(unknown, actual_renderer.body_missing.?.unknown);
        try std.testing.expect(!actual_renderer.body_missing.?.lost_missing_range);
        try std.testing.expectEqualDeep(tracked.ranges, actual_renderer.body_missing.?.ranges);
        var retained: usize = 0; var breaks: usize = 0; var before: usize = 0; var after: usize = 0; var missing: usize = 0;
        for (try FigureProducerTest.bodySpans(a, blocks)) |span| {
            try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
            if (span.kind == .line_break) { breaks += 1; continue; }
            if (std.mem.eql(u8, span.target, case.target)) {
                try std.testing.expectEqual(if (case.external) ir.InlineKind.external_link else ir.InlineKind.link, span.kind);
                if (case.external) {
                    try std.testing.expect(retained < 2);
                    try std.testing.expectEqualStrings(if (retained == 0) "韩国" else "标准语", span.text);
                } else try std.testing.expectEqualStrings("音频文件", span.text);
                retained += 1;
            }
            if (span.kind == .link) {
                if (std.mem.eql(u8, span.target, "Before")) before += 1;
                if (std.mem.eql(u8, span.target, "After#part")) after += 1;
                if (std.mem.eql(u8, span.target, "Template:R:hi:Rajpal")) missing += 1;
            }
        }
        try std.testing.expectEqual(@as(usize, if (case.external) 2 else 1), retained);
        try std.testing.expectEqual(@as(usize, if (case.external) 1 else 0), breaks);
        try std.testing.expectEqual(@as(usize, 1), before);
        try std.testing.expectEqual(@as(usize, 1), after);
        try std.testing.expectEqual(@as(usize, 1), missing);
        try std.testing.expect(!ns.manual_conversion_context.?.automatic_identity);
        const codec = @import("blob_encoder").presentation_codec;
        const encoded = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), encoded);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, encoded, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    };
}

