test "cross cell conversion refuses partial protected fostered mutation and foreign delimiter replay" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = CrossCellManual153Test;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = SourceRecursiveManualTest.profile();
    var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .content_conversion = true } };
    const tracked: MissingText = .{ .bytes = T.small, .unknown = true };
    const plan = (try renderer.tableManualMarkers(tracked, 0, T.opening(T.small), .{})) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 2), plan.offsets.len);
    for (0..7) |mode| {
        var changed = tracked;
        ns.manual_conversion_context = SourceRecursiveManualTest.profile(); renderer.context.content_conversion = true;
        switch (mode) {
            0 => changed.lost_missing_range = true,
            1 => changed.generated_source = T.small,
            2 => changed.ranges = &.{.{ .start = 9, .end = 10, .occurrence = 1 }},
            3 => changed.literal_curly_ranges = &.{.{ .start = 9, .end = 10 }},
            4 => ns.manual_conversion_context.?.source_core = "unproved",
            5 => renderer.context.content_conversion = false,
            6 => ns.manual_conversion_context = null,
            else => unreachable,
        }
        try std.testing.expect((try renderer.tableManualMarkers(changed, 0, T.opening(T.small), .{})) == null);
    }
    ns.manual_conversion_context = SourceRecursiveManualTest.profile(); renderer.context.content_conversion = true;
    for ([_][]const u8{
        "{|\n|-\n! -{<span style='font-size:140%'>head</span>\n| [[Target|-{label}-]]\n|}",
        "{|\n|-\n! -{<span style='font-size:140%'>head</span>\n| [[Target|-{label}-]]}-",
        "{|\nfostered\n|-\n! -{<span style='font-size:140%'>head</span>\n| [[Target|-{label}-]]}-\n|}",
        "{|\n|-\n| <nowiki>\n! -{<span style='font-size:140%'>head</span>\n| [[Target|-{label}-]]}-\n|}\n</nowiki>\n|}",
        "{|\n|-\n! <nowiki>-{<span style='font-size:140%'>head</span>\n| [[Target|-{label}-]]}-</nowiki>\n|}",
        "{|\n|-\n! -{<span style='font-size:140%'>head</span>\n| [[Target|-{zh:a;zh-hant:b}-]]}-\n|}",
        "{|\n|-\n! -{<span style='font-size:140%'>head</span>\n| [[Target|-{R|label}-]]}-\n|}",
        "{|\n|-\n! -{<span style='font-size:140%'>head</span>\n|-\n| [[Target|-{label}-]]}-\n|}",
        "{|\n|-\n! -{<span style='font-size:140%'>head</span>\n| [[Target|-{label}-]]}-suffix\n|}",
        "{|\n|-\n! -{<span style='font-size:140%'>head</span>\n| title='x|y'|[[Target|-{label}-]]}-\n|}",
        "{|\n|-\n! -{<span style='font-size:140%'>head</span>\n| [[File:X.svg|-{label}-]]}-\n|}",
    }) |source| {
        const bad: MissingText = .{ .bytes = source, .unknown = true };
        try std.testing.expect((try renderer.tableManualMarkers(bad, 0, T.opening(source), .{})) == null);
    }
    // The bound operation removes only its two markers via existing copied
    // segments. Equal bytes at another address and partial markers stay literal.
    for (0..7) |mode| {
        renderer.table_manual_markers = plan;
        ns.manual_conversion_context = SourceRecursiveManualTest.profile();
        const selected = if (mode == 1) try a.dupe(u8, T.small) else T.small;
        var input: MissingText = .{ .bytes = selected, .unknown = true };
        const bytes = if (mode == 2) selected[plan.offsets[0] + 1 .. plan.offsets[0] + 2] else selected;
        if (mode == 3) ns.manual_conversion_context.?.source_core = "unproved";
        if (mode == 4) input.lost_missing_range = true;
        if (mode == 5) input.ranges = &.{.{ .start = 9, .end = 10, .occurrence = 1 }};
        if (mode == 6) input.literal_curly_ranges = &.{.{ .start = 9, .end = 10 }};
        var output: MissingBuffer = .empty; defer output.deinit(a);
        var copies: std.ArrayList(HeadingSourceCopy) = .empty; defer copies.deinit(a);
        try renderer.appendWikiTableFosteredCopy(&output, &copies, input, bytes);
        const got = try output.take(a);
        try std.testing.expect(got.unknown);
        if (mode == 0) {
            try std.testing.expectEqualStrings("{|\n|-\n! <span style='font-size:140%'>head</span>\n| [[Target|-{label}-]]\n|}", got.bytes);
            try std.testing.expect(std.mem.indexOf(u8, got.bytes, "[[Target|-{label}-]]") != null);
        } else try std.testing.expectEqualStrings(bytes, got.bytes);
    }
}


