test "inline display receipt requires exact source visible value and live native parent" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const body = "<span title='owner'>text</span>";
    const css = "html{font-family:sans-serif;font-size:100%;font-feature-settings:normal;line-height:normal}" ++
        ".cdx-button.cdx-button--icon-only span + span{display:block}";
    var styles = try table_style_profile.parseForTargetAlloc(a, css, .screen); defer styles.deinit();
    var nodes = OrdinaryTableLinkProducerTest.nodes;
    nodes[8] = .{ .tag = "span", .parent = 7, .attributes = &.{.{ .name = "title", .value = "owner" }}, .has_text = true };
    const context = OrdinaryTableLinkProducerTest.scope(&styles, &nodes);
    var renderer = try OrdinaryTableLinkProducerTest.renderer(a, body, &styles);
    const metrics = (try table_style_profile.resolveObservedNestedTableNodeFontMetrics(a, context, 8, null, 0, null)) orelse return error.TestUnexpectedResult;
    const owner = (try renderer.tableNestedFoldFontMetrics(context, metrics)) orelse return error.TestUnexpectedResult;
    const tag = syntax.tagAt(body, 0).?;
    const native: table_style_profile.TextElement = .{ .tag = "td" };
    const own: table_style_profile.TextElement = .{ .tag = tag.name, .source_key = @intFromPtr(tag.name.ptr), .parent = &native };
    const binding = Renderer.TableInlineSourceFont{ .opening = tag, .subject = 8, .cell = 0, .owner = owner,
        .paint = .{}, .environment = .{}, .display_hidden = false };
    renderer.table_viewport_cell_source = .{ .source = body, .inline_fonts = &.{binding}, .closed_focus = true,
        .page_preflight_parents = .{ .inline_style = .{ .text_element = &native }, .block_style = .{ .text_element = &native } },
        .language = "de", .direction = .ltr, .font_scale = 1, .font_scale_basis = .normal_body };
    renderer.inline_missing = MissingText.untracked(body);
    renderer.context.table_styles = &styles; renderer.context.text_paint_styles = &styles;
    renderer.table_viewport_cell_source.?.inline_display_profile = &styles;
    var generic = try OrdinaryTableLinkProducerTest.renderer(a, body, &styles);
    generic.context.table_styles = &styles; generic.context.text_paint_styles = &styles;
    try std.testing.expect(!try generic.htmlDisplayNoneIn(tag, &native));
    try std.testing.expect(generic.fallbacks.unsupported_element);
    try std.testing.expect(renderer.tableInlineDisplayVisible(tag, &native));
    try std.testing.expect(renderer.tableInlineDisplayVisible(tag, &own));
    try std.testing.expect(!try renderer.htmlDisplayNoneIn(tag, &own));
    try std.testing.expect(!renderer.fallbacks.any());
    const held = renderer.table_viewport_cell_source.?;
    var foreign_styles = try table_style_profile.parseForTargetAlloc(a, css, .screen); defer foreign_styles.deinit();
    renderer.context.table_styles = &foreign_styles;
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
    renderer.context.table_styles = &styles; renderer.context.text_paint_styles = &foreign_styles;
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
    renderer.context.text_paint_styles = &styles;
    renderer.table_viewport_cell_source.?.inline_display_profile = null;
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
    renderer.table_viewport_cell_source = held;
    const foreign = try a.create(table_style_profile.TextElement); foreign.* = native;
    try std.testing.expect(foreign != &native);
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, foreign));
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, null));
    var foreign_own = own;
    foreign_own.source_key = @intFromPtr((try a.dupe(u8, tag.name)).ptr);
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &foreign_own));
    const copy = try a.dupe(u8, body);
    try std.testing.expect(!renderer.tableInlineDisplayVisible(syntax.tagAt(copy, 0).?, &native));
    var changed = tag; changed.attrs = try a.dupe(u8, tag.attrs);
    try std.testing.expect(!renderer.tableInlineDisplayVisible(changed, &native));
    var missing = binding; missing.display_hidden = null;
    renderer.table_viewport_cell_source.?.inline_fonts = &.{missing};
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
    missing.display_hidden = true;
    renderer.table_viewport_cell_source.?.inline_fonts = &.{missing};
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
    renderer.table_viewport_cell_source = held;
    renderer.table_viewport_cell_source.?.page_preflight_parents = null;
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
    renderer.table_viewport_cell_source = held;
    renderer.table_viewport_cell_source.?.closed_focus = false;
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
    renderer.table_viewport_cell_source = held;
    renderer.table_viewport_cell_source.?.source_constructed = true;
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
    renderer.table_viewport_cell_source = held;
    renderer.inline_missing = .{ .bytes = body, .unknown = true };
    try std.testing.expect(!renderer.tableInlineDisplayVisible(tag, &native));
}


test "captured linked ruby conversions retain complete pronunciation body actions styles and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    var ns = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").english_test_fixture); defer ns.deinit();
    ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior };
    const fixtures = [_]struct { source: []const u8, target: []const u8, visible: []const u8 }{
        .{ .source = "-{【[[旅路#日語|<ruby><rb>旅路</rb><rt>たびじ</rt></ruby>]]】}-", .target = "旅路#日語", .visible = "before first 【旅路（たびじ）】 after last" },
        .{ .source = "-{【[[飛び込む#日語|<ruby><rb>飛</rb><rt>と</rt></ruby>び<ruby><rb>込</rb><rt>こ</rt></ruby>む]]】}-", .target = "飛び込む#日語", .visible = "before first 【飛（と）び込（こ）む】 after last" },
    };
    const codec = @import("blob_encoder").presentation_codec;
    for (fixtures, 0..) |fixture, index| {
        errdefer std.debug.print("ZH linked ruby fixture={d}\n", .{index});
        const body = fixture.source[2 .. fixture.source.len - 2];
        const source = try std.mem.concat(a, u8, &.{ "''before [[Before|first]] ", fixture.source, " after'' [[After#tail|last]]" });
        const reference = try std.mem.concat(a, u8, &.{ "''before [[Before|first]] <span>", body, "</span> after'' [[After#tail|last]]" });
        var visible_renderer: Renderer = .{ .a = a, .context = context };
        const spans = try visible_renderer.parseSpans(source, .{});
        try std.testing.expectEqualStrings(fixture.visible, try flattened(a, spans));
        var before = false; var after = false; var ruby_action = false;
        for (try RubyProducerTest.leaves(a, spans)) |span| {
            if (span.kind != .link) continue;
            if (std.mem.eql(u8, span.target, "Before")) {
                before = true; try std.testing.expectEqualStrings("first", span.text); try std.testing.expect(span.flags.italic);
            } else if (std.mem.eql(u8, span.target, "After#tail")) {
                after = true; try std.testing.expectEqualStrings("last", span.text); try std.testing.expect(!span.flags.italic);
            } else {
                try std.testing.expectEqualStrings(fixture.target, span.target);
                try std.testing.expect(span.flags.italic); ruby_action = true;
            }
        }
        try std.testing.expect(before and after and ruby_action);
        var typed_owners: usize = 0;
        for (spans) |span| if (span.ruby) |ruby| {
            typed_owners += 1;
            try std.testing.expectEqual(@as(usize, 1), ruby.segments.len);
            try std.testing.expectEqual(@as(usize, 1), ruby.segments[0].bases.len);
            try std.testing.expectEqual(@as(usize, 1), ruby.segments[0].annotations.len);
            try std.testing.expectEqualStrings(fixture.target, ruby.segments[0].bases[0].spans[0].target);
            try std.testing.expectEqualStrings(fixture.target, ruby.segments[0].annotations[0].spans[0].target);
        };
        try std.testing.expectEqual(index + 1, typed_owners);
        var actual_renderer: Renderer = .{ .a = a, .context = context };
        var expected_renderer: Renderer = .{ .a = a, .context = context };
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, try actual_renderer.renderBody(source));
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, try expected_renderer.renderBody(reference));
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
        const bytes = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
        const decoded = try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .code = "en", .heading = "English" });
        try std.testing.expectEqualDeep(actual, decoded);
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));
    }
}

