test "pinned titled choice label preserves genuine citation tooltip action style Missing body and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = TitledChoice153Test; const M = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    try ns.attachInterwikiMap("Wikipedia\t1\t0\t0\t0\thttps://zh.wikipedia.org/wiki/$1\nw\t1\t0\t0\t0\thttps://zh.wikipedia.org/wiki/$1\n");
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" }; ns.manual_conversion_context = M.profile();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior, .content_conversion = true };
    for ([_]bool{ false, true }) |unknown| {
        const prefix = "before [[Before|before]]\n\n"; const suffix = "\nafter [[After|after]]\n\n" ++ M.marked;
        const source = try std.mem.concat(a, u8, &.{ prefix, T.citation, suffix });
        const reference = try std.mem.concat(a, u8, &.{ prefix, T.reference, suffix });
        var tracked = try M.tracked(a, source); tracked.unknown = unknown;
        var reference_tracked = try M.tracked(a, reference); reference_tracked.unknown = unknown;
        var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
        var reference_renderer: Renderer = .{ .a = a, .context = context, .body_missing = reference_tracked };
        const blocks = try actual_renderer.renderBodyWithMissing(tracked);
        const reference_blocks = try reference_renderer.renderBodyWithMissing(reference_tracked);
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
        const expected = try FormattingScopeTest.encode(a, &reference_renderer, reference_blocks);
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(reference_renderer.fallbacks, actual_renderer.fallbacks);
        try std.testing.expectEqual(unknown, actual_renderer.body_missing.?.unknown);
        try std.testing.expectEqualDeep(tracked.ranges, actual_renderer.body_missing.?.ranges);
        try std.testing.expect(!actual_renderer.body_missing.?.lost_missing_range);
        var selected: usize = 0; var external: usize = 0; var ordinary: usize = 0;
        for (try FigureProducerTest.bodySpans(a, blocks)) |span| {
            try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
            if (span.kind == .external_link) {
                external += 1;
                if (std.mem.eql(u8, span.target, "https://zh.wikipedia.org/wiki/%E5%A4%B1%E6%95%88%E9%93%BE%E6%8E%A5")) {
                    selected += 1;
                    try std.testing.expectEqualStrings("永久失效連結", span.text);
                    try std.testing.expectEqualStrings("自2022年10月失效", span.tooltip orelse return error.TestUnexpectedResult);
                    try std.testing.expect(span.flags.superscript);
                }
            }
            if (span.kind == .link and (std.mem.eql(u8, span.target, "Before") or std.mem.eql(u8, span.target, "After") or
                std.mem.eql(u8, span.target, "Template:R:hi:Rajpal"))) ordinary += 1;
        }
        try std.testing.expectEqual(@as(usize, 1), selected);
        try std.testing.expectEqual(@as(usize, 3), external);
        try std.testing.expectEqual(@as(usize, 3), ordinary);
        const codec = @import("blob_encoder").presentation_codec;
        const encoded = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), encoded);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, encoded, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    }
}

test "pinned titled choice label refuses copied protected foreign and malformed scopes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = TitledChoice153Test; const M = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" }; ns.manual_conversion_context = M.profile();
    var iterator: ir.InlineIterator = .{ .input = T.token, .renderer_boundaries = true };
    const node = iterator.next() orelse return error.TestUnexpectedResult;
    const tracked: MissingText = .{ .bytes = T.token, .unknown = true };
    const label: MissingText = .{ .bytes = node.text, .unknown = true };
    var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .content_conversion = true }, .inline_missing = tracked };
    var domain: InlineSourceDomain = .{ .source = T.token, .tracked = tracked, .parent = null };
    renderer.inline_source_domain = &domain;
    try std.testing.expect((try renderer.manualChoiceWikiLabel(T.token, 0, T.token.len, label, .{})) == null);
    const selected = (try renderer.sourceSemanticChoiceWikiLabel(T.token, 0, T.token.len, node.target, label, .{})) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(T.selected_label, selected.bytes);
    try std.testing.expect(selected.unknown and !selected.lost_missing_range and selected.ranges.len == 0);
    try std.testing.expect(renderer.inline_source_domain == &domain);
    try std.testing.expectEqualDeep(tracked, renderer.inline_missing.?);
    for (0..6) |mode| {
        var candidate = label; var target = node.target;
        switch (mode) {
            0 => candidate.bytes = try a.dupe(u8, label.bytes),
            1 => candidate.lost_missing_range = true,
            2 => candidate.generated_source = T.token,
            3 => candidate.ranges = &.{.{ .start = 1, .end = 2, .occurrence = 1 }},
            4 => candidate.literal_curly_ranges = &.{.{ .start = 1, .end = 2 }},
            5 => target = try a.dupe(u8, node.target),
            else => unreachable,
        }
        try std.testing.expect((try renderer.sourceSemanticChoiceWikiLabel(T.token, 0, T.token.len, target, candidate, .{})) == null);
    }
    domain.source = try a.dupe(u8, T.token);
    try std.testing.expect((try renderer.sourceSemanticChoiceWikiLabel(T.token, 0, T.token.len, node.target, label, .{})) == null);
    domain.source = T.token;
    for ([_]Style{ .{ .kind = .external_link, .target = "https://example.test" }, .{ .code = true }, .{ .provenance = .protected_literal } }) |style|
        try std.testing.expect((try renderer.sourceSemanticChoiceWikiLabel(T.token, 0, T.token.len, node.target, label, style)) == null);
    renderer.in_reference = true;
    try std.testing.expect((try renderer.sourceSemanticChoiceWikiLabel(T.token, 0, T.token.len, node.target, label, .{})) == null);
    renderer.in_reference = false; renderer.inline_source_domain = null;
    for ([_][]const u8{
        "<span title='tip' onclick='x'>prefix" ++ T.rule ++ "</span>",
        "<span title='tip' style='color:red'>prefix" ++ T.rule ++ "</span>",
        "<span title='tip' title='other'>prefix" ++ T.rule ++ "</span>",
        "<span title=tip>prefix" ++ T.rule ++ "</span>",
        "<span title='tip|flag'>prefix" ++ T.rule ++ "</span>",
        "<span title='tip'>" ++ T.rule ++ "</span>",
        "<span title='tip'><b>prefix</b>" ++ T.rule ++ "</span>",
        "<span title='tip'>prefix" ++ T.rule ++ "suffix</span>",
        "<span title='tip'>prefix" ++ T.rule ++ "</i>",
        "<span title='tip'>prefix" ++ T.rule ++ "</span><span>extra</span>",
        "<nowiki title='tip'>prefix" ++ T.rule ++ "</nowiki>",
        "<span title='tip'>prefix-{A|zh:one;zh-hans:two}-</span>",
    }) |bad_label| {
        const bad = try std.mem.concat(a, u8, &.{ "[[Target|", bad_label, "]]" });
        var links: ir.InlineIterator = .{ .input = bad, .renderer_boundaries = true };
        const bad_node = links.next() orelse return error.TestUnexpectedResult;
        renderer.inline_missing = .{ .bytes = bad, .unknown = true };
        try std.testing.expect((try renderer.sourceSemanticChoiceWikiLabel(bad, 0, bad.len, bad_node.target,
            .{ .bytes = bad_node.text, .unknown = true }, .{})) == null);
    }
}


test "negative selector ancestry retains converging physical and alternative parents" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Node = table_style_profile.TextElement;
    const shared: Node = .{ .tag = "div", .classes = "shared", .id = "shared-id" };
    const alternate_parent: Node = .{ .tag = "div", .classes = "alternate-parent", .id = "alternate-id", .parent = &shared };
    const parent: Node = .{ .tag = "div", .classes = "primary-parent", .id = "primary-id", .parent = &shared, .alternative_ancestry = &alternate_parent };
    const alternate: Node = .{ .tag = "div", .classes = "leaf", .id = "leaf-id", .parent = &alternate_parent };
    const node: Node = .{ .tag = "div", .classes = "leaf", .id = "leaf-id", .parent = &parent, .alternative_ancestry = &alternate };
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const classes = (try renderer.negativePaintQueryTokens("captured", &node, false)) orelse return error.TestUnexpectedResult;
    const ids = (try renderer.negativePaintQueryTokens("captured-id", &node, true)) orelse return error.TestUnexpectedResult;
    const Tokens = struct {
        fn has(haystack: []const u8, wanted: []const u8) bool {
            var words = std.mem.tokenizeAny(u8, haystack, " \t\r\n");
            while (words.next()) |word| if (std.mem.eql(u8, word, wanted)) return true;
            return false;
        }
    };
    inline for (.{ "captured", "shared", "alternate-parent", "primary-parent", "leaf" }) |token|
        try std.testing.expect(Tokens.has(classes, token));
    inline for (.{ "captured-id", "shared-id", "alternate-id", "primary-id", "leaf-id" }) |token|
        try std.testing.expect(Tokens.has(ids, token));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, classes, "shared"));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, classes, "alternate-parent"));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, ids, "shared-id"));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, ids, "alternate-id"));
    try std.testing.expect(node.parent == &parent and node.alternative_ancestry == &alternate);
    try std.testing.expect(parent.alternative_ancestry == &alternate_parent and alternate.parent == &alternate_parent);
    try std.testing.expect(node.complete_ancestor_classes == null and node.complete_ancestor_ids == null);
}

test "negative selector ancestry refuses cycles foreign scopes and bounded inventories" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Node = table_style_profile.TextElement;
    var renderer: Renderer = .{ .a = a, .context = .{} };
    var cyclic: Node = .{ .tag = "div" };
    cyclic.parent = &cyclic;
    try std.testing.expect(try renderer.negativePaintQueryTokens("", &cyclic, false) == null);
    cyclic.parent = null;
    cyclic.alternative_ancestry = &cyclic;
    try std.testing.expect(try renderer.negativePaintQueryTokens("", &cyclic, true) == null);
    var parent: Node = .{ .tag = "div" };
    const alternative: Node = .{ .tag = "div", .parent = &parent };
    const child: Node = .{ .tag = "div", .parent = &parent, .alternative_ancestry = &alternative };
    parent.alternative_ancestry = &child;
    try std.testing.expect(try renderer.negativePaintQueryTokens("", &child, false) == null);
    parent.alternative_ancestry = null;
    const foreign_scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "foreign", .subtree_classes = "foreign" };
    var foreign: Node = .{ .tag = "div", .ancestor_class_scope = &foreign_scope, .ancestor_class_source = "foreign" };
    const foreign_parent: Node = .{ .tag = "div", .parent = &foreign };
    const foreign_alternative: Node = .{ .tag = "div", .alternative_ancestry = &foreign };
    try std.testing.expect(try renderer.negativePaintQueryTokens("", &foreign_parent, false) == null);
    try std.testing.expect(try renderer.negativePaintQueryTokens("", &foreign_alternative, true) == null);
    foreign.ancestor_class_scope = null;
    try std.testing.expect(try renderer.negativePaintQueryTokens(null, &foreign, false) == null);
    var nodes: [257]Node = undefined;
    for (&nodes, 0..) |*item, i| item.* = .{ .tag = "div", .parent = if (i == 0) null else &nodes[i - 1] };
    try std.testing.expect(try renderer.negativePaintQueryTokens("", &nodes[255], false) != null);
    try std.testing.expect(try renderer.negativePaintQueryTokens("", &nodes[256], false) == null);
    const maximum = try a.alloc(u8, 65534);
    @memset(maximum, 'x');
    const accepted = (try renderer.negativePaintQueryTokens(maximum, &nodes[0], false)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 65536), accepted.len);
    const too_large = try a.alloc(u8, 65535);
    @memset(too_large, 'x');
    try std.testing.expect(try renderer.negativePaintQueryTokens(too_large, &nodes[0], false) == null);
}

