test "first Missing cell font source refuses incomplete foreign tainted and nonfirst grids" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var ns = try ObservedMixedReadyCaptionTest.registry(a); defer ns.deinit();
    const source = "{| class=\"infobox\"\n|-\n| colspan=\"2\" | [[File:Missing.png|thumb|center|200px|[1] caption]]\n|-\n! head !! other\n|-\n| '''[[Target|label]]''' || word\n|}";
    const open_end = std.mem.indexOfScalar(u8, source, '\n').?;
    const opening: syntax.Tag = .{ .name = "table", .attrs = source[2..open_end], .end = 0, .closing = false, .self_closing = false };
    var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns } };
    const first = (try renderer.wikiFigureFirstCellSource(source, 0, opening)) orelse return error.TestUnexpectedResult;
    try std.testing.expect(first.table.ptr == source.ptr and first.table.len == source.len);
    for ([_]struct { before: []const u8, after: []const u8 }{
        .{ .before = "\n|}", .after = "" },
        .{ .before = "\n|}", .after = "\n|} extra" },
        .{ .before = "\n! head", .after = "\n{|\n! head" },
        .{ .before = "\n|-\n| colspan", .after = "\n|-\n| earlier\n|-\n| colspan" },
        .{ .before = "caption]]", .after = "caption]] || second" },
        .{ .before = "caption]]", .after = "caption]] suffix" },
        .{ .before = "! head", .after = "! [[File:Other.png|thumb|caption]]" },
        .{ .before = "! head", .after = "! {{unknown}}" },
        .{ .before = "! head", .after = "! <ref>unknown</ref>" },
        .{ .before = "! head", .after = "! onclick='run()' | head" },
    }) |mutation| {
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, source, mutation.before));
        const changed = try std.mem.replaceOwned(u8, a, source, mutation.before, mutation.after);
        const end = std.mem.indexOfScalar(u8, changed, '\n').?;
        const changed_opening: syntax.Tag = .{ .name = "table", .attrs = changed[2..end], .end = 0, .closing = false, .self_closing = false };
        try std.testing.expect((try renderer.wikiFigureFirstCellSource(changed, 0, changed_opening)) == null);
    }
    const root: table_style_profile.TextElement = .{ .tag = "div", .classes = "mw-parser-output" };
    const table: table_style_profile.TextElement = .{ .tag = "table", .classes = "infobox", .parent = &root };
    const scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output",
        .subtree_classes = "infobox", .complete_ancestor_class_superset = "mw-parser-output infobox", .page_style_root = &root };
    const Probe = struct { fn observe(_: ?*const anyopaque, _: A, _: FigureStyleOperation) A.Error!?FigureStyleObservation { return null; } };
    var sizing = FigureProducerTest.sizing_source; sizing.figure_style_ctx = &scope; sizing.resolve_figure_style_fn = Probe.observe;
    sizing.text_class_scope = .{ .source = source, .scope = &scope };
    renderer.context.figure_sizing = sizing;
    renderer.content_root = .parser_output; renderer.body_depth = 1; renderer.figure_source_font_observation = true;
    renderer.bounded_text_class_scope = &scope; renderer.bounded_text_class_source = source;
    const native: Renderer.FigureWikiNativeFont = .{ .style = .{ .text_element = &root }, .formatting = .{} };
    try std.testing.expect((try renderer.issueWikiFigureTableFontSource(source, 0, opening, .{ .text_element = &table }, native, true)) != null);
    const foreign = try a.dupe(u8, source);
    var foreign_opening = opening; foreign_opening.attrs = foreign[2..open_end];
    try std.testing.expect((try renderer.issueWikiFigureTableFontSource(foreign, 0, foreign_opening, .{ .text_element = &table }, native, true)) == null);
    for (0..5) |mode| {
        var tracked = MissingText.untracked(source);
        switch (mode) { 0 => tracked.unknown = true, 1 => tracked.lost_missing_range = true,
            2 => tracked.ranges = &.{.{ .start = 0, .end = 1, .occurrence = 1 }},
            3 => tracked.literal_curly_ranges = &.{.{ .start = 0, .end = 1 }},
            4 => tracked.generated_source = source, else => unreachable }
        renderer.body_missing = tracked;
        try std.testing.expect((try renderer.issueWikiFigureTableFontSource(source, 0, opening, .{ .text_element = &table }, native, true)) == null);
    }
    renderer.body_missing = null;
    var unknown_native = native; unknown_native.style.font_size_unknown = true;
    try std.testing.expect((try renderer.issueWikiFigureTableFontSource(source, 0, opening, .{ .text_element = &table }, unknown_native, true)) == null);
    try std.testing.expect((try renderer.issueWikiFigureTableFontSource(source, 0, opening, .{ .text_element = &table }, native, false)) == null);
}


test "negative selector query retains both exact captured outer chains without native source anchors" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer styles.deinit();
    var fixture = try BlockMediaEmitterTest.init(a, &styles);
    const renderer = &fixture.renderer;
    const root = @constCast(fixture.scope.page_style_complete_root.?);
    const alternative = @constCast(root.alternative_ancestry.?);
    const first = @constCast(root.parent.?.parent.?);
    const second = @constCast(alternative.parent.?.parent.?);
    first.classes = "captured-primary"; first.id = "primary-id";
    second.classes = "captured-alternative"; second.id = "alternative-id";
    try std.testing.expect(root != fixture.scope.page_style_root and alternative != fixture.scope.page_style_root);
    try std.testing.expect(root.page_style_source == null and root.page_style_anchor == null);
    try std.testing.expect(alternative.page_style_source == null and alternative.page_style_anchor == null);
    try std.testing.expect(!renderer.currentAncestorScope(root) and !renderer.currentAncestorScope(alternative));
    try std.testing.expect(renderer.currentAncestorScope(fixture.native));
    const saved_native = fixture.native.*;
    const saved_root = root.*;
    const saved_alternative = alternative.*;
    const classes = (try renderer.negativePaintQueryTokens(fixture.scope.complete_ancestor_class_superset, fixture.native, false)) orelse return error.TestUnexpectedResult;
    const ids = (try renderer.negativePaintQueryTokens(fixture.scope.complete_ancestor_id_superset, fixture.native, true)) orelse return error.TestUnexpectedResult;
    inline for (.{ "mw-parser-output", "outer", "inner", "captured-primary", "captured-alternative" }) |token|
        try std.testing.expect(table_style_profile.Profile.hasClass(classes, token));
    inline for (.{ "primary-id", "alternative-id" }) |token|
        try std.testing.expect(table_style_profile.Profile.hasClass(ids, token));
    try std.testing.expect(std.meta.eql(saved_native, fixture.native.*));
    try std.testing.expect(std.meta.eql(saved_root, root.*));
    try std.testing.expect(std.meta.eql(saved_alternative, alternative.*));
    try std.testing.expect(renderer.blockMediaNativeAncestorsCurrent(fixture.native));
    try std.testing.expect(!renderer.currentAncestorScope(root) and !renderer.currentAncestorScope(alternative));
}

test "negative selector captured membership refuses stale roots copies incomplete arms and cycles" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer styles.deinit();
    for (0..12) |mode| {
        var fixture = try BlockMediaEmitterTest.init(a, &styles);
        const renderer = &fixture.renderer;
        const root = @constCast(fixture.scope.page_style_complete_root.?);
        const alternative = @constCast(root.alternative_ancestry.?);
        switch (mode) {
            0 => fixture.scope.page_style_complete_root = null,
            1 => root.alternative_ancestry = null,
            2 => alternative.parent = null,
            3 => root.page_style_root = fixture.scope.page_style_root,
            4 => alternative.page_style_root = root,
            5 => root.ancestry_complete = false,
            6 => alternative.physical_ancestry_complete = false,
            7 => alternative.alternative_ancestry = root,
            8 => alternative.tag = "foreign",
            9 => root.parent = root,
            10 => {
                const copied = try a.create(table_style_profile.TextElement); copied.* = root.*;
                @constCast(fixture.native.parent.?).parent = copied;
            },
            11 => fixture.projection.original.bytes = try a.dupe(u8, BlockMediaEmitterTest.source),
            else => unreachable,
        }
        try std.testing.expect((try renderer.negativePaintQueryTokens(fixture.scope.complete_ancestor_class_superset, fixture.native, false)) == null);
        try std.testing.expect((try renderer.negativePaintQueryTokens(fixture.scope.complete_ancestor_id_superset, fixture.native, true)) == null);
        try std.testing.expect(!renderer.blockMediaNativeAncestorsCurrent(fixture.native));
    }
}


const RubyProducerTest = struct {
    fn leaves(a: A, spans: []const Span) ![]const Span {
        const Capture = struct {
            a: A,
            values: std.ArrayList(Span) = .empty,
            fn emit(self: *@This(), span: Span) !void { try self.values.append(self.a, span); }
        };
        var capture: Capture = .{ .a = a };
        try presentation_types.visitRubyFallback(spans, &capture, Capture.emit);
        return try capture.values.toOwnedSlice(a);
    }
};

test "typed Ruby producer preserves associations gaps empty readings nested owners and explicit fallback actions" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const source = "before <ruby lang='ja'><rb>[[A|alpha]]</rb> <rb>beta</rb><rtc><rt>''[[R|reading]]''</rt><rt></rt></rtc><rtc>both</rtc></ruby> after";
    const spans = try renderer.parseSpans(source, .{});
    try std.testing.expectEqualStrings("before alpha beta（reading）（both） after", try flattened(a, spans));
    const ruby = spans[1].ruby orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), ruby.segments.len);
    const segment = ruby.segments[0];
    try std.testing.expectEqual(@as(usize, 2), segment.bases.len);
    try std.testing.expectEqualStrings(" ", segment.bases[1].gap_before[0].text);
    try std.testing.expectEqual(@as(usize, 3), segment.annotations.len);
    try std.testing.expectEqual(@as(u32, 0), segment.annotations[0].level);
    try std.testing.expectEqual(@as(u32, 1), segment.annotations[1].base_start);
    try std.testing.expectEqual(@as(usize, 0), segment.annotations[1].spans.len);
    try std.testing.expectEqual(@as(u32, 1), segment.annotations[2].level);
    try std.testing.expectEqual(@as(u32, 2), segment.annotations[2].base_count);
    try std.testing.expectEqualStrings("A", segment.bases[0].spans[0].target);
    try std.testing.expectEqualStrings("R", segment.annotations[0].spans[0].target);
    try std.testing.expect(segment.annotations[0].spans[0].flags.italic);
    try std.testing.expectApproxEqAbs(@as(f32, 0.5), segment.annotations[0].spans[0].font_scale.?, 0.00001);
    const explicit = try renderer.parseSpans("<ruby>outer<rp>[[Left|left]]</rp><rt><ruby>inner<rt>inside</rt></ruby></rt><rp>[[Right|right]]</rp></ruby>", .{});
    const annotation = explicit[0].ruby.?.segments[0].annotations[0];
    try std.testing.expect(annotation.explicit_fallback);
    try std.testing.expectEqualStrings("Left", annotation.fallback_before[0].target);
    try std.testing.expectEqualStrings("Right", annotation.fallback_after[0].target);
    try std.testing.expect(annotation.spans[0].ruby != null);
    const groups = try renderer.parseSpans("<ruby>a<rt>one</rt><rt>two</rt> b<rt>three</rt></ruby>", .{});
    try std.testing.expectEqual(@as(usize, 2), groups[0].ruby.?.segments.len);
    try std.testing.expectEqual(@as(u32, 1), groups[0].ruby.?.segments[0].annotations[1].level);
    try std.testing.expectEqualStrings(" ", groups[0].ruby.?.segments[1].gap_before[0].text);
    const padded = try renderer.parseSpans("<ruby><rb>a</rb><rtc><rt>one</rt><rt>two</rt></rtc></ruby>", .{});
    try std.testing.expectEqual(@as(usize, 2), padded[0].ruby.?.segments[0].bases.len);
    try std.testing.expectEqual(@as(usize, 0), padded[0].ruby.?.segments[0].bases[1].spans.len);
}

