test "typed Ruby producer refuses unsupported structure body controls media bidi and preserves protected input" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{
        "<ruby>a<rp>(</rp></ruby>",
        "<ruby><rb>a</rb>mixed<rt>x</rt></ruby>", "<ruby>a<rtc><rt>x</rt>mixed</rtc></ruby>",
        "<ruby>a<rt><br>x</rt></ruby>", "<ruby><div>a</div><rt>x</rt></ruby>",
        "<ruby>a<rt><span style='ruby-position:under'>x</span></rt></ruby>",
        "<ruby>a<rt><small style='ruby-position:under'>x</small></rt></ruby>",
        "<ruby>a<rt><span style='display:none'>x</span></rt></ruby>",
        "<ruby dir='auto'>a<rt>x</rt></ruby>", "<ruby>a<rt><bdo dir='rtl'>x</bdo></rt></ruby>",
        "<bdi><ruby>a<rt>x</rt></ruby></bdi>", "<bdi dir='rtl'><ruby>a<rt>x</rt></ruby></bdi>",
        "<ruby>a<rt><nowiki>x\ty</nowiki></rt></ruby>", "<ruby>a<rt><span class='wikidict-media'>x</span></rt></ruby>",
        "<ruby>a<rt>[[File:Test.png]]</rt></ruby>",
    }, 0..) |source, case_index| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        errdefer std.debug.print("RUBY_REFUSAL_CASE={d} source={s} at={s}:{d}\n", .{ case_index, source, @src().file, @src().line });
        try std.testing.expectError(error.UncompiledPresentation, renderer.parseSpans(source, .{}));
    }
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const protected = try renderer.parseSpans("<nowiki><ruby>a<rt>x</rt></ruby></nowiki>", .{});
    try std.testing.expectEqualStrings("<ruby>a<rt>x</rt></ruby>", try flattened(a, protected));
    for (protected) |span| try std.testing.expect(span.ruby == null);
    const directional = try renderer.parseSpans("<ruby dir='rtl'>a<rt dir='ltr'>x</rt></ruby>", .{});
    try std.testing.expectEqualStrings("rtl", directional[0].direction);
    try std.testing.expectEqualStrings("ltr", directional[0].ruby.?.segments[0].annotations[0].spans[0].direction);
    var nested: []const u8 = "base";
    for (0..presentation_types.max_ruby_depth + 1) |_| nested = try std.mem.concat(a, u8, &.{ "<ruby>", nested, "<rt>x</rt></ruby>" });
    try std.testing.expectError(error.UncompiledPresentation, renderer.parseSpans(nested, .{}));
}

