test "typed Ruby survives nonfloating image splitting and preserves plaintext provenance and derived boundaries" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody("<ruby>[[Before|before]]<rt>first</rt></ruby>[[File:Logo.svg|x40px|none|link=|alt=]]<ruby>[[After|after]]<rt>last</rt></ruby>");
    try std.testing.expectEqual(@as(usize, 3), blocks.len);
    try std.testing.expect(blocks[0].spans[0].ruby != null and blocks[2].spans[0].ruby != null);
    try std.testing.expectEqualStrings("before（first）", try plainText(a, blocks[0].spans));
    try std.testing.expectEqualStrings("after（last）", try plainText(a, blocks[2].spans));
    _ = try NonfloatingImageTest.occurrence(blocks[1], "Logo.svg", 40);
    try std.testing.expectEqualStrings("Before", blocks[0].spans[0].ruby.?.segments[0].bases[0].spans[0].target);
    try std.testing.expectEqualStrings("After", blocks[2].spans[0].ruby.?.segments[0].bases[0].spans[0].target);
    const boundary = Renderer.bidiBoundary(" ", blocks[0].spans[0]);
    try std.testing.expect(boundary.ruby == null and boundary.kind == .text);
    try std.testing.expectEqualStrings(" ", boundary.text);
    try std.testing.expectEqualStrings("{{literal}}（reading）", try renderer.inlineImagePlainText("<ruby><nowiki>{{literal}}</nowiki><rt>reading</rt></ruby>"));
    try std.testing.expectError(error.UncompiledTemplate, renderer.inlineImagePlainText("<ruby>{{missing}}<rt>reading</rt></ruby>"));
    const directed = try renderer.parseSpans("<span dir='rtl'><ruby>base<rt>reading</rt></ruby></span>", .{});
    try std.testing.expectEqualStrings("rtl", directed[0].direction);
    const bracket = try renderer.parseSpans("<ruby>[</ruby>", .{});
    var crossing = [_]Span{ .{ .text = "[", .generated_diagnostic = true }, bracket[0] };
    try separateGeneratedDiagnosticBoundaries(a, &crossing);
    try std.testing.expectEqualStrings("[ ", crossing[0].text);
    try std.testing.expectEqualStrings("[", crossing[1].ruby.?.segments[0].bases[0].spans[0].text);
    const readonly_child = [_]Span{.{ .text = "[", .generated_diagnostic = true }};
    const readonly_bases = [_]presentation_types.RubyBase(Span){.{ .owner = .{ .font = .{} }, .spans = &readonly_child }};
    const readonly_segments = [_]presentation_types.RubySegment(Span){.{ .bases = &readonly_bases }};
    const readonly_ruby: presentation_types.Ruby(Span) = .{ .segments = &readonly_segments };
    var refused = [_]Span{ .{ .text = "[" }, .{ .text = "", .ruby = &readonly_ruby } };
    try std.testing.expectError(error.UncompiledTemplate, separateGeneratedDiagnosticBoundaries(a, &refused));
    const adjacent_children = [_]Span{ .{ .text = "[" }, .{ .text = "[", .generated_diagnostic = true } };
    const adjacent_bases = [_]presentation_types.RubyBase(Span){.{ .owner = .{ .font = .{} }, .spans = &adjacent_children }};
    const adjacent_segments = [_]presentation_types.RubySegment(Span){.{ .bases = &adjacent_bases }};
    const adjacent_ruby: presentation_types.Ruby(Span) = .{ .segments = &adjacent_segments };
    const nested_children = [_]Span{.{ .text = "", .ruby = &adjacent_ruby }};
    const nested_bases = [_]presentation_types.RubyBase(Span){.{ .owner = .{ .font = .{} }, .spans = &nested_children }};
    const nested_segments = [_]presentation_types.RubySegment(Span){.{ .bases = &nested_bases }};
    const nested_ruby: presentation_types.Ruby(Span) = .{ .segments = &nested_segments };
    var prepared = [_]Span{.{ .text = "", .ruby = &nested_ruby }};
    try separateGeneratedDiagnosticBoundaries(a, &prepared);
    try std.testing.expectEqualStrings("[ [", try plainText(a, &prepared));
    try std.testing.expectEqualStrings("[", adjacent_children[1].text);
    try std.testing.expect(prepared[0].ruby.?.segments[0].bases[0].spans[0].ruby.?.segments[0].bases[0].spans[1].generated_diagnostic);
}

