test "selected prefix table projection retains unrelated Missing intervals and current scope" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer styles.deinit();
    const root: table_style_profile.TextElement = .{ .tag = "div", .classes = "mw-parser-output" };
    const scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "", .page_styles = &styles, .page_style_root = &root };
    const source = "ordinary prefix.....[[:missing]]...tail";
    const ranges = [_]missing_dependency.Range{.{ .start = 20, .end = 33, .occurrence = 1 }};
    const tracked: MissingText = .{ .bytes = source, .ranges = &ranges, .unknown = true };
    const copies = [_]SourceElementProjection.Copy{.{ .original_start = 0, .prepared_start = 0, .len = source.len }};
    var projection: SourceElementProjection = .{ .original = tracked, .prepared = source, .copies = &copies,
        .observed_source = .{ .source = source, .scope = &scope } };
    const F = struct {
        fn observed(raw: ?*const anyopaque, bytes: []const u8) ?ObservedTextClassScope {
            const selected: *const table_style_profile.BoundedTextClassScope = @ptrCast(@alignCast(raw orelse return null));
            return .{ .source = bytes, .scope = selected };
        }
        fn table(_: ?*const anyopaque, _: A, _: []const u8, _: usize) A.Error!?TableContainingDirectionObservation { return null; }
        fn sizing(_: ?*const anyopaque, _: A, _: []const u8, _: presentation_types.FigureFormat, _: ?u32, _: ?u32) A.Error!?presentation_types.FigureSizingPolicy { return null; }
    };
    const selected: TableContainingDirectionSource = .{ .prefix_viewport = true, .root_only = true,
        .source = source, .context = &scope, .preflight_scope = F.observed, .observe = F.table };
    var binding: TableDirectionRangeBinding = .{ .projection = &projection, .owner = tracked, .page_start = 0 };
    try std.testing.expect(binding.sourceCurrent(selected, &styles));
    try std.testing.expectEqual(@as(?usize, 0), binding.originalRange(source[0..15]));
    try std.testing.expect(binding.originalRange(source[20..25]) == null);
    try std.testing.expect(tracked.unknown and projection.original.unknown and binding.owner.unknown);
    try std.testing.expectEqualDeep(ranges[0], projection.original.ranges[0]);
    var derived = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer derived.deinit();
    var foreign = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer foreign.deinit();
    var renderer: Renderer = .{ .a = a, .content_root = .parser_output, .context = .{ .table_styles = &styles,
        .figure_sizing = .{ .resolve_fn = F.sizing, .table_containing_direction = selected } }, .table_direction_binding = binding };
    try std.testing.expect(renderer.tableDirectionSource() != null);
    renderer.context.table_styles = &derived;
    try std.testing.expect(renderer.tableDirectionSource() == null);
    renderer.table_direction_profile = .{ .source = source, .source_profile = &styles, .derived_profile = &derived };
    try std.testing.expect(renderer.tableDirectionSource() != null);
    renderer.context.table_styles = &foreign;
    try std.testing.expect(renderer.tableDirectionSource() == null);
    renderer.context.table_styles = &derived;
    renderer.table_direction_profile.?.source_profile = &foreign;
    try std.testing.expect(renderer.tableDirectionSource() == null);
    renderer.table_direction_profile.?.source_profile = &styles;
    const foreign_bytes = try a.dupe(u8, source);
    renderer.table_direction_profile.?.source = foreign_bytes;
    try std.testing.expect(renderer.tableDirectionSource() == null);
    renderer.table_direction_profile.?.source = source;
    try std.testing.expect(renderer.tableDirectionSource() != null);
    renderer.table_direction_profile = null;
    renderer.context.table_styles = &styles;
    try std.testing.expect(renderer.tableDirectionSource() != null);
    const link: Renderer.TableSourceLink = .{ .token = source[0..15], .target = "target", .external = false,
        .subject = 0, .cell = 0, .attributes = &.{} };
    renderer.table_viewport_cell_source = .{ .source = source[0..15], .links = &.{link}, .closed_focus = true,
        .language = "", .direction = .ltr, .font_scale = null, .font_scale_basis = .context };
    const clean_prefix: MissingText = .{ .bytes = source[0..15], .unknown = true };
    try std.testing.expect(renderer.selectedTableQuoteSource(clean_prefix));
    try std.testing.expect(renderer.selectedTableSourceState(clean_prefix));
    renderer.inline_missing = clean_prefix;
    // The source phase is admissible, but missing per-action font evidence is
    // still a hard refusal after the unchanged destination/source checks.
    try std.testing.expectError(error.UncompiledPresentation,
        renderer.tableLinkStyle(.{}, .{ .target = "target" }, clean_prefix.bytes));

    var quote_map: QuoteSourceMap = .{};
    const quoted = try normalizeWikiQuotesMappedInDomain(a, clean_prefix, 0, false, .{}, null, &quote_map, true);
    try std.testing.expect(quoted.unknown and QuoteSourceMap.cleanLocal(quoted));
    {
        const quote_source = "'''[[target]]'''.....[[:missing]]";
        const prefix_end = std.mem.indexOf(u8, quote_source, ".....").?;
        const quote_prefix = quote_source[0..prefix_end];
        const missing_start = std.mem.indexOf(u8, quote_source, "[[:missing]]").?;
        const quote_ranges = [_]missing_dependency.Range{.{ .start = @intCast(missing_start), .end = @intCast(quote_source.len), .occurrence = 1 }};
        const quote_tracked: MissingText = .{ .bytes = quote_source, .ranges = &quote_ranges, .unknown = true };
        const quote_copies = [_]SourceElementProjection.Copy{.{ .original_start = 0, .prepared_start = 0, .len = quote_source.len }};
        const quote_projection: SourceElementProjection = .{ .original = quote_tracked, .prepared = quote_source,
            .copies = &quote_copies, .observed_source = .{ .source = quote_source, .scope = &scope } };
        var operation_renderer = renderer;
        operation_renderer.table_direction_binding = .{ .projection = &quote_projection, .owner = quote_tracked, .page_start = 0 };
        operation_renderer.context.figure_sizing.?.table_containing_direction.?.source = quote_source;
        operation_renderer.table_viewport_cell_source.?.source = quote_prefix;
        const quote_input: MissingText = .{ .bytes = quote_prefix, .unknown = true };
        var generated_map: QuoteSourceMap = .{};
        const generated = try normalizeWikiQuotesMappedInDomain(a, quote_input, 0, false, .{}, null, &generated_map, true);
        try std.testing.expect(generated.unknown and QuoteSourceMap.cleanLocal(generated));
        try std.testing.expect(generated_map.generated.items.len != 0 and starts(generated.bytes, "<b>"));
        // A whole generated-tag output cannot pass coveredOriginal: its ends
        // are generated tags. Exact token ranges still have authored copies.
        try std.testing.expect(operation_renderer.tableLinkOriginalIn(generated.bytes, null, 0) == null);
        try std.testing.expect(!operation_renderer.selectedTableSourceState(generated));
        var domain: Renderer.TableLinkQuoteDomain = .{ .map = &generated_map, .cell = quote_prefix, .parent = null };
        operation_renderer.table_link_quote_source = &domain;
        try std.testing.expect(operation_renderer.tableLinkOriginalIn(generated.bytes, &domain, 0) == null);
        try std.testing.expect(operation_renderer.selectedTableSourceState(generated));
        const token_at = std.mem.indexOf(u8, generated.bytes, "[[target]]").?;
        try std.testing.expect(operation_renderer.selectedTableSourceRange(generated,
            generated.bytes[token_at..][0.."[[target]]".len]));
        domain.cell = try a.dupe(u8, quote_prefix);
        try std.testing.expect(!operation_renderer.selectedTableSourceState(generated));
        domain.cell = quote_prefix;
        const original = generated_map.original;
        generated_map.original = try a.dupe(u8, quote_prefix);
        try std.testing.expect(!operation_renderer.selectedTableSourceState(generated));
        generated_map.original = original;
        try std.testing.expect(operation_renderer.selectedTableSourceState(generated));
        operation_renderer.table_link_quote_source = null;
        try std.testing.expect(!operation_renderer.selectedTableSourceState(generated));
    }

    renderer.table_viewport_cell_source.?.closed_focus = false;
    try std.testing.expect(!renderer.selectedTableQuoteSource(clean_prefix));
    renderer.table_viewport_cell_source.?.closed_focus = true;
    const foreign_prefix: MissingText = .{ .bytes = try a.dupe(u8, clean_prefix.bytes), .unknown = true };
    try std.testing.expect(!renderer.selectedTableQuoteSource(foreign_prefix));
    try std.testing.expect(!renderer.selectedTableSourceState(foreign_prefix));
    renderer.inline_missing = foreign_prefix;
    try std.testing.expect((try renderer.tableLinkStyle(.{}, .{ .target = "target" }, foreign_prefix.bytes)) == null);
    renderer.inline_missing = clean_prefix;

    const tainted_prefix: MissingText = .{ .bytes = source[0..15], .unknown = true,
        .ranges = &.{.{ .start = 1, .end = 2, .occurrence = 1 }} };
    try std.testing.expect(!renderer.selectedTableQuoteSource(tainted_prefix));
    renderer.table_direction_binding.?.owner.lost_missing_range = true;
    try std.testing.expect(!renderer.selectedTableQuoteSource(clean_prefix));
    renderer.table_direction_binding = binding;
    projection.observed_source = null;
    try std.testing.expect(!binding.sourceCurrent(selected, &styles));
    try std.testing.expect(binding.originalRange(source[0..15]) == null);
    projection.observed_source = .{ .source = source, .scope = &scope };
    var foreign_scope = scope;
    projection.observed_source.?.scope = &foreign_scope;
    try std.testing.expect(!binding.sourceCurrent(selected, &styles));
    projection.observed_source.?.scope = &scope;
    binding.owner.lost_missing_range = true;
    try std.testing.expect(!binding.sourceCurrent(selected, &styles));
}

test "selected prefix table projection refuses malformed intervals and unissued unknown views" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer styles.deinit();
    const root: table_style_profile.TextElement = .{ .tag = "div", .classes = "mw-parser-output" };
    const scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "", .page_styles = &styles, .page_style_root = &root };
    const source = "ordinary prefix.....[[:missing]]...tail";
    const copies = [_]SourceElementProjection.Copy{.{ .original_start = 0, .prepared_start = 0, .len = source.len }};
    const F = struct {
        fn observed(raw: ?*const anyopaque, bytes: []const u8) ?ObservedTextClassScope {
            return .{ .source = bytes, .scope = @ptrCast(@alignCast(raw orelse return null)) };
        }
        fn table(_: ?*const anyopaque, _: A, _: []const u8, _: usize) A.Error!?TableContainingDirectionObservation { return null; }
    };
    const selected: TableContainingDirectionSource = .{ .prefix_viewport = true, .root_only = true,
        .source = source, .context = &scope, .preflight_scope = F.observed, .observe = F.table };
    const cases = [_][2]missing_dependency.Range{
        .{ .{ .start = 20, .end = 24, .occurrence = 1 }, .{ .start = 10, .end = 12, .occurrence = 2 } },
        .{ .{ .start = 20, .end = 24, .occurrence = 1 }, .{ .start = 23, .end = 26, .occurrence = 2 } },
        .{ .{ .start = 20, .end = 24, .occurrence = 1 }, .{ .start = 25, .end = 999, .occurrence = 2 } },
        .{ .{ .start = 20, .end = 20, .occurrence = 1 }, .{ .start = 25, .end = 26, .occurrence = 2 } },
        .{ .{ .start = 20, .end = 24, .occurrence = 0 }, .{ .start = 25, .end = 26, .occurrence = 2 } },
    };
    for (cases) |ranges| {
        const tracked: MissingText = .{ .bytes = source, .ranges = &ranges, .unknown = true };
        const projection: SourceElementProjection = .{ .original = tracked, .prepared = source, .copies = &copies,
            .observed_source = .{ .source = source, .scope = &scope } };
        const binding: TableDirectionRangeBinding = .{ .projection = &projection, .owner = tracked, .page_start = 0 };
        try std.testing.expect(!binding.sourceCurrent(selected, &styles));
        try std.testing.expect(binding.originalRange(source[0..15]) == null);
    }
    const tracked: MissingText = .{ .bytes = source, .unknown = true };
    const projection: SourceElementProjection = .{ .original = tracked, .prepared = source, .copies = &copies };
    const binding: TableDirectionRangeBinding = .{ .projection = &projection, .owner = tracked, .page_start = 0 };
    try std.testing.expect(!binding.sourceCurrent(selected, &styles));
}

const ManualCategoryMetadata153Test = struct {
    const token = "-{byʿḥ[[Category:Automatic Inscriptional Pahlavi transliterations containing ambiguous characters]]}-";
    // Exact retained 508-byte complete translation line, followed by test context LF.
    const line = "* <span class=\"trad-pal\">Farisiya navîn</span>[[Kategorî:Werger bi farisiya navîn]]: <span class=\"Phli\" lang=\"pal\">-{[[:𐭡𐭩𐭥𐭧#Farisiya&#95;navîn|𐭡𐭩𐭥𐭧]]}-</span> <span class=\"mention-gloss-paren annotation-paren\">(</span><span lang=\"pal-Latn\" class=\"tr Latn\">-{byʿḥ[[Category:Automatic Inscriptional Pahlavi transliterations containing ambiguous characters]]}-</span> <span class=\"ts mention-ts Latn\">/⁠māh⁠/</span><span class=\"mention-gloss-paren annotation-paren\">)</span>";
    fn registry(a: std.mem.Allocator) !@import("namespace_registry").Registry {
        const NS = @import("namespace_registry");
        const fixture = try std.mem.replaceOwned(u8, a, NS.english_test_fixture, "\tCAT\n", "\tCAT\tKategorî\n");
        var ns = try NS.Registry.init(a, fixture);
        ns.content_language = "ku";
        ns.language_conversion = &.{ "ku", "ku-arab", "ku-latn" };
        ns.manual_conversion_context = BundleManualChoiceTest.context();
        return ns;
    }
};

test "retained KU no-rule category metadata preserves complete translation body actions language and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = ManualCategoryMetadata153Test;
    var ns = try T.registry(a); defer ns.deinit();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior, .content_conversion = true };
    const source = T.line ++ "\n\n[[Next|next]] [https://example.test/after after]\n";
    // The converter wrapper is an inline parsing boundary. The category has no
    // visible bytes, action, or newline effect in this complete single-line body.
    const reference = try std.mem.replaceOwned(u8, a, source, T.token, "<span>byʿḥ</span>");
    var actual_renderer: Renderer = .{ .a = a, .context = context };
    var expected_renderer: Renderer = .{ .a = a, .context = context };
    const actual = try FormattingScopeTest.encode(a, &actual_renderer, try actual_renderer.renderBody(source));
    const expected = try FormattingScopeTest.encode(a, &expected_renderer, try expected_renderer.renderBody(reference));
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
    try std.testing.expect(!actual_renderer.fallbacks.any());
    var transliterations: usize = 0; var actions: usize = 0;
    for (actual.entry.sections[0].blocks) |block| for (block.spans) |span| {
        try std.testing.expect(std.mem.indexOf(u8, span.text, "Category:") == null);
        try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
        if (std.mem.eql(u8, span.text, "byʿḥ")) {
            transliterations += 1;
            try std.testing.expectEqualStrings("pal-Latn", span.language);
            try std.testing.expectEqualStrings("tr Latn", span.classes);
            try std.testing.expect(span.kind == .text and span.target.len == 0);
        }
        if (span.target.len != 0) {
            actions += 1;
            try std.testing.expect(std.mem.indexOf(u8, span.target, "Category:") == null);
        }
    };
    try std.testing.expectEqual(@as(usize, 1), transliterations);
    try std.testing.expectEqual(@as(usize, 3), actions);
    const codec = @import("blob_encoder").presentation_codec;
    const encoded = try codec.encodeAlloc(a, actual);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), encoded);
    const decoded = try codec.decodeAlloc(a, encoded, "formatting scope", .language, .{ .heading = "English", .code = "en" });
    try std.testing.expectEqualDeep(actual, decoded);
    try std.testing.expectEqualSlices(u8, encoded, try codec.encodeAlloc(a, decoded));
}

test "no-rule category proof refuses visible choices protected and foreign source without changing metadata" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = ManualCategoryMetadata153Test;
    var ns = try T.registry(a); defer ns.deinit();
    const parent = "<span lang='pal-Latn'>" ++ T.token ++ "</span> tail";
    const at = "<span lang='pal-Latn'>".len;
    const close = at + T.token.len - 2;
    const tracked: MissingText = .{ .bytes = parent, .ranges = &.{.{ .start = parent.len - 4, .end = parent.len, .occurrence = 1 }} };
    var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .content_conversion = true }, .inline_missing = tracked };
    var domain: InlineSourceDomain = .{ .source = parent, .tracked = tracked, .parent = null };
    renderer.inline_source_domain = &domain;
    const selected = renderer.manualCategoryMetadataBody(parent, at, close, .{}) orelse return error.TestUnexpectedResult;
    try std.testing.expect(selected.ptr == parent[at + 2 ..].ptr and selected.len == T.token.len - 4);
    try std.testing.expectEqualDeep(tracked, renderer.inline_missing.?);
    try std.testing.expect(renderer.inline_source_domain == &domain);
    const borrowed = try missingSlice(a, tracked, selected);
    try std.testing.expect(!borrowed.unknown and !borrowed.lost_missing_range and borrowed.ranges.len == 0);
    const conversion = try renderer.manualConversion(parent, at, .{});
    try std.testing.expect(conversion.body.ptr == selected.ptr and conversion.end == close + 2);
    try std.testing.expect(!renderer.manualConversionLinkedScope(selected, true));
    for (0..8) |mode| {
        var candidate = tracked;
        switch (mode) {
            0 => candidate.unknown = true,
            1 => candidate.lost_missing_range = true,
            2 => candidate.generated_source = parent,
            3 => candidate.bytes = try a.dupe(u8, parent),
            4 => candidate.ranges = &.{.{ .start = at + 2, .end = at + 3, .occurrence = 1 }},
            5 => candidate.literal_curly_ranges = &.{.{ .start = at + 1, .end = at + 2 }},
            6 => candidate.generated_links = &.{.{ .start = at + 2, .end = at + 3, .bound = &.{ .root = parent, .start = at + 2, .end = at + 3, .value = .{ .token = "x", .argument = "x", .target = "x", .label = "x" } } }},
            7 => candidate.bytes = parent[at + 1 ..],
            else => unreachable,
        }
        renderer.inline_missing = candidate;
        try std.testing.expect(renderer.manualCategoryMetadataBody(parent, at, close, .{}) == null);
        try std.testing.expectEqualDeep(candidate, renderer.inline_missing.?);
    }
    renderer.inline_missing = tracked;
    for (0..5) |mode| {
        domain = .{ .source = parent, .tracked = tracked, .parent = null };
        switch (mode) {
            0 => domain.source = try a.dupe(u8, parent),
            1 => domain.tracked = null,
            2 => domain.tracked.?.unknown = true,
            3 => domain.tracked.?.generated_source = parent,
            4 => domain.tracked.?.literal_curly_ranges = &.{.{ .start = at, .end = at + 1 }},
            else => unreachable,
        }
        try std.testing.expect(renderer.manualCategoryMetadataBody(parent, at, close, .{}) == null);
    }
    domain = .{ .source = parent, .tracked = tracked, .parent = null };
    for ([_]Style{ .{ .code = true }, .{ .preserve_whitespace = true }, .{ .provenance = .protected_literal },
        .{ .kind = .link, .target = "Outer" }, .{ .kind = .external_link, .target = "https://example.test" } }) |style|
        try std.testing.expect(renderer.manualCategoryMetadataBody(parent, at, close, style) == null);
    renderer.in_reference = true;
    try std.testing.expect(renderer.manualCategoryMetadataBody(parent, at, close, .{}) == null);
    renderer.in_reference = false;
    renderer.context.content_conversion = false;
    try std.testing.expect(renderer.manualCategoryMetadataBody(parent, at, close, .{}) == null);
    renderer.context.content_conversion = true;
    ns.manual_conversion_context.?.source_core = "unproved";
    try std.testing.expect(renderer.manualCategoryMetadataBody(parent, at, close, .{}) == null);
    ns.manual_conversion_context = BundleManualChoiceTest.context();
    renderer.inline_source_domain = null;
    for ([_][]const u8{
        "-{by[[Category:]]}-", "-{by[[Category:Name|sort]]}-", "-{by[[:Category:Name]]}-",
        "-{by[[File:Name]]}-", "-{by[[remote:Category:Name]]}-", "-{by[[Category:Name]]trail}-",
        "-{by[[Category:Name#fragment]]}-", "-{by[[Category:Na%6de]]}-", "-{by[[Category:Name;choice]]}-",
        "-{by[[Category:Name]]:choice}-", "-{ku:[[Category:Name]];ku-latn:other}-", "-{A|by[[Category:Name]]}-",
        "-{by[[Category:Name]]<b>text</b>}-", "-{by[[Category:Name]]\ntext}-", "-{by[[Category:Name]]{{missing}}}-",
        "-{by[[Category:Name]]''text''}-", "-{by[[Category:Name]]\xff}-", "-{by[[Category:Name] }-",
        "-{by[https://example.test label]}-", "-{by[[Category:Name]][[Action|label]]}-", "-{[[Category:Name]]}-",
    }) |source| {
        renderer.inline_missing = .{ .bytes = source };
        try std.testing.expect(renderer.manualCategoryMetadataBody(source, 0, source.len - 2, .{}) == null);
    }
    const attribute = "<span title='" ++ T.token ++ "'>body</span>";
    renderer.inline_missing = .{ .bytes = attribute };
    try std.testing.expect(renderer.manualCategoryMetadataBody(attribute, "<span title='".len,
        "<span title='".len + T.token.len - 2, .{}) == null);
    const choice = "-{ku:[[Category:Hidden]];ku-latn:shown}-";
    try std.testing.expect((try BundleManualChoiceTest.selection(&renderer, .{ .bytes = choice }, .{})) == null);
}


test "empty row color census preserves current source and Missing custody refusals" {
