    const facts = (try renderer.rowColorAttributesForTag(tag)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(table_style_profile.AttributePresence.absent, facts.get(facts.ctx, "bgcolor"));
    const saved = scope.closed_row_colors;
