        try std.testing.expect(changed.rowColorSourceProof() == null);
        scope.closed_row_colors = saved;
    }
    try std.testing.expect(renderer.rowColorSourceProof() == proof);
    source[0] = 'X';
    try std.testing.expect(renderer.rowColorSourceProof() == null);
}


test "Ruby retained TH label keeps full children actions fonts and codec under proved ancestor class absence" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    // Exact first Ruby-bearing label from retained TH p108817/r2190988.
    // This local source-contract control does not certify the complete page CSS.
    const source = "<span class=\"Jpan\" lang=\"ja\">[[:間性#ภาษาญี่ปุ่น|<ruby>間性<rp>(</rp><rt>かんせい</rt><rp>)</rp></ruby>]]</span>";
    const visible_css = ".Jpan{font-size:120%}.Jpan ruby rt{font-size:60%}";
    const unrelated_css = "*.center *{margin-left:auto;margin-right:auto}.Egyd *{font-style:normal;direction:rtl}";
    var actual_profile = try table_style_profile.parseForTargetAlloc(a, visible_css ++ unrelated_css, .screen); defer actual_profile.deinit();
    var expected_profile = try table_style_profile.parseForTargetAlloc(a, visible_css, .screen); defer expected_profile.deinit();
    const scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output",
        .subtree_classes = "Jpan", .complete_ancestor_class_superset = "mw-parser-output Jpan" };
    var actual: Renderer = .{ .a = a, .context = .{ .table_styles = &actual_profile, .text_paint_styles = &actual_profile },
        .body_depth = 1, .content_root = .parser_output, .bounded_text_class_scope = &scope, .bounded_text_class_source = source };
    var expected: Renderer = .{ .a = a, .context = .{ .table_styles = &expected_profile, .text_paint_styles = &expected_profile },
        .body_depth = 1, .content_root = .parser_output, .bounded_text_class_scope = &scope, .bounded_text_class_source = source };
    const actual_spans = try actual.parseSpans(source, .{});
    const expected_spans = try expected.parseSpans(source, .{});
    try std.testing.expectEqualStrings("間性(かんせい)", try flattened(a, actual_spans));
    const ruby = actual_spans[0].ruby orelse return error.TestUnexpectedResult;
    const segment = ruby.segments[0];
    try std.testing.expectEqualStrings("間性", segment.bases[0].spans[0].text);
    try std.testing.expectEqualStrings("かんせい", segment.annotations[0].spans[0].text);
    try std.testing.expect(segment.annotations[0].explicit_fallback);
    try std.testing.expectApproxEqAbs(@as(f32, 1.2), segment.bases[0].spans[0].font_scale.?, 0.00001);
    try std.testing.expectApproxEqAbs(@as(f32, 0.72), segment.annotations[0].spans[0].font_scale.?, 0.00001);
    const leaves = try RubyProducerTest.leaves(a, actual_spans);
    try std.testing.expectEqual(@as(usize, 4), leaves.len);
    for (leaves) |leaf| {
        try std.testing.expectEqual(ir.InlineKind.link, leaf.kind);
        try std.testing.expectEqualStrings("間性#ภาษาญี่ปุ่น", leaf.target);
        try std.testing.expectEqualStrings("ja", leaf.language);
    }
    const actual_stored = try FormattingScopeTest.encode(a, &actual, &.{.{ .kind = .paragraph, .spans = actual_spans }});
    const expected_stored = try FormattingScopeTest.encode(a, &expected, &.{.{ .kind = .paragraph, .spans = expected_spans }});
    try std.testing.expectEqualDeep(expected_stored, actual_stored);
    try std.testing.expectEqualDeep(expected.fallbacks, actual.fallbacks);
    for (0..3) |mode| {
        var refused_scope = scope;
        const foreign = try a.dupe(u8, source);
        var refused: Renderer = .{ .a = a, .context = .{ .table_styles = &actual_profile, .text_paint_styles = &actual_profile },
            .body_depth = 1, .content_root = .parser_output, .bounded_text_class_scope = &refused_scope,
            .bounded_text_class_source = if (mode == 2) foreign else source };
        if (mode == 0) refused_scope.complete_ancestor_class_superset = null;
        if (mode == 1) refused_scope.complete_ancestor_class_superset = "mw-parser-output Jpan center";
        try std.testing.expectError(error.UncompiledPresentation, refused.parseSpans(source, .{}));
    }
}


