test "retained recursive conversion after empty TemplateStyles keeps complete sibling body languages actions and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = T.profile();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior };
    // Complete retained list lines; reference changes only the child no-rule
    // wrappers. It retains outer conversion boundaries and TemplateStyles.
    for ([_]struct { source: []const u8, reference: []const u8, language: []const u8, classes: []const u8,
        targets: []const []const u8, labels: []const []const u8 }{
        .{ .source = "* 印尼語：<span class=\"Latn\" lang=\"id\">-{[[:darma#印尼語|-{darma}-]]}-</span><templatestyles src=\"Module:etymology/style.css\"/>, <span class=\"Latn\" lang=\"id\">-{[[:derma#印尼語|-{derma}-]]}-</span>",
            .reference = "* 印尼語：<span class=\"Latn\" lang=\"id\">-{[[:darma#印尼語|darma]]}-</span><templatestyles src=\"Module:etymology/style.css\"/>, <span class=\"Latn\" lang=\"id\">-{[[:derma#印尼語|derma]]}-</span>",
            .language = "id", .classes = "Latn",
            .targets = &.{ "darma#印尼語", "derma#印尼語" }, .labels = &.{ "darma", "derma" } },
        .{ .source = "* 日語：<span class=\"Jpan\" lang=\"ja\">-{[[:達磨#日語|-{達磨}-]]}-</span><templatestyles src=\"Module:etymology/style.css\"/>, <span class=\"Jpan\" lang=\"ja\">-{[[:ダルマ#日語|-{ダルマ}-]]}-</span>, <span class=\"Jpan\" lang=\"ja\">-{[[:ダーマ#日語|-{ダーマ}-]]}-</span>",
            .reference = "* 日語：<span class=\"Jpan\" lang=\"ja\">-{[[:達磨#日語|達磨]]}-</span><templatestyles src=\"Module:etymology/style.css\"/>, <span class=\"Jpan\" lang=\"ja\">-{[[:ダルマ#日語|ダルマ]]}-</span>, <span class=\"Jpan\" lang=\"ja\">-{[[:ダーマ#日語|ダーマ]]}-</span>",
            .language = "ja", .classes = "Jpan",
            .targets = &.{ "達磨#日語", "ダルマ#日語", "ダーマ#日語" }, .labels = &.{ "達磨", "ダルマ", "ダーマ" } },
    }) |case| for ([_]bool{ false, true }) |unknown| {
        const source = try std.mem.concat(a, u8, &.{ case.source, "\n\n", T.marked });
        const reference = try std.mem.concat(a, u8, &.{ case.reference, "\n\n", T.marked });
        var tracked = try T.tracked(a, source); tracked.unknown = unknown;
        var expected_tracked = try T.tracked(a, reference); expected_tracked.unknown = unknown;
        var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
        var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = expected_tracked };
        const blocks = try actual_renderer.renderBodyWithMissing(tracked);
        const expected_blocks = try expected_renderer.renderBodyWithMissing(expected_tracked);
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, expected_blocks);
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
        try std.testing.expectEqual(unknown, actual_renderer.body_missing.?.unknown);
        try std.testing.expectEqualDeep(tracked.ranges, actual_renderer.body_missing.?.ranges);
        try std.testing.expect(!actual_renderer.body_missing.?.lost_missing_range and actual_renderer.body_missing.?.generated_source == null);
        try std.testing.expect(!ns.manual_conversion_context.?.automatic_identity);
        var links: usize = 0; var lists: usize = 0; var missing: usize = 0;
        for (blocks) |block| {
            if (block.kind == .list_item) { lists += 1; try std.testing.expectEqualStrings("*", block.list_path); }
            for (block.spans) |span| {
                try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
                try std.testing.expect(std.mem.indexOf(u8, span.text, "templatestyles") == null);
                if (span.kind != .link) continue;
                if (std.mem.eql(u8, span.target, "Template:R:hi:Rajpal")) { missing += 1; continue; }
                try std.testing.expect(links < case.targets.len);
                try std.testing.expectEqualStrings(case.targets[links], span.target);
                try std.testing.expectEqualStrings(case.labels[links], span.text);
                try std.testing.expectEqualStrings(case.language, span.language);
                try std.testing.expectEqualStrings(case.classes, span.classes);
                links += 1;
            }
        }
        try std.testing.expectEqual(@as(usize, 1), lists);
        try std.testing.expectEqual(case.targets.len, links); try std.testing.expectEqual(@as(usize, 1), missing);
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    };
}

test "recursive empty TemplateStyles predecessor preserves exact source custody grammar and context refusals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = T.profile();
    const first = "-{[[:darma#印尼語|-{darma}-]]}-";
    const last = "-{[[:derma#印尼語|-{derma}-]]}-";
    const sheet = "<templatestyles src=\"Module:etymology/style.css\"/>";
    const before_sheet = "<span class=\"Latn\" lang=\"id\">" ++ first ++ "</span>";
    const prefix = before_sheet ++ sheet ++ ", <span class=\"Latn\" lang=\"id\">";
    const source = prefix ++ last ++ "</span>";
    const child = source[prefix.len..][0..last.len];
    for ([_]bool{ false, true }) |unknown| {
        const parent: MissingText = .{ .bytes = source, .unknown = unknown };
        const domain: InlineSourceDomain = .{ .source = source, .parent = null, .tracked = parent };
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns },
            .inline_missing = .{ .bytes = child, .unknown = unknown }, .inline_source_domain = &domain };
        try std.testing.expect(!Renderer.formattingAngleBodyPositionWithTrackedSiblings(source, prefix.len, true, parent));
        try std.testing.expect((try renderer.nestedRuleFreeLinkLabels(child, 0, .{})) == null);
        const result = (try renderer.sourceRecursiveRuleFreeLinkLabels(child, 0, .{})) orelse return error.TestUnexpectedResult;
        try std.testing.expect(result.body.ptr == child.ptr + 2 and result.body.len == child.len - 4 and result.end == child.len);
        try std.testing.expectEqual(unknown, (try missingSlice(a, renderer.inline_missing.?, result.body)).unknown);
    }
    for (0..14) |mode| {
        errdefer std.debug.print("recursive strip166 custody={d}\n", .{mode});
        var parent: MissingText = .{ .bytes = source, .unknown = true };
        var domain: InlineSourceDomain = .{ .source = source, .parent = null, .tracked = parent };
        switch (mode) {
            0 => parent.bytes = try a.dupe(u8, source),
            1 => parent.bytes = source[0..prefix.len-1],
            2 => parent.lost_missing_range = true,
            3 => parent.generated_source = source,
            4 => parent.ranges = &.{.{ .start = before_sheet.len, .end = before_sheet.len + sheet.len, .occurrence = 1 }},
            5 => parent.literal_curly_ranges = &.{.{ .start = before_sheet.len, .end = before_sheet.len + sheet.len }},
            6 => domain.source = try a.dupe(u8, source),
            7 => domain.source = source[0..prefix.len-1],
            else => {},
        }
        domain.tracked = if (mode == 8) null else parent;
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns },
            .inline_missing = .{ .bytes = child, .unknown = true }, .inline_source_domain = &domain };
        var style: Style = .{};
        switch (mode) {
            9 => style = .{ .kind = .link, .target = "Outer" },
            10 => renderer.in_reference = true,
            11 => renderer.pre_block = true,
            12 => renderer.explicit_wiki_label = .{ .kind = .link, .target = "Outer" },
            13 => ns.manual_conversion_context.?.source_core = "foreign",
            else => {},
        }
        defer ns.manual_conversion_context = T.profile();
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(child, 0, style)) == null);
    }
    for ([_][]const u8{
        "<templatestyles src='Module:x'>", "</templatestyles>", "<templatestyles/>",
        "<templatestyles src=''/>", "<templatestyles src='x' src='y'/>",
        "<templatestyles src='x' style='color:red'/>", "<templatestyles src='x' onclick='x'/>",
        "<templatestyles src='x&y'/>", "<templatestyles src='-{x}-'/>", "<templatestyles src='x\nq'/>",
        "<templatestyles src='x\x0bq'/>", "<templatestyles src='x/>",
        "<unknown src='x'/>", "<nowiki><templatestyles src='x'/>",
        "<pre><templatestyles src='x'/>", "[[Outer|<templatestyles src='x'/>",
    }) |bad| {
        const bad_prefix = try std.mem.concat(a, u8, &.{ before_sheet, bad, ", <span>" });
        const value = try std.mem.concat(a, u8, &.{ bad_prefix, last, "</span>" });
        const part = value[bad_prefix.len..][0..last.len];
        const parent: MissingText = .{ .bytes = value, .unknown = true };
        const domain: InlineSourceDomain = .{ .source = value, .parent = null, .tracked = parent };
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns },
            .inline_missing = .{ .bytes = part, .unknown = true }, .inline_source_domain = &domain };
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(part, 0, .{})) == null);
    }
}


test "typed Ruby optional RT end tag preserves explicit closure structure body actions and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    // HTML permits RT end omission when no content follows in its parent.
    // This preserves the actual172 accepted case as a positive equivalence.
    for ([_]struct { implicit: []const u8, explicit: []const u8 }{
        .{ .implicit = "<ruby>a<rt>x</ruby>", .explicit = "<ruby>a<rt>x</rt></ruby>" },
        .{ .implicit = "before <ruby>[[Base|base]]<rt><i>[[Reading|reading]]</i></ruby> after", .explicit = "before <ruby>[[Base|base]]<rt><i>[[Reading|reading]]</i></rt></ruby> after" },
    }, 0..) |source, case_index| {
        errdefer std.debug.print("RUBY_OPTIONAL_RT_CASE={d}\n", .{case_index});
        var actual: Renderer = .{ .a = a, .context = .{} };
        var reference: Renderer = .{ .a = a, .context = .{} };
        const actual_blocks = try actual.renderBody(source.implicit);
        const reference_blocks = try reference.renderBody(source.explicit);
        try std.testing.expect(!actual.fallbacks.any() and !reference.fallbacks.any());
        try std.testing.expectEqual(@as(usize, 1), actual_blocks.len);
        try std.testing.expectEqual(@as(usize, 1), reference_blocks.len);
        // Build Block.text retains its authored input spelling. All semantic
        // fields must agree independently of this checked source distinction.
        try std.testing.expectEqualStrings(source.implicit, actual_blocks[0].text);
        try std.testing.expectEqualStrings(source.explicit, reference_blocks[0].text);
        var actual_semantic = actual_blocks[0];
        var reference_semantic = reference_blocks[0];
        actual_semantic.text = "";
        reference_semantic.text = "";
        try std.testing.expectEqualDeep(reference_semantic, actual_semantic);
        const ruby_index: usize = if (case_index == 0) 0 else 1;
        const ruby = actual_blocks[0].spans[ruby_index].ruby orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(usize, 1), ruby.segments.len);
        const segment = ruby.segments[0];
        try std.testing.expectEqual(@as(usize, 1), segment.bases.len);
        try std.testing.expectEqual(@as(usize, 1), segment.annotations.len);
        try std.testing.expectEqual(@as(u32, 0), segment.annotations[0].base_start);
        try std.testing.expectEqual(@as(u32, 1), segment.annotations[0].base_count);
        try std.testing.expectEqualStrings(if (case_index == 0) "a" else "base", segment.bases[0].spans[0].text);
        try std.testing.expectEqualStrings(if (case_index == 0) "x" else "reading", segment.annotations[0].spans[0].text);
        if (case_index != 0) {
            try std.testing.expectEqualStrings("Base", segment.bases[0].spans[0].target);
            try std.testing.expectEqualStrings("Reading", segment.annotations[0].spans[0].target);
            try std.testing.expect(segment.annotations[0].spans[0].flags.italic);
        }
        const actual_stored = try FormattingScopeTest.encode(a, &actual, actual_blocks);
        const reference_stored = try FormattingScopeTest.encode(a, &reference, reference_blocks);
        try std.testing.expectEqualDeep(reference_stored, actual_stored);
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeAlloc(a, actual_stored);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, reference_stored), bytes);
        try std.testing.expectEqualDeep(actual_stored, try codec.decodeAlloc(a, bytes, actual_stored.entry.title, .language,
            .{ .heading = actual_stored.entry.language.?, .code = actual_stored.entry.language_code }));
    }
}


test "ordinary generated link carries only current source parent class absence into Ruby" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const source = try a.dupe(u8, "<span class='Jpan'>[[Target|<ruby>base<rt>reading</rt></ruby>]]</span><span>[[Other|outside]]</span>");
    const selected_token = source[std.mem.indexOf(u8, source, "[[Target").?..std.mem.indexOf(u8, source, "]]").? + 2];
    const tag = syntax.tagAt(source, 0).?;
    const pair = syntax.matchingTag(source, tag).?;
    const inner = source[tag.end..pair.inner_end];
    const foreign = try a.dupe(u8, source);
    var profile = try table_style_profile.parseForTargetAlloc(a, "*.center *{margin-left:auto}.Egyd *{direction:rtl}", .screen); defer profile.deinit();
    for (0..19) |mode| {
        errdefer std.debug.print("RUBY_ANCHOR_CUSTODY mode={d}\n", .{mode});
        var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output",
            .subtree_classes = "Jpan", .complete_ancestor_class_superset = "mw-parser-output Jpan" };
        const other_scope = scope;
        var renderer: Renderer = .{ .a = a, .context = .{ .table_styles = &profile, .text_paint_styles = &profile },
            .body_depth = 1, .content_root = .parser_output, .bounded_text_class_scope = &scope, .bounded_text_class_source = source };
        var parent = (try renderer.textElement(tag, null, "ja")).*;
        var root_frame: InlineSourceDomain = .{ .source = source, .parent = null, .tracked = MissingText.untracked(source) };
        var local_frame: InlineSourceDomain = .{ .source = inner, .parent = &root_frame, .tracked = MissingText.untracked(inner) };
        var tracked = MissingText.untracked(inner);
        var style: Style = .{ .text_element = &parent, .language = "ja" };
        var token = selected_token;
        renderer.inline_source_domain = &local_frame;
        switch (mode) {
            0 => {},
            1 => renderer.bounded_text_class_source = foreign,
            2 => renderer.bounded_text_class_scope = &other_scope,
            3 => token = try a.dupe(u8, selected_token),
            4 => token = selected_token[0..selected_token.len - 1],
            5 => tracked.unknown = true,
            6 => tracked.ranges = &.{.{ .start = 0, .end = @intCast(inner.len), .occurrence = 1 }},
            7 => parent.ancestor_class_source = foreign,
            8 => parent.source_key = @intFromPtr(foreign.ptr) + 1,
            9 => parent.tag = "div",
            10 => renderer.content_root = .unknown,
            11 => style.provenance = .protected_literal,
            12 => style.code = true,
            13 => parent.complete_ancestor_classes = null,
            14 => local_frame.source = try a.dupe(u8, inner),
            15 => scope.complete_ancestor_class_superset = null,
            16 => token = source[std.mem.indexOf(u8, source, "[[Other").?..source.len - "</span>".len],
            17 => root_frame.source = source[1..],
            18 => local_frame.tracked = null,
            else => unreachable,
        }
        renderer.inline_missing = tracked;
        if (mode != 0) {
            try std.testing.expect(renderer.ordinaryLinkClassParent(style, token) == null);
            continue;
        }
        try std.testing.expect(renderer.ordinaryLinkClassParent(style, token) == &parent);
        const linked = try renderer.wikiLinkStyleIn(style, .{ .target = "Target" }, token);
        const anchor = linked.text_element orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("a", anchor.tag);
        try std.testing.expect(anchor.parent == &parent and anchor.ancestor_class_scope == &scope);
        try std.testing.expect(anchor.ancestor_class_source.?.ptr == source.ptr and anchor.ancestor_class_source.?.len == source.len);
        try std.testing.expect(!anchor.ancestry_complete and !anchor.physical_ancestry_complete and
            anchor.page_style_root == null and anchor.element_index == null and anchor.source_sibling == null);
        const ruby_at = std.mem.indexOf(u8, source, "<ruby>").?;
        const ruby_tag = syntax.tagAt(source, ruby_at).?;
        try std.testing.expect(try renderer.rubyLayoutSupported(ruby_tag, linked, source[ruby_at..]));
        // A possible/present ancestor cannot be turned into a negative match.
        for ([_][]const u8{ "mw-parser-output Jpan center", "mw-parser-output Jpan Egyd" }) |present| {
            parent.complete_ancestor_classes = present;
            const changed = try renderer.wikiLinkStyleIn(style, .{ .target = "Target" }, token);
            try std.testing.expect(!try renderer.rubyLayoutSupported(ruby_tag, changed, source[ruby_at..]));
        }
    }
}

