                    .resolve_inline_missing_fn = F.Issuer.observe, .text_class_scope = .{ .source = F.source, .scope = &scope },
                    .source_context = .{ .namespace_sha256 = namespaces.source_sha256, .defaults = namespaces.figure_source_defaults.?, .missing_media_profile = .f45897 } } } };
        if (copied) try renderer.heading_source_aliases.append(a, .{ .copied = current, .original = F.source });
        const owner: Renderer.InlineMissingCellOwner = .{ .table = syntax.tagAt(current, 0).?,
            .row = syntax.tagAt(current, F.row_start).?, .cell = syntax.tagAt(current, F.cell_start).?, .body = .{ .bytes = selected_token } };
        renderer.inline_missing_cell = &owner;
        try std.testing.expect(try renderer.emitObservedInlineMissing(.{ .bytes = current }, selected_token, "Sr-averz.ogg", .{}));
        try std.testing.expectEqual(@as(usize, 1), renderer.spans.items.len);
        const span = renderer.spans.items[0];
        try std.testing.expectEqualStrings("noicon", span.text);
        try std.testing.expect(span.kind == .external_link and span.image == null);
        try std.testing.expectEqualStrings(F.href, span.target);
        try std.testing.expectEqualStrings("File:Sr-averz.ogg", span.tooltip.?);
        try std.testing.expectEqualStrings("", span.explanation);
        try std.testing.expectEqualStrings("de", span.language);
        try std.testing.expectEqual(@as(?f32, 1), span.font_scale);
        try std.testing.expect(span.font_scale_basis == .normal_body and !span.flags.bold and !span.flags.italic);
        try std.testing.expect(span.link_paint != null and span.inline_style.?.line_height != null);
        try std.testing.expectEqual(@as(usize, 0), renderer.media.items.len);
        const body = [_]Block{.{ .kind = .paragraph, .spans = renderer.spans.items }};
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try CenteredImageTest.encoded(a, &renderer, &body);
        const stored = try codec.decodeAlloc(a, bytes, "inline missing", .language, .{ .code = "de", .heading = "Deutsch" });
        try std.testing.expectEqualStrings("noicon", stored.entry.sections[0].blocks[0].spans[0].text);
        try std.testing.expectEqualStrings(F.href, stored.entry.sections[0].blocks[0].spans[0].target);
        try std.testing.expectEqualDeep(span.link_paint, stored.entry.sections[0].blocks[0].spans[0].link_paint);
        try std.testing.expectEqualDeep(span.inline_style, stored.entry.sections[0].blocks[0].spans[0].inline_style);
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
        try std.testing.expect(span.inline_style.?.font_normalized);
        try std.testing.expect(!span.flags.small and !span.flags.superscript and !span.flags.subscript);
        try std.testing.expectEqual(span.link_paint.?.normal.underline, span.flags.underline);
        // A second operation cannot annotate or merge into an earlier span.
        // Unsupported parent size flags retain the earlier font refusal.
        renderer.block_formatting = .{ .small = true };
        try std.testing.expectError(error.UncompiledPresentation, renderer.emitObservedInlineMissing(
            .{ .bytes = current }, selected_token, "Sr-averz.ogg", .{}));
        try std.testing.expectEqual(@as(usize, 1), renderer.spans.items.len);
        try std.testing.expectEqualDeep(span, renderer.spans.items[0]);
        renderer.block_formatting = .{};
        try std.testing.expect(try renderer.emitObservedInlineMissing(.{ .bytes = current }, selected_token, "Sr-averz.ogg", .{}));
        try std.testing.expectEqual(@as(usize, 2), renderer.spans.items.len);
        try std.testing.expectEqualDeep(span, renderer.spans.items[0]);
        try std.testing.expectEqualDeep(span, renderer.spans.items[1]);
        // Ordinary action suppression must refuse the observation atomically.
        try std.testing.expectError(error.UncompiledPresentation, renderer.emitObservedInlineMissing(
            .{ .bytes = current }, selected_token, "Sr-averz.ogg", .{ .missing_nonaction = true }));
        try std.testing.expectEqual(@as(usize, 2), renderer.spans.items.len);
        try std.testing.expectEqualDeep(span, renderer.spans.items[0]);
        try std.testing.expectEqualDeep(span, renderer.spans.items[1]);
    }
}

test "inline Missing operation retains local source parent status and option refusals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = InlineMissingCompilerTest;
    var namespaces = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").german_test_fixture); defer namespaces.deinit();
    try FigureProducerTest.attachThumbnailDefaults(a, &namespaces, false);
    var options = try @import("namespace_registry").image_options.Registry.init(a, image_option_test_identity ++ "img_width\t1\t\"$1px\"\nimg_thumbnail\t1\t\"miniatur\"\n", "dewiktionary", "20261001", "de", @splat(0), @splat(0)); defer options.deinit();
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.parseForTargetAlloc(a, F.css, .screen); defer styles.deinit(); styles.page_style_parent = &parent;
    const observed: table_style_profile.InlineMissingContext = .{ .styles = &styles, .nodes = &F.nodes, .root = 2, .wrapper = 7, .anchor = 8, .label = 9 };
    var issuer: F.Issuer = .{ .styles = &styles, .contexts = &.{observed, observed} };
    var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "audiotable audiofile", .complete_ancestor_class_superset = "audiotable audiofile" };
    const context: Context = .{ .namespace_catalog = &namespaces, .image_options = &options, .table_styles = &styles,
        .figure_sizing = .{ .ctx = null, .resolve_fn = F.noSizing, .figure_style_ctx = &issuer,
            .resolve_inline_missing_fn = F.Issuer.observe, .text_class_scope = .{ .source = F.source, .scope = &scope },
            .source_context = .{ .namespace_sha256 = namespaces.source_sha256, .defaults = namespaces.figure_source_defaults.?, .missing_media_profile = .f45897 } } };
    for (0..9) |mode| {
        var renderer: Renderer = .{ .a = a, .content_root = .parser_output, .body_depth = 1, .bounded_text_class_source = F.source, .bounded_text_class_scope = &scope, .context = context };
        const token = F.source[F.token_start..][0..F.token.len];
        var owner: Renderer.InlineMissingCellOwner = .{ .table = syntax.tagAt(F.source, 0).?, .row = syntax.tagAt(F.source, F.row_start).?,
            .cell = syntax.tagAt(F.source, F.cell_start).?, .body = .{ .bytes = token } };
        renderer.inline_missing_cell = &owner;
        var tracked: MissingText = .{ .bytes = F.source };
        var style: Style = .{};
        switch (mode) {
            0 => tracked.lost_missing_range = true,
            1 => tracked.ranges = &.{.{ .start = F.token_start, .end = F.token_start + 1, .occurrence = 1 }},
            2 => owner.cell = syntax.tagAt(try a.dupe(u8, F.source), F.cell_start).?,
            3 => owner.body = .{ .bytes = F.source },
            4 => renderer.inline_missing_cell = null,
            5 => style.font_size_unknown = true,
            6 => style.font_scale = 0.88,
            7 => owner.body.generated_source = token,
            else => style.kind = .external_link,
        }
        try std.testing.expectError(error.UncompiledPresentation, renderer.emitObservedInlineMissing(tracked, token, "Sr-averz.ogg", style));
        try std.testing.expectEqual(@as(usize, 0), renderer.spans.items.len);
    }
    // A source pointer without a generated-link ledger is not generated
    // authority. The normal borrowed slice drops it; retain complete parity.
    var baseline: ?[]const u8 = null;
    for ([_]bool{ false, true }) |orphan_pointer| {
        var renderer: Renderer = .{ .a = a, .content_root = .parser_output, .body_depth = 1,
            .bounded_text_class_source = F.source, .bounded_text_class_scope = &scope, .context = context };
        const token = F.source[F.token_start..][0..F.token.len];
        const owner: Renderer.InlineMissingCellOwner = .{ .table = syntax.tagAt(F.source, 0).?,
            .row = syntax.tagAt(F.source, F.row_start).?, .cell = syntax.tagAt(F.source, F.cell_start).?,
            .body = .{ .bytes = token } };
        renderer.inline_missing_cell = &owner;
        const tracked: MissingText = .{ .bytes = F.source, .generated_source = if (orphan_pointer) F.source else null };
        const sliced = try missingSlice(a, tracked, token);
        try std.testing.expect(sliced.generated_source == null and sliced.generated_links.len == 0);
        try std.testing.expect(try renderer.emitObservedInlineMissing(tracked, token, "Sr-averz.ogg", .{}));
        try std.testing.expectEqual(@as(usize, 1), renderer.spans.items.len);
        try std.testing.expect(renderer.spans.items[0].kind == .external_link);
        try std.testing.expectEqualStrings(F.href, renderer.spans.items[0].target);
        try std.testing.expectEqualStrings("noicon", renderer.spans.items[0].text);
        const body = [_]Block{.{ .kind = .paragraph, .spans = renderer.spans.items }};
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try CenteredImageTest.encoded(a, &renderer, &body);
        const stored = try codec.decodeAlloc(a, bytes, "inline missing", .language, .{ .code = "de", .heading = "Deutsch" });
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
        if (baseline) |expected| {
            try std.testing.expectEqualSlices(u8, expected, bytes);
            try std.testing.expectEqualDeep(try codec.decodeAlloc(a, expected, "inline missing", .language,
                .{ .code = "de", .heading = "Deutsch" }), stored);
        } else baseline = bytes;
    }
    var absent: Renderer = .{ .a = a, .context = context, .content_root = .parser_output, .body_depth = 1,
        .bounded_text_class_source = F.source, .bounded_text_class_scope = &scope };
    issuer.present = false;
    try std.testing.expect(!try absent.emitObservedInlineMissing(.{ .bytes = F.source }, F.source[F.token_start..][0..F.token.len], "Sr-averz.ogg", .{}));
    try std.testing.expectEqual(@as(usize, 0), absent.spans.items.len);
    issuer.present = true;
    const foreign = try a.dupe(u8, F.source);
    try std.testing.expect(!try absent.emitObservedInlineMissing(.{ .bytes = foreign }, foreign[F.token_start..][0..F.token.len], "Sr-averz.ogg", .{}));
    for ([_][]const u8{ "noicon|175px|miniatur", "noicon|175px|176px", "noicon|0px", "[[label]]|175px", "noicon|175px|extra" }) |raw|
        try std.testing.expect(inlineMissingOptions(raw, context) == null);
}

const InlineMissingCompilerTest = if (@import("builtin").is_test) struct {
    const token = "[[File:Sr-averz.ogg|noicon|175px]]";
    const source = "<table class='audiotable'><tr><td class='audiofile'>" ++ token ++ "</td></tr></table>";
    const token_start = "<table class='audiotable'><tr><td class='audiofile'>".len;
    const row_start = "<table class='audiotable'>".len;
    const cell_start = "<table class='audiotable'><tr>".len;
    const href = "//commons.wikimedia.org/wiki/Special:UploadWizard?uselang=sr&wpDestFile=Sr-averz.ogg";
    const css = "html{font-family:sans-serif;font-size:100%;color:#202122}body{font-size:100%}.audiotable{line-height:1em}" ++
        "a.new{color:#d33;text-decoration:none}a.new:hover{text-decoration:underline}";
    const nodes = [_]table_style_profile.ObservedStyleNode{
        .{ .tag = "html", .attributes = &.{.{ .name = "lang", .value = "de" }}, .parent = null },
        .{ .tag = "body", .attributes = &.{}, .parent = 0 },
        .{ .tag = "div", .attributes = &.{.{ .name = "class", .value = "mw-parser-output" }}, .parent = 1 },
        .{ .tag = "table", .attributes = &.{.{ .name = "class", .value = "audiotable" }}, .parent = 2 },
        .{ .tag = "tbody", .attributes = &.{}, .parent = 3 },
        .{ .tag = "tr", .attributes = &.{}, .parent = 4 },
        .{ .tag = "td", .attributes = &.{.{ .name = "class", .value = "audiofile" }}, .parent = 5 },
        .{ .tag = "span", .attributes = &.{.{ .name = "typeof", .value = "mw:Error mw:File" }}, .parent = 6, .has_text = false },
        .{ .tag = "a", .attributes = &.{.{ .name = "class", .value = "new" }, .{ .name = "href", .value = href }, .{ .name = "title", .value = "File:Sr-averz.ogg" }}, .parent = 7, .has_text = false },
        .{ .tag = "span", .attributes = &.{.{ .name = "class", .value = "mw-file-element mw-broken-media" }, .{ .name = "data-width", .value = "175" }}, .parent = 8, .has_text = true, .empty = false },
    };
    const Issuer = struct {
        styles: *const table_style_profile.Profile, contexts: []const table_style_profile.InlineMissingContext, present: bool = true,
        fn observe(raw: ?*const anyopaque, _: A, operation: InlineMissingOperation) A.Error!?InlineMissingObservation {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
            if (!self.present or operation.source.ptr != source.ptr or operation.source.len != source.len or
                operation.token.ptr != source[token_start..].ptr or operation.token.len != token.len or !std.mem.eql(u8, operation.file, "Sr-averz.ogg")) return null;
            return .{ .profile = self.styles, .contexts = self.contexts, .label = "noicon", .href = href, .title = "File:Sr-averz.ogg", .data_width = 175,
                .table_opening = source[0..row_start], .row_opening = source[row_start..cell_start], .cell_opening = source[cell_start..token_start] };
        }
    };
    fn noSizing(_: ?*const anyopaque, _: A, _: []const u8, _: presentation_types.FigureFormat, _: ?u32, _: ?u32) A.Error!?presentation_types.FigureSizingPolicy { return null; }
} else struct {};

test "fresh page external producer reports generated anonymous consumers across citation passes" {
    var storage = std.heap.ArenaAllocator.init(std.testing.allocator); defer storage.deinit(); const a = storage.allocator();
    const labelled = try preparePageExternalLinksAlloc(a, "ordinary [https://example.org labelled] https://example.org", .{});
    try std.testing.expectEqual(@as(?usize, 0), labelled.generated_external_labels);
    try std.testing.expectEqualStrings("ordinary [https://example.org labelled] https://example.org", labelled.source);
    const anonymous = try preparePageExternalLinksAlloc(a, "[https://example.org] <ref>[https://example.net]</ref><references/>", .{});
    try std.testing.expect(anonymous.generated_external_labels != null and anonymous.generated_external_labels.? >= 2);
    // Citation bodies retain their own numbered source in the immutable plan;
    // the ordinary page source carries the later body-link label.
    const plan = anonymous.citations orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), plan.items.items.len);
    const reference_body = plan.items.items[0].body orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("[https://example.net <nowiki>[1]</nowiki>]", reference_body.bytes);
    try std.testing.expect(std.mem.indexOf(u8, anonymous.source, "https://example.org <nowiki>[2]</nowiki>") != null);
    var renderer: Renderer = .{ .a = a, .context = .{ .citations = plan, .poem_phase = anonymous.poem_phase, .external_links_prepared = true } };
    const blocks = try renderer.renderBody(anonymous.source);
    try ExternalNumberingFixture.roundtrip(a, &renderer, blocks, &.{
        .{ .target = "https://example.net", .label = "[1]" },
        .{ .target = "https://example.org", .label = "[2]" },
    });
    const prepared = try preparePageExternalLinksAlloc(a, anonymous.source, .{ .citations = anonymous.citations });
    try std.testing.expect(prepared.generated_external_labels == null);
    try std.testing.expectEqualStrings(anonymous.source, prepared.source);
}

test "unobserved counter custody requires the independently validated complete source image" {
    var storage = std.heap.ArenaAllocator.init(std.testing.allocator); defer storage.deinit(); const a = storage.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, ".mw-parser-output{counter-reset:links}", .screen); defer styles.deinit();
    var root: table_style_profile.TextElement = .{ .tag = "div", .classes = "mw-parser-output" };
    const source = try a.dupe(u8, "body"); const snapshot = try a.dupe(u8, source);
    const source_image: table_style_profile.PageSourceImage = .{ .styles = &styles, .source = source, .snapshot = snapshot, .root = &root };
    var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "", .page_styles = &styles, .page_style_root = &root,
        .closed_row_colors = .{ .styles = &styles, .source = source, .root = &root, .attribute = "bgcolor", .owners = &.{}, .absent_source = snapshot },
        .page_source_image = &source_image,
        .unobserved_counter_resets = .{ .source_image = &source_image, .styles = &styles, .source = source, .root = &root, .source_snapshot = snapshot, .rules = styles.container_rules, .resets = &.{.{ .rule = 0, .name = "links" }} } };
