test "inline Missing ordinary parse retains selected operation through preceding quote normalization" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = InlineMissingCompilerTest;
    const T = struct {
        const prefix = "'''Audio: '''";
        const source = prefix ++ F.source;
        const Issuer = struct {
            styles: *const table_style_profile.Profile, contexts: []const table_style_profile.InlineMissingContext,
            accepted: usize = 0,
            fn observe(raw: ?*const anyopaque, _: A, operation: InlineMissingOperation) A.Error!?InlineMissingObservation {
                const self: *@This() = @ptrCast(@alignCast(@constCast(raw orelse return null)));
                if (operation.source.ptr != source.ptr or operation.source.len != source.len or
                    operation.token.ptr != source[prefix.len + F.token_start..].ptr or operation.token.len != F.token.len or
                    !std.mem.eql(u8, operation.file, "Sr-averz.ogg")) return null;
                self.accepted += 1;
                return .{ .profile = self.styles, .contexts = self.contexts, .label = "noicon", .href = F.href,
                    .title = "File:Sr-averz.ogg", .data_width = 175,
                    .table_opening = source[prefix.len..][0..F.row_start],
                    .row_opening = source[prefix.len + F.row_start..][0..F.cell_start - F.row_start],
                    .cell_opening = source[prefix.len + F.cell_start..][0..F.token_start - F.cell_start] };
            }
        };
    };
    var namespaces = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").german_test_fixture); defer namespaces.deinit();
    try FigureProducerTest.attachThumbnailDefaults(a, &namespaces, false);
    var options = try @import("namespace_registry").image_options.Registry.init(a, image_option_test_identity ++ "img_width\t1\t\"$1px\"\nimg_thumbnail\t1\t\"miniatur\"\n", "dewiktionary", "20261001", "de", @splat(0), @splat(0)); defer options.deinit();
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.parseForTargetAlloc(a, F.css, .screen); defer styles.deinit();
    styles.page_style_parent = &parent;
    const observed: table_style_profile.InlineMissingContext = .{ .styles = &styles, .nodes = &F.nodes, .root = 2, .wrapper = 7, .anchor = 8, .label = 9 };
    var issuer: T.Issuer = .{ .styles = &styles, .contexts = &.{observed, observed} };
    var root: table_style_profile.TextElement = .{ .tag = "div", .classes = "mw-parser-output", .ancestry_complete = true };
    var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output",
        .subtree_classes = "audiotable audiofile", .complete_ancestor_class_superset = "mw-parser-output audiotable audiofile",
        .page_styles = &styles, .page_style_root = &root, .page_style_complete_root = &root };
    var renderer: Renderer = .{ .a = a, .content_root = .parser_output, .body_depth = 1,
        .bounded_text_class_source = T.source, .bounded_text_class_scope = &scope,
        .body_missing = .{ .bytes = T.source },
        .context = .{ .namespace_catalog = &namespaces, .image_options = &options, .table_styles = &styles,
            .figure_sizing = .{ .resolve_fn = F.noSizing, .figure_style_ctx = &issuer,
                .resolve_inline_missing_fn = T.Issuer.observe, .text_class_scope = .{ .source = T.source, .scope = &scope },
                .source_context = .{ .namespace_sha256 = namespaces.source_sha256, .defaults = namespaces.figure_source_defaults.?, .missing_media_profile = .f45897 } } } };
    // The ordinary parser owns quote normalization and live TABLE/TR/TD frames.
    // There is no manual cell capability or whole-output copy alias here.
    const spans = try renderer.parseSpans(T.source, .{});
    // The exact operation is queried for hidden status, then visible admission.
    try std.testing.expectEqual(@as(usize, 2), issuer.accepted);
    var text: std.ArrayList(u8) = .empty; var actions: usize = 0; var label: ?Span = null; var line_breaks: usize = 0;
    for (spans) |span| {
        if (span.kind == .line_break) {
            line_breaks += 1; try std.testing.expectEqualStrings("\n", span.text);
        }
        // Build spans already carry parsed link trails in their text.
        try text.appendSlice(a, span.text);
        if (std.mem.eql(u8, span.text, "Audio: ")) try std.testing.expect(span.flags.bold);
        if (span.kind == .link or span.kind == .external_link) {
            actions += 1; label = span;
            try std.testing.expect(span.kind == .external_link and span.image == null);
            try std.testing.expectEqualStrings(F.href, span.target);
        }
    }
    // This fixture has a default TABLE, which retains both block edges.
    try std.testing.expectEqualStrings("Audio: \nnoicon\n", text.items);
    try std.testing.expectEqual(@as(usize, 2), line_breaks);
    try std.testing.expectEqual(@as(usize, 1), actions);
    const actual = label orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("noicon", actual.text);
    try std.testing.expectEqualStrings("File:Sr-averz.ogg", actual.tooltip.?);
    try std.testing.expect(!actual.flags.bold and !actual.flags.italic and actual.link_paint != null);
    try std.testing.expect(actual.inline_style != null and actual.inline_style.?.font_normalized);
    const body = [_]Block{.{ .kind = .paragraph, .spans = spans }};
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try CenteredImageTest.encoded(a, &renderer, &body);
    const stored = try codec.decodeAlloc(a, bytes, "inline missing", .language, .{ .code = "de", .heading = "Deutsch" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
    const repeated = try codec.decodeAlloc(a, try codec.encodeAlloc(a, stored), "inline missing", .language, .{ .code = "de", .heading = "Deutsch" });
    try std.testing.expectEqualDeep(stored, repeated);
}

test "inline Missing quote source mapping refuses foreign generated and contradictory intervals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const source = "'''Audio: '''" ++ InlineMissingCompilerTest.source ++ InlineMissingCompilerTest.source;
    var map: QuoteSourceMap = .{}; defer map.deinit(a);
    const quoted = try normalizeWikiQuotesPreparedMappedInDomain(a, .{ .bytes = source }, 0, false, .{}, null, &map, true);
    try std.testing.expect(quoted.bytes.ptr != source.ptr and map.generated.items.len != 0);
    const token = quoted.bytes[std.mem.indexOf(u8, quoted.bytes, InlineMissingCompilerTest.token).?..][0..InlineMissingCompilerTest.token.len];
    const expected = source[std.mem.indexOf(u8, source, InlineMissingCompilerTest.token).?..][0..InlineMissingCompilerTest.token.len];
    var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "audiotable audiofile", .complete_ancestor_class_superset = "mw-parser-output audiotable audiofile" };
    const foreign_scope = try a.create(table_style_profile.BoundedTextClassScope);
    foreign_scope.* = scope;
    try std.testing.expect(foreign_scope != &scope);
    const foreign_source = try a.dupe(u8, source);
    for (0..10) |mode| {
        var renderer: Renderer = .{ .a = a, .context = .{}, .content_root = .parser_output, .body_depth = 1,
            .bounded_text_class_source = source, .bounded_text_class_scope = &scope };
        var frame: Renderer.QuoteClassSource = .{ .map = &map, .scope = &scope, .selected = source, .parent = null };
        var copied_map = map;
        var conflict: Renderer.QuoteClassSource = .{ .map = &copied_map, .scope = &scope, .selected = source, .parent = null };
        renderer.figure_caption_quote_source = &frame;
        var selected_token: []const u8 = token;
        switch (mode) {
            0 => {},
            1 => renderer.figure_caption_quote_source = null,
            2 => frame.scope = foreign_scope,
            3 => frame.selected = foreign_source,
            4 => selected_token = try a.dupe(u8, token),
            5 => { copied_map.original = foreign_source; frame.map = &copied_map; },
            6 => { copied_map.copies = .empty; frame.map = &copied_map; },
            7 => selected_token = quoted.bytes[map.generated.items[0].output_start..][0..map.generated.items[0].token.bytes().len],
            8 => { renderer.content_root = .unknown; },
            9 => {
                copied_map.copies = .empty;
                try copied_map.copies.append(a, .{ .output_start = @intFromPtr(token.ptr) - @intFromPtr(quoted.bytes.ptr),
                    .original_start = @intFromPtr(expected.ptr) - @intFromPtr(source.ptr) + InlineMissingCompilerTest.source.len,
                    .len = token.len });
                frame.parent = &conflict;
            },
            else => unreachable,
        }
        const domain: Renderer.AuthoredElementSourceDomain = .{ .scope = &scope, .source = source };
        const result = renderer.inlineMissingOriginalSlice(domain, selected_token);
        if (mode == 0) {
            try std.testing.expect(result != null and result.?.ptr == expected.ptr and result.?.len == expected.len);
            for ([_][]const u8{ "<table class='audiotable'>", "<tr>", "<td class='audiofile'>" }) |opening| {
                const at = std.mem.indexOf(u8, quoted.bytes, opening).?;
                const original_at = std.mem.indexOf(u8, source, opening).?;
                try std.testing.expect(renderer.inlineMissingOpeningCurrent(domain, syntax.tagAt(quoted.bytes, at).?, source[original_at..][0..opening.len]));
            }
        } else try std.testing.expect(result == null);
    }
}

const ProjectedRubyLink179Test = struct {
    const source = "<span class='Jpan' lang='ja'>[[:間性#ภาษาญี่ปุ่น|<ruby>間性<rp>(</rp><rt>かんせい</rt><rp>)</rp></ruby>]]</span>";
    const inserted = "prepared-prefix ";
    renderer: Renderer,
    scope: *table_style_profile.BoundedTextClassScope,
    projection: *SourceElementProjection,
    prepared: []const u8,
    fn init(a: A, profile: *const table_style_profile.Profile) !@This() {
        const prepared = try std.mem.concat(a, u8, &.{ inserted, source });
        const root = try a.create(table_style_profile.TextElement);
        root.* = .{ .tag = "div", .classes = "mw-parser-output" };
        const scope = try a.create(table_style_profile.BoundedTextClassScope);
        scope.* = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "Jpan",
            .complete_ancestor_class_superset = "mw-parser-output Jpan", .page_styles = profile, .page_style_root = root };
        const copies = try a.alloc(SourceElementProjection.Copy, 1);
        copies[0] = .{ .original_start = 0, .prepared_start = inserted.len, .len = source.len };
        const projection = try a.create(SourceElementProjection);
        projection.* = .{ .original = .{ .bytes = source, .unknown = true }, .prepared = prepared, .copies = copies,
            .observed_source = .{ .source = source, .scope = scope } };
        const tracked: MissingText = .{ .bytes = prepared, .unknown = true };
        const binding: SourceElementBinding = .{ .scope = scope, .projection = projection, .owner = tracked, .page_start = 0 };
        var context = try FigureProducerTest.context(a);
        context.table_styles = profile; context.text_paint_styles = profile;
        context.observe_structure_only = true;
        context.figure_sizing.?.text_class_scope = .{ .source = source, .scope = scope };
        return .{ .renderer = .{ .a = a, .context = context, .content_root = .parser_output,
            .body_missing = tracked, .source_element_binding = binding, .figure_class_source_binding = binding },
            .scope = scope, .projection = projection, .prepared = prepared };
    }
};

test "projected ordinary link class absence requires exact copied token parent and live frame" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var profile = try table_style_profile.parseForTargetAlloc(a, ".center *{margin-left:auto}.Egyd *{direction:rtl}", .screen); defer profile.deinit();
    const F = ProjectedRubyLink179Test;
    for (0..17) |mode| {
        errdefer std.debug.print("PROJECTED_RUBY_LINK mode={d}\n", .{mode});
        var fixture = try F.init(a, &profile);
        const whole = fixture.prepared;
        const tag = syntax.tagAt(whole, F.inserted.len).?;
        const pair = syntax.matchingTag(whole, tag).?;
        const inner = whole[tag.end..pair.inner_end];
        // The normal parser supplies this exact quote map even when no quote
        // delimiters change. It authenticates the Ruby tag independently of A.
        const body = whole[F.inserted.len..];
        var quote_map: QuoteSourceMap = .{ .original = body, .output = body };
        defer quote_map.deinit(a);
        try quote_map.copies.append(a, .{ .original_start = 0, .output_start = 0, .len = body.len });
        const quote_domain: Renderer.QuoteClassSource = .{ .map = &quote_map, .scope = fixture.scope,
            .selected = F.source, .parent = null };
        fixture.renderer.quote_class_source = &quote_domain;
        var token = inner;
        var parent: table_style_profile.TextElement = .{ .tag = tag.name, .classes = "Jpan", .source_key = @intFromPtr(tag.name.ptr),
            .complete_ancestor_classes = fixture.scope.complete_ancestor_class_superset,
            .ancestor_class_scope = fixture.scope, .ancestor_class_source = F.source };
        var root_frame: InlineSourceDomain = .{ .source = whole, .parent = null, .tracked = fixture.renderer.body_missing };
        var tracked: MissingText = .{ .bytes = inner, .unknown = true };
        var local: InlineSourceDomain = .{ .source = inner, .parent = &root_frame, .tracked = tracked };
        fixture.renderer.inline_source_domain = &local;
        var style: Style = .{ .text_element = &parent, .language = "ja" };
        const foreign_scope = fixture.scope.*;
        switch (mode) {
            0 => {},
            1 => token = try a.dupe(u8, token),
            2 => token = token[0..token.len - 1],
            3 => fixture.renderer.figure_class_source_binding = null,
            4 => fixture.renderer.source_element_binding.?.scope = &foreign_scope,
            5 => parent.ancestor_class_source = try a.dupe(u8, F.source),
            6 => parent.source_key += 1,
            7 => parent.tag = "div",
            8 => tracked.lost_missing_range = true,
            9 => tracked.ranges = &.{.{ .start = 0, .end = @intCast(inner.len), .occurrence = 1 }},
            10 => fixture.projection.copies = &.{},
            11 => fixture.projection.observed_source = null,
            12 => root_frame.source = whole[1..],
            13 => style.provenance = .protected_literal,
            14 => parent.complete_ancestor_classes = null,
            15 => parent.alternative_ancestry = fixture.scope.page_style_root,
            16 => local.tracked = null,
            else => unreachable,
        }
        fixture.renderer.inline_missing = tracked;
        if (mode != 0) {
            try std.testing.expect(fixture.renderer.projectedLinkClassParent(style, token) == null);
            continue;
        }
        try std.testing.expect(fixture.renderer.bounded_text_class_scope == null and fixture.renderer.bounded_text_class_source == null);
        try std.testing.expect(fixture.renderer.projectedLinkClassParent(style, token) == &parent);
        const linked = try fixture.renderer.wikiLinkStyleIn(style, .{ .target = "Target" }, token);
        const anchor = linked.text_element.?;
        try std.testing.expect(anchor.parent == &parent and anchor.ancestor_class_scope == fixture.scope);
        try std.testing.expect(!anchor.ancestry_complete and !anchor.physical_ancestry_complete and anchor.element_index == null);
        const ruby_at = std.mem.indexOf(u8, whole, "<ruby>").?;
        const ruby_tag = syntax.tagAt(whole, ruby_at).?;
        try std.testing.expect(try fixture.renderer.rubyLayoutSupported(ruby_tag, linked, whole[ruby_at..]));
        for ([_][]const u8{ "mw-parser-output Jpan center", "mw-parser-output Jpan Egyd" }) |present| {
            parent.complete_ancestor_classes = present;
            const refused = try fixture.renderer.wikiLinkStyleIn(style, .{ .target = "Target" }, token);
            try std.testing.expect(!try fixture.renderer.rubyLayoutSupported(ruby_tag, refused, whole[ruby_at..]));
        }
    }
}

test "ordinary explicit label retains only its exact issued anchor action and lifetime" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var profile = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer profile.deinit();
    for (0..9) |mode| {
        var fixture = try ProjectedRubyLink179Test.init(a, &profile);
        const target = try a.dupe(u8, "Target");
        const label = try a.dupe(u8, "label");
        var anchor: table_style_profile.TextElement = .{ .tag = "a", .complete_ancestor_classes = "mw-parser-output Jpan",
            .ancestor_class_scope = fixture.scope, .ancestor_class_source = ProjectedRubyLink179Test.source };
        const foreign_anchor = anchor;
        var style: Style = .{ .kind = .link, .target = target, .text_element = &anchor };
        fixture.renderer.explicit_wiki_label = .{ .kind = .link, .target = target, .ordinary_anchor = &anchor,
            .ordinary_label = label, .ordinary_depth = 2 };
        var current_label: []const u8 = label;
        var current_target: []const u8 = target;
