    try std.testing.expect(std.mem.indexOfPos(u8, source, at + operation.len, operation) == null);
    // Keep every other byte, including the absent CENTER close and the outer
    // conversion boundary. This is a full captured-body control, not an owner
    // selection or ordinary Writer qualification.
    const reference = try std.mem.concat(a, u8, &.{ source[0..at], flat, source[at + operation.len..] });
    const NS = @import("namespace_registry");
