        try std.testing.expectEqual(unknown, actual_renderer.body_missing.?.unknown);
        try std.testing.expect(actual_renderer.body_missing.?.ranges.len == 0 and !actual_renderer.body_missing.?.lost_missing_range and actual_renderer.body_missing.?.generated_source == null);
        try std.testing.expect(actual_renderer.inline_source_domain == null);
        const spans = try FigureProducerTest.bodySpans(a, blocks);
        var found: usize = 0; var neighbors: usize = 0; var citation: usize = 0;
        for (spans) |span| {
