            if (span.kind == .external_link and std.mem.eql(u8, span.target, "https://e-dictionary.ilrdf.org.tw/singleSearch?tribeId=e68273b9-1f2b-4c42-8d95-f52189ab24b7&keyword=41967.htm")) {
