test "recursive consumed center position requires live exact source interval and ordinary parser consumption" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = SourceRecursiveManualTest.profile();
    const child = "-{[[:noipisa#達悟語|-{noipisa}-]]}-";
    const prefix = "<center><span class=\"Latn\" lang=\"tao\">";
    const source = prefix ++ child ++ "</span> 以後有機會時";
    for ([_]bool{ false, true }) |unknown| {
        var consumed: std.ArrayList(usize) = .empty; defer consumed.deinit(a);
        const tracked: MissingText = .{ .bytes = source, .unknown = unknown };
        const domain: InlineSourceDomain = .{ .source = source, .parent = null, .tracked = tracked, .consumed_unclosed_centers = &consumed };
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns }, .inline_missing = tracked, .inline_source_domain = &domain };
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(source, prefix.len, .{})) == null);
        var opaque_scan: syntax.OpaqueScan = .{};
        const end = (try renderer.htmlTagWithMissing(tracked, 0, .{}, 0, null, &opaque_scan, null)) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(usize, 8), end);
        try std.testing.expectEqualSlices(usize, &.{0}, consumed.items);
        try std.testing.expect(renderer.fallbacks.unclosed_formatting);
        try std.testing.expect(!Renderer.formattingAngleBodyPositionWithTrackedSiblings(source, prefix.len, true, tracked));
        const result = (try renderer.sourceRecursiveRuleFreeLinkLabels(source, prefix.len, .{})) orelse return error.TestUnexpectedResult;
        try std.testing.expect(result.body.ptr == source.ptr + prefix.len + 2 and result.body.len == child.len - 4 and result.end == prefix.len + child.len);
        const borrowed = try missingSlice(a, tracked, result.body);
        try std.testing.expectEqual(unknown, borrowed.unknown);
        for (0..16) |mode| {
            errdefer std.debug.print("consumed-center refusal={d}\n", .{mode});
            var parent = tracked;
            var changed_domain = domain;
            var refused = renderer;
            var style: Style = .{};
            var empty: std.ArrayList(usize) = .empty;
            switch (mode) {
                0 => changed_domain.consumed_unclosed_centers = null,
                1 => changed_domain.consumed_unclosed_centers = &empty,
                2 => changed_domain.source = try a.dupe(u8, source),
                3 => { var foreign = tracked; foreign.bytes = try a.dupe(u8, source); changed_domain.tracked = foreign; },
                4 => changed_domain.source = source[0..prefix.len],
                5 => parent.lost_missing_range = true,
                6 => parent.generated_source = source,
                7 => parent.ranges = &.{.{ .start = 0, .end = 8, .occurrence = 1 }},
                8 => parent.literal_curly_ranges = &.{.{ .start = 0, .end = 8 }},
                9 => { var lost = tracked; lost.lost_missing_range = true; changed_domain.tracked = lost; },
                10 => { var generated = tracked; generated.generated_source = source; changed_domain.tracked = generated; },
                11 => changed_domain.tracked = null,
                12 => style = .{ .kind = .link, .target = "Outer" },
                13 => refused.in_reference = true,
                14 => style.code = true,
                15 => ns.manual_conversion_context.?.source_core = "foreign",
                else => unreachable,
            }
            defer ns.manual_conversion_context = SourceRecursiveManualTest.profile();
            refused.inline_missing = parent; refused.inline_source_domain = &changed_domain;
            try std.testing.expect((try refused.sourceRecursiveRuleFreeLinkLabels(source, prefix.len, style)) == null);
        }
        renderer.inline_source_domain = null;
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(source, prefix.len, .{})) == null);
    }
    for ([_][]const u8{ "<center class='x'>", "<center style='display:none'>", "<center class='x'/>", "</center>", "<div>", "<nowiki>", "<pre>", "[[Outer|<center>" }) |before| {
        const value = try std.mem.concat(a, u8, &.{ before, child });
        const tracked: MissingText = .{ .bytes = value, .unknown = true };
        var consumed: std.ArrayList(usize) = .empty; defer consumed.deinit(a);
        const domain: InlineSourceDomain = .{ .source = value, .parent = null, .tracked = tracked, .consumed_unclosed_centers = &consumed };
        var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns }, .inline_missing = tracked, .inline_source_domain = &domain };
        if (value[0] == '<') {
            var opaque_scan: syntax.OpaqueScan = .{};
            _ = renderer.htmlTagWithMissing(tracked, 0, .{}, 0, null, &opaque_scan, null) catch null;
        }
        try std.testing.expect(consumed.items.len == 0);
        try std.testing.expect((try renderer.sourceRecursiveRuleFreeLinkLabels(value, before.len, .{})) == null);
    }
}

const BulletRuby182Test = struct {
    // Exact complete physical line from TH p108817/r2190988, first Ruby at
    // source byte41964. The full-page oracle remains independently selected.
    const line = "* <span class=\"Jpan\" lang=\"ja\">[[:間性#ภาษาญี่ปุ่น|<ruby>間性<rp>(</rp><rt>かんせい</rt><rp>)</rp></ruby>]]</span> <span class=\"mention-gloss-paren annotation-paren\">(</span><span class=\"tr\"><span class=\"mention-tr tr\">kansei</span></span><span class=\"mention-gloss-paren annotation-paren\">)</span>: [[intersex]]";
    const inserted = "prepared source prefix\n";
    const classes = "mw-parser-output Jpan mention-gloss-paren annotation-paren tr mention-tr";
    fn init(a: A, profile: *const table_style_profile.Profile, source: []const u8) !Renderer {
        const prepared = try std.mem.concat(a, u8, &.{ inserted, source });
        const root = try a.create(table_style_profile.TextElement); root.* = .{ .tag = "div", .classes = "mw-parser-output" };
        const scope = try a.create(table_style_profile.BoundedTextClassScope);
        scope.* = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = classes,
            .complete_ancestor_class_superset = classes, .page_styles = profile, .page_style_root = root };
        const copies = try a.alloc(SourceElementProjection.Copy, 1);
        copies[0] = .{ .original_start = 0, .prepared_start = inserted.len, .len = source.len };
        const projection = try a.create(SourceElementProjection);
        projection.* = .{ .original = .{ .bytes = source, .unknown = true }, .prepared = prepared, .copies = copies,
            .observed_source = .{ .source = source, .scope = scope } };
        const tracked: MissingText = .{ .bytes = prepared, .unknown = true };
        const binding: SourceElementBinding = .{ .scope = scope, .projection = projection, .owner = tracked, .page_start = 0 };
        var context = try FigureProducerTest.context(a);
        context.table_styles = profile; context.text_paint_styles = profile; context.observe_structure_only = true;
        context.figure_sizing.?.text_class_scope = .{ .source = source, .scope = scope };
        return .{ .a = a, .context = context, .content_root = .parser_output, .body_missing = tracked,
            .source_element_binding = binding, .figure_class_source_binding = binding };
    }
    fn body(renderer: *const Renderer) MissingText {
        return .{ .bytes = renderer.source_element_binding.?.owner.bytes[inserted.len..], .unknown = true };
    }
};

test "retained TH authored bullet preserves complete Ruby gloss actions list body and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = BulletRuby182Test;
    var actual_profile = try table_style_profile.parseForTargetAlloc(a, ".center *{margin-left:auto}.Egyd *{direction:rtl}button::-moz-focus-inner,[type='button']::-moz-focus-inner,[type='reset']::-moz-focus-inner,[type='submit']::-moz-focus-inner{border-style:none;padding:0}.mw-body blockquote > :first-child{margin-top:0}.mw-heading *{word-break:normal}", .screen); defer actual_profile.deinit();
    var expected_profile = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer expected_profile.deinit();
    var actual = try F.init(a, &actual_profile, F.line);
    var expected = try F.init(a, &expected_profile, F.line);
    for ([_]*Renderer{ &actual, &expected }) |renderer| {
        const scope = @constCast(renderer.source_element_binding.?.scope);
        const outer = try a.create(table_style_profile.TextElement); outer.* = .{ .tag = "body", .classes = "mw-body" };
        @constCast(scope.page_style_root.?).parent = outer;
        scope.complete_ancestor_class_superset = "mw-body " ++ F.classes;
        try BulletRuby187Test.install(a, renderer, F.line);
    }
    const actual_blocks = try actual.renderBodyWithMissing(F.body(&actual));
    const expected_blocks = try expected.renderBodyWithMissing(F.body(&expected));
    try std.testing.expectEqualDeep(expected_blocks, actual_blocks);
    try std.testing.expect(!actual.fallbacks.any() and !expected.fallbacks.any());
    try std.testing.expectEqual(@as(usize, 1), actual_blocks.len);
    try std.testing.expectEqual(Kind.list_item, actual_blocks[0].kind);
    try std.testing.expectEqualStrings("*", actual_blocks[0].list_path);
    try std.testing.expectEqual(@as(u8, 1), actual_blocks[0].depth);
    try std.testing.expectEqualStrings("間性(かんせい) (kansei): intersex", try flattened(a, actual_blocks[0].spans));
    const ruby = actual_blocks[0].spans[0].ruby orelse return error.TestUnexpectedResult;
    const segment = ruby.segments[0];
    try std.testing.expectEqualStrings("間性", segment.bases[0].spans[0].text);
    try std.testing.expectEqualStrings("かんせい", segment.annotations[0].spans[0].text);
    try std.testing.expect(segment.annotations[0].explicit_fallback);
    const leaves = try RubyProducerTest.leaves(a, actual_blocks[0].spans);
    var ruby_actions: usize = 0; var intersex_actions: usize = 0;
    for (leaves) |leaf| if (leaf.kind == .link) {
        if (std.mem.eql(u8, leaf.target, "間性#ภาษาญี่ปุ่น")) {
            ruby_actions += 1;
            try std.testing.expectEqualStrings("ja", leaf.language);
        } else {
            try std.testing.expectEqualStrings("intersex", leaf.target);
            intersex_actions += 1;
        }
    };
    try std.testing.expectEqual(@as(usize, 4), ruby_actions);
    try std.testing.expectEqual(@as(usize, 1), intersex_actions);
    try std.testing.expect(actual.ordinary_bullet_link == null and !actual.figure_implicit_list_context);
    try std.testing.expect(actual.bounded_text_class_scope == null and actual.bounded_text_class_source == null);
    const stored = try FormattingScopeTest.encode(a, &actual, actual_blocks);
    const reference = try FormattingScopeTest.encode(a, &expected, expected_blocks);
    try std.testing.expectEqualDeep(reference, stored);
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeAlloc(a, stored);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, reference), bytes);
    try std.testing.expectEqualDeep(stored, try codec.decodeAlloc(a, bytes, stored.entry.title, .language,
        .{ .heading = stored.entry.language.?, .code = stored.entry.language_code }));
}

test "ordinary bullet class custody refuses flag alone foreign operations protected and changed lists" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = BulletRuby182Test;
    var profile = try table_style_profile.parseForTargetAlloc(a, ".center *{margin-left:auto}", .screen); defer profile.deinit();
    for (0..12) |mode| {
        var renderer = try F.init(a, &profile, F.line);
        const body = F.body(&renderer);
        renderer.body_missing = body;
        renderer.figure_implicit_list_context = true;
        const token_at = std.mem.indexOf(u8, body.bytes, "[[:").?;
        var token = body.bytes[token_at..std.mem.indexOf(u8, body.bytes, "]]").? + 2];
        var operation: Renderer.OrdinaryBulletLink = .{ .source = body.bytes, .line = body.bytes,
            .body = Renderer.wikiListLineBody(body.bytes[1..]) };
        renderer.ordinary_bullet_link = &operation;
        switch (mode) {
            0 => {},
            1 => renderer.ordinary_bullet_link = null,
            2 => operation.source = try a.dupe(u8, operation.source),
            3 => operation.line = try a.dupe(u8, operation.line),
            4 => operation.body = operation.body[1..],
            5 => token = try a.dupe(u8, token),
            6 => renderer.html_list_item_flow = true,
            7 => renderer.html_blockquote_flow = true,
            8 => renderer.in_template_literal_scope = true,
            9 => renderer.body_missing.?.lost_missing_range = true,
            10 => renderer.body_missing.?.ranges = &.{.{ .start = 0, .end = @intCast(body.bytes.len), .occurrence = 1 }},
            11 => renderer.figure_implicit_list_context = false,
            else => unreachable,
        }
        try std.testing.expectEqual(mode == 11, renderer.wikiClassOrdinaryState());
        try std.testing.expectEqual(mode == 0, renderer.ordinaryBulletLinkState(token));
    }
    // These contexts retain the original refusal until their own operation
    // provenance is supported; a list boolean alone never certifies classes.
    for ([_][]const u8{ "# ", "** ", ": " }) |prefix| {
        const source = try std.mem.concat(a, u8, &.{ prefix, F.line[2..] });
        var refused = try F.init(a, &profile, source);
        try std.testing.expectError(error.UncompiledPresentation, refused.renderBodyWithMissing(F.body(&refused)));
    }
    var present = try F.init(a, &profile, F.line);
    @constCast(present.context.figure_sizing.?.text_class_scope.?.scope).complete_ancestor_class_superset = F.classes ++ " center";
    try std.testing.expectError(error.UncompiledPresentation, present.renderBodyWithMissing(F.body(&present)));
}

