            if (std.mem.eql(u8, span.target, "係#漢語")) { second += 1; try std.testing.expectEqualStrings("係", span.text); }
            if (std.mem.eql(u8, span.target, "only") or std.mem.eql(u8, span.target, "no more") or
                std.mem.eql(u8, span.target, "just") or std.mem.eql(u8, span.target, "merely")) translations += 1;
        };
        try std.testing.expectEqual(@as(usize, 1), first); try std.testing.expectEqual(@as(usize, 1), second);
        try std.testing.expectEqual(@as(usize, 4), translations);
        const visible = try FormattingScopeTest.text(a, spans);
        try std.testing.expect(std.mem.indexOf(u8, visible, "淨係") != null);
