        const decoded = try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .heading = "English", .code = "en" });
        try std.testing.expectEqualDeep(actual, decoded);
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));
    }
}

test "cross cell BR prefix retains exact source protected topology and malformed refusals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = SourceRecursiveManualTest.profile();
    var renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .content_conversion = true } };
    const tail = "-{<span style='font-size:140%'>(head)</span>\n| [[Target|-{label}-]]}-\n|}";
    const source = "{|\n|-\n! [[Before]]<br>" ++ tail;
    const tracked: MissingText = .{ .bytes = source, .unknown = true };
    const plan = (try renderer.tableManualMarkers(tracked, 0, CrossCellManual153Test.opening(source), .{})) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 2), plan.offsets.len);
    const br_start = std.mem.indexOf(u8, source, "<br>").?;
    const body_start = std.mem.indexOf(u8, source, "[[Before]]").?;
    const body = source[body_start..];
    const marker = std.mem.indexOf(u8, body, "-{").?;
    try std.testing.expect(!Renderer.formattingAngleBodyPosition(body, marker));
    try std.testing.expect(!renderer.manualConversionLinkedScope(body[0..marker], true));
    try std.testing.expect(renderer.tableManualPrefix(tracked, body, marker) != null);
    try std.testing.expect(renderer.tableManualPrefix(tracked, try a.dupe(u8, body), marker) == null);
    for (0..7) |mode| {
        var changed = tracked;
        ns.manual_conversion_context = SourceRecursiveManualTest.profile(); renderer.context.content_conversion = true;
        switch (mode) {
            0 => changed.lost_missing_range = true,
            1 => changed.generated_source = source,
            2 => changed.ranges = &.{.{ .start = @intCast(br_start), .end = @intCast(br_start + 4), .occurrence = 1 }},
            3 => changed.literal_curly_ranges = &.{.{ .start = @intCast(br_start), .end = @intCast(br_start + 4) }},
            4 => ns.manual_conversion_context.?.source_core = "unproved",
            5 => renderer.context.content_conversion = false,
            6 => ns.manual_conversion_context = null,
            else => unreachable,
        }
        try std.testing.expect((try renderer.tableManualMarkers(changed, 0, CrossCellManual153Test.opening(source), .{})) == null);
    }
    ns.manual_conversion_context = SourceRecursiveManualTest.profile(); renderer.context.content_conversion = true;
    for ([_][]const u8{
        "[[Before]]</br>", "[[Before]]<br class='x'>", "[[Before]]<br style='display:none'>",
        "[[Before]]<br title='-{' >", "[[Before]]<br\n>", "[[Before]]<wbr>",
        "<span>[[Before]]<br></span>", "[[Before|label<br>]]", "<nowiki>[[Before]]<br></nowiki>",
        "[[Before]]<br><span>", "[[Before]]<br>{{open", "[[Before]]<br>[[open",
    }) |prefix| {
        const value = try std.mem.concat(a, u8, &.{ "{|\n|-\n! ", prefix, tail });
        const bad: MissingText = .{ .bytes = value, .unknown = true };
        try std.testing.expect((try renderer.tableManualMarkers(bad, 0, CrossCellManual153Test.opening(value), .{})) == null);
    }
    // The new prefix cannot repair the actual absence of the closing delimiter,
    // cross a row, or consume a conversion-owned BR as if it were a prefix.
    for ([_][]const u8{
        "{|\n|-\n! [[Before]]<br>-{<span style='font-size:140%'>head</span>\n| [[Target|-{label}-]]\n|}",
        "{|\n|-\n! [[Before]]<br>-{<span style='font-size:140%'>head</span>\n|-\n| [[Target|-{label}-]]}-\n|}",
        "{|\n|-\n! [[Before]]<br>-{<span style='font-size:140%'>head<br></span>\n| [[Target|-{label}-]]}-\n|}",
    }) |value| {
        try std.testing.expect((try renderer.tableManualMarkers(.{ .bytes = value, .unknown = true }, 0, CrossCellManual153Test.opening(value), .{})) == null);
    }
    // Revoking the newly proved prefix interval also revokes marker deletion.
    renderer.table_manual_markers = plan;
    var protected = tracked;
    protected.literal_curly_ranges = &.{.{ .start = @intCast(br_start), .end = @intCast(br_start + 4) }};
    // Literal provenance may cover brace bytes only. Preserve the exact invalid
    // metadata as an error, then revoke the prefix with a valid Missing range.
    var invalid: MissingBuffer = .empty; defer invalid.deinit(a);
    var invalid_copies: std.ArrayList(HeadingSourceCopy) = .empty; defer invalid_copies.deinit(a);
    try std.testing.expectError(error.InvalidLiteralProvenance,
        renderer.appendWikiTableFosteredCopy(&invalid, &invalid_copies, protected, source));
    protected.literal_curly_ranges = &.{};
    protected.ranges = &.{.{ .start = @intCast(br_start), .end = @intCast(br_start + 4), .occurrence = 1 }};
    var retained: MissingBuffer = .empty; defer retained.deinit(a);
    var retained_copies: std.ArrayList(HeadingSourceCopy) = .empty; defer retained_copies.deinit(a);
    try renderer.appendWikiTableFosteredCopy(&retained, &retained_copies, protected, source);
    try std.testing.expectEqualStrings(source, retained.items);
    // Whole-source identity remains mandatory at delimiter replay.
    const foreign = try a.dupe(u8, source);
    renderer.table_manual_markers = plan;
    var output: MissingBuffer = .empty; defer output.deinit(a);
    var copies: std.ArrayList(HeadingSourceCopy) = .empty; defer copies.deinit(a);
    try renderer.appendWikiTableFosteredCopy(&output, &copies, .{ .bytes = foreign, .unknown = true }, foreign);
    try std.testing.expectEqualStrings(source, output.items);
}

