            .complete_ancestor_id_superset = ids, .page_styles = &selected, .page_style_root = &root };
        var context = try FigureProducerTest.context(a); context.table_styles = &selected;
        context.figure_sizing.?.text_class_scope = .{ .source = source, .scope = &scope };
        const tracked: MissingText = .{ .bytes = source };
        var renderer: Renderer = .{ .a = a, .context = context, .content_root = .parser_output, .body_missing = tracked,
            .bounded_text_class_scope = &scope, .bounded_text_class_source = source };
        try renderer.checkPageAncestorEffects(tracked);
        try std.testing.expect(!renderer.fallbacks.unresolved_table_style);
        const snapshot = renderer.checked_page_style_complete_ids orelse return error.TestUnexpectedResult;
        try std.testing.expect(snapshot.ptr != ids.ptr);
        try std.testing.expectEqualStrings("retained", snapshot);
        try renderer.checkPageAncestorEffects(tracked);
        try std.testing.expect(!renderer.fallbacks.unresolved_table_style and renderer.checked_page_style_complete_ids.?.ptr == snapshot.ptr);
        switch (change) {
            0 => scope.complete_ancestor_id_superset = null,
            1 => scope.complete_ancestor_id_superset = "required",
            2 => @memcpy(ids, "required"),
            else => unreachable,
        }
        try renderer.checkPageAncestorEffects(tracked);
        try std.testing.expect(renderer.fallbacks.unresolved_table_style and renderer.page_ancestor_effect != null);
        try std.testing.expectEqualStrings("retained", snapshot);
    }
}

test "projected quote fragment preserves ordinary audio parent font body action and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = InlineMissingCompilerTest;
    const T = struct {
        const prefix = "selected-page-prefix\n";
        const fragment = "'''Audio: '''" ++ F.source;
        const source = prefix ++ fragment ++ "\nselected-page-tail";
        const token_start = prefix.len + "'''Audio: '''".len + F.token_start;
        const Issuer = struct {
            styles: *const table_style_profile.Profile, contexts: []const table_style_profile.InlineMissingContext,
            accepted: usize = 0,
            fn observe(raw: ?*const anyopaque, _: A, operation: InlineMissingOperation) A.Error!?InlineMissingObservation {
                const self: *@This() = @ptrCast(@alignCast(@constCast(raw orelse return null)));
                if (operation.source.ptr != source.ptr or operation.source.len != source.len or
                    operation.token.ptr != source[token_start..].ptr or operation.token.len != F.token.len or
                    !std.mem.eql(u8, operation.file, "Sr-averz.ogg")) return null;
                self.accepted += 1;
                const table_start = prefix.len + "'''Audio: '''".len;
                return .{ .profile = self.styles, .contexts = self.contexts, .label = "noicon", .href = F.href,
                    .title = "File:Sr-averz.ogg", .data_width = 175,
                    .table_opening = source[table_start..][0..F.row_start],
                    .row_opening = source[table_start + F.row_start..][0..F.cell_start - F.row_start],
                    .cell_opening = source[table_start + F.cell_start..][0..F.token_start - F.cell_start] };
            }
        };
    };
    var namespaces = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").german_test_fixture); defer namespaces.deinit();
    try FigureProducerTest.attachThumbnailDefaults(a, &namespaces, false);
    var options = try @import("namespace_registry").image_options.Registry.init(a, image_option_test_identity ++ "img_width\t1\t\"$1px\"\nimg_thumbnail\t1\t\"miniatur\"\n", "dewiktionary", "20261001", "de", @splat(0), @splat(0)); defer options.deinit();
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.parseForTargetAlloc(a, F.css, .screen); defer styles.deinit();
    styles.page_style_parent = &parent;
    const observed: table_style_profile.InlineMissingContext = .{ .styles = &styles, .nodes = &F.nodes, .root = 2, .wrapper = 7, .anchor = 8, .label = 9 };
    var issuer: T.Issuer = .{ .styles = &styles, .contexts = &.{observed, observed} };
    var root: table_style_profile.TextElement = .{ .tag = "div", .classes = "mw-parser-output", .ancestry_complete = true };
    var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output",
        .subtree_classes = "audiotable audiofile", .complete_ancestor_class_superset = "mw-parser-output audiotable audiofile",
        .page_styles = &styles, .page_style_root = &root, .page_style_complete_root = &root };
    const context: Context = .{ .namespace_catalog = &namespaces, .image_options = &options, .table_styles = &styles,
        .figure_sizing = .{ .resolve_fn = F.noSizing, .figure_style_ctx = &issuer,
            .resolve_inline_missing_fn = T.Issuer.observe, .text_class_scope = .{ .source = T.source, .scope = &scope },
            .source_context = .{ .namespace_sha256 = namespaces.source_sha256, .defaults = namespaces.figure_source_defaults.?, .missing_media_profile = .f45897 } } };
    const codec = @import("blob_encoder").presentation_codec;
    var reference: ?presentation_types.Stored = null;
    var report: ?@import("presentation_fallback.zig").Report = null;
    for (0..3) |mode| {
        issuer.accepted = 0;
        const prepared = if (mode == 0) T.source else try a.dupe(u8, T.source);
        const owner = prepared[T.prefix.len..][0..T.fragment.len];
        var projection: SourceElementProjection = .{ .original = .{ .bytes = T.source, .unknown = mode == 2 },
            .prepared = prepared, .copies = &.{.{ .original_start = 0, .prepared_start = 0, .len = T.source.len }},
            .observed_source = .{ .source = T.source, .scope = &scope } };
        const tracked: MissingText = .{ .bytes = owner, .unknown = mode == 2 };
        const binding: SourceElementBinding = .{ .scope = &scope, .projection = &projection, .owner = tracked, .page_start = T.prefix.len };
        var renderer: Renderer = .{ .a = a, .context = context, .content_root = .parser_output, .body_depth = 1,
            .bounded_text_class_source = if (mode == 0) T.source else owner, .bounded_text_class_scope = &scope,
            .body_missing = tracked, .source_element_binding = if (mode == 0) null else binding,
            .figure_class_source_binding = if (mode == 0) null else binding };
        if (mode != 0) try std.testing.expect(owner.ptr != T.source[T.prefix.len..].ptr);
        // Same fragment scope installed by Document; the parser owns every
        // quote and TABLE/TR/TD frame, with no manual native parent or font.
        const spans = try renderer.parseSpansWithMissing(tracked, .{});
        // The exact operation is queried for hidden status, then visible admission.
        try std.testing.expectEqual(@as(usize, 2), issuer.accepted);
        try std.testing.expectEqual(mode == 2, renderer.body_missing.?.unknown);
        var text: std.ArrayList(u8) = .empty; var actions: usize = 0; var label: ?Span = null; var line_breaks: usize = 0;
        for (spans) |span| {
            if (span.kind == .line_break) {
                line_breaks += 1; try std.testing.expectEqualStrings("\n", span.text);
            }
            try text.appendSlice(a, span.text);
            if (std.mem.eql(u8, span.text, "Audio: ")) try std.testing.expect(span.flags.bold);
            if (span.kind == .link or span.kind == .external_link) {
                actions += 1; label = span;
                try std.testing.expect(span.kind == .external_link and span.image == null);
                try std.testing.expectEqualStrings(F.href, span.target);
            }
        }
        // This fixture has a default TABLE, which retains both block edges.
        try std.testing.expectEqualStrings("Audio: \nnoicon\n", text.items);
        try std.testing.expectEqual(@as(usize, 2), line_breaks);
        try std.testing.expectEqual(@as(usize, 1), actions);
        const actual = label orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("noicon", actual.text);
        try std.testing.expectEqualStrings("File:Sr-averz.ogg", actual.tooltip.?);
        try std.testing.expect(!actual.flags.bold and !actual.flags.italic and actual.link_paint != null);
        try std.testing.expect(actual.inline_style != null and actual.inline_style.?.font_normalized);
        const blocks = [_]Block{.{ .kind = .paragraph, .spans = spans }};
        const bytes = try CenteredImageTest.encoded(a, &renderer, &blocks);
        const stored = try codec.decodeAlloc(a, bytes, "inline missing", .language, .{ .code = "de", .heading = "Deutsch" });
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
        try std.testing.expectEqualDeep(stored, try codec.decodeAlloc(a, try codec.encodeAlloc(a, stored), "inline missing", .language, .{ .code = "de", .heading = "Deutsch" }));
        if (reference) |expected| try std.testing.expectEqualDeep(expected, stored) else reference = stored;
        if (report) |expected| try std.testing.expectEqualDeep(expected, renderer.fallbacks) else report = renderer.fallbacks;
    }
}

test "projected quote parent roots require both exact source bindings and locally ordinary intervals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const prefix = "page-prefix\n";
    const fragment = "'''A'''<table style='font-size:88%'><tr><td>x</td></tr></table>";
    const source = prefix ++ fragment ++ "\npage-tail";
    const prepared = try a.dupe(u8, source);
    const owner = prepared[prefix.len..][0..fragment.len];
    var parent_styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent_styles.deinit();
    var styles = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer styles.deinit();
    styles.page_style_parent = &parent_styles;
    var root: table_style_profile.TextElement = .{ .tag = "div", .classes = "mw-parser-output" };
    var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "",
        .complete_ancestor_class_superset = "mw-parser-output", .page_styles = &styles, .page_style_root = &root };
    const foreign_scope = try a.create(table_style_profile.BoundedTextClassScope); foreign_scope.* = scope;
    var projection: SourceElementProjection = .{ .original = .{ .bytes = source, .unknown = true }, .prepared = prepared,
        .copies = &.{.{ .original_start = 0, .prepared_start = 0, .len = source.len }},
        .observed_source = .{ .source = source, .scope = &scope } };
    const tracked: MissingText = .{ .bytes = owner, .unknown = true };
    const binding: SourceElementBinding = .{ .scope = &scope, .projection = &projection, .owner = tracked, .page_start = prefix.len };
    var renderer: Renderer = .{ .a = a, .content_root = .parser_output, .body_depth = 1,
        .context = .{ .table_styles = &styles, .figure_sizing = .{ .resolve_fn = InlineMissingCompilerTest.noSizing,
            .text_class_scope = .{ .source = source, .scope = &scope } } },
        .bounded_text_class_scope = &scope, .bounded_text_class_source = owner,
        .body_missing = tracked, .source_element_binding = binding, .figure_class_source_binding = binding };
    var map: QuoteSourceMap = .{}; defer map.deinit(a);
    const quoted = try normalizeWikiQuotesPreparedMappedInDomain(a, tracked, 0, false, renderer.context, null, &map, true);
    try std.testing.expect(quoted.unknown and quoted.bytes.ptr != owner.ptr);
    try std.testing.expect(renderer.quoteClassOutputOwned(&map, quoted, &scope));
    const original = renderer.quoteClassPageOriginal(&scope, owner) orelse return error.TestUnexpectedResult;
    try std.testing.expect(original.ptr == source[prefix.len..].ptr and original.len == owner.len);
    var domain: Renderer.QuoteClassSource = .{ .map = &map, .scope = &scope, .selected = owner, .parent = null,
        .selected_original = .{ .copied = owner, .selected = owner } };
    renderer.quote_class_source = &domain;
    renderer.inline_missing = quoted;
    var node: ?*const table_style_profile.TextElement = null;
    for ([_][]const u8{ "<table", "<tr>", "<td>" }) |opening| {
        const at = std.mem.indexOf(u8, quoted.bytes, opening).?;
        const tag = syntax.tagAt(quoted.bytes, at).?;
        const prior = node;
        node = try renderer.textElement(tag, prior, "");
        try std.testing.expect(node.?.page_style_root == &root and renderer.currentAncestorScope(node.?));
        try std.testing.expect(node.?.parent == prior and !node.?.physical_ancestry_complete and node.?.source_root_child == null);
        const anchor = node.?.page_style_anchor orelse return error.TestUnexpectedResult;
        try std.testing.expect(Renderer.wikiClassContains(owner, anchor));
        try std.testing.expect(binding.originalRange(anchor) != null);
    }
    const table_at = std.mem.indexOf(u8, quoted.bytes, "<table").?;
    const table = syntax.tagAt(quoted.bytes, table_at).?;
    const font = (try renderer.htmlComputedFontSize(table, .{})) orelse return error.TestUnexpectedResult;
    try std.testing.expect(!font.unknown and font.normal_body);
    try std.testing.expectApproxEqAbs(@as(f32, 0.88), font.value.?, 0.00001);
    for (0..12) |mode| {
        var refused = renderer;
        var changed_projection = projection;
        var other_projection = projection;
        refused.source_element_binding.?.projection = &changed_projection;
        refused.figure_class_source_binding.?.projection = &changed_projection;
        switch (mode) {
            0 => refused.source_element_binding = null,
            1 => refused.source_element_binding.?.projection = &other_projection,
            2 => refused.source_element_binding.?.owner.bytes = try a.dupe(u8, owner),
            3 => refused.source_element_binding.?.page_start += 1,
            4 => refused.source_element_binding.?.owner.lost_missing_range = true,
            5 => refused.figure_class_source_binding.?.owner.lost_missing_range = true,
            6 => changed_projection.original.generated_source = source,
            7 => changed_projection.original.ranges = &.{.{ .start = @intCast(prefix.len), .end = @intCast(prefix.len + fragment.len), .occurrence = 1 }},
            8 => refused.source_element_binding.?.owner.literal_curly_ranges = &.{.{ .start = 0, .end = @intCast(owner.len) }},
            9 => refused.figure_class_source_binding.?.scope = foreign_scope,
            10 => changed_projection.observed_source = null,
            11 => changed_projection.copies = &.{},
            else => unreachable,
        }
        try std.testing.expect(!refused.quoteClassOutputOwned(&map, quoted, &scope));
        const known = renderer.quoteClassTag(table) orelse return error.TestUnexpectedResult;
        try std.testing.expect(refused.pageStyleQuoteAnchor(known) == null);
        // No fallback scalar is supplied when the parent ownership is absent.
        refused.quote_class_source = null;
        const unresolved = (try refused.htmlComputedFontSize(table, .{})) orelse return error.TestUnexpectedResult;
        try std.testing.expect(unresolved.unknown);
    }
    try std.testing.expect(renderer.quoteClassPageOriginal(&scope, try a.dupe(u8, owner)) == null);
}

test "paired CENTER slash normalization preserves consumed position body language action and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry");
