    const tail = "<span class=\"Latn\" lang=\"tao\">-{[[:noipisa#達悟語|-{noipisa}-]]}-</span> 以後有機會時";
    const canonical = "<center>" ++ tail;
    const slash = "<center/>" ++ tail;
    const slash_tag = syntax.tagAt(slash, 0) orelse return error.TestUnexpectedResult;
    // Paired HTML tags ignore the lexical slash in the maintained tokenizer.
    try std.testing.expect(slash_tag.is("center") and !slash_tag.self_closing and slash_tag.attrs.len == 0);
    for ([_]bool{ false, true }) |unknown| {
        const source: MissingText = .{ .bytes = slash, .unknown = unknown };
        const reference: MissingText = .{ .bytes = canonical, .unknown = unknown };
        const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior };
        var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = source };
        var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = reference };
        const blocks = try actual_renderer.renderBodyWithMissing(source);
        const expected_blocks = try expected_renderer.renderBodyWithMissing(reference);
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, expected_blocks);
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
        try std.testing.expect(actual_renderer.fallbacks.unclosed_formatting);
        try std.testing.expectEqual(unknown, actual_renderer.body_missing.?.unknown);
        try std.testing.expect(actual_renderer.inline_source_domain == null);
        const spans = try FigureProducerTest.bodySpans(a, blocks);
        var actions: usize = 0;
        for (spans) |span| {
            try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
            if (span.kind == .link or span.kind == .external_link) {
                actions += 1; try std.testing.expect(span.kind == .link);
                try std.testing.expectEqualStrings("noipisa#達悟語", span.target);
                try std.testing.expectEqualStrings("noipisa", span.text);
                try std.testing.expectEqualStrings("tao", span.language);
                try std.testing.expectEqualStrings("Latn", span.classes);
            }
        }
        try std.testing.expectEqual(@as(usize, 1), actions);
        try std.testing.expect(std.mem.indexOf(u8, try FormattingScopeTest.text(a, spans), "以後有機會時") != null);
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    }
}

test "Ruby parent refutation binds exact current label and literal direct child" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var profile = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer profile.deinit();
    const F = ProjectedRubyLink179Test;
    for (0..14) |mode| {
        var fixture = try F.init(a, &profile);
        const whole = fixture.prepared;
        const at = std.mem.indexOf(u8, whole, "<ruby>").?;
        const tag = syntax.tagAt(whole, at).?;
        const pair = syntax.matchingTag(whole, tag).?;
        const label = whole[at..pair.end];
        var anchor: table_style_profile.TextElement = .{ .tag = "a", .complete_ancestor_classes = "mw-parser-output Jpan",
            .ancestor_class_scope = fixture.scope, .ancestor_class_source = F.source };
        var node: table_style_profile.TextElement = .{ .tag = tag.name, .source_key = @intFromPtr(tag.name.ptr), .parent = &anchor,
            .complete_ancestor_classes = "mw-parser-output Jpan", .ancestor_class_scope = fixture.scope, .ancestor_class_source = F.source };
        var tracked: MissingText = .{ .bytes = whole, .unknown = true };
        fixture.renderer.explicit_wiki_label = .{ .kind = .link, .target = "Target", .ordinary_anchor = &anchor,
            .ordinary_label = label, .ordinary_depth = 2 };
        const foreign_anchor = try a.create(table_style_profile.TextElement); foreign_anchor.* = anchor;
        try std.testing.expect(foreign_anchor != &anchor);
        switch (mode) {
            0 => {},
            1 => fixture.renderer.explicit_wiki_label = null,
            2 => fixture.renderer.explicit_wiki_label.?.ordinary_label = try a.dupe(u8, label),
            3 => fixture.renderer.explicit_wiki_label.?.ordinary_label = label[1..],
            4 => fixture.renderer.explicit_wiki_label.?.ordinary_anchor = foreign_anchor,
            5 => fixture.renderer.explicit_wiki_label.?.kind = .external_link,
            6 => node.source_key += 1,
            7 => node.ancestor_class_source = try a.dupe(u8, F.source),
            8 => tracked.lost_missing_range = true,
            9 => tracked.ranges = &.{.{ .start = @intCast(at), .end = @intCast(pair.end), .occurrence = 1 }},
            10 => fixture.projection.copies = &.{},
            11 => anchor.alternative_ancestry = foreign_anchor,
            12 => fixture.renderer.in_reference = true,
            13 => fixture.renderer.html_blockquote_flow = true,
            else => unreachable,
        }
        fixture.renderer.inline_missing = tracked;
        const result = fixture.renderer.rubySourceParentTag(tag, &node);
        if (mode == 0) {
            try std.testing.expectEqualStrings("a", result.?);
            try std.testing.expect(!node.ancestry_complete and !node.physical_ancestry_complete and node.source_parent_tag_nonmatch == null);
        } else try std.testing.expect(result == null);
    }
    // The first RP is a complete sibling before RT; a wrong parent or an
    // intervening wrapper is not interchangeable with that direct relationship.
    var fixture = try F.init(a, &profile);
    const whole = fixture.prepared;
    fixture.renderer.inline_missing = .{ .bytes = whole, .unknown = true };
    const ruby_tag = syntax.tagAt(whole, std.mem.indexOf(u8, whole, "<ruby>").?).?;
    const rt_tag = syntax.tagAt(whole, std.mem.indexOf(u8, whole, "<rt>").?).?;
    var ruby_node: table_style_profile.TextElement = .{ .tag = ruby_tag.name, .source_key = @intFromPtr(ruby_tag.name.ptr),
        .complete_ancestor_classes = "mw-parser-output Jpan", .ancestor_class_scope = fixture.scope, .ancestor_class_source = F.source };
    var rt_node: table_style_profile.TextElement = .{ .tag = rt_tag.name, .source_key = @intFromPtr(rt_tag.name.ptr), .parent = &ruby_node,
        .complete_ancestor_classes = "mw-parser-output Jpan", .ancestor_class_scope = fixture.scope, .ancestor_class_source = F.source };
    try std.testing.expectEqualStrings("ruby", fixture.renderer.rubySourceParentTag(rt_tag, &rt_node).?);
    ruby_node.source_key += 1;
    try std.testing.expect(fixture.renderer.rubySourceParentTag(rt_tag, &rt_node) == null);
    ruby_node.source_key -= 1;
    rt_node.parent = null;
    try std.testing.expect(fixture.renderer.rubySourceParentTag(rt_tag, &rt_node) == null);
    for ([_][]const u8{
        "<ruby><rt>x</rt></ruby>",
        "<ruby><span><rt>x</rt></span></ruby>",
        "<ruby><nowiki>p</nowiki><rt>x</rt></ruby>",
        "<ruby>[[X]]<rt>x</rt></ruby>",
        "<ruby><!--p--><rt>x</rt></ruby>",
        "<ruby><rp>(</rp><rt>x</rt></ruby>",
        "<ruby><span><div>x</div></span><rt>x</rt></ruby>",
        "<ruby><span><rb>x</rb></span><rt>x</rt></ruby>",
        "<ruby><div>x</div><rt>x</rt></ruby>",
        "<ruby><ul><li>x</li></ul><rt>x</rt></ruby>",
        "<ruby><table><tr><td>x</td></tr></table><rt>x</rt></ruby>",
        "<ruby><button>x</button><rt>x</rt></ruby>",
        "<ruby><span><button>x</button></span><rt>x</rt></ruby>",
        "<ruby><span>[[X]]</span><rt>x</rt></ruby>",
    }, 0..) |source, index| {
        var selected = try BulletRuby182Test.init(a, &profile, source);
        const bytes = selected.source_element_binding.?.owner.bytes;
        selected.inline_missing = .{ .bytes = bytes, .unknown = true };
        const scope = selected.source_element_binding.?.scope;
        const parent_tag = syntax.tagAt(bytes, BulletRuby182Test.inserted.len).?;
        const child_tag = syntax.tagAt(bytes, std.mem.indexOf(u8, bytes, "<rt>").?).?;
        var parent_node: table_style_profile.TextElement = .{ .tag = parent_tag.name, .source_key = @intFromPtr(parent_tag.name.ptr),
            .complete_ancestor_classes = scope.complete_ancestor_class_superset, .ancestor_class_scope = scope, .ancestor_class_source = source };
        const child_node: table_style_profile.TextElement = .{ .tag = child_tag.name, .source_key = @intFromPtr(child_tag.name.ptr), .parent = &parent_node,
            .complete_ancestor_classes = scope.complete_ancestor_class_superset, .ancestor_class_scope = scope, .ancestor_class_source = source };
        try std.testing.expectEqual(index == 0 or index == 5, selected.rubySourceParentTag(child_tag, &child_node) != null);
    }
}

test "Ruby parent refutation uses issued quote keys with a registered copied label" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var profile = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer profile.deinit();
    const F = ProjectedRubyLink179Test;
    for (0..5) |mode| {
        var fixture = try F.init(a, &profile);
        const original = fixture.prepared[F.inserted.len..];
        const copied = try a.dupe(u8, original);
        try std.testing.expect(copied.ptr != original.ptr);
        var map: QuoteSourceMap = .{ .original = original, .output = copied }; defer map.deinit(a);
        try map.copies.append(a, .{ .original_start = 0, .output_start = 0, .len = original.len });
        var domain: Renderer.QuoteClassSource = .{ .map = &map, .scope = fixture.scope, .selected = F.source, .parent = null };
        fixture.renderer.quote_class_source = &domain;
        try fixture.renderer.heading_source_aliases.append(a, .{ .copied = copied, .original = original });
        fixture.renderer.inline_missing = .{ .bytes = copied, .unknown = true };
        const at = std.mem.indexOf(u8, copied, "<ruby>").?;
        const tag = syntax.tagAt(copied, at).?;
        const pair = syntax.matchingTag(copied, tag).?;
        var anchor: table_style_profile.TextElement = .{ .tag = "a", .complete_ancestor_classes = "mw-parser-output Jpan",
            .ancestor_class_scope = fixture.scope, .ancestor_class_source = F.source };
        fixture.renderer.explicit_wiki_label = .{ .kind = .link, .target = "Target", .ordinary_anchor = &anchor,
            .ordinary_label = original[at..pair.end], .ordinary_depth = 2 };
        const ruby_node = try fixture.renderer.textElement(tag, &anchor, "ja");
        const rt_tag = syntax.tagAt(copied, std.mem.indexOf(u8, copied, "<rt>").?).?;
        const rt_node = try fixture.renderer.textElement(rt_tag, ruby_node, "ja");
        try std.testing.expectEqual(@intFromPtr(original.ptr) + at + 1, ruby_node.source_key);
        try std.testing.expect(ruby_node.source_key != @intFromPtr(tag.name.ptr));
        try std.testing.expectEqual(@intFromPtr(tag.name.ptr), fixture.renderer.ordinaryLinkOriginal(fixture.renderer.figureClassSourceDomain().?, tag.name).?.key);
        switch (mode) {
            0 => {},
            1 => @constCast(ruby_node).source_key = @intFromPtr(tag.name.ptr),
            2 => @constCast(rt_node).source_key = @intFromPtr(rt_tag.name.ptr),
            3 => map.copies.clearRetainingCapacity(),
            4 => domain.selected = try a.dupe(u8, F.source),
            else => unreachable,
        }
        if (mode == 0) {
            try std.testing.expectEqualStrings("a", fixture.renderer.rubySourceParentTag(tag, ruby_node).?);
            try std.testing.expectEqualStrings("ruby", fixture.renderer.rubySourceParentTag(rt_tag, rt_node).?);
            try std.testing.expect(!ruby_node.physical_ancestry_complete and !rt_node.physical_ancestry_complete);
        } else {
            if (mode != 2) try std.testing.expect(fixture.renderer.rubySourceParentTag(tag, ruby_node) == null);
            try std.testing.expect(fixture.renderer.rubySourceParentTag(rt_tag, rt_node) == null);
        }
    }
}

test "Ruby parent source receipt excludes nested anchors and structural reconstruction" {
    const F = ProjectedRubyLink179Test;
    const at = std.mem.indexOf(u8, F.source, "<ruby>").?;
    const tag = syntax.tagAt(F.source, at).?;
    const pair = syntax.matchingTag(F.source, tag).?;
    try std.testing.expect(Renderer.rubyGeneratedAnchorParentStable(F.source[at..pair.end]));
    try std.testing.expect(Renderer.rubyGeneratedAnchorParentStable("<ruby><rb><b>x</b></rb><rp>(</rp><rt>y</rt><rp>)</rp></ruby>"));
    for ([_][]const u8{
        "<ruby>[[X|x]]<rt>y</rt></ruby>",
        "<ruby>[https://example.test x]<rt>y</rt></ruby>",
        "<ruby>https://example.test<rt>y</rt></ruby>",
        "<ruby><a href='X'>x</a><rt>y</rt></ruby>",
        "<ruby><span><a href='X'>x</a></span><rt>y</rt></ruby>",
        "<ruby><ruby>x<rt>y</rt></ruby><rt>z</rt></ruby>",
        "<ruby><div>x</div><rt>y</rt></ruby>",
        "<ruby><ul><li>x</li></ul><rt>y</rt></ruby>",
        "<ruby><table><tr><td>x</td></tr></table><rt>y</rt></ruby>",
        "<ruby><button>x</button><rt>y</rt></ruby>",
        "<ruby><input><rt>y</rt></ruby>",
        "<ruby><nowiki>x</nowiki><rt>y</rt></ruby>",
        "<ruby><!--x-->a<rt>y</rt></ruby>",
        "<ruby>{{{x}}}<rt>y</rt></ruby>",
        "<ruby>-{x}-<rt>y</rt></ruby>",
        "<ruby>''x''<rt>y</rt></ruby>",
        "<ruby>x<rt>y</rt></ruby>tail",
    }) |source| try std.testing.expect(!Renderer.rubyGeneratedAnchorParentStable(source));
}

const ConsumedDivChoice176Test = struct {
    const full = @embedFile("testdata/zh-gugli176-expanded.wikitext");
    const reference = @embedFile("testdata/zh-gugli176-reference.wikitext");
    const target = "https://zh.wikipedia.org/wiki/%E5%A4%B1%E6%95%88%E9%93%BE%E6%8E%A5";
    const prefix = "<div class='citation-whole'><span>earlier [[Earlier|body]]</span><dl><dd>quotation</dd></dl></div>";
    const token = "[[Wikipedia:失效链接|<span title='自2022年11月失效'>永久-{zh:失效連結;zh-hant:失效連結;zh-hans:失效链接}-</span>]]";
    const FileFact = struct {
        batch: u32,
        canonical_file: []const u8,
        requested_file: []const u8,
        file_sha1: []const u8,
        file_timestamp: []const u8,
        mediatype: []const u8,
        mime: []const u8,
        original_width: u32,
        original_height: u32,
        state: []const u8,
    };
    const Media = struct {
        ns: *const @import("namespace_registry").Registry,
        namespace_sha256: [32]u8,
        facts: []const FileFact,
        fn resolve(raw: ?*const anyopaque, a: A, file: []const u8, format: presentation_types.FigureFormat, width: ?u32, height: ?u32) A.Error!?presentation_types.FigureSizingPolicy {
            const self: *const Media = @ptrCast(@alignCast(raw orelse return null));
            if (!std.mem.eql(u8, &self.namespace_sha256, &self.ns.source_sha256) or format != .thumbnail or height != null) return null;
            const requested_width = width orelse return null;
            if (requested_width == 0) return null;
            const canonical = self.ns.normalizeTitle(a, file, 6, .any) catch |err| return if (err == error.OutOfMemory) error.OutOfMemory else null;
            defer a.free(canonical);
            for (self.facts) |fact| {
                if (!std.mem.eql(u8, canonical, fact.requested_file) or !std.mem.eql(u8, fact.requested_file, fact.canonical_file)) continue;
                if (!std.mem.eql(u8, fact.state, "eligible") or fact.original_height == 0 or requested_width > fact.original_width) return null;
                if (!((std.mem.eql(u8, fact.mediatype, "BITMAP") and std.mem.eql(u8, fact.mime, "image/png")) or
                    (std.mem.eql(u8, fact.mediatype, "DRAWING") and std.mem.eql(u8, fact.mime, "image/svg+xml")))) return null;
                return .requested_fit;
            }
            return null;
        }
    };
    fn fullContext(a: A, ns: *@import("namespace_registry").Registry) !Context {
        const NS = @import("namespace_registry");
        try ns.attachLanguageConversion(@embedFile("testdata/zh-gugli176/namespace-siteinfo.raw.json"));
        // Match the normal loader's independent converter and figure epochs.
        // Only value fields cross from the isolated figure-site registry.
        var figure_ns = try NS.Registry.init(a, @embedFile("testdata/zh-gugli176/namespace-registry.tsv"));
        defer figure_ns.deinit();
        try figure_ns.attachLanguageConversion(@embedFile("testdata/zh-gugli176/figure-siteinfo.raw.json"));
        if (!std.mem.eql(u8, &ns.source_sha256, &figure_ns.source_sha256)) return error.TestUnexpectedResult;
        const defaults = figure_ns.figure_source_defaults orelse return error.TestUnexpectedResult;
        const facts = try std.json.parseFromSlice([]FileFact, a, @embedFile("testdata/zh-gugli176/retained-file-facts.json"), .{});
        const media = try a.create(Media);
        media.* = .{ .ns = ns, .namespace_sha256 = ns.source_sha256, .facts = facts.value };
        // Explicit controlled CSS scope, shared by the full input and reference;
        // this does not claim that the genuine page's CSS has been qualified.
        const styles = try a.create(table_style_profile.Profile);
        styles.* = try table_style_profile.parseAlloc(a, "");
        try ns.attachInterwikiMap("Wikipedia\t1\t0\t0\t0\thttps://zh.wikipedia.org/wiki/$1\nw\t1\t0\t0\t0\thttps://zh.wikipedia.org/wiki/$1\n");
        const behavior = try a.create(NS.behavior_switches.Registry);
        behavior.* = try ManualConversionTest.behavior(a, ns);
        return .{ .namespace_catalog = ns, .behavior_switches = behavior, .content_conversion = true,
            .table_styles = styles, .text_paint_styles = styles,
            .figure_sizing = .{ .ctx = media, .resolve_fn = Media.resolve,
                .source_context = .{ .namespace_sha256 = ns.source_sha256, .defaults = defaults } } };
    }
    fn context(a: A, ns: *@import("namespace_registry").Registry) !Context {
        ns.content_language = "zh";
        ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
        ns.manual_conversion_context = SourceRecursiveManualTest.profile();
        try ns.attachInterwikiMap("Wikipedia\t1\t0\t0\t0\thttps://zh.wikipedia.org/wiki/$1\nw\t1\t0\t0\t0\thttps://zh.wikipedia.org/wiki/$1\n");
        const behavior = try a.create(@import("namespace_registry").behavior_switches.Registry);
        behavior.* = try ManualConversionTest.behavior(a, ns);
        return .{ .namespace_catalog = ns, .behavior_switches = behavior, .content_conversion = true };
    }
};

test "consumed quotation DIV preserves complete retained gugli source body actions Missing and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = ConsumedDivChoice176Test; const NS = @import("namespace_registry");
    // The whole retained expanded page is input, not an isolated tooltip. The
    // reference changes only the source-proved base-zh choice. The retained
    // normal media inputs supply defaults and file facts; both arms use an
    // explicit empty test stylesheet, not claimed genuine page CSS.
    const opening = std.mem.indexOf(u8, T.full, "[[Wikipedia:失效链接|") orelse return error.TestUnexpectedResult;
    const line_start = (std.mem.lastIndexOfScalar(u8, T.full[0..opening], '\n') orelse return error.TestUnexpectedResult) + 1;
    const line_end = std.mem.indexOfScalarPos(u8, T.full, opening, '\n') orelse return error.TestUnexpectedResult;
    const quotation = T.full[line_start..line_end];
    const body_start = std.mem.indexOf(u8, quotation, "<div class=\"citation-whole\">") orelse return error.TestUnexpectedResult;
    const local_link = std.mem.indexOf(u8, quotation[body_start..], "[[Wikipedia:") orelse return error.TestUnexpectedResult;
    try std.testing.expect(!Renderer.formattingAngleBodyPosition(quotation[body_start..], local_link));
    for ([_]bool{ false, true }) |unknown| {
        var ns = try NS.Registry.init(a, @embedFile("testdata/zh-gugli176/namespace-registry.tsv")); defer ns.deinit();
        const context = try T.fullContext(a, &ns);
        const source: MissingText = .{ .bytes = T.full, .unknown = unknown };
        const reference: MissingText = .{ .bytes = T.reference, .unknown = unknown };
        var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = source };
        var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = reference };
        const actual_blocks = try actual_renderer.renderBodyWithMissing(source);
        const expected_blocks = try expected_renderer.renderBodyWithMissing(reference);
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, actual_blocks);
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, expected_blocks);
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
        try std.testing.expectEqual(unknown, actual_renderer.body_missing.?.unknown);
        try std.testing.expect(!actual_renderer.body_missing.?.lost_missing_range);
        try std.testing.expectEqualDeep(source.ranges, actual_renderer.body_missing.?.ranges);
        var tooltip_actions: usize = 0; var yahoo_actions: usize = 0; var group_actions: usize = 0;
        for (try FigureProducerTest.bodySpans(a, actual_blocks)) |span| {
            try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
            if (span.kind != .external_link) continue;
            if (std.mem.eql(u8, span.target, T.target)) {
                tooltip_actions += 1;
                try std.testing.expectEqualStrings("永久失效連結", span.text);
                try std.testing.expectEqualStrings("自2022年11月失效", span.tooltip orelse return error.TestUnexpectedResult);
                try std.testing.expect(span.flags.superscript);
            }
            if (std.mem.eql(u8, span.target, "http://dir.groups.yahoo.com/group/esperantoaustralia/message/4922")) {
                yahoo_actions += 1; try std.testing.expectEqualStrings("[2]", span.text);
            }
            if (std.mem.eql(u8, span.target, "https://groups.google.com/group/soc.culture.esperanto/msg/d3cdd665bfd6aae9")) {
                group_actions += 1; try std.testing.expectEqualStrings("[1]", span.text);
            }
        }
        try std.testing.expectEqual(@as(usize, 1), tooltip_actions);
        try std.testing.expectEqual(@as(usize, 1), yahoo_actions);
        try std.testing.expectEqual(@as(usize, 1), group_actions);
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
        const decoded = try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .heading = "English", .code = "en" });
        try std.testing.expectEqualDeep(actual, decoded);
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));
    }
}

test "consumed DIV position receipts keep invocation source metadata mutation and protected refusals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = ConsumedDivChoice176Test; const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    const context = try T.context(a, &ns);
    const source = try std.mem.concat(a, u8, &.{ T.prefix, T.token });
    const original = try a.dupe(u8, source);
    const tracked: MissingText = .{ .bytes = source, .unknown = true };
    var ledger: ConsumedClosedInlineDivs = .{ .source = source, .unknown = true, .snapshot = try a.dupe(u8, source) };
    var frame: InlineSourceDomain = .{ .source = source, .tracked = tracked, .parent = null, .consumed_closed_divs = &ledger };
    ledger.owner = &frame;
    var renderer: Renderer = .{ .a = a, .context = context, .inline_missing = tracked, .inline_source_domain = &frame };
    const end = T.prefix.len;
    try std.testing.expect(Renderer.consumedClosedDivEnd(source, 0, end, tracked, &frame) == null);
    try renderer.recordConsumedClosedDiv(tracked, 0, end, .{});
    try std.testing.expectEqual(@as(usize, 1), ledger.ranges.items.len);
    try std.testing.expectEqual(end, Renderer.consumedClosedDivEnd(source, 0, end, tracked, &frame).?);
    try std.testing.expect(!Renderer.formattingAngleBodyPosition(source, end));
    try std.testing.expect(Renderer.formattingAngleBodyPositionWithClosedDivSiblings(source, end, tracked, &frame));
    try std.testing.expect(!Renderer.formattingAngleBodyPositionWithConsumedSiblingsIn(source, end, false, tracked, false, &frame));
    try std.testing.expect(!Renderer.formattingAngleBodyPositionWithConsumedSiblingsIn(source, end, false, tracked, true, &frame));
    try std.testing.expect(Renderer.consumedClosedDivEnd(source, 0, end - 1, tracked, &frame) == null);
    const original_range = ledger.ranges.items[0];
    ledger.ranges.items[0][1] = end - 1;
    try std.testing.expect(Renderer.consumedClosedDivEnd(source, 0, end, tracked, &frame) == null);
    ledger.ranges.items[0] = original_range;
    var foreign_frame = frame;
    try std.testing.expect(Renderer.consumedClosedDivEnd(source, 0, end, tracked, &foreign_frame) == null);
    const copied = try a.dupe(u8, source);
    try std.testing.expect(Renderer.consumedClosedDivEnd(copied, 0, end, .{ .bytes = copied, .unknown = true }, &frame) == null);
    for (0..5) |mode| {
        var changed = tracked;
        switch (mode) {
            0 => changed.lost_missing_range = true,
            1 => changed.generated_source = source,
            2 => changed.unknown = false,
            3 => changed.ranges = &.{.{ .start = 2, .end = 3, .occurrence = 1 }},
            4 => changed.literal_curly_ranges = &.{.{ .start = 2, .end = 3 }},
            else => unreachable,
        }
        frame.tracked = changed;
        try std.testing.expect(Renderer.consumedClosedDivEnd(source, 0, end, changed, &frame) == null);
    }
    frame.tracked = tracked;
    source[1] = 'D';
    try std.testing.expect(Renderer.consumedClosedDivEnd(source, 0, end, tracked, &frame) == null);
    // Even a still-balanced source mutation cannot be enrolled after parsing:
    // the immutable frame image predates the ordinary child invocation.
    ledger.ranges.clearRetainingCapacity();
    try renderer.recordConsumedClosedDiv(tracked, 0, end, .{});
    try std.testing.expectEqual(@as(usize, 0), ledger.ranges.items.len);
    @memcpy(source, original);
    for ([_]Style{ .{ .provenance = .protected_literal }, .{ .code = true }, .{ .kind = .link, .target = "Foreign" } }) |style|
        try renderer.recordConsumedClosedDiv(tracked, 0, end, style);
    try std.testing.expectEqual(@as(usize, 0), ledger.ranges.items.len);
    try renderer.recordConsumedClosedDiv(tracked, 0, end - 1, .{});
    try std.testing.expectEqual(@as(usize, 0), ledger.ranges.items.len);
    try renderer.recordConsumedClosedDiv(tracked, 0, end, .{});
    const inside_attribute = std.mem.indexOf(u8, source, "citation-whole").?;
    const inside_body = std.mem.indexOf(u8, source, "earlier").?;
    try std.testing.expect(!Renderer.formattingAngleBodyPositionWithClosedDivSiblings(source, inside_attribute, tracked, &frame));
    try std.testing.expect(!Renderer.formattingAngleBodyPositionWithClosedDivSiblings(source, inside_body, tracked, &frame));
    var missing_snapshot = ledger; missing_snapshot.snapshot = null;
    frame.consumed_closed_divs = &missing_snapshot;
    try std.testing.expect(Renderer.consumedClosedDivEnd(source, 0, end, tracked, &frame) == null);
    frame.consumed_closed_divs = &ledger;
    // This choice caller gains only the closed-DIV receipt, not the other
    // pinned recursive evaluator's BR or preceding-nested-rule grammar.
    for ([_][]const u8{ "<br>", "-{[[Earlier|-{body}-]]}-" }) |prefix| {
        const candidate = try std.mem.concat(a, u8, &.{ prefix, T.token });
        const candidate_tracked: MissingText = .{ .bytes = candidate, .unknown = true };
        var candidate_ledger: ConsumedClosedInlineDivs = .{ .source = candidate, .unknown = true, .snapshot = try a.dupe(u8, candidate) };
        var candidate_frame: InlineSourceDomain = .{ .source = candidate, .tracked = candidate_tracked, .parent = null, .consumed_closed_divs = &candidate_ledger };
        candidate_ledger.owner = &candidate_frame;
        try std.testing.expect(!Renderer.formattingAngleBodyPositionWithClosedDivSiblings(candidate, prefix.len, candidate_tracked, &candidate_frame));
    }
    ns.manual_conversion_context.?.source_core = "foreign";
    ledger.ranges.clearRetainingCapacity();
    try renderer.recordConsumedClosedDiv(tracked, 0, end, .{});
    try std.testing.expectEqual(@as(usize, 0), ledger.ranges.items.len);
}

const OrdinaryViewportLinks187Test = struct {
    const T = OrdinaryTableLinkProducerTest;
    const css_without_auto_margins = T.css ++ "table{width:70%;border-collapse:collapse;box-sizing:border-box}" ++
        "@media(max-width:639px){table{display:block;overflow:auto;max-width:100%}}" ++
        ".mw-parser-output a{word-wrap:break-word}";
    // The ordinary block viewport wire shape requires horizontal auto margins.
    const css = css_without_auto_margins ++ "table{margin:0 auto}";
    const Constructor = struct {
        source: []const u8,
        refuse: bool = false,
        fn resolve(raw: ?*const anyopaque, _: A, operation: TableSourceAnchorOperation) A.Error!?[]const table_style_profile.FigureObservedAttribute {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
            if (self.refuse or operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
                !Renderer.wikiClassContains(self.source, operation.token) or
                !std.mem.eql(u8, operation.token, "[[Hilfe:Singular|Singular ''m'']]") or
                !std.mem.eql(u8, operation.target, "Hilfe:Singular")) return null;
            return T.nodes[7].attributes;
        }
    };
    fn renderer(a: A, ns: *const @import("namespace_registry").Registry, styles: *const table_style_profile.Profile) !Renderer {
        var result = try T.renderer(a, T.source, styles);
        result.context.namespace_catalog = ns;
        const constructor = try a.create(Constructor);
        constructor.* = .{ .source = T.source };
        result.context.figure_sizing.?.table_containing_direction.?.anchors = .{
            .source = T.source, .namespace_sha256 = ns.source_sha256,
            .context = constructor, .resolve = Constructor.resolve,
        };
        return result;
    }
    fn candidate(renderer_value: *Renderer) !?Renderer.TableViewportCandidate {
        return renderer_value.prepareTableViewportMode(T.source, 0, 2,
            .{ .style = .{}, .formatting = .{} }, null, false);
    }
};

test "ordinary viewport retains constructed link proof through materialization cell parsing and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = OrdinaryViewportLinks187Test;
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    // Preserve the actual189 omitted-margin fixture as a rejected shape.
    var no_margins = try table_style_profile.parseForTargetAlloc(a, T.css_without_auto_margins, .screen); defer no_margins.deinit();
    var unsupported = try T.renderer(a, &ns, &no_margins);
    try std.testing.expect((try T.candidate(&unsupported)) == null);
    var styles = try table_style_profile.parseForTargetAlloc(a, T.css, .screen); defer styles.deinit();
    var renderer = try T.renderer(a, &ns, &styles);
    var candidate = (try T.candidate(&renderer)) orelse return error.TestUnexpectedResult;
    const bound = candidate.link_source orelse return error.TestUnexpectedResult;
    try std.testing.expect(bound.source_constructed and !bound.context.intrinsic_viewport);
    try std.testing.expect(candidate.geometry == null and candidate.float_policy == null and candidate.prefix_font_owner == null);
    try std.testing.expectEqual(@as(u32, 639), candidate.policy.?.max_viewport_width_px);
    try std.testing.expect(candidate.policy.?.focus_paint == null);
    try std.testing.expectEqual(@as(usize, 1), bound.links.len);
    try std.testing.expectEqualStrings("#3366cc", bound.links[0].paint.?.normal.foreground);
    try std.testing.expectEqual(presentation_types.TextWrap.break_word, bound.links[0].wrap.?);
    const body = candidate.cells[0].body;
    const links = try renderer.tableLinksForCell(candidate, body);
    try std.testing.expectEqual(@as(usize, 1), links.len);
    try std.testing.expect(links[0].token.ptr == bound.links[0].token.ptr);
    try std.testing.expectEqual(@as(usize, 0), (try renderer.tableLinksForCell(candidate, try a.dupe(u8, body))).len);
    // The historical ordinary return dropped this exact field before the cell.
    var dropped = candidate; dropped.link_source = null;
    try std.testing.expectEqual(@as(usize, 0), (try renderer.tableLinksForCell(dropped, body)).len);
    try renderer.materializeTableViewport(&candidate);
    try std.testing.expect(candidate.link_source.?.links.ptr == bound.links.ptr);
    const opening: syntax.Tag = .{ .name = "table", .attrs = T.T.source[2..2], .end = 0, .closing = false, .self_closing = false };
