const HiddenInlineMissingCompilerTest = if (@import("builtin").is_test) struct {
    const F = InlineMissingCompilerTest;
    const opening = "<table class='audiotable' style='display:inline-block'><tr>";
    const leading = "<td>Audio: </td>";
    const cell_opening = "<td class='audiofile'>";
    const trailing = "<td class='audiometa' style='font-size:80%'>([[:File:Sr-averz.ogg|file]])</td></tr></table>";
    const source = opening ++ leading ++ cell_opening ++ F.token ++ "</td>" ++ trailing;
    const reference = opening ++ leading ++ trailing;
    const row_start = "<table class='audiotable' style='display:inline-block'>".len;
    const cell_start = opening.len + leading.len;
    const token_start = cell_start + cell_opening.len;
    const Issuer = struct {
        styles: *const table_style_profile.Profile, contexts: []const table_style_profile.InlineMissingContext,
        accepted: usize = 0,
        fn observe(raw: ?*const anyopaque, _: A, operation: InlineMissingOperation) A.Error!?InlineMissingObservation {
            const self: *@This() = @ptrCast(@alignCast(@constCast(raw orelse return null)));
            if (operation.source.ptr != source.ptr or operation.source.len != source.len or
                operation.token.ptr != source[token_start..].ptr or operation.token.len != F.token.len or
                !std.mem.eql(u8, operation.file, "Sr-averz.ogg")) return null;
            self.accepted += 1;
            return .{ .profile = self.styles, .contexts = self.contexts, .label = "noicon", .href = F.href,
                .title = "File:Sr-averz.ogg", .data_width = 175, .table_opening = source[0..row_start],
                .row_opening = source[row_start..opening.len], .cell_opening = source[cell_start..token_start] };
        }
    };
} else struct {};

