test "hidden inline Missing disposition refuses taint foreign parents and absent operation then restores its receipt" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = InlineMissingCompilerTest;
    var namespaces = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").german_test_fixture); defer namespaces.deinit();
    try FigureProducerTest.attachThumbnailDefaults(a, &namespaces, false);
    var options = try @import("namespace_registry").image_options.Registry.init(a, image_option_test_identity ++ "img_width\t1\t\"$1px\"\n", "dewiktionary", "20261001", "de", @splat(0), @splat(0)); defer options.deinit();
    var parent = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer parent.deinit();
    var styles = try table_style_profile.parseForTargetAlloc(a, F.css ++ ".client-nojs .audiofile{display:none}", .screen); defer styles.deinit(); styles.page_style_parent = &parent;
    var nodes = F.nodes; nodes[0].attributes = &.{.{ .name = "lang", .value = "de" }, .{ .name = "class", .value = "client-nojs" }};
    const observed: table_style_profile.InlineMissingContext = .{ .styles = &styles, .nodes = &nodes, .root = 2, .wrapper = 7, .anchor = 8, .label = 9 };
    var issuer: F.Issuer = .{ .styles = &styles, .contexts = &.{observed, observed} };
    var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "audiotable audiofile",
        .complete_ancestor_class_superset = "client-nojs mw-parser-output audiotable audiofile" };
    const context: Context = .{ .namespace_catalog = &namespaces, .image_options = &options, .table_styles = &styles,
        .figure_sizing = .{ .resolve_fn = F.noSizing, .figure_style_ctx = &issuer, .resolve_inline_missing_fn = F.Issuer.observe,
            .text_class_scope = .{ .source = F.source, .scope = &scope },
            .source_context = .{ .namespace_sha256 = namespaces.source_sha256, .defaults = namespaces.figure_source_defaults.?, .missing_media_profile = .f45897 } } };
    const tag = syntax.tagAt(F.source, F.cell_start).?;
    const pair = syntax.matchingTag(F.source, tag).?;
    for (0..10) |mode| {
        var incomplete_scope = scope; incomplete_scope.complete_ancestor_class_superset = null;
        var table: Renderer.InlineTableBoundaries = .{ .source_opening = syntax.tagAt(F.source, 0).?, .row_opening = syntax.tagAt(F.source, F.row_start).? };
        var renderer: Renderer = .{ .a = a, .context = context, .body_depth = 1, .content_root = .parser_output,
            .bounded_text_class_source = F.source, .bounded_text_class_scope = &scope,
            .body_missing = .{ .bytes = F.source },
            .inline_table_boundaries = &table };
        var tracked: MissingText = .{ .bytes = F.source }; var chosen = tag; var style: Style = .{};
        switch (mode) {
            0 => {},
            1 => tracked.lost_missing_range = true,
            2 => tracked.ranges = &.{.{ .start = F.token_start, .end = F.token_start + 1, .occurrence = 1 }},
            3 => chosen = syntax.tagAt(try a.dupe(u8, F.source), F.cell_start).?,
            4 => renderer.inline_table_boundaries.?.row_opening = syntax.tagAt(try a.dupe(u8, F.source), F.row_start).?,
            5 => renderer.context.figure_sizing.?.resolve_inline_missing_fn = null,
            6 => renderer.context.figure_sizing.?.source_context.?.missing_media_profile = null,
            7 => style.kind = .external_link,
            8 => renderer.inline_table_boundaries = null,
            9 => {
                renderer.bounded_text_class_scope = &incomplete_scope;
                renderer.context.figure_sizing.?.text_class_scope.?.scope = &incomplete_scope;
            },
            else => unreachable,
        }
        const proof = try renderer.hiddenInlineMissingCell(tracked, chosen, pair, style);
        if (mode != 0) { try std.testing.expect(proof == null); continue; }
        const owned = proof orelse return error.TestUnexpectedResult;
        renderer.hidden_inline_missing = owned;
        // The receipt is usable only inside the existing hidden consumer's
        // cleared table/capture state and for the exact owned token and file.
        renderer.inline_table_boundaries = null;
        try std.testing.expect(try renderer.emitObservedInlineMissing(tracked, owned.token, owned.file, .{}));
        try std.testing.expectEqual(@as(usize, 0), renderer.spans.items.len);
        try std.testing.expectEqual(@as(usize, 1), renderer.nodes);
        const foreign = try a.dupe(u8, owned.token);
        try std.testing.expect(!try renderer.emitObservedInlineMissing(.{ .bytes = foreign }, foreign, owned.file, .{}));
        try std.testing.expect(!try renderer.emitObservedInlineMissing(tracked, owned.token, "Ready.ogg", .{}));
        var tainted = tracked;
        tainted.ranges = &.{.{ .start = F.token_start, .end = F.token_start + 1, .occurrence = 1 }};
        try std.testing.expectError(error.UncompiledPresentation, renderer.emitObservedInlineMissing(tainted, owned.token, owned.file, .{}));
        renderer.nodes = max_nodes;
        try std.testing.expect(try renderer.emitObservedInlineMissing(tracked, owned.token, owned.file, .{}));
        try std.testing.expect(renderer.fallbacks.render_limit and renderer.truncated);
        try std.testing.expectEqual(@as(usize, max_nodes), renderer.nodes);
        renderer.hidden_inline_missing = null;
        try std.testing.expectError(error.UncompiledPresentation, renderer.emitObservedInlineMissing(tracked, owned.token, owned.file, .{}));
        try std.testing.expectEqual(@as(usize, 0), renderer.spans.items.len);
    }
}

test "retained gugli fixture media facts require exact namespace file and bounded thumbnail tuple" {
