    try std.testing.expectEqual(@as(?presentation_types.FigureSizingPolicy, null), try sizing.resolve_fn(sizing.ctx, a, "File:Other.png", .thumbnail, width, null));
    try std.testing.expectEqual(@as(?presentation_types.FigureSizingPolicy, null), try sizing.resolve_fn(sizing.ctx, a, "File:Google suggest.png", .framed, width, null));
    try std.testing.expectEqual(@as(?presentation_types.FigureSizingPolicy, null), try sizing.resolve_fn(sizing.ctx, a, "File:Google suggest.png", .thumbnail, width, 1));
    try std.testing.expectEqual(@as(?presentation_types.FigureSizingPolicy, null), try sizing.resolve_fn(null, a, "File:Google suggest.png", .thumbnail, width, null));
    const digest = ns.source_sha256;
    ns.source_sha256[0] ^= 1;
