    changed.facts = &.{};
    try std.testing.expectEqual(@as(?presentation_types.FigureSizingPolicy, null), try T.Media.resolve(&changed, a, "File:Google suggest.png", .thumbnail, width, null));
}

const OrdinaryConstructedFont189Test = struct {
    const T = OrdinaryTableLinkProducerTest;
    const body = "<div style=\"clear:both;background:#efefef;text-align:center\">'''Дополнительные символы'''</div>\n<div style=\"text-align:center\"><span style=\"float:left;width:2.1em\">[[ー]]</span><span style=\"float:left;width:2.1em\">[[ゝ]]</span><span style=\"float:left;width:2.1em\">[[ゞ]]</span><span style=\"float:left;width:2.1em\">[[ゟ]]</span><span style=\"float:left;width:2.1em\">[[ゔ]]</span></div>";
    const source = "{|\n|colspan=\"11\" class=\"Unicode\"|\n" ++ body ++ "\n|}";
    const css = T.css ++ "td span{font-size:1.25em}";
    const Constructor = struct {
        source: []const u8,
        fn resolve(raw: ?*const anyopaque, a: A, operation: TableSourceAnchorOperation) A.Error!?[]const table_style_profile.FigureObservedAttribute {
            const self: *const @This() = @ptrCast(@alignCast(raw orelse return null));
            if (operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
                !Renderer.wikiClassContains(self.source, operation.token)) return null;
            var iterator: ir.InlineIterator = .{ .input = operation.token, .renderer_boundaries = true };
            const token = iterator.next() orelse return null;
            if (token.kind != .link or iterator.cursor != operation.token.len or token.trail.len != 0 or
                !std.mem.eql(u8, token.target, operation.target)) return null;
            const attributes = try a.alloc(table_style_profile.FigureObservedAttribute, 2);
            attributes[0] = .{ .name = "href", .value = try std.fmt.allocPrint(a, "/wiki/{s}", .{token.target}) };
            attributes[1] = .{ .name = "title", .value = token.target };
            return attributes;
        }
    };
    fn prepare(a: A, ns: *const @import("namespace_registry").Registry, input: []const u8,
        styles: *const table_style_profile.Profile) !struct { renderer: Renderer, bound: Renderer.TableLinkSource, body: []const u8 }
    {
        var renderer = try T.renderer(a, input, styles);
        renderer.context.namespace_catalog = ns;
        renderer.context.table_styles = styles; renderer.context.text_paint_styles = styles;
        const constructor = try a.create(Constructor); constructor.* = .{ .source = input };
        const anchors: TableSourceAnchorConstructor = .{ .source = input, .namespace_sha256 = ns.source_sha256,
            .context = constructor, .resolve = Constructor.resolve };
        renderer.context.figure_sizing.?.table_containing_direction.?.anchors = anchors;
        const shallow = T.scope(styles, T.nodes[0..4]);
        const graph = (try renderer.tableViewportWikiGraphIn(input, 0, shallow, false)) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(usize, 1), graph.cells.len);
        const context: table_style_profile.TableContainingDirectionContext = .{ .styles = styles, .nodes = graph.nodes,
            .root = graph.root, .table = graph.table };
        const inventory = (try renderer.tableViewportDescendantInventory(graph, input)) orelse return error.TestUnexpectedResult;
        const bound = (try renderer.tableConstructedLinkSource(graph, input, context, anchors, inventory)) orelse return error.TestUnexpectedResult;
        const cell = graph.cells[0];
        return .{ .renderer = renderer, .bound = bound, .body = input[cell.body_start..cell.body_end] };
    }
    fn install(renderer: *Renderer, bound: Renderer.TableLinkSource, body_slice: []const u8) !void {
        // Match the ordinary candidate's explicit CellLineHeight and finishCell
        // context, rather than pretending source observation alone activates it.
        const cell_style: Style = .{ .font_scale = 1, .font_scale_basis = .normal_body };
        const metric = try relative_font.FontMetric(FontScaleBasis).from(1, .normal_body);
        const policy = try relative_font.resolveCellLineHeight(presentation_types, .inherit, metric, null,
            metric, .{ .multiplier = 1.6 }, true);
        renderer.cell_line_context = Renderer.computedCellNativeContext(cell_style, .{}, policy,
            .{ .style = cell_style, .formatting = .{}, .source_context_known = true });
        try std.testing.expect(renderer.cellObservedFontActive());
        renderer.table_viewport_cell_source = .{ .links = bound.links, .constructed_fonts = bound.constructed_fonts,
            .constructed_font_source = bound.constructed_font_source, .closed_focus = true, .source_constructed = true,
            .source = body_slice, .language = "", .direction = .ltr, .font_scale = 1, .font_scale_basis = .normal_body };
        renderer.inline_missing = MissingText.untracked(body_slice);
    }
};

