        try std.testing.expect(try fixture.renderer.applyObservedCellFont(tag, native, &native));
        try std.testing.expect(!native.font_size_unknown);
        const action = (try fixture.renderer.tableLinkStyle(native, .{ .target = link.target }, link.token)) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualDeep(link.paint.?, action.link_paint.?);
        try std.testing.expectEqualStrings(link.target, action.target);
        try fixture.renderer.textRaw(link.target, action);
        var foreign = native; foreign.font_scale = 2;
        try std.testing.expectError(error.UncompiledPresentation,
            fixture.renderer.tableLinkStyle(foreign, .{ .target = link.target }, link.token));
        try std.testing.expect(link.paint != null and link.wrap_checked);
        observed += 1;
    }
    try std.testing.expectEqual(@as(usize, 5), observed);
    try std.testing.expectEqualStrings("[[ー]]", fixture.bound.links[0].token);
    try std.testing.expectEqualStrings("ー", fixture.bound.links[0].target);
    try std.testing.expectEqualStrings("ゔ", fixture.bound.links[4].target);
    for (seen) |value| try std.testing.expect(value);
    try std.testing.expectEqual(@as(usize, 5), fixture.renderer.spans.items.len);
    for (fixture.renderer.spans.items, fixture.bound.links) |span, link| {
        try std.testing.expectEqualStrings(link.target, span.target);
        try std.testing.expectEqualDeep(link.paint.?, span.link_paint.?);
        try std.testing.expectEqual(@as(f32, 1.25), span.font_scale.?);
    }
    const codec = @import("blob_encoder").presentation_codec;
    const sections = [_]struct { level: u8 = 2, title: []const u8 = "Controls", blocks: []const Block }{
        .{ .blocks = &.{.{ .kind = .paragraph, .spans = fixture.renderer.spans.items }} },
