    const stored = try codec.decodeAlloc(a, bytes, "Font", .language, .{ .code = "de", .heading = "Controls" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
}

test "ordinary constructed font size refuses source profile metadata and owner revocation" {
