            8 => scope.source = try a.dupe(u8, fixture.body),
            9 => queried.name = try a.dupe(u8, tag.name),
            10 => fixture.bound.constructed_fonts[3].owner = null,
            11 => fixture.renderer.table_direction_binding.?.projection = try a.create(SourceElementProjection),
            else => unreachable,
        }
        if (mode == 11) @constCast(fixture.renderer.table_direction_binding.?.projection).* = .{
            .original = MissingText.untracked(input), .prepared = input, .copies = &.{} };
        try std.testing.expect(fixture.renderer.tableConstructedFontForTag(queried) == null);
    }
}

