    const saved = try a.dupe(Renderer.TableInlineSourceFont, fixture.bound.constructed_fonts);
    try std.testing.expect(!try fixture.renderer.tableNestedFontMetricsAtViewport(&fixture.bound, 600));
    for (saved, fixture.bound.constructed_fonts) |before, after| try std.testing.expect(Renderer.tableNestedFontOwnersAgree(before.owner, after.owner));
    // Complete absence invalidates var() and inherits; it is not uncertainty.
    var missing = try table_style_profile.parseForTargetAlloc(a, T.css ++ "td span{font-size:var(--unavailable-font)}", .screen); defer missing.deinit();
    var inherited = try T.prepare(a, &ns, T.source, &missing);
