const OrdinaryPlainPaintTransportTest = struct {
    source: []const u8,
    profile: *const table_style_profile.Profile,
    scope: *const table_style_profile.BoundedTextClassScope,
    expected_target: []const u8 = "target",
    available: bool = true,
    calls: usize = 0,
    fn observe(raw: ?*const anyopaque, _: A, operation: OrdinaryLinkPaintOperation) A.Error!?OrdinaryLinkPaintObservation {
        const self: *@This() = @ptrCast(@alignCast(@constCast(raw orelse return null)));
        self.calls += 1;
        if (!self.available or operation.scope != self.scope or operation.source.ptr != self.source.ptr or operation.source.len != self.source.len or
            operation.token.ptr != self.source.ptr or operation.token.len != self.source.len or !std.mem.eql(u8, operation.target, self.expected_target)) return null;
        const normal: presentation_types.LinkState = .{ .foreground = "#3366cc", .underline = false };
        return .{ .profile = self.profile, .label = "target", .font = .{ .font_scale = 1, .font_scale_basis = .normal_body,
            .font_normalized = true, .bold = true, .language = "en" },
            .wrap = .break_word, .paint = .{ .normal = normal, .hover = normal, .active = normal, .hover_active = .{ .foreground = "#123456", .underline = true },
                .visited = normal, .visited_hover = normal, .visited_active = normal,
                .visited_hover_active = .{ .foreground = "#654321", .underline = true }, .underline_on_focus = true } };
    }
    fn sizing(_: ?*const anyopaque, _: A, _: []const u8, _: presentation_types.FigureFormat, _: ?u32, _: ?u32) A.Error!?presentation_types.FigureSizingPolicy { return null; }
};

