test "lone T requires accepted current title and clean owned source while flag combinations remain refused" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = ExplicitTitlePrecedence188Test;
    var ns = try T.registry(a); defer ns.deinit();
    var foreign_ns = try T.registry(a); defer foreign_ns.deinit();
    const accepted = try T.receipt(a, &ns);
    var renderer: Renderer = .{ .a = a, .context = .{ .title = T.title, .namespace_catalog = &ns,
        .content_conversion = true, .display_title_precedence = accepted }, .inline_missing = MissingText.untracked(T.token) };
    const admitted = try renderer.manualConversion(T.token, 0, .{});
    try std.testing.expectEqual(@as(usize, 0), admitted.body.len);
    try std.testing.expectEqual(T.token.len, admitted.end);
    for ([_][]const u8{ "T;H", "T;A", "T;+", "T;-", "+;T", "H", "A", " T", "T " }) |flags| {
        const source = try std.mem.concat(a, u8, &.{ "-{", flags, "|ku-latn:lêker;ku-arab:لێکەر}-" });
        renderer.inline_missing = MissingText.untracked(source);
        try std.testing.expectError(error.UncompiledPresentation, renderer.manualConversion(source, 0, .{}));
    }
    for (0..14) |mode| {
        renderer.context = .{ .title = T.title, .namespace_catalog = &ns, .content_conversion = true, .display_title_precedence = accepted };
        var tracked = MissingText.untracked(T.token);
        const local_range = [_]missing_dependency.Range{.{ .start = 4, .end = 5, .occurrence = 1 }};
        const literal_range = [_]missing_dependency.LiteralRange{.{ .start = 0, .end = @intCast(T.token.len) }};
        switch (mode) {
            0 => renderer.context.display_title_precedence = null,
            1 => renderer.context.title = try a.dupe(u8, T.title),
            2 => renderer.context.namespace_catalog = &foreign_ns,
            3 => renderer.context.content_conversion = false,
            4 => tracked.unknown = true,
            5 => tracked.lost_missing_range = true,
            6 => tracked.ranges = &local_range,
            7 => tracked.bytes = try a.dupe(u8, T.token),
            8 => renderer.context.display_title_precedence.?.display.unknown = true,
            9 => renderer.context.display_title_precedence.?.display.bytes = "",
            10 => tracked.generated_source = T.token,
            11 => tracked.literal_curly_ranges = &literal_range,
            12 => renderer.context.display_title_precedence.?.display.lost_missing_range = true,
            13 => renderer.context.display_title_precedence.?.display.generated_source = T.display,
            else => unreachable,
        }
        renderer.inline_missing = tracked;
        // A literal-curly ledger must contain only braces. Preserve the exact
        // malformed whole-token ledger as its stronger provenance error.
        const expected_error = if (mode == 11) error.InvalidLiteralProvenance else error.UncompiledPresentation;
        try std.testing.expectError(expected_error, renderer.manualConversion(T.token, 0, .{}));
    }
    renderer.context = .{ .title = T.title, .namespace_catalog = &ns, .content_conversion = true, .display_title_precedence = accepted };
    const protected_brace = [_]missing_dependency.LiteralRange{.{ .start = 1, .end = 2 }};
    renderer.inline_missing = .{ .bytes = T.token, .literal_curly_ranges = &protected_brace };
    try std.testing.expectError(error.UncompiledPresentation, renderer.manualConversion(T.token, 0, .{}));
    renderer.inline_missing = MissingText.untracked(T.token);
    // An enclosing source owner must remain current independently of the
    // clean immediate marker and the accepted display-title carrier.
    for (0..2) |mode| {
        var owner = MissingText.untracked(T.token);
        const domain: InlineSourceDomain = .{ .source = T.token, .parent = null, .tracked = owner };
        renderer.inline_source_domain = &domain;
        const current = try renderer.manualConversion(T.token, 0, .{});
        try std.testing.expectEqual(@as(usize, 0), current.body.len);
        try std.testing.expectEqual(T.token.len, current.end);
        if (mode == 0) owner.lost_missing_range = true else owner.generated_source = T.token;
        const tainted: InlineSourceDomain = .{ .source = T.token, .parent = null, .tracked = owner };
        renderer.inline_source_domain = &tainted;
        try std.testing.expectError(error.UncompiledPresentation, renderer.manualConversion(T.token, 0, .{}));
        renderer.inline_source_domain = null;
    }
    for ([_]Style{ .{ .code = true }, .{ .kind = .external_link, .target = "https://example.test" }, .{ .provenance = .protected_literal } }) |style|
        try std.testing.expectError(error.UncompiledPresentation, renderer.manualConversion(T.token, 0, style));
    const malformed = "-{T|ku-latn:[[Hidden|action]];ku-arab:other}-";
    renderer.inline_missing = MissingText.untracked(malformed);
    try std.testing.expectError(error.UncompiledPresentation, renderer.manualConversion(malformed, 0, .{}));
    const owned = "<span title='" ++ T.token ++ "'>text</span>";
    renderer.inline_missing = MissingText.untracked(owned);
    const at = "<span title='".len;
    try std.testing.expectError(error.UncompiledPresentation, renderer.manualConversion(owned, at, .{}));
}

test "HTML first selector inside complete small conversion retains literal text full body action and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var ns = try @import("namespace_registry").Registry.init(a, @import("namespace_registry").english_test_fixture); defer ns.deinit();
