    for ([_]Case{
        .{ .source = "-{<small>ku:one</small>}-", .reference = "<small>ku:one</small>" },
        .{ .source = "-{<small>ku:one</small>}-[[Tail|after]]", .reference = "<small>ku:one</small>[[Tail|after]]" },
    }, 0..) |case, index| {
    const source = case.source;
    const reference = case.reference;
