    var expected_inline: Renderer = .{ .a = a, .context = context };
    const spans = try actual_inline.parseSpans(source, .{});
    try std.testing.expectEqualDeep(try expected_inline.parseSpans(reference, .{}), spans);
    var actual_renderer: Renderer = .{ .a = a, .context = context };
    var expected_renderer: Renderer = .{ .a = a, .context = context };
    const actual_blocks = try actual_renderer.renderBody(source);
    const expected_blocks = try expected_renderer.renderBody(reference);
    const actual = try FormattingScopeTest.encode(a, &actual_renderer, actual_blocks);
    const expected = try FormattingScopeTest.encode(a, &expected_renderer, expected_blocks);
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
    try std.testing.expect(!actual_renderer.fallbacks.any());
    try std.testing.expectEqual(index + 1, spans.len);
    try std.testing.expectEqualStrings("ku:one", spans[0].text);
    try std.testing.expect(spans[0].kind == .text and spans[0].target.len == 0 and spans[0].provenance == .parsed);
    try std.testing.expectApproxEqAbs(@as(f32, 1.0 / 1.2), spans[0].font_scale.?, 0.000001);
    try std.testing.expectEqual(FontScaleBasis.context, spans[0].font_scale_basis);
    try std.testing.expect(!spans[0].flags.strike and !spans[0].flags.code);
    if (index == 1) {
        try std.testing.expect(spans[1].kind == .link);
        try std.testing.expectEqualStrings("Tail", spans[1].target);
        try std.testing.expectEqualStrings("after", spans[1].text);
    }
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeAlloc(a, actual);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
    try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .code = "en", .heading = "English" }));
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .code = "en", .heading = "English" })));
    }
}


