test "manual HTML ordinary wiki link preserves exact borrowed body style reset actions and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = LinkedHtml176Test;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    var context = try T.context(a, &ns);
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit(); context.behavior_switches = &behavior;
    const prefix = "before [[Before|before]] <i><span class=\"tr Latn\" lang=\"la\">";
    const suffix = "</span></i> after [[After#part|after]]";
    const source = prefix ++ T.token ++ suffix;
    // A neutral SPAN keeps the existing recursive body boundary, as in the
    // maintained scientific-link conversion control, without evaluating a rule.
    const reference = prefix ++ "<span>" ++ T.body ++ "</span>" ++ suffix;
    var witness_stage: []const u8 = "initial";
    var witness_unknown = false;
    errdefer std.debug.print("LINKED_HTML124 stage={s} unknown={any}\n", .{ witness_stage, witness_unknown });
    for ([_]bool{ false, true }) |unknown| {
        witness_unknown = unknown;
        const tracked: MissingText = .{ .bytes = source, .unknown = unknown };
        var proof: Renderer = .{ .a = a, .context = context, .inline_missing = tracked };
        witness_stage = "linked-proof";
        try std.testing.expect(!proof.manualConversionLinkedScope(T.body, true));
        witness_stage = "html-proof";
        try std.testing.expect(proof.manualConversionHtmlScope(T.body, .{}));
        witness_stage = "operation";
        const operation = try proof.manualConversion(source, prefix.len, .{});
        witness_stage = "borrowed-body";
        try std.testing.expect(operation.body.ptr == source.ptr + prefix.len + 2 and operation.body.len == T.body.len);
        witness_stage = "operation-end";
        try std.testing.expectEqual(prefix.len + T.token.len, operation.end);
        witness_stage = "missing-slice";
        try std.testing.expectEqual(unknown, (try missingSlice(a, tracked, operation.body)).unknown);
        var actual_renderer: Renderer = .{ .a = a, .context = context };
        var expected_renderer: Renderer = .{ .a = a, .context = context };
        witness_stage = "actual-body";
        const blocks = try actual_renderer.renderBodyWithMissing(tracked);
        witness_stage = "reference-body";
        const reference_blocks = try expected_renderer.renderBodyWithMissing(.{ .bytes = reference, .unknown = unknown });
        witness_stage = "actual-encode";
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
        witness_stage = "reference-encode";
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, reference_blocks);
        witness_stage = "full-stored";
        try std.testing.expectEqualDeep(expected, actual);
        witness_stage = "reports";
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
        witness_stage = "literal-report";
        try std.testing.expect(!actual_renderer.fallbacks.literal_markup);
        var historical: usize = 0; var transliteration: usize = 0; var actions: usize = 0;
        for (blocks) |block| for (block.spans) |span| {
            if (span.kind == .link or span.kind == .external_link) actions += 1;
            if (std.mem.eql(u8, span.text, "中古")) {
                witness_stage = "historical-action";
                historical += 1;
                try std.testing.expect(span.kind == .external_link and !span.flags.italic);
                try std.testing.expectEqualStrings("https://zh.wikipedia.org/wiki/%E4%B8%AD%E5%8F%A4%E6%BC%A2%E8%AA%9E", span.target);
                try std.testing.expectEqualStrings("la", span.language);
                try std.testing.expectEqualStrings("tr Latn extiw", span.classes);
            }
            if (std.mem.eql(u8, span.text, " ha nom")) {
                witness_stage = "transliteration-style";
                transliteration += 1; try std.testing.expect(span.flags.italic and span.kind == .text);
                try std.testing.expectEqualStrings("la", span.language);
                try std.testing.expectEqualStrings("tr Latn", span.classes);
            }
        };
        witness_stage = "action-census";
        try std.testing.expectEqual(@as(usize, 3), actions);
        witness_stage = "historical-census";
        try std.testing.expectEqual(@as(usize, 1), historical);
        witness_stage = "transliteration-census";
        try std.testing.expectEqual(@as(usize, 1), transliteration);
        const codec = @import("blob_encoder").presentation_codec;
        witness_stage = "codec";
        const bytes = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    }
    witness_stage = "marked-range";
    const marked_at = std.mem.indexOf(u8, source, "中古]]") orelse return error.TestUnexpectedResult;
    const marked: MissingText = .{ .bytes = source, .unknown = true,
        .ranges = &.{.{ .start = @intCast(marked_at), .end = @intCast(marked_at + "中古".len), .occurrence = 9 }} };
    var marked_renderer: Renderer = .{ .a = a, .context = context, .inline_missing = marked };
    const borrowed = (try marked_renderer.manualConversion(source, prefix.len, .{})).body;
    try std.testing.expect(borrowed.ptr == source.ptr + prefix.len + 2);
    try std.testing.expectEqual(T.body.len, borrowed.len);
    const local = try missingSlice(a, marked, borrowed);
    // The conversion still borrows its body. A nonempty range ledger follows
    // missing_dependency.slice's owned-copy path while rebasing that metadata.
    try std.testing.expect(local.bytes.ptr != borrowed.ptr);
    try std.testing.expectEqualStrings(borrowed, local.bytes);
    try std.testing.expect(local.unknown and !local.lost_missing_range);
    try std.testing.expectEqual(@as(usize, 0), local.literal_curly_ranges.len);
    try std.testing.expectEqual(@as(usize, 0), local.generated_links.len);
    try std.testing.expect(local.generated_source == null);
    try std.testing.expectEqual(@as(usize, 1), local.ranges.len);
    try std.testing.expectEqual(marked_at - prefix.len - 2, @as(usize, local.ranges[0].start));
    try std.testing.expectEqual(marked_at + "中古".len - prefix.len - 2, @as(usize, local.ranges[0].end));
    try std.testing.expectEqual(@as(u32, 9), local.ranges[0].occurrence);
}

