            if (std.mem.eql(u8, span.text, " ha nom")) {
                transliteration += 1; try std.testing.expect(span.kind == .text and span.flags.italic);
                try std.testing.expectEqualStrings("la", span.language); try std.testing.expectEqualStrings("tr Latn", span.classes);
            }
            if (std.mem.indexOf(u8, span.text, "Wikibase sitelink snapshot missing entity=Q7850 site=zhwiki") != null) error_text += 1;
            if (span.kind == .link) {
                if (std.mem.eql(u8, span.target, "河南#漢語")) { henan += 1; try std.testing.expectEqualStrings("河南", span.text); }
                if (std.mem.eql(u8, span.target, "Hoƨnamƨ#壯語")) { old_spelling += 1; try std.testing.expectEqualStrings("Hoƨnamƨ", span.text); try std.testing.expectEqualStrings("za", span.language); }
                if (std.mem.eql(u8, span.target, "Hoznanz#壯語")) { synonym += 1; try std.testing.expectEqualStrings("Hoznanz", span.text); try std.testing.expectEqualStrings("za", span.language); }
            }
        };
        for ([_]usize{ historical, transliteration, error_text, henan, old_spelling, synonym }) |count| try std.testing.expectEqual(@as(usize, 1), count);
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    }
}

const MultilineLinkConversion4572Test = struct {
    const full = @embedFile("testdata/zh-parameter4572-expanded.wikitext");
    const reference = @embedFile("testdata/zh-parameter4572-reference.wikitext");
    const local = "<SPAN style=background:pink>02</SPAN>\n-{\n[[Appendix:部首索引/二|二]]\n<SPAN style=background:pink>03</SPAN>\n[[Appendix:部首索引/口|口]]\n}-\n";
    fn context(a: A, ns: *@import("namespace_registry").Registry) !Context {
        const NS = @import("namespace_registry");
        try ns.attachLanguageConversion(@embedFile("testdata/zh-gugli176/namespace-siteinfo.raw.json"));
        try ns.attachInterwikiMap(@embedFile("testdata/zh-parameter4572/interwiki-map.tsv"));
        const behavior = try a.create(NS.behavior_switches.Registry);
        behavior.* = try NS.behavior_switches.Registry.init(a, @embedFile("testdata/zh-parameter4572/behavior-switches.tsv"),
            ns.wiki, ns.dump_date, ns.content_language, ns.source_sha256);
        // This control qualifies source conversion under an explicit empty CSS
        // domain, not the genuine page's independently selected stylesheet.
        const styles = try a.create(table_style_profile.Profile);
        styles.* = try table_style_profile.parseAlloc(a, "");
        return .{ .namespace_catalog = ns, .behavior_switches = behavior, .content_conversion = true,
            .title = "Appendix:朝鮮語漢字", .table_styles = styles, .text_paint_styles = styles };
    }
    fn renderer(a: A, ns: *@import("namespace_registry").Registry, input: []const u8) !Renderer {
        const tracked = MissingText.untracked(input);
        const frame = try a.create(InlineSourceDomain);
        frame.* = .{ .source = input, .tracked = tracked, .parent = null };
        return .{ .a = a, .context = try context(a, ns), .inline_missing = tracked, .inline_source_domain = frame };
    }
    fn encode(a: A, renderer_value: *Renderer, blocks: []const Block) !@import("blob_encoder").presentation_types.Stored {
        const Section = struct { level: u8 = 2, title: []const u8 = "Chinese", blocks: []const Block };
        const sections = [_]Section{.{ .blocks = blocks }};
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeBuildAlloc(a, &[_]Span{}, &sections, presentation_types.Layout{},
            try renderer_value.finishReferences(), renderer_value.media.items);
        const stored = try codec.decodeAlloc(a, bytes, "Appendix:朝鮮語漢字", .language, .{ .code = "zh", .heading = "Chinese" });
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
        return stored;
    }
};

