test "multiline link conversion keeps source mutation metadata context and protected scope refusals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = MultilineLinkConversion4572Test; const NS = @import("namespace_registry");
    for (0..22) |mode| {
        var ns = try NS.Registry.init(a, @embedFile("testdata/zh-gugli176/namespace-registry.tsv")); defer ns.deinit();
        const source = try a.dupe(u8, T.local);
        var renderer = try T.renderer(a, &ns, source);
        const at = std.mem.indexOf(u8, source, "-{\n").?;
        const close = std.mem.indexOf(u8, source, "}-").?;
        try std.testing.expect(renderer.manualMultilineLinkedScope(source, at, close, .{}));
        const selected = try renderer.manualConversion(source, at, .{});
        try std.testing.expectEqualStrings(source[at + 2 .. close], selected.body);
        try std.testing.expect(selected.body.ptr == source[at + 2 ..].ptr and selected.end == close + 2);
        var style: Style = .{};
        switch (mode) {
            0 => renderer.inline_missing = null,
            1 => renderer.inline_missing.?.unknown = true,
            2 => renderer.inline_missing.?.lost_missing_range = true,
            3 => renderer.inline_missing.?.ranges = &.{.{ .start = 0, .end = @intCast(source.len), .occurrence = 1 }},
            4 => renderer.inline_missing.?.generated_source = source,
            5 => renderer.inline_source_domain = null,
            6 => @constCast(renderer.inline_source_domain.?).tracked = null,
            7 => @constCast(renderer.inline_source_domain.?).source = try a.dupe(u8, source),
            8 => @constCast(renderer.inline_source_domain.?).tracked.?.bytes = try a.dupe(u8, source),
            9 => renderer.context.content_conversion = false,
            10 => ns.manual_conversion_context = null,
            11 => ns.language_conversion = null,
            12 => style.code = true,
            13 => style.target = "foreign owner",
            14 => renderer.in_reference = true,
            15 => renderer.in_template_literal_scope = true,
            16 => renderer.inline_image_attribute = true,
            17 => renderer.body_link_target = "foreign owner",
            18 => renderer.block_formatting.code = true,
            19 => renderer.context.namespace_catalog = null,
            20 => {
                const parent = try a.create(InlineSourceDomain);
                parent.* = .{ .source = try a.dupe(u8, source), .tracked = MissingText.untracked(source), .parent = null };
                @constCast(renderer.inline_source_domain.?).parent = parent;
            },
            21 => source[std.mem.indexOf(u8, source, "[[").?] = '{',
            else => unreachable,
        }
        try std.testing.expect(!renderer.manualMultilineLinkedScope(source, at, close, style));
    }
    const rejected = [_][]const u8{
        "-{\n\n[[Appendix:二|二]]\n}-", "-{\n[[Appendix:二|二]]\n\n}-",
        "-{\n [[Appendix:二|二]]\n}-", "-{\n*[[Appendix:二|二]]\n}-",
        "-{\n[[Appendix:二|二]]\n==heading==\n}-", "-{\n[[Appendix:二|二]]\n{|\n|x\n|}\n}-",
        "-{\n[[File:Cat.png|thumb]]\n}-", "-{\n[[Category:Hidden]]\n}-",
        "-{\n[[Wikipedia:二|二]]\n}-", "-{\n[[Appendix:二|zh:二;zh-hans:two]]\n}-",
        "-{\n[[Appendix:二|二]]\n{{{missing}}}\n}-", "-{zh|\n[[Appendix:二|二]]\n}-",
        "-{\n[[Appendix:二|二]]\n<span>unclosed\n}-", "-{\n[[Appendix:二|二]]\n<nowiki>literal</nowiki>\n}-",
        "-{\n[[Appendix:二|二]]\n<script>opaque</script>\n}-", "-{\n[[Appendix:二|二]]\n<span title='bad>text</span>\n}-",
        "-{\n[[Appendix:二|二]]\n-{nested}-\n}-", "-{\n[[Appendix:二|二]]\n&quot;\n}-",
        "-{\n[[Appendix:二|二]]\r\n}-", "-{\n[[Appendix:二|\xff]]\n}-", "-{\n[[Appendix:二|\x00]]\n}-",
        "<span title='\n-{\n[[Appendix:二|二]]\n}-\n'>text</span>",
        "[[Appendix:Outer|\n-{\n[[Appendix:二|二]]\n}-\n]]",
        "prefix-{\n[[Appendix:二|二]]\n}-", "-{\n[[Appendix:二|二]]\n}-suffix",
    };
    var ns = try NS.Registry.init(a, @embedFile("testdata/zh-gugli176/namespace-registry.tsv")); defer ns.deinit();
    for (rejected) |literal| {
        const source = try a.dupe(u8, literal);
        var renderer = try T.renderer(a, &ns, source);
        const at = std.mem.indexOf(u8, source, "-{").?;
        const close = std.mem.indexOfPos(u8, source, at + 2, "}-").?;
        try std.testing.expect(!renderer.manualMultilineLinkedScope(source, at, close, .{}));
    }
}

test "retained piti rule free underline keeps inherited headword styles actions Stored and codec" {
