    const reference = "before [[Keep|kept]] " ++ head ++ "p<u>i</u>ti" ++ tail ++ " after [https://example.test outside]";
    const inherited: Style = .{ .bold = true, .italic = true, .strike = true, .language = "cho", .classes = "kept-parent",
        .foreground = "#123456", .foreground_set = true, .background = "#fedcba", .font_scale = 1.25,
        .font_scale_basis = .normal_body, .font_scale_set = true, .font_features = .seven_on, .font_family = .sans_serif,
        .captured_direction = "ltr", .role = .label, .explanation = "kept explanation", .explanation_set = true,
        .tooltip = "kept tooltip", .tooltip_set = true };
    var actual_renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior } };
    var reference_renderer: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior } };
    const actual_spans = try actual_renderer.parseSpans(source, inherited);
    const expected_spans = try reference_renderer.parseSpans(reference, inherited);
    const actual_inherited = try FormattingScopeTest.encode(a, &actual_renderer, &.{.{ .kind = .paragraph, .spans = actual_spans }});
    const expected_inherited = try FormattingScopeTest.encode(a, &reference_renderer, &.{.{ .kind = .paragraph, .spans = expected_spans }});
    try std.testing.expectEqualDeep(expected_inherited, actual_inherited);
    try std.testing.expectEqualDeep(reference_renderer.fallbacks, actual_renderer.fallbacks);
    var underlined: std.ArrayList(u8) = .empty;
