    for (actual_spans) |span| {
        if (span.flags.underline) {
            try underlined.appendSlice(a, span.text);
            try std.testing.expect(span.flags.bold and span.flags.italic and span.flags.strike);
            try std.testing.expectEqualStrings("cho", span.language);
            try std.testing.expectEqualStrings("#123456", span.foreground.?);
            try std.testing.expectEqualStrings("#fedcba", span.background.?);
            try std.testing.expectEqual(@as(?f32, 1.25), span.font_scale);
            try std.testing.expectEqual(FontScaleBasis.normal_body, span.font_scale_basis);
            try std.testing.expectEqual(presentation_types.FontFeaturePolicy.seven_on, span.font_features.?);
            try std.testing.expectEqualDeep(@as(?presentation_types.ContainerFontFamily, .sans_serif), span.font_family);
            try std.testing.expectEqualStrings("kept tooltip", span.tooltip.?);
            try std.testing.expectEqualStrings("kept explanation", span.explanation);
            try std.testing.expect(span.kind == .text and span.target.len == 0);
        }
        if (span.kind == .link or span.kind == .external_link) actions += 1;
    }
    try std.testing.expectEqualStrings("i", underlined.items);
    try std.testing.expectEqual(@as(usize, 2), actions);
    // A body-level reference exercises the ordinary structural/Stored adapter,
    // keeping complete surrounding actions rather than a flattened text oracle.
    var body_actual: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior } };
    var body_reference: Renderer = .{ .a = a, .context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior } };
    const actual = try FormattingScopeTest.encode(a, &body_actual, try body_actual.renderBody(source));
    const expected = try FormattingScopeTest.encode(a, &body_reference, try body_reference.renderBody(reference));
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualDeep(body_reference.fallbacks, body_actual.fallbacks);
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeAlloc(a, actual);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
    const decoded = try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .code = "en", .heading = "English" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));
}

