test "recursive conversion frames retain borrowed extents child order and outer close" {
    const source = "prefix -{a-{b-{c}-d}-e-{f}-g}- suffix -{later}-";
    const opening = std.mem.indexOf(u8, source, "-{").?;
    var frames = Renderer.ManualConversionFrames.init(source, opening);
    const expected = [_][]const u8{ "c", "b-{c}-d", "f", "a-{b-{c}-d}-e-{f}-g" };
    for (expected, 0..) |body, index| {
        const frame = frames.next() orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(body, frame.body(source));
        try std.testing.expect(frame.body(source).ptr == source[frame.opening + 2..].ptr);
        try std.testing.expectEqual(index == expected.len - 1, frame.parent_opening == null);
        if (frame.parent_opening) |parent_opening| try std.testing.expect(parent_opening < frame.opening);
    }
    try std.testing.expect(frames.next() == null and frames.count == 0 and !frames.overflow);
    const root = Renderer.manualConversionExtent(source, opening) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(expected[3], root.body(source));
    try std.testing.expect(root.closing > std.mem.indexOfPos(u8, source, opening + 2, "}-").?);
    try std.testing.expectEqualStrings(" suffix -{later}-", source[root.closing + 2..]);
    try std.testing.expect(Renderer.manualConversionExtent(source, 0) == null);
    try std.testing.expect(Renderer.manualConversionExtent(source, source.len + 1) == null);
    try std.testing.expect(Renderer.manualConversionExtent("-{outer-{child}-", 0) == null);
    try std.testing.expect(Renderer.manualConversionExtent("-{outer", 0) == null);
    // The existing maximum counts the outer frame. No new numeric limit is
    // introduced, and a completed sibling never exhausts cumulative storage.
    var nested: [max_depth * 4 + 1]u8 = undefined;
    for (0..max_depth) |index| {
        @memcpy(nested[index * 2..][0..2], "-{");
        @memcpy(nested[max_depth * 2 + 1 + index * 2..][0..2], "}-");
    }
    nested[max_depth * 2] = 'x';
    try std.testing.expect(Renderer.manualConversionExtent(&nested, 0) != null);
    var too_deep: [nested.len + 4]u8 = undefined;
    @memcpy(too_deep[0..2], "-{");
    @memcpy(too_deep[2..][0..nested.len], &nested);
    @memcpy(too_deep[too_deep.len - 2..], "}-");
    var excessive = Renderer.ManualConversionFrames.init(&too_deep, 0);
    while (excessive.next()) |_| {}
    try std.testing.expect(excessive.overflow);
}

test "retained recursive conversion frames preserve complete actions styles Missing Stored and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = T.profile();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior };
    const prefix = "before [[Before|before]] ";
    const suffix = " after [[After#part|after]]\n\n" ++ T.marked;
    const source = try std.mem.concat(a, u8, &.{ prefix, T.body, suffix });
    const reference = try std.mem.concat(a, u8, &.{ prefix, "-{", T.literal, "}-", suffix });
    const tracked = try T.tracked(a, source);
    const expected_tracked = try T.tracked(a, reference);
    const frame = Renderer.manualConversionExtent(source, prefix.len) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(prefix.len + T.body.len, frame.closing + 2);
    try std.testing.expectEqualStrings(T.body[2 .. T.body.len - 2], frame.body(source));
    var renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
    var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = expected_tracked };
    const actual = try FormattingScopeTest.encode(a, &renderer, try renderer.renderBodyWithMissing(tracked));
    const expected = try FormattingScopeTest.encode(a, &expected_renderer, try expected_renderer.renderBodyWithMissing(expected_tracked));
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualDeep(expected_renderer.fallbacks, renderer.fallbacks);
    try std.testing.expect(renderer.body_missing.?.unknown);
    try std.testing.expectEqualDeep(tracked.ranges, renderer.body_missing.?.ranges);
    const codec = @import("blob_encoder").presentation_codec;
    const encoded = try codec.encodeAlloc(a, actual);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), encoded);
    try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, encoded, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    // A structurally complete extent grants no mutation, title, alternative,
    // generated, Missing-overlap, or protected-context permission.
    for ([_][]const u8{ "-{[[Target|-{}-]]}-", "-{<span>-{}-</span>}-", "-{R|[[Target|-{plain}-]]}-", "-{[[Target|-{T|plain}-]]}-", "-{[[Target|-{zh-hans:a;zh-hant:b}-]]}-" }) |invalid| {
        try std.testing.expect(Renderer.manualConversionExtent(invalid, 0) != null);
        var refused: Renderer = .{ .a = a, .context = context, .inline_missing = MissingText.untracked(invalid) };
        try std.testing.expectError(error.UncompiledPresentation, refused.manualConversion(invalid, 0, .{}));
    }
    for (0..3) |mode| {
        var tainted: MissingText = .{ .bytes = T.body, .unknown = true };
        switch (mode) {
            0 => tainted.lost_missing_range = true,
            1 => tainted.generated_source = T.body,
            2 => tainted.ranges = &.{.{ .start = 2, .end = 3, .occurrence = 1 }},
            else => unreachable,
        }
