// Called only by the two existing regression controls after setup fails.
// Scalar observations locate the failed ownership fence; they issue no proof.
fn rowCopySetupDiagnostic193(renderer: *const Renderer, copied: MissingText, copies: usize, mode: usize, test_case: []const u8) void {
    const domain = renderer.pageStyleDomain();
    const original = renderer.body_missing;
    const anchor = renderer.pageStyleCopiedAnchor(copied, copied.bytes);
    const owner_matches = if (domain) |known| if (original) |tracked|
        tracked.bytes.ptr == known.owner.ptr and tracked.bytes.len == known.owner.len else false else false;
    const original_clean = if (original) |tracked| Renderer.wikiClassCleanText(tracked) and tracked.bytes.len != 0 else false;
    const anchor_contained = if (original) |tracked| if (anchor) |mapped| Renderer.wikiClassContains(tracked.bytes, mapped) else false else false;
    std.debug.print("ROW_COPY_SETUP193 test={s} mode={d} stage=after_register_copies copied_bytes={d} copies={d} aliases={d} source_binding={any} copied_clean={any} domain={any} proof={any} original={any} owner_matches={any} original_clean_nonempty={any} anchor={any} anchor_contained={any}\n", .{
        test_case, mode, copied.bytes.len, copies, renderer.heading_source_aliases.items.len,
        renderer.source_element_binding != null, Renderer.wikiClassCleanText(copied), domain != null,
        renderer.rowColorSourceProof() != null, original != null, owner_matches, original_clean, anchor != null, anchor_contained,
    });
}


