test "pinned recursive formatting frames and repeated plain labels preserve borrowed body actions Missing and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = RecursiveHoznamz124Test; const M = SourceRecursiveManualTest; const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
