    const context: Context = .{ .title = "Hoznamz", .namespace_catalog = &ns, .behavior_switches = &behavior };
    const prefix = "before [[Before|before]] ";
    const suffix = " after [[After#part|after]]\n\n" ++ M.marked;
    const source = prefix ++ T.body ++ suffix;
    const reference = prefix ++ T.reference ++ suffix;
    for ([_]bool{ false, true }) |unknown| {
        var tracked = try M.tracked(a, source); tracked.unknown = unknown;
        var reference_tracked = try M.tracked(a, reference); reference_tracked.unknown = unknown;
        var proof: Renderer = .{ .a = a, .context = context, .inline_missing = tracked };
        const operation = (try proof.sourceRecursiveRuleFreeLinkLabels(source, prefix.len, .{})) orelse return error.TestUnexpectedResult;
        try std.testing.expect(operation.body.ptr == source.ptr + prefix.len + 2);
        try std.testing.expectEqualStrings(T.body[2..T.body.len - 2], operation.body);
        try std.testing.expectEqual(prefix.len + T.body.len, operation.end);
        try std.testing.expectEqual(unknown, (try missingSlice(a, tracked, operation.body)).unknown);
        try std.testing.expectEqualDeep(tracked, proof.inline_missing.?);
        var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
        var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = reference_tracked };
        const blocks = try actual_renderer.renderBodyWithMissing(tracked);
        const reference_blocks = try expected_renderer.renderBodyWithMissing(reference_tracked);
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, reference_blocks);
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
        try std.testing.expect(!actual_renderer.fallbacks.literal_markup);
        try std.testing.expectEqual(unknown, actual_renderer.body_missing.?.unknown);
        try std.testing.expectEqualDeep(tracked.ranges, actual_renderer.body_missing.?.ranges);
        var old_spelling: usize = 0; var actions: usize = 0; var missing: usize = 0;
        for (blocks) |block| for (block.spans) |span| {
            try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
            if (span.kind == .link or span.kind == .external_link) actions += 1;
            if (std.mem.eql(u8, span.target, "Hoƨnamƨ#壯語")) {
                old_spelling += 1;
                try std.testing.expectEqualStrings("Hoƨnamƨ", span.text);
                try std.testing.expectEqualStrings("za", span.language);
                try std.testing.expect(span.kind == .link and span.flags.bold and !span.flags.italic);
                try std.testing.expect(std.mem.indexOf(u8, span.classes, "1957_spelling-form-of") != null);
            }
            if (std.mem.eql(u8, span.target, "Template:R:hi:Rajpal")) missing += 1;
        };
        try std.testing.expectEqual(@as(usize, 1), old_spelling);
        try std.testing.expectEqual(@as(usize, 4), actions);
        try std.testing.expectEqual(@as(usize, 1), missing);
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), bytes);
        const decoded = try codec.decodeAlloc(a, bytes, "formatting scope", .language, .{ .heading = "English", .code = "en" });
        try std.testing.expectEqualDeep(actual, decoded);
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));

        const link_source: MissingText = .{ .bytes = T.link, .unknown = unknown };
        var links: ir.InlineIterator = .{ .input = T.link, .renderer_boundaries = true };
        const node = links.next() orelse return error.TestUnexpectedResult;
        const label = try missingSlice(a, link_source, node.text);
        var label_renderer: Renderer = .{ .a = a, .context = context, .inline_missing = link_source };
        const selected = (try label_renderer.sourceSemanticChoiceWikiLabel(T.link, 0, T.link.len, node.target, label, .{})) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("Hoƨnamƨ", selected.bytes);
        try std.testing.expect(selected.bytes.ptr == node.text.ptr + 4);
        try std.testing.expectEqual(unknown, selected.unknown);
        try std.testing.expectEqualDeep(link_source, label_renderer.inline_missing.?);
        try std.testing.expectEqualStrings(":Hoƨnamƨ#壯語", node.target);
    }
}

