test "native linked Ruby direct parent survives complete document rendering without an observation Book" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const source = "before [[Target|<ruby>base<rp>(</rp><rt>reading</rt><rp>)</rp></ruby>]] after";
