    var expected_profile = try table_style_profile.parseForTargetAlloc(a, visible, .screen); defer expected_profile.deinit();
    const document = @import("presentation_document.zig");
    const observation = try document.observePreScopesWithTextPaintAndMissingAlloc(a, "entry", MissingText.untracked(source), .{}, null, null, null, .{}, null, &actual_profile);
    defer observation.deinitTextAncestry(a);
