        try std.testing.expectEqualStrings("reading", segment.annotations[0].spans[0].text);
        try std.testing.expectApproxEqAbs(@as(f32, 0.6), segment.annotations[0].spans[0].font_scale.?, 0.00001);
        const leaves = try RubyProducerTest.leaves(a, &[_]Span{span});
        try std.testing.expectEqual(@as(usize, 4), leaves.len);
        for (leaves) |leaf| {
            try std.testing.expectEqual(ir.InlineKind.link, leaf.kind);
            try std.testing.expectEqualStrings("Target", leaf.target);
        }
    };
    try std.testing.expectEqual(@as(usize, 1), found);
    try std.testing.expect(!actual.fallbacks.any());
    try std.testing.expectEqualDeep(expected.fallbacks, actual.fallbacks);
    try std.testing.expectEqualDeep(try FormattingScopeTest.encode(a, &expected, expected_blocks), try FormattingScopeTest.encode(a, &actual, blocks));
    try std.testing.expect(actual.context.figure_sizing == null and actual.bounded_text_class_scope == null and actual.source_element_binding == null);
