        var refused: Renderer = .{ .a = a, .context = .{ .title = "entry", .table_styles = &refused_profile } };
        try std.testing.expectError(error.UncompiledPresentation, refused.renderBody(source));
    }
}

test "native Ruby parent receipt refuses foreign copied partial tainted and expired label operations" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const source = "[[Target|<ruby>x<rt>r</rt></ruby>]]";
    var tokens: ir.InlineIterator = .{ .input = source, .renderer_boundaries = true };
    const token = tokens.next() orelse return error.TestUnexpectedResult;
    const label = MissingText.untracked(token.text);
    var outer: InlineSourceDomain = .{ .source = source, .tracked = MissingText.untracked(source), .parent = null };
    var anchor: table_style_profile.TextElement = .{ .tag = "a" };
    const style: Style = .{ .kind = .link, .target = "Target", .text_element = &anchor };
    var issuer: Renderer = .{ .a = a, .context = .{}, .inline_source_domain = &outer };
    const receipt = issuer.nativeRubyLabelParent(source, label, .{}, style) orelse return error.TestUnexpectedResult;
    const tag = syntax.tagAt(label.bytes, 0) orelse return error.TestUnexpectedResult;
    for (0..20) |mode| {
        var child: InlineSourceDomain = .{ .source = label.bytes, .tracked = label, .parent = &outer };
        var renderer: Renderer = .{ .a = a, .context = .{}, .inline_source_domain = &child, .inline_missing = label,
            .explicit_wiki_label = .{ .kind = .link, .target = style.target, .ordinary_label = label.bytes, .native_parent = receipt } };
        var current_style = style;
        const actual = try renderer.textElement(tag, &anchor, "");
        var element = actual.*;
        var other: table_style_profile.TextElement = .{ .tag = "ruby" };
        var literal_table: Renderer.InlineTableBoundaries = .{};
        switch (mode) {
            0 => {},
            1 => renderer.explicit_wiki_label = null,
            2 => renderer.explicit_wiki_label.?.native_parent = null,
            3 => renderer.explicit_wiki_label.?.native_parent.?.label.bytes = try a.dupe(u8, label.bytes),
            4 => { const foreign = try a.create(table_style_profile.TextElement); foreign.* = anchor;
                try std.testing.expect(foreign != &anchor); element.parent = foreign; },
            5 => child.parent = null,
            6 => renderer.inline_missing.?.unknown = true,
            7 => renderer.inline_missing.?.lost_missing_range = true,
            8 => renderer.inline_missing.?.bytes = label.bytes[0 .. label.bytes.len - 1],
            9 => current_style.target = try a.dupe(u8, style.target),
            10 => element.source_key += 1,
            11 => element.alternative_ancestry = &other,
            12 => renderer.in_template_literal_scope = true,
            13 => renderer.inline_missing.?.ranges = &.{.{ .start = 0, .end = 1, .occurrence = 1 }},
            14 => current_style.self_link_target = style.target,
            15 => current_style.kind = .external_link,
            16 => renderer.typed_table_depth = 1,
            17 => renderer.inline_table_boundaries = &literal_table,
            18 => renderer.figure_caption_depth = 1,
            19 => renderer.inline_image_attribute = true,
            else => unreachable,
        }
        try std.testing.expectEqual(mode == 0, renderer.nativeRubyDirectParent(tag, current_style, &element) != null);
        if (mode == 0) {
            // typedRuby rechecks after htmlInlineStyle has materialized this
            // same Ruby node; the immediate parent remains the issued anchor.
            current_style.text_element = &element;
            try std.testing.expect(renderer.nativeRubyDirectParent(tag, current_style, &element) == &anchor);
        }
        try std.testing.expect(element.page_style_root == null and element.complete_ancestor_classes == null and !element.ancestry_complete);
    }
    var tainted = label; tainted.unknown = true;
    try std.testing.expect(issuer.nativeRubyLabelParent(source, tainted, .{}, style) == null);
    try std.testing.expect(issuer.nativeRubyLabelParent(source, MissingText.untracked(try a.dupe(u8, label.bytes)), .{}, style) == null);
    for ([_]Style{
        .{ .kind = .link, .target = "Outer" },
        .{ .kind = .external_link, .target = "https://example.test" },
        .{ .self_link_target = "entry" },
    }) |inherited| try std.testing.expect(issuer.nativeRubyLabelParent(source, label, inherited, style) == null);
    for ([_][]const u8{
        "[[Target|<ruby><a href='/wiki/Other'>x</a><rt>r</rt></ruby>]]",
        "[[Target|<ruby>[[Other|x]]<rt>r</rt></ruby>]]",
        "[[Target|<ruby><nowiki>x</nowiki><rt>r</rt></ruby>]]",
    }) |nested| {
        var nested_tokens: ir.InlineIterator = .{ .input = nested, .renderer_boundaries = true };
        const nested_token = nested_tokens.next() orelse return error.TestUnexpectedResult;
        var frame: InlineSourceDomain = .{ .source = nested, .tracked = MissingText.untracked(nested), .parent = null };
        issuer.inline_source_domain = &frame;
        try std.testing.expect(issuer.nativeRubyLabelParent(nested, MissingText.untracked(nested_token.text), .{}, style) == null);
    }
}

test "colon in source-owned invalid brace title retains full literal list body actions and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const rejected = "[[{| class=\"wikitable\" border=\"1\" style=\"text-align: center\"]]";
    for ([_]bool{ false, true }) |unknown| {
        var witness_stage: []const u8 = "render_actual";
        var witness_lists: u8 = 0;
        var witness_literal: u8 = 0;
        var witness_actions: u8 = 0;
        errdefer std.debug.print("COLON_BRACE06 stage={s} unknown={any} lists={x} literal={x} actions={x}\n",
            .{ witness_stage, unknown, witness_lists, witness_literal, witness_actions });
        const source = "* " ++ rejected ++ "\n* '''bold''' [[After#Part|after]] [https://example.test/ outside]\n";
        const reference = if (unknown)
            "* <nowiki>" ++ rejected ++ "</nowiki>\n* '''bold''' [[After#Part|after]] [https://example.test/ outside]\n"
        else try std.mem.concat(a, u8, &.{ "* <nowiki>[[</nowiki>{<nowiki>|</nowiki>",
            rejected[4 .. rejected.len - 2], "<nowiki>]]</nowiki>\n* '''bold''' [[After#Part|after]] [https://example.test/ outside]\n" });
        const original = try a.dupe(u8, source);
        var actual: Renderer = .{ .a = a, .context = .{} };
        var expected: Renderer = .{ .a = a, .context = .{} };
        const tracked: MissingText = .{ .bytes = source, .unknown = unknown };
        const blocks = try actual.renderBodyWithMissing(tracked);
        witness_stage = "render_reference";
        const reference_blocks = try expected.renderBody(reference);
        witness_stage = "source_and_report";
        try std.testing.expectEqualStrings(original, source);
        try std.testing.expectEqual(unknown, tracked.unknown);
        try std.testing.expectEqual(@as(usize, 2), blocks.len);
        try std.testing.expect(actual.fallbacks.literal_markup);
        // Rejected source markup is diagnosed; authored NOWIKI is protected
        // literal content. Preserve this one expected classification difference
        // while comparing every other report field and the entire stored body.
        try std.testing.expect(!expected.fallbacks.literal_markup);
        var expected_report = expected.fallbacks;
        expected_report.literal_markup = true;
        try std.testing.expectEqualDeep(expected_report, actual.fallbacks);
        witness_stage = "list_shape";
        witness_lists = 7;
        for (blocks) |block| {
            if (block.kind != .list_item) witness_lists &= ~@as(u8, 1);
            if (block.table != null or block.container != null or block.figure != null or block.flow != null) witness_lists &= ~@as(u8, 2);
            for (block.spans) |span| if (span.generated_diagnostic) { witness_lists &= ~@as(u8, 4); };
        }
        for (blocks) |block| {
            try std.testing.expect(block.kind == .list_item and block.table == null and block.container == null and block.figure == null and block.flow == null);
            try std.testing.expectEqualStrings("*", block.list_path);
            for (block.spans) |span| try std.testing.expect(!span.generated_diagnostic);
        }
        witness_stage = "literal_text";
        try std.testing.expectEqualStrings(rejected, try flattened(a, blocks[0].spans));
        witness_stage = "literal_shape";
        // Known input takes the existing isolated-curly path: only the raw
        // brackets and separator are protected; child text is parsed normally.
        // Unknown input takes the source-local whole-token literal path.
        const literal_parts: []const []const u8 = if (unknown) &.{rejected} else
            &.{ "[[", "{", "|", rejected[4 .. rejected.len - 2], "]]" };
        try std.testing.expectEqual(literal_parts.len, blocks[0].spans.len);
        // Independent literal boundaries preserve the maintained known-input
        // five-span shape; unknown input remains one whole protected token.
        try std.testing.expectEqual(literal_parts.len, reference_blocks[0].spans.len);
        for (reference_blocks[0].spans, literal_parts) |span, part|
            try std.testing.expectEqualStrings(part, span.text);
        witness_literal = 7;
        for (blocks[0].spans, 0..) |span, part_index| {
            const expected_provenance: Provenance = if (unknown or part_index == 0 or part_index == 2 or part_index == 4)
                .protected_literal else .parsed;
            if (span.kind != .text) witness_literal &= ~@as(u8, 1);
            if (span.target.len != 0 or span.image != null) witness_literal &= ~@as(u8, 2);
            if (span.provenance != expected_provenance) witness_literal &= ~@as(u8, 4);
        }
        for (blocks[0].spans, literal_parts, 0..) |span, part, part_index| {
            const expected_provenance: Provenance = if (unknown or part_index == 0 or part_index == 2 or part_index == 4)
                .protected_literal else .parsed;
            try std.testing.expect(span.kind == .text and span.target.len == 0 and span.image == null);
            try std.testing.expectEqualStrings(part, span.text);
            try std.testing.expectEqual(expected_provenance, span.provenance);
        }
        witness_stage = "following_text";
        try std.testing.expectEqualStrings("bold after outside", try flattened(a, blocks[1].spans));
        witness_stage = "action_census";
        var bold = false; var after = false; var outside = false;
        for (blocks[1].spans) |span| {
            if (std.mem.eql(u8, span.text, "bold")) bold = span.flags.bold;
            if (span.kind == .link and std.mem.eql(u8, span.target, "After#Part") and std.mem.eql(u8, span.text, "after")) after = true;
            if (span.kind == .external_link and std.mem.eql(u8, span.target, "https://example.test/") and std.mem.eql(u8, span.text, "outside")) outside = true;
        }
        witness_actions = @as(u8, @intFromBool(bold)) | (@as(u8, @intFromBool(after)) << 1) | (@as(u8, @intFromBool(outside)) << 2);
        try std.testing.expect(bold and after and outside);
        witness_stage = "stored_parity";
        const actual_stored = try FormattingScopeTest.encode(a, &actual, blocks);
        const reference_stored = try FormattingScopeTest.encode(a, &expected, reference_blocks);
        try std.testing.expectEqualDeep(reference_stored, actual_stored);
        witness_stage = "codec_parity";
        const codec = @import("blob_encoder").presentation_codec;
        const bytes = try codec.encodeAlloc(a, actual_stored);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, reference_stored), bytes);
        const decoded = try codec.decodeAlloc(a, bytes, actual_stored.entry.title, .language,
            .{ .heading = actual_stored.entry.language.?, .code = actual_stored.entry.language_code });
        try std.testing.expectEqualDeep(actual_stored, decoded);
        try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, decoded));
    }
}

test "colon invalid brace literal recovery keeps protocol magic source and local range refusals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
