        try std.testing.expectEqual(@as(usize, 0), refused.spans.items.len);
        try std.testing.expect(!refused.fallbacks.literal_markup);
    }
    const source = "prefix [[{| text-align: center]] suffix";
    const at = std.mem.indexOf(u8, source, "[[").?;
    const raw = source[at..][0.."[[{| text-align: center]]".len];
    const domain: InlineSourceDomain = .{ .source = source, .parent = null };
    const outside = [_]missing_dependency.Range{.{ .start = 0, .end = 1, .occurrence = 1 }};
    var local: Renderer = .{ .a = a, .context = .{}, .inline_source_domain = &domain };
    try std.testing.expect(try local.preservePlainInvalidBraceLink(.{ .bytes = source, .unknown = true, .ranges = &outside }, raw, "", .{}));
    try std.testing.expectEqualStrings(raw, try flattened(a, local.spans.items));
    const overlap = [_]missing_dependency.Range{.{ .start = @intCast(at), .end = @intCast(at + 1), .occurrence = 1 }};
    const literal = [_]missing_dependency.LiteralRange{.{ .start = @intCast(at + 2), .end = @intCast(at + 3) }};
    const foreign = try a.dupe(u8, raw);
    const parent: InlineSourceDomain = .{ .source = source, .parent = null };
    const nested: InlineSourceDomain = .{ .source = source, .parent = &parent };
    for (0..13) |mode| {
        var tracked: MissingText = .{ .bytes = source, .unknown = true };
        var style: Style = .{};
        var refused: Renderer = .{ .a = a, .context = .{}, .inline_source_domain = &domain };
        var token: []const u8 = raw;
        var trail: []const u8 = "";
        switch (mode) {
            0 => tracked.ranges = &overlap,
            1 => tracked.literal_curly_ranges = &literal,
            2 => tracked.lost_missing_range = true,
            3 => tracked.generated_source = source,
            4 => token = foreign,
            5 => refused.inline_source_domain = &nested,
            6 => { style.kind = .link; style.target = "Owner"; },
            7 => style.code = true,
            8 => trail = "suffix",
            9 => style.provenance = .protected_literal,
            10 => refused.in_template_literal_scope = true,
            11 => refused.in_reference = true,
            12 => refused.inline_source_domain = null,
            else => unreachable,
        }
        try std.testing.expect(!try refused.preservePlainInvalidBraceLink(tracked, token, trail, style));
        try std.testing.expectEqual(@as(usize, 0), refused.spans.items.len);
        try std.testing.expect(!refused.fallbacks.literal_markup);
    }
}

