test "ordinary constructed footer crosses real finishCell structural Missing lifetime with exact body actions paint and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = ConstructedStructuralCell04Test;
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    var styles = try table_style_profile.parseForTargetAlloc(a, F.F.css, .screen); defer styles.deinit();
    var expected = try F.prepared(a, &ns, &styles);
    const expected_blocks = try expected.renderer.renderBody(expected.body);
    try std.testing.expectEqual(@as(usize, 2), expected_blocks.len);
    var actual = try F.prepared(a, &ns, &styles);
    const owned = actual.renderer.table_viewport_cell_source.?;
    actual.renderer.table_viewport_cell_source = null;
    actual.renderer.inline_missing = null;
    actual.renderer.body_missing = MissingText.untracked(actual.body);
    // parseTable owns this depth throughout normal line copying and finishCell.
    // Keep that genuine recorder premise scoped to this controlled cell test.
    try std.testing.expect(actual.renderer.typed_table_depth == 0 and actual.renderer.heading_source == null);
    actual.renderer.typed_table_depth = 1;
    defer actual.renderer.typed_table_depth = 0;
    try std.testing.expect(actual.renderer.tableDirectionOriginal(actual.body[1..]) != null);
    var buffer: MissingBuffer = .empty; defer buffer.deinit(a);
    var copies: std.ArrayList(HeadingSourceCopy) = .empty; defer copies.deinit(a);
    try std.testing.expect(actual.body.len > 1 and actual.body[0] == '\n');
    var cursor: usize = 1;
    while (cursor < actual.body.len) {
        const end = std.mem.indexOfScalarPos(u8, actual.body, cursor, '\n') orelse actual.body.len;
        // The normal empty cell buffer inserts LF only BETWEEN copied lines.
        if (buffer.items.len != 0) try buffer.append(a, '\n');
        try actual.renderer.appendWikiTableFosteredCopy(&buffer, &copies, MissingText.untracked(actual.body), actual.body[cursor..end]);
        cursor = if (end < actual.body.len) end + 1 else end;
    }
    try std.testing.expectEqual(actual.body.len - 1, buffer.items.len);
    try std.testing.expect(copies.items.len >= 2 and copies.items[0].start == 0 and copies.items[0].original.ptr == actual.body[1..].ptr);
    var current: ?Cell = .{ .spans = &.{}, .colspan = 11, .table_viewport_source = owned,
        .style = .{ .line_height = try F.policy() } };
    var completed: std.ArrayList(Cell) = .empty;
    // The structural caller deliberately has no inline parser frame. The real
    // finishCell owns buffer/copies and must revoke their lease on return.
    try std.testing.expect(actual.renderer.inline_missing == null and owned.structural_source == null);
    try actual.renderer.finishCell(&completed, &buffer, &copies, &current, .{},
        .{ .font_scale = 1, .font_scale_basis = .normal_body });
    try std.testing.expect(current == null and completed.items.len == 1);
    try std.testing.expectEqual(@as(u16, 11), completed.items[0].colspan);
    try std.testing.expect(actual.renderer.inline_missing == null and actual.renderer.table_viewport_cell_source == null);
    try std.testing.expect(completed.items[0].table_viewport_source == null);
    const blocks = completed.items[0].blocks orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(expected_blocks, blocks);
    const heading = blocks[0].container orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(presentation_types.FigureClear.both, heading.style.clear.?);
    try std.testing.expectEqualStrings("#efefef", heading.style.background.?.rgb);
    try std.testing.expectEqual(@as(?f32, 1), heading.style.owner_font_scale);
    const footer = blocks[1].container orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 5), footer.blocks.len);
    for (footer.blocks, actual.bound.links) |child, action| {
        const box = child.container orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(presentation_types.TableFloatSide.left, box.style.float_side.?);
        const span = box.blocks[0].spans[0];
        try std.testing.expectEqualDeep(action.paint.?, span.link_paint.?);
        try std.testing.expectEqual(@as(?f32, 1), span.font_scale);
        try std.testing.expectEqual(FontScaleBasis.normal_body, span.font_scale_basis);
    }
    try std.testing.expect(!actual.renderer.fallbacks.unsupported_element);
    const codec = @import("blob_encoder").presentation_codec;
    const Section = struct { level: u8 = 2, title: []const u8 = "Footer", blocks: []const Block };
    const bytes = try codec.encodeBuildAlloc(a, &[_]Span{}, &[_]Section{.{ .blocks = blocks }}, presentation_types.Layout{}, &.{}, &.{});
    const reference = try codec.encodeBuildAlloc(a, &[_]Span{}, &[_]Section{.{ .blocks = expected_blocks }}, presentation_types.Layout{}, &.{}, &.{});
    try std.testing.expectEqualSlices(u8, reference, bytes);
    const stored = try codec.decodeAlloc(a, bytes, "Footer", .language, .{ .code = "de", .heading = "Footer" });
    try std.testing.expectEqualSlices(u8, bytes, try codec.encodeAlloc(a, stored));
}

test "constructed structural cell lease refuses arbitrary bodies revoked copies Missing and stale inline frames" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = ConstructedStructuralCell04Test;
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    var styles = try table_style_profile.parseForTargetAlloc(a, F.F.css, .screen); defer styles.deinit();
    for (0..23) |mode| {
        var value = try F.prepared(a, &ns, &styles);
        const copied = try a.dupe(u8, value.body[1..]);
        var records = [_]HeadingSourceCopy{.{ .start = 0, .original = value.body[1..] }};
        try value.renderer.registerHeadingSourceCopies(copied, &records);
        value.renderer.inline_missing = null;
        value.renderer.body_missing = MissingText.untracked(copied);
        value.renderer.table_viewport_cell_source.?.structural_source = .{ .cell_source = value.body, .tracked = MissingText.untracked(copied), .copies = &records };
        const tag = syntax.tagAt(copied, 0) orelse return error.TestUnexpectedResult;
        try std.testing.expect(value.renderer.tableConstructedBoxForTag(tag) != null);
        const second_at = std.mem.indexOfPos(u8, copied, tag.end, "<div").?;
        const second = syntax.tagAt(copied, second_at).?;
        const second_pair = syntax.matchingTag(copied, second).?;
        const child_body = copied[second.end..second_pair.inner_end];
        const span_at = std.mem.indexOf(u8, child_body, "<span").?;
        const span_tag = syntax.tagAt(child_body, span_at).?;
        value.renderer.body_missing = MissingText.untracked(child_body);
        try std.testing.expect(value.renderer.tableConstructedBoxForTag(span_tag) != null);
        value.renderer.body_missing = MissingText.untracked(copied);
        var selected_tag = tag;
        switch (mode) {
            0 => value.renderer.table_viewport_cell_source.?.structural_source = null,
            1 => value.renderer.body_missing = null,
            2 => value.renderer.body_missing.?.bytes = try a.dupe(u8, copied),
            3 => value.renderer.table_viewport_cell_source.?.structural_source.?.tracked.bytes = try a.dupe(u8, copied),
            4 => value.renderer.table_viewport_cell_source.?.source = try a.dupe(u8, value.body),
            5 => value.renderer.body_missing.?.unknown = true,
            6 => value.renderer.table_viewport_cell_source.?.structural_source.?.tracked.lost_missing_range = true,
            7 => value.renderer.body_missing.?.ranges = &.{.{ .start = 0, .end = 1, .occurrence = 1 }},
            8 => value.renderer.body_missing.?.generated_source = copied,
            9 => value.renderer.table_viewport_cell_source.?.structural_source.?.copies = &.{},
            10 => records[0].original = try a.dupe(u8, value.body[1..]),
            11 => records[0].start = 1,
            12 => copied[std.mem.indexOf(u8, copied, "#efefef").? + 1] = 'a',
            13 => value.renderer.inline_missing = MissingText.untracked(try a.dupe(u8, copied)),
            14 => value.renderer.inline_missing = .{ .bytes = copied, .unknown = true },
            15 => value.renderer.in_template_literal_scope = true,
            16 => value.renderer.table_viewport_cell_source.?.closed_focus = false,
            17 => value.renderer.table_viewport_cell_source.?.constructed_font_source.?.snapshot = value.renderer.table_viewport_cell_source.?.constructed_font_source.?.source,
            18 => {
                // A mutation outside the current child must revoke the complete
                // lease too, even while its own SPAN opener remains unchanged.
                value.renderer.body_missing = MissingText.untracked(child_body);
                selected_tag = span_tag; copied[1] = 'x';
            },
            19 => {
                value.renderer.body_missing = MissingText.untracked(try a.dupe(u8, child_body));
                selected_tag = span_tag;
            },
            20 => value.renderer.table_viewport_cell_source.?.source = value.body[1..],
            21 => value.renderer.table_viewport_cell_source.?.structural_source.?.cell_source = try a.dupe(u8, value.body),
            22 => {
                // The one physical LF exception cannot erase a second byte.
                value.renderer.body_missing = MissingText.untracked(copied[1..]);
                value.renderer.table_viewport_cell_source.?.structural_source.?.tracked = MissingText.untracked(copied[1..]);
                records[0].original = value.body[2..]; selected_tag = span_tag;
            },
            else => unreachable,
        }
        try std.testing.expect(value.renderer.tableConstructedBoxForTag(selected_tag) == null);
        // The old inline source domain remains authoritative when present;
        // structural custody never repairs a tainted/foreign live inline token.
        if (mode == 13 or mode == 14) try std.testing.expect(value.renderer.inline_missing != null);
    }
}

const InlineRubyCore06Test = struct {
