        try map.copies.append(a, .{ .original_start = 0, .output_start = 0, .len = body.len });
        const domain = try a.create(Renderer.QuoteClassSource);
        domain.* = .{ .map = map, .scope = binding.scope,
            .selected = binding.projection.original.bytes, .parent = renderer.quote_class_source };
        renderer.quote_class_source = domain;
        renderer.inline_missing = BulletRuby182Test.body(&renderer);
