        return renderer;
    }
};

test "root inline Ruby negative classes require the exact current copied occurrence and complete owner" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    var styles = try table_style_profile.parseForTargetAlloc(a, ".mw-heading *{word-break:normal}", .screen); defer styles.deinit();
    for (0..15) |mode| {
        var renderer = try InlineRubyCore06Test.setup(a, &styles);
        const body = BulletRuby182Test.body(&renderer).bytes;
        const scope = @constCast(renderer.source_element_binding.?.scope);
        const proof = @constCast(&scope.source_inline_rubies[0]);
        const span_tag = syntax.tagAt(body, 0).?;
        const strong_tag = syntax.tagAt(body, span_tag.end).?;
        const ruby_tag = syntax.tagAt(body, strong_tag.end).?;
        const span_node = try renderer.textElement(span_tag, null, "");
        const strong_node = @constCast(try renderer.textElement(strong_tag, span_node, "ja"));
        const node = @constCast(try renderer.textElement(ruby_tag, strong_node, "ja"));
        var table: Renderer.InlineTableBoundaries = .{};
        switch (mode) {
            0, 14 => {},
            1 => scope.source_inline_rubies_source = try a.dupe(u8, InlineRubyCore06Test.source),
            2 => proof.ruby_start += 1,
            3 => proof.line_end -= 1,
            4 => { const foreign = try a.create(table_style_profile.TextElement); foreign.* = proof.root.*;
                try std.testing.expect(foreign != proof.root); proof.root = foreign; },
            5 => @constCast(renderer.source_element_binding.?.projection).copies = &.{},
            6 => renderer.inline_missing.?.lost_missing_range = true,
            7 => renderer.inline_missing.?.ranges = &.{.{ .start = @intCast(strong_tag.end), .end = @intCast(strong_tag.end + 1), .occurrence = 1 }},
            8 => renderer.inline_missing.?.bytes = try a.dupe(u8, body),
            9 => renderer.typed_table_depth = 1,
            10 => renderer.inline_table_boundaries = &table,
            11 => strong_node.source_key += 1,
            12 => { const foreign = try a.create(table_style_profile.TextElement); foreign.* = node.*;
                try std.testing.expect(foreign != node); node.alternative_ancestry = foreign; },
            13 => scope.source_inline_rubies = &.{},
            else => unreachable,
        }
        if (mode == 14) proof.classes = "mw-body mw-heading mw-parser-output Jpan headword";
        const classes = renderer.rubyInlineAncestorClasses(ruby_tag, node);
        if (mode == 0 or mode == 14) {
            try std.testing.expect(classes != null);
            var query = node.*; query.complete_ancestor_classes = classes.?;
            try std.testing.expectEqual(mode == 0, try styles.sourceRubyLayoutUnchanged(a, &query, "", false));
            try std.testing.expect(table_style_profile.Profile.hasClass(scope.complete_ancestor_class_superset.?, "mw-heading"));
            try std.testing.expect(!node.ancestry_complete and !node.physical_ancestry_complete);
        } else try std.testing.expect(classes == null);
    }
}

test "closed linked reading preserves later Ruby parent edge without granting ancestor or action authority" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = StrongRubyCore04Test;
    var profile = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer profile.deinit();
    const reading = "[[:あいだ#ภาษาญี่ปุ่น|あいだ]]";
    const source = "<ruby>間<rp>(</rp><rt>" ++ reading ++ "</rt><rp>)</rp></ruby>";
    for (0..8) |mode| {
        var renderer = try F.init(a, &profile, source);
        const body = BulletRuby182Test.body(&renderer); renderer.inline_missing = body;
        if (mode != 6) try F.bindDirectQuote(a, &renderer);
        const parent_tag = syntax.tagAt(body.bytes, 0).?;
        const child_tag = syntax.tagAt(body.bytes, std.mem.lastIndexOf(u8, body.bytes, "<rp>").?).?;
        const parent = @constCast(try renderer.textElement(parent_tag, null, "ja"));
        const child = @constCast(try renderer.textElement(child_tag, parent, "ja"));
        switch (mode) {
            0 => {},
            1 => parent.source_key += 1,
            2 => renderer.inline_missing.?.bytes = try a.dupe(u8, body.bytes),
            3 => renderer.inline_missing.?.lost_missing_range = true,
            4 => @constCast(renderer.source_element_binding.?.projection).copies = &.{},
            5 => { const other = try a.create(table_style_profile.TextElement); other.* = parent.*; parent.alternative_ancestry = other; },
            6 => {},
            7 => { const held = renderer.figure_class_source_binding.?.owner.bytes; renderer.figure_class_source_binding.?.owner.bytes = held[0 .. held.len - 1]; },
            else => unreachable,
        }
        const result = renderer.rubySourceParentTag(child_tag, child);
        if (mode == 0) {
            try std.testing.expect(result != null);
            try std.testing.expectEqualStrings("ruby", result.?);
            try std.testing.expect(!Renderer.rubyParentInlineSourceStable(reading));
            try std.testing.expect(renderer.rubyClosedReadingSiblingStable(reading));
            try std.testing.expect(child.source_parent_tag_nonmatch == null and child.constructed_direct_parent == null);
            try std.testing.expect(!child.ancestry_complete and !child.physical_ancestry_complete);
        } else try std.testing.expect(result == null);
    }
    const proof = try F.init(a, &profile, source);
    for ([_][]const u8{
        "[[Target|reading]]", ":[[Target#part|reading]] suffix",
    }) |valid| try std.testing.expect(proof.rubyClosedReadingSiblingStable(valid));
    for ([_][]const u8{
        "[[File:X|reading]]", "[[Category:X|reading]]", "[[Target]]", "[[Target|]]",
        "[[Target|reading", "[[Target|<a href='x'>reading</a>]]", "[[Target|<span>reading</span>]]",
        "[[Target|[[Nested|reading]]]]", "[https://example.invalid reading]", "-{[[Target|reading]]}-",
        "[[Target|first]][[Other|second]]", "<nowiki>[[Target|reading]]</nowiki>",
        "<!--x-->[[Target|reading]]", "[[Target|reading]]</rt><div>x</div>",
    }) |refused| try std.testing.expect(!proof.rubyClosedReadingSiblingStable(refused));
    // A closed reading sibling never turns an intervening wrapper into Ruby.
    const wrapped = "<ruby>x<rp>(</rp><rt>" ++ reading ++ "</rt><span><rp>)</rp></span></ruby>";
    var renderer = try F.init(a, &profile, wrapped);
    const body = BulletRuby182Test.body(&renderer); renderer.inline_missing = body;
    try F.bindDirectQuote(a, &renderer);
    const parent_tag = syntax.tagAt(body.bytes, 0).?;
    const child_tag = syntax.tagAt(body.bytes, std.mem.lastIndexOf(u8, body.bytes, "<rp>").?).?;
    const parent = try renderer.textElement(parent_tag, null, "ja");
    const child = try renderer.textElement(child_tag, parent, "ja");
    try std.testing.expect(renderer.rubySourceParentTag(child_tag, child) == null);
}

