test "constructed plain paint rejects unknown changing and alternate context paint without rejecting fonts" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = ConstructedPlainPaint07Test; const T = F.T;
    var ns = try @import("namespace_registry").Registry.init(a, @embedFile("testdata/de-mai-prefix/namespace-registry.tsv")); defer ns.deinit();
    for ([_][]const u8{
        "@media (orientation:portrait){td div{color:red}}",
        "td div:before{content:'extra'}",
        "td div{color:var(--unknown-paint)}@media (prefers-reduced-motion:reduce){td{--unknown-paint:red}}",
    }) |suffix| {
        var styles = try table_style_profile.parseForTargetAlloc(a, try std.fmt.allocPrint(a, "{s}{s}", .{ F.css, suffix }), .screen); defer styles.deinit();
        var value = try T.prepare(a, &ns, F.F.source, &styles);
        try std.testing.expect(try value.renderer.tableNestedFontMetricsAtViewport(&value.bound, 900));
        try std.testing.expect(value.bound.constructed_fonts[0].owner != null);
        try std.testing.expect(value.bound.constructed_foregrounds[0].rejected);
    }
    var responsive = try table_style_profile.parseForTargetAlloc(a, F.css ++ "@media (max-width:700px){td div{color:red}}", .screen); defer responsive.deinit();
    var changed = try T.prepare(a, &ns, F.F.source, &responsive);
    try std.testing.expect(try changed.renderer.tableNestedFontMetricsAtViewport(&changed.bound, 900));
    try std.testing.expect(!changed.bound.constructed_foregrounds[0].rejected);
    try std.testing.expect(try changed.renderer.tableNestedFontMetricsAtViewport(&changed.bound, 600));
    try std.testing.expect(changed.bound.constructed_foregrounds[0].rejected);
    try std.testing.expect(try changed.renderer.tableNestedFontMetricsAtViewport(&changed.bound, 900));
    try std.testing.expect(changed.bound.constructed_foregrounds[0].rejected);
    var base = try table_style_profile.parseForTargetAlloc(a, F.css, .screen); defer base.deinit();
    var red = try table_style_profile.parseForTargetAlloc(a, F.css ++ "td div{color:red}", .screen); defer red.deinit();
    const left = try F.prepared(a, &ns, F.F.source, &base);
    var same = try F.prepared(a, &ns, F.F.source, &base);
    const other = try F.prepared(a, &ns, F.F.source, &red);
    try std.testing.expect(Renderer.tableLinkSourcesEqual(left.bound, same.bound));
    try std.testing.expect(!Renderer.tableLinkSourcesEqual(left.bound, other.bound));
    same.bound.constructed_foregrounds[0].subject += 1;
    try std.testing.expect(!Renderer.tableLinkSourcesEqual(left.bound, same.bound));
    const nested = "{|\n|\n<div>[[Target|''label'']]</div>\n|}";
    const linked = try F.prepared(a, &ns, nested, &base);
    var linked_quotes: usize = 0;
    for (linked.bound.constructed_fonts, linked.bound.constructed_foregrounds) |font, paint| {
        if (font.quote != null) {
            linked_quotes += 1;
            try std.testing.expect(font.owner != null and paint.rejected and paint.foreground == null);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), linked_quotes);
}

