test "prefixed Ruby anchor proof requires complete live token copied label and clean siblings" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = BulletRuby182Test;
    const source = "[[Target#part|この" ++ PrefixedRubyLabelCore10Test.ruby ++ "tail]]";
    var profile = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer profile.deinit();
    for (0..13) |mode| {
        var renderer = try F.init(a, &profile, source);
        const scope = renderer.source_element_binding.?.scope;
        const original = F.body(&renderer).bytes;
        const copied = try a.dupe(u8, original);
        try std.testing.expect(copied.ptr != original.ptr);
        var map: QuoteSourceMap = .{ .original = original, .output = copied }; defer map.deinit(a);
        try map.copies.append(a, .{ .original_start = 0, .output_start = 0, .len = original.len });
        var quote: Renderer.QuoteClassSource = .{ .map = &map, .scope = scope, .selected = source, .parent = null };
        renderer.quote_class_source = &quote;
        try renderer.heading_source_aliases.append(a, .{ .copied = copied, .original = original });
        var source_frame: InlineSourceDomain = .{ .source = original, .parent = null,
            .tracked = .{ .bytes = original, .unknown = true } };
        var child_frame: InlineSourceDomain = .{ .source = copied, .parent = &source_frame,
            .tracked = .{ .bytes = copied, .unknown = true } };
        renderer.inline_source_domain = &child_frame;
        renderer.inline_missing = child_frame.tracked;
        var tokens: ir.InlineIterator = .{ .input = original, .renderer_boundaries = true };
        const token = tokens.next().?;
        try std.testing.expect(token.kind == .link and token.link_has_pipe and tokens.cursor == original.len);
        var anchor: table_style_profile.TextElement = .{ .tag = "a", .complete_ancestor_classes = F.classes,
            .ancestor_class_scope = scope, .ancestor_class_source = source };
        const ruby_at = std.mem.indexOf(u8, copied, "<ruby>").?;
        const tag = syntax.tagAt(copied, ruby_at).?;
        const node = @constCast(try renderer.textElement(tag, &anchor, "ja"));
        renderer.explicit_wiki_label = .{ .kind = .link, .target = "Target#part", .ordinary_anchor = &anchor,
            .ordinary_label = token.text, .ordinary_depth = 2, .ordinary_token = original, .ordinary_frame = &source_frame };
        switch (mode) {
            0 => {},
            1 => renderer.explicit_wiki_label.?.ordinary_token = try a.dupe(u8, original),
            2 => renderer.explicit_wiki_label.?.ordinary_label = token.text[1..],
            3 => renderer.explicit_wiki_label.?.ordinary_label = try a.dupe(u8, token.text),
            4 => renderer.explicit_wiki_label.?.ordinary_frame = null,
            5 => child_frame.parent = null,
            6 => source_frame.tracked.?.lost_missing_range = true,
            7 => renderer.inline_missing.?.ranges = &.{.{ .start = 14, .end = 15, .occurrence = 1 }},
            8 => map.copies.clearRetainingCapacity(),
            9 => quote.selected = try a.dupe(u8, source),
            10 => node.source_key += 1,
            11 => { const other = try a.create(table_style_profile.TextElement); other.* = anchor; anchor.alternative_ancestry = other; },
            12 => renderer.explicit_wiki_label.?.kind = .external_link,
            else => unreachable,
        }
        const parent_tag = renderer.rubySourceParentTag(tag, node);
        if (mode == 0) {
            try std.testing.expect(parent_tag != null);
            try std.testing.expectEqualStrings("a", parent_tag.?);
            try std.testing.expect(node.source_parent_tag_nonmatch == null and node.constructed_direct_parent == null);
            try std.testing.expect(!node.ancestry_complete and !node.physical_ancestry_complete);
        } else try std.testing.expect(parent_tag == null);
    }
    for ([_][]const u8{ "", "この", "tail", "plain text" }) |plain|
        try std.testing.expect(Renderer.rubyPlainAnchorSibling(plain));
    for ([_][]const u8{
        "<span>x</span>", "[[Other|x]]", "<a>x</a>", "<nowiki>x</nowiki>", "<!--x-->",
        "https://example.invalid", "ISBN 978-0-306-40615-7", "-{x}-", "{{x}}", "&lt;", "''", "\n", "\x00",
    }) |refused| try std.testing.expect(!Renderer.rubyPlainAnchorSibling(refused));
}

