    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior, .content_conversion = true };
    const prefix = "before [[Before#one|before]] ";
    const suffix = " after [[After|after]]\n\n" ++ SourceRecursiveManualTest.marked;
    const source = try std.mem.concat(a, u8, &.{ prefix, T.body, suffix });
    const reference = try std.mem.concat(a, u8, &.{ prefix, T.reduced, suffix });
    const tracked = try SourceRecursiveManualTest.tracked(a, source);
    var proof: Renderer = .{ .a = a, .context = context, .inline_missing = tracked };
    try std.testing.expect(!proof.sourceRecursiveManualContext());
    try std.testing.expect((try proof.nestedRuleFreeFormattingBody(source, prefix.len, .{})) == null);
    const operation = (try proof.sourceKuRecursiveRuleFreeBody(source, prefix.len, .{})) orelse return error.TestUnexpectedResult;
    try std.testing.expect(operation.body.ptr == source[prefix.len + 2..].ptr);
    try std.testing.expectEqualStrings(T.body[2 .. T.body.len - 2], operation.body);
    try std.testing.expectEqual(prefix.len + T.body.len, operation.end);
    const borrowed = try missingSlice(a, tracked, operation.body);
    try std.testing.expect(borrowed.unknown and !borrowed.lost_missing_range and borrowed.ranges.len == 0);
    try std.testing.expect(proof.inline_missing.?.unknown and proof.inline_missing.?.ranges[0].occurrence == 1);
    var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
    const reference_tracked = try SourceRecursiveManualTest.tracked(a, reference);
    var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = reference_tracked };
    const blocks = try actual_renderer.renderBodyWithMissing(tracked);
    const expected_blocks = try expected_renderer.renderBodyWithMissing(reference_tracked);
    const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
    const expected = try FormattingScopeTest.encode(a, &expected_renderer, expected_blocks);
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
    try std.testing.expectEqualDeep(tracked.ranges, actual_renderer.body_missing.?.ranges);
    try std.testing.expect(actual_renderer.body_missing.?.unknown);
    try FormattingScopeTest.word(a, blocks, "あめ", .{ .language = "ja", .classes = "Jpan" });
    try FormattingScopeTest.word(a, actual.entry.sections[0].blocks, "あめ", .{ .language = "ja", .classes = "Jpan" });
    var actions: usize = 0;
    for (blocks) |block| for (block.spans) |span| {
        try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
        if (span.kind == .link) actions += 1;
    };
    try std.testing.expectEqual(@as(usize, 3), actions);
    const codec = @import("blob_encoder").presentation_codec;
    const encoded = try codec.encodeAlloc(a, actual);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), encoded);
    try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, encoded, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
}

