test "inline padding motion custody revalidates ancestor declarations and expires between renderer invocations" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const source = try a.dupe(u8, "<span style='font-size:135%'><span style='padding:0 .25em'>reading</span></span>");
    const tracked = MissingText.untracked(source);
    var renderer: Renderer = .{ .a = a, .context = .{}, .inline_missing = tracked };
    const root: NativeInlineMotionRoot = .{ .source = tracked };
    const parent_tag = syntax.tagAt(source, 0) orelse return error.TestUnexpectedResult;
    const child_tag = syntax.tagAt(source, parent_tag.end) orelse return error.TestUnexpectedResult;
    var saved: FormattingAttributes = .{};
    {
        const scope = renderer.nativeInlineMotionBegin(&root, false); defer scope.deinit();
        try std.testing.expect(renderer.native_inline_motion_root == &root);
        const parent = try renderer.nativeInlineMotionEntry(parent_tag, renderer.body_formatting_attributes.native_inline_motion);
        const child = try renderer.nativeInlineMotionEntry(child_tag, parent);
        const declarations = (try renderer.nativeInlineMotionDeclarations(child)) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(usize, 2), declarations.len);
        try std.testing.expectEqualStrings("padding:0 .25em", declarations[0]);
        try std.testing.expectEqualStrings("font-size:135%", declarations[1]);
        renderer.body_formatting_attributes.native_inline_motion = child;
        saved = renderer.formattingAttributes();
        try std.testing.expect(saved.native_inline_motion == .proved);
        try std.testing.expect(renderer.observerFormattingAttributes().native_inline_motion == .unknown);
        const digit = std.mem.indexOf(u8, source, "135") orelse return error.TestUnexpectedResult;
        source[digit] = '2';
        try std.testing.expect(try renderer.nativeInlineMotionDeclarations(child) == null);
        source[digit] = '1';
        try std.testing.expect(try renderer.nativeInlineMotionDeclarations(child) != null);
        var tainted = tracked; tainted.lost_missing_range = true;
        renderer.inline_missing = tainted;
        try std.testing.expect((try renderer.nativeInlineMotionEntry(child_tag, parent)) == .unknown);
        renderer.inline_missing = tracked;
        var foreign: Renderer = .{ .a = a, .context = .{}, .inline_missing = tracked };
        try std.testing.expect(try foreign.nativeInlineMotionDeclarations(child) == null);
        const invalid_fragment = renderer.nativeInlineMotionBegin(&root, true);
        try std.testing.expect(try renderer.nativeInlineMotionDeclarations(child) == null);
        invalid_fragment.deinit();
        try std.testing.expect(try renderer.nativeInlineMotionDeclarations(child) != null);
    }
    try std.testing.expect(!renderer.native_inline_motion_active and renderer.native_inline_motion_root == null);
    // Reuse the exact same root address and renderer; the invocation epoch,
    // not that address alone, keeps an old private receipt expired.
    {
        const scope = renderer.nativeInlineMotionBegin(&root, false); defer scope.deinit();
        try std.testing.expect(renderer.native_inline_motion_root == &root);
        try std.testing.expect(try renderer.nativeInlineMotionDeclarations(saved.native_inline_motion) == null);
        renderer.restoreFormattingAttributes(saved);
        try std.testing.expect(renderer.body_formatting_attributes.native_inline_motion == .unknown);
    }
}

