const InlinePaddingProducerTest = struct {
    fn read(a: A, embedded: []const u8, length: usize, digest: []const u8) ![]const u8 {
        const bytes = try a.dupe(u8, embedded);
        try std.testing.expectEqual(length, bytes.len);
        var actual: [32]u8 = undefined; std.crypto.hash.sha2.Sha256.hash(bytes, &actual, .{});
        try std.testing.expectEqualStrings(digest, &std.fmt.bytesToHex(actual, .lower));
        return bytes;
    }
    fn groups(spans: []const Span) usize {
        var count: usize = 0;
        for (spans) |span| {
            if (span.inline_padding_group) |group| count += 1 + groups(group.spans);
            if (span.ruby) |ruby| for (ruby.segments) |segment| {
                for (segment.bases) |base| count += groups(base.spans);
                for (segment.annotations) |annotation| count += groups(annotation.spans);
            };
        }
        return count;
    }
};

