    const source: []const u8 = "prefix\n==Noun==\nmissing\n";
    const heading_at = std.mem.indexOf(u8, source, "Noun").?;
    const missing_at = std.mem.indexOf(u8, source, "missing").?;
    const ranges = [_]missing_dependency.Range{.{ .start = @intCast(missing_at), .end = @intCast(missing_at + 7), .occurrence = 1 }};
    for ([_]usize{ 1, 2, 47, 48, 49, 60 }) |count| {
        var renderer: Renderer = .{ .a = a, .context = .{}, .heading_source = source };
        var current: MissingText = .{ .bytes = source, .ranges = &ranges, .unknown = true };
        for (0..count) |_| {
            const previous = current;
            current = try renderer.missingSliceWithHeadingSource(previous, previous.bytes);
            try std.testing.expect(current.bytes.ptr != previous.bytes.ptr);
            try std.testing.expectEqualStrings(source, current.bytes);
            try std.testing.expectEqual(@as(usize, 1), current.ranges.len);
            try std.testing.expectEqual(@as(u32, @intCast(missing_at)), current.ranges[0].start);
            try std.testing.expectEqual(@as(u32, @intCast(missing_at + 7)), current.ranges[0].end);
            try std.testing.expectEqual(@as(u32, 1), current.ranges[0].occurrence);
            try std.testing.expect(current.unknown);
        }
        try std.testing.expectEqual(count, renderer.heading_source_aliases.items.len);
        renderer.a = std.testing.failing_allocator;
        try std.testing.expectEqual(@as(?usize, heading_at), renderer.headingSourceOffset(current.bytes[heading_at..]));
        try std.testing.expectEqual(@as(?usize, 0), renderer.headingSourceOffset(current.bytes));
    }
}

test "heading source offset refuses foreign generated and cyclic copy domains" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source: []const u8 = "root Noun end";
    const heading_at = std.mem.indexOf(u8, source, "Noun").?;
    var renderer: Renderer = .{ .a = a, .context = .{}, .heading_source = source };
    const foreign = try a.dupe(u8, source);
    try std.testing.expect(foreign.ptr != source.ptr);
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(foreign[heading_at..]));

    var output: std.ArrayList(u8) = .empty;
    var copies: std.ArrayList(HeadingSourceCopy) = .empty;
    try output.appendSlice(a, "Noun generated ");
    const copied_at = output.items.len;
    try renderer.appendHeadingSourceCopy(&output, &copies, source[heading_at .. heading_at + 4]);
    try renderer.registerHeadingSourceCopies(output.items, copies.items);
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(output.items));
    try std.testing.expectEqual(@as(?usize, heading_at), renderer.headingSourceOffset(output.items[copied_at..]));
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(output.items[output.items.len..]));

    const self_cycle = try a.dupe(u8, "Noun");
    const first = try a.dupe(u8, "Noun");
    const second = try a.dupe(u8, "Noun");
    try std.testing.expect(first.ptr != second.ptr and first.ptr != self_cycle.ptr);
    try renderer.registerHeadingSourceCopies(self_cycle, &.{.{ .start = 0, .original = self_cycle }});
    try renderer.registerHeadingSourceCopies(first, &.{.{ .start = 0, .original = second }});
    try renderer.registerHeadingSourceCopies(second, &.{.{ .start = 0, .original = first }});
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(self_cycle));
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(first));
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(second));
    renderer.heading_source = null;
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(source));
}

test "heading source point traversal preserves precedence and bounds comparison work" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source: []const u8 = "left Noun right Noun";
    const first_at = std.mem.indexOf(u8, source, "Noun").?;
    const second_at = std.mem.lastIndexOf(u8, source, "Noun").?;
    const first = try a.dupe(u8, source[first_at .. first_at + 4]);
    const second = try a.dupe(u8, first);
    var renderer: Renderer = .{ .a = a, .context = .{}, .heading_source = source };
    try renderer.registerHeadingSourceCopies(first, &.{.{ .start = 0, .original = source[first_at .. first_at + 4] }});
    try renderer.registerHeadingSourceCopies(second, &.{.{ .start = 0, .original = first }});
    renderer.a = std.testing.failing_allocator;
    var sufficient: usize = 3;
    try std.testing.expectEqual(@as(?usize, first_at), renderer.headingSourceOffsetWithinWork(second, &sufficient));
    var insufficient: usize = 2;
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffsetWithinWork(second, &insufficient));
    var direct: usize = 0;
    try std.testing.expectEqual(@as(?usize, first_at), renderer.headingSourceOffsetWithinWork(source[first_at..], &direct));
    try std.testing.expectEqual(@as(?usize, source.len), renderer.headingSourceOffsetWithinWork(source[source.len..], &direct));
    try std.testing.expectEqual(@as(usize, 0), direct);

    renderer.a = a;
    try renderer.registerHeadingSourceCopies(second, &.{.{ .start = 0, .original = source[second_at .. second_at + 4] }});
    // Both source occurrences have identical bytes. Earlier registered custody
    // retains precedence instead of selecting the last equal-text relation.
    try std.testing.expectEqual(@as(?usize, first_at), renderer.headingSourceOffset(second));

    // One byte-identical overlapping relation can move the point twice without
    // repeating an address. It is neither a cycle nor two distinct relations.
    const overlap = try a.dupe(u8, "aaa");
    var overlapping: Renderer = .{ .a = a, .context = .{}, .heading_source = overlap[0..1] };
    try overlapping.registerHeadingSourceCopies(overlap[1..3], &.{.{ .start = 0, .original = overlap[0..2] }});
    try std.testing.expectEqual(@as(usize, 1), overlapping.heading_source_aliases.items.len);
    overlapping.a = std.testing.failing_allocator;
    var overlap_work: usize = 2;
    try std.testing.expectEqual(@as(?usize, 0), overlapping.headingSourceOffsetWithinWork(overlap[2..3], &overlap_work));
    try std.testing.expectEqual(@as(?usize, 0), overlapping.headingSourceOffset(overlap[2..3]));

    var cyclic: Renderer = .{ .a = a, .context = .{}, .heading_source = source };
    const cycle_a = try a.dupe(u8, "Noun");
    const cycle_b = try a.dupe(u8, "Noun");
    try cyclic.registerHeadingSourceCopies(cycle_a, &.{.{ .start = 0, .original = cycle_b }});
    try cyclic.registerHeadingSourceCopies(cycle_b, &.{.{ .start = 0, .original = cycle_a }});
    for (0..24) |_| {
        const unrelated = try a.dupe(u8, "Noun");
        try cyclic.registerHeadingSourceCopies(unrelated, &.{.{ .start = 0, .original = source[first_at .. first_at + 4] }});
    }
    cyclic.a = std.testing.failing_allocator;
    var cycle_work: usize = 8;
    try std.testing.expectEqual(@as(?usize, null), cyclic.headingSourceOffsetWithinWork(cycle_a, &cycle_work));
    try std.testing.expect(cycle_work != 0);
}

