test "retained TH sibling Ruby label preserves both readings whole bullet actions and Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = BulletRuby182Test; const line = SiblingRubyLabelCore12Test.line;
    var actual_profile = try table_style_profile.parseForTargetAlloc(a, ".mw-body blockquote > :first-child{margin-top:0}.mw-heading *{word-break:normal}", .screen); defer actual_profile.deinit();
    var expected_profile = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer expected_profile.deinit();
    var actual = try F.init(a, &actual_profile, line);
    var expected = try F.init(a, &expected_profile, line);
    for ([_]*Renderer{ &actual, &expected }) |renderer| {
        const scope = @constCast(renderer.source_element_binding.?.scope);
        const outer = try a.create(table_style_profile.TextElement); outer.* = .{ .tag = "body", .classes = "mw-body" };
        @constCast(scope.page_style_root.?).parent = outer;
        try BulletRuby187Test.install(a, renderer, line);
        const proofs = try a.alloc(table_style_profile.SourceBulletRubyProof, 2);
        proofs[0] = scope.source_bullet_rubies[0];
        proofs[1] = proofs[0];
        const second = std.mem.indexOfPos(u8, line, proofs[0].ruby_end, "<ruby>").?;
        proofs[1].ruby_start = second;
        proofs[1].ruby_end = syntax.matchingTag(line, syntax.tagAt(line, second).?).?.end;
        try std.testing.expect(proofs[0].ruby_end < proofs[1].ruby_start);
        scope.source_bullet_rubies = proofs;
    }
    const blocks = try actual.renderBodyWithMissing(F.body(&actual));
    const reference = try expected.renderBodyWithMissing(F.body(&expected));
    try std.testing.expectEqualDeep(reference, blocks);
    try std.testing.expect(!actual.fallbacks.any() and !expected.fallbacks.any());
    try std.testing.expectEqual(@as(usize, 1), blocks.len);
    try std.testing.expectEqual(Kind.list_item, blocks[0].kind);
    try std.testing.expectEqualStrings("*", blocks[0].list_path);
    try std.testing.expectEqual(@as(u8, 1), blocks[0].depth);
    try std.testing.expectEqualStrings("床(とこ)の間(ま) (toko no ma)", try flattened(a, blocks[0].spans));
    var rubies: usize = 0;
    for (blocks[0].spans) |span| if (span.ruby) |ruby| {
        try std.testing.expect(rubies < 2);
