        try std.testing.expectEqualStrings(if (rubies == 0) "床" else "間", ruby.segments[0].bases[0].spans[0].text);
        try std.testing.expectEqualStrings(if (rubies == 0) "とこ" else "ま", ruby.segments[0].annotations[0].spans[0].text);
        try std.testing.expect(ruby.segments[0].annotations[0].explicit_fallback);
        rubies += 1;
    };
    try std.testing.expectEqual(@as(usize, 2), rubies);
    const leaves = try RubyProducerTest.leaves(a, blocks[0].spans);
    var actions: usize = 0;
    for (leaves) |leaf| if (leaf.kind == .link) {
        actions += 1;
        try std.testing.expectEqualStrings("床の間#ภาษาญี่ปุ่น", leaf.target);
        try std.testing.expectEqualStrings("ja", leaf.language);
    };
    try std.testing.expectEqual(@as(usize, 9), actions);
    try std.testing.expect(actual.explicit_wiki_label == null and actual.ordinary_bullet_link == null);
    const stored = try FormattingScopeTest.encode(a, &actual, blocks);
    const reference_stored = try FormattingScopeTest.encode(a, &expected, reference);
    try std.testing.expectEqualDeep(reference_stored, stored);
    const codec = @import("blob_encoder").presentation_codec;
    const bytes = try codec.encodeAlloc(a, stored);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, reference_stored), bytes);
    try std.testing.expectEqualDeep(stored, try codec.decodeAlloc(a, bytes, stored.entry.title, .language,
        .{ .heading = stored.entry.language.?, .code = stored.entry.language_code }));
}

test "Ruby label siblings select exact equal text occurrence and reject malformed or foreign copies" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const ruby = "<ruby>x<rp>(</rp><rt>r</rt><rp>)</rp></ruby>";
    const label = "pre" ++ ruby ++ "middle" ++ ruby ++ "post";
    const first = label[3 .. 3 + ruby.len];
    const second = label[3 + ruby.len + 6 .. 3 + ruby.len + 6 + ruby.len];
    try std.testing.expect(std.mem.eql(u8, first, second) and first.ptr != second.ptr);
    for ([_][]const u8{ first, second }) |occurrence| {
        const found = Renderer.rubyAnchorLabelBody(label, occurrence) orelse return error.TestUnexpectedResult;
        try std.testing.expect(found.ptr == occurrence.ptr and found.len == occurrence.len);
        const child_at = std.mem.indexOf(u8, occurrence, "rt>").?;
        const child = occurrence[child_at .. child_at + 2];
        try std.testing.expect(Renderer.rubyAnchorLabelBody(label, child).?.ptr == occurrence.ptr);
    }
    try std.testing.expect(Renderer.rubyAnchorLabelBody(label, try a.dupe(u8, first)) == null);
    try std.testing.expect(Renderer.rubyAnchorLabelBody(label, label[0..1]) == null);
    for ([_][]const u8{
        ruby ++ "<ruby>broken", ruby ++ "<ruby>x<rt><div>x</div></rt></ruby>", ruby ++ "<span>text</span>",
        ruby ++ "[[Other|x]]", ruby ++ "<!--x-->", ruby ++ "<nowiki>x</nowiki>",
        ruby ++ "-{x}-", ruby ++ "https://example.invalid", ruby ++ "<ruby>[[Nested|x]]<rt>x</rt></ruby>",
        ruby ++ "<ruby><ruby>x<rt>r</rt></ruby><rt>x</rt></ruby>",
    }) |bad| try std.testing.expect(Renderer.rubyAnchorLabelBody(bad, bad[0..ruby.len]) == null);
    var excessive: std.ArrayList(u8) = .empty; defer excessive.deinit(a);
    for (0..max_depth + 2) |_| try excessive.appendSlice(a, ruby);
    try std.testing.expect(Renderer.rubyAnchorLabelBody(excessive.items, excessive.items[0..ruby.len]) == null);

    const source = "[[Target|" ++ label ++ "]]";
    const F = BulletRuby182Test;
    var profile = try table_style_profile.parseForTargetAlloc(a, "", .screen); defer profile.deinit();
    var renderer = try F.init(a, &profile, source);
    const original = F.body(&renderer).bytes;
    const copied = try a.dupe(u8, original);
    var map: QuoteSourceMap = .{ .original = original, .output = copied }; defer map.deinit(a);
    try map.copies.append(a, .{ .original_start = 0, .output_start = 0, .len = original.len });
    var quote: Renderer.QuoteClassSource = .{ .map = &map, .scope = renderer.source_element_binding.?.scope, .selected = source, .parent = null };
    renderer.quote_class_source = &quote;
    try renderer.heading_source_aliases.append(a, .{ .copied = copied, .original = original });
    var source_frame: InlineSourceDomain = .{ .source = original, .parent = null, .tracked = .{ .bytes = original, .unknown = true } };
    var child_frame: InlineSourceDomain = .{ .source = copied, .parent = &source_frame, .tracked = .{ .bytes = copied, .unknown = true } };
    renderer.inline_source_domain = &child_frame; renderer.inline_missing = child_frame.tracked;
    var tokens: ir.InlineIterator = .{ .input = original, .renderer_boundaries = true };
    const token = tokens.next().?;
    try std.testing.expect(token.kind == .link and token.link_has_pipe and tokens.cursor == original.len);
    renderer.explicit_wiki_label = .{ .kind = .link, .target = "Target", .ordinary_label = token.text,
        .ordinary_token = original, .ordinary_frame = &source_frame };
    const selected = renderer.figureClassSourceDomain().?;
    const binding = renderer.figureStyleOriginalBinding(selected).?;
    const first_at = std.mem.indexOf(u8, copied, "<ruby>").?;
    const second_at = std.mem.indexOfPos(u8, copied, first_at + ruby.len, "<ruby>").?;
    const first_copy = copied[first_at .. first_at + ruby.len];
    const second_copy = copied[second_at .. second_at + ruby.len];
    const first_original = renderer.ordinaryLinkOriginal(selected, first_copy).?.bytes;
    const second_original = renderer.ordinaryLinkOriginal(selected, second_copy).?.bytes;
    try std.testing.expect(first_original.ptr != second_original.ptr and std.mem.eql(u8, first_original, second_original));
    try std.testing.expect(renderer.rubyMappedAnchorLabel(selected, binding, renderer.inline_missing.?, token.text, first_copy, first_original));
    try std.testing.expect(renderer.rubyMappedAnchorLabel(selected, binding, renderer.inline_missing.?, token.text, second_copy, second_original));
    try std.testing.expect(!renderer.rubyMappedAnchorLabel(selected, binding, renderer.inline_missing.?, token.text, first_copy, second_original));
    try std.testing.expect(!renderer.rubyMappedAnchorLabel(selected, binding, renderer.inline_missing.?, token.text, second_copy, first_original));
    child_frame.parent = null;
    try std.testing.expect(!renderer.rubyMappedAnchorLabel(selected, binding, renderer.inline_missing.?, token.text, first_copy, first_original));
}

