    // issuance is separately tested by Profile and genuine retained Book cases.
    var scope: table_style_profile.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output", .subtree_classes = "",
        .complete_ancestor_class_superset = "mw-parser-output", .page_styles = &styles, .page_style_root = &root,
        .page_source_image = &source_image,
        .closed_row_colors = .{ .styles = &styles, .source = source, .root = &root, .attribute = "bgcolor",
            .owners = &.{.{ .attrs_start = start, .attrs_end = end }} },
        .unobserved_counter_resets = .{ .source_image = &source_image, .styles = &styles, .source = source,
            .source_snapshot = snapshot, .root = &root, .rules = styles.container_rules,
            .resets = &.{.{ .rule = 0, .name = "links" }} } };
    try std.testing.expect(Renderer.validClosedRowColors(&scope, source, &styles) != null);
    try std.testing.expect(Renderer.validUnobservedCounters(&scope, source, &styles) != null);
    var renderer: Renderer = .{ .a = a, .content_root = .parser_output,
        .context = .{ .table_styles = &styles, .figure_sizing = .{ .resolve_fn = F.sizing,
            .text_class_scope = .{ .source = source, .scope = &scope } } },
        .bounded_text_class_scope = &scope, .bounded_text_class_source = source, .body_missing = MissingText.untracked(source) };
    try renderer.checkPageAncestorEffects(MissingText.untracked(source));
    try std.testing.expect(!renderer.fallbacks.unresolved_table_style and renderer.checked_page_style_counters != null);
    const saved_rows = scope.closed_row_colors;
    scope.closed_row_colors = null;
    try std.testing.expect(Renderer.validUnobservedCounters(&scope, source, &styles) != null);
    scope.closed_row_colors = saved_rows;
    const saved_image = source_image; const saved_scope = scope;
    for (0..14) |mode| {
        var changed = renderer; var tracked = MissingText.untracked(source);
        var rebound = source_image; var wrong_root = root;
        switch (mode) {
            0 => scope.page_source_image = null,
            1 => scope.page_source_image = &rebound,
            2 => source_image.source = foreign,
            3 => source_image.snapshot = foreign,
            4 => source_image.snapshot = source,
            5 => source[0] = 'X',
            6 => snapshot[0] = 'X',
            7 => source_image.root = &wrong_root,
            8 => source_image.styles = &base,
            9 => scope.unobserved_counter_resets.?.resets = &.{},
            10 => tracked.unknown = true,
            11 => tracked.lost_missing_range = true,
            12 => tracked.ranges = &.{.{ .start = 0, .end = @intCast(source.len), .occurrence = 1 }},
            13 => tracked.generated_source = source,
            else => unreachable,
        }
        changed.inline_missing = tracked;
        try changed.checkPageAncestorEffects(tracked);
        try std.testing.expect(changed.fallbacks.unresolved_table_style);
        source[0] = '{'; snapshot[0] = '{'; source_image = saved_image; scope = saved_scope;
    }
    try std.testing.expect(scope.closed_row_colors.?.owners.len == 1 and scope.closed_row_colors.?.absent_source == null);
    try std.testing.expect(Renderer.validUnobservedCounters(&scope, source, &styles) != null);
}


test "interrupted qualified prose preserves literal boundaries live child actions and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { source: []const u8, escaped: []const u8, visible: []const u8 }{
        .{ .source = "<ll:more <>> [[Tail|END]]", .escaped = "&lt;ll:more &lt;&gt;> [[Tail|END]]", .visible = "<ll:more <>> END" },
        .{ .source = "''برد<tr:bord><pos:past stem of <i lang=fa>[[:بردن#Persian|بردن]]</i> (bordan)>'' [[Tail|END]]",
            .escaped = "''برد<tr:bord>&lt;pos:past stem of <i lang=fa>[[:بردن#Persian|بردن]]</i> (bordan)>'' [[Tail|END]]",
            .visible = "برد<tr:bord><pos:past stem of بردن (bordan)> END" },
    };
    for (cases) |case| {
        var actual: Renderer = .{ .a = a, .context = .{} };
        var reference: Renderer = .{ .a = a, .context = .{} };
        const blocks = try actual.renderBody(case.source);
        const reference_blocks = try reference.renderBody(case.escaped);
        try FormattingScopeTest.shapes(a, blocks, &.{"paragraph"}, &.{case.visible});
        try FormattingScopeTest.word(a, blocks, "END", .{ .kind = .link, .target = "Tail" });
        if (std.mem.indexOf(u8, case.source, "pos:") != null) {
            try FormattingScopeTest.word(a, blocks, "بردن", .{ .kind = .link, .target = "بردن#Persian", .italic = true, .language = "fa" });
        }
        try std.testing.expect(actual.fallbacks.literal_markup);
        const stored = try FormattingScopeTest.encode(a, &actual, blocks);
        const expected = try FormattingScopeTest.encode(a, &reference, reference_blocks);
        try std.testing.expectEqualDeep(expected, stored);
        try std.testing.expectEqualSlices(u8, try @import("blob_encoder").presentation_codec.encodeAlloc(a, expected),
            try @import("blob_encoder").presentation_codec.encodeAlloc(a, stored));
    }
}

test "interrupted qualified prose refuses executable attribute protocol and protected domains" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{
        "<pos:past {{missing}} <i>x</i>>", "<pos:past {{{missing}}} <i>x</i>>",
        "<pos:past [[Target]] <i>x</i>>", "<pos:past &amp; <i>x</i>>",
        "<pos:past 'quote' <i>x</i>>", "<pos:past name=value <i>x</i>>",
        "<https:past <i>x</i>>", "</pos:past <i>x</i>>", "<pos:past\n<i>x</i>>",
        "<pos:past <script>x</script>>", "<pos:past <ref>x</ref>>", "<pos:past <i>x",
        "<pos:past <table>x</table>>",
    }) |source| {
        try std.testing.expect(Renderer.interruptedQualifiedProseOpening(source, 0) == null);
    }
    const borrowed = "<span title='<pos:past <i>x</i>>'>";
    try std.testing.expect(Renderer.interruptedQualifiedProseOpening(borrowed, 13) == null);
    var raw: Renderer = .{ .a = a, .context = .{} };
    const unresolved = "<pos:past {{missing}} <i>x</i>>";
    const prepared = try raw.literalHtmlAnglesSourceWithMissing(MissingText.untracked(unresolved));
    try std.testing.expectEqualStrings(unresolved, prepared.bytes);
    try std.testing.expectError(error.UncompiledPresentation, requireCompiledText(unresolved));
    var protected: Renderer = .{ .a = a, .context = .{} };
    const spans = try protected.parseSpans("<nowiki><pos:past <i>[[Target|x]]</i>></nowiki>", .{});
    try std.testing.expectEqualStrings("<pos:past <i>[[Target|x]]</i>>", try flattened(a, spans));
    for (spans) |span| try std.testing.expect(span.kind == .text and span.target.len == 0 and span.provenance == .protected_literal);
    try std.testing.expect(!protected.fallbacks.literal_markup);
}


