test "retained MG 崩れる malformed reference prefix does not hide its physical table" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const Read = struct {
        fn exact(allocator: A, comptime path: []const u8, length: usize, digest: []const u8) ![]const u8 {
            const embedded = @embedFile(path);
            try std.testing.expect(embedded.len < 16 * 1024);
            const bytes = try allocator.dupe(u8, embedded);
            try std.testing.expectEqual(length, bytes.len);
            var actual: [32]u8 = undefined; std.crypto.hash.sha2.Sha256.hash(bytes, &actual, .{});
            try std.testing.expectEqualStrings(digest, &std.fmt.bytesToHex(actual, .lower));
            return bytes;
        }
    };
    const prefix = "testdata/mg208-reference/";
    const raw = try Read.exact(a, prefix ++ "raw.wikitext", 338, "be51b48315bf31c693d320b32e76208e3c23b1392d3ef81817ffa34c36a96f79");
    const expanded = try Read.exact(a, prefix ++ "expanded.wikitext", 2918, "ad57bbf290bc3b74370f706919c135df9c3bc2e628fc96c4d3c10ff8c47eb418");
    const metadata = try Read.exact(a, prefix ++ "missing-dependency.json", 402, "4399207f9fd00156d8bdbf3cb44c9cadae98373d6affe2415d2d7ebe7b68dbab");
    try std.testing.expect(std.mem.indexOf(u8, raw, "<ref name=\"KDJ2\">{{R:Nihon Kokugo Daijiten 2, intrans)") != null);
    try std.testing.expect(std.mem.indexOf(u8, raw, "</ref>") == null);
    var phase = try missing_dependency.decode(a, metadata, expanded, ""); defer phase.deinit();
    try std.testing.expect(phase.output().unknown);
    try std.testing.expectEqual(@as(usize, 1), phase.output().ranges.len);
    const source = try missing_dependency.slice(a, phase.output(), 225, 1229);
    try std.testing.expect(source.unknown and !source.lost_missing_range and source.ranges.len == 0);
    try std.testing.expectEqualStrings(expanded[225..1229], source.bytes);
    try std.testing.expectEqual(@as(usize, 1004), source.bytes.len);
    try std.testing.expectEqualStrings("{|", expanded[433..435]);
    try std.testing.expectEqualStrings("</ref>", expanded[1229..1235]);
    try std.testing.expect(syntax.balanced(source.bytes, 0) == null);
    try std.testing.expect(Renderer.referenceHasWikiTableBody(source.bytes));
    // This is a structural selection proof, not acceptance of the truncated
    // table, unknown dependency state, or the entire page's CSS and media.
    try std.testing.expect(phase.output().unknown and source.unknown);
}

test "reference malformed prefix retains diagnostic typed table action and complete codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const body = "{{broken words\n\n{|\n| [[Target|cell]]\n|}\n\nafter";
    var renderer: Renderer = .{ .a = a, .context = .{ .title = "entry" } };
    try renderer.refs.append(a, .{ .number = 1, .group_number = 1, .name = "note", .body = body,
        .missing = .{ .bytes = body, .unknown = true } });
    const refs = try renderer.finishReferences();
    try std.testing.expectEqual(@as(usize, 1), refs.len);
    try std.testing.expect(refs[0].blocks != null and refs[0].spans.len == 0);
    try std.testing.expect(renderer.refs.items[0].missing.?.unknown);
    try std.testing.expectEqualStrings(body, renderer.refs.items[0].body);
    try std.testing.expect(renderer.fallbacks.literal_markup);
    const blocks = refs[0].blocks.?;
    var tables: usize = 0; var actions: usize = 0; var diagnostic_count: usize = 0;
    for (blocks) |block| {
        for (block.spans) |span| {
            if (span.generated_diagnostic) {
                diagnostic_count += 1;
                try std.testing.expectEqualStrings("[malformed template]", span.text);
                try std.testing.expect(span.kind == .text and span.target.len == 0);
            }
            try std.testing.expect(std.mem.indexOf(u8, span.text, "{{broken") == null);
        }
        if (block.table) |table| {
            tables += 1;
            try std.testing.expectEqual(@as(usize, 1), table.rows.len);
            try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            for (table.rows[0].cells[0].spans) |span| if (span.kind == .link) {
                actions += 1;
                try std.testing.expectEqualStrings("Target", span.target);
                try std.testing.expectEqualStrings("cell", span.text);
            };
        }
    }
    try std.testing.expectEqual(@as(usize, 1), tables);
    try std.testing.expectEqual(@as(usize, 1), actions);
    try std.testing.expectEqual(@as(usize, 1), diagnostic_count);
    try std.testing.expectEqualStrings("after", try plainText(a, blocks[blocks.len - 1].spans));
    const Section = struct { level: u8 = 0, title: []const u8 = "", blocks: []const Block = &.{} };
    const sections = [_]Section{.{}};
    const blob = @import("blob_encoder");
    const encoded = try blob.presentation_codec.encodeBuildAlloc(a, &[_]Span{}, &sections, blob.presentation_types.Layout{}, renderer.refs.items, renderer.media.items);
    const decoded = try blob.presentation_codec.decodeAlloc(a, encoded, "entry", .supplemental, null);
    try std.testing.expectEqual(@as(usize, 1), decoded.entry.references.len);
    const stored_note = decoded.entry.references[0];
    try std.testing.expectEqual(@as(usize, 1), stored_note.number);
    try std.testing.expectEqual(@as(?u32, 1), stored_note.group_number);
    try std.testing.expectEqualStrings("note", stored_note.name);
    try std.testing.expectEqual(@as(usize, 0), stored_note.spans.len);
    const stored_blocks = stored_note.blocks.?;
    try std.testing.expectEqual(@as(usize, 3), stored_blocks.len);
    try std.testing.expectEqualStrings("[malformed template] words", try FormattingScopeTest.text(a, stored_blocks[0].spans));
    try std.testing.expectEqualStrings("after", try FormattingScopeTest.text(a, stored_blocks[2].spans));
    const stored_cell = stored_blocks[1].table.?.rows[0].cells[0];
    try std.testing.expectEqual(@as(usize, 1), stored_cell.spans.len);
    try std.testing.expectEqualStrings("cell", stored_cell.spans[0].text);
    try std.testing.expectEqualStrings("Target", stored_cell.spans[0].target);
    try std.testing.expect(stored_cell.spans[0].kind == .link);
    const reencoded = try blob.presentation_codec.encodeAlloc(a, decoded);
    try std.testing.expectEqualSlices(u8, encoded, reencoded);
    try std.testing.expectEqualDeep(decoded, try blob.presentation_codec.decodeAlloc(a, reencoded, "entry", .supplemental, null));
}

