test "pinned recursive no-rule sibling frame preserves borrowed source complete body and actions" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const NS = @import("namespace_registry"); const T = SourceRecursiveManualTest;
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" };
    ns.manual_conversion_context = T.profile();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .namespace_catalog = &ns, .behavior_switches = &behavior };
    // Full211's former negative is balanced and entirely rule-free. The pinned
    // converter evaluates both children before the no-rule parent, independent
    // of whether a child is inside a label or an ordinary sibling.
    const frame = "-{[[Target|-{plain}-]] -{outside}-}-";
    // Reduce the link-label child only. Preserve the ordinary sibling frame:
    // inlineTextWithMissing emits its borrowed body at a separate span boundary.
    const reduced_frame = "-{[[Target|plain]] -{outside}-}-";
    const prefix = "before [[Before|before]] ";
    const suffix = " after [[After#part|after]]\n\n" ++ T.marked;
    const source = try std.mem.concat(a, u8, &.{ prefix, frame, suffix });
    const reference = try std.mem.concat(a, u8, &.{ prefix, reduced_frame, suffix });
    const tracked = try T.tracked(a, source);
    var proof: Renderer = .{ .a = a, .context = context, .inline_missing = tracked };
    const operation = (try proof.sourceRecursiveRuleFreeLinkLabels(source, prefix.len, .{})) orelse return error.TestUnexpectedResult;
    try std.testing.expect(operation.body.ptr == source[prefix.len + 2 ..].ptr);
    try std.testing.expectEqualStrings(frame[2 .. frame.len - 2], operation.body);
    try std.testing.expectEqual(prefix.len + frame.len, operation.end);
    try std.testing.expect(!operation.multiline_boundary_lfs);
    const borrowed = try missingSlice(a, tracked, operation.body);
    try std.testing.expect(borrowed.unknown and !borrowed.lost_missing_range and borrowed.ranges.len == 0);
    try std.testing.expect(!ns.manual_conversion_context.?.automatic_identity);
    var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
    const reference_tracked = try T.tracked(a, reference);
    var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = reference_tracked };
    const blocks = try actual_renderer.renderBodyWithMissing(tracked);
    const reference_blocks = try expected_renderer.renderBodyWithMissing(reference_tracked);
    const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
    const expected = try FormattingScopeTest.encode(a, &expected_renderer, reference_blocks);
    // Check the complete ordinary child boundary before the full Stored oracle;
    // neither flatten nor coalesce the actual presentation to fit the reference.
    try std.testing.expectEqual(@as(usize, 8), blocks[0].spans.len);
    try std.testing.expectEqualStrings(" ", blocks[0].spans[4].text);
    try std.testing.expectEqualStrings("outside", blocks[0].spans[5].text);
    try std.testing.expect(blocks[0].spans[4].kind == .text);
    var expected_outside_span = blocks[0].spans[4];
    expected_outside_span.text = "outside";
    try std.testing.expectEqualDeep(expected_outside_span, blocks[0].spans[5]);
    try std.testing.expectEqualDeep(expected, actual);
    try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
    try std.testing.expectEqualStrings("before before plain outside after after", try flattened(a, blocks[0].spans));
    try std.testing.expect(actual_renderer.body_missing.?.unknown);
    try std.testing.expectEqualDeep(tracked.ranges, actual_renderer.body_missing.?.ranges);
    var action_count: usize = 0; var target_count: usize = 0; var missing_count: usize = 0;
    for (blocks) |block| for (block.spans) |span| {
        try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
        if (span.kind == .link) {
            action_count += 1;
            if (std.mem.eql(u8, span.target, "Target")) {
                target_count += 1; try std.testing.expectEqualStrings("plain", span.text);
            }
            if (std.mem.eql(u8, span.target, "Template:R:hi:Rajpal")) missing_count += 1;
        }
    };
    try std.testing.expectEqual(@as(usize, 4), action_count);
    try std.testing.expectEqual(@as(usize, 1), target_count);
    try std.testing.expectEqual(@as(usize, 1), missing_count);
    const codec = @import("blob_encoder").presentation_codec;
    const encoded = try codec.encodeAlloc(a, actual);
    try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), encoded);
    try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, encoded, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
}


test "qualified prose distinguishes literal brackets from maintained action openers" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{
        "[see <xlit:Word <span>x</span>>]",
        "[see <xlit:Word <span>x</span>>",
        "<i>[see <xlit:Word <span>x</span>>]</i>",
        "[see <xlit:Word <span>x</span>>] [[Target|T]] [https://example.test E]",
    }) |source| {
        const reference_source = try std.mem.replaceOwned(u8, a, source, "<xlit:", "&lt;xlit:");
        for ([_]bool{ false, true }) |ordinary| {
            var preparing: Renderer = .{ .a = a, .context = .{} };
            const prepared = try preparing.prepareQuoteSource(MissingText.untracked(source), ordinary);
            try std.testing.expectEqualStrings(reference_source, prepared.source.bytes);
        }
        var actual: Renderer = .{ .a = a, .context = .{} };
        var expected: Renderer = .{ .a = a, .context = .{} };
        const spans = try actual.parseSpans(source, .{});
        const reference_spans = try expected.parseSpans(reference_source, .{});
        try std.testing.expectEqualDeep(reference_spans, spans);
        var internal_count: usize = 0;
        var external_count: usize = 0;
        for (spans) |span| {
            if (span.kind == .link) {
                internal_count += 1;
                try std.testing.expectEqualStrings("Target", span.target);
                try std.testing.expectEqualStrings("T", span.text);
            } else if (span.kind == .external_link) {
                external_count += 1;
                try std.testing.expectEqualStrings("https://example.test", span.target);
                try std.testing.expectEqualStrings("E", span.text);
            } else try std.testing.expect(span.kind == .text and span.target.len == 0);
        }
        const has_actions = std.mem.indexOf(u8, source, "[[Target|") != null;
        try std.testing.expectEqual(@as(usize, if (has_actions) 1 else 0), internal_count);
        try std.testing.expectEqual(@as(usize, if (has_actions) 1 else 0), external_count);
        var body: Renderer = .{ .a = a, .context = .{} };
        var reference: Renderer = .{ .a = a, .context = .{} };
        const blocks = try body.renderBody(source);
        const reference_blocks = try reference.renderBody(reference_source);
        const stored = try FormattingScopeTest.encode(a, &body, blocks);
        const expected_stored = try FormattingScopeTest.encode(a, &reference, reference_blocks);
        try std.testing.expectEqualDeep(expected_stored, stored);
        try std.testing.expectEqualSlices(u8,
            try @import("blob_encoder").presentation_codec.encodeAlloc(a, expected_stored),
            try @import("blob_encoder").presentation_codec.encodeAlloc(a, stored));
        try std.testing.expect(body.fallbacks.literal_markup);
    }
    // Actual and malformed action domains keep their refusal. A surrounding
    // literal bracket must not hide a nested genuine opener from the hold.
    for ([_][]const u8{
        "[[Target|<xlit:Word <span>x</span>>]]",
        "[[Target|<xlit:Word <span>x</span>>",
        "[https://example.test <xlit:Word <span>x</span>>]",
        "[https://example.test <xlit:Word <span>x</span>>",
        "[HTTPS://example.test <xlit:Word <span>x</span>>]",
        "[//example.test <xlit:Word <span>x</span>>]",
        "[ftp://example.test <xlit:Word <span>x</span>>]",
        "[see [[Target|<xlit:Word <span>x</span>>]]]",
        "[see [https://example.test <xlit:Word <span>x</span>>]]",
    }) |source| {
        for ([_]bool{ false, true }) |ordinary| {
            var preparing: Renderer = .{ .a = a, .context = .{} };
            try std.testing.expectError(error.UncompiledPresentation,
                preparing.prepareQuoteSource(MissingText.untracked(source), ordinary));
        }
        try std.testing.expectError(error.UncompiledPresentation, requireCompiledText(source));
    }
}


