        "https://zh.wikipedia.org/wiki/%E6%9D%B1%E4%BA%AC%E6%96%B9%E8%A8%80", "頭高型",
        "Wiktionary:國際音標", "Appendix:日語發音", "Wiktionary:日語轉寫", "piasu#日語", "耳环", "耳坠",
    };
    const labels = [_][]const u8{ "英語", "piercing", "pierce", "東京", "頭高型", "國際音標", "幫助", "•", "piasu", "耳环", "耳坠" };
    var actions: usize = 0;
