    var summary = unbound; summary.tag = "summary";
    const details = try profile.resolveAlignmentIn(a, &summary, null, "");
    try std.testing.expect(details.unresolved);
}

test "ordinary literal DIV issuer keeps unknown exterior and incompatible subject source separate" {
    const Case = struct {
        source: []const u8, child_at: usize, expected_subject: bool = true, expected_parent: bool = true,
        stale: bool = false, copied: bool = false, previous: []const u8 = "", negative_previous: ?[]const u8 = null,
    };
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const outer = "<div class=outer>";
    const child = "<div class=inner>x</div>";
    const sibling = "<div class=heading><div style='width:25em'>Етимолошко стабло</div></div>";
    const crossed = "<div><i>prior</div></i>";
    const opaque_sibling = "<textarea>prior</textarea>";
    const flex_item = "<span style='position:relative;height:20px'></span>";
    const not_direct = "<div class=intervening><span>other depth</span>";
    var profile = try table_style_profile.parseForTargetAlloc(a,
        "details.outer div.inner{font-size:150%}div.outer div.inner{font-size:100%;font-weight:bold;text-align:left}.mw-body-content div.inner{font-weight:normal!important}.IPA *{font-style:italic}", .screen);
    defer profile.deinit();
    for ([_]Case{
        .{ .source = outer ++ child ++ "</div>", .child_at = outer.len },
        .{ .source = outer ++ sibling ++ child ++ "</div>", .child_at = outer.len + sibling.len, .previous = "div" },
        .{ .source = outer ++ sibling ++ " " ++ child ++ "</div>", .child_at = outer.len + sibling.len + 1, .expected_parent = false },
        .{ .source = outer ++ sibling ++ flex_item ++ child ++ "</div>", .child_at = outer.len + sibling.len + flex_item.len,
            .expected_parent = false, .negative_previous = "span" },
        .{ .source = outer ++ not_direct ++ child ++ "</div></div>", .child_at = outer.len + not_direct.len, .expected_parent = false },
        .{ .source = outer ++ crossed ++ child ++ "</div>", .child_at = outer.len + crossed.len, .expected_parent = false },
        .{ .source = outer ++ opaque_sibling ++ child ++ "</div>", .child_at = outer.len + opaque_sibling.len, .expected_parent = false },
        .{ .source = outer ++ " " ++ child ++ "</div>", .child_at = outer.len + 1, .expected_parent = false },
        .{ .source = outer ++ "<div class=inner style='color:red' style='color:blue'>x</div></div>", .child_at = outer.len, .expected_subject = false, .expected_parent = false },
        .{ .source = outer ++ "<div\x0bclass=inner>x</div></div>", .child_at = outer.len, .expected_subject = false, .expected_parent = false },
        .{ .source = outer ++ child ++ "</div>", .child_at = outer.len, .expected_subject = false, .expected_parent = false, .stale = true },
        .{ .source = outer ++ child ++ "</div>", .child_at = outer.len, .expected_subject = false, .expected_parent = false, .copied = true },
    }) |sample| {
        const input = try a.dupe(u8, sample.source);
        const tracked = MissingText.untracked(input);
        const source_root: NativeInlineMotionRoot = .{ .source = tracked };
        var renderer = Renderer{ .a = a, .context = .{ .title = "word", .table_styles = &profile, .text_paint_styles = &profile },
            .body_missing = tracked, .content_root = .parser_output, .native_body_language = "en",
            .native_inline_motion_active = true, .native_inline_motion_root = &source_root, .native_inline_motion_epoch = 1 };
        var host: NativeArticleHost = .{ .renderer = &renderer, .source = tracked, .title = "word", .language_code = "en",
            .active_source = tracked, .active_snapshot = NativeArticleHost.snapshot(tracked), .native_paragraph_css_subjects = true };
        renderer.native_article_host = &host;
        const parent_tag = syntax.tagAt(input, 0).?;
        const initial = NativeInlineMotionState{ .proved = .{ .root = &source_root, .epoch = 1 } };
        const state = try renderer.nativeInlineMotionEntry(parent_tag, initial);
        try std.testing.expect(state == .proved and state.proved.last != null);
        const parent = try renderer.textElement(parent_tag, null, "");
        const source = if (sample.copied) try a.dupe(u8, input) else input;
        const tag = syntax.tagAt(source, sample.child_at) orelse {
            try std.testing.expect(!sample.expected_subject);
            continue;
        };
        const node = try renderer.textElement(tag, parent, "");
        if (sample.stale) renderer.native_inline_motion_epoch += 1;
        var work: LiteralSubjectWork = .{};
        renderer.literal_subject_work = &work;
        renderer.literal_subject = try renderer.bindLiteralSubjectForBlock(tag, .{ .native_inline_motion = state, .text_element = parent });
        const bound_work = work;
        const got = try renderer.literalFirstDivQuery(tag, node, state, node);
        try std.testing.expectEqual(sample.expected_subject, got != null);
        if (got) |local| {
            try std.testing.expect(local.source_nonlink_element);
            try std.testing.expect(local.complete_ancestor_classes == null and local.complete_ancestor_ids == null);
            try std.testing.expectEqual(sample.expected_parent, local.parent != null);
            if (!sample.expected_parent) {
                try std.testing.expect(!local.literal_first_div_pair);
                if (sample.negative_previous) |expected| {
                    try std.testing.expectEqualStrings(expected, local.source_literal_previous.?.tag.?);
                } else if (sample.child_at == outer.len + not_direct.len or sample.child_at == outer.len + opaque_sibling.len)
                    try std.testing.expect(local.source_literal_previous == null);
            }
            if (sample.expected_parent) {
                try std.testing.expectEqual(sample.previous.len == 0, local.literal_first_div_pair);
                try std.testing.expectEqualStrings(sample.previous, local.source_literal_previous.?.tag.?);
                const size = (try profile.resolveFontSizeIn(a, local, "", null)).?;
                try std.testing.expect(size == .relative and size.relative == 1);
                const resolution = try profile.resolveTextPaintWithCustom(a, local, "", .{});
                try std.testing.expect(resolution.weight != null and resolution.weight.? == .unknown);
                try std.testing.expect(resolution.font_style != null and resolution.font_style.? == .unknown);
                const alignment = try profile.resolveAlignmentIn(a, local, null, "");
                try std.testing.expect(!alignment.unresolved and alignment.value == .left);
                // Repeated font/alignment/geometry queries retain the operation's
                // original receipt and perform no further source scans/hashes.
                for (0..3) |_| try std.testing.expect((try renderer.literalFirstDivQuery(tag, node, state, node)) != null);
                try std.testing.expectEqual(bound_work, work);
                try std.testing.expectEqual(@as(usize, 1), work.snapshot_calls);
                try std.testing.expectEqual(input.len, work.snapshot_source_bytes);
                try std.testing.expectEqual(@as(usize, 1), work.pair_scans);
                try std.testing.expectEqual(input.len, work.pair_source_bytes);
                try std.testing.expectEqual(@as(usize, @intFromBool(sample.previous.len != 0)), work.sibling_scans);
                try std.testing.expectEqual(if (sample.previous.len != 0) sibling.len else @as(usize, 0), work.sibling_source_bytes);
                renderer.native_inline_motion_epoch += 1;
                try std.testing.expect((try renderer.literalFirstDivQuery(tag, node, state, node)) == null);

            }
        }
    }
}

test "relative source owner keeps one original measured width and rejects crossed or positioned descendants" {
    const text = [_]Span{.{ .kind = .text, .text = "Header", .flags = .{ .bold = true } }};
    const paragraphs = [_]Block{.{ .kind = .paragraph, .spans = &text }};
    var child = [_]Block{.{ .kind = .container, .container = .{ .style = .{
        .width = .{ .length = .{ .unit = .em, .value = 23.75 } }, .owner_font_scale = 0.95,
    }, .blocks = &paragraphs } }};
    const source = "<div style=\"width:25em\">Header</div>";
    try std.testing.expect(Renderer.sourceWidthOnlyPlainChild(source, &child));
    for ([_][]const u8{
        "<div style=\"width:25em;z-index:5\">Header</div>", "<div style=\"width:25em\"><a>Header</a></div>",
        "<div style=\"width:25em\" style=\"width:25em\">Header</div>", "<div style=\"width:25em\">Elsewhere</div>",
        "<div style=\"width:24em\">Header</div>", "<div style=\"width:25em\">Header</div> sibling",
    }) |bad| try std.testing.expect(!Renderer.sourceWidthOnlyPlainChild(bad, &child));
    child[0].container.?.style.positioning = .relative_auto;
    try std.testing.expect(!Renderer.sourceWidthOnlyPlainChild(source, &child));
}

test "observed screen root survives a refused generic query only at its exact live opening" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const input = "<div class=card><div class=card>inside</div></div><div class=card>outside</div>";
    const nested_start = "<div class=card>".len;
    const root_end = "<div class=card><div class=card>inside</div></div>".len;
    const tracked = MissingText.untracked(input);
    const declaration: table_style_profile.ObservedLiteralScreenBox = .{
        .box = .{ .style = .{ .width = .max_content, .overflow = .hidden }, .specified = true },
        .table_collapse = .collapse,
    };
    const Fixture = struct {
        fn noImage(_: ?*const anyopaque, _: A, _: []const u8, _: presentation_types.FigureFormat,
            _: ?u32, _: ?u32) A.Error!?presentation_types.FigureSizingPolicy
        {
            return null;
        }
    };
    const sizing: FigureSizingSource = .{
        .resolve_fn = Fixture.noImage,
        .literal_region = .{ .page = input, .selected = input[0..root_end],
            .classes = "card", .screen_root_box = &declaration },
    };
    var renderer: Renderer = .{ .a = a, .context = .{ .title = "selected", .figure_sizing = sizing },
        .native_body_language = "en", .content_root = .parser_output, .body_missing = tracked };
    var host: NativeArticleHost = .{ .renderer = &renderer, .source = tracked, .title = "selected",
        .language_code = "en", .active_source = tracked, .active_snapshot = NativeArticleHost.snapshot(tracked),
        .active_whole_page = true, .native_paragraph_css_subjects = true };
    renderer.native_article_host = &host;
    const opener = syntax.tagAt(input, 0) orelse return error.TestUnexpectedResult;
    const element: table_style_profile.TextElement = .{ .tag = opener.name, .source_key = @intFromPtr(opener.name.ptr) };
    try std.testing.expect(renderer.observedScreenRootForOpening(opener, &element) == &declaration);
    for ([_]usize{ nested_start, root_end }) |offset| {
        const other = syntax.tagAt(input, offset) orelse return error.TestUnexpectedResult;
        const other_node: table_style_profile.TextElement = .{ .tag = other.name, .source_key = @intFromPtr(other.name.ptr) };
        try std.testing.expect(renderer.observedScreenRootForOpening(other, &other_node) == null);
    }
    const copy = try a.dupe(u8, input);
    const copied_opener = syntax.tagAt(copy, 0) orelse return error.TestUnexpectedResult;
    const copied_node: table_style_profile.TextElement = .{ .tag = copied_opener.name, .source_key = @intFromPtr(copied_opener.name.ptr) };
    renderer.body_missing = MissingText.untracked(copy);
    try std.testing.expect(renderer.observedScreenRootForOpening(copied_opener, &copied_node) == null);
    renderer.body_missing = tracked;
    host.active_snapshot = null;
    try std.testing.expect(renderer.observedScreenRootForOpening(opener, &element) == null);
}

pub fn verifyTableNestedFontOwnerEqualityForTesting() !void {
    if (!@import("builtin").is_test) @compileError("test-only font owner equality inspection");
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const F = struct {
        fn copy(alloc: A, value: Renderer.TableNestedFontOwner) !Renderer.TableNestedFontOwner {
            var result = value;
            inline for (.{ "font", "parent_font", "body_font" }) |name| {
                const original = @field(value, name);
                @field(result, name).language = try alloc.dupe(u8, original.language);
                @field(result, name).classes = try alloc.dupe(u8, original.classes);
                if (original.font_family) |family|
                    @field(result, name).font_family = try table_style_profile.cloneFontFamilyRequestAlloc(alloc, family);
            }
            return result;
        }
        fn disagree(left: Renderer.TableNestedFontOwner, right: Renderer.TableNestedFontOwner) !void {
            try std.testing.expect(!Renderer.tableNestedFontOwnersAgree(left, right));
            try std.testing.expect(!Renderer.tableNestedFontOwnersAgree(right, left));
        }
    };
    const font: presentation_types.InlineFontSnapshot = .{ .font_scale = 1.1, .font_scale_basis = .normal_body,
        .bold = true, .italic = true, .language = "ku", .classes = "retained",
        .font_features = .normal, .font_family = .{ .stack = .{ .names = &.{ "Retained First", "Retained Second" }, .fallback = .serif } } };
    const template: Renderer.TableNestedFontOwner = .{ .font = font, .parent_font = font, .body_font = font,
        .height = .{ .multiplier = 1.5 }, .html_metric = .{ .value = 1, .basis = .normal_body },
        .body_metric = .{ .value = 1, .basis = .normal_body }, .owner_metric = .{ .value = 1.1, .basis = .normal_body },
        .parent_metric = .{ .value = 1, .basis = .normal_body } };
    const original = try F.copy(a, template);
    const equal = try F.copy(a, original);
    inline for (.{ "font", "parent_font", "body_font" }) |name| {
        const one = @field(original, name); const two = @field(equal, name);
        try std.testing.expect(one.language.ptr != two.language.ptr and one.classes.ptr != two.classes.ptr);
        const first = one.font_family.?.stack; const second = two.font_family.?.stack;
        try std.testing.expect(first.names.ptr != second.names.ptr);
        for (first.names, second.names) |x, y| try std.testing.expect(x.ptr != y.ptr);
    }
    // Independent equality proves the values before the changed comparator is
    // used; the generic custody comparison must keep its original semantics.
    try std.testing.expectEqualDeep(original, equal);
    try std.testing.expect(!Renderer.sameFigurePreparationValue(original, equal));
    std.debug.print("KU_FONT_OWNER_EQUALITY stage=distinct_allocations_equal_values\n", .{});
    try std.testing.expect(Renderer.tableNestedFontOwnersAgree(original, equal));
    try std.testing.expect(Renderer.tableNestedFontOwnersAgree(equal, original));
    try std.testing.expect(Renderer.tableNestedFontOwnersAgree(null, null));
    try std.testing.expect(!Renderer.tableNestedFontOwnersAgree(original, null));
    try std.testing.expect(!Renderer.tableNestedFontOwnersAgree(null, original));
    inline for (.{ "font", "parent_font", "body_font" }) |name| {
        const family = @field(equal, name).font_family.?.stack;
        var changed = equal;
        @field(changed, name).font_family = .{ .stack = .{ .names = &.{ "Different First", family.names[1] }, .fallback = family.fallback } };
        try F.disagree(original, changed);
        changed = equal;
        @field(changed, name).font_family = .{ .stack = .{ .names = family.names, .fallback = .sans_serif } };
        try F.disagree(original, changed);
        changed = equal;
        @field(changed, name).font_family = .{ .stack = .{ .names = &.{ family.names[1], family.names[0] }, .fallback = family.fallback } };
        try F.disagree(original, changed);
        changed = equal;
        @field(changed, name).font_family = .{ .stack = .{ .names = family.names[0..1], .fallback = family.fallback } };
        try F.disagree(original, changed);
        changed = equal; @field(changed, name).font_family = .sans_serif; try F.disagree(original, changed);
        changed = equal; @field(changed, name).font_family = null; try F.disagree(original, changed);
        inline for (.{ "small", "superscript", "subscript", "font_normalized", "bold", "italic", "code" }) |flag| {
            changed = equal; @field(@field(changed, name), flag) = !@field(@field(equal, name), flag);
            try F.disagree(original, changed);
        }
        changed = equal; @field(changed, name).font_scale = 1.25; try F.disagree(original, changed);
        changed = equal; @field(changed, name).font_scale = null; try F.disagree(original, changed);
        changed = equal; @field(changed, name).font_scale_basis = .css_px; try F.disagree(original, changed);
        changed = equal; @field(changed, name).language = "tr"; try F.disagree(original, changed);
        changed = equal; @field(changed, name).classes = "different"; try F.disagree(original, changed);
        changed = equal; @field(changed, name).role = .label; try F.disagree(original, changed);
        changed = equal; @field(changed, name).font_features = .seven_on; try F.disagree(original, changed);
        changed = equal; @field(changed, name).font_features = null; try F.disagree(original, changed);
    }
    inline for (.{ "html_metric", "body_metric", "owner_metric", "parent_metric" }) |name| {
        var changed = equal; @field(changed, name).value = 2; try F.disagree(original, changed);
        changed = equal; @field(changed, name).value = null; try F.disagree(original, changed);
        changed = equal; @field(changed, name).basis = .css_px; try F.disagree(original, changed);
        changed = equal; @field(changed, name).unknown = true; try F.disagree(original, changed);
    }
    var changed = equal; changed.height = .{ .multiplier = 1.75 }; try F.disagree(original, changed);
    changed = equal; changed.height = .normal; try F.disagree(original, changed);
    changed = equal; changed.height = .{ .length = .{ .value = 1.5, .font_scale_basis = .normal_body } }; try F.disagree(original, changed);
    try std.testing.expectEqualDeep(original, equal);
    std.debug.print("KU_FONT_OWNER_EQUALITY stage=complete snapshots=3\n", .{});
}

const ArmoredClassPipe461Test = struct {
    // Exact three form owners retained in ZH03 failure461, polvoroso p1513544/r6045117.
    const feminine = "-{ <b class=\"Latn form-of lang-es f|s-form-of\" lang=\"es\">[[:polvorosa#西班牙語|-{polvorosa}-]]</b>}-";
    const masculine_plural = "-{ <b class=\"Latn form-of lang-es m|p-form-of\" lang=\"es\">[[:polvorosos#西班牙語|-{polvorosos}-]]</b>}-";
    const feminine_plural = "-{ <b class=\"Latn form-of lang-es f|p-form-of\" lang=\"es\">[[:polvorosas#西班牙語|-{polvorosas}-]]</b>}-";
    const body = feminine ++ "，陽性複數" ++ masculine_plural ++ "，陰性複數" ++ feminine_plural;
    // The existing flat HTML conversion is the independent reference. Keep
    // each outer frame: deleting it coalesces adjacent plain-text spans before
    // the codec (see SourceRecursiveManualTest). Only flatten inner labels;
    // armor attribute pipes exactly as the pinned Sanitizer does.
    const reference = "-{ <b class=\"Latn form-of lang-es f&#124;s-form-of\" lang=\"es\">[[:polvorosa#西班牙語|polvorosa]]</b>}-，陽性複數-{ <b class=\"Latn form-of lang-es m&#124;p-form-of\" lang=\"es\">[[:polvorosos#西班牙語|polvorosos]]</b>}-，陰性複數-{ <b class=\"Latn form-of lang-es f&#124;p-form-of\" lang=\"es\">[[:polvorosas#西班牙語|polvorosas]]</b>}-";
};

test "pinned sanitized class pipes preserve recursive original forms actions classes Missing and codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = ArmoredClassPipe461Test; const M = SourceRecursiveManualTest; const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" }; ns.manual_conversion_context = M.profile();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .title = "polvoroso", .namespace_catalog = &ns, .behavior_switches = &behavior };
    const prefix = "forms ";
    const source = prefix ++ T.body ++ "\n\n" ++ M.marked;
    const reference = prefix ++ T.reference ++ "\n\n" ++ M.marked;
    for ([_]bool{ false, true }) |unknown| {
        var tracked = try M.tracked(a, source); tracked.unknown = unknown;
        var reference_tracked = try M.tracked(a, reference); reference_tracked.unknown = unknown;
        var proof: Renderer = .{ .a = a, .context = context, .inline_missing = tracked };
        const operation = (try proof.sourceRecursiveRuleFreeLinkLabels(source, prefix.len, .{})) orelse return error.TestUnexpectedResult;
        try std.testing.expect(operation.body.ptr == source.ptr + prefix.len + 2);
        try std.testing.expectEqualStrings(T.feminine[2..T.feminine.len - 2], operation.body);
        try std.testing.expectEqual(prefix.len + T.feminine.len, operation.end);
        try std.testing.expectEqualDeep(tracked, proof.inline_missing.?);
        var actual_renderer: Renderer = .{ .a = a, .context = context, .body_missing = tracked };
        var expected_renderer: Renderer = .{ .a = a, .context = context, .body_missing = reference_tracked };
        const blocks = try actual_renderer.renderBodyWithMissing(tracked);
        const expected_blocks = try expected_renderer.renderBodyWithMissing(reference_tracked);
        try std.testing.expectEqual(@as(usize, 2), blocks.len);
        try std.testing.expectEqualStrings("forms  polvorosa，陽性複數 polvorosos，陰性複數 polvorosas",
            try FormattingScopeTest.text(a, blocks[0].spans));
        try std.testing.expectEqual(@as(usize, 1), tracked.ranges.len);
        try std.testing.expectEqual(@as(u32, 1), tracked.ranges[0].occurrence);
        try std.testing.expectEqualStrings(M.marked, source[tracked.ranges[0].start..tracked.ranges[0].end]);
        const actual = try FormattingScopeTest.encode(a, &actual_renderer, blocks);
        const expected = try FormattingScopeTest.encode(a, &expected_renderer, expected_blocks);
        try std.testing.expectEqualDeep(expected, actual);
        try std.testing.expectEqualDeep(expected_renderer.fallbacks, actual_renderer.fallbacks);
        try std.testing.expect(!actual_renderer.fallbacks.literal_markup);
        try std.testing.expectEqual(unknown, actual_renderer.body_missing.?.unknown);
        try std.testing.expectEqualDeep(tracked.ranges, actual_renderer.body_missing.?.ranges);
        var forms: usize = 0;
        for (blocks) |block| for (block.spans) |span| {
            try std.testing.expect(std.mem.indexOf(u8, span.text, "-{") == null);
            if (std.mem.startsWith(u8, span.target, "polvoros")) {
                const expected_forms = [_][]const u8{ "polvorosa", "polvorosos", "polvorosas" };
                const expected_classes = [_][]const u8{ "f|s-form-of", "m|p-form-of", "f|p-form-of" };
                try std.testing.expect(forms < expected_forms.len);
                try std.testing.expectEqualStrings(expected_forms[forms], span.text);
                try std.testing.expectEqualStrings("es", span.language);
                try std.testing.expect(span.kind == .link and span.flags.bold);
                try std.testing.expect(std.mem.indexOf(u8, span.classes, expected_classes[forms]) != null);
                try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "{s}#西班牙語", .{expected_forms[forms]}), span.target);
                try std.testing.expectEqualStrings(try std.fmt.allocPrint(a, "Latn form-of lang-es {s}", .{expected_classes[forms]}), span.classes);
                forms += 1;
            }
        };
        try std.testing.expectEqual(@as(usize, 3), forms);
        const codec = @import("blob_encoder").presentation_codec;
        const encoded = try codec.encodeAlloc(a, actual);
        try std.testing.expectEqualSlices(u8, try codec.encodeAlloc(a, expected), encoded);
        try std.testing.expectEqualDeep(actual, try codec.decodeAlloc(a, encoded, "formatting scope", .language, .{ .heading = "English", .code = "en" }));
    }
}

test "pinned class pipe proof refuses rule flags foreign attributes duplicate owners and tainted source" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const M = SourceRecursiveManualTest; const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" }; ns.manual_conversion_context = M.profile();
    var behavior = try ManualConversionTest.behavior(a, &ns); defer behavior.deinit();
    const context: Context = .{ .title = "class pipe refusal", .namespace_catalog = &ns, .behavior_switches = &behavior };
    // Literal and entity-armored pipes are the same ordinary HTML token.
    // No namespace/conversion context is supplied to this lexical projection.
    var ordinary: Renderer = .{ .a = a, .context = .{} };
    for ([_]struct { source: []const u8, expected: []const u8 }{
        .{ .source = "<b class=\"Latn f|s-form-of\">", .expected = "Latn f|s-form-of" },
        .{ .source = "<b class=\"Latn f&#124;s-form-of\">", .expected = "Latn f|s-form-of" },
        .{ .source = "<b class=\"Latn f&#x7c;s-form-of\">", .expected = "Latn f|s-form-of" },
        .{ .source = "<b class=\"IPA|headword f|s-form-of\">", .expected = "IPA|headword f|s-form-of" },
        .{ .source = "<b class=\"keep wikidict-media-file-546f6e65 wikidict-media-file-54|66\">", .expected = "keep" },
        .{ .source = "<b class=\"keep wikidict-media-file-54&#124;66\">", .expected = "keep" },
        .{ .source = "<b class=\"keep bad:selector bad[selector] bad&amp;token bad&quot;quote bad&lt;tag\">", .expected = "keep" },
        .{ .source = "<b class=\"keep bad\x01control\">", .expected = "keep" },
    }) |sample| {
        const tag = syntax.tagAt(sample.source, 0) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(sample.expected, try ordinary.safeHtmlClassNames(tag));
    }
    for ([_][]const u8{
        "-{ <b class=f|s>-{plain}-</b>}-",
        "-{ <b lang=\"f|s\">-{plain}-</b>}-",
        "-{ <b title=\"f|s\">-{plain}-</b>}-",
        "-{ <b class=\"f|s\" class=\"other\">-{plain}-</b>}-",
        "-{ <b class=\"f|s\"lang=\"es\">-{plain}-</b>}-",
        "-{ <b class=\"f|s\">-{T|plain}-</b>}-",
        "-{ <b class=\"f|s\">-{zh-hans:a;zh-hant:b}-</b>}-",
        "-{ <b class=\"f|s\">-{plain}-</i>}-",
        "-{plain|<b class=\"f|s\">-{plain}-</b>}-",
    }) |invalid| {
        var refused: Renderer = .{ .a = a, .context = context, .inline_missing = MissingText.untracked(invalid) };
        try std.testing.expectError(error.UncompiledPresentation, refused.manualConversion(invalid, 0, .{}));
    }
    const body = ArmoredClassPipe461Test.feminine;
    for (0..4) |mode| {
        var tracked: MissingText = .{ .bytes = body, .unknown = true };
        switch (mode) {
            0 => tracked.lost_missing_range = true,
            1 => tracked.generated_source = body,
            2 => tracked.ranges = &.{.{ .start = 2, .end = 3, .occurrence = 1 }},
            3 => tracked.literal_curly_ranges = &.{.{ .start = 2, .end = 3 }},
            else => unreachable,
        }
        var refused: Renderer = .{ .a = a, .context = context, .inline_missing = tracked };
        try std.testing.expectError(error.UncompiledPresentation, refused.manualConversion(body, 0, .{}));
    }
    var protected: Renderer = .{ .a = a, .context = context, .inline_missing = MissingText.untracked(body) };
    try std.testing.expectError(error.UncompiledPresentation, protected.manualConversion(body, 0, .{ .provenance = .protected_literal }));
    ns.manual_conversion_context.?.source_core = "unproved core";
    var unproved: Renderer = .{ .a = a, .context = context, .inline_missing = MissingText.untracked(body) };
    try std.testing.expectError(error.UncompiledPresentation, unproved.manualConversion(body, 0, .{}));
}

test "pinned class pipe predecessor keeps complete tracked sibling scope and refuses generic or tainted shortcuts" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const T = ArmoredClassPipe461Test; const M = SourceRecursiveManualTest; const NS = @import("namespace_registry");
    var ns = try NS.Registry.init(a, NS.english_test_fixture); defer ns.deinit();
    ns.content_language = "zh"; ns.language_conversion = &.{ "zh", "zh-hans", "zh-hant" }; ns.manual_conversion_context = M.profile();
    const context: Context = .{ .title = "tracked sibling forms", .namespace_catalog = &ns };
    const source = "forms " ++ T.body;
    const second = "forms ".len + T.feminine.len + "，陽性複數".len;
    const third = second + T.masculine_plural.len + "，陰性複數".len;
    for ([_]bool{ false, true }) |unknown| {
        const tracked: MissingText = .{ .bytes = source, .unknown = unknown };
        var proof: Renderer = .{ .a = a, .context = context, .inline_missing = tracked };
        try std.testing.expect(!Renderer.formattingAngleBodyPositionWithTrackedSiblingsIn(source, second, true, tracked, true));
        for ([_]usize{ second, third }) |at| {
            const operation = (try proof.sourceRecursiveRuleFreeLinkLabels(source, at, .{})) orelse return error.TestUnexpectedResult;
            try std.testing.expect(operation.body.ptr == source.ptr + at + 2);
            try std.testing.expectEqualDeep(tracked, proof.inline_missing.?);
        }
        for (0..4) |mode| {
            var tainted = tracked;
            switch (mode) {
                0 => tainted.ranges = &.{.{ .start = 8, .end = 9, .occurrence = 1 }},
                1 => tainted.literal_curly_ranges = &.{.{ .start = 8, .end = 9 }},
                2 => tainted.lost_missing_range = true,
                3 => tainted.generated_source = source,
                else => unreachable,
            }
            var refused: Renderer = .{ .a = a, .context = context, .inline_missing = tainted };
            try std.testing.expect((try refused.sourceRecursiveRuleFreeLinkLabels(source, second, .{})) == null);
        }
    }
    for ([_][]const u8{
        "-{ <b class=\"f|s\">[[:one|-{one}-]]</i>}-",
        "-{ <b title=\"f|s\">[[:one|-{one}-]]</b>}-",
        "-{ <b class=\"f|s\" class=\"two\">[[:one|-{one}-]]</b>}-",
        "-{ <b class=\"f|s\">[[:one|-{T|one}-]]</b>}-",
        "-{ <b class=\"f|s\">[[:one|-{one}-]]</b>",
    }) |prefix| {
        const candidate = try std.mem.concat(a, u8, &.{ prefix, " next ", T.masculine_plural });
        const tracked = MissingText.untracked(candidate);
        var refused: Renderer = .{ .a = a, .context = context, .inline_missing = tracked };
        try std.testing.expect((try refused.sourceRecursiveRuleFreeLinkLabels(candidate, prefix.len + " next ".len, .{})) == null);
    }
}

test "nested top stroke preserves its interior fixed dotted circle and plain neighbors" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const outer = "<span style='border-top:1px solid'>";
    const inner = "<span style='border:1px dotted gray;border-radius:50%'>";
    const mark = outer ++ "ジ" ++ inner ++ "プ</span>ト</span>";
    const rule = "body.action-info .mw-body-content :target,.citation:target { background-color:#def;background-color:rgba(0,127,255,.133) }";
    var profile = try table_style_profile.parseForTargetAlloc(a, rule, .screen);
    defer profile.deinit();
    const prefix = "<span lang='ja' class='Jpan'>エ";
    const suffix = "</span> [[Egypt]]";
    var r: Renderer = .{ .a = a, .content_root = .parser_output, .context = .{ .table_styles = &profile } };
    const blocks = try r.renderBody(prefix ++ mark ++ suffix);
    var count: usize = 0;
    var links: usize = 0;
    for (blocks[0].spans, 0..) |span, i| {
        if (span.kind == .link) {
            try std.testing.expectEqualStrings("Egypt", span.target);
            links += 1;
        }
        const group = span.inline_box_group orelse continue;
        try std.testing.expect(topEdgeWithCircle(span, group.*));
        try std.testing.expect(i > 0 and std.mem.endsWith(u8, blocks[0].spans[i - 1].text, "エ"));
        try std.testing.expectEqualStrings("ジ", group.spans[0].text);
        try std.testing.expectEqualStrings("プ", fixedCircleLeaf(group.spans[1]).?.text);
        try std.testing.expectEqualStrings("#808080", group.spans[1].inline_box_group.?.border.top.dotted.color.rgb);
        try std.testing.expectEqualStrings("ト", group.spans[2].text);
        count += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), count);
    try std.testing.expectEqual(@as(usize, 1), links);
    // A target higher in the tree can still paint an id-less descendant.
    var ancestor = try table_style_profile.parseForTargetAlloc(a, "body.action-info :target span { background-color:#def }", .screen);
    defer ancestor.deinit();
    var conditional: Renderer = .{ .a = a, .content_root = .parser_output, .context = .{ .table_styles = &ancestor } };
    try std.testing.expectError(error.UncompiledPresentation, conditional.renderBody("<span id='ref'>" ++ mark ++ "</span>"));
    for ([_][]const u8{
        "<span style='border-bottom:1px solid'>ジ" ++ inner ++ "プ</span>ト</span>",
        outer ++ "ジ<span style='border:1px dotted gray;border-radius:50%' title='advice'>プ</span>ト</span>",
        outer ++ "ジ" ++ inner ++ "[[Egypt|プ]]</span>ト</span>",
        outer ++ "ジ" ++ inner ++ "プ</span>" ++ inner ++ "ト</span></span>",
        outer ++ "ジ<span style='border:1px dotted gray;border-radius:25%'>プ</span>ト</span>",
    }) |changed| {
        var negative: Renderer = .{ .a = a, .content_root = .parser_output, .context = .{ .table_styles = &profile } };
        const page = try std.mem.concat(a, u8, &.{ prefix, changed, suffix });
        try std.testing.expectError(error.UncompiledPresentation, negative.renderBody(page));
    }
}

test "native list keeps a literal bracketed sample with one authored deletion" {
    const sample = "<samp>[èjíp<del>ú</del>tó]</samp>";
    try std.testing.expect(Renderer.containerPositionChildCompleteIn(sample, true, null));
    try std.testing.expect(!Renderer.containerPositionChildCompleteIn(sample, false, null));
    for ([_][]const u8{
        "<samp>[ht<del>tps:</del>//example.org]</samp>",
        "<samp>[a<del title='x'>b</del>c]</samp>",
        "<samp>[a<del>[[target]]</del>c]</samp>",
        "<samp>[a<del><i>b</i></del>c]</samp>",
        "<samp>[a<del>b</del><del>c</del>d]</samp>",
        "<samp>[a<del>b</i>c]</samp>",
        "<samp>[a<del>b</del>c]</samp>\n* other",
    }) |changed| try std.testing.expect(!Renderer.containerPositionChildCompleteIn(changed, true, null));
}


test "literal HTML cell DIV uses only the current complete projected table operation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const T = LiteralDivCustomRootTest;
    var parent_styles = try table_style_profile.parseForTargetAlloc(a, "", .screen);
    defer parent_styles.deinit();
    var styles = try table_style_profile.joinPageSourcesAlloc(a, &parent_styles,
        &.{.{ .css = ":root{--ink:red;--paper:white}", .base_url = "" }}, &.{});
    defer styles.deinit();
    try T.attach(&styles);
    var fixture = try LiteralDivContextTest.init(a, &styles);
    const renderer = &fixture.renderer;
    const source = "<table style='--paper:var(--ink)'><tr style='--ink:blue'><th>label</th><td style='--cell:var(--ink);border-right:0px'><div class='inner' style='--ink:purple'>body</div></td></tr></table>";
    const root = @constCast(fixture.scope.page_style_complete_root.?);
    root.observed_custom_environment = T.environment;
    @constCast(root.alternative_ancestry.?).observed_custom_environment = T.environment;
    fixture.scope.page_custom_invariant = .{};
    const prepared = try a.dupe(u8, source);
    const table_start: usize = 0;
    const row_start = std.mem.indexOf(u8, source, "<tr ").?;
    const cell_start = std.mem.indexOf(u8, source, "<td ").?;
    const div_start = std.mem.indexOf(u8, source, "<div ").?;
    const openings = [_]usize{ table_start, row_start, cell_start };
    var ranges: [3]table_style_profile.SourceLiteralHtmlElement = undefined;
    for (openings, &ranges) |start, *range| {
        const tag = syntax.tagAt(source, start).?;
        const pair = syntax.matchingTag(source, tag).?;
        range.* = .{ .start = start, .opening_end = tag.end, .body_end = pair.inner_end, .end = pair.end };
    }
    const div = syntax.tagAt(source, div_start).?;
    const div_end = syntax.matchingTag(source, div).?.end;
    const proof: table_style_profile.SourceLiteralDivProof = .{ .range = .{ .anchor_start = div_start,
        .anchor_end = div_end, .name_start = div_start + 1, .name_len = div.name.len,
        .attrs_start = @intFromPtr(div.attrs.ptr) - @intFromPtr(source.ptr), .attrs_len = div.attrs.len },
        .parent_start = null, .html_cell_parent = .{ .table = ranges[0], .row = ranges[1], .cell = ranges[2] } };
    fixture.scope.source_literal_divs = &.{proof};
    fixture.scope.source_literal_divs_source = source;
    const original: MissingText = .{ .bytes = source, .unknown = true };
    var owner = original;
    owner.bytes = prepared;
    fixture.projection.* = .{ .original = original, .prepared = prepared,
        .copies = &.{.{ .original_start = 0, .prepared_start = 0, .len = source.len }},
        .observed_source = .{ .source = source, .scope = fixture.scope } };
    renderer.context.figure_sizing.?.text_class_scope = .{ .source = source, .scope = fixture.scope };
    renderer.body_missing = owner;
    renderer.source_element_binding.?.owner = owner;
    renderer.figure_class_source_binding.?.owner = owner;
    renderer.bounded_text_class_scope = fixture.scope;
    renderer.bounded_text_class_source = prepared;

    const table = syntax.tagAt(prepared, table_start).?;
    const row = syntax.tagAt(prepared, row_start).?;
    const cell = syntax.tagAt(prepared, cell_start).?;
    const div_tag = syntax.tagAt(prepared, div_start).?;
    const table_body = prepared[ranges[0].opening_end..ranges[0].body_end];
    const cell_body = prepared[ranges[2].opening_end..ranges[2].body_end];
    const active = renderer.prepareLiteralHtmlTable(table, table_body) orelse return error.TestUnexpectedResult;
    const live = (try renderer.prepareLiteralHtmlCell(active, row, cell, cell_body)) orelse return error.TestUnexpectedResult;
    try std.testing.expect((try renderer.prepareLiteralHtmlCell(active, row, cell, try a.dupe(u8, cell_body))) == null);

    try std.testing.expect(!(try renderer.textElement(div_tag, live.physical, "")).physical_ancestry_complete);
    renderer.literal_html_cell = &live;
    const node = try renderer.textElement(div_tag, live.physical, "");
    try std.testing.expect(node.physical_ancestry_complete and node.ancestry_complete and node.element_index == null);
    try std.testing.expect(node.source_literal_div == &fixture.scope.source_literal_divs[0]);
    try std.testing.expect(node.parent == live.physical);
    try std.testing.expectEqualStrings("td", node.parent.?.tag);
    try std.testing.expectEqualStrings("tr", node.parent.?.parent.?.tag);
    try std.testing.expectEqualStrings("tbody", node.parent.?.parent.?.parent.?.tag);
    try std.testing.expectEqualStrings("table", node.parent.?.parent.?.parent.?.parent.?.tag);
    try std.testing.expect(node.alternative_ancestry.?.parent == live.physical.alternative_ancestry);
    // Compute each authored declaration at its actual TABLE/TR/TD stage.
    // The child's override must not re-evaluate inherited var() expressions.
    const palette = (try renderer.customElement(div_tag, .{
        .text_element = live.physical, .custom_properties = styles.custom_properties.?.root_environment })).?;
    try std.testing.expect(palette.complete);
    try std.testing.expectEqualStrings("#235923", palette.get("--paper").known);
    try std.testing.expectEqualStrings("blue", palette.get("--cell").known);
    try std.testing.expectEqualStrings("purple", palette.get("--ink").known);
    @constCast(root.alternative_ancestry.?).observed_custom_environment = .{
        .complete = true, .values = &.{.{ .name = "--ink", .value = .{ .known = "orange" } }} };
    const disagree = (try renderer.customElement(div_tag, .{ .text_element = live.physical })).?;
    try std.testing.expect(disagree.get("--paper") == .unknown);
    try std.testing.expectEqualStrings("blue", disagree.get("--cell").known);
    @constCast(root.alternative_ancestry.?).observed_custom_environment = T.environment;
    const wrong_cell = live.physical.*;
    try std.testing.expect(!(try renderer.textElement(div_tag, &wrong_cell, "")).physical_ancestry_complete);
    try std.testing.expect((try renderer.customElement(div_tag, .{ .text_element = &wrong_cell })).?.get("--cell") == .unknown);
    // A later enclosing-row taint must invalidate an already-issued lease,
    // even though the target DIV's bytes and local range remain clean.
    owner.ranges = &.{.{ .start = @intCast(row_start + 1), .end = @intCast(row_start + 2), .occurrence = 1 }};
    renderer.source_element_binding.?.owner = owner;
    try std.testing.expect(!(try renderer.textElement(div_tag, live.physical, "")).physical_ancestry_complete);
    try std.testing.expect((try renderer.customElement(div_tag, .{ .text_element = live.physical })).?.get("--cell") == .unknown);
    // Restore the owner and prove recovery before independently removing the
    // live operation; otherwise row taint could mask a missing lease check.
    owner.ranges = &.{};
    renderer.source_element_binding.?.owner = owner;
    try std.testing.expectEqualStrings("blue", (try renderer.customElement(div_tag, .{ .text_element = live.physical })).?.get("--cell").known);
    renderer.literal_html_cell = null;
    try std.testing.expect((try renderer.customElement(div_tag, .{ .text_element = live.physical })).?.get("--cell") == .unknown);

    owner.ranges = &.{.{ .start = @intCast(row_start + 1), .end = @intCast(row_start + 2), .occurrence = 1 }};
    renderer.body_missing = owner;
    renderer.source_element_binding.?.owner = owner;
    try std.testing.expect(renderer.prepareLiteralHtmlTable(table, table_body) == null);
}

test "paired advisory circle emits owner and text family through Stored codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const P = table_style_profile;
    const title = "Vowel sign appearing in front of the initial consonant.";
    const css = "border:1px dotted var(--wikt-palette-grey-9,gray);border-radius:50%;cursor:help";
    const token = "<span title=\"" ++ title ++ "\" style=\"" ++ css ++ "\">æ</span>";
    const source = try a.dupe(u8, "<table><tr><td><small>" ++ token ++ "</small></td></tr></table>");
    const nodes = [_]P.ObservedStyleNode{
        .{ .tag = "html", .parent = null, .attributes = &.{} },
        .{ .tag = "body", .parent = 0, .attributes = &.{} },
        .{ .tag = "div", .parent = 1, .attributes = &.{.{ .name = "class", .value = "mw-parser-output" }} },
        .{ .tag = "table", .parent = 2, .attributes = &.{} },
        .{ .tag = "tr", .parent = 3, .attributes = &.{} },
        .{ .tag = "td", .parent = 4, .attributes = &.{} },
        .{ .tag = "small", .parent = 5, .attributes = &.{} },
        .{ .tag = "span", .parent = 6, .has_text = true, .empty = false,
            .attributes = &.{.{ .name = "title", .value = title }, .{ .name = "style", .value = css }} },
    };
    var parent = try P.parseForTargetAlloc(a, "", .screen);
    defer parent.deinit();
    var styles = try P.parseForTargetAlloc(a,
        "@media screen{html,body{font-family:sans-serif}}:root{--wikt-palette-grey-9:#777777}", .screen);
    defer styles.deinit();
    styles.page_style_parent = &parent;
    const observed = (try P.observedHelpCircleBox(a, &styles, &nodes, 2, 7,
        "--wikt-palette-grey-9", false)) orelse return error.TestUnexpectedResult;
    var geometry = observed.geometry;
    inline for (.{ "top", "right", "bottom", "left" }) |side|
        @field(geometry.border, side).dotted.color = .{ .rgb = observed.ink };
    const at = std.mem.indexOf(u8, source, "<span").?;
    const tag = syntax.tagAt(source, at).?;
    const pair = syntax.matchingTag(source, tag).?;
    var root_element: P.TextElement = .{ .tag = "div", .classes = "mw-parser-output" };
    const paints = [_]P.SourceHelpCirclePaint{.{ .source = source, .styles = &styles,
        .opening = source[at..tag.end], .owner_snapshot = try a.dupe(u8, source[at..pair.end]),
        .physical = .{ .parent = &parent, .box = geometry,
            .table_chains = .{ &.{observed.table_chain}, &.{observed.table_chain} } } }};
    var scope: P.BoundedTextClassScope = .{ .root_tag = "div", .root_classes = "mw-parser-output",
        .subtree_classes = "", .complete_ancestor_class_superset = "mw-parser-output",
        .page_styles = &styles, .page_style_root = &root_element, .help_circle_paints = &paints };
    const input = MissingText.untracked(source);
    // A paired page profile deliberately cannot issue a whole-page class proof.
    // This fixture uses its current source-bound help-circle paint instead.
    try std.testing.expect((try nativeSourceClassProofAlloc(a, input, &styles)) == null);
    var renderer: Renderer = .{ .a = a, .content_root = .parser_output, .body_depth = 1,
        .body_missing = input, .inline_missing = input,
        .bounded_text_class_source = source, .bounded_text_class_scope = &scope,
        .context = .{ .table_styles = &styles, .text_paint_styles = &styles,
            .figure_sizing = .{ .resolve_fn = OrdinaryPlainPaintTransportTest.sizing,
                .text_class_scope = .{ .source = source, .scope = &scope } } } };
    var root: NativeInlineMotionRoot = .{ .source = input };
    const motion = renderer.nativeInlineMotionBegin(&root, false);
    defer motion.deinit();
    var inherited: Style = .{ .native_inline_motion = renderer.body_formatting_attributes.native_inline_motion };
    var offset: usize = 0;
    while (offset < at) {
        const ancestor = syntax.tagAt(source, offset).?;
        const element = try renderer.textElement(ancestor, inherited.text_element, "");
        inherited.native_inline_motion = try renderer.nativeInlineMotionEntry(ancestor, inherited.native_inline_motion);
        inherited.text_element = element;
        offset = ancestor.end;
    }
    var effective = inherited;
    effective.native_inline_motion = try renderer.nativeInlineMotionEntry(tag, inherited.native_inline_motion);
    effective.tooltip = title;
    effective.font_scale = 0.8333;
    try std.testing.expect(effective.font_family == null);
    try std.testing.expect(try renderer.typedInlineBox(input, at, tag, pair, effective, inherited, 0));
    try std.testing.expectEqual(@as(usize, 1), renderer.spans.items.len);
    const blocks = [_]Block{.{ .kind = .paragraph, .spans = renderer.spans.items }};
    const stored = try FormattingScopeTest.encode(a, &renderer, &blocks);
    const codec = @import("blob_encoder").presentation_codec;
    const encoded = try codec.encodeAlloc(a, stored);
    const decoded = try codec.decodeAlloc(a, encoded, "formatting scope", .language,
        .{ .heading = "English", .code = "en" });
    const owner = decoded.entry.sections[0].blocks[0].spans[0];
    const child = owner.inline_box_group.?.spans[0];
    try std.testing.expect(owner.font_family.? == .sans_serif);
    try std.testing.expectEqualDeep(owner.font_family, child.font_family);
    try std.testing.expectEqualStrings("æ", child.text);
    for ([_]presentation_types.Span{owner, child}) |span| {
        try std.testing.expect(span.kind == .text and span.target.len == 0);
        try std.testing.expectEqualStrings(title, span.tooltip.?);
        try std.testing.expect(span.inline_style.?.cursor == .help);
    }
    try std.testing.expectEqualSlices(u8, encoded, try codec.encodeAlloc(a, decoded));
}
